  // ret : (cost, (node1, node2))
  def makeCosts(pl: List[(Int, Int)]): List[(Int, (Int, Int))] = {
    def calc(pl: List[(Int, Int)], res: List[(Int, (Int, Int))]): List[(Int, (Int, Int))] = {
      pl match {
        case Nil | _ :: Nil => res
        case a :: b :: rest =>
          val cost = Math.abs(a._1 - b._1)
          calc(b :: rest, (cost, (a._2, b._2)) :: res)
      }
    }
    calc(pl, List())
  }

  val xc = makeCosts(xp.toList)
  val yc = makeCosts(yp.toList)

  val pq = new PriorityQueue[(Int, (Int, Int))]

