struct Edge {
	int fromX, fromY, toX, toY, cost;
	Edge(int fx, int fy, int tx, int ty, int c) {
		fromX = fx; fromY = fy; toX = tx; toY = ty; cost = c;
	}
};
using Pair = pair<int, int>;
using Graph = map<Pair, vector<Edge>>;

//コストの小さい辺から探索する。探索済みの頂点は探索しない。
//※dijkstraの場合は、累積コストの小さい辺を探索する。全域木にする必要がない。
ll prim(Graph& g, Pair start) {
	map<Pair, bool> used;
	using CostPair = pair<ll, Pair>;
	priority_queue<CostPair, vector<CostPair>, greater<CostPair>> pq;
	pq.push(CostPair(0, start));

	ll sumcost = 0;
	while (!pq.empty()) {
		CostPair cp = pq.top(); pq.pop();
		ll c = cp.first; Pair v = cp.second;
		if (used[v]) continue;
		used[v] = true;
		sumcost += c;
		for (Edge e : g[v]) {
			pq.push(CostPair(e.cost, Pair(e.toX, e.toY)));
		}
	}
	return sumcost;
}
