int kruskal(int N, vector<edge> edges) {
    int totalCost = 0;
    sort(edges.begin(), edges.end());

    UnionFind uf = UnionFind(N + 1);
    rep (i, N) uf.init(i);

    int source, target;
    rep (i, edges.size()) {
        edge e = edges[i];
        if (!uf.isSame(e.source, e.target)) {
            totalCost += e.cost;
            uf.unite(e.source, e.target);
        }
    }

    return totalCost;
}

