using namespace std;

class UnionFind {
   public:
    UnionFind(int n)  // 0~n-1までitemを初期化
    {
        parent = vector<int>(n, -1);  //親なら-size
    }
    int root(int a) {
        if (parent[a] < 0) return a;
        return parent[a] = root(parent[a]);
    }
    int size(int a) { return -parent[root(a)]; }
    bool connect(int a, int b) {
        int A = root(a);
        int B = root(b);
        if (A == B) return false;
        if (size(A) > size(B)) swap(A, B);
        parent[B] += parent[A];
        parent[A] = B;
        return true;
    }

   private:
    vector<int> parent;
};
