void unite(int x,int y){
  x = find(x);
  y = find(y);
  if(x == y) return;

  if(rankd[x] < rankd[y]){
    par[x] = y;
  }
  else{
    par[y] = x;
    if(rankd[x] == rankd[y]) rankd[x]++;
  }
}

