struct UnionFind {
  vector< int > par;
  UnionFind(int n = 1) {
    init(n);
  }

  void init(int n) {
    par.resize(n);
    for(int i = 0; i < n; i++)
      par[i] = -1;
  }

  int root(int n) {
    if (par[n] < 0) return n;
    return par[n] = root(par[n]);
  }

  bool unite(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return false;
    if (par[x] > par[y]) swap(x, y);
    par[x] += par[y];
    par[y] = x;

    return true;
  }
};

int N;

Edge e[MAX_N];

int kruskal()
{
  sort(e, e + N * N, [](const Edge& x, const Edge& y) {
      return x.cost < y.cost;
  });
  UnionFind uf(N);
  ll res = 0ll;
  REP(i, N * N) {
    Edge ei = e[i];
    if (!(uf.root(ei.from) == uf.root(ei.to))) {
      uf.unite(ei.from, ei.to);
      res += ei.cost;
    }
  }
  return res;
}

