void init_union_find(int n) {
	t_rank.resize(n, 0);
	par.resize(n);
	for (int i = 0; i < n; i++)
		par[i] = i;
}

int find(int x) {
	if (par[x] == x)
		return x;
	else
		return par[x] = find(par[x]);
}

void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y)
		return;
	if (t_rank[x] < t_rank[y])
		par[x] = y;
	else {
		par[y] = x;
		if (t_rank[x] == t_rank[y])
			t_rank[x]++;
	}
}

bool same(int x, int y) {
	return find(x) == find(y);
}

bool comp(const edge& e1, const edge& e2) {
	return e1.cost < e2.cost;
}

ll kruskal(void) {
	ll res;
	sort(es.begin(), es.end(), comp);
	init_union_find(N);
	res = 0;
	for (int i = 0; i < (int)es.size(); ++i) {
		edge e = es[i];
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}

