};
typedef pair<ll,ll> P;
typedef pair<ll,P> T;
const int MAX_V=200000;
const int MAX_N=100000;
vector<edge> G[MAX_N];
vector<edge> F[MAX_V];//利用した辺を収納
class uft {//union-find tree
public:
    int parent[MAX_N];
    int size[MAX_N];
    void initialize(int N);//N頂点利用するということ。
    int root(int x);
    int sz(int x);//頂点xが属するグループに含まれている要素数を返す
    bool same(int x,int y);
    void unite(int x,int y);
};
void uft::initialize(int N){
    for(int i=0;i<N;i++){
        parent[i]=i;
    }
}
int uft::root(int x){
    if(parent[x]==x){
        return x;
    }
    return parent[x] = root(parent[x]);
}
int uft::sz(int x){
    return size[root(x)];
}
bool uft::same(int x,int y){
    if(root(x)==root(y)){
        return true;
    }else{
        return false;
    }
}
void uft::unite(int x,int y){
    x=root(x);
    y=root(y);
    if(x == y) return;
    parent[x] = y;
    size[y] = size[y]+size[x];
}
ll Kruskal(int N){//頂点数NのグラフGの最小全域木を求める。そして、利用した辺の重みの和を返す。
    uft u;
    u.initialize(N);
    ll ret=0;
    priority_queue<T, vector<T>, greater<T> > q;
    for(int i=0;i<N;i++){
        for(int j=0;j<G[i].size();j++){
            edge e=G[i][j];
            q.push(T(e.cost,P(i,e.to)));
        }
    }
    while(u.sz(0) != N && !q.empty()){
        T t=q.top(); q.pop();
        int x=(t.second).first;
        int y=(t.second).second;
        ll co=t.first;
        if(!u.same(x,y)){
            u.unite(x,y);
            ret+=co;
            edge e;
            e.cost=co;
            e.to=y; F[x].push_back(e);
            e.to=x; F[y].push_back(e);
        }
    }
    return ret;
}

int main(){
    int N;
    P xy[100000],yx[100000];
    cin>>N;
    for(int i=0;i<N;i++){
        ll x,y;
        cin>>x>>y;
        xy[i]=P(x,i);
        yx[i]=P(y,i);
    }
    sort(xy,xy+N);
    sort(yx,yx+N);
    for(int i=0;i<N-1;i++){
        ll x=xy[i+1].first-xy[i].first;
        ll xi=xy[i].second;
        ll xii=xy[i+1].second;
        edge e;
        e.to=xii;
        e.cost=x;
        G[xi].push_back(e);
        e.to=xi;
        G[xii].push_back(e);

        ll y=yx[i+1].first-yx[i].first;
        ll yi=yx[i].second;
        ll yii=yx[i+1].second;
        e.to=yii;
        e.cost=y;
        G[yi].push_back(e);
        e.to=yii;
        G[yii].push_back(e);
    }
    ll ans = Kruskal(N);
    cout<<ans<<endl;
    return 0;
}

