            for ( int j = 0; j < n; j++ ) {
                d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
            }
        }
    }

    long long ans = 0;
    int minc = INF;
    for ( int i = 0; i < n; i++ ) {
        for ( int j = 0; j < n; j++ ) {
            int tmp = d[i][j];
            minc = min(tmp, minc);
        }
        ans += minc;
    }

    cout << ans << endl;

    return 0;
}

