bool cmp2(Node a,Node b)
{
    return (a.y<b.y);
}
bool cmp3(edge a,edge b)
{
    return (a.w<b.w);
}
int par[MAXN];
void Init()
{
    memset(par,-1,sizeof(par));
    sort(a+1,a+1+n,cmp1);
    for(int i=1; i<n; i++)
        edges.push_back({a[i].pos,a[i+1].pos,abs(a[i].x-a[i+1].x)});
