    sort(edges.begin(),edges.end(),cmp3);
}
int root(int u)
{
    return par[u]<0 ? u : (par[u]=root(par[u]));
}
bool Merge(int u,int v)
{
    if((u=root(u))==(v=root(v)))
        return false ;
    if(par[u]>par[v])
        swap(u,v);
    //cerr<<par[u]<<" "<<par[v]<<'\n';
    par[u]+=par[v];
    par[v]=u;
    return true ;
}
