struct UnionFind{
    vector<int> parent,size;

    UnionFind(int n): parent(n,-1),size(n,1){}
    void init(int n){ 
        parent.assign(n,-1);
        size.assign(n,1);
        return;
    }

    int root(int x){
        if (parent[x]<0) return x;
        else return parent[x] = root(parent[x]);
    }

    bool same(int x, int y){
        return root(x)==root(y);
    }

    void unite(int x,int y){
        int gx = root(x);
        int gy = root(y);
        if (gx==gy) return;
        else{
            if(size[gx]<size[gy]){
                size[gy]+=size[gx];
                parent[gx]=gy;
            } else{
                size[gx]+=size[gy];
                parent[gy]=gx;
            }
        }
    }
    int get_size(int x){
        return size[root(x)];
    }    
};

