	std::vector<int> par;//xの親はpar[x]. もしx自身が親ならpar[x]<0で,-par[x]がその集合のサイズ.
	int cnt;			 //Number of group.

	UnionFind(int n):par(n,-1),cnt(n){}//Constructor.

	void reset(int n){par.assign(n,-1),cnt=n;}
	int root(int x){return (par[x]<0)?x:par[x]=root(par[x]);}//Recrusion.
