struct Prim{
    ll INF = 5000000000000000;
    Point point[100005];
    int getCost(Point p1,Point p2){
        return min(abs(p1.x - p2.x) , abs(p1.y - p2.y));
    }
    ll mincost[100005];
    bool used[100005];
    int V;
    Prim(int _V){
        V = _V;
    }

    ll min(ll a,ll b){
        if( a > b) return b;
        else return a;
    }

    int prim(){
        for(int i = 0; i < V; ++i){
            mincost[i] = INF;
            used[i] = false;
        }

        mincost[0] = 0;
        int res = 0;

        while(true){
            int v = -1;
            for(int u = 0; u < V; u++){
                if(!used[u] && (v == -1 || mincost[u] < mincost[v])) v = u;
            }

            if(v == -1) break;
            used[v] = true;
            res += mincost[v];

            for(int u = 0; u < V; u++){
                mincost[u] = min(mincost[u], getCost(point[u],point[v]));
            }
        }

        return res;
    }
};

