    Kruskal<ll> kr(n);
    vi orderx(n);
    vi ordery(n);
    iota(orderx.begin(), orderx.end(), 0);
    iota(ordery.begin(), ordery.end(), 0);
    auto compx = [&](int l, int r) { return x[l] < x[r]; };
    auto compy = [&](int l, int r) { return y[l] < y[r]; };
    sort(orderx.begin(), orderx.end(), compx);
    sort(ordery.begin(), ordery.end(), compy);
    for (int i = 1; i < n; ++i) {
        ll mincostx = min(abs(x[orderx[i]] - x[orderx[i - 1]]),
                          abs(y[orderx[i]] - y[orderx[i - 1]]));
        ll mincosty = min(abs(x[ordery[i]] - x[ordery[i - 1]]),
                          abs(y[ordery[i]] - y[ordery[i - 1]]));
        kr.addEdge(orderx[i], orderx[i - 1], mincostx);
        kr.addEdge(ordery[i], ordery[i - 1], mincosty);
    }
    ll ret = kr.build();
    cout << ret << "\n";
    return 0;
}

