// 経路圧縮のみ実装？ 深さ１の部分木を生成
class DisjointSet {
private:
    vector<int> p;              // 頂点 i の所属している木の root を記録する or 部分木の root には自分を含む頂点数が負の数で記録してある
    int count;                  // 分離している部分木の本数を記録(１となったとき孤立した部分木・頂点がなくなったことを示す)

    // 所属している部分木の root を調べる
    int root(int x) {         
        return p[x] < 0 ? x : p[x] = root(p[x]);
    }

public:
    // コンストラクタ　頂点数の提示が必要
    DisjointSet(int size) {
        p.resize(size, -1); 
        count = size;
    }
    // メインとなるメソッド 部分木同士の結合
    bool unite_set(int x, int y) {          
        int rootX = root(x);
        int rootY = root(y);

        if (rootX != rootY) {                       // 部分木におけるループの排除
            if (p[rootX] > p[rootY]) {              // 自分を含む頂点数が多い方を rootX とする  
                swap(rootX, rootY); 
            }
            p[rootX] += p[rootY];                   // 自分を含む頂点数を p[rootX] に渡す
            p[rootY] = rootX;                       // root を変更
            count--;                                // 部分木同士がつながったので、本数を一つ減らす
            return true;
        }
        else{
            return false;
        }
    }

    int number_of_sets() {                          // 分離している部分木の本数を出力
        return count;
    }
};

