//////　クラスカル法 
// 参考資料：https://mickey24.hatenablog.com/entry/20090605/1244132474

////// 一見 O(n^2) 本だと思われる辺を 2(n-1) 本まで減らせる 
// x座標、y座標それぞれにおいて、隣接している２頂点間のコストさえ考えればよい
// 参考資料：https://img.atcoder.jp/arc076/editorial.pdf  dProblem

int main() {
    int nVertex;
    cin >> nVertex;
    priority_queue< pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>> > vertexInfoX, vertexInfoY;
    for (int i = 0; i < nVertex; i++){
        int x, y;
        cin >> x >> y;
        vertexInfoX.push(make_pair(x, i));
        vertexInfoY.push(make_pair(y, i));
    }

    pair<int, int> x0 = vertexInfoX.top(); vertexInfoX.pop();
    pair<int, int> y0 = vertexInfoY.top(); vertexInfoY.pop();
    priority_queue< tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>> > edgeInfo;
    for (int i = 0; i < nVertex - 1; i++){
        pair<int, int> x1 = vertexInfoX.top(); vertexInfoX.pop();
        pair<int, int> y1 = vertexInfoY.top(); vertexInfoY.pop();
        int dx = x1.first - x0.first, dy = y1.first - y0.first;
        edgeInfo.push(make_tuple(dx, x0.second, x1.second));
        edgeInfo.push(make_tuple(dy, y0.second, y1.second));
        x0 = x1, y0 = y1;
    }

    DisjointSet vJoint(nVertex);

    int sumEdgeWeightMin = 0; 
    while (true){
        tuple<int, int, int> tmp = edgeInfo.top(); edgeInfo.pop();
        bool isJoint = vJoint.unite_set(get<1>(tmp), get<2>(tmp));
        if (isJoint){
            sumEdgeWeightMin += get<0>(tmp);
        }
        if (vJoint.number_of_sets() == 1){
            break;
        }
    }

    cout << sumEdgeWeightMin << endl;

    return 0;
}

