	vector<ar<ll,2> >  v,t;
	map<ar<ll,2> , int> m;
	for(int i = 0,j,k; i<n; i++)
	{
		cin>>j>>k,--j,--k;
		v.push_back({j,k});
		t.push_back({k,j});
		m[v[i]] = i;
	}
	sort(v.begin(),v.end());
	sort(t.begin(),t.end());
	vector<ar<ll,2> > edges[n];
	for(int i = 1; i<n; i++)
	{
		auto y = v[i];
		auto y2 = v[i-1];
		edges[m[y]].push_back({m[y2],abs(y2[0]-y[0])});
		edges[m[y2]].push_back({m[y],abs(y2[0]-y[0])});
		y = t[i];
		y2 = t[i-1];
		swap(y[0],y[1]);
		swap(y2[0],y2[1]);
		edges[m[y]].push_back({m[y2],abs(y2[1]-y[1])});
		edges[m[y2]].push_back({m[y],abs(y2[1]-y[1])});
	}
	set<ar<ll,2> > st;
	st.insert({0,0});
	bool vis[n]={0};
	vis[0] = 1;
	ll dist[n];
	memset(dist,0x3f, sizeof(dist));
	dist[0] = 0;
	while(!st.empty())
	{
		auto y = *st.begin();
		st.erase(st.begin());
		vis[y[1]] = 1;
		for(auto it:edges[y[1]])
		{
			if(!vis[it[0]] && dist[it[0]]>it[1])
			{
				st.erase({dist[it[0]],it[0]});
				dist[it[0]] = it[1];
				st.insert({dist[it[0]],it[0]});
			}
		}
	}
	cout<<accumulate(dist,dist+n,0LL)<<endl;
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll INF = (ll)1e17;
const ll MAX = 1e5+10;

ll N;
ll par[MAX];

ll root(ll x){
  if(par[x] == x) return x;
  return root(par[x]);
}

void unite(ll x, ll y){
  ll rx = root(x);
  ll ry = root(y);
  if(rx == ry) return;
  par[rx] = ry;
  par[x] = ry;
  par[y] = ry;
}

bool same(ll x, ll y){
  ll rx = root(x), ry = root(y);
  return rx == ry;
}


int main(){
  cin >> N;
  vector<pair<ll, ll> > x(N), y(N);
  vector<pair<ll, pair<ll, ll> > > s;
  ll ans = 0;

  for(ll i = 0; i < N; i++){
    ll xx, yy; cin >> xx >> yy;
    x[i] = make_pair(xx, i);
    y[i] = make_pair(yy, i);
  }

  sort(x.begin(), x.end());
  sort(y.begin(), y.end());
  for(ll i = 1; i < N; i++){
    ll dx = x[i].first - x[i-1].first;
    ll fx = x[i].second, sx = x[i-1].second;
    s.push_back(make_pair(dx, make_pair(fx, sx)));

    ll dy = y[i].first - y[i-1].first;
    ll fy = y[i].second, sy = y[i-1].second;
    s.push_back(make_pair(dy, make_pair(fy, sy)));
  }

  sort(s.begin(), s.end());

  for(ll i = 0; i < N; i++){
    par[i] = i;
  }

  ll M = s.size();
  for(ll i = 0; i < M; i++){
    ll des = s[i].first, fst = s[i].second.first, scd = s[i].second.second;
    if(!same(fst, scd)){
      ans += des;
      unite(fst, scd);
    }
  }

  cout << ans << endl;
}

