using namespace std;

class UF
{
private:
	int         num;
	vector<int> par;
	vector<int> siz;
public:
	//vector<int> val;
public:
	UF(int n) : num(n) {
		par.resize(n);
		siz.resize(n);
		//val.resize(n);
		int i;
		for (i = 0; i < n; i++) {
			par[i] = i; siz[i] = 1;
			//val[i]=0;
		}
	}

	int find(int x) {
		if (x == par[x]) return x;
		return par[x] = find(par[x]);
	}

	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (siz[x] < siz[y]) {
			par[x] = y;
			siz[y] = siz[x] + siz[y];
			//val[y]=val[x]+val[y];
		}
		else {
			par[y] = x;
			siz[x] = siz[x] + siz[y];
			//val[x]=val[x]+val[y];
		}
	}

	bool same(int x, int y) {
		return find(x) == find(y);
	}

	int size(int x) {
		return siz[find(x)];
	}

	int ngroup() {
		//int ngroup( int& ans ) {
		int count = 0;
		int i;
		for (i = 0; i < num; i++) {
			if (par[i] == i) {
				count++;
				//ans += (val[i]? siz[i]: siz[i]-1);
			}
		}
		return count;
	}
};

void solve()
{
	int n;
	scanf("%d", &n);

	vector<pair<int, int> > x, y;
	int i;
	for (i = 0; i < n; i++) {
		int x0, y0;
		scanf("%d%d", &x0, &y0);
		x.push_back(make_pair(x0, i));
		y.push_back(make_pair(y0, i));
	}
	sort(x.begin(), x.end());
	sort(y.begin(), y.end());

	vector<pair<int, pair<int, int> > > z;
	for (i = 1; i < n; i++) {
		z.push_back(make_pair(x[i].first - x[i - 1].first, make_pair(x[i].second, x[i - 1].second)));
		z.push_back(make_pair(y[i].first - y[i - 1].first, make_pair(y[i].second, y[i - 1].second)));
	}
	sort(z.begin(), z.end());

	UF uf(n);
	ll ans = 0;
	for (i = 0; i < (int)z.size(); i++) {
		int d=z[i].first;
		int a = z[i].second.first;
		int b = z[i].second.second;
		if (!uf.same(a, b)) {
			ans += d;
			uf.unite(a, b);
		}
	}
	printf("%lld\n", ans);

	return;
}


