typedef pair<li, li> PI;

li n;
PI xy[100100];

PI xs[100100];
PI ys[100100];

li xi[100100];
li yi[100100];

bool visited[100100];

inline vector<PI> GetNext(li id) {
    vector<PI> res;
    li xid = xi[id];
    li yid = yi[id];
    if (xid > 0) {
        res.push_back({xs[xid].F - xs[xid - 1].F, xs[xid - 1].S});
    }
    if (xid < n - 1) {
        res.push_back({xs[xid + 1].F - xs[xid].F, xs[xid + 1].S});
    }
    if (yid > 0) {
        res.push_back({ys[yid].F - ys[yid - 1].F, ys[yid - 1].S});
    }
    if (yid < n - 1) {
        res.push_back({ys[yid + 1].F - ys[yid].F, ys[yid + 1].S});
    }
    return res;
}

inline li solve() {
    li res = 0;
    priority_queue<PI> pq;
    pq.push({0, 0});
    while (!pq.empty()) {
        li now = pq.top().S;
        li now_cost = -pq.top().F;
        pq.pop();
        if (visited[now]) {
            continue;
        }
        res += now_cost;
        visited[now] = true;

        for (const auto& p : GetNext(now)) {
            pq.push({ -p.F, p.S});
        }
    }
    return res;
}

