};

struct D {
    int idx;
    int next;
    int64_t d;

    bool operator>(const D& rhs) const {
        return d > rhs.d;
    }
};


using pq = priority_queue<D, vector<D>, greater<D>>;

void calc_d(const vector<int>& ss, const vector<int>& pos, const vector<int64_t>& c, int idx, pq* que) {
    auto pp = pos[idx];

    if (pp > 0) {
        que->push(D{idx, ss[pp - 1], abs(c[ss[pp - 1]] - c[idx])});
    }
    if (pp + 1 < ss.size()) {
        que->push(D{idx, ss[pp + 1], abs(c[ss[pp + 1]] - c[idx])});
    }
}

int64_t solve(const vector<int64_t>& x, const vector<int64_t>& y) {
    vector<int> xs(x.size());
    vector<int> ys(y.size());

    iota(xs.begin(), xs.end(), 0);
    sort(xs.begin(), xs.end(), [&x](int lhs, int rhs) {
        return x[lhs] < x[rhs];
    });

    iota(ys.begin(), ys.end(), 0);
    sort(ys.begin(), ys.end(), [&y](int lhs, int rhs) {
        return y[lhs] < y[rhs];
    });

    vector<int> xpos(x.size()), ypos(y.size());
    for (int i = 0; i < x.size(); ++i) {
        xpos[xs[i]] = i;
        ypos[ys[i]] = i;
    }

    priority_queue<D, vector<D>, greater<D>> q;

    calc_d(xs, xpos, x, 0, &q);
    calc_d(ys, ypos, y, 0, &q);

    unordered_set<int> selected;
    selected.insert(0);

    int64_t ans = 0;

    while(true) {
        D md;

        while (!q.empty()) {
            md = q.top();
            if (selected.count(md.next) > 0) {
                q.pop();
                continue;
            }
            break;
        }

        if (q.empty()) {
            break;
        }

        int next;
        q.pop();
        ans += md.d;
        next = md.next;
        selected.insert(next);
        calc_d(xs, xpos, x, next, &q);
        calc_d(ys, ypos, y, next, &q);
    }

    return ans;
}

int main() {
    int n;
    cin >> n;

    vector<int64_t> x(n), y(n);
    for (int i = 0; i < n; ++i) {
        cin >> x[i] >> y[i];
    }

    cout << solve(x, y) << endl;

    return 0;
}

