// 素集合データ構造
//--------------------------------------------
struct UnionFind {

    // par[i]→データiの親の番号 i==par[i]ならiは木の親
    vector<int> par;
    // sizes[i]→iを根とする木に含まれる子の数
    vector<int> sizes;

    UnionFind(int n)
            : par(n), sizes(n, 1) {
        // すべてのノードがiに属すると初期化
        REP(i, n) {
            par[i] = i;
        }
    }

    // データxが属する木の根を得る
    int find(int x) {
        if (x == par[x]) {
            return x;
        }
        return par[x] = find(par[x]);
    }

    // 2つのデータx, yが属する木をマージする
    void unite(int x, int y) {
        // データの根ノードを得る
        x = find(x);
        y = find(y);

        // 同じ木ならマージしない
        if (x == y) {
            return;
        }

        // xの木 > yの木
        if (sizes[x] < sizes[y]) {
            swap(x, y);
        }
        // xはyの親とする
        par[y] = x;
        sizes[x] += sizes[y];
    }

    // x,yが同じ木ならtrue
    bool same(int x, int y) {
        return find(x) == find(y);
    }

    // xが含まれる木のサイズ
    int size(int x) {
        return sizes[find(x)];
    }
};

