    LL ans = 0;
    UnionFind UF(N);
    for (int i = 0; i < edges.size(); i++) {
        edge &e = edges[i];
        if (!UF.same(e.from, e.to)) {
            ans += e.cost;
            UF.unite(e.from, e.to);
        }
    }


    OUT_L(ans);

    return 0;
}

