//spaghetti-source(github)から
struct edge {
    int src, dst;
    int weight;
};

struct graph {
    int n;
    vector<edge> edges;

    explicit graph(int n = 0) : n(n) {
    }

    void add_edge(int src, int dst, int weight) {
        n = max(n, max(src, dst) + 1);
        edges.push_back({src, dst, weight});
    }

    vector<int> p;

    int root(int i) {
        return p[i] < 0 ? i : p[i] = root(p[i]);
    }

    bool unite(int i, int j) {
        if ((i = root(i)) == (j = root(j))) return false;
        if (p[i] > p[j]) swap(i, j);
        p[i] += p[j];
        p[j] = i;
        return true;
    }

    int kruskal() {
        p.assign(n, -1);
        sort(edges.begin(), edges.end(), [](edge x, edge y) {
            return x.weight < y.weight;
        });

        int result = 0;
        for (auto e: edges)
            if (unite(e.src, e.dst))
                result += e.weight;
        return result;
    }
};


int main() {
    int n;
