        vt.push_back({x, y, i});
    }

    auto g = graph(n);

    sort(vt.begin(), vt.end(), sortX);
    for (int i = 0; i < n - 1; ++i) {
        g.add_edge(vt[i].id, vt[i + 1].id, vt[i + 1].x - vt[i].x);
    }

    sort(vt.begin(), vt.end(), sortY);
    for (int i = 0; i < n - 1; ++i) {
        g.add_edge(vt[i].id, vt[i + 1].id, vt[i + 1].y - vt[i].y);
    }

    cout << g.kruskal() << endl;
    return 0;
}

