  for (int i = 0; i < n; ++i) {
    int x, y;
    cin >> x >> y;
    vx.push_back({x, i});
    vy.push_back({y, i});
  }

  sort(vx.begin(), vx.end());
  sort(vy.begin(), vy.end());

  vector<array<int, 3>> edges;
  for (int i = 1; i < vx.size(); ++i) {
    auto p1 = vx[i], p2 = vx[i - 1];
    edges.push_back({abs(p1.first - p2.first), p1.second, p2.second});
  }

  for (int i = 1; i < vy.size(); ++i) {
    auto p1 = vy[i], p2 = vy[i - 1];
    edges.push_back({abs(p1.first - p2.first), p1.second, p2.second});
  }

  sort(edges.begin(), edges.end());

  // 入力された辺を優先度付きキューへ入れる
  priority_queue<Edge, vector<Edge>, greater<array<int, 3>>> edge_q;
  for (auto &e : edges) {
    edge_q.push(e);
  }

  // キューから取り出し，閉路が出来なければ追加
  int ans = 0;
  UnionFind uf(n);
  while (!edge_q.empty()) {
    auto &edge = edge_q.top();
    if (!uf.Same(edge[1], edge[2])) {
      uf.Unite(edge[1], edge[2]);
      ans += edge[0];
    }

    edge_q.pop();
  }

  cout << ans << '\n';
}

