void ufinit(int n){
	int i;
	for(i=0; i<n; ++i){
		ufp[i] = i;
		ufr[i] = 0;
	}
}

int ufind(int x){
	int ans;
	if(ufp[x] == x){
		return x;
	}else{
		ans = ufind(ufp[x]);
		ufp[x] = ans;
		return ans;
	}
}

void unionf(int x, int y){
	x = ufind(x);
	y = ufind(y);
	if(ufr[x] > ufr[y]){
		ufp[y] = x;
	}else{
		ufp[x] = y;
	}
	if(ufr[x] == ufr[y]){
		ufr[y]++;
	}
}

