		node[i+n-1].len=y[i+1].sit-y[i].sit;
		node[i+n-1].a=y[i+1].order;node[i+n-1].b=y[i].order;
	}

	sort(node+1,node+2*n-1,cmp2);

	//克鲁斯卡尔算法 
	init(n); 
	ll ans=Kruskal(n,2*n-2);//顶点数量、边数 
	cout<<ans<<endl;

 	return 0;
