  int p[2];
  int c;
}Cost;
vector<Cost> cost;
long total;
int visited[MN];

bool comp(const Cost &l, const Cost &r){
  return l.c==r.c ? l.p[0] < r.p[0] : l.c < r.c;
}

void print(){
  for( int i = 0; i < N; i++ ){
	cout << visited[i] << ",";
  }
  cout << endl;
