  std::cin >> N;
  for( long i = 0; i < N; i++ ){
	std::cin >> x[i] >> y[i];
	visited[i] = 0;
  }
  long N2 = N*(N-1)/2;
  cost.resize(N2);
  int k = 0;
  int dx, dy;
  Cost c;
  total = 0;
  for( int i = 0; i < N; i++ ){
	for( int j = i+1; j < N; j++ ){
	  Cost c;
	  int dx = abs(x[i]-x[j]);
	  int dy = abs(y[i]-y[j]);
	  c.p[0] = i;
	  c.p[1] = j;
	  c.c = (dx<dy ? dx : dy);
	  cost[k++] = c;
	}
  }
  sort(cost.begin(), cost.end(), comp);
  /*
  for( long i = 0; i < N2; i++ ){
	std::cout << cost[i].p[0] << "," << cost[i].p[1] << "," << cost[i].c << std::endl;
  }
  */
  k = 1;
  for( long i = 0; i < N2; i++ ){
	//print();
	int p0 = cost[i].p[0];
	int p1 = cost[i].p[1];
	int vn = visited[p0]>visited[p1] ? visited[p0] : visited[p1];
	int vn2 = visited[p0]<=visited[p1] ? visited[p0] : visited[p1];
	if( visited[p0] + visited[p1] == 0 ){
	  //std::cout << p0 << "-" << p1 << std::endl;
	  k++;
	  total += cost[i].c;
	  visited[p0] = k;
	  visited[p1] = k;
	}else if( visited[p0] * visited[p1] == 0){
	  //std::cout << p0 << "-" << p1 << std::endl;
	  k++;
	  total += cost[i].c;
	  visited[p0] = vn;
	  visited[p1] = vn;
	}else if( visited[p0] != visited[p1] ){
	  //std::cout << p0 << "-" << p1 << std::endl;
	  k++;
	  total += cost[i].c;
	  for( int i = 0; i < N; i++ ){
		if( visited[i] == vn2 ){ visited[i] = vn; }
	  }
	}
	if( k > N-1 ){ break; }
  }
  std::cout << total << std::endl;
  return 0;
}

