struct Point{
    ll x;
    ll y;
    ll id;
    Point(ll x, ll y, ll id): x(x), y(y), id(id) {}

    static bool sortByY(Point a, Point b){
        if(a.y == b.y){
            return a.x < a.y;
        }else{
            return a.y < b.y;
        }
    }

    static bool sortByX(Point a, Point b){
        if(a.x == b.x){
            return a.y < a.y;
        }else{
            return a.x < b.x;
        }
    }
};

struct Edge{
    int from;
    int to;
    int cost;

    static bool sortByCost(Edge a, Edge b){
        return a.cost < b.cost;
    }
};

const int N_MAX = 100010;
int parent[N_MAX] = {};

int findRoot(int x){
    if(parent[x] == x){
        return x;
    }else{
        auto root = findRoot(parent[x]);
        parent[x] = root; // path compression
        return root;
    }
}

void _union(int a, int b){
    auto rootA = findRoot(a);
    auto rootB = findRoot(b);

    if(rootA == rootB){
        return;
    }else{
        parent[a] = b;
    }
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    int N;
    cin >> N;

    vector<Point> P;
    P.reserve(N);

    FOR(i, 0, N){
        ll x, y;
        cin >> x >> y;
        Point p = Point(x, y, i);
        P.push_back(p);
    }

    // p("[point]");
    // for(auto p : P){
    //     cout << p.id << " " << p.x << " " << p.y << endl;
    // }

    vector<Edge> edgeList;

    FOR(i, 0, 2){
        if(i==0){
            sort(ALL(P), Point::sortByX);
        }else{
            sort(ALL(P), Point::sortByY);
        }

        FOR(i, 0, N-1){
            Edge edge;
            edge.from = P[i].id;
            edge.to = P[i+1].id;
            edge.cost = min(abs(P[i].x - P[i+1].x), abs(P[i].y - P[i+1].y));
            edgeList.push_back(edge);
        }
    }

    // make MST by kruskal
    FOR(i, 0, N_MAX){
        parent[i] = i;
    }

    ll cost_sum = 0;
    sort(ALL(edgeList), Edge::sortByCost);

    // p("[edge]");
    // for(auto edge : edgeList){
    //     cout << edge.from << " " << edge.to << " " << edge.cost << endl;
    // }

    // 短いエッジから使うか検討
    for(auto edge : edgeList){
        if(findRoot(edge.from) == findRoot(edge.to)){
            // skip
        }
        else{
            // つなぐ
            _union(edge.from, edge.to);
            cost_sum += edge.cost;
        }
    }

    p(cost_sum);

    return 0;
}

