    UnionFind(int n) : parent(n), usize(n, 1LL){
        rep(i, n)parent[i]=i;
    }

    int root(int x){
        if(parent[x] == x) return x;
        else return parent[x] = root(parent[x]);
    }

    bool issame(int x, int y){
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x);
        y = root(y);

        if(x == y)return false;

        if(parent[x] > parent[y]) swap(x, y);

        usize[x] += usize[y];
        parent[y] = x;

        return true;
    }

    int size(int x) {
        return usize[root(x)];
    }
};

struct leaf{
    ll s, t;
    ll cost;
};

int main(){
    ll n;
    cin >> n;

    vector<ll> x(n), y(n);
    rep(i, n)cin >> x[i] >> y[i];

    vector<ll> ord_x(n), ord_y(n);
    iota(ALL(ord_x), 0);
    iota(ALL(ord_y), 0);
    sort(ALL(ord_x), [&](ll a, ll b){
        return x[a] < x[b];
    });
    sort(ALL(ord_y), [&](ll a, ll b){
        return y[a] < y[b];
    });

    vector<leaf> g;
    rep(i, n-1){
        g.push_back(leaf{ord_x[i], ord_x[i+1], abs(x[ord_x[i]] - x[ord_x[i+1]])});
        g.push_back(leaf{ord_y[i], ord_y[i+1], abs(y[ord_y[i]] - y[ord_y[i+1]])});
    }

    vector<ll> ord(g.size());
    iota(ALL(ord), 0);

    sort(ALL(ord), [&](ll a, ll b){
        return g[a].cost < g[b].cost;
    });

    UnionFind uf(n);

    ll ans = 0;
    rep(i, g.size()){
        if(!uf.issame(g[ord[i]].s, g[ord[i]].t)){
            ans += g[ord[i]].cost;
            uf.merge(g[ord[i]].s, g[ord[i]].t);
        }
    }

    cout << ans << endl;

}

