ll prim(const Graph &G, ll N, ll s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d+N, INFTY);
    fill(seen, seen+N, 0);
    d[s] = 0;
    seen[s] = 0;
    que.push(P(0, s));
    Graph tree(N);
    ll total = 0;

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        ll v = p.second;
        if( seen[v] == 1 ) continue;
        total += p.first;
        seen[v] = 1;
        for (ll i=0; i<G[v].size(); ++i) {
            edge e = G[v][i];
            que.push(P(e.cost, e.to));
        }
    }

    return total;
}



