		ll cost = y[i + 1].first - y[i].first;
		edges.push_back(edge(cost,pii(v1,v2)));
	}
	sort(edges.begin(), edges.end());
	UnionFind uf(2*(N-1));
	ll ans = 0;
	for (auto e : edges) {
		int u = e.second.first, v = e.second.second;
		ll cost = e.first;
		if (!uf.same(u,v)) {
			uf.unite(u,v);
			ans += cost;
		}
	}
	cout << ans << endl;
	return 0;
}

