int MST()
{
	int ret = 0;
	priority_queue<Edge> quu;
	for (int i = 0; i < adj[1].size(); i++)
		quu.push(adj[1][i]);
	visited[1] = true;

	while (!quu.empty())
	{
		auto cur = quu.top(); quu.pop();
		if (visited[cur.to]) continue;
		visited[cur.to] = true;
		ret += cur.weight;
		for (int i = 0; i < adj[cur.to].size(); i++)
			quu.push(adj[cur.to][i]);
	}

	return ret;
}

