void initSet(int n) {
    fto(i, 1, n) par[i] = i;
}

int findSet(int u) {
    return (par[u] == u) ? u : par[u] = findSet(par[u]);
}

void unionSet(int u, int v) {
    par[findSet(u)] = findSet(v);
}

int main() {
    sci(n);
    fto(i, 1, n) {
        scii(p[i].x, p[i].y);
        x[i].ff = p[i].x; x[i].ss = i;
        y[i].ff = p[i].y; y[i].ss = i;
    }

    sort(x+1, x+n+1);
    sort(y+1, y+n+1);

    fto(i, 1, n-1) {
        int u = x[i].ss, v = x[i+1].ss;
        int w = min(abs(p[u].x-p[v].x), abs(p[u].y-p[v].y));
        canh.pb(mp(w, mp(u, v)));

        u = y[i].ss, v = y[i+1].ss;
        w = min(abs(p[u].x-p[v].x), abs(p[u].y-p[v].y));
        canh.pb(mp(w, mp(u, v)));
    }

    sort(canh.begin(), canh.end());
    initSet(n);
    fto(i, 0, (int)canh.size()-1) {
        int w = canh[i].ff, u = canh[i].ss.ff, v = canh[i].ss.ss;
        if (findSet(u) != findSet(v)) {
            unionSet(u, v);
            ans += w;
        }
    }
    pril(ans);

    return 0;
}

