vector<ll>par(2e5+10);
void init(ll n) {
  for(ll i=0;i<n;i++) {
    par[i]=i;
  }
}

ll root(ll x) {
  if(par[x]==x) {
    return x;
  }
  else {
    return par[x]=root(par[x]);
  }
}

bool same(ll x, ll y) {
  return root(x)==root(y);
}

void unite(ll x, ll y) {
  if(same(x,y)) return;
  par[root(x)]=root(y);
}

int main() {
  ll n;
  cin >> n;
  vector<pll> x(n);
  vector<pll> y(n);
  for(ll i=0;i<n;i++) {
    ll tx, ty;
    cin >> tx >> ty;
    x[i]=pll(tx,i);
    y[i]=pll(ty,i);
  } 
  sort(x.begin(),x.end());
  sort(y.begin(),y.end());
  init(n);
  priority_queue<pair<ll,pll>, vector<pair<ll,pll>>, greater<pair<ll,pll>>> q;
  for(ll i=0;i<n-1;i++) {
    q.push(pair<ll,pll>(x[i+1].first-x[i].first,pll(x[i].second,x[i+1].second)));
    q.push(pair<ll,pll>(y[i+1].first-y[i].first,pll(y[i].second,y[i+1].second)));
  }
  ll ans=0;
  while(q.size()) {
    auto p=q.top();
    q.pop();
    ll d=p.first;
    ll p1=p.second.first;
    ll p2=p.second.second;
    if(!same(p1,p2)) {
      ans+=d;
      unite(p1,p2);
    }
  }
  cout << ans << endl;
}

