void prim(int v) {
    priority_queue<P, vector<P>, greater<P> > q;
    fill(dist, dist+100100, INF);
    dist[v] = 0;
    q.push(P(0, v));
    while (!q.empty()) {
        P p = q.top(); q.pop();
        int cost = p.first;
        int node = p.second;
        memo[node] = 1;
        if (cost > dist[node]) continue;
        for (auto e: g[node]) {
            if (dist[e.to] > e.cost && !memo[e.to]) {
                dist[e.to] = e.cost;
                q.push(P(e.cost, e.to));
            }
        }
    }
}

