ll Kruskal(ll ver,ll edge){//顶点数量、边数 
	ll tot=0,e=0;//目前的权值和已加入的边数

	//初始化前驱 
	for(int i=1;i<=ver;i++){
		rk[i]=i;//最开始第i个顶点的集合是他自己 
	}

	for(int i=1;i<=edge&&e<ver-1;i++){
		ll h=find(node[i].a);//a点根节点 
		ll k=find(node[i].b);//b点根节点 
		if(h!=k){//如果这两个点不在同一个集合中，说明可以加入这条边 
			tot+=node[i].len;//增加权值 
			e++;//增加边数 
			rk[h]=k; //合并这两个点到同一个集合 
		}
	}

	return tot; 
}

