  }
};

typedef pair<int, int> cost_and_index;
typedef priority_queue<cost_and_index, vector<cost_and_index>, greater<cost_and_index> > pq; 

int prim(int v, int n, vector<Point>& points){
  pq q;
  q.push(make_pair(0,v));
  int cost = 0;
  int rest = n;
  set<int> visited;

  while(rest>0){
    cost_and_index ci = q.top();q.pop();rest--;
    visited.insert(ci.second);
    //cout << ci.first << " / " << ci.second << endl;
    cost += ci.first;
    pq empty;
    swap(q,empty);
    for(auto base: visited){
      //cout << base << endl;
      for(int i=0;i<n;i++){
        if(visited.count(i)>0){continue;}
        int dist = points[base].dist(points[i]);
        //cout << dist << "/" << ci.second << ":" << i << endl;
        q.push(make_pair(dist,i));
      }
    }
  }

  return cost;
}

