struct Union_Find
{
    vector <int> parent;
    Union_Find(int N) : parent(N)
    {
        for(int i = 0; i < N; i++) parent[i] = i;
    }
    int root(int n)
{
    if (parent[n]==n) return n;
    else
    {
        return root(parent[n]);
    }
}

void unite(int i,int j)
{
    int rx,ry;
    rx=root(i);
    ry=root(j);
    if (rx==ry) return;
    else
    {
        int k;
        if (rx<ry)
        {
            parent[ry]=rx;
            return;
        }
        else
        {
            parent[rx]=ry;
            return;
        }
    }
}
bool same(int i, int j)
{
    if (root(i)==root(j)) return true;
    else return false;
}
