    vector<P_P> rootlist(2*N-2);
    for(int i=0; i<N-1; i++){
        rootlist[2*i]=make_pair(xpair[i+1].first-xpair[i].first, P(xpair[i+1].second, xpair[i].second));
        rootlist[2*i+1]=make_pair(ypair[i+1].first-ypair[i].first, P(ypair[i+1].second, ypair[i].second));
    }
    sort(rootlist.begin(), rootlist.end());

    ll ans=0;
    for(int i=0; i<2*N-2; i++){
        if(Uni.connect(rootlist[i].second.first, rootlist[i].second.second)){
            ans+=rootlist[i].first;
        }
    }





