	for (int i = 0; i < N; ++i) {
		p[i].id = i;
		cin >> p[i].x >> p[i].y;
	}

	vector<vector<edge>> g(N);

	sort(p.begin(), p.end(), [](auto &a, auto &b) {return a.x < b.x; });
	for (int i = 0; i + 1 < N; ++i) {
		edge e;
		e.src = p[i].id;
		e.dst = p[i + 1].id;
		e.cost = p[i + 1].x - p[i].x;
		g[e.src].push_back(e);
		swap(e.src, e.dst);
		g[e.src].push_back(e);
	}

	sort(p.begin(), p.end(), [](auto &a, auto &b) {return a.y < b.y; });
	for (int i = 0; i + 1 < N; ++i) {
