class UnionFind {
public:
	vector<int> rank;
	UnionFind(int N) : rank(N, -1) {}
	int root(int x) {
		if (rank[x] < 0)
			return x;
		else
			return rank[x] = root(rank[x]);
	}

	bool find(int a, int b) {
		return root(a) == root(b);
	}

	void uni(int a, int b) {
		a = root(a); b = root(b);
		if (a < b)
			rank[b] = a;
		else if (b < a)
			rank[a] = b;
		else {
			rank[b] = a;
			rank[a]--;
		}
	}
};

using Weight = ll;
class Edge {
public:
