	Weight w;
	Edge() : s(0), d(0), w(0) {}
	Edge(int s, int d, Weight w) : s(s), d(d), w(w) {}
	bool operator < (const Edge &e) const {
		return w != e.w ? w < e.w :
			   s != e.s ? s < e.s :
			   d < e.d;
	}
};
using Graph = vector<vector<Edge>>;

// 最小全域森とそのコストを返す O(ElogE)
pair<Weight, Graph> kruskal(Graph& g) {
	UnionFind uf(g.size());
	Weight cost = 0;
	Graph f(g.size());
	vector<Edge> es;
	for (auto&& ee : g)
		for (auto&& e : ee)
			es.push_back(e);
	sort(es.begin(), es.end());
	for (auto&& e : es) {
		if (uf.find(e.s, e.d))
			continue;
		uf.uni(e.s, e.d);
		cost += e.w;
		f[e.s].push_back(e);
	}
	return make_pair(cost, f);
}

