class Union_Find {
    public:
    std::vector<int> par;
    //std::vector<int> gn; //動的に連結成分の頂点数を出力する必要があるときに利用する。
    Union_Find() {}
    Union_Find(int n){
        par.resize(n, 0);
        //gn.resize(n, 0);
        reset();
    }

    void reset() {
        // サイズは変えずに初期状態に戻す。
        for (int i = 0; i < par.size(); i++) {
            par[i] = i;
            //gn[i] = 1;
        }
    }

    void simplify(int x) {
        std::vector<int> path;
        while (par[x] != x) {
            path.push_back(x);
            x = par[x];
        }
        for (int p : path) {
            par[p] = x;
        }
    }

    int find(const int x){
        simplify(x);
        return par[x];
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if (x != y) {
            par[y] = x;
            // 改造する時は「根になっているノードの親を変更する」という原則が守られていることに注意。
            //gn[x] += gn[y];
            //gn[y] = 0;
        }
    }

    //int group_num(const int x) {
    //    return gn[find(x)];
    //}

    std::unordered_map<int, std::vector<int>> get_group(const int begin, const int end) {
        assert(0 <= begin && end < par.size());
        std::unordered_map<int, std::vector<int>> ret;
        for (int i = begin; i <= end; i++) {
            ret[find(i)].push_back(i);
        }
        return ret;
    }
};

