using lint = long long;

bool second_less(pair<int, lint> a, pair<int, lint> b) {
    if (a.second != b.second) {
        return a.second < b.second;
    } else {
        return a.first < b.first;
    }
}

struct Edge {
    int from, to;
    lint cost;
};

struct UnionFind {
    vector<int> par;
    UnionFind(int N): par(N) {
        for (int i = 0; i < N; i++) {
            par[i] = i;
        }
    }

    int root(int a) {
        if (par[a] == a) {
            return a;
        } else {
            par[a] = root(par[a]);
            return par[a];
        }
    }
    void unite(int a, int b) {
        if (root(a) != root(b)) {
            par[root(b)] = root(a);
        }
    }
    bool same(int a, int b) {
        return root(a) == root(b);
    }
};

int main() {
    int N;
    cin >> N;
    vector<pair<int, lint>> x(N), y(N);
    for (int i = 0; i < N; i++) {
        x[i].first = y[i].first = i;
        cin >> x[i].second >> y[i].second;
    }

    sort(x.begin(), x.end(), second_less);
    sort(y.begin(), y.end(), second_less);

    vector<Edge> edge;
    for (int i = 1; i < N; i++) {
        edge.push_back({x[i - 1].first, x[i].first, abs(x[i].second - x[i - 1].second)});
        edge.push_back({y[i - 1].first, y[i].first, abs(y[i].second - y[i - 1].second)});
    }

    sort(edge.begin(), edge.end(), [](Edge a, Edge b) {return a.cost < b.cost;});

    lint ans = 0;
    UnionFind uf(N);
    for (int i = 0; i < edge.size(); i++) {
        if (uf.same(edge[i].from, edge[i].to) == false) {
            uf.unite(edge[i].from, edge[i].to);
            ans += edge[i].cost;
        }
    }

    cout << ans << endl;
    return 0;
}

