struct Point {
	int x, y;
};
class UnionFind {
	std::vector<int> parent;
public:
	UnionFind(int size) :parent(size, -1) {};
	int find(int a) {
		if (parent[a] < 0) return a;
		else return parent[a] = find(parent[a]);
	}
	bool is_same(int a, int b) { return find(a) == find(b); }
	void merge(int a, int b) {
		a = find(a);
		b = find(b);
		if (a != b) {
			if (parent[a] < parent[b]) {
				parent[a] += parent[b];
				parent[b] = a;
			}
			else {
				parent[b] += parent[a];
				parent[a] = b;
			}
		}
	}
};
enum class Axis {
	X, Y
};
int main() {
	int n; std::cin >> n;
	std::vector<Point> points(n); for (auto& p : points) std::cin >> p.x >> p.y;
	std::vector<int> sort_by_x(n), sort_by_y(n);
	for (auto i = 0; i < n; ++i) {
		sort_by_x[i] = i;
		sort_by_y[i] = i;
	}
	std::sort(sort_by_x.begin(), sort_by_x.end(), [&points](const int a, const int b) {return points[a].x < points[b].x; });
	std::sort(sort_by_y.begin(), sort_by_y.end(), [&points](const int a, const int b) {return points[a].y < points[b].y; });
	auto comparator = [&points, &sort_by_x, &sort_by_y](const std::pair<Axis, int>& a, const std::pair<Axis, int>& b) {
		int diff_a{ 0 };
		switch (a.first) {
		case Axis::X: diff_a = points[sort_by_x[a.second]].x - points[sort_by_x[a.second - 1]].x; break;
		case Axis::Y: diff_a = points[sort_by_y[a.second]].y - points[sort_by_y[a.second - 1]].y; break;
		default: break;
		}
		int diff_b{ 0 };
		switch (b.first) {
		case Axis::X: diff_b = points[sort_by_x[b.second]].x - points[sort_by_x[b.second - 1]].x; break;
		case Axis::Y: diff_b = points[sort_by_y[b.second]].y - points[sort_by_y[b.second - 1]].y; break;
		default: break;
		}
		return diff_a > diff_b;
	};
	std::priority_queue<std::pair<Axis, int>, std::vector<std::pair<Axis, int>>, decltype(comparator)> queue(comparator);
	for (auto i = 1; i < n; ++i) {
		queue.emplace(Axis::X, i);
		queue.emplace(Axis::Y, i);
	}
	UnionFind uft(n);
	long long int result = 0;
	while (!queue.empty()) {
		auto top = queue.top(); queue.pop();
		switch (top.first) {
		case Axis::X: 
			if (!uft.is_same(sort_by_x[top.second], sort_by_x[top.second - 1])) {
				result += points[sort_by_x[top.second]].x - points[sort_by_x[top.second - 1]].x;
				uft.merge(sort_by_x[top.second], sort_by_x[top.second - 1]);
			}
			break;
		case Axis::Y:
			if (!uft.is_same(sort_by_y[top.second], sort_by_y[top.second - 1])) {
				result += points[sort_by_y[top.second]].y - points[sort_by_y[top.second - 1]].y;
				uft.merge(sort_by_y[top.second], sort_by_y[top.second - 1]);
			}
			break;
		default: break;
		}
	}
	std::cout << result << std::endl;
}

