struct Union_Find {

    vector<int> par;
    vector<int> rank;

    Union_Find(int n) : par(n), rank(n, 1) {
        for(int i=0; i<n; i++) par[i] = i;
    } 

    int find(int x) {
        if(x == par[x]) return x;
        return par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);

        if(x == y) return;

        if(rank[x] < rank[y]) swap(x, y);
        par[y] = x;
        rank[x] += rank[y];
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return rank[find(x)];
    }

};

struct Edge {
    int a, b, cost;
    bool operator<(const Edge& o) const {
        return cost < o.cost;
    }
};


