class UnionFind
{
	vector<int> pr, rank;
public:
	UnionFind(int n) {
		pr.resize(n);
		rank.resize(n, 0);	//rank	子どもの深さ
		for (int i = 0; i < n; ++i) pr[i] = i;	//頂点iの親を格納する
	}
	int root(int x) {
		if (x == pr[x]) return x;
		else return pr[x] = root(pr[x]);	//経路圧縮
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	bool unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		if (rank[x] < rank[y]) {
			pr[x] = y;	//子どもを深く持つ方を親にする
		}
		else {
			pr[y] = x;
			if (rank[x] == rank[y]) ++rank[x];
		}
		return true;
	}
};

