        xst.emplace_back(x,y,idx);
        yst.emplace_back(y,x,idx);
    }
    std::sort(xst.begin(), xst.end());
    std::sort(yst.begin(), yst.end());
    std::priority_queue<tp,std::vector<tp>,std::greater<>>que;
    std::map<std::pair<int,int>,int> dic;
    for(int i = 0; i + 1 < xst.size(); ++i){
        int ax,ay,ai,bx,by,bi;
