struct UnionFind {
  vector<int> data;

  UnionFind(int sz) {
    data.assign(sz, -1);
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  bool same(int a, int b){
    return find(a) == find(b);
  }

  int size(int k) {
    return (-data[find(k)]);
  }
};

struct Edge{
  int a, b;
  long long weight;

  Edge(int a, int b, long long weight) : a(a), b(b), weight(weight){}
  bool operator< (const Edge& r) const {
    if(weight != r.weight) return weight < r.weight;
    if(a != r.a) return a < r.a;
    return b < r.b;
  }
};

long long kruskal(int V, vector<Edge>& Edges){
  long long ans = 0; // 辺の重みの総和
  int count =0; // 選んだ辺の数
  int E = Edges.size(); // 辺の数
  sort(Edges.begin(), Edges.end());
  UnionFind uf(V);
  for(int i = 0; i < E; ++i){
    int a = Edges[i].a, b = Edges[i].b;
    if(uf.same(a, b)) continue;
    ans += Edges[i].weight;
    uf.unite(a, b);
    ++count;
  }
  return ans;
}

