vector<pair<int, int> > vr;
//            r  num
vector<pair<int, int> > vc;
//            c  num
priority_queue<pair<int, pair<int, int> > > q;
//                  cost      num, num
int N;

void init()
{
	cin >> N;
	rep(i, N) {
		int r, c;
		cin >> c >> r;
		vr.PB(MP(r, i));
		vc.PB(MP(c, i));
	}
	sort(all(vr));
	sort(all(vc));
	rep(i, N-1) {
		int r1 = vr[i].first;
		int r2 = vr[i+1].first;
		q.push(MP(-abs(r1-r2), MP(vr[i].second, vr[i+1].second)));
		int c1 = vc[i].first;
		int c2 = vc[i+1].first;
		q.push(MP(-abs(c1-c2), MP(vc[i].second, vc[i+1].second)));
	}
}

struct uf {
	vector<int> par;
	vector<int> h;
	int n;
	uf(int sz) {
		n = sz;
		par.RS(n);
		h.RS(n, 0);
		rep(i, n) par[i] = i;
	}
	int root(int x) {
		if (par[x] == x) return x;
		return par[x] = root(par[x]);
	}
	bool merge(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		if (h[x] > h[y]) {
			par[y] = x;
		} else {
			par[x] = y;
			if (x == y) h[y]++;
		}
		return true;
	}
};


void solve()
{
	int res = 0;
	uf u(N);
	while (!q.empty()) {
		auto x = q.top();
		int c = x.first;
		int n1 = x.second.first;
		int n2 = x.second.second;
		if (u.merge(n1, n2)) {
			res += c;
		}
		q.pop();
	}
	cout << -res << endl;
}

