int group(int idx) {
  int original_idx = idx;
  int group_idx;
  while (uf[idx] != idx) {
    idx = uf[idx];
  }
  group_idx = idx;
  idx = original_idx;
  while (uf[idx] != idx) {
    int parent_idx = uf[idx];
    uf[idx] = group_idx;
    idx = parent_idx;
  }
  return(group_idx);
}

void merge(int src_idx, int dest) {
  while (uf[src_idx] != src_idx) {
    int parent_idx = uf[src_idx];
    uf[src_idx] = dest;
    src_idx = parent_idx;
  }
  uf[src_idx] = dest;
  return;
}

