struct UnionFind {
  int N;
  vector<int> par,ranc;

  UnionFind(int N) : N(N),par(N),ranc(N) { REP(i,N) par[i]=i,ranc[i]=0; }

  int root(int s) {
    if (par[s]==s) return s;
    else return root(par[s]);
  }

  bool same(int x, int y) { return root(x)==root(y); }

  bool connected() {
    int base = root(0);
    REP(i,N) if (root(i)!=base) return false;
    return true;
  }

  void merge(int x, int y) {
    x = root(x);
    y = root(y);
    if (x==y) return;
    if (ranc[x]>ranc[y]) {
      par[y] = x;
    } else {
      par[x] = y;
      if (ranc[x]==ranc[y]) ranc[y]++;
    }
  }
};

int main() {
  int N;cin>>N;
  vector<tuple<int,int,int>> xtowns;
  vector<tuple<int,int,int>> ytowns;
  REP(i,N) {
    int x,y;cin>>x>>y;
    xtowns.push_back({x,y,i});
    ytowns.push_back({y,x,i});
  }

  struct edge { int cost,from,to; };
  auto comp = [](edge a, edge b) { return a.cost > b.cost; };
  priority_queue<edge, vector<edge>, decltype(comp)> pq(comp);
  // xの順に並び替えた上で、edgeを追加
  sort(ALL(xtowns));
  FOR(i,1,N) {
    int x1,y1,idx1;
    tie(x1,y1,idx1) = xtowns[i-1];
    int x2,y2,idx2;
    tie(x2,y2,idx2) = xtowns[i];
    edge e = {abs(x2-x1),idx1,idx2};
    pq.push(e);
  }
  // yの順に並び替えた上で、edgeを追加
  sort(ALL(ytowns));
  FOR(i,1,N) {
    int x1,y1,idx1;
    tie(y1,x1,idx1) = ytowns[i-1];
    int x2,y2,idx2;
    tie(y2,x2,idx2) = ytowns[i];
    pq.push({abs(y2-y1),idx1,idx2});
  }

  // 全てのrootが同じになればいい
  UnionFind uf(N);
  int ans = 0;
  while (true) {
    edge e = pq.top();pq.pop();
    if (uf.root(e.from) == uf.root(e.to)) continue;
    uf.merge(e.from,e.to);
    ans += e.cost;
    if (uf.connected()) break;
  }
  OUT(ans);

  return 0;
}

