      if(!used[index]) {
        //cout << "D to " << index << endl;
        auto next_x = point[index].first;
        auto next_y = point[index].second;
        pq.push(P(min(abs(now_x-next_x), abs(now_y-next_y)), index));
      }
    }

    auto u = upper_bound(ALL(y), make_pair(now_y, INF));
    if(u != y.end()) {
      int index = (*u).second;
      if(!used[index]) {
        //cout << "U to " << index << endl;
