    cin >> a >> b;
    town[i] = make_pair(a, b);
  }
  UnionFind closed(n);
  priority_queue<pair<int, pair<int, int>>> road;
  rep(i, n)
  {
    rep(j, i)
    {
      road.push(make_pair(-min(abs(town[i].first - town[j].first), abs(town[i].second - town[j].second)), make_pair(i, j)));
    }
  }
  int ans = 0;
  while (!road.empty())
  {
    auto top = road.top();
    road.pop();
    int cost = -top.first;
    int i = top.second.first;
    int j = top.second.second;
    if (closed.root(i) == closed.root(j))
      continue;
    closed.unite(i, j);
    ans += cost;
  }
  cout << ans << endl;

  return 0;
}

