  uf.Unite(0, 1);
  ll ans = 0;
  for (int i = 0; i < n; ++i) {
    if (!uf.Same(0, i)) {
      uf.Unite(i, 0);
      ans += dists[i];
    }
  }

  cout << ans << '\n';
}

