void makeSet(int v) {
	parent[v] = v;
	rnk[v] = 0;
}

int findSet(int v) {
	if (v == parent[v])
		return v;
	return parent[v] = findSet(parent[v]);
}

void unionSets(int a, int b) {
	a = findSet(a);
	b = findSet(b);
	if (a != b) {
		if (rnk[a] < rnk[b])
			swap(a, b);
		parent[b] = a;
		if (rnk[a] == rnk[b])
			++rnk[a];
	}
}
