#include <queue>

#include <vector>

struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

Weight kruskal(const Graph &g) {
	size_t nvertices = g.vertices.size();
	UnionFind uf((int)nvertices);
	priority_queue<Edge> que;
	for (const auto &p_e : g.edges)
		if (p_e->p_src->id < p_e->p_dst->id)
			que.push(*p_e);

	Weight sum = 0;
	for (int i = 0; i < nvertices && !que.empty();)
	{
		Edge tmpe(que.top()); que.pop();
		if (uf.unionSet(tmpe.p_src->id, tmpe.p_dst->id)) {
			sum += tmpe.weight;
			i++;
		}
	}

	return sum;
}
using Pwi = pair<Weight, int>;
