		qx.push(Pwi(x, id));
		qy.push(Pwi(y, id));
	}
	Graph g(N);
	REP(i, N - 1) {
		Pwi tmppair, nxtpair;
		tmppair = qx.top(); qx.pop();
		nxtpair = qx.top();
		g.add_edge(tmppair.second, nxtpair.second, tmppair.first - nxtpair.first);
		g.add_edge(nxtpair.second, tmppair.second, tmppair.first - nxtpair.first);
		tmppair = qy.top(); qy.pop();
		nxtpair = qy.top();
		g.add_edge(tmppair.second, nxtpair.second, tmppair.first - nxtpair.first);
		g.add_edge(nxtpair.second, tmppair.second, tmppair.first - nxtpair.first);
	}

	ans = kruskal(g);

	cout << ans << endl;
	return;
}

