	return get_g(grp.at(i), grp);
}

int	main() {
	int N;
	cin >>N;
	vector<vector<int>> X(N, vector<int> (2, 0));
	vector<vector<int>> Y(N, vector<int> (2, 0));
	for (int i=0; i<N; i++) {
		cin >>X.at(i).at(0) >>Y.at(i).at(0);
		X.at(i).at(1)=i;
		Y.at(i).at(1)=i;
	}
	sort(X.begin(), X.end());
	sort(Y.begin(), Y.end());
	vector<vector<int>> D;
	for (int i=0; i<N-1; i++) {
		int d=X.at(i+1).at(0)-X.at(i).at(0);
		D.push_back({d, X.at(i).at(1), X.at(i+1).at(1)});
		d=Y.at(i+1).at(0)-Y.at(i).at(0);
		D.push_back({d, Y.at(i).at(1), Y.at(i+1).at(1)});
	}
	sort(D.begin(), D.end());
	vector<int> grp(N, 0);
	vector<int> grp_depth(N, 0);
	for (int i=0; i<N; i++)
		grp.at(i)=i;
	int ix=0;
	int S=0;
	int NoB=0;
	while (NoB!=N-1) {
		while (get_g(D.at(ix).at(1), grp)==get_g(D.at(ix).at(2), grp))
			ix++;
		S +=D.at(ix).at(0);
		int p1=get_g(D.at(ix).at(1), grp);
		int p2=get_g(D.at(ix).at(2), grp);
		if (grp_depth.at(p1)==grp_depth.at(p2)) {
			// Groups have same height
			// Merge into less-number-group
			grp.at(max(p1, p2)) = get_g(min(p1, p2), grp);
			grp_depth.at(min(p1, p2))++;
		} else if (grp_depth.at(p1)>grp_depth.at(p2)) {
			// x is higher
			// Merge into x so that the hight will not increase
			// (height for y will be +1)
			grp.at(p2) = p1;
		} else
			// y is higher
			// Merget into y
			grp.at(p1) = p2;
		NoB++;
	}
	cout <<S <<endl;
	return 0;
}

