const int MAX_V = 200010;

int par[MAX_V];
int rank_[MAX_V];

void init(int n) {

    for (int i = 0; i < n; ++i) {
        par[i] = i;
        rank_[i] = 0;
    }
}

int root(int x) {
    return par[x] == x ? x : par[x] = root(par[x]); //経路圧縮
}

bool same(int x, int y) {
    return root(x) == root(y);
}

void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;

    if (rank_[x] < rank_[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (rank_[x] == rank_[y]) rank_[x]++;
    }
}

struct edge {
    ll u, v, cost;
};

vector<edge> E;

bool comp(edge &e1, edge &e2) {
    return e1.cost < e2.cost;
}

ll kruskal(int n) {
    sort(E.begin(), E.end(), comp);
    init(n);
    ll res = 0;
    for (auto e : E) {
        if (!same(e.u, e.v)) {
            unite(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}

