class UnionFind {
public:
  vector<int> data;
  UnionFind(int size) : data(size, -1) {}
  int find(int x) {
    return data[x] < 0 ? x : data[x] = find(data[x]);
  }
  bool unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
