ll uf_rank[MAX_N];

void uf_init(ll n) {
  for (ll i = 0; i < n; ++i) {
    uf_par[i] = i;
    uf_rank[i] = 0;
  }
}

ll uf_find (ll x) {
  if (uf_par[x] == x) {return x;}
  else {
    return uf_par[x] = uf_find(uf_par[x]);
  }
}

void uf_unite(ll x, ll y) {
  x = uf_find(x);
  y = uf_find(y);

  if (x == y) {return;}
  if (uf_rank[x] < uf_rank[y]) {uf_par[x] = y;}
  else {
    uf_par[y] = x;
    if (uf_rank[x] == uf_rank[y]) uf_rank[x] += 1;
  }
}

bool uf_same(ll x, ll y) {
  return uf_find(x) == uf_find(y);
}
