    }


    for (int i = 0; i < V - 1; i++) {
        ll p = y[i].second;
        ll n = y[i + 1].second;
        G[p].PB(MP(min(abs(z[p].first - z[n].first), abs(z[p].second - z[n].second)), n));
        G[n].PB(MP(min(abs(z[p].first - z[n].first), abs(z[p].second - z[n].second)), p));
    }

    cout << prim() << endl;
}

