		UnionFind uf(n);
		sort(es.begin(), es.end());
		// for(auto e : es)cout << e.from << " " <<  e.to << " " << e.cost << endl;

		ll min_cost = 0;
		for(auto e : es){
			if(uf.find(e.from) == uf.find(e.to))continue;
			uf.unite(e.from, e.to);
			min_cost += e.cost;
		}
		return min_cost;
	}

