struct UnionFind {
 private:
  vector<int> data;
  vector<int> rank;

 public:
  int num;

  UnionFind(int N) : data(N, -1), rank(N, 0), num(N) {}

  int root(int x) {
    if (data[x] < 0) return x;
    return data[x] = root(data[x]);
  }

  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x != y) {
      if (rank[x] < rank[y]) swap(x, y);
      if (rank[x] == rank[y]) rank[x]++;
      data[x] += data[y];
      data[y] = x;
      num--;
    }
    return x != y;
  }

  bool same(int x, int y) { return root(x) == root(y); }

  int size(int x) { return -data[root(x)]; }
};

struct Edge {
  int to, w;
  Edge(int t, int w) :to(t), w(w) {}
};

struct Tree {
  int N;
  vector<vector<Edge>> edges;

  Tree(int N) :N(N), edges(N) {}

  void addDEdge(int a, int b) { addDEdge(a, b, 1); }
  void addDEdge(int a, int b, int w) { edges[a].emplace_back(b, w); }
  void addEdge(int a, int b) { addEdge(a, b, 1); }
  void addEdge(int a, int b, int w) { 
    edges[a].emplace_back(b, w);
    edges[b].emplace_back(a, w);
  }
};

struct Graph {
  int N, M;
  vector<vector<Edge>> edges;

  Graph(int N) : N(N), edges(N) {}

  void addDEdge(int a, int b) { addDEdge(a, b, 1); }
  void addDEdge(int a, int b, int w) { edges[a].emplace_back(b, w); }
  void addEdge(int a, int b) { addEdge(a, b, 1); }
  void addEdge(int a, int b, int w) {
    edges[a].emplace_back(b, w);
    edges[b].emplace_back(a, w);
  }

  vector<tuple<int, int, int>> edgeList;
  long long MSTcost;
  Tree kruskal() {
    rep(i, N) for (Edge e : edges[i]) {
      int a = i, b = e.to;
      if (a > b) continue;
      edgeList.emplace_back(e.w, a, b);
    }
    sort(edgeList.begin(), edgeList.end());
    UnionFind uf(N);
    Tree T(N);
    MSTcost = 0;
    for (auto t : edgeList) {
      int w, a, b;
      tie(w, a, b) = t;
      if (uf.same(a, b)) continue;
      T.addEdge(a, b, w);
      uf.unite(a, b);
      MSTcost += w;
    }
    return T;
  }
};

int main() {
  int N;
  cin >> N;
  vector<pair<int, int>> X, Y;
  rep(i, N) {
    int x, y;
    cin >> x >> y;
    X.emplace_back(x, i);
    Y.emplace_back(y, i);
  }
  sort(X.begin(), X.end());
  sort(Y.begin(), Y.end());

  Graph G(N);
  rep(i, N - 1) {
    G.addEdge(X[i].second, X[i + 1].second, X[i + 1].first - X[i].first);
    G.addEdge(Y[i].second, Y[i + 1].second, Y[i + 1].first - Y[i].first);
  }

  G.kruskal();

  cout << G.MSTcost << endl;
}

