const int MAX = 100010;

int par[MAX];//親
int Rank[MAX];//木の深さ

			  //n要素で初期化
void init(int n) {
	REP(i, n) {
		par[i] = i;
		Rank[i] = 0;
	}
}

//木の根を求める
int find(int x) {
	if (par[x] == x) {
		return x;
	}
	else {
		return par[x] = find(par[x]);//経路圧縮(根に直接つなぎなおす)もしつつ
	}
}

//xとyの属する集合を併合
void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y)return;
	//低いほうを高いほうにつなげる(効率化)
	if (Rank[x] < Rank[y]) {
		par[x] = y;
	}
	else {
		par[y] = x;
		if (Rank[x] == Rank[y])Rank[x]++;
	}
}

//xとyが同じ集合に属するか否か
bool same(int x, int y) {
	return find(x) == find(y);
}


struct edge { int u, v, cost; };
struct vertex { int p, x, y; };

//比較関数
bool comp(const edge& e1, const edge&e2) {
	return e1.cost < e2.cost;
}
bool compX(const vertex& v1, const vertex& v2) {
	return v1.x < v2.x;
}
bool compY(const vertex& v1, const vertex& v2) {
	return v1.y < v2.y;
}

edge es[2 * MAX];
vertex ver[MAX];
int N; int E;

ll kruskal() {
	sort(es, es + E, comp);//costでソート
	init(N);
	ll res = 0;
	//コストが小さい辺から順に追加する
	REP(i, E) {
		edge e = es[i];
		//もし閉路ができなければその辺を追加する
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}

