class UnionFind {
public:
    vector <ll> par;
    vector <ll> siz;

    UnionFind(ll sz_): par(sz_), siz(sz_, 1LL) {
        for (ll i = 0; i < sz_; ++i) par[i] = i;
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);
        for (ll i = 0; i < sz_; ++i) par[i] = i;
    }

    ll find(ll x) {
        while (par[x] != x) {
            x = par[x] = par[par[x]];
        }
        return x;
    }

    bool merge(ll x, ll y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool issame(ll x, ll y) {
        return find(x) == find(y);
    }

    ll size(ll x) {
        return siz[find(x)];
    }
};


struct Graph{
public:
ll V, logV;
vector<vector<edge>> Glist;
vector<vector<ll>> Gmatrix;
vector<ll> LCA_dist;
vector<vector<ll>> LCA_doubling;

Graph(ll NodeNum){
    V = NodeNum;
    Glist.resize(V);
}
    void add(ll from,ll to,ll cost = 1){
        Glist[from].push_back({to,cost});
    }
    void bidadd(ll from,ll to,ll cost = 1){
        Glist[from].push_back({to, cost});
        Glist[to].push_back({from, cost});
    }

    void express(){
        for(ll i = 0; i < Glist.size(); i++){
            cout << i << " => {";
            eachdo(Glist[i], e){
                cout << " " << e.to;
            } 
            cout << " }" << endl;
        }
        return;
    }

    void UpdateGmatrix() {
        Gmatrix.resize(V);
        rep(i,V){
            Gmatrix[i].resize(V,INF);
            eachdo(Glist[i],e){
                Gmatrix[i][e.to] = e.cost;
            }
        }
    }

    vector<vector<ll>> WarshallFloyd(){
        UpdateGmatrix();
        vector<vector<ll>> dist = Gmatrix;
        rep(i,V) dist[i][i] = 0;
        rep(k,V)rep(i,V)rep(j,V) chmin(dist[i][j],dist[i][k]+dist[k][j]);
        return dist;
    }

    vector<bool> hasNegativeLoop(){
        vector<bool> ret(V,false);
        vector<ll> dist(V,0);
        rep(loop,2*V-1){
            rep(i,V)eachdo(Glist[i],e){
                if(dist[i] + e.cost < dist[e.to]){
                    dist[e.to] = dist[i] + e.cost;
                    if(V-1 <= loop) ret[e.to] = true;        
                }
            }
        }
        return ret;
    }

    vector<ll> BellmanFord(ll start){
        vector<ll> dist(V,INF);
        dist[start] = 0;
        rep(loop,V-1){
            rep(i,V)eachdo(Glist[i],e){
                if(dist[i] + e.cost < dist[e.to]){
                    dist[e.to] = dist[i] + e.cost;        
                }
            }
        }
        return dist;
    }

    vector<ll> Dijkstra(ll start){
        vector<ll> dist(V,INF);
        priority_queue<P,vector<P>,greater<P>> que;
        dist[start] = 0;
        que.push(P(0,start)); 
        while(!que.empty()){
            P p = que.top();que.pop();
            ll v = p.second;
            if(dist[v]<p.first) continue;
            rep(i,Glist[v].size()){
                edge e = Glist[v][i];
                if(dist[v] + e.cost < dist[e.to]){
                    dist[e.to] = dist[v]+e.cost;
                    que.push(P(dist[e.to],e.to));
                }
            }
        }
        return dist;
    }

    // Graph needs to be undirected tree.
    void dfs_in_build_LCA(ll node, ll parent = -1){
        if (parent != -1) LCA_dist[node] = LCA_dist[parent] + 1;
        LCA_doubling[0][node] = parent;
        for(auto e : Glist[node]){
            if (e.to == parent) continue;
            dfs_in_build_LCA(e.to, node);
        }
    }

    void build_LCA(ll root){
        LCA_dist.assign(V, INF);
        logV = 1;
        while(1 << logV < V) logV++;
        LCA_dist.assign(V, INF);
        LCA_doubling.assign(logV, vector<ll>(V, -1));
        LCA_dist[root] = 0;
        dfs_in_build_LCA(root);
        for(ll i = 1; i < logV; i++){
            for(ll j = 0; j < V; j++){
                if (LCA_doubling[i - 1][j] == -1){
                    LCA_doubling[i][j] = -1;
                    continue;
                }
                LCA_doubling[i][j] = LCA_doubling[i - 1][LCA_doubling[i - 1][j]];
            }
        }
    }

    ll LCA_query(ll u, ll v){
        if (LCA_dist[v] < LCA_dist[u]) swap(u, v);
        ll upstream = LCA_dist[v] - LCA_dist[u];
        for(ll i = 0; i < logV; i++){
            if (upstream >> i & 1) v = LCA_doubling[i][v]; 
        }
        ll ng = -1, ok = V;
        while(ok - ng > 1){
            ll half = (ng + ok) / 2;
            ll ua = u, va = v;
            for(ll i = 0; i < logV; i++){
                if (half >> i & 1){
                    if (ua == -1 || va == -1){
                        ua = -1;
                        va = -1;
                        break;
                    }
                    ua = LCA_doubling[i][ua];
                    va = LCA_doubling[i][va];
                }
            }

            if (ua == va) ok = half;
            else ng = half;
        }
        ll ret = u;
        for(ll i = 0; i < logV; i++){
            if (ok >> i & 1) ret = LCA_doubling[i][ret]; 
        }
        return ret;
    }

    ll path_dist(ll u, ll v){
        return LCA_dist[u] + LCA_dist[v] - 2 * LCA_dist[LCA_query(u, v)];
    }

    bool is_on_path(ll u, ll v, ll x){
        return path_dist(u, x) + path_dist(x, v) == path_dist(u, v); 
    }

    // needs UnionFind
    // needs to be undirected graph
    ll kruskal(){
        vector<tuple<ll, ll, ll>> list_e; // cost, u, v
        rep(i, V) eachdo(Glist[i], e){
            if (i >= e.to) continue;
            list_e.emplace_back(make_tuple(e.cost, (ll)i, e.to));
        }        
        sort(list_e.begin(), list_e.end());
        ll ret = 0;
        UnionFind uf(V);
        rep(i, list_e.size()){
            ll cost, from, to;
            tie(cost, from, to) = list_e[i];
            if (!uf.issame(from, to)){
                ret += cost;
                uf.merge(from, to);
            }
        }
        return ret;
    }
};

