class UnionFind{
public:
    //親の番号を格納する。親だった場合はー（その集合のサイズ）
    vector<int> parents;

    //作る時はparentsを-1で初期化する
    //こうすることで全部ばらばらになる
    UnionFind(int n){
        parents = vector<int>(n, -1);
    }

    //Aがどのグループにいるか調べる
    int root(int A){
        if(parents[A]<0) return A;
        return parents[A] = root(parents[A]);
    }

    //自分のいるグループの大きさを調べる
    int size(int A){
        return -parents[root(A)];
    }

    //AとBをくっつける
    bool connect(int A, int B){
        //AとBを直接ではなく親同士をくっつける
        A=root(A);
        B=root(B);
        if(A==B){
            return false;
        }

        //大きい方（A)に小さい方（B)をくっつけたい
        if(size(A)<size(B)) swap(A, B);

        parents[A] += parents[B];
        parents[B] = A;

        return true;
    }
};


class Edge {
    public:
    ll source, target, cost;
    Edge(int source=0, int target=0, int cost=0):
    source(source), target(target), cost(cost){}
    bool operator < (const Edge &e) const{
        return cost < e.cost;
    }
};

ll kruskal(int N, vector<Edge> edges){
    ll totalCost = 0;
    sort(edges.begin(), edges.end());

    UnionFind uni(N);
    for(int i=0; i<edges.size(); i++){
        Edge e=edges[i];
        if(uni.root(e.source) != uni.root(e.target)){
            totalCost += e.cost;
            uni.connect(e.source, e.target);
        }
    }

    return totalCost;
}


