typedef long long ll;
typedef pair<ll, ll> P;
typedef vector<vector<P>> vp;

// input
int N;
vector<int> X, Y;

const ll INF = 1e15;

vector<P> xlist, ylist;
vp link;
vector<ll> w;
vector<bool> vis;
priority_queue<P, vector<P>, greater<P>> pq;


void input() {
    cin >> N;
    X = Y = vector<int>(N);
    rep(i, N) cin >> X[i] >> Y[i];
}


ll solve() {
    w = vector<ll>(N, INF);
    vis = vector<bool>(N, false);
    w[0] = 0;
    pq.push(P(0, 0));
    int n = 0;
    while (!pq.empty()) {
        ll cost = pq.top().first;
        int s = pq.top().second;
        pq.pop();
        if (vis[s]) continue;
        vis[s] = true;
        n++;
        if (n == N) break;
        for (P p : link[s]) {
            ll c = p.second;
            int t = p.first;
            if (!vis[t] && c < w[t]) {
                w[t] = c;
                pq.push(P(c, t));
            }
        }
    }
    ll ret = 0;
    rep(i, N) ret += w[i];
    return ret;
}


