using P = pair<s64, int>;

s64 prim(vector< vector< P > >& g, int s)
{
    int n = g.size();
    static const s64 inf = 1e18;
    vs64 cost(n, inf);
    cost[s] = 0;

    priority_queue<P, vector<P>, greater<P>> pq;
    pq.push(P{cost[s], s});

    s64 ret = 0;
    vector< bool > used(n, false);
    while (!pq.empty())
    {
        auto p = pq.top(); pq.pop();
        int from = p.second;
        if (used[from]) continue;
        used[from] = true;
        ret += cost[from];

        for (auto x : g[from])
        {
            int to = x.first;
            s64 c = x.second;
            if (cost[to] > c)
            {
                cost[to] = c;
                pq.push(P{cost[to], to});
            }
        }
    }

    return ret;
}

