bool sortbysec(const pair<pair<ll,ll>, ll> &a, const pair<pair<ll,ll>, ll> &b)
{
     return (a.first.second < b.first.second);
}

int prim(ll x)
{
    priority_queue<PII, vector<PII>, greater<PII> > Q;
    ll y;
    ll minimumCost = 0;
    PII p;
    Q.push(make_pair(0, x));
    while(!Q.empty())
    {
        // Select the edge with minimum weight
        p = Q.top();
        Q.pop();
        x = p.second;
        // Checking for cycle
        if(marked[x] == true)
            continue;
        minimumCost += p.first;
        marked[x] = true;
        for(ll i = 0;i < (int)adj[x].size();++i)
        {
            y = adj[x][i].second;
            if(marked[y] == false)
                Q.push(adj[x][i]);
        }
    }
    return minimumCost;
}

