        return a.x < b.x;
    });

    FOR(i, 1, n) {
        edge e = {a[i].x - a[i - 1].x, a[i - 1].i, a[i].i};
        E.pb(e);
    }

    sort(all(a), [](node a, node b) {
        return a.y < b.y;
    });

    FOR(i, 1, n) {
        edge e = {a[i].y - a[i - 1].y, a[i - 1].i, a[i].i};
        E.pb(e);
    }

    sort(all(E));

    int ans = 0;
    FOR(n) {
        link[i] = i;
        sz[i] = 1;
