struct UnionFind {
    vector<int> par;  // par[i]: parent of i

    UnionFind(int N) : par(N + 1) {  // initialize by making every node a root node
        for (int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) {  // find the root of a given node
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        par[rx] = ry;
    }

    bool same(int x, int y) {  // return true if x and y belong to the same tree
        return root(x) == root(y);
    }
};

