void prim() {
    int ff = 1;
    //Ưu tiên
    priority_queue<ad3, vector<ad3>, cmpc> qu;
    //Tự do cho các đỉnh
    memset(outside, 1, sizeof outside);
    //Set các nhãn bằng vô cực
    for (int i=1; i<=n; i++) d[i]=oo;
    //Thêm vào hàng đợi ưu tiên đỉnh u với trọng số là 0 và nhãn dán của u là 0
    qu.push({ff, 0, 1}); d[ff]=0;
    //U nằm trong cây khung
    outside[ff]=false;
    while (!qu.empty()) {
        // Lấy phần tử ưu tiên nhất
        ad3 pp=qu.top();
        qu.pop();
        //Lấy dữ liệu
        int u = pp.first;
        int du = pp.second;
        if (du!=d[u]) continue;
        //Tổng
        Sum+=d[u];
        d[u]=0;
        //Xét các đỉnh kề của U
        for (int i=0; i < e[u].size(); i++){
            if (d[e[u][i].F] > e[u][i].S && outside[e[u][i].F]) {
                //đặt d của v là w của cạnh (u,v)
                d[e[u][i].F] = e[u][i].S;
                // Thêm đỉnh v và nhãn dán d của v vào hàng đợi ưu tiên
                qu.push({e[u][i].F, d[e[u][i].F], u});
            }
        }
        outside[u] = false;
    }
}

