struct UnionFind {
  vector<int> d;
  UnionFind() { }
  UnionFind(int n) :d(n, -1) { }
  bool unite(int x, int y) {
    int a = root(x), b = root(y);
    if (a == b) return false;
    if (size(a) < size(b)) swap(a, b);
    d[a] += d[b];
    d[b] = a;
    return true;
  }
  int size(int v) { return -d[root(v)]; }
  int root(int v) { return d[v] < 0 ? v : d[v] = root(d[v]); }
  bool same(int x, int y) { return root(x) == root(y); }
};

void Calc() {
  int n = in;
  struct Data {
    int i, x, y;
    void In() {
      in, x, y;
    }
    bool operator<(const Data&d)const {
      return make_tuple(x, y) < make_tuple(d.x, d.y);
    }
  };

  vector<Data> d(n), dy(n);
  rep(i, n) {
    d[i].In();
    d[i].i = i;
    dy[i] = d[i];
    swap(dy[i].x, dy[i].y);
  }
  sort(all(d));
  sort(all(dy));

  vector<Data> x(n * 2 - 2);
  rep(i, n - 1) {
    x[i].x = d[i + 1].x - d[i].x;
    x[i].i = i;
    x[i].y = 0;
    x[i + n - 1].x = dy[i + 1].x - dy[i].x;
    x[i + n - 1].i = i;
    x[i + n - 1].y = 1;
    err(x[i + n - 1].x, dy[i + 1].x, dy[i].x);
  }
  sort(all(x));

  UnionFind uni(n);
  int cnt = 0;
  rep(i, 0, size(x)) {
    int a, b;
    if (x[i].y == 0) {
      a = d[x[i].i].i;
      b = d[x[i].i + 1].i;
    }
    else {
      a = dy[x[i].i].i;
      b = dy[x[i].i + 1].i;
    }
    if (uni.same(a, b)) continue;
    uni.unite(a, b);
    cnt += x[i].x;
    err(a, b, cnt, x[i].x, x[i].y);
  }
  cout << (cnt) << endl;

}

