class UnionFind {
  public:
    // 親の番号を格納する。親の場合 -1 になる
    vector<int> Parent;

    // 宣言されたとき Parent の値はすべて -1 にする
    UnionFind(int N) { Parent = vector<int>(N, -1); }

    // 与えられた値 x がどの親であるか調べる
    int root(int x) {
        if (Parent[x] < 0)
            return x;
        return Parent[x] = root(Parent[x]);
    }

    // 木の全体の数を返す
    int size(int x) { return -Parent[root(x)]; }

    // 2つの引数を同じ親にする
    bool update(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y)
            return false;
        if (size(x) < size(y))
            swap(x, y);
        Parent[x] += Parent[y];
        Parent[y] = x;
        return true;
    }

    // 引数の親が同じか判定する
    bool is_same(int x, int y) { return root(x) == root(y); }
};

// 最小全域木
class Kruskal {
  private:
    struct Edge {
        int u, v, cost;
    };
    int vertex_max, edge_max;
    long long cost_sum = 0;
    vector<Edge> edge;

  public:
    Kruskal(int edge_in, int vertex_in) {
        edge_max   = edge_in;
        vertex_max = vertex_in;
    }
    // 辺を追加する
    void update(int u, int v, int c) { edge.push_back({u, v, c}); }
    // 最小全域木を求める。そのときの最小コストを返す。
    long long cal() {
        sort(edge.begin(), edge.end(),
             [](const Edge e1, const Edge e2) { return e1.cost < e2.cost; });
        auto uni = UnionFind(vertex_max);
        for (int i = 0; i < edge_max; i++) {
            auto e = edge[i];
            if (!uni.is_same(e.u, e.v)) {
                uni.update(e.u, e.v);
                cost_sum += (long long)e.cost;
            }
        }
        return cost_sum;
    };
};

