struct UnionFind{
    vector<int> par;
    int cnt;
    UnionFind(int N):par(N,-1),cnt(N){}
    void init(int N){par.assign(N,-1);}
    int root(int x){
        if(par[x]<0)return x;
        return par[x]=root(par[x]);
    }
    bool issame(int x,int y){
        return root(x)==root(y);
    }
    bool merge(int x,int y){
        x=root(x),y=root(y);
        if(x==y)return false;
        if(par[x]>par[y])swap(x,y);
        par[x]+=par[y];
        par[y]=x;
        cnt--;
        return true;
    }
    int size(int x){
        return -par[root(x)];
    }
};
