typedef long long int ll;
#define ARRAY_MAX 100005

vector<ll> par(ARRAY_MAX);//親
vector<ll> ra(ARRAY_MAX);//木の深さ

typedef struct edge{

    ll u;
    ll v;
    ll cost;
}EDGE;

bool comp(const EDGE& e1,const EDGE& e2){
    return e1.cost < e2.cost;
}


//n要素で初期化
void init(ll n){
    for(ll i = 0;i < n;i++){
        par[i] = i;/*各ノードに番号を振る,この時par[x]=xとなる時は木の根となる*/
        ra[i] = 0;/*各ノード自体の高さは0*/
    }
}
//木の根を求める
ll find(ll x){
    if(par[x] == x){
        return x;/*根ならそのノードの番号を返す*/
    }else{
        return par[x] = find(par[x]);/*根でないならさらにノードの根を探す*/
    }
}

//xとyの属する集合を併合する
void unite(ll x,ll y){
    x = find(x);//xの根の番号を探す
    y = find(y);//yの根の番号を探す
    if(x == y){//一致すればつながっている
        return;
    }
    if(ra[x] < ra[y]){//xの高さが低いなら高いほうにつなぐ、そして高さは大きい方(y)になる
        par[x] = y;
    }else{
        par[y] = x;//yの高さが低いなら高いほうにつなぐ、そして高さは大きいほう(x)になる
        if(ra[x] == ra[y]){//高さが一致しているなら併合の高さは1増える
            ra[x]++;
        }
    }
}

//xとyが同じ集合に属するか判定
bool same(ll x,ll y){
    return find(x) == find(y);//同じ集合なら1、違うなら0が返る
}

ll kruskal(ll n,ll count,vector<EDGE>& es){

    sort(es.begin(),es.end(),comp);
    init(n);
    ll res = 0;
    for(ll i = 0;i < count;i++){
        EDGE e = es[i];
        if(!same(e.u,e.v)){
            unite(e.u,e.v);
            res += e.cost;
        }
    }
    return res;
}



int main(){

