    }

    for(ll i = 0;i < n-1;i++){
        for(ll j = i+1;j < n;j++){
            EDGE e;
            e.u = i;
            e.v = j;
            e.cost = min(abs(x[j]-x[i]),abs(y[j]-y[i]));
            es.push_back(e);
            count++;
        }
    }
    ll ans = kruskal(n,count,es);
    cout << ans << endl;



    return 0;
}

