TTT VT dijkstra(const GT&g,const int&start){
  VT d(g.n,MAXT);
  priority_queue<pair<T,int>,vector<pair<T,int>>,greater<pair<T,int>>>s;
  d[start]=0;
  s.emplace(d[start],start);
  while(!s.empty()){
    T expected=s.top().fi;int from=s.top().se;s.pop();
    if(d[from]<expected)continue;
    tra(id,g.g[from]){
      auto e=g.edges[id];
      int to=e.from^e.to^from;if(d[from]+e.cost<d[to]){d[to]=d[from]+e.cost;s.emplace(d[to],to);}
    }
  }
  return d;
}

TTT T prim(const GT&g){
  T total = 0;VI used(g.n,0);priority_queue<pair<T,int>,vector<pair<T,int>>,greater<pair<T,int>>>s;
  s.emplace(0,0);
  while(!s.empty()){
    T cost=s.top().fi;int from=s.top().se;s.pop();
    if(used[from])continue;used[from]=true;total+=cost;
    tra(id,g.g[from]){
      auto e=g.edges[id];
      int to=e.from^e.to^from;
      s.emplace(e.cost,to);
    }
  }
  return total;
}


