    for(int i=0; i<V-1; i++){
        es[2*i] = (edge){x[i].second,x[i+1].second,x[i+1].first-x[i].first};
        es[2*i+1] = (edge){y[i].second,y[i+1].second,y[i+1].first-y[i].first};
    }

    E=(V-1)*2;
    cout << kruskal() << endl; 
