// 経路圧縮している場合はランクではなくサイズ
struct UnionFind{
  // 負：根あり，絶対値はサイズの大きさ
  // 非負：根ではなく，値は親を指す（普通の parent の動き）
  vector<int> par;
  UnionFind(int n):par(n, -1){}

  int root(int x){
    // 負なので親，x はサイズの大きさではなく親の index
    if(par[x] < 0) return x;
    // 経路の圧縮（親を root に統一）
    else return par[x] = root(par[x]);
  }

  bool find(int x, int y){
    return root(x) == root(y);
  }

  //union が予約語
  void merge(int x, int y){
    x = root(x); y = root(y);
    if(x == y) return;

    // 絶対値でサイズの大きさを比較
    // rx が ry よりサイズが大きくなるよう swap
    if(-par[x] < -par[y]) swap(x, y);

    // rx に ry をくっつける
    // サイズの更新（ry のサイズを加算）
    par[x] += par[y];
    // 親の更新
    par[y] = x;
  }
};

