    x[i].second = i;
    y[i].second = i;
  }
  sort(x.begin(),x.end());
  sort(y.begin(),y.end());

  Graph g;
  g.n = N;
  Edge e;
  rep(i,N-1){
    e.a = x[i].second;
    e.b = x[i+1].second;
    e.cost = x[i+1].first - x[i].first;
    g.es.push_back(e);
  }
  rep(i,N-1){
    e.a = y[i].second;
    e.b = y[i+1].second;
    e.cost = y[i+1].first - y[i].first;
    g.es.push_back(e);
  }
  cout << g.kruskal() << endl;

  return 0;

}

