const u32 MAX_N = 100000;
i32 x[MAX_N], y[MAX_N];
bool used[MAX_N];

inline u32 calc(i32 x1, i32 y1, i32 x2, i32 y2) {
    return min(abs(x1-x2), abs(y1-y2));
}

int main() {
    u32 N;
    IN(N);
    REP(i, N) {
        cin >> x[i] >> y[i];
    }
    auto q = priority_queue<pair<u32, u32>, vector<pair<u32, u32>>,
         greater<pair<u32, u32>>>();
    used[0] = true;
    REP(i, N) {
        u32 cost = calc(x[0], y[0], x[i], y[i]);
        q.push(MP(cost, i));
    }
    u32 remain = N;
    u32 ans = 0;
    while(!q.empty()) {
        auto vi = q.top();
        q.pop();
        auto v = vi.first;
        auto index = vi.second;
        if(used[index]) {
            continue;
        }
        ans += v;
        if(!--remain) {
            break;
        }
        used[index] = true;
        REP(i, N) {
            if(used[i]) {
                continue;
            }
            u32 cost = calc(x[index], y[index], x[i], y[i]);
            q.push(MP(cost, i));
        }
    }
    cout << ans << endl;
    return 0;
}

