#define REP(i, n) for (int i = 0; i < n; i++)
#define REPR(i, n) for (int i = n; i >= 0; i--)
#define FOR(i, m, n) for (ll i = m; i < n; i++)
#define ALL(v) (v).begin(), (v).end()

struct UF{
    int p[MAX_N], r[MAX_N];
    void init(int N){
        REP(i,N){
            p[i] = i;
            r[i] = 0;
        }
    }
    int find(int x){
        if(p[x] == x)return x;
        else return p[x] = find(p[x]);
    }
    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x==y)return;
        if(r[x]<r[y])swap(x,y);
        if(r[x]==r[y])r[x]++;
        p[y] = x;
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
};

P x[MAX_N], y[MAX_N];

int main() {
    int n;

    cin >> n;
    REP(i,n){
        cin >> x[i].first >> y[i].first;
        x[i].second = i;
        y[i].second = i;
    }
    sort(x,x+n);
    sort(y,y+n);
    vector<P3> ls;
    REP(i,n){
        ls.push_back({abs(x[i+1].first-x[i].first),{x[i].second,x[i+1].second}});
        ls.push_back({abs(y[i+1].first-y[i].first),{y[i].second,y[i+1].second}});
    }
    sort(ALL(ls));
    int ans = 0;
    UF g;
    g.init(n);
    for(auto i : ls){
        P e = i.second;
        if(!g.same(e.first,e.second)){
            g.unite(e.first,e.second);
            ans += i.first;
        }
    }
    cout << ans << endl;
    return 0;
}

