typedef int64_t Int;
Int mod = 1e9+7;
Int INF = 1e9+7;

Int par[100001];

Int root(Int x) {
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
}

void unite(Int x, Int y) {
    Int rx = root(x);
    Int ry = root(y);
    if (rx == ry) return;
    par[rx] = ry;
}

int main() {
    ios::sync_with_stdio(false);
    Int n;
    cin >> n;
    for (Int i = 0; i < n; i++) par[i] = i;
    vector<pair<Int, Int>> vx(n), vy(n);
    for (Int i = 0; i < n; i++) {
        Int x, y;
        cin >> x >> y;
        vx[i] = {x, i};
        vy[i] = {y, i};
    }
    sort(vx.begin(), vx.end());
    sort(vy.begin(), vy.end());
    priority_queue<tuple<Int, Int, Int>, vector<tuple<Int, Int, Int>>, greater<tuple<Int, Int, Int>>> q;
    for (Int i = 0; i < n - 1; i++) {
        q.push({vx[i + 1].first - vx[i].first, vx[i].second, vx[i + 1].second});
        q.push({vy[i + 1].first - vy[i].first, vy[i].second, vy[i + 1].second});
    }
    Int res = 0;
    for (Int i = 0; i < n - 1; i++) {
        tuple<Int, Int, Int> t = q.top();
        while (root(get<1>(t)) == root(get<2>(t))) {
            q.pop();
            t = q.top();
        }
        unite(get<1>(t), get<2>(t));
        res += get<0>(t);
    }
    dump(res);
    return 0;
}

