 struct UnionFind{
    vector<ll> par;
    UnionFind(ll n) : par(n, -1){}


    int root(int x){
        if(par[x]<0) return x;
        return par[x] = root(par[x]);
    }

    bool same(int a, int b){
        return root(a)==root(b);
    }
    void unite(int a, int b){
        int x=root(a), y=root(b);
        if(same(x, y)) return;
        if(y<x) swap(x, y);
        par[x] += par[y];
        par[y] = x;
    }
    int size(int x){
        return -par[root(x)];
    }

};

int main(){
    int n;  cin >> n;
    UnionFind tree = UnionFind(n);
    vector<pair<ll, ll>> g(n);
    REP(i, n) cin >> g[i].first >> g[i].second;
    typedef tuple<ll, ll, ll> tp;
    priority_queue<tp, vector<tp>, greater<tp>> que;

    REP(i, n){
        ll x=g[i].first, y=g[i].second;
        FOR(j, i+1, n){
            ll a=g[j].first, b=g[j].second;
            ll cost = min(abs(a-x), abs(b-y));
            que.emplace(cost, i, j);
        }
    }
    ll res=0;
    //cout << "size: " << que.size() << endl;
    while(!que.empty()){
        int to=get<1>(que.top()), from=get<2>(que.top());
        ll cost = get<0>(que.top());    
        que.pop();
        if(!tree.same(from, to)){
            res += cost;
            tree.unite(from, to);
        }
    }
    cout << res << endl;
}

