typedef struct {
    vector<pair<int, int>> edge;
}node_t;
vector<node_t> node;

bool cmpx(const posi_t& left, const posi_t& right) {
    return left.x < right.x;
}
bool cmpy(const posi_t& left, const posi_t& right) {
    return left.y < right.y;
}

priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
void prim(ll& ans, vector<bool>& visit) {
    //int cnt = 1;
    while (!pq.empty()) {
        pair<int, int> x = pq.top();
        pq.pop();
        if (visit[x.second]) continue;
        ans += (ll)x.first;
        visit[x.second] = true;
        //cnt++;

        //cout << x.second << "ans=" << ans << endl;
        for (auto ed : node[x.second].edge) {
            if (visit[ed.second]) continue;
            pq.push(ed);
        }        
    }
}

int main() {
    int N;
    cin >> N;

    posi = vector<posi_t>(N);
    for (int i = 0; i < N; i++) {
        posi[i].id = i;
        cin >> posi[i].x >> posi[i].y;
    }

    node = vector<node_t>(N);
    sort(posi.begin(), posi.end(), cmpx);
    for (int i = 0; i < N - 1; i++) {
        int cost = posi[i + 1].x - posi[i].x;
        node[posi[i].id].edge.push_back(make_pair(cost, posi[i + 1].id));
        node[posi[i + 1].id].edge.push_back(make_pair(cost, posi[i].id));
    }

    sort(posi.begin(), posi.end(), cmpy);
    for (int i = 0; i < N - 1; i++) {
        int cost = posi[i + 1].y - posi[i].y;
        node[posi[i].id].edge.push_back(make_pair(cost, posi[i + 1].id));
        node[posi[i + 1].id].edge.push_back(make_pair(cost, posi[i].id));
    }

    vector<posi_t>().swap(posi);
    ll ans = 0;
    vector<bool> visit(N);
    visit[0] = true;
    for (auto ed : node[0].edge) {
        pq.push(ed);
    }
    prim(ans, visit);

    cout << ans << endl;

}

