class city {
public:
  i64 id, x, y;
};

namespace std {
  std::istream& operator>>(std::istream& is, city& self) {
    static i64 next_id = 0;
    self.id = next_id++;
    return is >> self.x >> self.y;
  }

  template <>
  struct hash<std::pair<i64, i64>> {
    std::size_t operator()(const std::pair<i64, i64>& self) const {
      static std::hash<i64> hash;
      std::size_t result = 17;
      result = 31 * result + hash(self.first);
      result = 31 * result + hash(self.second);
      return result;
    }
  };
}

int main() {
  i64 N;
  std::cin >> N;
  std::vector<city> cities;
  tools::read(cities, N);

  tools::prim<i64> prim(N);
  std::unordered_map<std::pair<i64, i64>, i64> map;
  std::sort(cities.begin(), cities.end(), [](const city& city1, const city& city2) { return city1.x < city2.x; });
  for (auto it1 = cities.begin(), it2 = ++cities.begin(); it2 != cities.end(); ++it1, ++it2) {
    std::pair<i64, i64> pair = std::make_pair(std::min(it1->id, it2->id), std::max(it1->id, it2->id));
    if (map.find(pair) != map.end()) {
      map[pair] = std::min(map[pair], it2->x - it1->x);
    } else {
      map.insert(std::make_pair(pair, it2->x - it1->x));
    }
  }
  std::sort(cities.begin(), cities.end(), [](const city& city1, const city& city2) { return city1.y < city2.y; });
  for (auto it1 = cities.begin(), it2 = ++cities.begin(); it2 != cities.end(); ++it1, ++it2) {
    std::pair<i64, i64> pair = std::make_pair(std::min(it1->id, it2->id), std::max(it1->id, it2->id));
    if (map.find(pair) != map.end()) {
      map[pair] = std::min(map[pair], it2->y - it1->y);
    } else {
      map.insert(std::make_pair(pair, it2->y - it1->y));
    }
  }
  for (const auto& kv : map) {
    prim.add_edge(kv.first.first, kv.first.second, kv.second);
  }
  std::cout << prim.calc().total_distance << std::endl;
  return 0;
}

