class DisjointSet
{
public:
    DisjointSet(int _n)
    {
        n = _n;
        root.resize(n);
        height.resize(n);

        for (int i = 0;i < n; i++) {
            root[i] = i;
            height[i] = 0;
        }
    }

    int getRoot(int x)
    {
        if (root[x] == x)
            return x;

        return root[x] = getRoot(root[x]);
    }

    void merge(int x, int y)
    {
        int rx = getRoot(x), ry = getRoot(y);
        if (rx == ry)
            return;

        if (height[rx] < height[ry]) {
            root[rx] = ry;
        } else if (height[rx] > height[ry]) {
            root[ry] = rx;
        } else {
            root[ry] = rx;
            height[rx]++;
        }
    }
private:
    int n;
    vector<int> root, height;
};

void solveSingleCase(int caseNo)
{
    int N;
    cin >> N;
    vector<pair<Pii, int> > xy, yx;
    FOR(i, 0, N) {
        int a, b;
        cin >> a >> b;
        xy.PB(PAIR(Pii(a, b), i));
        yx.PB(PAIR(Pii(b, a), i));
    }

    sort(ALL(xy));
    sort(ALL(yx));

    vector<pair<int, Pii> > Edges;
    FOR(i, 0, N - 1) {
        int x1 = xy[i].FIR.FIR, x2 = xy[i + 1].FIR.FIR;
        int i1 = xy[i].SEC, i2 = xy[i + 1].SEC;
        Edges.PB(PAIR(x2 - x1, Pii(i1, i2)));

        int y1 = yx[i].FIR.FIR, y2 = yx[i + 1].FIR.FIR;
        int j1 = yx[i].SEC, j2 = yx[i + 1].SEC;
        Edges.PB(PAIR(y2 - y1, Pii(j1, j2)));
    }

    sort(ALL(Edges));
    lint ret = 0;
    DisjointSet dset(N);

    for (auto& edge: Edges) {
        int cost = edge.FIR;
        int a = edge.SEC.FIR, b = edge.SEC.SEC;
        if (dset.getRoot(a) != dset.getRoot(b)) {
            ret += cost;
            dset.merge(a, b);
        }
    }

    cout << ret << endl;
};

