class DisjointSet{
    public:
    vector<ll> rank,p;
    DisjointSet(){}
    DisjointSet(ll size){
        rank.resize(size,0);
        p.resize(size,0);
        rep(i,size) makeSet(i);
    }
    void makeSet(ll x){ //頂点数が一つ。初期化。
        p[x] = x;
        rank[x] = 0;
    }
    bool same(ll x,ll y){
        return findSet(x) == findSet(y);
    }
    void unite(ll x, ll y){
        link(findSet(x),findSet(y));
    }
    void link(ll x, ll y){
        if(rank[x] > rank[y]){
            p[y] = x;
        }
        else{
            p[x] = y;
            if(rank[x] == rank[y]){
                rank[y]++;
            }
        }
    }
    ll findSet(ll x){
        if(x!=p[x]){
            p[x] = findSet(p[x]);
        }
        return p[x];
    }
};

class Edge{
    public:
    ll source,target,cost;
    Edge(ll source=0,ll target=0,ll cost=0):
    source(source),target(target),cost(cost){}
    bool operator < (const Edge &e) const{
        return cost < e.cost; //Edgeのオブジェクトをソートできるように。
    }
};
ll kruskal(ll n,vector<Edge> edges){
    ll totalCost = 0; //コスト合計
    sort(edges.begin(),edges.end()); //辺の重みでソート
    DisjointSet dset = DisjointSet(n+1); //要素数はnでも良さそう
    //木の高さと親を入れる配列を用意し、頂点が一つのものを用意して初期化。
    rep(i,n) dset.makeSet(i); //既に初期化しているから必要ないのでは？
    ll source,target;
    rep(i,edges.size()){
        Edge e = edges[i];
        if(!dset.same(e.source,e.target)){ //sourceとtargetが同じ木でないとき
            totalCost += e.cost;
            dset.unite(e.source,e.target);

        }
    }
    return totalCost;
}

