    edge[arr2[i+1].se].push_back(mp(min(abs(x[arr2[i].se]-x[arr2[i+1].se]), abs(y[arr2[i].se]-y[arr2[i+1].se])), arr2[i].se));
  }
  for(int i=0;i<N;++i) {
    sort(edge[i].begin(), edge[i].end());
  }
  priority_queue<pair<ll, ll>, vector<pair<ll, ll> >, greater<pair<ll, ll> > > que;
  que.push(mp(0, 0));
  pair<ll, ll> state; //(dist, ind)
  map<ll, ll> amap;
  for(int i=0;i<N;++i) amap[i] = -1;
  ll node, dist;
  while(!que.empty()) {
    state = que.top();que.pop();
    node = state.se;
    dist = state.fi;
    if(amap[node]>-1) continue;
    amap[node] = dist;
    for(int i=0;i<edge[node].size();++i) {
      if(amap[edge[node][i].se]>-1) continue;
      que.push(mp(edge[node][i].fi, edge[node][i].se));
    }
  }
  ll ans = 0;
  for(int i=0;i<N;++i) ans += amap[i];
  cout<<ans<<endl;
}

