class UF {
  private:
	vector<int> root;
	vector<int> nodenum;

  public:
	UF(int n) {
		root = vector<int>(n, -1);
		nodenum = vector<int>(n, 1);
	}
	int getRoot(int x) {
		if (root[x] == -1) return x;
		return root[x] = getRoot(root[x]);
	}
	int getNodeNum(int x) { return nodenum[getRoot(x)]; }
	void connect(int x, int y) {
		x = getRoot(x);
		y = getRoot(y);
		if (x == y) return;
		if (x > y) swap(x, y);
		root[y] = x;
		nodenum[x] += nodenum[y];
	}
};

