struct UnionFind
{
    vector<int> par;
    vector<int> sizes;

    UnionFind(int n)
    {
        for (auto i = 0; i < n; i++)
        {
            par.push_back(i);
            sizes.push_back(1);
        }
    }

    int find(int x)
    {
        if (x == par[x])
        {
            return x;
        }
        else
        {
            return par[x] = find(par[x]);
        }
    }

    // 2つのデータx, yが属する木をマージする
    void unite(int x, int y)
    {
        // データの根ノードを得る
        x = find(x);
        y = find(y);

        // 既に同じ木に属しているならマージしない
        if (x == y)
            return;

        // xの木がyの木より大きくなるようにする
        if (sizes[x] < sizes[y])
            swap(x, y);

        // xがyの親になるように連結する
        par[y] = x;
        sizes[x] += sizes[y];
        // sizes[y] = 0;  // sizes[y]は無意味な値となるので0を入れておいてもよい
    }

    // 2つのデータx, yが属する木が同じならtrueを返す
    bool same(int x, int y)
    {
        return find(x) == find(y);
    }

    // データxが含まれる木の大きさを返す
    int size(int x)
    {
        return sizes[find(x)];
    }
};

struct Edge
{
    int a, b, cost;

    bool operator<(const Edge &o) const
    {
        return cost < o.cost;
    }
};

struct Graph
{
    int n;
    vector<Edge> es;

    int kruskal()
    {
        sort(es.begin(), es.end());
        UnionFind uf(n);
        int min_cost = 0;
        for (auto i = 0; i < es.size(); i++)
        {
            Edge& e = es[i];
            if (!uf.same(e.a, e.b))
            {
                min_cost += e.cost;
                uf.unite(e.a, e.b);
            }
        }
        return min_cost;
    }
};

Graph input_graph(){
    Graph g;
    int n;
    cin >> n;
    g.n = n;
    pair<int, int> node[n];
    for (auto i = 0; i < n; i++)
    {
        cin >> node[i].first >> node[i].second;
    }

    for (auto i = 0; i < n - 1; i++)
    {
        for (auto j = i + 1; j < n; j++)
        {
            Edge e;
            e.a = i;
            e.b = j;
            e.cost = min(abs(node[i].first - node[j].first), abs(node[i].second - node[j].second));
            g.es.push_back(e);
        }
    }
    return g;

}

