  cout << fixed << setprecision(20);

  ll n;
  cin >> n;

  vector<P> city;
  rep(i, n) {
    ll x, y;
    cin >> x >> y;
    city.emplace_back(x, y);
  }

  sort(all(city));
  multimap<ll, ll> mp;
  rep(i, n) {
    mp.emplace(city[i].second, i);
  }

  UnionFind uf(n);

  using T = tuple<ll, ll, ll>;
  priority_queue<T, vector<T>, greater<T>> que;
  REP(i, n) {
    que.emplace(city[i].first - city[i - 1].first, i - 1, i);
  }
  auto itr = mp.begin();
  for (;;) {
    auto t = next(itr);
    if (t == mp.end()) {
      break;
    }
    que.emplace(t->first - itr->first, t->second, itr->second);
    itr = t;
  }
  ll ans = 0;
  while (!que.empty()) {
    auto q = que.top();
    que.pop();

    ll cost = get<0>(q);
    ll c1 = get<1>(q);
    ll c2 = get<2>(q);
    if (!uf.is_same(c1, c2)) {
      uf.unite(c1, c2);
      ans += cost;
    }
  }

  cout << ans << endl;

