class UnionFind
{
public:
    explicit UnionFind(int N)
    {
        m_par.reserve(N);
        for (int n = 0; n < N; ++n) {
            m_par.push_back(n);
        }
    }
    int Root(int n)
    {
        if (n == m_par[n]) return n;
        return m_par[n] = Root(m_par[n]);
    }
    void Unite(int n, int m)
    {
        if (Root(n) == Root(m)) return;
        m_par[Root(n)] = Root(m);
    }
    bool Same(int n, int m)
    {
        return Root(n) == Root(m);
    }
private:
    vector<int> m_par;
};

