const ll cmax = 1000000;
ll fac[cmax], finv[cmax], inv[cmax];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (ll i = 2; i < cmax; i++){
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}

// 二項係数計算
ll nCk(ll n, ll k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}
//nのm乗をMODで割ったあまりO(logm)
ll modpow(ll n,ll m,ll MOD){
    if(m == 0)return 1;
    if(m < 0)return -1;
    ll res = 1;
    while(m){
        if(m & 1)res = (res * n) % MOD;
        m >>= 1;
        n *= n;
        n %= MOD;
    }
    return res;
}
ll mypow(ll n,ll m){
    if(m == 0)return 1;
    if(m < 0)return -1;
    ll res = 1;
    while(m){
        if(m & 1)res = (res * n);
        m >>= 1;
        n *= n;
    }
    return res;
}
struct UnionFind{
    vector<ll> par;
    vector<ll> ran;
    vector<ll> siz;
    ll tree_num;

    UnionFind(ll n) : par(n),ran(n,0),siz(n,1){
        rep(i,n){
            tree_num = n;
            par[i] = i;
        }
    }
    ll find(ll x){
        if(x == par[x])return x;
        else return par[x] = find(par[x]);
    }
    void unite(ll x,ll y){
        x = find(x);
        y = find(y);
        if(x == y)return;
        tree_num--;
        if(ran[x] < ran[y]){
            siz[y] += siz[x];
            par[x] = y;
        }
        else{
            siz[x] += siz[y];
            par[y] = x;
            if(ran[x] == ran[y])ran[x]++;
        }
    }
    bool same(ll x,ll y){
        return find(x) == find(y);
    }
    ll get_size(ll x){
        return siz[find(x)];
    }
    ll renketsu_seibun(){
        return tree_num;
    }
};
