// Union-Find Tree(クラスカル法で使う)
class UnionFind{
    private:
        int par_[MAX_N];
        int rank_[MAX_N];
        int groups_;

    public:
        void init(int n){ // initializes the tree 
            for(int i=0; i<n; i++){
                par_[i] = i;
                rank_[i] = 0;
            }
            groups_ = n;
        } 
        int rootOf(int x){ // returns the root of x 
            if(par_[x] == x){
                return x;
            }
            else{
                return par_[x] = rootOf(par_[x]);
            }
        } 
        void unite(int x, int y){ // unites x and y 
            x = rootOf(x);
            y = rootOf(y);
            if(x == y) return;
            if(rank_[x] < rank_[y]){
                par_[x] = y;
                groups_--;
            }
            else{
                par_[y] = x;
                groups_--;
                if(rank_[x] == rank_[y]) rank_[x]++;
            }
        }
        bool isSameGroupe(int x, int y){ // whether x and y are united
            return rootOf(x) == rootOf(y);
        }
        int countGroups(){ // returns the number of groups
            return groups_;
        }
};

int main(void){
    int n;
    cin >> n;
    vector<pair<int,int> > vx;
    vector<pair<int,int> > vy;
    for(int i=0; i<n; i++){
        int x, y;
        cin >> x >> y;
        vx.push_back(make_pair(x, i));
        vy.push_back(make_pair(y, i));
    }
    sort(vx.begin(), vx.end());
    sort(vy.begin(), vy.end());

    vector<edge> es;
    // x 座標で隣り合う点どうしに辺を張る
    for(int i=0; i<n-1; i++){
        edge tmp_e;
        tmp_e.u = vx[i].second;
        tmp_e.v = vx[i+1].second;
        tmp_e.cost = (vx[i+1].first - vx[i].first);
        es.push_back(tmp_e);
    }
    // y 座標で隣り合う点どうしに辺を張る
    for(int i=0; i<n-1; i++){
        edge tmp_e;
        tmp_e.u = vy[i].second;
        tmp_e.v = vy[i+1].second;
        tmp_e.cost = (vy[i+1].first - vy[i].first);
        es.push_back(tmp_e);
    }

    // ここからクラスカル法
    sort(es.begin(), es.end(), comp);
    UnionFind tree; 
    tree.init(n);
    int ans = 0;
    for(int i=0; i<es.size(); i++){
        edge e = es[i];
        if(!tree.isSameGroupe(e.u, e.v)){
            tree.unite(e.u, e.v);
            ans += e.cost;
        }
    }

    cout << ans << endl;
    return 0;
}

