class Unionfind{
public:
	vector<int> par;
	vector<int> size;

	Unionfind(int n){
		par=vector<int>(n);
		size=vector<int>(n,1);
		for(int i=0;i<n;i++) par[i]=i;
	}

	int root(int x){
		if(par[x]==x) return x;
		return par[x]=root(par[x]);
	}

	bool merge(int x,int y){
		x=root(x);
		y=root(y);
		if(par[x]==par[y]) return false;
		if(size[y]>size[x]) swap(x,y);
		par[y]=x;
		size[x]+=size[y];
		return true;
	}
};

