}

void UNION(int a, int b){
    a = FIND(a); b = FIND(b);
    if(a == b) return;
    if(ranks[a] < ranks[b]){
        dsu[a] = b;
    } else if(ranks[b] < ranks[a]){
        dsu[b] = a;
    } else {
        dsu[a] = b;
        ++ranks[b];
    }
}


