class UnionFind {
    public:
        vector<int> rank, p, size;

        UnionFind() {}
        UnionFind(int s) {
            rank.resize(s, 0);
            p.resize(s, 0);
            size.resize(s, 0);
            rep (i, s) init(i);
        }

        void init(int x) {
            p[x] = x;
            rank[x] = 0;
            size[x] = 1;
        }

        bool isSame(int x, int y) {
            return root(x) == root(y);
        }

        void unite(int x, int y) {
            if (isSame(x, y)) return;
            link(root(x), root(y));
        }

        void link(int x, int y) {
            if (rank[x] > rank[y]) {
                p[y] = x;
                size[x] += size[y];
            } else {
                p[x] = y;
                size[y] += size[x];
                if (rank[x] == rank[y]) {
                    rank[y]++;
                }
            }
        }

        int root(int x) {
            if (x != p[x]) {
                p[x] = root(p[x]);
            }
            return p[x];
        }

        int getSize(int x) {
            return size[root(x)];
        }
};

struct edge {
    int source, target, cost;
    edge(int source = 0, int target = 0, int cost = 0): source(source), target(target), cost(cost) {}
    bool operator < (const edge &e) const {
        return cost < e.cost;
    } 
};

int kruskal(int N, vector<edge> edges) {
    int totalCost = 0;
    sort(edges.begin(), edges.end());

    UnionFind uf = UnionFind(N + 1);
    rep (i, N) uf.init(i);

    int source, target;
    rep (i, edges.size()) {
        edge e = edges[i];
        if (!uf.isSame(e.source, e.target)) {
            totalCost += e.cost;
            uf.unite(e.source, e.target);
        }
    }

    return totalCost;
}

