typedef pair<int, int> P;

struct edge{
    int to;
    int len;
};
//s:グラフの頂点数
//1から始める
long prim(vector<edge> G[], bool appended[], int s){
    priority_queue<P, vector<P>, greater<P>> que;
    long ans = 0;
    //init tree
    for(int i = 1; i <= s; i++){
        appended[i] = false;
    }
    appended[1] = true;
    for(int i = 0; i < G[1].size(); i++){
        que.push(P(G[1][i].len, G[1][i].to));
        //cout << G[1][i].len << ' ' << G[1][i].to << endl;
    }

    while(!que.empty()){
        P top = que.top();
        que.pop();
        //cout << top.second << endl;
        if(!appended[top.second]){
            //cout << top.first << ' ' << top.second << endl;
            ans += top.first;
            appended[top.second] = true;

            for(int i = 0; i < G[top.second].size(); i++){
                que.push(P(G[top.second][i].len, G[top.second][i].to));
                //cout << G[top.second][i].len << ' ' <<  G[top.second][i].to << endl;
            }
        }
    }
    return ans;
}

int main(){
    int N;
    //long ans;
    vector<edge> G[N_MAX+1];
    cin >> N;
    P X[N_MAX+1], Y[N_MAX+1];
    bool appended[N_MAX+1];
    for(int i = 1; i <= N; i++){
        int x, y;
        cin >> x >> y;
        X[i] = P(x, i);
        Y[i] = P(y, i);
    }
    sort(X+1, X+N+1);
    sort(Y+1, Y+N+1);
    //init graph
    for(int i = 1; i <= N-1; i++){
        edge edge1, edge2;
        edge1.to = X[i+1].second;
        edge1.len = X[i+1].first - X[i].first;
        edge2.to = Y[i+1].second;
        edge2.len = Y[i+1].first - Y[i].first;
        G[X[i].second].push_back(edge1);
        G[Y[i].second].push_back(edge2);
        //逆の辺
        edge1.to = X[i].second;
        edge1.len = X[i+1].first - X[i].first;
        edge2.to = Y[i].second;
        edge2.len = Y[i+1].first - Y[i].first;
        G[X[i+1].second].push_back(edge1);
        G[Y[i+1].second].push_back(edge2);
    }

    cout << prim(G, appended, N) << endl;
}

