using Graph = vector<vi>;  // vi <=> vl
using P = pair<int, int>;  // int <=> ll
const int MOD = 1e9+7;
const double EPS = 1e-9;

P parent(vi &vec, int v, int depth = 0) {
  if (vec[v] == v) return P(v, depth);
  return parent(vec, vec[v], depth + 1);
}

int main() {
  int N; cin >> N;
  Graph town_x(N, vi(2)), town_y(N, vi(2));
  rep(i,N) {
    cin >> town_x[i][0] >> town_y[i][0];
    town_x[i][1] = town_y[i][1] = i;
  }

  sort(all(town_x));
  sort(all(town_y));

  priority_queue<vi, vector<vi>, greater<vi>> pq;
  rep(i,N-1) {
    vi tmp(3);
    tmp[0] = town_x[i+1][0] - town_x[i][0];
    tmp[1] = town_x[i][1];
    tmp[2] = town_x[i+1][1];
    pq.push(tmp);
  }
  rep(i,N-1) {
    vi tmp(3);
    tmp[0] = town_y[i+1][0] - town_y[i][0];
    tmp[1] = town_y[i][1];
    tmp[2] = town_y[i+1][1];
    pq.push(tmp);
  }

  vi connect(N);
