auto pint_compare = [](pint x, pint y) -> bool{return (x.first < y.first);};

class UnionFind{
    public:
        UnionFind(int N) : parent(N), rank(N){
            for(int i = 0; i < N; i++){
                parent[i] = i;
                rank[i] = 1;
            }
        }

        int find(int n){
            if(parent[n] == n){
                return n;
            }
            return parent[n] = find(parent[n]);
        }

        void merge(int m, int n){
            int root_x = find(m);
            int root_y = find(n);
            if(root_x == root_y){
                return;
            }
            if(rank[root_x] < rank[root_y]){
                parent[root_x] = root_y;
            }else if(rank[root_x] > rank[root_y]){
                parent[root_y] = root_x;
            }else{
                parent[root_y] = root_x;
                rank[root_x]++;
            }
        }

        bool equivalent(int x, int y){
            return find(x) == find(y);
        }

    private:
        vector<int> parent;
        vector<int> rank;

};

struct edge{
    int cost, x, y;
};

int N;
vector<pint> x, y;  //(point, index)
vector<struct edge> es;

ll kruskal(){
    ll ret = 0;
    sort(ALL(es), [](struct edge u, struct edge v) -> bool{return (u.cost < v.cost);});
    UnionFind uf(N);
    for(auto i : es){
        if(!uf.equivalent(i.x, i.y)){
            ret += i.cost;
            uf.merge(i.x, i.y);
        }
    }
    return ret;
}

signed main(){
