        y.push_back(pint(b, i));
    }
    sort(ALL(x));
    sort(ALL(y));
    REP(i, N - 1){
        es.push_back({x[i + 1].first - x[i].first, x[i].second, x[i + 1].second});
        es.push_back({y[i + 1].first - y[i].first, y[i].second, y[i + 1].second});
    }
    PRINT(kruskal());
    return 0;
}

