    for(int i = 0; i < N; i++) par[i] = i;
  }

  int root(int x){
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  bool unite(int x, int y){
    int rx = root(x);
    int ry = root(y);
    if (rx == ry) return false;
    par[rx] = ry;
    return true;
  }

  bool same(int x, int y){
    return par[x] == par[y];
  }
};

struct corridor {
