class Node
{
    public:
        long long id, x, y;
};

bool xsort(Node a, Node b)
{
    return a.x < b.x ? true : false;
}
bool ysort(Node a, Node b)
{
    return a.y < b.y ? true : false;
}

void build_table(vector<Node>& nodes, vector<vector<pair<long long, long long> > >& cost)
{
    vector<Node> sorted(nodes);
    sort(sorted.begin(), sorted.end(), xsort);
    for (auto itr = sorted.begin(); itr != sorted.end(); ++itr) {
        if (itr != sorted.begin())
            cost.at(itr->id).push_back(make_pair(itr->x - (itr - 1)->x, (itr - 1)->id));
        if (itr != sorted.end())
            cost.at(itr->id).push_back(make_pair((itr + 1)->x - itr->x, (itr + 1)->id));
    }
    sort(sorted.begin(), sorted.end(), ysort);
    for (auto itr = sorted.begin(); itr != sorted.end(); ++itr) {
        if (itr != sorted.begin())
            cost.at(itr->id).push_back(make_pair(itr->y - (itr - 1)->y, (itr - 1)->id));
        if (itr != sorted.end())
            cost.at(itr->id).push_back(make_pair((itr + 1)->y - itr->y, (itr + 1)->id));
    }
}

long long prim(vector<vector<pair<long long, long long> > >& cost)
{
    long long sum = 0;
    bool on[cost.size()];
    for (long long i = 0; i < cost.size(); i++) {
        on[i] = false;
    }
    // pair<cost, node>
    priority_queue<pair<long long, long long>, vector<pair<long long, long long> >, greater<pair<long long, long long> > > PQ;
    PQ.push(make_pair(0, 0));
    while (!PQ.empty()) {
        pair<long long, long long> edge = PQ.top();
        PQ.pop();
        if (on[edge.second]) continue;
        on[edge.second] = true;
        sum += edge.first;
        for (auto itr = cost.at(edge.second).begin(); itr != cost.at(edge.second).end(); ++itr) {
            if (on[itr->second]) continue;
            PQ.push(*itr);
        }
    }
    return sum;
}

int main()
{
    long long n;
    cin >> n;

    vector<Node> nodes;
    // pair<cost, dst>
    vector<vector<pair<long long, long long> > > cost(n);
    Node node;
    for (long long i = 0; i < n; i++) {
        node.id = i;
        cin >> node.x >> node.y;
        nodes.push_back(node);
    }
    build_table(nodes, cost);
    return 0;
    cout << prim(cost) << endl;
    return 0;
}

