void init(int n) {//初期化、引数は要素数
	for (int i = 0; i < n; i++) {
		par[i] = i;
		urank[i] = 0;
	}
}

int find(int x) {//木の根の添字
	if (par[x] == x) {
		return x;
	} else {
		return par[x] = find(par[x]);
	}
}

void unite(int x, int y) {//xをyに併合
	x = find(x);
	y = find(y);
	if (x == y) return;
	if (urank[x] < urank[y]) {
		par[x] = y;
	} else {
		par[y] = x;
		if (urank[x] == urank[y]) urank[x]++;
	}
}

bool same(int x, int y) {//同じか判定
	return find(x) == find(y);
}

