int binary_search(int index[],int n,int x){
  int l=0,r=n-1;
  while(r-l>=1){
    int i=(l+r)/2;
    if(index[i] == x)return i;
    else if(index[i]<x)l=i+1;
    else r=i;
  }
  return l;
}

