int n, a, b;
ii x[N], y[N];
priority_queue<vector<int>, vector<vector<int>>, greater<vector<int>>> que;
int root[N];
ll ans;

int findr(int x) {
    if (x == root[x]) return root[x];
    return root[x] = findr(root[x]);
}

bool unionr(int p1, int p2) {
    int r1 = findr(p1);
    int r2 = findr(p2);
    if (r1 == r2) return false;
    root[r1] = r2;
    return true;
}

int main() {
    cin >> n;
    iota(root, root + n, 0);
    for (int i = 0; i < n; ++i) {
        cin >> a >> b;
        x[i] = {a, i};
        y[i] = {b, i};
    }
    sort(x, x + n);
    sort(y, y + n);
    for (int i = 1; i < n; ++i) {
        int d = x[i].first - x[i - 1].first;
        que.push({d, x[i].second, x[i - 1].second});
    }
    for (int i = 1; i < n; ++i) {
        int d = y[i].first - y[i - 1].first;
        que.push({d, y[i].second, y[i - 1].second});
    }
    int cnt = 1;
    while (cnt != n) {
        auto v = que.top();
        que.pop();
        int d = v[0], p1 = v[1], p2 = v[2];
        if (unionr(p1, p2)) {
            ans += d;
            ++cnt;
        }
    }
    cout << ans << endl;
    return 0;
}

