        town[i] = P(x, y);
        mincost[i] = INF;
        used[i] = false;
    }
    REP(i, N){
        REP(j, N - i - 1){
            e[i].push_back(edge{i + j + 1,min(abs(town[i].first - town[i + j + 1].first),abs(town[i].second - town[i + j + 1].second))});
            e[i + j + 1].push_back(edge{i,min(abs(town[i].first - town[i + j + 1].first),abs(town[i].second - town[i + j + 1].second))});
        }
