bool sortID(town a,town b){return a.id <b.id ;}
bool sortE (Edge a,Edge b){return a.wei<b.wei;}

struct disjoint
{
	vector<int> node;
	disjoint(int n)
	{
		node.resize(n);
		For(i,0,n-1) node[i]=i;
	}
	int find(int n)
	{
		if(node[n]==n) return n;
		return node[n]=find(node[n]);
	}
	bool add(int a,int b)
	{
		a=find(a); b=find(b);
		if(a==b) return false;
		node[a]=b;
		return true;
	}
	bool ask(int a,int b)
	{
		return find(a)==find(b);
	}
};

int span(int n,vector<Edge> &edge)
{
	disjoint dis(n);

	int ecnt=0;
	int ans=0;
	for(int i=0;ecnt<n-1;i++)
	{
		Edge &e=edge[i];
		//cout<<i<<"\n";
		if(dis.ask(e.v1,e.v2)) continue;
		else
		{
			dis.add(e.v1,e.v2);
			ans+=e.wei;
			ecnt++;
		}
	}
	return ans;
}

