int main(){
  int N; cin >> N;

  vector < pair < pair<ll, ll>, int> > XY(N), YX(N);

  for (int i = 0; i < N; i++){
    ll X, Y; cin >> X >> Y;
    XY[i].first = make_pair(X, Y); XY[i].second = i;
    YX[i].first = make_pair(Y, X); YX[i].second = i;
  }
  sort(XY.begin(), XY.end());
  sort(YX.begin(), YX.end());

  vector < pair<ll, int> > graph[N];

  for (int i = 0; i < N - 1; i++){
    ll X1 = XY[i].first.first, X2 = XY[i+1].first.first;
    int now = XY[i].second, next = XY[i+1].second;
    graph[now].push_back(make_pair(X2 - X1, next));
    graph[next].push_back(make_pair(X2 - X1, now));

    ll Y1 = YX[i].first.first, Y2 = YX[i+1].first.first;
    now = YX[i].second; next = YX[i+1].second;
    graph[now].push_back(make_pair((Y2 - Y1), next));
    graph[next].push_back(make_pair((Y2 - Y1), now));
  }

  vector <bool> visited(N);
  ll ans = 0;

  priority_queue <pair<ll, int>, vector<pair<ll, int> >, greater<pair<ll, int> > > que;
  que.push(make_pair(0, 0));
  while (!que.empty()){
    pair<ll, int> Q = que.top(); que.pop();

    if (visited[Q.second] == false){
      ans += Q.first;
      visited[Q.second] = true;

      for (int i = 0; i < graph[Q.second].size(); i++){
        pair <ll, int> P = graph[Q.second][i];
        if (visited[P.second] == false){
          que.push(P);
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
}

