using namespace std;

class UnionFind{
public:
    vector<int> belong;
    vector<int> size;

    UnionFind(){

    }

    UnionFind(int n){
        rep(i, n + 1){
            belong.pback(i);
            size.pback(1);
        }
    }

    int find(int a){

        vector<int> fixv;
        while(belong[a] != a){
            fixv.pback(a);
            a = belong[a];
        }

        rep(i, fixv.size()){
            belong[fixv[i]] = a;
        }

        return a;
    }

    bool isSame(int a, int b){

        a = this->find(a);
        b = this->find(b);

        return a == b;
    }

    //sizeをかえす
    int merge(int a, int b){

        a = this->find(a);
        b = this->find(b);

        belong[b] = a;
        int tmp = size[a] + size[b];
        size[a] = tmp;

        return tmp;

    }

};

int main(){

    int n;
    cin >> n;

    map<ll,int> mx;
    map<ll,int> my;

    UnionFind uf(n);

    rep(i,n){
        ll a,b;
        cin >> a >> b;
        int idx = i + 1;

        if(mx.find(a) == mx.end()){
            mx[a] = idx;
        }else{
            uf.merge(mx[a], idx);
        }

        if(my.find(b) == my.end()){
            my[b] = idx;
        }else{
            uf.merge(my[b], idx);
        }

    }

    priority_queue<pair<ll, pair<int,int>>,
                   vector<pair<ll, pair<int,int>>>,
                   greater<pair<ll, pair<int,int>>>> pq;

    for(auto itr = mx.begin(); next(itr) != mx.end(); itr++){

        ll p = (*itr).first;
        ll q = (*(next(itr))).first;

        pq.push(mpair(q - p, mpair(mx[p], mx[q])));
    }

    for(auto itr = my.begin(); next(itr) != my.end(); itr++){

        ll p = (*itr).first;
        ll q = (*(next(itr))).first;

        pq.push(mpair(q - p, mpair(my[p], my[q])));
    }

    ll ans = 0;

    while(!pq.empty()){

        ll len = pq.top().first;
        int a = pq.top().second.first;
        int b = pq.top().second.second;

        if(!uf.isSame(a,b)){

            ans += len;
            int tmp = uf.merge(a,b);
            if(tmp == n) break;

        }

        pq.pop();
    }

    cout << ans << endl;


    return 0;
}

