typedef long long ll;
typedef pair<ll,ll>P;
typedef pair<ll,P>Pi;
ll n,a,b,ans,ra[100000],fa[100000];
vector<P>v1,v2;
priority_queue<Pi,vector<Pi>,greater<Pi>>pque;
ll find(ll x){
    if(x==fa[x])return x;
    return fa[x]=find(fa[x]);
}
void uni(ll x,ll y){
    x=find(x);
    y=find(y);
    if(x==y)return ;
    if(ra[x]<ra[y])swap(x,y);
    fa[y]=x;
    if(ra[x]==ra[y])ra[x]++;
}
int main(void){
    cin>>n;
    vector<vector<Pi>>G(n);
    for(int i=0;i<n;i++)fa[i]=i;
    for(int i=0;i<n;i++){
        cin>>a>>b;
        v1.push_back({a,i});
        v2.push_back({b,i});
    }
    sort(v1.begin(),v1.end());
    sort(v2.begin(),v2.end());
    auto s=v1[0],t=v2[0];
    for(int i=1;i<n;i++){
        auto s1=v1[i],t1=v2[i];
        G[s.S].push_back(Pi(s1.F-s.F,{s.S,s1.S}));
        G[t.S].push_back(Pi(t1.F-t.F,{t.S,t1.S}));
        G[s1.S].push_back(Pi(s1.F-s.F,{s1.S,s.S}));
        G[t1.S].push_back(Pi(t1.F-t.F,{t1.S,t.S}));
        if(s.S==0)pque.push(Pi(s1.F-s.F,{s.S,s1.S}));
        if(s1.S==0)pque.push(Pi(s1.F-s.F,{s1.S,s.S}));
        if(t1.S==0)pque.push(Pi(t1.F-t.F,{t1.S,t.S}));
        if(t.S==0)pque.push(Pi(t1.F-t.F,{t.S,t1.S}));
        s=s1,t=t1;
    }
    while(pque.size()){
        auto p=pque.top();
        pque.pop();
        auto pp=p.S;
        ll p1=p.F,p2=pp.F,p3=pp.S;
        //cout<<p1<<endl;
        if(find(p2)!=find(p3)){
            //cout<<ans<<endl;
            uni(p2,p3);
            ans+=p1;
            for(auto x:G[p3])pque.push(x);
        }
    }
    cout<<ans<<endl;
}

