bool comx(path a,path b){
    if(a.x==b.x) return a.y<b.y;
    else return a.x<b.x;
}

bool comy(path a,path b){
    if(a.y==b.y) return a.x<b.x;
    else return a.y<b.y;
}

vector<pair<ll,int>> T[MAX];
int state[MAX],N;
priority_queue<pair<ll,int>> Q;

ll prim(){
    for(int i=0;i<N;i++){
        state[i]=0;
    }
    for(int i=0;i<T[0].size();i++){
        Q.push(make_pair(-T[0][i].first,T[0][i].second));
    }
    state[0]=1;
    int cnt=1;
    ll ans=0;
    while(Q.size()){
        int a=Q.top().second;
        if(state[a]==0){
            ans+=(-Q.top().first);
            cnt++;
            state[a]=1;
        Q.pop();
        for(int i=0;i<T[a].size();i++){
            int b=T[a][i].second;
            if(state[b]==0){
                Q.push(make_pair(-T[a][i].first,T[a][i].second));
            }
        }
        }
        else Q.pop();
        if(cnt==N) break;
    }
    return ans;
}

