//木の根を求める
int root(int x){
  if(par[x].num==x){
    return x;
  }else{
    return par[x].num=root(par[x].num);//経路圧縮
  }
}
//属する集合の要素数を求める
int size(int x){
  return par[root(x)].size;
}
//x,yが同じ集合に属するか否か
bool same(int x,int y){
  return (root(x)==root(y));
}
//x,yの属する集合を併合
void unite(int x,int y){
  x=root(x);
  y=root(y);
  if(x==y)return;
  par[y].size += par[x].size;
  par[x].num = y;
}
//集合の数を数える
int count(int n){
  set<int> cnt;
  //nは要素数
  rep(i,n){
    cnt.insert(root(i));
  }
  return cnt.size();
