  //ここにやりたい処理を書く
  for(auto i:root->nexts){
    if(pre==i.to){
      continue;
    }
    opera.push_back({i.to,depth+i.length});
  }
  BFS(root);
  return;
}


vector<bool> ness;//その頂点は必要かを考える
void DFS_ness(treev* root,ll depth,treev* pre,ll time,deque<treev*> path){
  //ゴールにちゃんと通じてるか調べる
  deque<treev*> tmppath=path;
  if(ness[root->num]==true||root->num==n-1){
    for(auto i:path){
      ness[i->num]=true;
    }
    //return;
  }

  for(auto i:root->nexts){
    if(ness[i.to->num]==true){
      for(auto i:path){
        ness[i->num]=true;
      }
      break;
    }
    if(ness[root->num]==true){
      return;
    }
    tmppath.pb(i.to);
    DFS_ness(i.to,depth+i.length,root,time + 1,tmppath);
    tmppath.pop_back();
  }
  return;
}
deque<deque<treev*>> loops;
void DFS_loop(treev* root,deque<treev*> path,vector<bool> past){
  //ループを調べる
  //pastの、0がunvisited,1がvisited
  deque<treev*> tmppath=path;
  if(ness[root->num]==true && past[root->num]==true){
    //ループを発見した際の処理
    int mode=0;
    deque<treev*> forrec;
    for(auto i=path.begin();i!=path.end();++i){
      if(mode==0){
        if((*i)->num==root->num){
          mode=1;
          forrec.pb(*i);
        }else{
          forrec.pb(*i);
        }
      }
    }
    loops.pb(forrec);
    return;
  }
  past[root->num]=true;//過去に訪れたことを記録
  for(auto i:root->nexts){
    if(ness[root->num]==false){//その頂点がゴールに通じてない場合
      continue;
    }
    tmppath.pb(i.to);
    DFS_loop(i.to,tmppath,past);
    tmppath.pop_back();
  }
  return;
}

