#define ALL(v) v.begin(), v.end()
using namespace std;
typedef long long ll;
typedef long double ld;
using P = pair<int, int>;

int prim(vector<vector<P>> g)
{
  priority_queue<P, vector<P>, greater<P>> que;
  int total = 0;
  vector<bool> used(g.size(), false);
  que.emplace(0, 0);
  while(!que.empty()){
    P p = que.top();
    que.pop();
    if(used[p.second]) continue;
    used[p.second] = true;
    total += p.first;
    for(auto &v: g[p.second]){
      que.emplace(v.second, v.first);
    }
  }
  return total;
}

int main()
{
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  cin >> n;
  vector<P> px(n), py(n);
  REP(i,n){ 
    cin >> px[i].first >> py[i].first;
    px[i].second = py[i].second = i;
  }

  vector<vector<P>> G(n);
  sort(ALL(px));
  sort(ALL(py));
  REP(i,n-1){
    int costx = px[i+1].first- px[i].first;
    G[px[i].second].emplace_back(px[i+1].second, costx);
    G[px[i+1].second].emplace_back(px[i].second, costx);
