bool less_x(ppii s, ppii t) {
  return s.second.first < t.second.first;
}

bool less_y(ppii s, ppii t) {
  return s.second.second < t.second.second;
}

long long prim() {
  priority_queue<pii, vector<pii>, greater<pii>> q;
  vector<bool> visited(n, false);
  q.push(make_pair(0, 0));
  long long ans = 0;
  while (!q.empty()) {
    auto p = q.top();
    q.pop();
    int cost = p.first, u = p.second;
    if (visited[u]) {
      continue;
    }
    visited[u] = true;
    ans += cost;
    for (auto e: edge[u]) {
      int v = e.first, c = e.second;
      if (visited[v]) {
        continue;
      }
      q.push(make_pair(c, v));
    }
  }
  return ans;
}

