#include <bits/stdc++.h>
#define rep(i, n) for (int i = 0; i < (n); i++)
using namespace std;
using ll = long long;
using pii = pair<int, int>;

struct UnionFind {
	vector<int> par;

	UnionFind(int n) : par(n) {
		for (int i = 0; i < n; i++) par[i] = i;
	}

	int root(int x) {
		return (par[x] == x) ? x : par[x] = root(par[x]);
	}

	bool same(int x, int y) {
		return root(x) == root(y);
	}

	void unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return;
		par[x] = y;
	}
};

struct Edge {
	int from, to, cost;

	bool operator <(Edge const &e) {
		return cost < e.cost;
	}
};

int main() {
	int n;
	cin >> n;
	vector<pii> x(n), y(n);
	rep(i, n) {
		int tx, ty;
		cin >> tx >> ty;
		x[i] = pii{tx, i};
		y[i] = pii{ty, i};
	}
	sort(x.begin(), x.end());
	sort(y.begin(), y.end());
	vector<Edge> e;
	rep(i, n - 1) {
		pii t = x[i];
		pii u = x[i + 1];
		e.push_back(Edge{t.second, u.second, abs(t.first - u.first)});
		t = y[i];
		u = y[i + 1];
		e.push_back(Edge{t.second, u.second, abs(t.first - u.first)});
	}
	sort(e.begin(), e.end());
	UnionFind uf(n);
	ll ans = 0;
	for (auto a : e) {
		if (!uf.same(a.from, a.to)) {
			uf.unite(a.from, a.to);
			ans += a.cost;
		}
	}
	cout << ans << endl;
	return 0;
}

