    if(visited[curr.second]) continue;
    visited[curr.second] = true;
    vCount ++;
    totalCost += curr.first;
    if(vCount == n) break;
    for(int i=0; i<n; i++) {
      if(!visited[i]) {
        pii p = make_pair(dist(curr.second, i), i);

        q.push(p);
      }
    }
  }
  cout << totalCost << endl;
  return 0;
}

