struct UnionFind{
    // 重みなしunionFind
    vector<int> par;
    vector<int> rank;
    UnionFind(int n){
        par = vector<int>(n, -1);
        rank = vector<int>(n, 0);
    }

    int root(int x){
        if(par[x] < 0){
            return x;
        }
        return par[x] = root(par[x]);
    }

    bool isSame(int x, int y){
        return root(x) == root(y);
    }

    bool merge(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y){
            return false;
        }
        if(rank[x] < rank[y]){
            swap(x, y);
        }
        if(rank[x] == rank[y]){
            rank[x] ++;
        }
        par[x] += par[y];
        // par[root]はroot以下のノード数 * -1
        par[y] = x;
        return true;
    }

};

struct edge{
    // edgeをsortして最小辺から処理するのでfromがないとだめ
    int from;
    int to;
    int cost;
    bool operator<(const edge& e) const{
