    }
};

struct Kruskal {
    int v;
    vector<edge> edges;
    Kruskal(int n, vector<edge> es){
        v = n;
        edges = es;
    }

    ll kruskal(){
        UnionFind uf(v);
        sort(edges.begin(), edges.end());

        ll min_cost = 0;

        for(edge e : edges){
            if(! uf.isSame(e.to, e.from)){
                min_cost += e.cost;
                uf.merge(e.to, e.from);
            }
        }
        return min_cost;
    }
};



