        t[i]=town{x,y,i};
    }

    struct edge{ll from,to,len;};
    vector<edge>e;
    auto dist=[](const town&t1,const town&t2){return min(abs(t1.x-t2.x),abs(t1.y-t2.y));};
    sort(ALL(t),[](const town&t1,const town&t2){return t1.x<t2.x;});
    REP(i,n-1)e.push_back(edge{t[i].idx,t[i+1].idx,dist(t[i],t[i+1])});
    sort(ALL(t),[](const town&t1,const town&t2){return t1.y<t2.y;});
    REP(i,n-1)e.push_back(edge{t[i].idx,t[i+1].idx,dist(t[i],t[i+1])});
    sort(ALL(e),[](const edge&e1,const edge&e2){return e1.len<e2.len;});

    ll ans=0;
    union_find uf(n);
    REPC(ei,e){
        if(!uf.is_same(ei.from,ei.to)){
