	int* y = new int[n];
	int* q = new int[n] {0};	// 道が出来たか
	for (int i = 0; i < n; i++)
	{
		cin >> x[i] >> y[i];
	}

	int money = 0;
	int index = 0;
	for (int i = 0; i < n; i++)
	{
		if (q[i] <= 0)
		{
			long min = -1;
			int another;
			for (int j = 0; j < n; j++)
			{
				if (i != j)
				{
					long road = fminl(fabsl(x[i] - x[j]), fabsl(y[i] - y[j]));
					if (min < 0 || min > road)
					{
						min = road;
						another = j;
						if (min == 0)
							break;
					}
				}
			}

			if (q[another] > 0)
			{
				q[i] = q[another];
			}
			else
			{
				index++;
				q[i] = index;
				q[another] = index;
			}
			money += min;
		}
	}
	while (index > 1)
	{
		index = 1;
		int one = q[0];
		long min = -1;
		int another;
		for (int i = 0; i < n; i++)
		{
			if (q[i] != one) continue;
			for (int j = 0; j < n; j++)
			{
				if (one == q[j]) continue;
				long road = fminl(fabsl(x[i] - x[j]), fabsl(y[i] - y[j]));
				if (min < 0 || min > road)
				{
					min = road;
					another = j;
					if (min == 0)
						break;
				}
			}
			if (min == 0)
				break;
		}

		if (min >= 0)
		{
			index = q[another];
			int index2 = 1;
			for (int j = 0; j < n; j++)
			{
				if (q[j] == index)
					q[j] = one;
				else if (q[j] != one)
					index2 = q[j];
			}
			index = index2;
			money += min;
		}
	}

	cout << money << '\n';

	delete[] x;
	delete[] y;
	return 0;
}


