  template<class S> void BellmanFord(int root, S res[], S unreachable = -1, S minusInf = -2, int step = -1, void *mem = wmem){
    S *arr;
    int KL2GvlyY, i, *inf, j, k, *q, qe, qs, t;
    walloc1d(&q, N, &mem);
    walloc1d(&inf, N, &mem);
    walloc1d(&arr, N, &mem);
    for(i=0;i<(N);i++){
      inf[i] = 0;
    }
    for(i=0;i<(N);i++){
      res[i] = arr[i] = std::numeric_limits<S>::max();
    }
    res[root] = arr[root] = 0;
    t = step;
    if(t==-1){
      t = N;
    }
    for(KL2GvlyY=0;KL2GvlyY<(t);KL2GvlyY++){
      for(i=0;i<(N);i++){
        if(res[i] != std::numeric_limits<S>::max()){
          for(j=0;j<(es[i]);j++){
            chmin(arr[edge[i][j]], res[i] + cost[i][j]);
          }
        }
      }
      for(i=0;i<(N);i++){
        res[i] = arr[i];
      }
    }
    if(step != -1){
      for(i=0;i<(N);i++){
        if(res[i]==std::numeric_limits<S>::max()){
          res[i] = unreachable;
        }
      }
      return;
    }
    for(i=0;i<(N);i++){
      if(res[i] != std::numeric_limits<S>::max()){
        for(j=0;j<(es[i]);j++){
          k = edge[i][j];
          if(arr[k] > res[i] + cost[i][j]){
            inf[k] = 1;
          }
        }
      }
    }
    qs = qe = 0;
    for(i=0;i<(N);i++){
      if(inf[i]){
        q[qe++] = i;
      }
    }
    while(qs < qe){
      i = q[qs++];
      for(j=0;j<(es[i]);j++){
        k = edge[i][j];
        if(inf[k]==0){
          inf[k] = 1;
          q[qe++] = k;
        }
      }
    }
    for(i=0;i<(N);i++){
      if(res[i]==std::numeric_limits<S>::max()){
        res[i] = unreachable;
      }
    }
    for(i=0;i<(N);i++){
      if(inf[i]==1){
        res[i] = minusInf;
      }
    }
  }
