    V.at(i) = {x, y, i};
  }
  sort(V.begin(), V.end());
  Kruskal<int> K(N);
  for (int i = 0; i + 1 < N; i++) {
    auto[a, b, c] = V.at(i);
    auto[e, f, g] = V.at(i + 1);
    K.add(c, g, min(abs(a - e), abs(b - f)));
  }
  for (int i = 0; i < N; i++) {
    auto[a, b, c] = V.at(i);
