using namespace std;
typedef pair<long long, long long> p;

long long n;
// x,y, point num
vector<pair<p, int>> v;
// cost, to
vector<p> edge[100005];
// now dis, now point
priority_queue<p, vector<p>, greater<p>> pq;
// bf point, now point, cost(edge list)
map<p, long long> mp;
// mindis, before point
p dis[100005];

long long calccost(int x, int y) {
  return min(
      max(v[x].fi.fi - v[y].fi.fi, v[y].fi.fi - v[x].fi.fi),
      max(v[x].fi.se - v[y].fi.se,
          v[y].fi.se - v[x].fi.se));
}

void setedge();
long long solve();

int main() {
  cin >> n;
  for(int i = 0; i < n; ++i) {
    long long x, y;
    cin >> x >> y;
    v.push_back(make_pair(make_pair(x, y), i));
  }
  setedge();
  cout << solve() << endl;
  return 0;
}

void setedge() {
  sort(v.begin(), v.end());
  for(int i = 1; i < n; ++i) {
    long long now = calccost(i - 1, i);
    edge[v[i].se].push_back(make_pair(now, v[i - 1].se));
    edge[v[i - 1].se].push_back(make_pair(now, v[i].se));
  }
  for(int i = 0; i < n; ++i) swap(v[i].fi.fi, v[i].fi.se);
  sort(v.begin(), v.end());
  for(int i = 1; i < n; ++i) {
    long long now = calccost(i - 1, i);
    edge[v[i].se].push_back(make_pair(now, v[i - 1].se));
    edge[v[i - 1].se].push_back(make_pair(now, v[i].se));
  }
}

long long solve() {
  long long ans = 0;
  for(int i = 1; i < n; ++i) dis[i].fi = inf;
  pq.push(make_pair(0, 0));
  while(pq.size() > 0) {
    p now = pq.top();
    pq.pop();
    for(int i = 0; i < edge[now.se].size(); ++i) {
      p nextp = now;
      nextp.se = edge[now.se][i].se;
      nextp.fi += edge[now.se][i].fi;
      if(dis[nextp.se].fi >= nextp.fi) {
        if(dis[nextp.se].fi > nextp.fi) pq.push(nextp);
        if(dis[nextp.se].fi == nextp.fi &&
           edge[now.se][i].fi >=
               mp[make_pair(nextp.se, dis[nextp.se].se)])
          continue;
        dis[nextp.se].fi = nextp.fi;
        dis[nextp.se].se = now.se;
        mp[make_pair(nextp.se, now.se)] =
            edge[now.se][i].fi;
      }
    }
  }
  for(int i = 1; i < n; ++i)
    ans += mp[make_pair(i, dis[i].se)];
  return ans;
}

