    struct Edge {
        ll from; // 移動前のノード
        ll to; // 移動先のノード
        ll cost; // 辺のコスト
        ll hoge; // 任意変更 いらないかも

        Edge() = default;
        Edge(ll _to) : from(-1), to(_to), cost(1), hoge(-1) {};
        Edge(ll _to, ll _cost) : from(-1), to(_to), cost(_cost), hoge(-1) {};
        Edge(ll _from, ll _to, ll _cost) : from(_from), to(_to), cost(_cost), hoge(-1) {};
        Edge(ll _from, ll _to, ll _cost, ll _hoge) : from(_from), to(_to), cost(_cost), hoge(_hoge) {};
        bool operator< (const Edge& rhs) const {
            return cost < rhs.cost;
        }
        bool operator> (const Edge& rhs) const {
            return cost > rhs.cost;
        }
    };

    using Graph = std::vector<Edge>;

    struct UnionFind {
    private:
        const int n;
        int __size;
        std::vector<int> uf;
    public:
        // 初期化 UnionFind uni(n) のように宣言すれば良い
        UnionFind(int _n) : n(_n), __size(_n), uf(_n, -1) {}
        // find (木の根を求める)
        int find(int x) { return (uf[x] < 0) ? x : uf[x] = find(uf[x]); }
        // x と y が同じ集合に属するかどうか
        bool same(int x, int y) { return find(x) == find(y); }
        // x が属する集合の要素数
        int size(int x) { return -uf[find(x)]; }
        // 集合はいくつあるか
        int size() { return __size; }
        // x と y の属する集合を併合
        bool unite(int x, int y) {
            x = find(x); y = find(y);
            if (x == y) return false;
            __size--;
            if (uf[y] < uf[x]) swap(x, y);
            uf[x] += uf[y]; uf[y] = x;
            return true;
        }
    };

    // 最小全域木を求める firstは最小コスト secondは必要な辺の数
    std::pair<int, int> Kruskal(Graph& G, const int v) {
        // 辺のコストが小さい順に並べる
        std::sort(G.begin(), G.end());
        UnionFind uni(v);

        std::pair<int, int> res;
        for (int i = 0, sz = G.size(); i < sz; ++i) {
            Edge e = G[i];
            // すでに同じグループなら繋げない
            if (uni.same(e.from, e.to)) continue;
            uni.unite(e.from, e.to);
            res.first += e.cost;
            ++res.second;
        }

        return res;
    }

    struct Point {
        int x, y, index;
        Point() = default;
        Point(int x, int y, int index) : x(x), y(y), index(index) {};
    };
}

