int root(int a){
  if(a==par.at(a)){
    return a;
  }
  else{
    return par.at(a)=root(par.at(a));
  }
}
void UN(int a,int b){
  a=root(a);
  b=root(b);
  if(a==b){
    return;
  }
  else if(RA.at(a)<RA.at(b)){
    par.at(a)=b;
  }
  else{
    par.at(b)=a;
  }
  if(RA.at(a)==RA.at(b)){
    RA.at(a)++;
  }
}

