    p.at(i)=make_tuple(a,b,i);
    q.at(i)=make_tuple(b,a,i);
  }
  sort(p.begin(), p.end());
  sort(q.begin(), q.end());
  vector<tuple<int,int,int>> r;
  for(int i=1;i<N;i++){
    int a,b,c,d,e,f;
    tie(a,b,c)=p.at(i-1);
    tie(d,e,f)=p.at(i);
