struct UnionFind{
    vector<long long int> parent;
    vector<long long int> size;
    vector<long long int> rank;

    /* constructor (initialize) */
    UnionFind(long long int n){
        parent.resize(n);
        size.resize(n);
        rank.resize(n);
        for(long long int i=0; i<n; i++){
            parent[i] = i;// completely-disjoint
            size[i] = 1;
            rank[i] = 0;// union by rank
        }
    }

    long long int root(long long int x){
        // terminal case
        if(parent[x] == x){
            return x;// by definition
        }

        // recursion
        parent[x] = root(parent[x]);// path compression : keep tree as shallow as possible
        return parent[x];
    }

    void merge(long long int x, long long int y){
        long long int rx = root(x);
        long long int ry = root(y);

        // if (root(x) == root(y)) do nothing;
        if (rx != ry){
            if(rank[rx] < rank[ry]){
                parent[rx] = ry;// root of merged tree = ry
                size[ry] += size[rx];
            }
            else if(rank[rx] == rank[ry]){
                parent[rx] = ry;
                size[ry] += size[rx];
                rank[ry] += 1;
            }
            else if(rank[rx] > rank[ry]){
                parent[ry] = rx;// root of merged tree = rx
                size[rx] += size[ry];
            }
        }
        return;
    }

    bool same(long long int x, long long int y){
        return root(x) == root(y);
    }

    long long int nodes(long long int x){
        return size[root(x)];
    }
};

