long long int V,E;// number of (vertices, edges)
vector<edge> e(E);

long long int Kruskal(){
    UnionFind tree(V);
    sort(e.begin(), e.end(), compare);// edges sorted by weight-order
    long long int total_cost = 0;
    for (long long int i=0; i<E; i++){// since edges are sorted, less-weight edge comes first!
	    if (tree.same(e[i].u, e[i].v) == false){// if vertices disconnected,
            tree.merge(e[i].u, e[i].v);// then merge them with it
            total_cost += e[i].cost;
	    }
    }
    return total_cost;// minimum weight
}

