	        e[count] = {i, j, min(abs(x[i]-x[j]),abs(y[i]-y[j]))};
            count += 1;
        }
    }

    UnionFind uf(V);
    sort(e.begin(), e.end(), compare);// edges sorted by weight-order
    long long int total_cost = 0;
    for (long long int i=0; i<E; i++){// since edges are sorted, less-weight edge comes first!
	    if (uf.same(e[i].u, e[i].v) == false){// if vertices disconnected,
            uf.merge(e[i].u, e[i].v);// then merge them with it
