ll kruskal()
{
    ll res = 0;
    int xi = 0;
    int yi = 0;
    while (xi < N - 1 && yi < N - 1) {
        edge ex;
        if (xi == N - 1) {
            ex = { 0, 0, INF };
        } else {
            ex = X[xi];
        }
        edge ey;
        if (yi == N - 1) {
            ey = { 0, 0, INF };
        } else {
            ey = Y[yi];
        }
        if (ex.cost < ey.cost) {
            if (!same(ex.from, ex.to)) {
                unite(ex.from, ex.to);
                res += ex.cost;
            }
            xi++;
        } else {
            if (!same(ey.from, ey.to)) {
                unite(ey.from, ey.to);
                res += ey.cost;
            }
            yi++;
        }
    }
    return res;
}

// n要素で初期化
void init(int n)
{
    for (int i = 0; i < n; i++) {
        par[i] = i;
        t_rank[i] = 0;
    }
}

// 木の根を求める
int find(int x)
{
    if (par[x] == x) {
        return x;
    } else {
        return par[x] = find(par[x]);
    }
}

// xとyの属する集合を併合
void unite(int x, int y)
{
    x = find(x);
    y = find(y);
    if (x == y)
        return;

    if (t_rank[x] < t_rank[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (t_rank[x] == t_rank[y])
            t_rank[x]++;
    }
}

// xとyが同じ集合に属するか否か
bool same(int x, int y)
{
    return find(x) == find(y);
}

