        x[i].second = y[i].second = i;
    }

    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    struct Edge {
        int src, dst;
        ll w;
        Edge() {}
        Edge(int _s, int _d, ll _w) : src(_s), dst(_d), w(_w) {}
        bool operator<(const Edge &e) { return w < e.w; }
    };

    vector<Edge> edges;
    for (int i = 1; i < n; ++i)
        edges.emplace_back(Edge(x[i - 1].second, x[i].second,
                                x[i].first - x[i - 1].first));
    for (int i = 1; i < n; ++i)
        edges.emplace_back(Edge(y[i - 1].second, y[i].second,
                                y[i].first - y[i - 1].first));

    ll res = 0;
    UnionFind uf(n);
    sort(edges.begin(), edges.end());
    for (auto e : edges) {
        if (uf.find(e.src, e.dst)) continue;
        res += e.w;
        uf.unite(e.src, e.dst);
    }

    return res;
}

