int main(){
    ll n; cin >> n;
    vector<node> xy(n);
    rep(i,n){
        ll x,y; cin >> x >> y;
        node t(i,x,y);
        xy[i] = t;
    }    
    vector<vector<Pll>> graph(n);
    sort(all(xy),
    [](const auto &a, const auto &b){
        return a.m_x < b.m_x;
    });
    rep(i,n-1){
        node from = xy[i];
        node to = xy[i+1];
        graph[from.m_id].emplace_back(Pll(to.m_id,to.m_x - from.m_x));
        graph[to.m_id].emplace_back(Pll(from.m_id,to.m_x - from.m_x));
    }
    sort(all(xy),
    [](const auto &a, const auto &b){
        return a.m_y < b.m_y;
    });
    rep(i,n-1){
        node from = xy[i];
        node to = xy[i+1];
        graph[from.m_id].emplace_back(Pll(to.m_id,to.m_y - from.m_y));
        graph[to.m_id].emplace_back(Pll(from.m_id,to.m_y - from.m_y));
    }

    // プリム法
    vector<ll> mincost(n,INF);
    bool used[n];
    fill(used, used + n, false);
    mincost[0] = 0;
    ll res = 0;
    ll cnt = 0;
    while(1){
        assert(cnt <= n);
        cnt++;
        ll v = -1;
        rep(u,n){
            if(!used[u]){
                if(v == -1 || mincost[u] < mincost[v])v = u;
            }
        }
        if(v == -1)break;
        used[v] = true;
        res += mincost[v];
        for(auto i : graph[v]){
            ll to = i.first;ll cost = i.second;
            mincost[to] = min(mincost[to], cost);
        }
    }

    cout << res << endl;
}

