    vector<pii> px, py;
    REP(i,N) {
        px.push_back(pii(i, X[i]));
        py.push_back(pii(i, Y[i]));
    }
    sort(px.begin(), px.end(), second_smaller);
    sort(py.begin(), py.end(), second_smaller);

    vector<pair<pii, int>> es;
    REP(i,N-1) {        
        es.push_back(pair<pii,int>(pii(px[i].first, px[i + 1].first), 
            abs(px[i].second-px[i+1].second)));
        es.push_back(pair<pii,int>(pii(py[i].first, py[i + 1].first), 
            abs(py[i].second-py[i+1].second)));
    }

    sort(es.begin(), es.end(),p_second_smaller);

    DSU du(N);
    ll ans = 0;
    for(auto e : es) {
        int u = e.first.first, v = e.first.second;
        if (du.root(u) == du.root(v)) continue;
        du.unite(u, v);
        ll cost = e.second;
        ans += cost;
    }

    cout << ans << endl;

    return 0;
}

