void make_set(int u) {
    p[u] = u;
    h[u] = 0 ;
}
int Find(int u) {
    while(u != p[u]) u = p[u] ;
    return u ;
}
bool Union(int u,int v) {
    int x = Find(u);
    int y = Find(v);
    if(x == y) return false;
    if(h[x] < h[y]) p[x] = y;
    else {
        p[y] = x;
        if(h[x] == h[y]) h[x] ++;
    }
    return true ;
}
