bool edgeComp(const edge& e1, const edge& e2){
    return e1.cost < e2.cost;
}

class UnionFind{
    vector<int> par;
    vector<int> rank;

public:
    UnionFind(){}
    UnionFind(int n): par(n), rank(n){
        REP(i, n){
            par[i] = i;
            rank[i] = 0;
        }
    }

    void resize(int n){
        int m = par.size();
        par.resize(n);
        rank.resize(n, 0);
        FOR(i, m, n) par[i] = i;
    }

    int find(int x){
        if(x == par[x]) return x;
        else return par[x] = find(par[x]);
    }

    void unit(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if(rank[x] == rank[y]) ++rank[x];
        }
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }
};

int kruskal(){
    sort(ALL(G), edgeComp);
    int res = 0;
    UnionFind UF(V);
    for(edge &e: G){
        if(!UF.same(e.from, e.to)){
            UF.unit(e.from, e.to);
            res += e.cost;
        }
    }
    return res;
}

