    vector<edge> edges;
    sort(all(vs), compx);

    int from = -1;
    int to = -1;
    ll pre_x;
    rep(i,n) {
        if (i==0) {
            from = vs[i].idx;
            pre_x = vs[i].x;
            continue;
        }
        to = vs[i].idx;
        edge e;
        e.from = from; e.to = to; e.cost = abs(vs[i].x - pre_x);
        edges.push_back(e);

        pre_x = vs[i].x; from = to;
    }

    ll pre_y;
    sort(all(vs), compy);
    rep(i,n) {
        if (i==0) {
            from = vs[i].idx;
            pre_y = vs[i].y;
            continue;
        }
        to = vs[i].idx;
        edge e;
        e.from = from; e.to = to; e.cost = abs(vs[i].y - pre_y);
        edges.push_back(e
                );
        pre_y = vs[i].y; from = to;
