	while (('0' <= c && c <= '9') || c == '.') {
		if (c == '.') { adp = true; }
		else if (adp) { dp *= 0.1; ret += (c - '0') * dp; }
		else { ret = ret * 10 + (c - '0'); }
		c = getchar_unlocked();
	}
	return neg ? -ret : ret;
