using Weight=LL;
const Weight INF = 1'000'000'000'000'000;
using P=pair<Weight, int>;
struct Edge { int to; Weight cost; };
struct Edge2 { int u, v; Weight cost; };
bool comp(const Edge2& e1, const Edge2& e2) {
	return e1.cost < e2.cost;
}

class UnionFind {
	vector<int> par, sz;
public:
	UnionFind(int n = 1) {
		init(n);
	}
	void init(int n) {
		par.resize(n); sz.resize(n);
		for (int i = 0; i < n; i++)par[i] = i, sz[i] = 1;
	}
	int root(int x) {
		if (par[x] == x)return x;
		else return par[x] = root(par[x]);
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	int size(int x) {
		return sz[root(x)];
	}
	void unite(int x, int y) {
		x = root(x); y = root(y);
		if (x == y)return;
		par[y] = x;
		sz[x] += sz[y];
	}
};


Weight Kruskal(int V, vector<Edge2>& graph) {
	sort(graph.begin(), graph.end(), comp);
	int E = graph.size(); Weight ret = 0;
	UnionFind uf(V);
	for (int i = 0; i < E; i++) {
		Edge2 e = graph[i];
		if (!uf.same(e.u, e.v)) {
			uf.unite(e.u, e.v);
			ret += e.cost;
		}
	}
	return ret;
}

