struct UnionFind {
    int n; // id : 0...n-1
    vector<int> par, rank;

    UnionFind(int n) : n(n), par(n), rank(n) { rep (i,n) par[i] = i, rank[i] = 0; }
    int root(int x) {
        assert(0 <= x && x < n);
        return par[x] == x ? x : par[x] = root(par[x]);
    }
    bool unite(int x, int y) {
        x = root(x), y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) par[x] = y; else par[y] = x;
        if (rank[x] == rank[y]) rank[x]++;
        return true;
    }
    bool same(int x, int y) { return root(x) == root(y); }
};

int32_t main() {
    int n; cin >> n;
    struct town { int id,x,y; };
    vector<town> v(n);
    rep (i,n) {
        int x,y; cin >> x >> y;
        v[i].id = i; v[i].x = x; v[i].y = y;
    }

    pque_min<pair<int, pair<int, int> > > q;
    auto add_edge = [&](town const& s, town const& t) {
        q.push(mp(min(abs(s.x-t.x),abs(s.y-t.y)), mp(s.id, t.id)));
    };

    sort(all(v), [](town const& s, town const& t) { return s.x < t.x; });
    rep (i,n-1) add_edge(v[i],v[i+1]);
    sort(all(v), [](town const& s, town const& t) { return s.y < t.y; });
    rep (i,n-1) add_edge(v[i],v[i+1]);

    UnionFind uf(n);
    int c = 0, sum = 0;
    while (c < n-1) {
        cauto p = q.top(); q.pop();
        int x = p.snd.fst, y = p.snd.snd;
        if (uf.unite(x,y)) {
            c++;
            sum += p.fst;
        }
    }
    cout << sum << endl;

}

