struct UnionFind {
    // 親の番号を入れる配列。根のときはpar[i] = i
    vector<int> par;

    // 初めは空グラフとして初期化
    UnionFind(int N) : par(N){
        for(int i = 0; i < N; i++) par[i] = i;
    }

    // その点を含む成分の根を取り出す
    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    // xとyを同じ成分に入れる
    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        par[rx] = ry;
    }

    // xとyが同じ成分に入っているか判定
    bool same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

