	for (int i = 1; i < N; ++i) {
		cost = x_vec.at(i).first - x_vec.at(i - 1).first;
		src = x_vec.at(i - 1).second;
		dst = x_vec.at(i).second;
		edge.push_back(make_tuple(cost, src, dst));
	}
	for (int i = 1; i < N; ++i) {
		cost = y_vec.at(i).first - y_vec.at(i - 1).first;
		src = y_vec.at(i - 1).second;
		dst = y_vec.at(i).second;
		edge.push_back(make_tuple(cost, src, dst));
	}
	sort(edge.begin(), edge.end());
	UnionFind	uf(N);
	int64_t		total = 0;
	for (auto tpl: edge) {
		tie(cost, src, dst) = tpl;
		if (uf.same(src, dst))
			continue;
		total += cost;
		uf.unite(src, dst);
		if (uf.num_group == 1)
			break;
	}
	cout << total << endl;
}

