template<class Abel> struct UnionFind {
	vector<int> par;
	vector<int> size;
	vector<int> rank;
	vector<Abel> diff_weight;

	UnionFind(int n) {
		init(n);
	}

	void init(int n) {
		par.resize(n);
		size.resize(n);
		rank.resize(n);
		diff_weight.resize(n);
		for (int i = 0; i < n; ++i) {
			par[i] = i;
			size[i] = 1;
			rank[i] = 0;
		}
	}

	int root(int x) {
		if (par[x] == x) {
			return x;
		} else { 
			int r = root(par[x]);
			size[x] = size[r];
			diff_weight[x] += diff_weight[par[x]];
			return par[x] = r;
		}
	}

	int scale(int x){
		return size[root[x]];
	}

	Abel weight(int x) {
		root(x);
		return diff_weight[x];
	} 

	Abel diff(int x, int y) {
		return weight(y) - weight(x);
	} 

	bool issame(int x, int y) {
		return root(x) == root(y);
	}

	bool merge(int x, int y, int w = 0) {
		w += weight(x);
		w -= weight(y);
		x = root(x);
		y = root(y);
		if (x == y) return false;
		if (rank[x] < rank[y]) {
			swap(x,y);
			w = -w;
		}
		if (rank[x] == rank[y]) rank[x]++;
		size[x] += size[y];
		par[y] = x;
		diff_weight[y] = w;
		return true;
	}
};

int n,x[100001],y[100001],a[100001],b[100001];
vector<tuple<int,int,int>> edg;

bool x_cmp(int p,int q){
	return x[p]<x[q];
}

bool y_cmp(int p,int q){
	return y[p]<y[q];
}

bool edg_cmp(tuple<int,int,int> e1,tuple<int,int,int> e2){
	return get<2>(e1)<get<2>(e2);
}

inline void solve(){
	sort(a,a+n,x_cmp);
	sort(b,b+n,y_cmp);
	rep(i,n-1){
		edg.pub(make_tuple(a[i],a[i+1],x[a[i+1]]-x[a[i]]));
		edg.pub(make_tuple(b[i],b[i+1],y[b[i+1]]-y[b[i]]));
	}
	sort(edg.begin(),edg.end(),edg_cmp);
	UnionFind<int> uf(n);
	int ans=0;
	rep(i,edg.size()){
		int v1=get<0>(edg[i]);
		int v2=get<1>(edg[i]);
		if(!uf.issame(v1,v2)){
			uf.merge(v1,v2);
			ans+=get<2>(edg[i]);
		}
	}
	cout<<ans<<endl;
	return;
}

