#define ll long long
static const int MAX = 100010;
static const ll INFTY = 1e18;

struct edge {
    ll to;
    ll cost;
    ll cost_s;
};
using Graph = vector<vector<edge>>;

// <最短距離, 頂点の番号>
using P = pair<ll, ll>;

ll d[MAX];
ll d_s[MAX];
ll _min[MAX];

void dijkstra(const Graph &G, ll N, ll s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d+N, INFTY);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        ll v = p.second;
        if (d[v] < p.first) continue;

        for (ll i=0; i<G[v].size(); ++i) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

void dijkstra_s(const Graph &G, ll N, ll s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d_s, d_s+N, INFTY);
    d_s[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        ll v = p.second;
        if (d_s[v] < p.first) continue;

        for (ll i=0; i<G[v].size(); ++i) {
            edge e = G[v][i];
            if (d_s[e.to] > d_s[v] + e.cost_s) {
                d_s[e.to] = d_s[v] + e.cost_s;
                que.push(P(d_s[e.to], e.to));
            }
        }
    }
}




int main() {

    ll n, m, s, t; cin >> n >> m >> s >> t;
    s--; t--;
    Graph G(n);

    REP(i, m){
        ll u, v, a, b;
        cin >> u >> v>> a>> b;
        u--; v--;
        edge e;
        e = {v, a, b};
        G[u].push_back(e);
        e = {u, a, b};
        G[v].push_back(e);
    }

    dijkstra(G, n, s);
    dijkstra_s(G, n, t);

    ll t_min = INFTY;
    for(int i = n-1; i >=0; i--){
        ll ryogae = d[i] + d_s[i];
        if( t_min > ryogae){
            t_min = ryogae;
        }
        _min[i] = t_min;
    }

    REP(i, n){
        cout << 1000000000000000 - _min[i] << endl;
    }


}
