const u32 MAX_N = 100000;
i32 x[MAX_N], y[MAX_N];
vector<pair<i32, i32>> xs;
vector<pair<i32, i32>> ys;
vector<pair<i32, i32>> e[MAX_N];
bool used[MAX_N];

inline u32 calc(i32 x1, i32 y1, i32 x2, i32 y2) {
    return min(abs(x1-x2), abs(y1-y2));
}

int main() {
    u32 N;
    IN(N);
    REP(i, N) {
        cin >> x[i] >> y[i];
        xs.PB(MP(x[i], i));
        ys.PB(MP(y[i], i));
    }
    sort(ys.begin(), ys.end());
    sort(xs.begin(), xs.end());
    auto q = priority_queue<pair<u32, u32>, vector<pair<u32, u32>>,
         greater<pair<u32, u32>>>();
    used[0] = true;
    u32 ans = 0;
    REP(i, N-1) {
        i32 x1 = xs[i].second;
        i32 x2 = xs[i+1].second;
        u32 cost1 = calc(x[x1], y[x1], x[x2], y[x2]);
        e[x1].PB(MP(cost1, x2));
        e[x2].PB(MP(cost1, x1));

        i32 y1 = ys[i].second;
        i32 y2 = ys[i+1].second;
        u32 cost2 = calc(x[y1], y[y1], x[y2], y[y2]);
        e[y1].PB(MP(cost2, y2));
        e[y2].PB(MP(cost2, y1));
    }
    REP(i, e[0].size()) {
        q.push(e[0][i]);
    }
    while(!q.empty()) {
        auto vi = q.top();
        q.pop();
        auto v = vi.first;
        auto index = vi.second;
        if(used[index]) {
            continue;
        }
        ans += v;
        used[index] = true;

        for(auto a : e[index]) {
            if(used[a.second]) {
                continue;
            }
            q.push(a);
        }
    }
    cout << ans << endl;
    return 0;
}

