using namespace std;
typedef long long ll;
const int Max = 2*1e5+5;
const int mod = 1e9+7;
const int Hash = 10000;
const int INF = 1<<30;
const ll llINF = 1e18;

int n, m;
struct edge
{
    int start, finish, w;
};
struct node
{
    int a,b, index;
};
node in[Max];//点的输入
edge arr[Max];//储存所有的边，在该数组上跑克鲁斯卡尔算法，O(nlogn)
bool cmp1(const node& t1, const node& t2)
{
    return t1.a<t2.a;
}
bool cmp2(const node& t1, const node& t2)
{
    return t1.b<t2.b;
}
bool cmp3(const edge& t1, const edge& t2)
{
    return t1.w<t2.w;
}
int isvisited[Max];
void init( )
{
    for(int i=0; i<Max; i++)
        isvisited[i] = i;
}
int f(int k)
{
    if(k != isvisited[k])
        isvisited[k] = f(isvisited[k]);
    return isvisited[k];
}
int main( )
{
    //freopen("input.txt", "r", stdin);
    while(~scanf("%d", &n))
    {
        for(int i=0; i<n; i++)
        {
            scanf("%d%d", &in[i].a, &in[i].b);
            in[i].index = i;
        }
        //将所有的可能生成树中的边都加到数组arr中
        int cnt = 0;
        sort(in, in+n, cmp1);
        for(int i=0; i<n-1; i++)
            arr[cnt++] = (edge){in[i].index, in[i+1].index, in[i+1].a-in[i].a};
        sort(in, in+n, cmp2);
        for(int i=0; i<n-1; i++)
            arr[cnt++] = (edge){in[i].index, in[i+1].index, in[i+1].b-in[i].b};
        //克鲁斯卡尔
        ll ans = 0;
        init( );
        sort(arr, arr+cnt, cmp3);
        for(int i=0; i<cnt; i++)
        {
            int a = f(arr[i].start);
            int b = f(arr[i].finish);
            if(a == b)
                continue;
            ans += arr[i].w;
            isvisited[a] = b;
        }
        cout<<ans<<endl;
    }
    return 0;
}

