#define REP(i,n) for(long (i)=0;(i)<(n);(i)++)
#define REPI(i,a,b) for(long (i)=(a);(i)<(b);(i)++)
#define INF numeric_limits<double>::infinity()
constexpr long MOD = 1e9 + 7;
using namespace std;
using P = pair<long, long>;
using VI = vector<long>;

int find(int x, VI *par) {
    if (x == (*par)[x]) {
        return x;
    }
    return (*par)[x] = find((*par)[x], par);
}

int same(int x, int y, VI *par) {
    return find(x, par) == find(y, par);
}

void unyon(int x, int y, VI *par) {
    int xr = find(x, par);
    int yr = find(y, par);
    if (xr != yr) (*par)[yr] = xr;
}

int main() {
    int n;
    cin >> n;
    vector<P> xs, ys;
    REP(i,n) {
        long x, y;
        cin >> x >> y;
        x--;
        y--;
        xs.push_back(P(x,i));
        ys.push_back(P(y,i));
    }
    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());

    using T = pair<int, P>;
    vector<T> v;
    REP(i,n-1) {
        v.push_back(T(xs[i+1].first - xs[i].first, P(xs[i+1].second, xs[i].second)));
    }
    REP(i,n-1) {
        v.push_back(T(ys[i+1].first - ys[i].first, P(ys[i+1].second, ys[i].second)));
    }
    sort(v.begin(), v.end());
    int cnt = 0, i = 0;
    long ans = 0;
    VI par(n);
    REP(i,n) par[i] = i;
    while (cnt != n - 1) {
        int xr = v[i].second.first;
        int yr = v[i].second.second;
        if (!same(xr, yr, &par)) {
            unyon(xr, yr, &par);
            ans += v[i].first;
            cnt++;
        }
        i++;
    }
    cout << ans << endl;
}

