struct UnionFind{
    vl par;
    vl rank;
    map<ll, ll> size;
    UnionFind(ll N) : par(N, 0), rank(N, 0){
        for(int i = 0; i < N; i++){
            par[i] = i; size[i] = 1;
        }
    }

    ll root(ll x){
        if(par[x] == x) return x;
        else{
            par[x] = root(par[x]); // compression
            return par[x];
        }
    }

    void unite(ll x, ll y){
        ll rx = root(x); ll ry = root(y);
        if(rx == ry) return;
        if(rank[rx] < rank[ry]) swap(rx, ry);
        if(rank[rx] == rank[ry]) ++rank[rx];
        par[ry] = rx;
        if(rx != ry) size[rx] = size[rx] + size[ry];
        else{
            size[rx] = max(size[rx], size[ry]);
        }
    }

    ll get_size(ll x){
        return size[root(x)];
    }

    bool same(ll x, ll y){
        return root(x) == root(y);
    }
};

int main(){
    ll N; cin >> N;
    vpl xp(N), yp(N);
    REP(i, N){
        ll x, y; cin >> x >> y;
        xp[i] = PL(x,i); yp[i] = PL(y,i);
    }
    sort(xp.begin(), xp.end());
    sort(yp.begin(), yp.end());
    map<ll, vpl> m;
    REP(i, N-1){
        ll dx = xp[i+1].ff - xp[i].ff;
        m[dx].pb({xp[i].ss, xp[i+1].ss});
        ll dy = yp[i+1].ff - yp[i].ff;
        m[dy].pb({yp[i].ss, yp[i+1].ss});
    }

    ll ans = 0;
    UnionFind uf(N);
    FORMAP(it, m){
        ll d = it->ff;
        for(auto& p : it->ss){
            ll x = p.ff, y = p.ss;
            if(uf.same(x, y)) continue;
            ans += d;
            uf.unite(x, y);
            if(uf.get_size(x) == N){
                cout << ans << endl; return 0;
            }
        }
    }
    return 0;
}

