template <typename T>
T Kruskal(int V, vector<edge<T>>& es) {
    sort(es.begin(), es.end());  // reverseすると最大全域木
    UnionFind uf(V);
    T res = 0;
    for (edge<T> e : es) {
        if (!uf.same(e.from, e.to)) {
            uf.unite(e.from, e.to);
            res += e.cost;
        }
    }
    return res;
}

