int kruskal(int V, int E, edge* es)
{
	sort(es, es + E, comp);
	UnionFind uf(V);

	int res = 0;
	for (int i = 0; i < E; i++)
	{
		edge e = es[i];
		if (!uf.same(e.u, e.v))
		{
			uf.unite(e.u, e.v);
			res += e.cost;
		}
	}

	return res;
}

