const int MOD = 1e9 + 7;


struct UnionFind {
    UnionFind(int n) :parent(n), rank(n, 0), nums(n, 1), groupnum(n) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int a) {
        return parent[a] == a ? a : (parent[a] = find(parent[a]));
    }
    bool same(int a, int b) {
        return find(a) == find(b);
    }
    void unite(int a, int b) {
        a = find(a), b = find(b);
        if (a == b)
            return;
        groupnum--;
        if (rank[a] < rank[b]) {
            parent[a] = b;
            nums[b] += nums[a];
        }
        else {
            parent[b] = a;
            nums[a] += nums[b];
            if (rank[a] == rank[b])
                rank[a]++;
        }
    }
    int group_count() {
        return groupnum;
    }
    int get_group_size(int i) {
        return nums[find(i)];
    }
    vector<int> parent;
    vector<int> rank;
    vector<int> nums;
    int groupnum;
};

