    int from;
    int to;
    int cost;
};
bool pred(const Edge &lhs, const Edge &rhs) {
    return lhs.cost > rhs.cost;
}

int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> x(n), y(n);
    rep(i, 0, n) {
        cin >> x[i].first >> y[i].first;
        x[i].second = y[i].second = i;
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    priority_queue<Edge, vector<Edge>, decltype(&pred)> edges(pred);

    rep(i, 0, n-1) {
        edges.push({ x[i + 1].second, x[i].second, x[i + 1].first - x[i].first });
        edges.push({ y[i + 1].second, y[i].second, y[i + 1].first - y[i].first });
    }
    UnionFind uf(n);
    long long now = 0;
    int cnt = 0;
    while(cnt < n-1) {
        auto t = edges.top();
        edges.pop();
        if (uf.same(t.from, t.to))
            continue;

        uf.unite(t.from, t.to);
        now += t.cost;
        cnt++;
    }

    cout << now << endl;


    return 0;
}

