	//辺張り終了
	UF u=UF(n);//ufの初期化
	//最小全域木
	while(u.getsize(0)<n)
	{
		Edge e=que.top();
		que.pop();
		cerr<<u.getsize(0)<<" "<<e.from<<"<->"<<e.to<<" "<<e.cost<<endl;
		if(!u.same(e.from,e.to))
		{
			ans+=e.cost;
			//cerr<<ans<<endl;
			u.unite(e.from,e.to);
		}
	}
	cout<<ans<<endl;
}

