struct UnionFind {
  vll rank, par, data;

  void set(ll n) {
	rank.resize(n + 1, 0);
	par.resize(n + 1, 0);
	data.resize(n + 1, 1);
	REP(i, n + 1) par[i] = i;
  }

  ll root(ll x) {
	if (x != par[x]) par[x] = root(par[x]);
	return par[x];
  }

  ll size(ll x) {
	return data[root(x)];
  }

  void unite(ll a, ll b) {
	ll x = root(a);
	ll y = root(b);
	if (x == y) return;
	if (rank[x] > rank[y]) {
	  par[y] = x;
	  data[x] += data[y];
	}
	else {
	  par[x] = y;
	  data[y] += data[x];
	  if (rank[x] == rank[y]) rank[y]++;
	}
  }

  bool same(ll a, ll b) {
	return root(a) == root(b);
  }
};

struct edge {
  ll cost;
  pll node;
  edge(ll c, pll n) : cost(c), node(n) {}
  bool operator>(const edge &e) const {
	return cost > e.cost;
  }
};

