		xi[i]=pii(x,i);
		yi[i]=pii(y,i);
	}
	sort(ALL(xi)), sort(ALL(yi));

	using type=tuple<int,int,int>;
	priority_queue<type,vector<type >,greater<type > > pque;
	REP(i,n-1){
		int x,xx,p,pp;
		tie(x,p)=xi[i], tie(xx,pp)=xi[i+1];
		pque.push(type(xx-x,p,pp));
	}
	REP(i,n-1){
		int y,yy,p,pp;
		tie(y,p)=yi[i], tie(yy,pp)=yi[i+1];
		pque.push(type(yy-y,p,pp));
	}

	llong ans=0LL;
	UnionFind tree(n);
	while(!pque.empty()){
		int cost,u,v;
		tie(cost,u,v)=pque.top();
		pque.pop();

		if(!tree.same(u,v)){
			ans+=cost;
			tree.unite(u,v);
		}
	}

	cout<<ans<<endl;
	return 0;
}

