    for(int i=0; i<n; i++){
        link[i] = i;
        sizex[i] = 1;
    }
    sort(all(x));
    sort(all(y));
    for(int i=0; i+1<n; i++){
        edges.pb(make_pair(x[i+1].first-x[i].first, make_pair(x[i].second, x[i+1].second)));
        edges.pb(make_pair(y[i+1].first-y[i].first, make_pair(y[i].second, y[i+1].second)));
    }
    sort(all(edges));
    int ans = 0;
    for(pair<int, pii> i:edges){
        if(!same(i.second.first, i.second.second)){
            unite(i.second.first, i.second.second);
            ans += i.first;
        }
    }
    cout << ans << endl;
}

