    for(int i = 0; i < n; ++i){
        int x, y;
        cin >> x >> y;
        xorder[i] = P(x, i);
        yorder[i] = P(y, i);
    }
    sort(xorder.begin(), xorder.end());
    sort(yorder.begin(), yorder.end());
    vector<Edge> es;
    for(int i = 0; i + 1 < n; ++i){
        int u = xorder[i].second, v = xorder[i + 1].second;
        int64_t costu = xorder[i].first, costv = xorder[i + 1].first;
        es.push_back(Edge(u, v, costv - costu));
        u = yorder[i].second, v = yorder[i + 1].second;
        costu = yorder[i].first, costv = yorder[i + 1].first;
        es.push_back(Edge(u, v, costv - costu));
    }
    int64_t ans = Kruskal(es);
    cout << ans << endl;
}

