	cin >> n;
	REP(i, n){
		cin >> x[i] >> y[i];
	}

	REP(i, n){
		REP(j, n){
			M[i][j] = min(abs(x[i] - x[j]), abs(y[i] - y[j]));
		}
	}

	cout << prim(n) << endl;
}

