VI par;

int root(int x) {
    if(par[x] == x) return x;
    else return root(par[x]);
}

void unite(int x, int y) {
    int rx = root(x), ry = root(y);
    if(rx == ry) return;
    par[rx] = ry;
}

bool same(int x, int y) {
    int rx = root(x), ry = root(y);
    return rx == ry;
}

