        v[i].x = x;
        v[i].y = y;
        v[i].i = i;
    }
    auto cmp1 = [](node a, node b) {
        return a.x < b.x;
    };
    auto cmp2 = [](node a, node b) {
        return a.y < b.y;
    };
    sort(ALL(v), cmp1);
    vector<edge> e;
    FOR(i, 1, n) {
        edge tmp;
        tmp.u = v[i-1].i;
        tmp.v = v[i].i;
        tmp.cost = min(abs(v[i].x - v[i-1].x), abs(v[i].y - v[i-1].y));
        e.push_back(tmp);
    }
    sort(ALL(v), cmp2);
    FOR(i, 1, n) {
        edge tmp;
        tmp.u = v[i-1].i;
        tmp.v = v[i].i;
