    }
};


int parent[100004];
int length[100004];
int num[100004];

void init(){
  for (int i=0; i<100004; i++) {
    parent[i] = i;
    length[i] = 1;
    num[i] = 1;
    //printf("num[%d]=%d\n", i, num[i]);
  }
  return;
}

int getroot(int n) {
  if (n==parent[n]) return n;
  int orig = n;
  while(n!=parent[n]) {
    n = parent[n];
  }
  parent[orig] = n;
  return n;
}

bool samegroup(int n, int m) {
  int nroot = getroot(n);
  int mroot = getroot(m);
  return nroot==mroot;
}

void unite(int n, int m) {
  if (samegroup(n, m)) return;
  int nroot = getroot(n);
  int mroot = getroot(m);
  parent[mroot] = nroot;
  num[nroot] += num[mroot];
  return;
}

int main(){
  int N;
  std::cin >> N;
  int x, y;
  init();
  std::vector<point> data;
  for (int i=0; i<N; i++) {
    std::cin >> x >> y;
    data.push_back((point){i, x, y});
  }
  //printf("read end\n");
  //printf("num0=%d\n", getroot(0));
  // X
  std::sort(data.begin(), data.end(), CompareX);
  std::priority_queue<edge, std::vector<edge >, CompareFirst > queue;
  for (int i=0; i<N-1; i++) {
    //printf("x[%d] = %d\n", i, data[i].x);
    int diff = data[i+1].x - data[i].x;
    if (diff == 0) {
      unite(data[i+1].i, data[i].i);
    } else {
      queue.push((edge){data[i+1].i, data[i].i, diff});
      //printf("pushing(%d, %d) dist=%d\n", data[i+1].i, data[i].i, diff);
    }
  }

  // Y
  std::sort(data.begin(), data.end(), CompareY);
  for (int i=0; i<N-1; i++) {
    int diff = data[i+1].y - data[i].y;
    if (diff == 0) {
      unite(data[i+1].i, data[i].i);
    } else {
      queue.push((edge){data[i+1].i, data[i].i, diff});
      //printf("pushing(%d, %d) dist=%d\n", data[i+1].i, data[i].i, diff);
    }
  }

  // unite
  int num0 = num[getroot(0)];
  long long sum = 0;
  while(num0 < N) {
    auto entry = queue.top();
    queue.pop();
    int i = entry.i1;
    int j = entry.i2;
    int d = entry.dist;
    if (samegroup(i, j)) continue;
    sum += d;
    //printf("d=%d, unite (%d, %d)\n", d, i, j);
    unite(i, j);
    num0 = num[getroot(0)];
    //printf("num0=%d\n", num0);
  }
  std::cout << sum << std::endl;
  return 0;
}

