    for(ll i=0;i<N;i++){
        cin>>x[i]>>y[i];
        xsort[i]=P(x[i],i);
        ysort[i]=P(y[i],i);
    ;}
    sort(xsort.begin(), xsort.end());
    sort(ysort.begin(), ysort.end());
    priority_queue<T, vector<T>, greater<T>> pq;
    for(ll i=0;i<N-1;i++){
        pq.push(T(xsort[i+1].first-xsort[i].first,xsort[i].second,xsort[i+1].second));
        pq.push(T(ysort[i+1].first-ysort[i].first,ysort[i].second,ysort[i+1].second));
    ;}
    UnionFind tree(N);
    ll k=pq.size();
    for(ll i=0;i<k;i++){
        T j=pq.top();
        pq.pop();
        if(!tree.same(get<1>(j),get<2>(j))){
            ans+=get<0>(j);
            tree.unite(get<1>(j),get<2>(j));
        }
    ;}
    cout<<ans<<endl;


return 0;
