struct UnionFind{
    vector<int> par;

    UnionFind(int n) : par(n,-1) { }
    void init(int n) { par.assign(n,-1); }

    int root(int x){
        if(par[x]<0) return x;
        else return par[x]=root(par[x]);
    }

    bool issame(int x,int y){
        return root(x)==root(y);
    }

    bool merge(int x,int y){
        x=root(x);
        y=root(y);
        if(x==y) return false;
        if(par[x]>par[y]) swap(x,y);
        par[x]+=par[y];
        par[y]=x;
        return true;
    }

    int size(int x){
        return -par[root(x)];
    }
};

int main(){
    int N;
    cin>>N;
    vector<pair<int,int>> x,y;
    rep(i,N){
        int a,b;
        cin>>a>>b;
        x.push_back({a,i});
        y.push_back({b,i});
    }

    sort(all(x));
    sort(all(y));
    // Kruskal 法で使用する枝
    using pint = pair<int,int>;
    using Edge = pair<ll, pint>;
    vector<Edge> edges;
    //枝入力
    rep(i,N-1){
        int u=x[i].second;
        int v=x[i+1].second;
        ll c=x[i+1].first-x[i].first;
        edges.push_back({c, pint(u, v)});
    }
    rep(i,N-1){
        int u=y[i].second;
        int v=y[i+1].second;
        ll c=y[i+1].first-y[i].first;
        edges.push_back({c, pint(u, v)});
    }

    // Kruskal 法
    sort(all(edges));
    // unionfindのスニペット読み込んで
    UnionFind uf(N);
    ll res = 0;
    for (auto e : edges) {
        int u = e.second.first, v = e.second.second;
        ll cost = e.first;
        if (uf.issame(u, v)) continue;
        uf.merge(u, v);
        res += cost;
    }
    cout << res << endl;

}

