			if(c[s]!=BLACK){
				if(d[s]>t){
					d[s]=t;
					c[s]=GRAY;
				}
			}
		}
	}
	ll sum=0;
	for(int i=0; i<n; i++){
		sum+=d[i];
	}
	return sum;
}

