#define N 100001

int parent[N];
int visited[N];
ll num[N];
vector<vector<int>> edge(N, vector<int>(0));
int findroot(int a){
  if (parent[a] == a)
    return a;

  int newparent = findroot(parent[a]);
  parent[a] = newparent;
  return newparent;
}

void init(){
  for (int i = 0; i < N; i++){
    parent[i] = i;
    num[i] = 1;
  }
}

