    x[i].second = i;
    y[i].second = i;
  }

  sort(x.begin(), x.end());
  sort(y.begin(), y.end());

  priority_queue<pair<ll, pair<int, int>>, vector<pair<ll, pair<int, int>>>, greater<pair<ll, pair<int, int>>>> Q;
  for (int i = 0; i < n - 1; i++){
    Q.push(make_pair(x[i+1].first-x[i].first, make_pair(x[i+1].second, x[i].second)));
    Q.push(make_pair(y[i+1].first-y[i].first, make_pair(y[i+1].second, y[i].second)));
  }
