class DisjointSet
{
  private:
    vector<int> p;

  public:
    DisjointSet(int size) : p(size, -1) {}

    bool unite_set(int x, int y)
    {
	x = root(x);
	y = root(y);

	if (x != y)
	{
	    if (x > y)
	    {
		swap(x, y);
	    }
	    p[x] += p[y];
	    p[y] = x;
	}

	return x != y;
    }

  private:
  	void swap(int x,int y){
		  int temp = p[x];
		  p[x] = p[y];
		  p[y] = temp;
	  }
    int root(int x)
    {
	return p[x] < 0 ? x : p[x] = root(p[x]);
    }
};

