struct corridor
{
    int a, b; // 繋がっているcell
    int len;  // 通路の長さ
    corridor(int a, int b, int len) : a(a), b(b), len(len) {}

    // ソート用
    bool operator<(const corridor &rhs) const
    {
	if (len != rhs.len)
	{
	    return len < rhs.len;
	}
	if (a != rhs.a)
	{
	    return a < rhs.a;
	}
	return b < rhs.b;
    }
};

