  return a.cost < b.cost;
}

int par[MAXN];
int rank_[MAXN];
int size[MAXN];

void init() {
    for (int i=0;i<n;i++) {
      par[i] = i;
      rank_[i] = 0;
      size[i] = 1;
    }
}

int find(int x) {
  if (par[x] == x) {
    return x;
  } else {
    return par[x] = find(par[x]);
  }
}

bool same(int x, int y) {
  return find(x) == find(y);
}

void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if (x == y) {
    return;
  }

  if (rank_[x] < rank_[y]) {
    par[x] = y;
    size[y] += size[x];
  } else {
    par[y] = x;
    if (rank_[x] == rank_[y]) {
      rank_[x]++;
    }
    size[x] += size[y];
  }
}


