#include <bits/stdc++.h>
#define rep(i,n) for (int i = 0; i < (n); ++i)
using namespace std;
typedef long long ll;
typedef tuple<int,int,int> T;

class UnionFind {
public:
    vector <ll> par; // 各元の親を表す配列
    vector <ll> siz; // 素集合のサイズを表す配列(1 で初期化)

    // Constructor
    UnionFind(ll n){
    	rep(i,n){
    		par.push_back(i); // 初期では親は自分自身
    		siz.push_back(1);
    	}
    }

    // Member Function
    // Find
    ll root(ll x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }

    // Union(Unite, Merge)
    bool merge(ll x, ll y) {
        ll rx = root(x);
        ll ry = root(y);
        if (rx == ry) return false;
        // merge technique（データ構造をマージするテク．小を大にくっつける）
        if (siz[rx] < siz[ry]) swap(rx, ry);
        siz[rx] += siz[ry];
        par[ry] = rx;
        return true;
    }

    bool issame(ll x, ll y) { // 連結判定
        return root(x) == root(y);
    }

    ll size(ll x) { // 素集合のサイズ
        return siz[root(x)];
    }

};


struct edge{
	int a,b,cost;

	bool operator<(const edge& o) const{
		return cost < o.cost;
	}
};
// クラスカル法
// nは頂点数
ll kruskal(vector<edge> es, int n){
	sort(es.begin(), es.end());
	UnionFind uf(n);
	ll res = 0;

	rep(i, es.size()){
		edge& e = es[i];
		if(!uf.issame(e.a, e.b)){
			res += e.cost;
			uf.merge(e.a, e.b);
		}
	}
	return res;
}


bool compbya(const T &left, const T &right){
	return get<0>(left) < get<0>(right);
}
bool compbyb(const T &left, const T &right){
	return get<1>(left) < get<1>(right);
}

