		int dist = abs(get<0>(inputs[i]) - get<0>(inputs[i+1]));
		es.push_back(edge{get<2>(inputs[i]), get<2>(inputs[i+1]), dist});
	}

	sort(inputs.begin(), inputs.end(), compbyb);
