typedef pair<int, int> P;

class Unionfind
{
    int root[100002], rank[100002];

public:
    Unionfind(int n){
        for(int i = 0; i < n; i++){
            root[i] = i;
            rank[i] = 0;
        }
    }

    int find(int i){
        if(root[i] == i) return i;
        return root[i] = find(root[i]);
    }

    bool same(int i, int j){
        return find(i) == find(j);
    }

    void unite(int i, int j){
        if(same(i, j)) return;
        if(rank[i] < rank[j]) root[i] = j;
        else{
            root[j] = i;
            if(rank[i] == rank[j]) rank[i]++;
        }
    }
};

int main()
{
    int n;
    cin >> n;
    int x[100002], y[100002];
    P px[100002], py[100002];
    for(int i = 0; i < n; i++){
        cin >> x[i] >> y[i];
        px[i] = P(x[i], i);
        py[i] = P(y[i], i);
    }
    sort(px, px + n);
    sort(py, py + n);
    vector<P> v[100002];
    for(int i = 1; i < n; i++){
        v[px[i - 1].second].push_back(P(px[i].first - px[i - 1].first, px[i].second));
        v[px[i].second].push_back(P(px[i].first - px[i - 1].first, px[i - 1].second));
    }
    for(int i = 1; i < n; i++){
        v[py[i - 1].second].push_back(P(py[i].first - py[i - 1].first, py[i].second));
        v[py[i].second].push_back(P(py[i].first - py[i - 1].first, py[i - 1].second));
    }
    priority_queue<P, vector<P>, greater<P>> que;
    bool used[100002];
    fill(used, used + n, false);
    int l = v[0].size();
    for(int i = 0; i < l; i++){
        que.push(v[0][i]);
    }
    int ans = 0;
    used[0] = true;
    while(que.size()){
        P now = que.top();
        que.pop();
        if(!used[now.second]){
            used[now.second] = true;
            ans += now.first;
            l = v[now.second].size();
            for(int i = 0; i < l; i++){
                P next = v[now.second][i];
                if(!used[next.second]) que.push(next);
            }
        }
    }
    cout << ans << endl;
}

