struct UnionFind {
  vector<int> par;

  // Constructor
  UnionFind(int n): par(n) {
    for(int i = 0; i < n; i++) par[i] = i;
  }

  // n要素で初期化
  void init(int n) {
    par.resize(n);
    for(int i = 0; i < n; i++) par[i] = i;
  }

  // 根の検索
  int find(int x) {
    if(par[x] == x) return x;
    else return par[x] = find(par[x]);
  }

  // xとyの属する集合を併合
  bool unite(int x, int y) {
    x = find(x);
    y = find(y);
    if(x == y) return false;
    par[x] = y;
    return true;
  }

  // xとyが同じ集合に属するか
  bool same(int x, int y) {
    return find(x) == find(y);
  }
};

static const ll MAX = 1e5 + 1;

// クラスカル法(Union-Findと同時に使う) O(|E|log|E|)
vector<pair<ll, ll>> G[MAX];
// main関数からこれらを削除すること

ll kruskal(int n) { // n:頂点数
  vector<tuple<int, int, int>> x;
  for(int i = 0; i < n; i++){
    for(int j = 0; j < G[i].size(); j++){
      x.emplace_back(make_tuple(G[i][j].second, i, G[i][j].first));
    }
  }

  sort(x.begin(), x.end()); // 辺の重みでソート

  UnionFind uf(n);

  int totalCost = 0;
  // vector<tuple<int, int, int>> MST; // 最小全域木
  for(int i = 0; i < x.size(); i++){
    if(!uf.same(get<1>(x.at(i)), get<2>(x.at(i)))){
      totalCost += get<0>(x.at(i));
      // MST.emplace_back(make_tuple(get<1>(x.at(i)), get<2>(x.at(i)), get<0>(x.at(i))));
      uf.unite(get<1>(x.at(i)), get<2>(x.at(i)));
    }
  }
  return totalCost;
  // return MST;
}

