const int MAX = 1e5 + 5;
const int INF = 1001001001;
const int MOD = 1e9 + 7;

class UnionFindTree{
    private:
        vector<int> par, rank;

    public:
        UnionFindTree(int n) {
            par = rank = vector<int>(n);

            for (int i = 0; i < n; ++i) {
                par[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (par[x] == x) {
                return x;
            } else {
                return par[x] = find(par[x]);
            }
        }

        void unite(int x, int y) {
            x = find(x);
            y = find(y);
            if (x == y) return;

            if (rank[x] < rank[y]) {
                par[x] = y;
            } else {
                par[y] = x;
                if (rank[x] == rank[y]) rank[x]++;
            }
        }

        bool same(int x, int y) {
            return find(x) == find(y);
        }
};

struct Edge
{
    int from, to, cost;

    Edge(int f, int t, int c) {
        from = f;
        to = t;
        cost = c;
    }

    bool operator <(const Edge& e) const {
        return cost < e.cost;
    }

    bool operator >(const Edge& e) const {
        return cost > e.cost;
    }
};

struct Town
{
    int id, x, y;

    Town() {}

    Town(int a, int b, int c) {
        id = a, x = b, y = c;
    }
};


int main(){
    int N;
    cin >> N;

    vector<Town> T(N);
    rep(i, N) {
        int x, y;
        cin >> x >> y;
        T[i] = Town(i, x, y);
    }

    priority_queue<Edge, vector<Edge>, greater<Edge>> q;

    sort(T.begin(), T.end(), [](Town a, Town b){ return (a.x < b.x) || (a.x == b.x && a.y < b.y); });

    rep(i, N - 1) {
        Town a = T[i], b = T[i + 1];
        Edge e = Edge(a.id, b.id, b.x - a.x);
        q.push(e);
    }

    sort(T.begin(), T.end(), [](Town a, Town b){ return (a.y < b.y) || (a.y == b.y && a.x < b.x); });

    rep(i, N - 1) {
        Town a = T[i], b = T[i + 1];
        q.push(Edge(a.id, b.id, b.y - a.y));
    }

    UnionFindTree uf = UnionFindTree(N);
    int ans = 0;
    while (!q.empty()) {
        Edge e = q.top(); q.pop();
        int a = e.from, b = e.to;
        if (!uf.same(a, b)) {
            ans += e.cost;
            uf.unite(a, b);
        }
    }

    cout << ans << endl;
}

