            parent[x] = y;
        }
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return (parent[x] == x ? x : parent[x] = root(parent[x]));
    }
};

int main() {
    int N;
    cin >> N;

    struct Point {
        int x, y, index;
    };

    vector<Point> points_sorted_by_x(N), points_sorted_by_y(N);
    for (int i = 0; i < N; i++) {
        int x, y;
