        points_sorted_by_x[i].x = points_sorted_by_y[i].x = x;
        points_sorted_by_x[i].y = points_sorted_by_y[i].y = y;
        points_sorted_by_x[i].index = points_sorted_by_y[i].index = i;
    }

    sort(points_sorted_by_x.begin(), points_sorted_by_x.end(), [&](Point& lhs, Point& rhs){
        return (lhs.x != rhs.x ? lhs.x < rhs.x : lhs.y < rhs.y);
    });
    sort(points_sorted_by_y.begin(), points_sorted_by_y.end(), [&](Point& lhs, Point& rhs) {
        return (lhs.y != rhs.y ? lhs.y < rhs.y : lhs.x < rhs.x);
    });

    struct Edge {
        int index1, index2, cost;
    };

    vector<Edge> edges;
    for (int i = 0; i < N - 1; i++) {
        Edge tmp;
        tmp.index1 = points_sorted_by_x[i].index;
        tmp.index2 = points_sorted_by_x[i + 1].index;
        tmp.cost = min(abs(points_sorted_by_x[i].x - points_sorted_by_x[i + 1].x),
            abs(points_sorted_by_x[i].y - points_sorted_by_x[i + 1].y));
