            abs(points_sorted_by_y[i].y - points_sorted_by_y[i + 1].y));
        edges.push_back(tmp);
    }
    sort(edges.begin(), edges.end(), [&](Edge& lhs, Edge& rhs) {
        return lhs.cost < rhs.cost;
    });

    //クラスカル法
    long long ans = 0;
    UnionFind uf(N);
    for (Edge e : edges) {
        if (!uf.same(e.index1, e.index2)) {
            uf.unionSet(e.index1, e.index2);
            ans += e.cost;
        }
    }

    cout << ans << endl;
}

