	std::vector<int> data;

	UnionFind(int n) {
		data.assign(n, -1);
	}

	void unite(int x, int y) {
		x = find(x); y = find(y);
		if(x == y) return;
		if(data[x] > data[y]) std::swap(x, y);
		data[x] += data[y];
		data[y] = x;
	}

	int find(int k) {
		if(data[k] < 0) return k;
		return data[k] = find(data[k]);
	}

