int par[MAX_V];
int ranks[MAX_V];

void init(int n){
  rep(i, n) par[i] = i, ranks[i] = 0;
}

int find(int x){
  if(par[x] == x){
    return x;
  } else{
    int r = find(par[x]);
    return par[x] = r;
  }
}

void unite(int x, int y){
  x = find(x); y = find(y);
  if (x == y) return;
  if (ranks[x] < ranks[y]) swap(x, y);
  if (ranks[x] == ranks[y]) ranks[x]++;
  par[y] = x;
}

bool same(int x, int y){
  return find(x) == find(y);
}

