//閉路判定でUnionfindを使う

/* UnionFind：素集合系管理の構造体(union by rank)
    isSame(x, y): x と y が同じ集合にいるか。 計算量はならし O(α(n))
    unite(x, y): x と y を同じ集合にする。計算量はならし O(α(n))
*/
struct UnionFind
{ // The range of node number is u 0 v n-1
    vector<ll> rank, parents;
    UnionFind() {}
    UnionFind(ll n)
    { // make n trees.
        rank.resize(n, 0);
        parents.resize(n, 0);
        for (ll i = 0; i < n; i++)
        {
            makeTree(i);
        }
    }
    void makeTree(ll x)
    {
        parents[x] = x; // the parent of x is x
        rank[x] = 0;
    }
    bool isSame(ll x, ll y) { return findRoot(x) == findRoot(y); }
    void unite(ll x, ll y)
    {
        x = findRoot(x);
        y = findRoot(y);
        if (rank[x] > rank[y])
        {
            parents[y] = x;
        }
        else
        {
            parents[x] = y;
            if (rank[x] == rank[y])
            {
                rank[y]++;
            }
        }
    }
    ll findRoot(ll x)
    {
        if (x != parents[x])
            parents[x] = findRoot(parents[x]);
        return parents[x];
    }
};
