struct UnionFind {
    vector<int> par;  // par[i]: parent of i

    UnionFind(int N) : par(N + 1) {  // initialize by making every node a root node
        for (int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) {  // find the root of a given node
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        par[rx] = ry;
    }

    bool same(int x, int y) {  // return true if x and y belong to the same tree
        return root(x) == root(y);
    }
};

int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> points_x(n), points_y(n);
    map<pair<int, int>, int> indices;
    rep(i, n) {
        int x, y;
        cin >> x >> y;
        points_x[i].first = x;
        points_x[i].second = y;
        points_y[i].first = y;
        points_y[i].second = x;
        indices[make_pair(x, y)] = i;
        indices[make_pair(y, x)] = i;
    }
    sort(points_x.begin(), points_x.end());
    sort(points_y.begin(), points_y.end());

    vector<pair<int, int>> adj[n]{};
    rep(i, n - 1) {
        int from = indices[points_x[i]];
        int to = indices[points_x[i + 1]];
        adj[from].push_back(make_pair(to, abs(points_x[i].first - points_x[i + 1].first)));
        adj[to].push_back(make_pair(from, abs(points_x[i].first - points_x[i + 1].first)));
    }
    rep(i, n - 1) {
        int from = indices[points_y[i]];
        int to = indices[points_y[i + 1]];
        adj[from].push_back(make_pair(to, abs(points_y[i].first - points_y[i + 1].first)));
        adj[to].push_back(make_pair(from, abs(points_y[i].first - points_y[i + 1].first)));
    }

    // Prim's algo
    ll cost = 0;
    UnionFind tree(n);
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    for (auto p : adj[0]) {
        pq.push(make_pair(p.second, p.first));
    }
    while (!pq.empty()) {
        auto p = pq.top();
        pq.pop();
        if (tree.same(0, p.second)) continue;
        tree.unite(0, p.second);
        cost += p.first;
        for (auto p : adj[p.second]) {
            pq.push(make_pair(p.second, p.first));
        }
    }
    cout << cost << endl;
}

