struct UnionFind {
    vector<int> par;

    UnionFind(int n): par(n, -1) {}
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }

    int issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);

        if (x == y) return false;

        // merge by size
        // force size of x to be bigger than that of y
        if (par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;

        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

struct Edge {
    ll u, v, cost;
};

bool comp(Edge x, Edge y) {
    return x.cost < y.cost;
}

int V, E;
const int MAX_E = 4 * 1e5;
Edge es[MAX_E];

int kruskal() {
    sort(es, es + E, comp);
    UnionFind uf(V);

    int ret = 0;
    REP(i, E) {
        Edge e = es[i];
        if (!uf.issame(e.u, e.v)) {
            uf.merge(e.u, e.v);
            ret += e.cost;
        }
    }

    return ret;
}

