}

int find_set(int v) {
	if (p[v] == v) return v;
	return p[v] = find_set(p[v]);
}

void union_sets(int a, int b) {
	a = find_set(a);
	b = find_set(b);
	if (a != b) {
		if (s[a] < s[b]) swap(a, b);
		p[b] = a;
		s[a] += s[b];
	}
}

