long long int calculate(pair<long long int, long long int> start, pair<long long int, long long int> end)
{
	long long int xdist = abs(start.first - end.first);
	long long int ydist = abs(start.second - end.second);
	return xdist < ydist ? xdist : ydist;
}

int main()
{
	int n;
	cin >> n;
	vector<pair<long long int, long long int>> points(n);
	vector<int> xpoints(n);
	vector<int> ypoints(n);
	vector<bool> flag(n, false);
	for (int i = 0; i < n; i++)
	{
		long long int x, y;
		cin >> x >> y;
		points[i] = make_pair(x, y);
		xpoints[i] = i;
		ypoints[i] = i;
	}
	auto comparex = [&points](int a, int b) -> bool
	{
		return points[a].first < points[b].first;
	};
	auto comparey = [&points](int a, int b) -> bool
	{
		return points[a].second < points[b].second;
	};
	sort(xpoints.begin(), xpoints.end(), comparex);
	sort(ypoints.begin(), ypoints.end(), comparey);

	//クラスカル法の実装
	//union-find木の実装
	struct union_find_tree {
		vector<int> parent;
		vector<int> rank;

		void init(int n)
		{
			for (int i = 0; i < n; i++)
			{
				parent.push_back(i);
				rank.push_back(0);
			}
		}

		int find(int x)
		{
			if (parent[x] == x)
			{
				return x;
			}
			else
			{
				return parent[x] = find(parent[x]);
			}
		}

		void unite(int x, int y)
		{
			x = find(x);
			y = find(y);

			if (x == y) return;

			if (rank[x] < rank[y])
			{
				parent[x] = y;
			}
			else {
				parent[y] = x;
				if (rank[x] == rank[y]) rank[x]++;
			}
		}

		bool same(int x, int y)
		{
			return find(x) == find(y);
		}
	};
	union_find_tree tree;
	tree.init(n);
	//辺集合の生成
	struct edge
	{
		int start;
		int end;
		long long int cost;

		bool operator<(edge &e) const {
			return cost < e.cost;
		}
	};
	vector<edge> edges;
	for (int i = 0; i < n - 1; i++)
	{
		edge e1 = { xpoints[i], xpoints[i + 1], calculate(points[xpoints[i]], points[xpoints[i + 1]]) };
		edge e2 = { ypoints[i], ypoints[i + 1], calculate(points[ypoints[i]], points[ypoints[i + 1]]) };
		edges.push_back(e1);
		edges.push_back(e2);
	}
	sort(edges.begin(), edges.end());
	long long int cost = 0;
	for (auto e : edges)
	{
		if (!tree.same(e.start, e.end))
		{
			tree.unite(e.start, e.end);
			cost += e.cost;
		}
	}
	cout << cost << endl;
}

