template<typename T>
struct Kruskal{
  struct edge{
    ll from,to;
    T cost;
    ll used;
    edge(ll from,ll to,T cost):
      from(from),to(to),cost(cost),used(0){}
    bool operator<(const edge& e) const{
      return cost<e.cost;
    }
  };
  vector<ll> r,p;
  vector<edge> es;

  Kruskal(){}
  Kruskal(ll n):r(n,1),p(n){
    iota(p.begin(),p.end(),0);
  }

  ll find(ll x){
    return (x==p[x]?x:p[x]=find(p[x]));
  }

  bool same(ll x,ll y){
    return find(x)==find(y);
  }

  void unite(ll x,ll y){
    x=find(x);y=find(y);
    if(x==y) return;
    if(r[x]<r[y]) swap(x,y);
    r[x]+=r[y];
    p[y]=x;
  }

  void add_edge(ll u,ll v,T c){
    es.emplace_back(u,v,c);
  }

  T build(){
    sort(es.begin(),es.end());
    T res=0;
    for(auto &e:es){
      if(!same(e.from,e.to)){
        res+=e.cost;
        unite(e.from,e.to);
        e.used=1;
      }
    }
    return res;
  }
};

