enum { WEIGHT, PREV, NEXT };

int main(void) {
    int N;
    cin >> N;

    UnionFind uf(N);
    priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>,
                   greater<tuple<int, int, int>>>
        edges;

    vector<tuple<int, int, int>> x_order_node(N), y_order_node(N);
    rep(i, N) {
        int x, y;
        scanf("%d%d", &x, &y);

        x_order_node[i] = make_tuple(x, y, i);
        y_order_node[i] = make_tuple(y, x, i);
    }

    sort(ALL(x_order_node));
    for(int i = 0; i < N - 1; i++) {
        int cost =
            min(abs(get<0>(x_order_node[i]) - get<0>(x_order_node[i + 1])),
                abs(get<1>(x_order_node[i]) - get<1>(x_order_node[i + 1])));
        edges.push(make_tuple(cost, get<2>(x_order_node[i]),
                              get<2>(x_order_node[i + 1])));
    }

    sort(ALL(y_order_node));
    for(int i = 0; i < N - 1; i++) {
        int cost =
            min(abs(get<0>(y_order_node[i]) - get<0>(y_order_node[i + 1])),
                abs(get<1>(y_order_node[i]) - get<1>(y_order_node[i + 1])));
        edges.push(make_tuple(cost, get<2>(y_order_node[i]),
                              get<2>(y_order_node[i + 1])));
    }

    vector<int> ans;
    while(!edges.empty()) {
        tuple<int, int, int> edge = edges.top();
        edges.pop();
        if(!uf.isSame(get<PREV>(edge), get<NEXT>(edge))) {
            uf.unite(get<PREV>(edge), get<NEXT>(edge));
            ans.push_back(get<WEIGHT>(edge));
        }
    }

    cout << accumulate(ALL(ans), 0) << endl;
    return 0;
}

