int mst(void)
{
    int mincost[MAX_N];
    bool used[MAX_N];
    for (int i = 0; i < n; i++) {
        mincost[i] = INF;
        used[i] = false;
    }
    mincost[0] = 0;
    int res = 0;
    for (;;) {
        int v = -1;
        for (int u = 0; u < n; u++)
            if (!used[u] && (v == -1 || mincost[u] < mincost[v]))
                v = u;
        if (v == -1) break;
        used[v] = true;
        res += mincost[v];
        for (int u = 0; u < n; u++)
            mincost[u] = min(mincost[u], cost[v][u]);
    }
    return res;
}

