int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    for( int i = 0; i < SIZE; ++i ) {
        root[i] = i;

    }

    vector< LP > x_edge, y_edge;
    for( LL i = 0; i < n; ++i ) {
        LL x, y;
        cin >> x >> y;
        x_edge.pb( MP( x, i ) );
        y_edge.pb( MP( y, i ) );

    }
    sort( all( x_edge ) );
    sort( all( y_edge ) );

    for( int i = 0; i < n - 1; ++i ) {
        LL x_min_cost = abs( x_edge[i].F - x_edge[i + 1].F );
        LL y_min_cost = abs( y_edge[i].F - y_edge[i + 1].F );

        edge.pb( MP( x_min_cost, MP( x_edge[i].S, x_edge[i + 1].S ) ) );
        edge.pb( MP( y_min_cost, MP( y_edge[i].S, y_edge[i + 1].S ) ) );

    }

    cout << Kruskal() << endl;

    return 0;
}

int Root( int x ) {
    if( x == root[x] ) {
        return x;

    }

    return root[x] = Root( root[x] );

}

bool Unite( int x, int y ) {
    int rx, ry;
    rx = Root( x );
    ry = Root( y );
    if( rx == ry ) {
        return false;

    }

    if( rx > ry ) {
        root[ry] = rx;

    } else {
        root[rx] = ry;

    }
    return true;

}

LL Kruskal() {
    sort( all( edge ) );

    LL res = 0;
    for( int i = 0; i < edge.size(); ++i ) {
        if( Unite( edge[i].S.F, edge[i].S.S ) ) {
            res += edge[i].F;

        }
    }

    return res;
}

