class UnionFind
{
public:
    UnionFind(int size) : m_Nodes(size)
    {
        Init();
    }

    void Init()
    {
        for (int i = 0, size = m_Nodes.size(); i < size; ++i)
        {
            m_Nodes[i].Init(i);
        }
    }

    int Root(int x)
    {
        const int parent = m_Nodes[x].m_Parent;
        if (parent == x)
        {
            return x;
        }
        else
        {
            return m_Nodes[x].m_Parent = Root(parent);
        }
    }

    bool Same(int x, int y)
    {
        return Root(x) == Root(y);
    }

    bool Unite(int x, int y)
    {
        x = Root(x);
        y = Root(y);

        if (x == y) return false;

        if (m_Nodes[x].m_Rank < m_Nodes[y].m_Rank)
        {
            m_Nodes[x].m_Parent = y;
            m_Nodes[y].m_Size += m_Nodes[x].m_Size;
        }
        else
        {
            m_Nodes[y].m_Parent = x;
            m_Nodes[x].m_Size += m_Nodes[y].m_Size;
            if (m_Nodes[x].m_Rank == m_Nodes[y].m_Rank) ++m_Nodes[x].m_Rank;
        }

        return true;
    }

    int Size(int x)
    {
        return m_Nodes[Root(x)].m_Size;
    }

private:
    struct Node
    {
    public:
        void Init(int index)
        {
            m_Parent = index;
            m_Rank = 0;
            m_Size = 1;
        }

        int m_Parent = -1;
        int m_Rank = -1;
        int m_Size = -1;
    };

    vector<Node> m_Nodes;
};
