void _main()
{
    int N;
    cin >> N;
    vector<pair<int, int>> x(N), y(N);
    rep(i, 0, N)
    {
        cin >> x[i].first >> y[i].first;
        x[i].second = y[i].second = i;
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    vector<tuple<int, int, int>> v;
    rep(i, 0, N - 1)
    {
        v.push_back(make_tuple(x[i + 1].first - x[i].first, x[i].second, x[i + 1].second));
        v.push_back(make_tuple(y[i + 1].first - y[i].first, y[i].second, y[i + 1].second));
    }
    sort(v.begin(), v.end());

    UnionFind uf(N);

    ll ans = 0;
    int roadNum = 0;
    for (const auto& t : v)
    {
        int cost, a, b;
        tie(cost, a, b) = t;

        if (uf.Same(a, b)) continue;

        ans += cost;

        uf.Unite(a, b);

        ++roadNum;

        if (roadNum == N - 1)
        {
            break;
        }
    }
    cout << ans << endl;
}

