class UF
{
	int node;//ノード数
	vector<int> parent;//親
	vector<int> depth;//深さ
	vector<int> size;//直径

	public:
	//コンストラクタ
	UF(int n)
	{
		node=n;
		parent.resize(n);
		depth.resize(n,0);
		size.resize(n,1);
		for(int i=0;i<node;i++)
			parent[i]=i;
	}

	//根を求める
	int find(int x)
	{
		int prex=x;
		while(parent[x]!=x)
		{
			x=parent[x];
			parent[prex]=parent[x];
			prex=x;
		}
		return x;
	}

	//併合
	void unite(int x,int y)
	{
		int parx=find(x);
		int pary=find(y);
		if(parx==pary)
			return;
		if(depth[parx]<depth[pary])
		{
			parent[pary]=parx;
			size[parx]+=size[pary];
		}else{
			parent[parx]=pary;
			size[pary]+=size[parx];
			if(depth[parx]==depth[pary])
				depth[pary]++;
		}
	}
	//同じ集合か
	bool same(int x,int y)
	{
		return find(x)==find(y);
	}
	//直径を求める
	int getsize(int x)
	{
		return size[find(x)];
	}
};

