static const ll MAX_N = 200000;
ll par[MAX_N];
ll ran[MAX_N];

ll Z[100001] = {};
void init(ll n) {
	repe(i, 1, n) {
		par[i] = i;
		ran[i] = 0;
		Z[i] = 1;
	}
}

ll find(ll x) {
	if (par[x] == x)  return x;
	else return par[x] = find(par[x]);
}
void unite(ll x, ll y) {
	x = find(x);
	y = find(y);

	if (x == y) return;

	if (ran[x] < ran[y]) {
		par[x] = y;
		Z[y] += Z[x];
		Z[x] = 0;
	}
	else {
		par[y] = x;
		Z[x] += Z[y];
		Z[y] = 0;
		if (ran[x] == ran[y]) ran[x]++;
	}

	////if (Z[x] < Z[y]) swap(x, y);
