class union_find {
private:
    vector<int> parent, rank, gs;
    int size;

public:
    int count_group;
    union_find() = default;
    union_find(int n) { init(n); }

    void init(int n) {
        size = n;
        count_group = n;
        parent.resize(size);
        rank.assign(size, 0);
        gs.assign(size, 1);
        for (int i = 0; i < size; ++i) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] == x)
            return x;
        else
            return parent[x] = find(parent[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) {
            parent[x] = y;
            gs[y] += gs[x];
        } else {
            parent[y] = x;
            gs[x] += gs[y];
            if (rank[x] == rank[y]) ++rank[x];
        }
        --count_group;
    }

    bool is_same_group(int x, int y) {
        return find(x) == find(y);
    }

    int group_size(int x) {
        return gs[find(x)];
    };
};

void solve() {
    //constexpr i64 mod = 1'000'000'007;
    i64 N;
    cin >> N;

    vector<i64> x(N),y(N);
    rep(i,0,N){
        cin >> x[i] >> y[i];
    }

    vector<pair<i64,i64>> xi(N),yi(N);
    rep(i,0,N) xi[i]=make_pair(x[i],i);
    rep(i,0,N) yi[i]=make_pair(y[i],i);

    sort(begin(xi),end(xi));
    sort(begin(yi),end(yi));

    using edge=tuple<i64,i64,i64>;
    vector<edge> edges;
    rep(i,1,N){
        edges.emplace_back(make_tuple(xi[i].first-xi[i-1].first,xi[i].second,xi[i-1].second));
    }
    rep(i,1,N){
        edges.emplace_back(make_tuple(yi[i].first-yi[i-1].first,yi[i].second,yi[i-1].second));
    }

    sort(begin(edges),end(edges));

    i64 ans=0;
    union_find uf(N);
    for(const auto& e:edges){
        i64 d,u,v;
        tie(d,u,v)=e;
        if(uf.is_same_group(u,v)) continue;
        uf.unite(u,v);
        ans+=d;
    }

    cout << ans << endl;
}

