using namespace std;

const int N = 100000, M = (N - 1) * 2;

struct E {
	int i, j, w;
} ee[M];

int xx[N], yy[N], ii[N], jj[N], ds[N];

int find(int i) {
	return ds[i] < 0 ? i : (ds[i] = find(ds[i]));
}

bool join(int i, int j) {
	i = find(i);
	j = find(j);
	if (i == j)
		return false;
	if (ds[i] > ds[j])
		ds[i] = j;
	else {
		if (ds[i] == ds[j])
			ds[i]--;
		ds[j] = i;
	}
	return true;
}

int main() {
	int n; cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> xx[i] >> yy[i];
		ii[i] = jj[i] = i;
	}
	sort(ii, ii + n, [] (int i, int j) { return xx[i] < xx[j]; });
	sort(jj, jj + n, [] (int i, int j) { return yy[i] < yy[j]; });
	int m = 0;
	for (int h = 1; h < n; h++) {
		int i, j, w;
		i = ii[h - 1];
		j = ii[h];
		w = xx[j] - xx[i];
		auto &e = ee[m++];
		e.i = i, e.j = j, e.w = w;
		i = jj[h - 1];
		j = jj[h];
		w = yy[j] - yy[i];
		auto &f = ee[m++];
		f.i = i, f.j = j, f.w = w;
	}
	sort(ee, ee + m, [] (auto &e, auto &f) { return e.w < f.w; });
	fill(ds, ds + n, -1);
	long long ans = 0;
	for (int h = 0; h < m; h++) {
		auto &e = ee[h];
		if (join(e.i, e.j))
			ans += e.w;
	}
	cout << ans << '\n';
	return 0;
}

