const int MAXN=510;//最大点数
const int MAXM=250000;//最大边数
int F[MAXN];//并查集使用
int x[MAXN],y[MAXN];
struct Edge{
    int u,v;
    int w;
}edge[MAXM];//存储边的信息，包括起点/终点/权值
int ww[MAXM];
int tol;//边数，加边前赋值为 0
void addedge(int u,int v,double w){
    edge[tol].u=u;
    edge[tol].v=v;
    edge[tol++].w=w;
}
//排序函数，讲边按照权值从小到大排序
bool cmp(Edge a,Edge b){
    return a.w<b.w;
}
int find(int x){
    if(F[x]==-1)return x;
    else return F[x]=find(F[x]);
}//传入点数，返回最小生成树的权值，如果不连通返回 -1
int Kruskal(int n){
    memset(F,-1,sizeof(F));
    sort(edge,edge+tol,cmp);
    int cnt=0;//计算加入的边数
    int ans=0;
    for(int i=0;i<tol;i++){
        int u=edge[i].u;
        int v=edge[i].v;
        int w=edge[i].w;
        int t1=find(u);
        int t2=find(v);
        if(t1!=t2){
            ww[cnt]=w;
            ans+=w;
            F[t1]=t2;
            cnt++;
        }
        if(cnt==n-1)break;
    }
    if(cnt<n-1)return -1;//不连通
    else return ans;
}
int main(){
    int n,m;
    int ans=0;
    tol=0;
    scanf("%d",&n);
    for(int i=1;i<=n;i++){
        scanf("%d%d",&x[i],&y[i]);
    }
    for(int i=1;i<=n;i++){
        for(int j=1+i;j<=n;j++){
            addedge(i,j,min(fabs(x[i]-x[j]),fabs(y[i]-y[j])));
        }
    }
    ans=Kruskal(n);
    printf("%d",ans);
    return 0;
}

