vector<int> arr(N),siz(N);

void init(int n)
{
	int i;
	for(i=1;i<=n;++i)
		arr[i]=i,siz[i]=1;
}

int root(int x)
{
	while(arr[x]!=x)
	{
		arr[x]=arr[arr[x]];   //path compression
		x=arr[x];
	}
	return x;
}

int uni(int a,int b)  //"weighted" union
{
	int ra=root(a);
	int rb=root(b);

	if(ra==rb)
        return 0;

	if(siz[ra]>siz[rb])
	{
		arr[rb]=ra;
		siz[ra]+=siz[rb];
	}
	else
	{
		arr[ra]=rb;
		siz[rb]+=siz[ra];
	}

	return 1;
}

