typedef pair<int, int> P;

struct UnionFind {
  vector<int> par, sizes;

  UnionFind(int n) : par(n), sizes(n, 1) {
    for (int i = 0; i < n; i++) par[i] = i;
  }

  int find(int x) {
    return (x == par[x] ? x : par[x] = find(par[x]));
  }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);

    if (x == y) return;

    if (sizes[x] < sizes[y]) swap(x, y);

    par[y] = x;
    sizes[x] += sizes[y];
  }

  bool same(int x, int y) {
    return (find(x) == find(y));
  }

  int size(int x) {
    return sizes[find(x)];
  }
};

struct Edge {
  int a, b, cost;

  bool operator<(const Edge& o) const {
    return cost < o.cost;
  }
};

struct Graph {
  int n;
  vector<Edge> es;

  // クラスカル法
  int kruskal() {
    sort(es.begin(), es.end());

    UnionFind uf(n);
    int min_cost = 0;
    for (int i = 0; i < es.size(); i++) {
      Edge& e = es[i];
      if (!uf.same(e.a, e.b)) {
        min_cost += e.cost;
        uf.unite(e.a, e.b);
      }
    }

    return min_cost;
  }
};

int main() {
  int N;
  cin >> N;
  P x[N], y[N];
  for (int i = 0; i < N; i++) {
    scanf("%d %d", &x[i].first, &y[i].first);
    x[i].second = y[i].second = i;
  }

  // 最小全域木を求めるのに辺が多すぎるので、必要な辺だけを残す
  sort(x, x + N), sort(y, y + N);

  Graph g;
  g.n = N;
  Edge e;
  for (int i = 0; i < N - 1; i++) {
    e.a = x[i].second, e.b = x[i+1].second, e.cost = x[i+1].first - x[i].first;
    g.es.push_back(e);
    e.a = y[i].second, e.b = y[i+1].second, e.cost = y[i+1].first - y[i].first;
    g.es.push_back(e);
  }

  cout << g.kruskal() << endl;
  return 0;
}

