const ll MAX_E = 200001;

struct uf_tree {
  vector<ll> par, sizes;
  uf_tree(ll n) : par(n), sizes(n, 1) {
    for (ll i = 0; i < n; i++) {
      par[i] = i;
    }
  }
  ll find(ll x) {
    if (x == par[x]) {
      return x;
    }
    return par[x] = find(par[x]);
  }
  void unite(ll x, ll y) {
    x = find(x);
    y = find(y);
    if (x == y) {
      return;
    }
    if (sizes[x] < sizes[y]) {
      swap(x, y);
    }
    par[y] = x;
    sizes[x] += sizes[y];
  }
  bool same(ll x, ll y) { return find(x) == find(y); }
  ll size(ll x) { return sizes[find(x)]; }
};

struct edge {
  ll u, v, cost;
};
bool comp(const edge &e1, const edge &e2) { return e1.cost < e2.cost; }

edge es[MAX_E];
ll V, E;

ll kruskal() {
  sort(es, es + E, comp);
  uf_tree uf(V);
  ll res = 0;
  for (ll i = 0; i < E; i++) {
    edge e = es[i];
    if (!uf.same(e.u, e.v)) {
      uf.unite(e.u, e.v);
      res += e.cost;
    }
  }
  return res;
}

