  sort(x.begin(), x.end());
  sort(y.begin(), y.end());
  for (int i = 1; i < N; i++) {
    es[i - 1] =
        edge{x[i - 1].second, x[i].second, abs(x[i].first - x[i - 1].first)};
  }
  for (int i = 1; i < N; i++) {
    es[i - 2 + N] =
        edge{y[i - 1].second, y[i].second, abs(y[i].first - y[i - 1].first)};
  }

  cout << kruskal() << endl;
  return 0;
}

