struct unionfind{
    vector<int> rank,parent,size;
    unionfind(int n){
        for(int i=0;i<n;i++){
            rank.push_back(1);//树的高度
            parent.push_back(i);//根
            size.push_back(1);//树大小
        }
    }
    int getroot(int x){
        if(parent[x]==x)
            return x;
        return parent[x]=getroot(parent[x]);//押平路径加速以后的查找
    }
    bool issame(int a,int b){
        return getroot(a)==getroot(b);
    }
    void unite(int a,int b){
        a=getroot(a);
        b=getroot(b);
        if(a==b)
            return;
        else if(rank[a]>rank[b]){ //合并到高的树下
            parent[b]=a;
            size[a]+=size[b];
        }
        else if(rank[a]==rank[b]){
            parent[b]=a;
            rank[a]++;
            size[a]+=size[b];
        }
        else{
            parent[a]=b;
            size[b]+=size[a];
        }
    }
};

class Edge{
public:
    int source,target,cost;
    Edge(int source=0,int target=0,int cost=0):
    source(source), target(target), cost(cost) {}
    bool operator < ( const Edge &e) const {
        return cost < e.cost;
    }
};

int kruskal(int n,vector<Edge> edges){
    int total=0;
    sort(all(edges));
    unionfind uf(n);
    for(int i=0;i<edges.size();i++){
        Edge e=edges[i];
        if(!uf.issame(e.source, e.target)){
            total+=e.cost;
            uf.unite(e.source,e.target);
        }
    }
    return total;
}

