struct UnionFind {
  int N;
  vector<int> par,ranc;

  UnionFind(int n) : N(n),par(n),ranc(n) { REP(i,n) par[i]=i,ranc[i]=0; }

  int root(int s) {
    if (par[s]==s) return s;
    else return root(par[s]);
  }

  void merge(int a,int b) {
    a = root(a);
    b = root(b);
    if (a==b) return;

    if (ranc[a]>ranc[b]) {
      par[b] = a;
    } else {
      par[a] = b;
      if (ranc[a]==ranc[b]) ranc[b]++;
    }
  }

  bool same(int a,int b) { return root(a)==root(b); }

  bool connected() {
    int base = root(0);
    REP(i,N) if (base != root(i)) return false;
    return true;
  }
};

int main() {
