    xtowns.push_back(make_tuple(x,y,i));
    ytowns.push_back(make_tuple(y,x,i));
  }

  sort(ALL(xtowns));
  sort(ALL(ytowns));
  struct edge { int cost,from,to; };
  auto compare = [](edge a,edge b) { return a.cost>b.cost; };
  priority_queue<edge,vector<edge>,decltype(compare)> es(compare);
  FOR(i,1,N) {
    int x1,y1,idx1;
    int x2,y2,idx2;
    tie(x1,y1,idx1) = xtowns[i-1];
    tie(x2,y2,idx2) = xtowns[i];
    es.push({abs(x2-x1),idx1,idx2});
  }
  FOR(i,1,N) {
    int x1,y1,idx1;
    int x2,y2,idx2;
    tie(y1,x1,idx1) = ytowns[i-1];
    tie(y2,x2,idx2) = ytowns[i];
    es.push({abs(y2-y1),idx1,idx2});
  }

  UnionFind uf(N);
  int ans = 0;
  while (!es.empty()) {
    edge e = es.top();es.pop();
    if (uf.root(e.from)==uf.root(e.to)) continue;
    uf.merge(e.from,e.to);
    ans += e.cost;
    if (uf.connected()) break;
  }
  OUT(ans);

