ll kruskal(void){
	sort (ALL(es), cmp);	// edge.cost が小さい順にソートする
	UNION_FIND uf(V);	// Union-Find の初期化
	ll res = 0LL;
	for (int i = 0; i < E; ++i){
		edge e = es[i];
		if (!uf.same (e.u, e.v)){
