LL prim(const vector<vector<Edge>>& G) {
  vector<bool> used(G.size(), false);
  vector<LL> d(G.size(), LLONG_MAX);
  LL total_dist = 0;

  priority_queue<P, vector<P>, greater<P>> que;
  que.push({0, 0});
  while (!que.empty()) {
    auto p = que.top(); que.pop();
    LL dist = p.first;
    int v = p.second;
    if (used[v]) continue;

    used[v] = true;
    total_dist += dist;
    for (auto e : G[v]) {
      que.push({e.cost, e.to});
    }
  }
  return total_dist;
}

