    vector<edge> e[MAX_N];
    int mincost[MAX_N];
    bool used[MAX_N];
    int N, E;
    cin >> N >> E;
    REP(i, N){
        mincost[i] = INF;
        used[i] = false;
    }
    REP(i, E){
        int s, t, w;
        cin >> s >> t >> w;
        edge ss = {t, w};
        edge tt = {s, w};
        e[s].push_back(ss);
        e[t].push_back(tt);
    }
    mincost[0] = 0;
    int res = 0;
    priority_queue<P, vector<P>, greater<P>> que;
    REP(i, e[0].size()){
        que.push(P(e[0][i].cost,e[0][i].to));
    }
    used[0] = true;
    int vnokazu = 1;
    while(vnokazu < N){
        P p;
        do{
            p = que.top();que.pop();
        }while(used[p.second]);
        used[p.second] = true;
        res += p.first;
        vnokazu++;
        REP(i, e[p.second].size()){
            if(!used[e[p.second][i].to])que.push(P(e[p.second][i].cost,e[p.second][i].to));
        }
    }
    return res;
}

