  vector< pair< int, pair<int,int> > > city(N);
  for(int i=0; i<N; i++){
    int x,y;
    cin >> x >> y;
    city[i].first = i;
    city[i].second.first = x;
    city[i].second.second = y;
  }

  //グラフの準備
  vector<vector<pair<int,int>>> g(N); //g[from](to,cost) 
  //注意。最初のベクトルはノードのベクトル。2番目のベクトルは辺のベクトル。


  //まずは辺を張る。全域最小木の候補としてはx・y座標でソートしたものだけを見れば良い。
  sort(city.begin(), city.end(), compare_by_first);//街のx座標でソート。
  for(int i=0; i<N-1; i++){//i番目の街とi+1番目の街の間に辺を張る。
    g[city[i].first].push_back(make_pair(city[i+1].first,city[i+1].second.first-city[i].second.first) );
    //i+1番目にx座標が小さい街
  }

  sort(city.begin(), city.end(), compare_by_second);//街のy座標でソート。
