  for(int i=0; i<edges.size(); i++){
    if(!tree.isUnited(edges[i].first, edges[i].second.first)){
      //最小辺のfromとtoが連結でない時
      tree.unite(edges[i].first, edges[i].second.first);
      ans += edges[i].second.second;
    }
  }

  output(ans);

