/*
引数
　g:探索するグラフ
　start:この点を根とする全域木を求める
戻り値
　return:最小全域木を構成する辺のコストの総和
　ming:最小全域木のグラフ
*/
ll prim(const vector<vector<Edge>> &g, vector<vector<Edge>> &ming, ll start = 0) {
	ll n = g.size();
	ming.assign(n, vector<Edge>());
	ll mincost = 0;
	vector<bool> visited(n,false);
	priority_queue<Edge, vector<Edge>, function<bool(Edge,Edge)>> que(
		[](const Edge &x, const Edge &y){
			return x.cost != y.cost ? (x.cost > y.cost) : 
				(x.from != y.from ? x.from < y.from : x.to < y.to);
		}
	);

	que.push( Edge(-1, start, 0) );
	while (!que.empty()) {
		Edge e = que.top();
		que.pop();
		if (visited[e.to]) continue;
		visited[e.to] = true;
		if (e.from>=0) ming[e.from].push_back(e);
		mincost += e.cost;
		for(Edge f:g[e.to]) {
			if (!visited[f.to]) que.push(f);
		}
	}
	return mincost;
}

