    for (int i = 0; i < N; i++) {
        int a, b;
        cin >> a >> b;
        x.push_back(make_pair(a, i));
        y.push_back(make_pair(b, i));
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    vector<int> x_idxs(N), y_idxs(N);
    for (int i = 0; i < N; i++) {
        x_idxs[x[i].second] = i;
        y_idxs[y[i].second] = i;
