    // cout << x << endl;
    // cout << y << endl;
    // cout << x_idxs << endl;
    // cout << y_idxs << endl;

    vector<ll> dist(N, INF);
    dist[0] = 0;
    vector<bool> used(N, false);
    used[0] = false;
    priority_queue<P, vector<P>, greater<P>> que;
    que.push(make_pair(0, 0));
    ll cost = 0;
    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int idx = p.second;
        if (used[idx] || dist[idx] < p.first) continue;

        used[idx] = true;
        cost += dist[idx];
        // p_("idx", idx, " dist", dist[idx], " cost", cost);

        int ix = x_idxs[idx];
        int iy = y_idxs[idx];
        // p_("ix", ix, " iy", iy);

        vector<int> next_idxs;
        vector<ll> ds;
        if (ix > 0) {
            next_idxs.push_back(x[ix-1].second);
            ds.push_back(x[ix].first - x[ix-1].first);
        }
        if (ix < N-1) {
            next_idxs.push_back(x[ix+1].second);
            ds.push_back(x[ix+1].first - x[ix].first);
        }
        if (iy > 0) {
            next_idxs.push_back(y[iy-1].second);
            ds.push_back(y[iy].first - y[iy-1].first);
        }
        if (iy < N-1) {
            next_idxs.push_back(y[iy+1].second);
            ds.push_back(y[iy+1].first - y[iy].first);
        }

        for (int i = 0; i < next_idxs.size(); i++) {
            if (!used[next_idxs[i]] && dist[next_idxs[i]] > ds[i]) {
                dist[next_idxs[i]] = ds[i];
                // p_("add ", dist[next_idxs[i]], next_idxs[i]);
                que.push(make_pair(dist[next_idxs[i]], next_idxs[i]));
            }
        }
    }

    cout << cost << endl;

    return 0;
}

