        graph[y_vec[i + 1].second].push_back(y_vec[i].second);
    }
    priority_queue<P> PQ;
    int ans = 0;
    PQ.push(MP(0, 0));
    while (!PQ.empty()) {
        P now = PQ.top();
        PQ.pop();
        int cost = -now.first, node = now.second;
        if (is_checked[node]) continue;
        is_checked[node] = true;
        ans += cost;
        for (int i = 0; i < graph[node].size(); i++) {
            if (is_checked[graph[node][i]]) continue;
            int u = graph[node][i];
            PQ.push(MP(max(-abs(x[node] - x[u]), -abs(y[node] - y[u])), u));
        }
    }
    cout << ans << endl;
    return 0;
}

