        Y[i] = {{y, x}, i};
    }

    sort(X.begin(), X.end());
    sort(Y.begin(), Y.end());

    struct edge {
        int from, to, cost;
    };
    vector<edge> E;

    for(int i=0; i<N-1; i++){
        edge e;
        e.from = X[i].sc;
        e.to = X[i+1].sc;
        e.cost = abs(X[i+1].fs.fs-X[i].fs.fs);
        E.push_back(e);

        e.from = Y[i].sc;
        e.to = Y[i+1].sc;
        e.cost = abs(Y[i+1].fs.fs-Y[i].fs.fs);
        E.push_back(e);
    }



    sort(E.begin(), E.end(), [](const edge &a, const edge &b){return a.cost>b.cost;});

    UnionFind U(N);
    ll ans = 0;
    while(E.size()){
        edge e = E.back();
        E.pop_back();
        if(U.root(e.from)!=U.root(e.to)){
            ans += e.cost;
            U.unite(e.from, e.to);
        }
    }

    cout << ans << endl;

    return 0;
}

