template <typename T>
struct Kruskal {
    int v;
    vector<pair<T, pair<int, int>>> e; // {cost, {from, to}}

    Kruskal(int v) : v(v) {}

    struct UnionFind {
        vector<int> par;

        UnionFind(int n): par(n, -1) {}
        void init(int n) { par.assign(n, -1); }

        int root(int x) {
            if (par[x] < 0) return x;
            return par[x] = root(par[x]);
        }

        int issame(int x, int y) {
            return root(x) == root(y);
        }

        bool merge(int x, int y) {
            x = root(x); y = root(y);

            if (x == y) return false;

            // merge by size
            // force size of x to be bigger than that of y
            if (par[x] > par[y]) swap(x, y);
            par[x] += par[y];
            par[y] = x;

            return true;
        }

        int size(int x) {
            return -par[root(x)];
        }
    };

    void add_edge(int s, int t, T w) {
        // Assuming undirected connection
        e.pb({w, {s, t}});
        e.pb({w, {t, s}});
    }

    // return cost of mst
    T operator()() {
        sort(ALL(e));
        UnionFind uf(v);

        T ret = 0;
        for(auto &p: e) {
            int s = p.se.fi, t = p.se.se;
            if (uf.issame(s, t)) continue;

            uf.merge(s, t);
            ret += p.fi;
        }

        return ret;
    }
};

