struct union_find {
  vector<int> p;
  union_find(int n): p(n) {
    dotimes(x, n)
      p[x] = x;
  }
  int find(int x) {
    while (x != p[x]) {
      int y = p[x];
      p[x] = p[y];
      x = y;
    }
    return x;
  }
  bool eqv(int x, int y) {
    int a = find(x), b = find(y);
    return a == b;
  }
  bool unite(int x, int y) {
    int a = find(x), b = find(y);
    if (a == b)
      return false;
    if (!(a < b))
      swap(a, b);
    p[b] = a;
    return true;
  }
};

