#include "bits/stdc++.h"

using namespace std;

vector<int> parents;
vector<int> ranks;

void init(int n) {
    parents = vector<int>(n, 0);
    ranks = vector<int>(n, 0);
    for (int i = 0; i < n; ++i) {
        parents[i] = i;
    }
}

int find(int x) {
    if (parents[x] == x) {
        return x;
    }
    else {
        parents[x] = find(parents[x]);
        return parents[x];
    }
}

void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) {
        return;
    }

    if (ranks[x] < ranks[y]) {
        parents[x] = y;
    }
    else if (ranks[x] > ranks[y]) {
        parents[y] = x;
    }
    else {
        parents[y] = x;
        ++ranks[x];
    }
}

bool same(int x, int y) {
    return find(x) == find(y);
}

void Main() {
    int N;
