        x[i].second = i;
        y[i].second = i;
    }

    sort(x.begin(), x.end());
    sort(y.begin(), y.end());
    vector<pair<int, pair<int, int>>> diffs;
    for (int i = 1; i < N; ++i) {
        int xdiff = abs(x[i].first - x[i - 1].first);
        int ydiff = abs(y[i].first - y[i - 1].first);
        diffs.push_back(make_pair(xdiff, make_pair(x[i - 1].second, x[i].second)));
        diffs.push_back(make_pair(ydiff, make_pair(y[i - 1].second, y[i].second)));
    }
    sort(diffs.begin(), diffs.end());

    init(N);
    long long ans = 0LL;
    for (int i = 0; i < diffs.size(); ++i) {
        int a = diffs[i].second.first;
        int b = diffs[i].second.second;
        int cost = diffs[i].first;
        if (!same(a, b)) {
            unite(a, b);
            ans += (long long)cost;
        }
    }
