        edges.push_back(Edge(X[i].second, X[i + 1].second, X[i + 1].first - X[i].first));
        edges.push_back(Edge(Y[i].second, Y[i + 1].second, Y[i + 1].first - Y[i].first));
    }

    cout << Kruskal(V, edges) << endl;

    return 0;

}

