struct Point
{
  slli x, y;
  Point(slli x = 0, slli y = 0) : x(x), y(y) {}
  bool operator<(const Point &rhs) const
  {
    return y == rhs.y ? x < rhs.x : y < rhs.y;
  }
};

std::istream& operator>>(std::istream &is, Point &p)
{
  is >> p.x >> p.y;
  return is;
}

inline slli costs(const Point &p, const Point &q) {
  return std::min(::abs(p.x - q.x), ::abs(p.y - q.y));
}

struct PointSortItem
{
  Point p;
  unsigned n;
  PointSortItem(const Point &p, unsigned n)
    : p(p), n(n) {}
};

bool pointSortByLessX(const PointSortItem &lhs, const PointSortItem &rhs)
{
  return lhs.p.x == rhs.p.x ? lhs.n < rhs.n : lhs.p.x < rhs.p.x;
}

bool pointSortByLessY(const PointSortItem &lhs, const PointSortItem &rhs)
{
  return lhs.p.y == rhs.p.y ? lhs.n < rhs.n : lhs.p.y < rhs.p.y;
}

typedef std::pair<unsigned, unsigned> Edge;

void buildEdgeMap(const std::vector<Point> &p, std::map<Edge, unsigned> &edge)
{
  unsigned N = p.size();

  std::vector<PointSortItem> px, py;

  for (unsigned n = 0; n < N; ++n) {
    px.emplace_back(p[n], n);
    py.emplace_back(p[n], n);
  }

  std::sort(px.begin(), px.end(), pointSortByLessX);
  std::sort(py.begin(), py.end(), pointSortByLessY);

  for (unsigned n = 1; n < N; ++n) {
    edge.emplace(Edge(px[n - 1].n, px[n].n), costs(px[n - 1].p, px[n].p));
    edge.emplace(Edge(py[n - 1].n, py[n].n), costs(py[n - 1].p, py[n].p));
  }
}

struct SetItem
{
  Edge edge;
  unsigned cost;

  SetItem(const Edge &edge, unsigned cost) : edge(edge), cost(cost) {}
  bool operator<(const SetItem &rhs) const {
    return cost == rhs.cost ? (
      edge.first == rhs.edge.first 
      ? edge.second < rhs.edge.second 
      : edge.first  < rhs.edge.first
    ) : cost < rhs.cost;
  }
};

struct SearchForestItem
{
  std::set<unsigned> nodes;
  std::set<Edge> edges;
  unsigned cost;

  SearchForestItem() : cost(0) {}

  void set_union(const SearchForestItem &rhs) {
    for(unsigned n : rhs.nodes) nodes.insert(n);
    for(Edge     e : rhs.edges) edges.insert(e);
    cost += rhs.cost;
  }
};

std::list<SearchForestItem>::iterator searchForestByNode(std::list<SearchForestItem> &forest, unsigned node)
{
  for (std::list<SearchForestItem>::iterator itr = forest.begin(); itr != forest.end(); ++itr) {
    SearchForestItem tree = *itr;
    if (tree.nodes.find(node) != tree.nodes.end()) {
      return itr;
    }
  }
  return forest.end();
}

unsigned searchByKruskal(unsigned N, std::map<Edge, unsigned> &edge)
{
  std::list<SearchForestItem> forest;

  for (unsigned n = 0; n < N; ++n) {
    SearchForestItem item;
    item.nodes.insert(n);
    forest.push_back(item);
  }

  std::set<SetItem> s;

  for (const std::pair<Edge, unsigned> e : edge) {
    s.emplace(e.first, e.second);
  }

  while (!s.empty()) {
    SetItem item = *s.begin(); s.erase(s.begin());

    auto itr1 = searchForestByNode(forest, item.edge.first);
    auto itr2 = searchForestByNode(forest, item.edge.second);
    if (itr1 != itr2) {
      itr1->set_union(*itr2);
      forest.erase(itr2);
      itr1->cost += item.cost;
    }
  }

  return forest.begin()->cost;
}

int main()
{
  unsigned N;
  std::cin >> N;

  std::vector<Point> p(N);
  for (unsigned n = 0; n < N; ++n) {
    std::cin >> p[n];
  }

  std::map<Edge, unsigned> edge;
  buildEdgeMap(p, edge);

  std::cout << searchByKruskal(N, edge) << std::endl;

  return 0;
}

