        cin >> a >> b;
        A[i] = tie(i, a, b);
    }
    Edges<int> edges;

    // X座標が小さい順に辺を繋げる
    sort(ALL(A), [](const ti &a, const ti &b) {
        // X座標で昇順ソート
        return get<1>(a) < get<1>(b);
    });
    REP(i, N - 1) {
        int from_id, from_x, from_y, to_id, to_x, to_y;
        tie(from_id, from_x, from_y) = A[i];
        tie(to_id, to_x, to_y) = A[i + 1];
        edges.emplace_back(from_id, to_id, to_x - from_x);
    }

    // Y座標が小さい順に辺を繋げる
    sort(ALL(A), [](const ti &a, const ti &b) {
        // Y座標で昇順ソート
        return get<2>(a) < get<2>(b);
    });
    REP(i, N - 1) {
