typedef long long ll;
typedef pair<ll, ll> P;
typedef vector<vector<P>> vp;

// input
int N;
vector<int> X, Y;

const ll INF = 1e15;

vector<P> xlist, ylist;
vp link;
vector<ll> w;
vector<bool> vis;
priority_queue<P, vector<P>, greater<P>> pq;


void input() {
    cin >> N;
    X = Y = vector<int>(N);
    rep(i, N) cin >> X[i] >> Y[i];
}


ll solve() {
    w = vector<ll>(N, INF);
    vis = vector<bool>(N, false);
    w[0] = 0;
    pq.push(P(0, 0));
    int n = 0;
    while (!pq.empty()) {
        ll cost = pq.top().first;
        int s = pq.top().second;
        pq.pop();
        if (vis[s]) continue;
        vis[s] = true;
        n++;
        if (n == N) break;
        for (P p : link[s]) {
            ll c = p.second;
            int t = p.first;
            if (c < w[t]) {
                w[t] = c;
                pq.push(P(c, t));
            }
        }
    }
    ll ret = 0;
    rep(i, N) ret += w[i];
    return ret;
}


int main() {
    input();
    rep(i, N) {
        xlist.push_back(P(X[i], i));
        ylist.push_back(P(Y[i], i));
    }
    sort(xlist.begin(), xlist.end());
    sort(ylist.begin(), ylist.end());
    link = vp(N);
    rep(i, N - 1) {
        int s, t, v;
        s = xlist[i].second;
        t = xlist[i + 1].second;
        v = xlist[i + 1].first - xlist[i].first;
        link[s].push_back(P(t, v));
        link[t].push_back(P(s, v));
        s = ylist[i].second;
        t = ylist[i + 1].second;
        v = ylist[i + 1].first - ylist[i].first;
        link[s].push_back(P(t, v));
        link[t].push_back(P(s, v));
    }
    ll ans = solve();
    cout << ans << endl;
}

