        if(a.x == b.x){
            return a.y < a.y;
        }else{
            return a.x < b.x;
        }
    }

    static bool sortByY(Point a, Point b){
        if(a.y == b.y){
            return a.x < a.x;
        }else{
            return a.y < b.y;
        }
    }
};

struct Edge{
