    rep(i,N-1) {
        edges.push_back(make_pair(x[i + 1].first - x[i].first, make_pair(x[i].second, x[i + 1].second)));
        edges.push_back(make_pair(y[i + 1].first - y[i].first, make_pair(y[i].second, y[i + 1].second)));
    }

    sort(edges.begin(), edges.end());
    UnionFind tree(N);
    long long ans = 0;
    rep(i,edges.size()) {
        if (!tree.same(edges[i].second.first, edges[i].second.second)) {
            ans += edges[i].first;
            tree.unite(edges[i].second.first, edges[i].second.second);
