struct UF{ //O(loga(n))
    int n;
    int m;
    vi d, r;
    UF(int n) : n(n), m(n), d(n, -1), r(n, 0){};
    int root(int i){
        if(d[i] < 0) return i;
        return d[i] = root(d[i]);
    }
    bool same(int x, int y){
        return root(x) == root(y);
    }
    bool unite(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y) return false;

        if(r[x] < r[y]) swap(x, y);
        else if(r[x] == r[y]) r[x]++;
        d[x] += d[y];
        d[y] = x;
        --m;
        return true;
    }
    int size(int i){
        return -d[root(i)];
    }
    int size() {
        return m;
    }
};

int main(){
    ll n;
    cin >> n;
    vl x(n), y(n);
    rep(i, n) cin >> x[i] >> y[i];
    vl id(n);
    rep(i, n) id[i] = i;
    auto calc = [&](int i, int j) {
        return min(abs(x[i]-x[j]), abs(y[i] - y[j]));
    };
    using Edge = tuple<ll, int, int>;
    vector<Edge> es;
    sort(all(id), [&](int i, int j){return x[i] < x[j];});
    rep(i, n-1) es.emplace_back(calc(id[i], id[i+1]), id[i], id[i+1]);
    sort(all(id), [&](int i, int j){return y[i] < y[j];});
    rep(i, n-1) es.emplace_back(calc(id[i], id[i+1]), id[i], id[i+1]);
    sort(all(es));
    UF uf(n);
    ll ans = 0;
    for(auto&& e:es) {
        ll x, y, z;
        tie(z, x, y) = e;
        if(uf.same(x, y)) continue;
        uf.unite(x, y);
        ans += z;
    }
    cout << ans << endl;
    return 0;
}

