struct UnionFind {
    vector<int> par, w;

    UnionFind(int n) : par(n, -1), w(n, 0) { }
    void init(int n) { par.assign(n, -1); w.assign(n, 0); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) {
            ++w[x];
            return false;
        }
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        w[x] += w[y];
        ++w[x];
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }

    int wei(int x) {
        return w[root(x)];
    }
};

//密グラフのMSTは考えるべき辺の本数を減らす
//MST　は　O(ElogV)

void solve() {
	int n; cin >> n;
    vector<ll> x(n), y(n);
    rep(i, n) cin >> x[i] >> y[i];

    using edge = pair<ll, LP>;
    vector<edge> edges;

    vector<int> ids(n);
    iota(all(ids), 0);
    sort(all(ids), [&](int i, int j){ return x[i] > y[j];});
    rep(i, n - 1) {
        int u = ids[i], v = ids[i+1];
        edges.push_back(edge(x[u] - x[v], LP(u, v)));
    }

    sort(all(ids), [&](int i, int j){ return y[i] > y[j];});
    rep(i, n - 1) {
        int u = ids[i], v = ids[i+1];
        edges.push_back(edge(y[u] - y[v], LP(u, v)));
    }

    sort(all(edges));
    UnionFind uf(n);
    ll res = 0;
    for(auto e: edges) {
        int u = e.sc.fr, v = e.sc.sc;
        ll cost = e.fr;
        if(uf.issame(u, v)) continue;
        uf.merge(u, v);
        res += cost;
    }
    cout << res << endl;
}

