struct UnionFind {
    vector<int> par; 
    UnionFind(int N) : par(N){for(int i = 0; i < N; i++) par[i] = i;}
    int root(int x) {if(par[x] == x)return x;return par[x]=root(par[x]);}
    void unite(int x, int y) 
    {
        int rx = root(x);int ry = root(y);
        if (rx == ry) return;
        par[rx] = ry;
    }
    bool same(int x, int y) 
    {
        int rx = root(x);int ry = root(y);
        return rx == ry;
    }
};

int main()
{
  int N;scanf("%d",&N);
  vector<pair<int,int>> x,y;
  for(int X,Y,i=0;i<N;i++)
  {
    scanf("%d %d",&X,&Y);
    x.push_back(make_pair(X,i));
    y.push_back(make_pair(Y,i));
  }
  sort(x.begin(),x.end());sort(y.begin(),y.end());
  vector<tuple<int,int,int>> G;
  for(int i=1;i<N;i++)
  {
