void union_init(int n){
  for(int i=0;i<n;i++){
    union_data[i] = i;
    union_weight[i] = 1;
  }
}

int union_root(int x){
  int tmp = x;
  while(x!=union_data[x]){
    x = union_data[x];
  }
  while(tmp != union_data[tmp]){
    tmp = union_data[tmp];
    union_data[tmp] = x;
  }
  return x;
}

bool union_eq(int x,int y){
  return union_root(x) == union_root(y);
}

int union_join(int x, int y){
  if(union_eq(x,y)) return 0;
  if(union_weight[y] > union_weight[x]){
    union_weight[union_root(x)] += union_weight[union_root(y)];
    union_data[union_root(y)] = union_root(x);
  } else {
    union_weight[union_root(y)] += union_weight[union_root(x)];
    union_data[union_root(x)] = union_root(y);
  }
  return 0;
}

int union_size(int x){
  return union_weight[union_root(x)];
}

