struct Town
{
	ll i = 0;
	ll x = 0;
	ll y = 0;
};

auto NyaSortX = [](const Town& l, const Town& r)
{	// 降順は演算子>, 昇順は演算子<, if順の優先でソートされる
	if (l.x != r.x) return l.x < r.x;
	return l.y < r.y;
};

auto NyaSortY = [](const Town& l, const Town& r)
{	// 降順は演算子>, 昇順は演算子<, if順の優先でソートされる
	if (l.y != r.y) return l.y < r.y;
	return l.x < r.x;
};

int main(void)
{
	ll n; cin >> n;
	vt<Town> town;
	rep(i, 0, n)
	{
		ll x, y; cin >> x >> y; x--, y--;
		town.push_back({ i,x,y });
	}
	vector<vector<pair<long long, long long>>> lg(n);

	sort(all(town), NyaSortX);
	rep(i, 1, Size(town))
	{
		lg[town[i - 1].i].push_back({ town[i].i, abs(town[i].x - town[i - 1].x) });
		lg[town[i].i].push_back({ town[i - 1].i, abs(town[i].x - town[i - 1].x) });
	}

	sort(all(town), NyaSortY);
	rep(i, 1, Size(town))
	{
		lg[town[i - 1].i].push_back({ town[i].i, abs(town[i].y - town[i - 1].y) });
		lg[town[i].i].push_back({ town[i - 1].i, abs(town[i].y - town[i - 1].y) });
	}

	cout << GT_Kruskal::Run(lg);
	return 0;
}

