// http://www.prefield.com/algorithm/container/union_find.html
struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

int main()
{
    int N; cin >> N;
    vector<pair<int, int>> cities(N);
    for (int i = 0; i < N; i++) {
        int x, y; cin >> x >> y;
        cities[i] = {x, y};
    }
    map<int, vector<int>> xs, ys;
    for (int i = 0; i < N; i++) {
        int x, y;
        tie(x, y) = cities[i];
        xs[x].emplace_back(i);
        ys[y].emplace_back(i);
    }
    vector<tuple<int, int, int>> edges;
    #define EDGE(i, j) do { \
        int a, b, c, d; \
        tie(a, b) = cities[i]; \
        tie(c, d) = cities[j]; \
        edges.emplace_back(min(abs(a-c), abs(b-d)), i, j); \
    } while (0)
    for (auto it = xs.begin(); it != xs.end(); ++it) {
        for (int i = 0; i < it->second.size(); i++) {
            for (int j = i + 1; j < it->second.size(); j++) {
                EDGE(i, j);
            }
        }
        if (next(it) != xs.end()) {
            EDGE(it->second[0], next(it)->second[0]);
        }
    }
    for (auto it = ys.begin(); it != ys.end(); ++it) {
        for (int i = 0; i < it->second.size(); i++) {
            for (int j = i + 1; j < it->second.size(); j++) {
                EDGE(i, j);
            }
        }
        if (next(it) != ys.end()) {
            EDGE(it->second[0], next(it)->second[0]);
        }
    }
    sort(edges.begin(), edges.end());
    edges.erase(unique(edges.begin(), edges.end()), edges.end());

    UnionFind uf(N);
    int first = get<1>(edges[0]);
    int cost = 0;
    for (int i = 0; i < edges.size() && uf.size(first) < N; i++) {
        int c, x, y;
        tie(c, x, y) = edges[i];
        if (uf.findSet(x, y)) continue;
        uf.unionSet(x, y);
        cost += c;
    }
    cout << cost << endl;
    return 0;
}

