struct Point
{
    int index;
    int x, y;

    int ConnectionCost(const Point &other) const
    {
        return min(abs(x - other.x), abs(y - other.y));
    }
};

struct CmpX
{
    bool operator()(const Point &a, const Point &b) const
    {
        if (a.x == b.x) {
            return a.y < b.y;
        }
        return a.x < b.x;
    }
};

struct CmpY
{
    bool operator()(const Point &a, const Point &b) const
    {
        if (a.y == b.y) {
            return a.x < b.x;
        }
        return a.y < b.y;
    }
};

struct Edge
{
    int index1;
    int index2;
    int cost;

    Edge(const Point &a, const Point &b)
        : index1(a.index), index2(b.index), cost(a.ConnectionCost(b)) {}

    bool operator<(const Edge &other) const { return cost < other.cost; }
};

class DisjointSet
{
public:
    DisjointSet(int size) : fathers_(size, -1) {}

    void Unite(int a, int b);

    bool SameGroup(int a, int b) { return Root(a) == Root(b); }

private:
    int Root(int node);

    vector<int> fathers_;
};

void DisjointSet::Unite(int a, int b)
{
    auto root_a = Root(a);
    auto root_b = Root(b);

    if (root_a != root_b) {
        fathers_[root_b] = root_a;
    }
}

int DisjointSet::Root(int node)
{
    if (fathers_[node] == -1) {
        return node;
    }
    return fathers_[node] = Root(fathers_[node]);
}

vector<Edge> BuildEdges(vector<Point> &points)
{
    vector<Edge> edges;

    sort(points.begin(), points.end(), CmpX());
    for (size_t i = 0; i + 1 < points.size(); i += 1) {
        edges.push_back(Edge(points[i], points[i + 1]));
    }

    sort(points.begin(), points.end(), CmpY());
    for (size_t i = 0; i + 1 < points.size(); i += 1) {
        edges.push_back(Edge(points[i], points[i + 1]));
    }

    return edges;
}

int64_t FindCost(vector<Edge> &edges, int n)
{
    DisjointSet set(n);
    int64_t cost = 0;

    sort(edges.begin(), edges.end());
    for (const auto &e : edges) {
        if (!set.SameGroup(e.index1, e.index2)) {
            cost += e.cost;
            set.Unite(e.index1, e.index2);
        }
    }
    return cost;
}

