{
    int n;
    cin >> n;

    vector<Point> points(n);
    for (auto i = 0; i < n; i += 1) {
        points[i].index = i;
        cin >> points[i].x;
        cin >> points[i].y;
    }

    auto edges = BuildEdges(points);
    auto cost = FindCost(edges, n);

    cout << cost << "\n";
    return 0;
}

