struct UnionFind{
    int ElementCount[100000],Adress[100001];
    void unite(int a ,int b) {
        if (!is_Linked(a) && !is_Linked(b)) {
            ElementCount[a] = 2;
            Adress[a] = Adress[b] = a;
        } else if (!is_Linked(a)) {
            int b_root = find(b);
            ElementCount[b_root]++;
            Adress[a] = b_root;
        } else if (!is_Linked(b)) {
            int a_root = find(a);
            ElementCount[a_root]++;
            Adress[b] = a_root;
        } else {
            int a_root = find(a),b_root = find(b);
            if (a_root != b_root) {
                ElementCount[a_root] += ElementCount[b_root];
                Adress[b_root] = a_root;
            }
        }
    }
    int find(int a) {
        if (a == Adress[a]) return Adress[a];
        else {
            Adress[a] = find(Adress[a]);
            return Adress[a];
        }
    }
    int size(int a) {
        int root = find(a);
        return ElementCount[root];
    }
    bool is_Linked(int a) {
        int root = find(a);
        if (ElementCount[root]) return true;
        else return false;
    }
    /*
     * ElementCount : 属するグループの要素数
     * Adress : rootの番号
     * unite : 併合
     * find : aのrootを返す
     * size : aのrootのElementCountを返す
     * is_Linked : aがグループに所属しているかをElementCountで判断する
     *
     * */
};


