  vector<int> order_y(N);
  iota(ALL(order_x), 0);
  iota(ALL(order_y), 0);

  auto comp_x = [=](int a, int b){
    return x[a] < x[b];
  };
  auto comp_y = [=](int a, int b){
    return y[a] < y[b];
  };

  sort(ALL(order_x), comp_x);
  sort(ALL(order_y), comp_y);

  vector<edge> edges;

  REP(i, N-1){
    int from = order_x[i];
    int to = order_x[i+1];
    edges.push_back({from, to, abs(x[from]-x[to])});
  }

  REP(i, N-1){
    int from = order_y[i];
    int to = order_y[i+1];
    edges.push_back({from, to, abs(y[from]-y[to])});
  }

