using namespace std;
using ll = int64_t;
using pint = pair<int, int>;
using ppint = pair<int, pair<int, int>>;

struct UnionFind
{
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N)
    { // 最初は全てが根であるとして初期化
        for (int i = 0; i < N; i++)
            par[i] = i;
    }

    int root(int x)
    { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x)
            return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y)
    {                     // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry)
            return;   //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y)
    { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main()
{
    int n;
    cin >> n;
    vector<pint> x(n), y(n);
    rep(i, n)
    {
        int X, Y;
        cin >> X >> Y;
        x[i] = pint(X, i);
        y[i] = pint(Y, i);
    }

    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    vector<ppint> dx(n - 1), dy(n - 1);
    rep(i, n - 1)
    {
        dx[i] = ppint(abs(x[i + 1].first - x[i].first), pint(x[i].second, x[i + 1].second));
        dy[i] = ppint(abs(y[i + 1].first - y[i].first), pint(y[i].second, y[i + 1].second));
    }

    sort(dx.begin(), dx.end());
    sort(dy.begin(), dy.end());

    int rx = 0, ry = 0;
    UnionFind tree(n);

    ll ans = 0;

    while (1)
    {
        if (rx == n - 1 && ry == n - 1)
            break;
        int ddx = INT32_MAX, ddy = INT32_MAX;
        if (rx != n - 1)
            ddx = dx[rx].first;
        if (ry != n - 1)
            ddy = dy[ry].first;
        int a, b, d;
        if (ddx < ddy)
        {
            a = dx[rx].second.first;
            b = dx[rx].second.second;
            ++rx;
            d = ddx;
        }
        else
        {
            a = dy[ry].second.first;
            b = dy[ry].second.second;
            ++ry;
            d = ddy;
        }
        if (!tree.same(a, b))
        {
            tree.unite(a, b);
            ans += d;
        }
    }
    cout << ans << endl;
}

