ll E; // 辺の本数

struct edge{ ll u, v, cost;};
edge es[MAX_E];

struct UnionFind {
  vector<ll> d;
  UnionFind(ll n): d(n,-1) {}
  ll find(ll x) {
    if (d[x] < 0) return x;
    return d[x] = find(d[x]);
  }
  bool unite(ll x, ll y) {
    x = find(x); y = find(y);
    if (x == y) return false;
    if (d[x] > d[y]) swap(x,y); // -d[x] < -d[y]
    d[x] += d[y];
    d[y] = x;
    return true;
  }
  bool same(ll x, ll y) { return find(x) == find(y);}
  ll size(ll x) { return -d[find(x)];}
};

// クラスカル法: 最小全域木のコストの合計値を返す O(|E|log|V|)
ll kruskal() {
  auto comp = [](const edge& e1, const edge& e2) {
    return e1.cost < e2.cost;
  };
  sort(es, es + E, comp);
  UnionFind uf(MAX_V);
  ll res = 0;
  for (ll i = 0; i < E; ++i) {
    edge e = es[i];
    if (!uf.same(e.u, e.v)) {
      uf.unite(e.u, e.v);
      res += e.cost;
    }
  }
  return res;
}

