  rep(i,n-1) {
    es[2*i] = (edge){get<2>(p[i]), get<2>(p[i+1]), abs(get<0>(p[i])-get<0>(p[i+1]))};
    es[2*i+1] = (edge){get<2>(q[i]), get<2>(q[i+1]), abs(get<1>(q[i])-get<1>(q[i+1]))};
  }
  ll ans = kruskal();
  cout << ans << endl;
