class UnionFind {
    private: 
        vector<int> par;
        vector<int> rank;
        vector<int> cnt;

    public:
        UnionFind(int n);
        int find(int x);
        void unite(int x, int y);
        bool same(int x, int y);
        int count(int x);
        void printStatus();
};

UnionFind::UnionFind(int n) {
    for (int i = 0; i < n; i++) {
        par.push_back(i);
        rank.push_back(0);
        cnt.push_back(1);
    }
}
int UnionFind::find(int x) {
    if (par[x] == x) return x;
    else return par[x] = find(par[x]);
}
void UnionFind::unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rank[x] < rank[y]) {
        cnt[y] += cnt[x];
        par[x] = y;
    } else {
        cnt[x] += cnt[y];
        par[y] = x;
        if (rank[x] == rank[y]) rank[x]++;
    }
}
bool UnionFind::same(int x, int y) {
    return find(x) == find(y);
}
int UnionFind::count(int x) {
    return cnt[find(x)];
}
void UnionFind::printStatus() {
    printf("----------------\n");
    for (int i = 0; i < par.size(); i++) {
        printf("[node %d]: parent = %d, rank = %d, count = %d\n", i, par[i], rank[i], cnt[i]);
    }
}

struct edge { int u, v, cost; };
bool comp_edge(const edge& e1, const edge& e2) {
    return e1.cost < e2.cost;
}

long long kruskal (vector<edge> edges, int V) {
    sort(edges.begin(), edges.end(), comp_edge);
    UnionFind u_tree(V);
    long long res = 0;
    for (int i = 0; i < edges.size(); i++) {
        if (!u_tree.same(edges[i].u, edges[i].v)) {
            u_tree.unite(edges[i].u, edges[i].v);
            res += edges[i].cost;
        }
    }

    return res;
}

