class  UnionFind {
private:
	vector<int>par;
public:
	UnionFind(int n) {
		for (int i = 0; i < n; i++) {
			par.push_back(-1);
		}
	}

	int root(int x) {
		if (par[x] < 0) return x;
		else return par[x] = root(par[x]);
	}

	bool same(int x, int y) {
		return root(x) == root(y);
	}

	void unite(int x, int y) {
		x = root(x), y = root(y);
		if (x == y) return;
		if (par[x] > par[y]) swap(x, y);
		par[x] += par[y];
		par[y] = x;
		return;
	}
};

struct Edge {
	int a, b, cost;
	bool operator<(const Edge& o)const {
		return cost < o.cost;
	}
};

class Graph {
public:
	vector<Edge>es;

	int kruscal(int n) {
		sort(es.begin(), es.end());
		UnionFind uf(n);
		int min_cost = 0;
		for (int ei = 0; ei < es.size(); ei++) {
			Edge ed = es[ei];
			if (!uf.same(ed.a, ed.b)) {
				min_cost += ed.cost;
				uf.unite(ed.a, ed.b);
			}
		}
		return min_cost;
	}
};

