    yl[i] = P(y, i);
  }
  Sort(xl);
  Sort(yl);

  rep(i, n - 1) {
    ll posi = xl[i].first;
    ll posip1 = xl[i + 1].first;
    ll wt = abs(posi - posip1);
    ll s = xl[i].second;
    ll t = xl[i + 1].second;
    eds.push_back(T(wt, s, t));
  }

  rep(i, n - 1) {
    ll posi = yl[i].first;
    ll posip1 = yl[i + 1].first;
    ll wt = abs(posi - posip1);
    ll s = yl[i].second;
    ll t = yl[i + 1].second;
    eds.push_back(T(wt, s, t));
  }

  // Kruscal's algorithm
  Sort(eds);  
  UnionFind uf(n);
  ll ans = 0;
  for (auto e : eds) {
    ll wt, s, t;
    tie(wt, s, t) = e;
    if(!uf.same(s, t)){
      ans += wt;
      uf.unite(s, t);
    }
  }

  cout << ans << endl;

  return 0;
}

