struct UF {
	int n;
	vector<int>d;
	UF() {}
	UF(int n) :n(n), d(n, -1) {}

	int root(int v) {
		if (d[v] < 0) { return v; }
		return d[v] = root(d[v]);
	}
	bool unite(int x,int y) {
		x = root(x);
		y = root(y);
		if (x == y) { return false; }
		if (size(x) < size(y)) { swap(x, y); }
		d[x] += d[y];
		d[y] = x;
		return true;
	}
	int size(int v) { return -d[root(v)]; }
};

vector<P>xs;
vector<P>ys;
vector<P>ex;

priority_queue<P, vector<P>, greater<P> > que;

int main(){

	int N;

	scanf("%d",&N);

	UF t(N+5);

	int i;

	for(i=0;i<N;i++){
		int x,y;
		scanf("%d %d",&x,&y);
		xs.push_back(P(x,i));
		ys.push_back(P(y,i));
	}

	sort(xs.begin(),xs.end());
	sort(ys.begin(),ys.end());

	for(i=0;i<N-1;i++){
		ex.push_back(P(xs[i].second,xs[i+1].second));
		que.push(P(abs(xs[i].first-xs[i+1].first),ex.size()-1));
	}
	for(i=0;i<N-1;i++){
		ex.push_back(P(ys[i].second,ys[i+1].second));
		que.push(P(abs(ys[i].first-ys[i+1].first),ex.size()-1));
	}

	int ans=0;

	while(!que.empty()){
		P e = que.top();
		que.pop();
