const int mxN = 1e5;
int link[mxN];

int find(int x) {
    if (link[x] == x) return x;
    return find(link[x]);
}

void solve() {
    int n;
    read(n);
    vt<node> a(n);

    FOR(n) {
        read(a[i].x, a[i].y);
        a[i].i = i;
    }

    vt<edge> E;

    sort(all(a), [](node a, node b) {
        return a.x < b.x;
    });

    FOR(i, 1, n) {
        edge e = {a[i].x - a[i - 1].x, a[i - 1].i, a[i].i};
        E.pb(e);
    }

    sort(all(a), [](node a, node b) {
        return a.y < b.y;
    });

    FOR(i, 1, n) {
        edge e = {a[i].y - a[i - 1].y, a[i - 1].i, a[i].i};
        E.pb(e);
    }

    sort(all(E));

    int ans = 0;
    FOR(n) {
        link[i] = i;
    }

    EACH(x, E) {
        if (find(x.x) != find(x.y)) {
            ans += x.w;
            link[find(x.x)] = link[find(x.y)];
        }
    }

    print(ans);
}

