struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main(void){
    long long N;
    cin >> N;
    vector<vector<long long>> xy(2, vector<long long>(N)), sorted_xy(2, vector<long long>(N));
    vector<vector<long long>> sorted_index_xy(2, vector<long long>(N));
    iota(sorted_index_xy[0].begin(), sorted_index_xy[0].end(), 0);
    iota(sorted_index_xy[1].begin(), sorted_index_xy[1].end(), 0);

    for(int i = 0; i < N; i++){
        long long x, y;
        cin >> x >> y;
        xy[0][i] = x; xy[1][i] = y;
    }

    sort(sorted_index_xy[0].begin(), sorted_index_xy[0].end(), [&xy](size_t i1, size_t i2) {
        return xy[0][i1] < xy[0][i2];
    });
    sort(sorted_index_xy[1].begin(), sorted_index_xy[1].end(), [&xy](size_t i1, size_t i2) {
        return xy[1][i1] < xy[1][i2];
    });

    vector<vector<long long>> edges(2*N-2, vector<long long>(3, 0));
    for(int i = 0; i < N-1; i++){
        for(int j = 0; j < 2; j++){
            edges[2*i+j][0] = sorted_index_xy[j][i];
            edges[2*i+j][1] = sorted_index_xy[j][i+1];
            edges[2*i+j][2] = abs(xy[j][sorted_index_xy[j][i]] - xy[j][sorted_index_xy[j][i+1]]);
        }
    }

    sort(edges.begin(), edges.end(), [](vector<long long> i1, vector<long long> i2) {
        return i1[2] < i2[2];
    });

    UnionFind tree(N);
    long long cost = 0;
    for(auto edge:edges){
        if(!tree.same(edge[0], edge[1])){
            tree.unite(edge[0], edge[1]);
            cost += edge[2];
        }
    }

    cout << cost << endl;
}

