struct UnionFind{
    vector<int> par;

    UnionFind(int n) : par(n,-1) { }
    void init(int n) { par.assign(n,-1); }

    int root(int x){
        if(par[x]<0) return x;
        else return par[x]=root(par[x]);
    }

    bool issame(int x,int y){
        return root(x)==root(y);
    }

    bool merge(int x,int y){
        x=root(x);
        y=root(y);
        if(x==y) return false;
        if(par[x]>par[y]) swap(x,y);
        par[x]+=par[y];
        par[y]=x;
        return true;
    }

    int size(int x){
        return -par[root(x)];
    }
};

int main(){
    int n;
    cin>>n;
    vector<pair<ll,int>> x(n),y(n);

    rep(i,n){
        int a,b;
        cin>>a>>b;
        x[i]={a,i};
        y[i]={b,i};
    }

    sort(all(x));
    sort(all(y));

    // Kruskal法
    // O(ElogE)
    // Kruskal 法で使用する枝
    using pint = pair<int,int>;
    using Edge = pair<ll, pint>;
    vector<Edge> edges;
    //枝入力
    rep(i,n-1) {
        edges.push_back({x[i+1].first-x[i].first, pint(x[i+1].second, x[i].second)});
        edges.push_back({y[i+1].first-y[i].first, pint(y[i+1].second, y[i].second)});
    }
    // Kruskal 法
    sort(all(edges));
    // unionfindのスニペット読み込んで
    UnionFind uf(n);
    ll res = 0;
    for (auto e : edges) {
        int u = e.second.first, v = e.second.second;
        ll cost = e.first;
        if (uf.issame(u, v)) continue;
        uf.merge(u, v);
        res += cost;
    }
    cout << res << endl;
}

