{
    int n;
    cin >> n;

    vector<Node> nodes;
    // pair<cost, dst>
    vector<vector<pair<int, int> > > cost(n);
    Node node;
    for (int i = 0; i < n; i++) {
        node.id = i;
        cin >> node.x >> node.y;
        nodes.push_back(node);
    }
    build_table(nodes, cost);
    cout << prim(cost) << endl;
    return 0;
}

