      return find(x) == find(y);
    }
};
int kruskal(edges<int>& es){
  sort(es.begin(), es.end(), compByCost<int>);
  union_find u(es.size());
  int res = 0;
  rep(i, es.size()){
    edge<int> e = es[i];
    if(!u.same(e.from, e.to)){
      u.unite(e.from, e.to);
      res += e.cost;
    }
  }
  return res;
}

