#include <bits/stdc++.h>
using namespace std;

vector<int> parent;

int getRoot(int v) {
  if (parent[v] == v) return v;
  return parent[v] = getRoot(parent[v]);
}

bool isSame(int v0, int v1) {
  return getRoot(v0) == getRoot(v1);
}

void unite(int v0, int v1) {
  int root0 = getRoot(v0);
  int root1 = getRoot(v1);
  if (root0 != root1) parent[root0] = root1;
}

int main(){
  int N;
  cin >> N;
  parent.resize(N);
  vector<pair<int, int>> x(N);
  vector<pair<int, int>> y(N);
  for (int i = 0; i < N; ++i) {  // For each vertex.
    int x_tmp, y_tmp;
    cin >> x_tmp >> y_tmp;
    x[i] = make_pair(x_tmp, i);
    y[i] = make_pair(y_tmp, i);
  }
  sort(x.begin(), x.end());
  sort(y.begin(), y.end());
  vector<pair<int, pair<int, int>>> edges;
  for (int i = 1; i < N; ++i) {
    auto index_x = make_pair(x[i].second, x[i - 1].second);
    auto value_x = abs(x[i].first - x[i - 1].first);
    auto pair_x = make_pair(value_x, index_x);
    edges.push_back(pair_x);
    auto index_y = make_pair(y[i].second, y[i - 1].second);
    auto value_y = abs(y[i].first - y[i - 1].first);
    auto pair_y = make_pair(value_y, index_y);
    edges.push_back(pair_y);
  }
  sort(edges.begin(), edges.end());  // ascending edge length.
  for (int i = 0; i < N; ++i) parent[i] = i;  // no edges.
  int distance = 0;
  for (int i = 0; i < edges.size(); ++i) {
    auto e = edges[i];
    auto next = e.second.first;
    auto prev = e.second.second;
    if (!isSame(next, prev)) {  // Connects components if not connected.
      unite(next, prev);
      distance += e.first;
    }
  }
  cout << distance << endl;
}

