    {
        if (p[x] < 0) return x;
        else return p[x] = findSet(p[x]);
    }
};

s64 kruskal(vector< pair<s64, P> >& edge)
{
    int n = edge.size();
    UnionFind uf(n);
    sort(edge.begin(), edge.end());
    s64 ret = 0;
    rep (i, n)
    {
        int u, v;
        s64 c = edge[i].first;
        u = edge[i].second.first;
        v = edge[i].second.second;
        if (!uf.same(u, v))
        {
            ret += c;
            uf.unite(u, v);
        }
    }
    return ret;
}

