int fin(int v)
{
    if(par[v]==v) return v;
    return par[v] = fin(par[v]);
}

bool join(int a, int b)
{
    a = fin(a); b = fin(b);
    if(a==b) return false;
    if(len[a] < len[b]) swap(a,b);
    len[a] += len[b];
    par[b] = a;
    return true;
}

