struct Edge{
    ll from;
    ll to;
    ll cost;
};

struct UnionFind{
    vector<int> parent;
    vector<int> s;

    UnionFind(int n){
        parent.resize(n);
        s.resize(n, 1);
        for(int i = 0; i < n; i++) parent[i] = i;
    }

    int root(int node){
        if(parent[node] == node){
            return node;
        } else {
            return parent[node] = root(parent[node]);
        }
    }

    void unite(int x, int y){
        int rootx = root(x);
        int rooty = root(y);
        if(rootx == rooty) return;
        if(s[rootx] < s[rooty]) swap(rootx, rooty);
        s[rootx] += s[rooty];
        parent[rooty] = rootx;
    }

    bool isSame(int x, int y){
        return root(x) == root(y);
    }

    int size(int x){
        return s[root(x)];
    }
};

ll kruskal(vector<Edge> &e, ll n){
    sort(e.begin(), e.end(), [](const Edge &a, const Edge &b){
        return a.cost < b.cost;
    });
    UnionFind uf(n);
    ll res = 0;
    for(int i = 0; i < e.size(); i++){
        if(!uf.isSame(e[i].from, e[i].to)){
            res += e[i].cost;
            uf.unite(e[i].from, e[i].to);
        }
    }
    return res;
}


