const int MAX_N = 100007;

struct uft{
    int par[MAX_N], rank[MAX_N], size[MAX_N];
    void init(int n){
        rep(i,n){
            par[i] = i;
            rank[i] = 0;
            size[i] = 1;
        }
        return ;
    }

    int find(int x){
        if(par[x]==x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;
        if(rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if(rank[x] == rank[y])  ++rank[x];
        }
        size[x] = size[y] = size[x] + size[y];
        return ;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }
};

