struct MyMain {
	int N = in;
	pints C = in(N);

	void Run() {
		ints xSortedIndexs(N);
		ints ySortedIndexs(N);
		REP(i, N) {
			xSortedIndexs[i] = i;
			ySortedIndexs[i] = i;
		}

		auto calcCost = [&](pint a, pint b) -> int {
			return min(abs(a.x - b.x), abs(a.y - b.y));
		};

		auto predX = [&](int a, int b) {
			return C[a].x < C[b].x;
		};
		auto predY = [&](int a, int b) {
			return C[a].y < C[b].y;
		};
		xSortedIndexs.sort(predX);
		ySortedIndexs.sort(predY);

		arr<Kruskal::Edge> edges;
		REP(i, N - 1) {
			{
				Kruskal::Edge edge;
				edge.a = xSortedIndexs[i];
				edge.b = xSortedIndexs[i + 1];
				edge.cost = calcCost(C[edge.a], C[edge.b]);
				edges.pb(edge);
			}
			{
				Kruskal::Edge edge;
				edge.a = ySortedIndexs[i];
				edge.b = ySortedIndexs[i + 1];
				edge.cost = calcCost(C[edge.a], C[edge.b]);
				edges.pb(edge);
			}
		}

		auto k = Kruskal(N, edges);

		out << k.totalCost;
	}
};

