    }
};
using Edges = vector<Edge>;
Edges E;

ll kruscal(ll n, Edges E){
    ll res = 0;
    sort(all(E));
    UnionFind uf(n);
    for(auto v:E) if(uf.merge(v.from, v.to)) res += v.cost; 
    return res;
}

