class unionfind
{
public:
  vector<int> parent;

  unionfind(int N)
  {
    parent = vector<int>(N, -1);
  }

  int root(int X)
  {
    if (parent.at(X) < 0) return X;
    return parent.at(X) = root(parent.at(X));
  }

  int size(int X)
  {
    return -parent.at(root(X));
  }

  bool unite(int X, int Y)
  {
    int x = root(X);
    int y = root(Y);
    if (x == y) return false;

    if (size(x) < size(y)) swap(x, y);
    parent.at(x) += parent.at(y);
    parent.at(y) = x;
    return true;
  }
};

