class UnionFind{
    private:
    vector<int> par; // 親
    vector<int> rank; // 木の深さ
    vector<long long> sizes_; 
    int num_of_conn;

    public:
    // n要素で初期化
    UnionFind(int n) {
        par = vector<int>(n);
        rank = vector<int>(n);
        sizes_ = vector<long long>(n);
        for (int i = 0; i < n; i++) {
            par[i] = i;
            rank[i] = 0;
            sizes_[i] = 1;
        }
        num_of_conn = n;
    }

    // 木の根を求める
    int find(int x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    long long getSize(int x){
        return sizes_[par[x]];
    }

    // xとyの属する集合を併合
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        auto sizex = getSize(x);
        auto sizey = getSize(y);
        if (x == y) return;
        if (rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (rank[x] == rank[y]) rank[x]++;
        }
        num_of_conn--;
        sizes_[find(x)] = sizex + sizey;
    }

    // xとyが同じ集合に属するか否か
    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int numOfConnected(){
        return num_of_conn;
    }
};


