    vec<Road> roads;

    sort(towns.begin(), towns.end(), [](Town a, Town b){return a.x < b.x;});  // aがbより先頭にくるときtrueになるように。
    for(int i=0; i < towns.size() - 1; i++){
        roads.push_back(Road{towns[i].id, towns[i+1].id, towns[i+1].x - towns[i].x});
    }

    sort(towns.begin(), towns.end(), [](Town a, Town b){return a.y < b.y;});  // aがbより先頭にくるときtrueになるように。
    for(int i=0; i < towns.size() - 1; i++){
        roads.push_back(Road{towns[i].id, towns[i+1].id, towns[i+1].y - towns[i].y});
    }

    // kruskal
    // Kruskal
    auto cmp = [](Road left, Road right){
        // leftが先に出てくるときfalse
        return left.d > right.d;
    };
    priority_queue<Road, vector<Road>, decltype(cmp)> que(cmp);
    for(auto iter: roads){
        que.push(iter);
    }
    UnionFind uf(towns.size());
    ll res = 0;
    while(!que.empty()){
        auto popped = que.top();
        que.pop();

        // もしだめならやめる
        if(uf.same(popped.from, popped.to)){
            continue;
        }

        // 訪問
        uf.unite(popped.from, popped.to);

        // 追加
        res += popped.d;
    }

    cout << res << endl;

}

