    UnionFind(){}
    UnionFind(int sz):n(sz),r(sz,1),p(sz,0){iota(p.begin(),p.end(),0);}
    int find(int x){
      return (x==p[x]?x:p[x]=find(p[x]));
    }
    bool same(int x,int y){
      return find(x)==find(y);
    }
    void unite(int x,int y){
      x=find(x);y=find(y);
      if(x==y) return;
      if(r[x]<r[y]) swap(x,y);
      r[x]+=r[y];
      p[y]=x;
    }
  };

  struct edge{
    int from,to,cost,used;
    edge(){}
    edge(int from,int to,int cost):
      from(from),to(to),cost(cost),used(0){}
    bool operator<(const edge& e) const{
      return cost<e.cost;
    }
  };

  int n;
  vector<edge> edges;

  Kruskal(){}
  Kruskal(int sz):n(sz){}

  void add_edge(int u,int v,int c){
    edges.emplace_back(u,v,c);
  }

  void input(int n, int offset=0){
    rep(i, 1, n){
      add_edge(get<0>(sx[i]), get<0>(sx[i-1]), get<1>(sx[i])-get<1>(sx[i-1]));
      add_edge(get<0>(sx[i-1]), get<0>(sx[i]), get<1>(sx[i])-get<1>(sx[i-1]));
      add_edge(get<0>(sy[i]), get<0>(sy[i-1]), get<2>(sy[i])-get<2>(sy[i-1]));
      add_edge(get<0>(sy[i-1]), get<0>(sy[i]), get<2>(sy[i])-get<2>(sy[i-1]));
    }
  }

  int build(){
    sort(edges.begin(),edges.end());
    UnionFind uf(n+1);
    int res=0;
    for(auto &e:edges){
      if(!uf.same(e.from,e.to)){
        res+=e.cost;
        uf.unite(e.from,e.to);
        e.used=1;
      }
    }
    return res;
  }
};
