long long prim(const WGraph &G) {
    int n = (int)G.size();
    std::vector<bool> used(n, false);
    long long res = 0;
    using P = std::pair<long long, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> que;
    used.at(0) = true;
    for (auto e : G.at(0)) {
        que.push(std::make_pair(e.second, e.first));
    }
    while (!que.empty()) {
        auto p = que.top();
        que.pop();
        int v = p.second;
        if (used.at(v)) {
            continue;
        }
        used.at(v) = true;
        res += p.first;
        for (auto e : G.at(v)) {
            if (!used.at(e.first)) {
                que.push(std::make_pair(e.second, e.first));
            }
        }
    }
    return res;
}

