#include <bits/stdc++.h>
using namespace std;
#define rep(i, n) for (int i = 0, i##_len = (int)(n); i < i##_len; i++)
#define reps(i, n) for (int i = 1, i##_len = (int)(n); i <= i##_len; i++)
using Int = long long;
struct Point {
    bool finished = false;
    Int x, y, minimumLengthFromFinishedPoints;

    Point(Int x, Int y) {
        Point::x = x;
        Point::y = y;
    }

    Int lengthFrom(Point p) {
        Int x1 = Point::x;
        Int y1 = Point::y;
        Int x2 = p.x;
        Int y2 = p.y;
        return min(abs(x1 - x2), abs(y1 - y2));
    }
};
struct Candidate {
    Int index;
    Int minimumLengthFromFinishedPoints;
};

int main() {
    Int n;
    cin >> n;
    auto points = vector<Point>();
    rep(i, n) {
        Int x, y;
        cin >> x >> y;
        points.push_back(Point(x, y));
    }

    // 候補を確定済みノードからの距離が小さいもので序列化する
    auto c = [](const Candidate &a, const Candidate &b) {
        return a.minimumLengthFromFinishedPoints > b.minimumLengthFromFinishedPoints;
    };
    // 優先度付きキューを用意
    auto q = priority_queue<Candidate, vector<Candidate>, decltype(c)>(c);

    // ノード0を確定させる
    points[0].finished = true;
    auto unfinished = n - 1;

    // ノード1以降のノード0からの距離を計算して候補点キューに加える
    for (Int i = 1; i < n; i++) {
        auto length = points[i].lengthFrom(points[0]); // ノードiのノード0からの距離
        points[i].minimumLengthFromFinishedPoints = length; // ノードiの値にセット
        q.push(Candidate{i, length}); // キューに候補を追加
    }

    Int ans = 0;
    while (q.size() > 0 && unfinished > 0) {
        // 距離最小候補を取り出す
        auto node = q.top();
        q.pop();
        auto index = node.index;
        auto length = node.minimumLengthFromFinishedPoints;
        auto &point = points[index];
        // 確定済みノードはスキップ
        if (point.finished) continue;
        // 未確定ノードに関する候補の中で確定済みノードからの距離が最小の1つを確定させる
        point.finished = true;
        unfinished--;
        ans += length;
        // このノードからの他のノードの距離を計算
        rep(i, n) {
            auto &target = points[i];
            if (target.finished) continue; // 確定済みノードはスキップ
            auto oldLength = target.minimumLengthFromFinishedPoints; // ノードに書き込まれている最小値
            auto newLength = target.lengthFrom(point); // 新たに計算した距離
            if (newLength < oldLength) { // このノードからの距離の方が小さければ
                target.minimumLengthFromFinishedPoints = newLength; // ノードに書き込まれている値を更新
                q.push(Candidate{i, newLength}); // 候補に加える（同じノードに関する情報が重複して加えられても構わない（最終的にキューから取り出されずに終わる））
            }
        }
    }
    cout << ans << endl;
}

