int Find(int n) {
  int g = group[n];
  if (g != n) {
    group[n] = Find(g);
  }
  return group[n];
}

void Union(int n, int m) {
  int g1 = Find(n);
  int g2 = Find(m);
  if (g1 != g2) {
    group[g1] = g2;
  }
}

