    int root(int x){
        if(par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    //親が同じならば同じ集合に属する
    bool same(int x, int y){
        return root(x) == root(y);
    }

    bool merge(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y) return false;
        //新しい要素を加えた時に、rootに対して辺を張る(merge technique)
        if(par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    //新しいノードを集合に加えた時に、-1をrootに加算するため、
    //rootには、集合に属するノードの数に負符号を付加したものが保存されている。
    int size(int x){
        return -par[root(x)];
    }
};


int main(){
    int n;
    cin >> n;
    using P = pair<ll, int>;
    vector<P> x(n), y(n);
    rep(i, n){
        cin >> x[i].first;
        x[i].second = i;
        cin >> y[i].first;
        y[i].second = i;
    }

    sort(all(x));
    sort(all(y));

    UnionFind uf(n);
    using edge = tuple<ll, ll, ll>;
    priority_queue<edge, vector<edge>, greater<edge>> que;
    rep(i, n-1){
        que.push(edge(x[i+1].first-x[i].first, x[i+1].second, x[i].second));
        que.push(edge(y[i+1].first-y[i].first, y[i+1].second, y[i].second));
    }

    ll ans = 0;
    while(que.size() != 0){
        ll cost, a, b;
        tie(cost, a, b) = que.top();
        que.pop();
        if(!uf.same(a, b)){
            uf.merge(a, b);
            ans += cost;
        }
    }

    cout << ans << endl;
}

