struct UnionFind{
    vector<ll> parent;
    UnionFind(ll sz){
        parent.resize(sz);
        reset();
    }

    void reset(){
        FOR(i, 0, parent.size()){
            parent[i] = i;
        }
    }

    void unite(ll a, ll b){
        if(a>b){
            swap(a, b);
        }
        ll rootA = findRoot(a);
        ll rootB = findRoot(b);
        if(rootA>rootB){
            swap(rootA, rootB);
        }
        if(rootA==rootB){
            return;
        }else{
            // 小さい方を親にする
            parent[rootB] = rootA;
        }
    }

    ll findRoot(ll a){
        if(parent[a]==a){
            return a;
        }else{
            return parent[a] = findRoot(parent[a]);
        }
    }

    map<ll, vector<ll> > getGroups(){
        map<ll, vector<ll> > G;
        FOR(i, 0, SZ(parent)){
            ll r = findRoot(i);
            G[r].push_back(i);
        }
        return G;
    }

    bool is_same_group(ll a, ll b){
        ll rootA = findRoot(a);
        ll rootB = findRoot(b);
        if(rootA==rootB){
            return true;
        }else{
            return false;
        }
    }
};

struct Point{
    ll x;
    ll y;
    ll id;
    Point(ll x, ll y, ll id): x(x), y(y), id(id) {}
    static bool sortByX(Point a, Point b){
        if(a.x == b.x){
            return a.y < b.y;
        }else{
            return a.x < b.x;
        }
    }
    static bool sortByY(Point a, Point b){
        if(a.y == b.y){
            return a.x < b.x;
        }else{
            return a.y < b.y;
        }
    }
};

struct Edge{
    ll from;
    ll to;
    ll cost;
    Edge(ll f, ll t, ll c){
      from = f;
      to = t;
      cost = c;
    }
    static bool sortByCost(Edge a, Edge b){
        return a.cost < b.cost;
    }
};

ll MST(vector<Edge>& edges){
  ll N = edges.size();
  UnionFind uf(N);
  sort(ALL(edges), Edge::sortByCost);
  ll sum = 0;
  for(auto edge : edges){
    if(uf.findRoot(edge.from) == uf.findRoot(edge.to)) continue;
    uf.unite(edge.from, edge.to);
    sum += edge.cost;
  }
  return sum;
}

