ll kruskal(int N, Graph& es) {  // ここでconstはだめ。ソートするから。いっぱいエラー出る。http://nocotan.github.io/%E3%82%A2%E3%83%AB%E3%82%B4%E3%83%AA%E3%82%BA%E3%83%A0/2017/01/27/mst-copy.html
