struct UF{
    vector<int> p, rank;
    int n;
    UF(int siz){
        n = siz;
        p.resize(n);
        rank.resize(n, 1);
        for(int i = 0; i < n; i++)  p[i] = i;
    }
    int findSet(int x){
        if(p[x] != x)   p[x] = findSet(p[x]);
        return p[x];
    }
    bool same(int x, int y){
        return findSet(x) == findSet(y);
    }
    void unite(int x, int y){
        x = findSet(x), y = findSet(y);
        if(x == y)  return;
        if(rank[x] < rank[y]){
            p[x] = y;
            rank[y] += rank[x];
        }else{
            p[y] = x;
            rank[x] += rank[y];
        }
    }
};

