int kruskal(){
    sort(edges.begin(),edges.end(),comp);
    init(n);
    long long res=0;
    rep(i,edges.size()){
        edge e=edges[i];
        if(!same(e.u,e.v)){
            unite(e.u,e.v);
            res += (long long)e.cost;
        }
    }
    return res;
}

