struct UnionFind {
    UnionFind() {}
    UnionFind(int n) {
        resize(n);
    }

    void resize(int n) {
        par.resize(n, -1);
    }

    int root(int x) {
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }

    bool merge(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return false;
        if (par[rx] > par[ry]) swap(rx, ry);
        par[rx] += par[ry];
        par[ry] = rx;
        return true;
    }

    bool is_same(int x, int y) {
        return (root(x) == root(y));
    }

    int size(int x) {
        return -par[root(x)];
    }

private:
