};

class UnionFindTree {
   public:
    vector<int> parent;

    UnionFindTree(int n) {
        parent.resize(n);
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    int root(int x) {
        if (parent[x] == x) return x;
        return parent[x] = root(parent[x]);
    }

    void unite(int x, int y) {
        int rx = root(x); int ry = root(y);
        if (rx == ry) return;
        parent[rx] = ry;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }
};

ll kruscal(vector<Edge> e, int n) {
    UnionFindTree uft(n + 1); // 1 origin
    sort(e.begin(), e.end(), [](Edge l, Edge r) { return l.cost < r.cost; });

    ll cost = 0;
    for (auto edge : e) {
        if (!uft.same(edge.u, edge.v)) {
            uft.unite(edge.u, edge.v);
            cost += edge.cost;
        }
    }

    return cost;
}

