    for(int i = 0; i < V-1; i++){
        edge e;
        e.u = xv[i].second;
        e.v = xv[i+1].second;
        e.cost = xv[i+1].first - xv[i].first;
        es[id] = e;
        id++;
    }
    for(int i = 0; i < V-1; i++){
        edge e;
        e.u = yv[i].second;
