class UnionFind {
	int n;
	int * parent;
	int * depth;
	int NumOfSets;
public:
	UnionFind (int n) {
		this->n = n;
		parent = new int[n];
		depth = new int[n];
		for (int i = 0; i < n; ++i) {
			parent[i] = i;
			depth[i] = 1;
		}
		NumOfSets = n;
	}
	~UnionFind () {
		delete[] parent;
		delete[] depth;
	}
	int find (int node) {
		while (parent[node] != parent[parent[node]]) {
			parent[node] = parent[parent[node]];
		}
		return parent[node];
	}
	void union_ (int nodeA, int nodeB) {
		int rootA = find(nodeA), rootB = find(nodeB);
		if (rootA != rootB) {
			if (depth[rootA] < depth[rootB]) {
				std::swap(rootA, rootB);
			}
			parent[rootB] = rootA;
			depth[rootA] = std::max(depth[rootA], depth[rootB] + 1);
			--NumOfSets;
		}
	}
	int getNumOfSets () { return NumOfSets; }
};

struct Town {
	int x, y;
	Town (int x, int y) : x(x), y(y) {}
};

struct Road {
	int a, b, cost;
	Road (int a, int b, int cost) : a(a), b(b), cost(cost) {}
};

int main () {

	int n;
	scanf("%d", &n);

	std::vector<Town> towns;
	std::vector<Road> roads;

	UnionFind unionFind(n);

	int tempX, tempY, totalCost = 0;

	auto getCost = [&towns] (int a, int b) -> int {
		return std::min(abs(towns[a].x - towns[b].x), abs(towns[a].y - towns[b].y));
	};

	for (int i = 0; i < n; ++i) {
		scanf("%d%d", &tempX, &tempY);
		towns.push_back(Town(tempX, tempY));
	}

	for (int i = 0; i < n; ++i) {
		for (int j = i + 1; j < n; ++j) {
			roads.push_back(Road(i, j, getCost(i, j)));
		}
	}

	std::sort(roads.begin(), roads.end(), [] (
		const Road & a,
		const Road & b
	) -> bool {
		return a.cost < b.cost;
	});

	for (Road road : roads) {
		if (unionFind.find(road.a) != unionFind.find(road.b)) {
			totalCost += road.cost;
			unionFind.union_(road.a, road.b);
			if (unionFind.getNumOfSets() == 1) break;
		}
	}

	printf("%d\n", totalCost);

	return 0;

}

