#include <bits/stdc++.h>
using namespace std;

int parent[100001];
int rnk[100001];

void init(int n) {
  for (int i=0; i<n; i++) {
    parent[i] = i;
    rnk[i] = 1;
  }
}

int find(int i) {
  if (parent[i] == i) {
    return i;
  }
  return parent[i] = find(parent[i]);
}

void unite(int i, int j) {
  i = find(i);
  j = find(j);
  if (i == j) {
    return;
  }
  if (rnk[i] < rnk[j]) {
    parent[i] = j;
  } else {
    parent[j] = i;
    if (rnk[i] == rnk[j]) {
      ++rnk[i];
    }
  }
}

