struct edge{ll v, to, cost;};
struct UnionFind{
  ll N; //ノードの個数
  vector<edge> G;
  vector<int> par; // 親ノード
  vector<int> rank; // ランク

  UnionFind(int n) { //初期化
    N=n; par.resize(N); rank.resize(N);
    rep(i,N) {par[i] = i, rank[i] = 0;}
  }

  int root(int x) { //ノードの根を返す
    if(par[x] == x) return x; //親が自分なら自分を返す
    else{
      int r = root(par[x]); //根まで遡る
      return par[x] = r;
    }
  }
  bool issame(int x, int y) { //同じ根ならtrue,ちがうならfalse
    return root(x) == root(y);
  }
  bool merge(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return false;
    if (rank[x] < rank[y]) swap(x, y);
    if (rank[x] == rank[y]) rank[x]++;
    par[y] = x; //ランクの小さい方に接続
    return true;
  }

  void add_edge(ll v,ll to,ll cost){
    G.emplace_back((edge){v, to, cost});
  }
/*
  bool comp(const edge& e1, const edge& e2) {
    return e1.cost < e2.cost;
  }
  */
  ll kruskal() {
    //sort(G.begin(), G.end(), comp);
    sort(G.begin(), G.end(), [](const edge &a, const edge &b) {
       return a.cost < b.cost;
    });//比較関数をラムダ式で作る);
    ll res = 0;
    for(auto E: G) {
      if(!issame(E.v, E.to)) {
        merge(E.v, E.to);
        res += E.cost;
      }
    }
    return res;
  }

};


