ll prim(ll n) {
    ll res = 0;
	vl d(n, INF); d[0] = 0;
	priority_queue<P, vector<P>, greater<P>> q;
	q.push(P(0, 0));
    while(q.size()){
		ll cost = q.top().first, v = q.top().second; q.pop();
		if(d[v] < cost) continue;
		res += cost; d[v] = -INF;
		for(ll i = 0; i < g[v].size(); i++){
			ll to = g[v][i].to, nxtcost = g[v][i].cost;
			if(d[to] > nxtcost){
				d[to] = nxtcost;
				q.push(P(nxtcost, to));
			}
		}
    }
    return res;
}
