struct DisjoinSet{
    int *par, *rank;
    int n;
    DisjoinSet(int n){
        this -> n = n;
        par = new int[n + 1];
        rank = new int[n + 1];
        For(i, 1, n) {
            rank[i] = 0;
            par[i] = i;
        }
    }
    int find(int i){
        while(par[i] != i) i = par[i];
        return i;
    }
    void Union(int x, int y){
        x = find(x);
        y = find(y);
        if(rank[x] < rank[y]) par[x] = y;
        else par[y] = x;
        if(rank[x] == rank[y]) rank[x]++;
    }

};
