void myinsert(set<pii>& s, priority_queue<pii>& q, int v, int i) {
	auto it = s.upper_bound(mp(v,i));
	if(it != s.end()) {
		int d = abs(it->F - v);
		q.push(mp(-d, it->S));
	}
	it--;
	if(it != s.end()) {
		int d = abs(it->F - v);
		q.push(mp(-d, it->S));
	}
}

ll prim() {
	set<pii> sx;
	set<pii> sy;
	set<int> s;
	rep(i,0,n) {
		sx.insert(mp(x[i],i));
		sy.insert(mp(y[i],i));
	}

	s.insert(0);
	sx.erase(mp(x[0],0));
	sy.erase(mp(y[0],0));
	priority_queue<pair<int, int> > Q;
	myinsert(sx, Q, x[0], 0);
	myinsert(sy, Q, y[0], 0);
	ll ret = 0;
	while(s.size() < n && !Q.empty()) {
		int d = -Q.top().F;
		int i = Q.top().S;
		Q.pop();
		if(s.find(i) != s.end()) {
			continue;
		} else {
			s.insert(i);
			ret += (ll)d;
			if(s.size() == n) {
				break;
			}
			sx.erase(mp(x[i],i));
			sy.erase(mp(y[i],i));
			myinsert(sx,Q,x[i],i);
			myinsert(sy,Q,y[i],i);
		}
	}
	return ret;
}


