struct data
{
    int u, v, w, id;
} a[mx],p[mx];
int root[mx], n;
void nhap()
{
    cin >> n;
    for(int i = 1; i <= n; i++)
        cin >> a[i].u >> a[i].v, a[i].id = i;
}
bool cmp(data a,data b)
{
    return a.u < b.u;
}
bool cmp2(data a, data b)
{
    return a.v < b.v;
}
bool cmp3(data a, data b)
{
    return a.w < b.w;
}
int get(int u)
{
    return(root[u])?(root[u] = get(root[u])): u;
}
void solve()
{
    long long ans = 0;
    int m = 0;
    sort(a + 1, a + 1 + n,cmp);

    for(int i = 2; i <= n; i++)
    {
        p[++m] = {a[i].id,a[i-1].id,abs(a[i].u - a[i-1].u)};
    }
    p[++m] = {a[1].id, a[n].id, abs(a[1].u - a[n].u)};
    sort(a + 1, a + 1 + n,cmp2);
    for(int i = 2; i    <= n; i++)
    {
        p[++m] = {a[i].id,a[i-1].id,abs(a[i].v - a[i-1].v)};
    }
    p[++m] = {a[1].id, a[n].id, abs(a[1].v - a[n].v)};
    p[++m] = {1, n, min(abs(a[1].u - a[n].u),abs(a[1].v - a[n].v))};
    sort(p + 1, p + 1 + m, cmp3);
    for(int i = 1; i <= m; i++)
    {
        int x = get(p[i].u);
        int y = get(p[i].v);
        if(x != y)
        {
            root[x] = y;
            ans += 1ll * p[i].w;
        }
    }
    cout << ans;
}
int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    nhap();
    solve();
}

