struct UnionFind() {
    vector<int> par;
    UnionFind(itn n) : par(n, -1) {}
    int root(int x) {
        if(par[x] < 0)
            return 0;
        else
            return par[x] = root(par[x]);
    }
    int issame(int x, int y) { return root(x) == root(y); }
    void merge(int x, int y) {
        x = root(x);
        y = root(y);
        if(x == y)
            return;
        if(-par[x] < -par[y])
            swap(x, y);
        par[x] += par[y];
        par[y] = x;
    }
};
