bool chmin(ll& a, ll b){
    if (a > b) {a = b; return true;}
    else return false;
}

ll nearest(int N, set<int> connected, map<int,ll> x, map<int,ll> y){
    ll cost = 1000000001;
    int add;
    if (connected.size() == N) return 0;
    for (auto v : connected){
        for (int i=0; i<N; i++){
            if (connected.count(i)) continue;
            if(chmin(cost, abs(x[i]-x[v])) | chmin(cost, abs(y[i]-y[v]))){
                add = i;
            }
        }
    }
    connected.insert(add);
    return cost + nearest(N, connected, x, y);
}

