			return min(abs(x-rhs.x), abs(y-rhs.y));
		}
	};
	vector<Point> pts;
	for (ll i = 0; i < N; i++) {
		ll x, y;
		cin >> x >> y;
		pts.push_back({i, x, y});
	}
	struct Edge {
		ll idx0;
		ll idx1;
		ll cost;
		static bool comp(Edge lhs, Edge rhs) {
			return lhs.cost > rhs.cost;
		}
	};
	priority_queue<Edge, vector<Edge>, decltype(&Edge::comp)> edges(&Edge::comp);
	sort(pts.begin(), pts.end(), [](Point lhs, Point rhs){
		return lhs.x < rhs.x || (lhs.x == rhs.x && lhs.y < rhs.y);
	});
	for (ll i = 0; i < N-1; i++) {
		edges.push({pts[i].idx, pts[i+1].idx, pts[i].cost(pts[i+1])});
