class UF
{
	vector<int> par;
public:
	UF(int n) {
		par.resize(n);
		rep(i, n) par[i] = i;
	}
	int root(int x) {
		if (x == par[x]) return x;
		else return par[x] = root(par[x]);
	}
	bool same(int x, int y) { return root(x) == root(y); }
	bool unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		par[x] = y;
		return true;
	}
};
