template <class T>
T abs(T a) { return (a > 0 ? a : -a); }

template <class T>
T root(std::vector<T>& v, T x) {
    if (v[x] == x) return x;
    else return v[x] = root(v, v[x]);
}

template <class T>
bool same (std::vector<T>& v, T x, T y) {
    return root(v, x) == root(v, y);
}

template <class T>
void unite(std::vector<T>& v, T x, T y) {
    x = root(v, x);
    y = root(v, y);
    if (x == y) return;
    v[x] = y;
}

int main() {
    long long n;
    std::cin >> n;

    /* cost, i, j */
    using T = std::tuple<long long, long long, long long>;
    std::priority_queue<T, std::vector<T>, std::greater<T>> pq;

    {
        std::priority_queue<std::pair<long long, long long>> cx, cy;
        for (auto i = 0ll; i < n; i++) {
            long long x, y;
            std::cin >> x >> y;
            cx.push(std::make_pair(x, i));
            cy.push(std::make_pair(y, i));
        }

        auto px = cx.top(), py = cy.top();
        cx.pop();
        cy.pop();
        for (auto i = 1ll; i < n; i++) {
            auto &currx = cx.top(), &curry = cy.top();
            pq.push(std::make_tuple(px.first - currx.first, px.second, currx.second));
            pq.push(std::make_tuple(py.first - curry.first, py.second, curry.second));
            px = currx;
            py = curry;
            cx.pop();
            cy.pop();
        }
    }

    std::vector<long long> par(n);
    for (auto i = 0ll; i < n; i++) par[i] = i;

    long long ret = 0, count = 0;
    std::vector<bool> done(n, false);
    while (count < n - 1) {
        auto& curr = pq.top();
        //std::cout << std::get<0>(curr) << " " << std::get<1>(curr) << " " << std::get<2>(curr);
        auto fst = std::get<1>(curr), snd = std::get<2>(curr);
        if (!same(par, fst, snd)) {
            //std::cout << " Add";
            ret += std::get<0>(curr);
            count++;
            unite(par, fst, snd);
        }
        pq.pop();
        //std::cout << std::endl;
    }

    std::cout << ret << std::endl;

    return 0;
}

