struct edge
{
    int from;
    int to;
    int cost;
};

struct UnionFind
{
    vector<int> par;

    UnionFind(int n) : par(n, -1) {}
    void init(int n) { par.assign(n, -1); }

    int root(int x)
    {
        if (par[x] < 0)
            return x;
        else
            return par[x] = root(par[x]);
    }

    bool issame(int x, int y)
    {
        return root(x) == root(y);
    }

    bool merge(int x, int y)
    {
        x = root(x);
        y = root(y);
        if (x == y)
            return false;
        if (par[x] > par[y])
            swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x)
    {
        return -par[root(x)];
    }
};

int kruskal(vector<edge> &graph, int V)
{
    sort(ALL(graph), [](const edge &a, const edge &b) { return a.cost < b.cost; });
    UnionFind uf(V);

    int res = 0;
    for (int v = 0; v < (int)graph.size(); v++)
    {
        edge e = graph[v];
        if (!uf.issame(e.from, e.to))
        {
            uf.merge(e.from, e.to);
            res += e.cost;
        }
    }
    return res;
}

int calcCost(pair<int, int> a, pair<int, int> b)
{
    int aa = abs(a.first - b.first);
    int bb = abs(a.second - b.second);
    return min(aa, bb);
}

