	v[i] = myfind(v[i], v);
	return v[i];
}

void myunion(int i1, int i2, vector<int>& v) {
	int r1 = myfind(i1, v);
	int r2 = myfind(i2, v);
	if (r1 == r2) return;
	v[r1] = r2;
}

