int find(int a){
    if(root[a]==a)
        return root[a];
    else
        return root[a]=find(root[a]);
}
bool same(int a,int b){
    return find(a)==find(b);
}
void unite(int a,int b){
    a=find(a);
    b=find(b);
    if(size[b]>size[a])
        swap(a,b);
    size[a]+=size[b];
    root[b]=a;
}
bool cmp(tuple<int,int,int>a,tuple<int,int,int>b){
    int o=get<2>(a);
    int p=get<2>(b);
    return o<p;
}
