        for(int j=i+1;j<=n;j++){
            dix=abs(x[i]-x[j]);
            diy=abs(y[i]-y[j]);
            road.push_back({i,j,min(dix,diy)});
        }
    sort(road.begin(),road.end(),cmp);
    for(int i=1;i<=n;i++){
