class UnionFind{
public:
    //親の番号，親の場合-(その集合のサイズ)
    vector<int> Parent;

    UnionFind(int N){
        Parent = vector<int>(N,-1);
    }

    //Aがどのグループに属しているか調べる
    int root(int A){
        if(Parent[A]<0) return A;
        return Parent[A] = root(Parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    int size(int A){
        return -Parent[root(A)];
    }

    bool connect(int A, int B){
        //root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        if(A==B) return false;//すでにくっついてる

        //大きい方に小さい方をくっつける
        if(size(A) < size(B)) swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

int main(){
