        v.push_back({{x,y},i});
    }
    VSORT(v);
    for(int i=1;i<n;i++){
        ll now = min(abs(v[i-1].first.first-v[i].first.first),
                     abs(v[i-1].first.second-v[i].first.second));
        pq.push({now,{v[i-1].second,v[i].second}});
    }
    for(int i=0;i<n;++i) swap(v[i].first.first,v[i].first.second);
    VSORT(v);
    for(int i=1;i<n;i++){
        ll now = min(abs(v[i-1].first.first-v[i].first.first),
                     abs(v[i-1].first.second-v[i].first.second));
        pq.push({now,{v[i-1].second,v[i].second}});
    }
    ll ans=0;
    while(pq.size()>0){
       auto now = pq.top();
       pq.pop();
       if(uf.root(now.second.first)!=uf.root(now.second.second)){
           ans += now.first;
           uf.connect(now.second.first,now.second.second);
       }
    }
    cout<<ans<<endl;
}

