typedef long long ll;

const int INF = 1000000000;

struct UF
{
  vector<int> parent_, rank_;

  UF(int N) {
    parent_ = vector<int>(N + 5);
    rank_ = vector<int>(N + 5, 1);
    for (int i = 0; i <= N; ++i) { parent_[i] = i; }
  }

  int find_set(int x)
  {
    if (parent_[x] != x) {
      parent_[x] = find_set(parent_[x]);
    }
    return parent_[x];
  }

  void unite(int x, int y)
  {
    int s1 = find_set(x), s2 = find_set(y);
    if (s1 == s2) { return; }
    if (rank_[s1] > rank_[s2]) { parent_[s2] = s1; }
    else {
      parent_[s1] = s2;
      if (rank_[s1] == rank_[s2]) { ++rank_[s2]; }
    }
  }

  bool is_connected(int x, int y) { return find_set(x) == find_set(y); }
};

int main()
{
  int N; scanf("%d", &N);
  vector<pair<ll, ll>> towns(N, pair<ll, ll>());
  vector<pair<ll, int>> X(N), Y(N);
  for (int i = 0; i < N; ++i) {
    ll x, y;
    scanf("%lld %lld", &x, &y);
    X[i] = {x, i};
    Y[i] = {y, i};
  }
  sort(X.begin(), X.end());
  sort(Y.begin(), Y.end());
  vector<pair<ll, pair<int, int>>> edges;
  for (int i = 1; i < N; ++i) {
    edges.push_back({ abs(X[i].first - X[i - 1].first),
        { X[i].second, X[i - 1].second }});
    edges.push_back({ abs(Y[i].first - Y[i - 1].first),
        { Y[i].second, Y[i - 1].second }});
  }
  sort(edges.begin(), edges.end());
  UF uf(N);
  ll ans = 0;
  for (int i = 0; i < (int)edges.size(); ++i) {
    int u = edges[i].second.first, v = edges[i].second.second;
    if (uf.find_set(u) == uf.find_set(v)) { continue; }
    uf.unite(u, v);
    ans += edges[i].first;
  }
  printf("%lld\n", ans);
  return 0;
}

