using P = pair<int, int>;

class UnionFind {
private:
    vector<int> par; // plus: parent node, minus: node size
    int group; // group count
public:
    UnionFind(int n) : par(n, -1), group(n) {}

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if(x == y) return;
        if(-par[x] < -par[y]) std::swap(x, y);

        par[x] += par[y];
        par[y] = x;

        group--;
    }

    bool same(int x, int y)  {
        return find(x) == find(y);
    }

    int find(int x) {
        return par[x] < 0 ? x : par[x] = find(par[x]);
    }

    int size(int x){
        return -par[find(x)];
    }

    int count() {
        return group;
    }
};

struct edge {
    int from, to, cost;
};

int kruskal(int v, vector<edge> es) {
    std::sort(es.begin(), es.end(), [](edge& a, edge& b){
        return a.cost < b.cost;
    });

    UnionFind uf(v);

    int res = 0;
    for(auto& e : es) {
        if(uf.same(e.from, e.to)) continue;

        uf.unite(e.from, e.to);
        res += e.cost;
    }

    return res;
}


int main(void){
