        cityx[i] = i;
        cityy[i] = i;
    }    

    vector<edge> e;

    sort(cityx.begin(), cityx.end(), [&](int a, int b){
        return pos[a].first < pos[b].first;
    });

    for(int i=0; i<N-1; i++) e.push_back(edge{cityx[i], cityx[i+1], pos[cityx[i+1]].first - pos[cityx[i]].first});

