int solve(int n)
{
    int res = 0;
    priority_queue<P, vector<P>, greater<P>> que;
    vector<int> cost(n, INF);
    que.push(P(0, 0));
    cost[0] = 0;
    while(not que.empty())
    {
        int w = que.top().first;
        int v = que.top().second;
        que.pop();
        if(cost[v] < w) continue;
        res += w;
        for(int u = 0; u < n; u++)
        {
            int c = min(abs(x[u] - x[v]), abs(y[u] - y[v]));
            if(c < cost[u])
            {
                cost[u] = c;
                que.push(P(cost[u], u));
            }
        }
    }
    return res;
}
