    bool operator<(const Edge &e) const {
        return (cost < e.cost);
    }
};

int main() {
    ll n;
    cin >> n;
    const ll m = 2*(n-1);

    vector<pair<ll, ll>> p1(n), p2(n);
    rep(i, n) {
        ll x, y;
        cin >> x >> y;
        p1[i] = make_pair(x, i);
        p2[i] = make_pair(y, i);
    }
    sort(all(p1));
    sort(all(p2));

    vector<Edge> es(m);  // es[i] : 辺iは頂点es[i].aと頂点es[i].bをコストes[i].costで結ぶ
    rep(i, m) {
        if(i < n-1) {
            es[i].a = p1[i].second;
            es[i].b = p1[i+1].second;
            es[i].cost = abs(p1[i].first - p1[i+1].first);
        }
        else {
            es[i].a = p2[i - (n-1)].second;
            es[i].b = p2[(i+1) - (n-1)].second;
            es[i].cost = abs(p2[i - (n-1)].first - p2[(i+1) - (n-1)].first);
        }
    }
    sort(all(es));  // esをcostの昇順でソート

    UnionFind Uni(n);
    Uni.init(n);

    // クラスカル法。計算量はO(E*log(E))
    ll min_cost = 0;
    rep(i, m) {
        if(!Uni.same(es[i].a, es[i].b)) {
            Uni.unite(es[i].a, es[i].b);
            min_cost += es[i].cost;
        }
    }

    out(min_cost);
    re0;
}

