const int N = 1e5 + 2;
int pa[N],sz[N];

void make_set(int x) {
    pa[x] = x;
    sz[x] = 1;
}

int find_set(int x) {
    if(pa[x] == x) {
        return x;
    }
    return pa[x] = find_set(pa[x]);
}

void union_set(int a,int b) {
    a = find_set(a);
    b = find_set(b);
    if(a != b) {
        if(sz[a] < sz[b])
            swap(a,b);
        sz[a] += sz[b];
        pa[b] = a;
    }
}

void solve() {
        int n;
        cin >> n;
        std::vector<pair<int,int > > a,b;
        FOR(i,0,n) {
                int x,y;
                cin >> x >> y;
                a.pb({x,i});
                b.pb({y,i});
        }
        sort(a.begin(), a.end());
        sort(b.begin(), b.end());
        FOR(i,0,N) make_set(i);
        std::vector<pair <int, pair <int,int > > > v;
        FOR(i, 1, int(a.size())) {
                v.pb({a[i].fi - a[i-1].fi, {a[i].se,a[i-1].se}});
        }
        FOR(i, 1, int(b.size())) {
                v.pb({b[i].fi - b[i-1].fi, {b[i].se,b[i-1].se}});
        }
        sort(v.begin(), v.end());
        ll ans = 0;
        for(auto i:v) {
                if(find_set(i.se.fi) != find_set(i.se.se)) {
                        union_set(i.se.fi,i.se.se);
                        ans += i.fi;
                }
        }
        cout << ans << endl;
}

