struct unionfind_tree{
    int par[500000], rank[500000], num[500000];
    //要素数n(0〜n-1)の初期化されたUnion-Find木を構築
    unionfind_tree(int N){
        rep(i, N){par[i] = i, rank[i] = 0, num[i] = 1;}
    }
    //ノードxの根を取得
    int find(int x){
        if(par[x] == x) return x;
        else return find(par[x]);
    }
    //xとyの属する集合を併合
    void unite(int x, int y){
        x = find(x), y = find(y);
        if(x == y) return;
        elif(rank[x] < rank[y]){par[x] = y, num[y] += num[x];}
        else{
            par[y] = x, num[x] += num[y];
            if(rank[x] == rank[y]) rank[x]++;
        }
    }
    //xの属する集合の要素数を取得
    int size(int x){
        return num[find(x)];
    }
    //xとyが同じ集合に属するか判定
    bool same(int x, int y){
        return find(x) == find(y);
    }
};

int main(){
    int N;
    cin >> N;
    pll p[N];
    rep(i, N){
        ll x, y;
        cin >> x >> y;
        p[i] = pll(x, y);
    }
    pli x[N];
    rep(i, N){
        x[i] = pli(p[i].first, i);
    }
    pli y[N];
    rep(i, N){
        y[i] = pli(p[i].second, i);
    }
    sort(x, x+N);
    sort(y, y+N);
    vector<pli> vx[N], vy[N];
    rep(i, N){
        int v = x[i].second;
        if(i != N-1) vx[v].pb(pli(x[i+1].first - x[i].first, x[i+1].second));
        if(i != 0) vx[v].pb(pli(x[i].first - x[i-1].first, x[i-1].second));
    }
    rep(i, N){
        int v = y[i].second;
        if(i != N-1) vy[v].pb(pli(y[i+1].first - y[i].first, y[i+1].second));
        if(i != 0) vy[v].pb(pli(y[i].first - y[i-1].first, y[i-1].second));
    }
    priority_queue<pli, vector<pli>, greater<pli> > qx, qy;
    for(auto &e: vx[0]){
        qx.push(e);
    }
    for(auto &e: vy[0]){
        qy.push(e);
    }
    ll ans = 0;
    unionfind_tree uft(N);
    while(uft.size(0) < N){
        while(uft.same(0, qx.top().second)){
            qx.pop();
        }
        while(uft.same(0, qy.top().second)){
            qy.pop();
        }
        if(qx.top().first < qy.top().first){
            ans += qx.top().first;
            int v = qx.top().second;
            uft.unite(0, v);
            qx.pop();
            for(auto &e: vx[v]) qx.push(e);
            for(auto &e: vy[v]) qy.push(e);
        }
        else{
            ans += qy.top().first;
            int v = qy.top().second;
            uft.unite(0, v);
            qy.pop();
            for(auto &e: vx[v]) qx.push(e);
            for(auto &e: vy[v]) qy.push(e);
        }
    }
    cout << ans << endl;
}

