#include <bits/stdc++.h>
using namespace std;
typedef pair<int,int> P;
typedef pair<int, P> PP;
#define fi first
#define se second

struct UnionFind{
	vector<int> ran, par;
	void init(int n){
		for(int i = 0;i < n;i++){
			par.push_back(i);
			ran.push_back(0);
		}
	}

	int find(int x){
		if(par[x] == x)return x;
		return par[x] = find(par[x]);
	}

	void unite(int x, int y){
		x = find(par[x]);
		y = find(par[y]);
		if(x == y)return;
		if(ran[x] < ran[y]){
			par[x] = y;
		}else{
			par[y] = x;
			if(par[x] == par[y])ran[x]++;
		}
	}

	bool same(int x, int y){
		return find(par[x]) == find(par[y]);
	}
};

int main(){
	vector<P> xs, ys;
	vector<PP> c;
	UnionFind UF;
	int n;
	scanf("%d", &n);
	UF.init(n);

	for(int i = 0;i < n;i++){
		int x, y;
		scanf("%d%d", &x, &y);
		xs.push_back(P(x, i));
		ys.push_back(P(y, i));
	}
	sort(xs.begin(), xs.end());
	sort(ys.begin(), ys.end());

	for(int i = 1;i < n;i++){
		int d = xs[i].fi-xs[i-1].fi;
		c.push_back(PP(d, P(xs[i].se, xs[i-1].se)));
	}
	for(int i = 1;i < n;i++){
		int d = ys[i].fi-ys[i-1].fi;
		c.push_back(PP(d, P(ys[i].se, ys[i-1].se)));
	}
	sort(c.begin(), c.end());

	int ans = 0;
	for(int i = 0;i < c.size();i++){
		int d = c[i].fi;
		int x = c[i].se.fi, y = c[i].se.se;
		if(UF.same(x, y) == 0){
			UF.unite(x, y);
			ans += d;
		}
	}
	printf("%d\n", ans);
	return 0;
}

