struct Node{
    vector<P> edges;
    bool done;
    ll cost;
};
ll prim(vector<Node> &nodes){
    priority_queue<P,vector<P>,greater<P>> mincost;
    rep(i,V){
        nodes[i].cost = INF;
        nodes[i].done = false;
    }
    ll res = 0;
