ll distance(vector<ll>& a,vector<ll>& b){
  return min({abs(a[0]-b[0]),abs(a[1]-b[1])});
}

int main(){
  ll n;cin >> n;
  vector< vector<ll> > v1(n,vector<ll>(3,0));
  vector< vector<ll> > v2(n,vector<ll>(3,0));
  //自作クラスのpr_queueどうする
  for(ll i=0;i<n;i++){
    ll x,y;cin >> x >> y;
    v1[i][0]=x;v1[i][1]=y;v1[i][2]=i;
    v2[i][0]=x;v2[i][1]=y;v2[i][2]=i;
  }
  sort(v1.begin(),v1.end(),[](vector<ll>& a,vector<ll>& b){return a[0] < b[0];});
  sort(v2.begin(),v2.end(),[](vector<ll>& a,vector<ll>& b){return a[1] < b[1];});

  //ここでそれぞれのNodeから伸びる辺をqueueに入れておく
  vector< queue<Side> > sides_before(n);
  for(ll i=0;i<n-1;i++){
    sides_before[v1[i][2]].push(Side(v1[i+1][2],distance(v1[i],v1[i+1])));
    sides_before[v1[i+1][2]].push(Side(v1[i][2],distance(v1[i],v1[i+1])));
    sides_before[v2[i][2]].push(Side(v2[i+1][2],distance(v2[i],v2[i+1])));
    sides_before[v2[i+1][2]].push(Side(v2[i][2],distance(v2[i],v2[i+1])));
  }

  //0から始まるので0を初期化
  vector<bool> check(n,false);check[0]=true;
  priority_queue<Side> sides;
  ll l=sides_before[0].size();
  for(ll i=0;i<l;i++){
    sides.push(sides_before[0].front());
    sides_before[0].pop();
  }

  ll cost_sum=0;
  Side now=sides.top();
  while(sides.size()!=0){
    //nowが訪問済みなのは
    if(!check[now.to_Node]){
      check[now.to_Node]=true;
      cost_sum+=now.cost;
      int k=now.to_Node;
      ll l=sides_before[k].size();
      sides.pop();
      for(ll i=0;i<l;i++){
        Side s=sides_before[k].front();
        if(!check[s.to_Node]) sides.push(s);
        sides_before[k].pop();
      }
      now=sides.top();
    }else{
      sides.pop();now=sides.top();
    }
  }
  cout << cost_sum << endl;
}

