const int MOD = 1000000007;

class UnionFind {
    vector<int> parent;

    public:
        UnionFind(int size) {
            parent = vector<int>(size, -1);
        }

        int find(int x) {
            if (parent[x] < 0) {
                // parent itself
                return x;
            } else {
                return parent[x] = find(parent[x]);
            }
        }

        bool unite(int x, int y) {
            int rX, rY;
            if ((rX = find(x)) == (rY = find(y))) {
                // already united
                return false;
            }
            if (size(rX) < size(rY)) {
                int tmp = rX;
                rX = rY;
                rY = tmp;
            }
            parent[rX] += parent[rY];
            parent[rY] = rX;
            return true;
        }

        int size(int x) {
            return -parent[find(x)];
        }

        bool isSame(int x, int y) {
            return find(x) == find (y);
        }

        int component_count() {
            int c = 0;
            for (const int x : parent) {
                if (x < 0) {
                    c++;
                }
            }
            return c;
        }
};

int main() {
    int n;
    cin >> n;

    // idx, x, y
    vector<tuple<int, int, int>> x(n);
    int u, v;
    for (int i = 0; i < n; i++) {
        cin >> u >> v;
        x[i] = make_tuple(i, u, v);
    }

    // dist, idx1, idx2 
    vector<tuple<int, int, int>> d;
    sort(ALL(x), [](tuple<int, int, int> a, tuple<int, int, int> b){return get<1>(a) <= get<1>(b);});
    for (int i = 1; i < n; i++) {
        d.emplace_back(abs(get<1>(x[i]) - get<1>(x[i - 1])), get<0>(x[i]), get<0>(x[i - 1]));
    }
    sort(ALL(x), [](tuple<int, int, int> a, tuple<int, int, int> b){return get<2>(a) <= get<2>(b);});
    for (int i = 1; i < n; i++) {
        d.emplace_back(abs(get<2>(x[i]) - get<2>(x[i - 1])), get<0>(x[i]), get<0>(x[i - 1]));
    }

    sort(ALL(d), [](tuple<int, int,int> a, tuple<int, int, int> b){return get<0>(a) <= get<0>(b);});

    UnionFind uf = UnionFind(n);

    int t = 0;
    for (const auto e : d) {
        if (uf.component_count() == 1) {
            break;
        }

        if (uf.isSame(get<1>(e), get<2>(e))) {
            continue;
        }

        t += get<0>(e);
        uf.unite(get<1>(e), get<2>(e));
    }

    cout << t << endl;
}

