struct UnionFind {
    vector<ll> par;

    //要素nで初期化
    UnionFind(ll n) : par(n, -1) { }
    void init(ll n) { par.assign(n, -1); }

    //xが属する集合の根を返す
    ll root(ll x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    //xとyが同じ集合に属しているかを判定
    bool issame(ll x, ll y) {
        return root(x) == root(y);
    }

    //xが属する集合とyが属する集合をマージ
    bool merge(ll x, ll y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // 計算量が減るよ
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    //xが属する集合のサイズ
    ll size(ll x) {
        return -par[root(x)];
    }
};

