struct UnionFind
{
  vector<int> rank, p;
  UnionFind(int n)
  {
    rank.resize(n, 0);
    p.resize(n);
    rep(i, n)
    {
      p.at(i) = i;
    }
  }

  int find(int x)
  {
    if (x != p.at(x))
    {
      p.at(x) = find(p.at(x));
    }
    return p.at(x);
  }

  bool same(int x, int y)
  {
    return find(x) == find(y);
  }

  void link(int x, int y)
  {
    if (rank.at(x) < rank.at(y))
    {
      p.at(x) = y;
    }
    else
    {
      p.at(y) = x;
      if (rank.at(x) == rank.at(y))
      {
        rank.at(x)++;
      }
    }
  }

  void unite(int x, int y)
  {
    link(find(x), find(y));
  }
};

