using namespace std;
class DisjointSet{
    private:
        unordered_map<int,int> parent;
        unordered_map<int,int> rank;
    public:
        void makeset(vector<int> v){
            for(int i = 0; i < v.size(); i++){
                parent[v[i]] = v[i];
                rank[v[i]] = 0;
            }
        }
        int findset(int x){
            if(parent[x] == x){
                return x;
            }
            parent[x] = findset(parent[x]);
            return parent[x];
        }
        void unionset(int x, int y){
            int set1 = findset(x);
            int set2 = findset(y);
            if(set1 == set2)return;

            if(rank[set1] < rank[set2]){
                parent[set1] = set2;
            }
            else if(rank[set1] > rank[set2]){
                parent[set2] = set1;
            }
            else{
                parent[set1] = set2;
                rank[set2]++;
            }
        }
};
