edge es[MAX_E];
bool comp(const edge& e1, const edge& e2){
    return e1.cost < e2.cost;
}

//クラスカル法
int kruskal(){
    sort(es, es+E, comp);
    UnionFind tree(V);
    int res=0;

    for(int i=0; i<E; i++){
        edge e = es[i];
        if(!tree.same(e.u, e.v)){
            tree.unite(e.u, e.v);
            res += e.cost;
        }
    }

    return res;
}

