    DWORD dwNodeIdx)
{
//    printf("add %d\n", dwNodeIdx);
    abIsUsed[dwNodeIdx] = M_TRUE;
    add_neighbor_dist(xpos, adwIdxListX, dwNodeIdx);
    add_neighbor_dist(ypos, adwIdxListY, dwNodeIdx);
}

