class UnionFind {
    // 各ノードが根である時の高さ
    // ノードが根でないときは意味をなさない
    vector<int> rank;
    // 各ノードが属する木の根
    // findSetするときのみ更新される
    vector<int> p;
    // 二つの根を結合
    void link(int rx, int ry) {
        if (rx == ry) return;
        if (rank[rx] > rank[ry]) p[ry] = rx;
        else p[rx] = ry;
        if (rank[rx] == rank[ry]) rank[ry]++;
    }
public:
    //　根を作成
    // その木の高さは0
    void makeSet(int x) {
        p[x] = x;
        rank[x] = 0;
    }
    // 初期化
    // 入力サイズ分のノードを確保
    // それらのノードをそれぞれ根とする木を作成
    // ノードの値は 0 ~ size-1
    UnionFind(int size) {
        rank.resize(size, 0);
        p.resize(size, 0);
        rep(i,size) makeSet(i);
    }
    // あるノードの属する木の根を返す
    // 根を探す過程で途中のノードの親も更新
    int findSet(int x) {
        if (x != p[x]) p[x] = findSet(p[x]);
        return p[x];
    }
    // 二つのノードが同じ木にあるか判定
    bool same(int x, int y) {return findSet(x) == findSet(y);}
    // 二つのノードの属する木を結合
    void unite(int x, int y) {link(findSet(x), findSet(y));}
};

struct Edge {
    int from, to, cost;
    Edge(int f,int t, int c) {
        from = f;
        to = t;
        cost = c;
    }
    bool operator <(const Edge &e) const {return (cost < e.cost);}
    bool operator >(const Edge &e) const {return (cost > e.cost);}
};

ll kruskal(int v, const vector<Edge> &e) {
    UnionFind tree(v);
    ll ans = 0;
    for (auto edge: e) {
        if (!tree.same(edge.from, edge.to)) {
            ans += edge.cost;
            tree.unite(edge.from, edge.to);
        }
    }
    return ans;
}

