	ifstream ifs("in.txt");
	cin.rdbuf(ifs.rdbuf());
#endif
	ll N; cin >> N;
	set< pair< ll, ll> > XclassSet; // x座標、クラス
	set< pair< ll, ll> > YclassSet; // y座標、クラス
	UnionFind<ll> UF(N);
	priority_queue< tuple<ll,ll,ll> , vector< tuple<ll,ll,ll> >, greater< tuple<ll,ll,ll>> > Q; // 距離、class1, class2
	FOR(i, N)
	{
		ll x, y; cin >> x >> y;
		XclassSet.insert(make_pair(x, i));
		YclassSet.insert(make_pair(y, i));
	} // 隣接したX, 隣接したYの距離をpriority_queueにつっこむ。
	for (auto it = XclassSet.begin(); next(it) != XclassSet.end(); ++it) {
		ll dist = abs(it->first - next(it)->first);
		Q.push(tie(dist, it->second, next(it)->second));
	}
	for (auto it = YclassSet.begin(); next(it) != YclassSet.end(); ++it) {
		ll dist = abs(it->first - next(it)->first);
		Q.push(tie(dist, it->second, next(it)->second));
	}
	ll NoRemainClass = N - 1; // これがゼロになるまで。
	ll ans = 0;
	while (NoRemainClass != 0) {		
		ll dist, cls1, cls2;
		tie(dist, cls1, cls2) = Q.top(); Q.pop();
		if (UF.unionSet(cls1, cls2)) {
			NoRemainClass -= 1;
			ans += dist;
		}
	}

	cout << ans << endl;

	return 0;
}

