struct UnionFind{
    vector<int> par;
    void init(int n){
        par.resize(n,-1);
    }

    int root(int x){
        if(par[x]<0)return x;
        else return par[x]=root(par[x]);
    }

    bool same(int a,int b){
        return root(a)==root(b);
    }

    void merge(int a,int b){
        a=root(a);
        b=root(b);
        if(a==b)return;
        if(par[a]>par[b]){
            swap(a,b);
        }
        par[a]+=par[b];
        par[b]=a;
    }
};


