//初期化(n要素0オリジン)
void init(int n){
	for(int i=0;i<n;i++){
		par[i] = i;
		rnk[i] = 0;
	}
}
//xの根を求める
int find(int x){
	if(par[x] == x){
		return x;
	}else{
		return par[x] = find(par[x]);
	}
}
//x,yの属する集合を併合
void unite(int x,int y){
	x = find(x);
	y = find(y);
	if(x == y)return;

	if(rnk[x] < rnk[y]){
		par[x] = y;
	}else{
		par[y] = x;
		if(rnk[x] == rnk[y])rnk[x]++;
	}
}
//xとyが同じ集合に属するか
bool same(int x,int y){
	return find(x) == find(y);
}

//最小全域木-Kruskal
struct edge{int u,v;ll cost;};
bool comp(const edge& e1,const edge& e2){
	return e1.cost < e2.cost;
}
edge es[SIZE];
int V,E; //頂点数・辺数
ll kruscal(){
	sort(es,es+E,comp);
	init(V+1); //Union-Find初期化
	ll res = 0;
	for(int i=0;i<E;i++){
		edge e = es[i];
		if(!same(e.u,e.v)){
			unite(e.u,e.v);
			res += e.cost;
		}
	}
	return res;
}

