class Graph {
    using ll = long long;
public:
    struct Edge {
        enum class Type { Directed, Undirected };
        int  src, dst;
        ll   cost;
        bool validity;
        Edge(const int& _src, const int& _dst, const ll& _cost = 0) :
            src(_src), dst(_dst), cost(_cost), validity(true) { }
        friend std::ostream& operator <<(std::ostream& os, const Edge& e) {
            os << "src : " << e.src << ", " << "dst : " << e.dst << ", " << "cost : " << e.cost;
            return os;
        }
    };

    struct Vertex {
        ll cost;
        explicit Vertex(const ll& _cost) : cost(_cost) { }
    };

    Graph(const int&        num_vertex,
          const Edge::Type& edge_type,
          const ll&         vertex_init_cost = (ll)1e9 + 1) :
        vertices_(num_vertex, Vertex(vertex_init_cost)),
        edges_(num_vertex),
        num_vertex_(num_vertex),
        num_edge_(0),
        total_edge_cost_(0),
        total_vertex_cost_(num_vertex * vertex_init_cost),
        edge_type_(edge_type) { }

    const std::vector<Vertex>& getVertices() const { return vertices_; }
    const std::vector<std::vector<Edge>>& getEdges() const { return edges_; }
    const ll& getTotalEdgeCost() const { return total_edge_cost_; }
    const ll& getTotalVertexCost() const { return total_vertex_cost_; }
    const int& getNumVertex() const { return num_vertex_; }
    const int& getNumEdge() const { return num_edge_; }
    const Edge::Type& getEdgeType() const { return edge_type_; }

    void setCostToAllVertex(const ll& val) {
        total_vertex_cost_ = vertices_.size() * val;
        std::fill(vertices_.begin(), vertices_.end(), Vertex(val));
    };

    void setCostToSpecificVertex(const int& index, const ll& val) {
        total_vertex_cost_ += val - vertices_[index].cost;
        vertices_[index].cost = val;
    };

    int addVertex(const ll& cost = (ll)1e9 + 1) {
        vertices_.emplace_back(cost); edges_.emplace_back();
        num_vertex_++;
        total_vertex_cost_ += cost;
        return num_vertex_ - 1;
    }

    void addEdge(const int& src, const int& dst, const ll& cost = 1) {
        edges_[src].emplace_back(src, dst, cost);
        if(edge_type_ == Edge::Type::Undirected) edges_[dst].emplace_back(dst, src, cost);
        num_edge_++;
        total_edge_cost_ += cost;
    }

    void invalidateEdge(const int& src, const int& dst) {
        auto invalidate = [&](const int& src, const int& dst) -> ll {
                              for(auto& edge : edges_[src])
                                  if(edge.dst == dst) { edge.validity = false; return edge.cost; }
                              return 0LL;
                          };
        total_edge_cost_ -= invalidate(src, dst);
        if(edge_type_ == Edge::Type::Undirected) invalidate(dst, src);
        num_edge_--;
    }

    friend std::ostream& operator <<(std::ostream& os, const Graph& g) {
        for(const auto& v : g.edges_) { for(const auto& e : v) { os << "[" << e << "]" << std::endl; } }
        return os;
    }
private:
    std::vector<Vertex>            vertices_;
    std::vector<std::vector<Edge>> edges_;
    int                            num_vertex_;
    int                            num_edge_;
    ll                             total_edge_cost_;
    ll                             total_vertex_cost_;
    const Edge::Type               edge_type_;
};

/**
 *  最小全域木を求める(Kruskal法)
 *  NOTE: 計算量O(|E|log|V|), Dependencies: comp-Graph,
 *  @Return: 最小全域木を返す グラフが非連結の場合、連結成分ごとに最小全域木を構成する
 */
// 使用例
// auto mst = kruskal(g, start_index, inf_val);
// std::cout << mst.getTotalCost() << std::endl;
Graph kruskal(const Graph& g) {
    if(g.getEdgeType() != Graph::Edge::Type::Undirected) {
        throw std::logic_error("Graph type is invalid");
    }
    auto& vs = g.getVertices();
    auto& es = g.getEdges();
    Graph mst(vs.size(), Graph::Edge::Type::Undirected);
    std::vector<Graph::Edge> mst_e;
    mst_e.reserve(g.getNumEdge() * 2);
    for(const auto& ee : es) for(const auto& e : ee) mst_e.push_back(e);
    auto sort_rule = [](const Graph::Edge& l, const Graph::Edge& r) { return l.cost < r.cost; };
    sort(mst_e.begin(), mst_e.end(), sort_rule);
    struct UF {
        struct N{ll p,r;N(const ll&_p=0,const ll&_r=0):p(_p),r(_r){}};std::vector<N>n;
        explicit UF(const ll&nn){n.reserve(nn);for(ll i=0;i<nn;i++){n.emplace_back(i);}}
        ll R(const ll&x){return(n[x].p==x)?x:n[x].p=R(n[x].p);}
        void U(const ll&x,const ll&y){ll w=R(x);ll z=R(y);
            if(w!=z){if(n[w].r<n[z].r)std::swap(w,z);n[z].p=w;if(n[w].r==n[z].r)n[w].r++;}}
        bool S(const ll&x,const ll&y){return R(x)==R(y);}
    };
    UF uf(vs.size());
    for(const auto& e : mst_e) {
        if(!uf.S(e.src, e.dst)) {
            mst.addEdge(e.src, e.dst, e.cost);
            uf.U(e.src, e.dst);
        }
    }
    return mst;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    std::cin >> N;

    vector<pair<pair<int, int>, int>> city_prior_x;
    vector<pair<pair<int, int>, int>> city_prior_y;
    REP(i, N) {
        int x, y;
        std::cin >> x >> y;
        city_prior_x.emplace_back(make_pair(x, y), i);
        city_prior_y.emplace_back(make_pair(y, x), i);
    }

    Graph g(N, Graph::Edge::Type::Undirected);

    sort(ALL(city_prior_x));
    sort(ALL(city_prior_y));
    for(int i = 0; i < N - 1; i++) {
        g.addEdge(city_prior_x[i].second,
                  city_prior_x[i + 1].second,
                  min(abs(city_prior_x[i].first.first  - city_prior_x[i + 1].first.first),
                      abs(city_prior_x[i].first.second - city_prior_x[i + 1].first.second)));
        g.addEdge(city_prior_y[i].second,
                  city_prior_y[i + 1].second,
                  min(abs(city_prior_y[i].first.first  - city_prior_y[i + 1].first.first),
                      abs(city_prior_y[i].first.second - city_prior_y[i + 1].first.second)));
    }

    auto mst = kruskal(g);
    std::cout << mst.getTotalEdgeCost() << std::endl;
    return 0;
}

