		sz[x] += sz[y];
		sz[y] += sz[x];
	}
}

int N;
pair<int, int> X[100005], Y[100005];

vector<vector<int> > G;

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> X[i].first >> Y[i].first;
		X[i].second = i;
		Y[i].second = i;
	}

	sort(X, X + N);
	sort(Y, Y + N);
	for (int i = 0; i < N - 1; i++) {
		vector<int> x_edge;
		x_edge.push_back(X[i+1].first - X[i].first);
		x_edge.push_back(X[i].second);
		x_edge.push_back(X[i+1].second);
		G.push_back(x_edge);
		vector<int> y_edge;
		y_edge.push_back(Y[i+1].first - Y[i].first);
		y_edge.push_back(Y[i].second);
		y_edge.push_back(Y[i+1].second);
		G.push_back(y_edge);
	}

	// Kruskal's Algorithm
	// First sort the edges by weight in ascending order
	sort(G.begin(), G.end());

	// Initialize UFDS
	init(N);

	// To track the cost of the MST
	int cost = 0;
	// Go through edges one by one, add them into the MST as long as a cycle is not formed
	for (int i = 0; i < G.size(); i++) {
		int W = G[i][0], A = G[i][1], B = G[i][2];
		// Note: adding an edge A - B only forms a cycle if A and B are already connected via some other path
		// Two nodes are already connected, if they are in the same set
		if (find(A) != find(B)) {
			merge(A, B);
			cost += W;
		}
	}

	cout << cost << "\n";

}

