    }
    for (auto it = ys.begin(); next(it) != ys.end(); ++it) {
        for (int i : it->second) {
            for (int j : next(it)->second) {
                int a, b, c, d;
                if (i > j) swap(i, j);
                tie(a, b) = cities[i];
                tie(c, d) = cities[j];
                edges.emplace_back(min(abs(a-c), abs(b-d)), i, j);
            }
        }
    }
    sort(edges.begin(), edges.end());
    edges.erase(unique(edges.begin(), edges.end()), edges.end());

    UnionFind uf(N);
    int first = get<1>(edges[0]);
    int cost = 0;
    for (int i = 0; i < edges.size() && uf.size(first) < N; i++) {
        int c, x, y;
        tie(c, x, y) = edges[i];
        if (uf.findSet(x, y)) continue;
        uf.unionSet(x, y);
        cost += c;
    }
    cout << cost << endl;
    return 0;
}

