class UnionFind {
public:
    vector<int> parent;  //親ノード
    vector<int> Siz;  //集合の大きさ

    // コンストラクタ
    UnionFind(int n): parent(n), Siz(n, 1) {
        rep(i, n) {
            parent[i] = i;
        }
    }

    // n要素で初期化
    void init(int n) {
        parent.resize(n);
        Siz.assign(n, 1);
        rep(i, n) {
            parent[i] = i;
        }
    }

    // xの属する集合の根を求める
    int root(int x) {
        if(parent[x] == x) {
            return x;
        }
        else {
            return parent[x] = root(parent[x]);
        }
    }

    // xとyの属する集合を併合
    void unite(int x, int y) {

        x = root(x);
        y = root(y);
        if(x == y) {
            return;
        }

        if(Siz[x] < Siz[y]) {
            swap(x, y);
        }

        Siz[x] += Siz[y];
        parent[y] = x;
    }

    // xとyが同じ集合に属するかどうか
    bool same(int x, int y) {
        return root(x) == root(y);
    }

    // xの属する集合の要素数を求める
    int size(int x) {
        return Siz[root(x)];
    }
};

int main() {
    int n;
    cin >> n;

    vector<ll> x(n), y(n);
    rep(i, n) {
        cin >> x[i] >> y[i];
    }

    // Kruskal法で使用する枝
    using Edge = pair<ll, pair<int, int>>;
    vector<Edge> edges;

    // x軸方向にソートして隣接している部分のみ
    vector<int> ids(n);
    iota(ids.begin(), ids.end(), 0);
    sort(ids.begin(), ids.end(), [&](int i, int j) { return x[i] < x[j]; });
    for(int i = 0; i+1 < ids.size(), i++) {
        int u = ids[i];
        int v = ids[i+1];
        edges.push_back(Edge(x[v] - x[u], make_pair(u, v)));
    }

    // y軸方向にソートして隣接している部分のみ
    sort(ids.begin(), ids.end(), [&](int i, int j) { return y[i] < y[j]; });
    for(int i = 0; i+1 < ids.size(), i++) {
        int u = ids[i];
        int v = ids[i+1];
        edges.push_back(Edge(y[v] - y[u], make_pair(u, v)));
    }

    // Kruskal法
    sort(edges.begin(), edges.end());
    UnionFind Uni(n);
    ll ans = 0;
    for(auto e : edges) {

        int u = e.second.first;
        int v = e.second.second;
        ll cost = e.first;

        if(Uni.same(u, v)) {
            continue;
        }

        Uni.unite(u, v);
        ans += cost;
    }

    cout << ans << endl;
    return 0;
}

