        v[i] = {{x, y}, i};
        v2[i] = {{y, x}, i};
    }

    sort(ALL(v));
    sort(ALL(v2));

    V<P<int, Pii>> edges;
    REP(i, n-1) {
        int x1 = v[i].first.first, y1 = v[i].first.second, node1 = v[i].second;
        int x2 = v[i+1].first.first, y2 = v[i+1].first.second, node2 = v[i+1].second;
        if (abs(x1-x2) <= abs(y1-y2)) {
            edges.push_back({abs(x1-x2), {node1, node2}});
        }
        y1 = v2[i].first.first, x1 = v2[i].first.second, node1 = v2[i].second;
        y2 = v2[i+1].first.first, x2 = v2[i+1].first.second, node2 = v2[i+1].second;
        if (abs(y1-y2) < abs(x1-x2)) {
            edges.push_back({abs(y1-y2), {node1, node2}});
        }
    }

    sort(ALL(edges));
    UFTree t = UFTree(n);

    ll res = 0;
    FOR(i, edges) {
        int cost = i->first, node1 = i->second.first, node2 = i->second.second;
        if (t.same(node1, node2)) continue;
        t.unite(node1, node2);
        res += cost;
    }

