  sort(ALL(yp));
  auto cost = [](P a, P b){
    ll c = abs(a.first - b.first);
    ll d = abs(a.second - b.second);
    return min(c, d);
  };
  REP(i, n-1){
    ll p = xmp[xp[i]];
    ll q = xmp[xp[i+1]];
    c.emplace_back(cost(xp[i], xp[i+1]), p, q);
    p = ymp[yp[i]];
    q = ymp[yp[i+1]];
    c.emplace_back(cost(yp[i], yp[i+1]), p, q);
  }
  sort(ALL(c));
  ll ans = 0;
  ll m = c.size();
  for(ll i = 0; i < m && uf.size(0) != n; i++){
    ll d, p, q;
    tie(d, p, q) = c[i];
    if(uf.issame(p, q)) continue;
    uf.marge(p, q);
    ans += d;
  }
  cout << ans << endl;
  return 0;
}

