using namespace std;

#define f first
#define s second

long long ans = 0, cnt = 0;

void update(set<pair<int,int>> &used, vector<bool> &seen, pair<int, pair<int,int>> edge) {
    if (seen[edge.s.f] && seen[edge.s.s]) {
        return;
    }
    else if (used.count({edge.s.f, edge.s.s})) {
        return;
    }

    ans += edge.f;
    cnt++;
    used.insert({edge.s.f, edge.s.s});
    used.insert({edge.s.s, edge.s.f});
    seen[edge.s.f] = true;
    seen[edge.s.s] = true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    vector<pair<int,int>> a(n);
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        a[i] = {x, y};
    }

    vector<pair<int,int>> x(n), y(n);
    for (int i = 0; i < n; i++) {
        x[i] = {a[i].f, i};
        y[i] = {a[i].s, i};
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    vector<pair<int, pair<int,int>>> xdist(n-1), ydist(n-1);
    for (int i = 0; i < n - 1; i++) {
        xdist[i] = {x[i+1].f - x[i].f, {x[i+1].s, x[i].s}};
        ydist[i] = {y[i+1].f - y[i].f, {y[i+1].s, y[i].s}};
    }
    sort(xdist.begin(), xdist.end());
    sort(ydist.begin(), ydist.end());

    int p1 = 0, p2 = 0;
    set<pair<int,int>> used;
    vector<bool> seen(n);
    while (cnt < n - 1) {
        if (p1 >= n - 1 && p2 >= n - 1) {
            break;
        }
        else if (p1 >= n - 1) {
            update(used, seen, ydist[p2]);
            p2++;
        }
        else if (p2 >= n - 1) {
            update(used, seen, xdist[p1]);
            p1++;
        }
        else if (xdist[p1].f < ydist[p2].f) {
            update(used, seen, xdist[p1]);
            p1++;
        }
        else {
            update(used, seen, ydist[p2]);
            p2++;
        }
    }

    if (cnt < n - 1) {
        p1 = 0, p2 = 0;
        while (cnt < n - 1) {
            if (xdist[p1].f < ydist[p2].f) {
                if (!used.count({xdist[p1].s.f, xdist[p1].s.s})) {
                    ans += xdist[p1].f;
                    cnt++;
                }
                p1++;
            }
            else {
                if (!used.count({ydist[p2].s.f, ydist[p2].s.s})) {
                    ans += ydist[p2].f;
                    cnt++;
                }
                p2++;
            }
        }
    }

    cout << ans << '\n';

    return 0;
}

