using P=pair<int,int>;
using PP=pair<int,P>;
struct UnionFind{
    vector<int> par,siz;
    UnionFind(int n){
        par.resize(n);
        siz.resize(n,1);
        for(int i=0;i<n;i++)par[i]=i;
    }
    int root(int a){
        if(par[a]==a)return a;
        else return par[a]=root(par[a]);
    }
    bool issame(int a,int b){
        return root(a)==root(b);
    }
    int size(int a){
        return siz[root(a)];
    }
    void marge(int a,int b){
        a=root(a);
        b=root(b);
        if(siz[a]>siz[b])swap(a,b);
        par[a]=b;
        siz[b]+=siz[a];
    }
};
int main(){
    int n;
