struct UnionFind{
    int data[n_max];
    UnionFind(int n){
        REP(i,n) data[i]=i;
    }

    int root(int x){
        int tmp;
        if(data[x]==x) return x;
        else{
            tmp=root(data[x]);
            data[x]=tmp;
            return tmp;
        }
    }

    bool is_same(int x,int y){
        return root(x) == root(y);
    }

    void merge(int x,int y){
        data[root(x)] = root(y);
    }
};


int main(){
    cin >> n;
    dot A[n_max+5],B[n_max+5];
    int x,y;
    FOR(i,1,n+1){
        scanf("%d%d",&x,&y);
        A[i].x=x;
        A[i].y=y;
        A[i].id=i;
        B[i].x=x;
        B[i].y=y;
        B[i].id=i;
    }
    A[0].x=-INF;
    A[0].y=-INF;
    A[0].id=0;
    B[0].x=-INF;
    B[0].y=-INF;
    B[0].id=0;
    A[n+1].x=INF;
    A[n+1].y=INF;
    A[n+1].id=n+1;
    B[n+1].x=INF;
    B[n+1].y=INF;
    B[n+1].id=n+1;

    sort(A+1,A+n+1,x_comp);
    sort(B+1,B+n+1,y_comp);


    edge E[4 * n_max +5];
    int j=0;
    FOR(i,1,n+1){
        E[j].v1=A[i].id;
        E[j].v2=A[i-1].id;
        E[j].d=A[i].x - A[i-1].x;
        j+=1;
        E[j].v1=A[i].id;
        E[j].v2=A[i+1].id;
        E[j].d=A[i+1].x - A[i].x;
        j+=1;
        E[j].v1=B[i].id;
        E[j].v2=B[i-1].id;
        E[j].d=B[i].y - B[i-1].y;
        j+=1;
        E[j].v1=B[i].id;
        E[j].v2=B[i+1].id;
        E[j].d=B[i+1].y - B[i].y;
        j+=1;
    }

    sort(E,E+4*n,e_comp);

