struct Edge {
    int no;
    int from;
    int to;
    long long cost;
    Edge() {}
    Edge(int from, int to, long long cost) : from(from), to(to), cost(cost) {}
    Edge(int no, int from, int to, long long cost) : no(no), from(from), to(to), cost(cost) {}
    bool operator<(const Edge& edge) const {
        return this->cost < edge.cost;
    }
    bool operator>(const Edge& edge) const {
        return this->cost > edge.cost;
    }
};

class UnionFind {
public:
    vector<int> parent;
    vector<int> setSize;

    UnionFind(unsigned int size) {
        parent.resize(size + 1);
        iota(parent.begin(), parent.end(), 0);
        setSize.resize(size + 1, 1);
    }

    // xとyが同じ集合に属するか
    bool isSameSet(int x, int y) {
        return findRoot(x) == findRoot(y);
    }

    // xとyの属する集合を併合
    void unionSet(int x, int y) {
        x = findRoot(x);
        y = findRoot(y);
        if (x == y) { return; }

        parent[x] = y;
        setSize[y] += setSize[x];
    }

private:
    // 木の根を求める
    int findRoot(int x) {
        if (parent[x] == x) {
            return x;
        }
        else {
            return parent[x] = findRoot(parent[x]);
        }
    }
};

/**
 * グラフの最小全域木を求める。O(|E| log|V|)
 * @param num_of_node ノード数
 * @param edges　エッジ　無向グラフならu -> vとv -> uの両方向入れる
 * @return
 */
long long kruskal(int num_of_node, vector<Edge> &edges) {
    sort(edges.begin(), edges.end());

    UnionFind uf(num_of_node);
    long long ans = 0;
    for (const auto e : edges) {
        if (!uf.isSameSet(e.from, e.to)) {
            uf.unionSet(e.from, e.to);
            ans += e.cost;
        }
    }

    return ans;
}

int main() {
    cin.tie(0);
