    FOR(i, 0, N - 1) {
        int x1 = xs[i].first;
        int c1 = xs[i].second;
        int x2 = xs[i + 1].first;
        int c2 = xs[i + 1].second;
        edges.emplace_back(Edge(c1, c2, abs(x1 - x2)));
        edges.emplace_back(Edge(c2, c1, abs(x1 - x2)));
    }
