void citire()
{
    long long i;
    cin>>n;
    for(i=1; i<=n; ++i)
    {
        cin>>A[i].x>>A[i].y;
        A[i].id=i;
    }
    //calculez nodurile pt X
    sort(A,A+n+1,comparX);
    for(i=2; i<n; ++i)
    {
        Nod[A[i].id].push_back(make_pair(A[i-1].id, abs(A[i].x-A[i-1].x)));
        Nod[A[i-1].id].push_back(make_pair(A[i].id, abs(A[i].x-A[i-1].x)));

        Nod[A[i].id].push_back(make_pair(A[i+1].id, abs(A[i].x-A[i+1].x)));
