void rezolvare()
{
    long long i,x=1,sz=Nod[1].size();
    for(i=0; i<sz; ++i)
    {
        if(!Intalnit[Nod[x][i].first])
            Pq.push(make_pair(Nod[x][i].second, Nod[x][i].first));
    }
    Intalnit[1]=1;
    while(!Pq.empty())
    {
        x=Pq.top().second;
        if(Intalnit[x])
        {
            Pq.pop();
            continue;
        }
        Intalnit[x]=1;
        ans+=Pq.top().first;
        sz=Nod[x].size();
        Pq.pop();

        for(i=0; i<sz; ++i)
        {
            if(!Intalnit[Nod[x][i].first])
            {
                Pq.push(make_pair(Nod[x][i].second, Nod[x][i].first));
            }
        }

    }
    cout<<ans;
}

