int X[101010], Y[101010];
class UnionFind {
public:
	vector<int> r, p;

	UnionFind() {}
	UnionFind(int size) {
		r.resize(size, 0);
		p.resize(size, 0);
		for (int i = 0; i < size;i++)makeSet(i);
	}

	void makeSet(int x) {
		p[x] = x;
		r[x] = 0;
	}

	bool same(int x, int y) {
		return findSet(x) == findSet(y);
	}

	void unite(int x, int y) {
		link(findSet(x), findSet(y));
	}

	void link(int x, int y) {
		if (r[x] > r[y]) {
			p[y] = x;
		}
		else {
			p[x] = y;
			if (x == y) {
				r[y]++;
			}
		}
	}


	int findSet(int x) {
		if (x == p[x]) {
			return x;
		}
		else {
			return p[x] = findSet(p[x]);
		}
	}
};

int main() {
	int N;
	cin >> N;
	UnionFind un(N);
	for (int i = 0; i < N; i++) {
		cin >> X[i] >> Y[i];
	}

	vector<int>xorder, yorder;
	for (int i = 0; i < N; i++) { xorder.pb(i); yorder.pb(i); }
	sort(all(xorder), [&](int i, int j) {return X[i] < X[j]; });
	sort(all(yorder), [&](int i, int j) {return Y[i] < Y[j]; });

	vector<vector<ll>>edges;
	int xsz = (int)xorder.size();
	int ysz = (int)yorder.size();
	for (int i = 0; i < xsz - 1; i++) {
		edges.pb({X[xorder[i+1]]-X[xorder[i]],xorder[i],xorder[i+1]});
	}
	for (int i = 0; i < ysz - 1; i++) {
		edges.pb({Y[yorder[i + 1]]-Y[yorder[i]],yorder[i],yorder[i + 1] });
	}
	sort(all(edges));

	ll ans = 0;
	fore(e, edges) {
		if (!un.same(e[1], e[2])) {
			un.unite(e[1], e[2]);
			ans += e[0];
		}
	}
	puts(ans);


	return 0;
}

