  return get_root(union_find_vec[node], union_find_vec);
}

int main(void) {
  long N;
  cin >> N;
  unordered_map<long, pair<long, long>> points;
  rep (i, N) {
    long x, y;
    cin >> x >> y;
    points[i] = make_pair(x, y);
  }
  vector<pair<long, long>> xs, ys;
  for (auto it: points) {
    xs.push_back(make_pair(it.second.first, it.first));
    ys.push_back(make_pair(it.second.second, it.first));
  }
  sort(xs.begin(), xs.end());
  sort(ys.begin(), ys.end());
  vector<pair<long, pair<long, long>>> edges;
  rep (i, N-1) {
    edges.push_back(make_pair(xs[i+1].first - xs[i].first, make_pair(xs[i].second, xs[i+1].second)));
    edges.push_back(make_pair(ys[i+1].first - ys[i].first, make_pair(ys[i].second, ys[i+1].second)));
  }
  sort(edges.begin(), edges.end());

  long result = 0;

  vector<long> union_find_vec(N, -1);
  for (auto it: edges) {
    long a = it.second.first;
    long b = it.second.second;
    long a_root = get_root(a, union_find_vec);
    long b_root = get_root(b, union_find_vec);
    if (a_root == b_root) continue;
    result += it.first;
    union_find_vec[b] = a_root;
    union_find_vec[b_root] = a_root;
  }

  cout << result << endl;

  return 0;
}

