	}
	sort(X.begin(), X.end());
	sort(Y.begin(), Y.end());

	vtll edges;
	REP(i, N-1){
		ll x,  v;  tie(x,v)  =X[i];
		ll xx, vv; tie(xx,vv)=X[i+1];
		edges.emplace_back(xx-x, v, vv);
	}
	REP(i, N-1){
		ll y,  v;  tie(y,v)  =Y[i];
		ll yy, vv; tie(yy,vv)=Y[i+1];
		edges.emplace_back(yy-y, v, vv);
	}

	sort(edges.begin(), edges.end());

	UnionFindTree uft(N);

	ll count=0, sumyen=0;
	EACH(edge, edges){
		ll yen, v, vv; tie(yen, v, vv) = edge;
		if (uft.Same(v, vv)) continue;
		uft.Unite(v, vv);
		count++;
		sumyen+=yen;
		if (count == N-1) break;
	}
	cout << sumyen << '\n';
}


