class UnionFindTree {
private:
    vector<int> parent;
    vector<int> count;
public:
    UnionFindTree(int n) : parent(n), count(n, 1) {
        // 最初は全てを根として初期化
        for(int i = 0; i < n; i++) parent[i] = i;
    }

    int get_root(const int x) {
        // データxが属する木の根を取得する
        if (parent[x] == x) return x;
        // 取得したものは直接木の根をつなぐ(経路圧縮)
        return parent[x] = get_root(parent[x]);
    }

    void unite(const int x, const int y) {
        // xとyの木を併合する
        int rx = get_root(x);
        int ry = get_root(y);
        // 元から同じ木に属している場合は何もしない
        if (rx == ry) return;
        // xの属する木をyの属する木につける
        parent[rx] = ry;
        count[ry] += count[rx];
        count[rx] = 0;
    }

    bool is_same_root(const int x, const int y) {
        return get_root(x) == get_root(y);
    }

    int get_size(const int x) {
        return count[get_root(x)];
    }

    void print() {
        for(auto elm : parent) cout << elm << " ";
        cout << endl;
        for(auto elm : count) cout << elm << " ";
        cout << endl;
    }
};

int main() {
    int n;
    cin >> n;

    vector<pair<int, int>> x(n);
    vector<pair<int, int>> y(n);
    for (auto i = 0; i < n; i++) {
        int a, b; cin >> a >> b;
        x[i] = {a, i}; y[i] = {b, i};
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    UnionFindTree tree(n);
    map<int64_t, vector<pair<int, int>>> g;
    for (auto i = 0; i < n - 1; i++) {
        int64_t cost = abs(x[i].first - x[i + 1].first);
        g[cost].emplace_back(x[i].second, x[i + 1].second);
        cost = abs(y[i].first - y[i + 1].first);
        g[cost].emplace_back(y[i].second, y[i + 1].second);
    }

    int64_t ans = 0;
    for (auto &a : g) {
        for (auto &b : a.second) {
            if (not tree.is_same_root(b.first, b.second)) {
                tree.unite(b.first, b.second);
                ans += a.first;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

