using namespace std;

class UnionFind
{
    private:
        std::vector<int> parent;  // parent[x]: x の根の番号
                                  //            x が根の場合はその連結成分の大きさ
        std::vector<int> rank;    // rank[x]  : x が属する木の高さ
        std::size_t sz;           // 連結成分の数

    public:
        // x が親の場合、parent[x] = -(その連結成分の大きさ)
        UnionFind( std::size_t n ): parent(n, -1), rank(n, 0), sz(n) {}

        // x が属する集合の親を返し、x を親に直接繋ぎ直す(経路圧縮)
        int find( int x )
        {
            if( parent[x] < 0 ) return x;
            else return parent[x] = find( parent[x] );
        }

        // x が属する集合と y が属する集合を統合する
        bool unite( int x, int y )
        {
            x = find( x );
            y = find( y );
            if( x == y ) return false;

            // 大きい方(x)に小さい方(y)を繋げる
            if( rank[x] < rank[y] ) std::swap( x, y );

            parent[x] += parent[y];  // x に連結している成分の大きさを更新する
            parent[y] = x;           // y を x に繋ぐ
            if( rank[x] == rank[y] ) rank[x]++;
            sz--;

            return true;
        }

        bool same( int x, int y ) { return find(x) == find(y); }
        std::size_t size()        { return sz; }
        std::size_t size( int x ) { return - parent[find(x)]; }
};

struct edge{
    int from, to, cost;
    edge(int i, int j, int c): from(i), to(j), cost(c) {}
};

bool operator> (const edge& edge1, const edge& edge2){
    return edge1.cost > edge2.cost;
}

int main()
{
    int N;
    cin >> N;
    vector<pair<int,int>> x(N), y(N);  // (coordinate, index)
    for(int i = 0; i < N; ++i){
        int x_in, y_in;
        cin >> x_in >> y_in;
        x[i] = make_pair(x_in, i);
        y[i] = make_pair(y_in, i);
    }

    // 変の候補を priority_queue に挿入
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());
    priority_queue<edge, vector<edge>, greater<edge>> q;
    for(int i = 0; i < N-1; ++i){
        q.push(edge(x[i].second, x[i+1].second, abs(x[i].first-x[i+1].first)));
        q.push(edge(y[i].second, y[i+1].second, abs(y[i].first-y[i+1].first)));
    }

    UnionFind uni(N);
    long long ans = 0;
    while(!q.empty()){
        auto tmp = q.top();
        q.pop();
        if(uni.same(tmp.from, tmp.to)) continue;
        uni.unite(tmp.from, tmp.to);
        ans += tmp.cost;
    }
    cout << ans << endl;

    return 0;
}

