        xsort[i]=P(x, i);
        ysort[i]=P(y, i);
    }

    sort(xsort.begin(), xsort.end());
    sort(ysort.begin(), ysort.end());

    for(int i=0; i<n-1; i++){
        int cx, cv, nx, nv;
        tie(cx, cv)=xsort[i];
        tie(nx, nv)=xsort[i+1];
        int cost=abs(nx-cx);
        edge[i]=T(cost, cv, nv);
    }
    for(int i=0; i<n-1; i++){
        int cy, cv, ny, nv;
        tie(cy, cv)=ysort[i];
        tie(ny, nv)=ysort[i+1];
        int cost=abs(ny-cy);
        edge[i+n-1]=T(cost, cv, nv);
    }

    cout << kruskal(n, edge) << endl;
}

