    priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> q;
    q.push(make_pair(0, 0));
    vector<bool> isVisited(N, false);
    while(!q.empty())
    {
        pair<ll, ll> p = q.top();
        q.pop();
        if (isVisited[p.second]) continue;
        isVisited[p.second] = true;
        ans += p.first;
        REPV(it, G[p.second])
        {
            q.push(*it);
        }
    }

    cout << ans << endl;
}

