int link[maxn];
int sizex[maxn];

int find(int a){
    if(a==link[a])
        return a;
    return link[a] = find(link[a]);
}

bool same(int a, int b){
    return find(a)==find(b);
}

void unite(int a, int b){
    a = find(a);
    b = find(b);
    if(a==b)
        return;
    if(sizex[a]<sizex[b])
        swap(a, b);
    sizex[b] += a;
    link[a] = b;
}

