using namespace std;

class Node
{
    public:
        int id, x, y;
};

bool xsort(Node a, Node b)
{
    return a.x < b.x ? true : false;
}
bool ysort(Node a, Node b)
{
    return a.y < b.y ? true : false;
}

void build_table(vector<Node>& nodes, vector<vector<pair<int, int> > >& cost)
{
    vector<Node> sorted(nodes);
    sort(sorted.begin(), sorted.end(), xsort);
    for (auto itr = sorted.begin(); itr != sorted.end(); ++itr) {
        if (itr != sorted.begin())
            cost.at(itr->id).push_back(make_pair(itr->x - (itr - 1)->x, (itr - 1)->id));
        if (itr != sorted.end())
            cost.at(itr->id).push_back(make_pair((itr + 1)->x - itr->x, (itr + 1)->id));
    }
    sort(sorted.begin(), sorted.end(), ysort);
    for (auto itr = sorted.begin(); itr != sorted.end(); ++itr) {
        if (itr != sorted.begin())
            cost.at(itr->id).push_back(make_pair(itr->y - (itr - 1)->y, (itr - 1)->id));
        if (itr != sorted.end())
            cost.at(itr->id).push_back(make_pair((itr + 1)->y - itr->y, (itr + 1)->id));
    }
}

bool on[1000000];

unsigned long long prim(vector<vector<pair<int, int> > >& cost)
{
    unsigned long long sum = 0;
    //bool on[cost.size()];
    for (int i = 0; i < cost.size(); i++) {
        on[i] = false;
    }
    // pair<cost, node>
    priority_queue<pair<int, int>, vector<pair<int, int> >, greater<pair<int, int> > > PQ;
    PQ.push(make_pair(0, 0));
    while (!PQ.empty()) {
        pair<int, int> edge = PQ.top();
        PQ.pop();
        if (on[edge.second]) continue;
        on[edge.second] = true;
        sum += edge.first;
        for (auto itr = cost[edge.second].begin(); itr != cost[edge.second].end(); ++itr) {
            if (on[itr->second]) continue;
            PQ.push(*itr);
        }
    }
    return sum;
}

int main()
{
    int n;
    cin >> n;

    vector<Node> nodes;
    // pair<cost, dst>
    vector<vector<pair<int, int> > > cost(n);
    Node node;
    for (int i = 0; i < n; i++) {
        node.id = i;
        cin >> node.x >> node.y;
        nodes.push_back(node);
    }
    build_table(nodes, cost);
    cout << prim(cost) << endl;
    return 0;
}

