  priority_queue<vl,vector<vl>,decltype(cp)> cand(cp);
  incl[0] = true;
  REP(j,edge[0][0]/2){
    cand.push({edge[0][2*j+1],edge[0][2*j+2]});
  }

  while(cnt<n){
    vl eg = cand.top();
    cand.pop();
    if(!incl[eg[0]]){
      incl[eg[0]] = true;
      cnt ++;
      REP(i,edge[eg[0]][0]/2){
        if(incl[edge[eg[0]][2*i+1]]) continue;
        cand.push({edge[eg[0]][2*i+1],edge[eg[0]][2*i+2]});
      }
      ans += eg[1];
    }
  }
  cout << ans << endl;

  return 0;
}

