struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2
    vector<int> r_size; //頂点vが何個の頂点を従えているか（自身を含む）

    //コンストラクタで初期化
    UnionFind(int n) : par(n), r_size(n) { //最初は全てが根であるとして初期化
        for(int i = 0; i < n; i++){
            par[i] = i; //vectorのassignを使ってもいいかもしれない
        }
        r_size.assign(n, 1);
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        // 経路圧縮
        return par[x] = root(par[x]); //これで根を貼り直してる．巧妙なテクニックや...
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま

        //par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
        // xとyの根が同じでない(=同じ木にない)時：サイズが小さい方の根をサイズが大きい方の根につける
        if(r_size[rx] < r_size[ry]){
            par[rx] = ry;
            r_size[ry] += r_size[rx];
        }else{
            par[ry] = rx;
            r_size[rx] += r_size[ry];
        }
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    //
    int size(int x){
        return r_size[root(x)];
    }
};

