class uftree{
  std::vector<int> parent;
  std::vector<int> rank;
  std::vector<long long> ufsize;
  public:
  uftree(int n) : parent(n), rank(n), ufsize(n, 1) {
    for(int i = 0; i < n; i++){
      parent[i] = i;
    }
  }
  int root(int x){
    std::vector<int> update_node_arr;
    while(parent[x] != x){
      update_node_arr.push_back(x);
      x = parent[x];
    }
    for(const auto& it: update_node_arr) parent[it] = x;
    return x;
  }

  bool same(int x, int y){
    return root(x)==root(y);
  }

  long long size(int x){
    return ufsize[root(x)];
  }

  void unite(int x, int y){
    x = root(x);
    y = root(y);
    if(x==y) return;
    long long xsize = size(x);
    long long ysize = size(y);
    if(rank[x]<rank[y]){
      parent[x] = y;
      ufsize[y] += xsize;
    }else{
      parent[y] = x;
      ufsize[x] += ysize;
      if(rank[x]==rank[y]) rank[x]++;
    }
  }
};

