  }

  std::vector<std::tuple<int, int, int>> edges;
  std::sort(index_arr.begin(), index_arr.end(), [&](int l, int r){return std::get<0>(xy_arr[l]) < std::get<0>(xy_arr[r]);});
  for(int i = 0; i < N-1; i++) edges.push_back(std::make_tuple(std::get<0>(xy_arr[index_arr[i+1]])-std::get<0>(xy_arr[index_arr[i]]), index_arr[i+1], index_arr[i]));
  std::sort(index_arr.begin(), index_arr.end(), [&](int l, int r){return std::get<1>(xy_arr[l]) < std::get<1>(xy_arr[r]);});
  for(int i = 0; i < N-1; i++) edges.push_back(std::make_tuple(std::get<1>(xy_arr[index_arr[i+1]])-std::get<1>(xy_arr[index_arr[i]]), index_arr[i+1], index_arr[i]));

  std::sort(edges.begin(), edges.end());
