    rep(i, n) {
        ll x, y;
        cin >> x >> y;
        px[i] = make_pair(x, i);
        py[i] = make_pair(y, i);
    }
    sort(all(px));
    sort(all(py));

    const ll m = 2*n-2;
    vector<Edge> es(m);  // es[i] : 辺iは頂点es[i].aと頂点es[i].bをコストes[i].costで結ぶ
    rep(i, n-1) {
        es[i].a = px[i].second;
        es[i].b = px[i+1].second;
        es[i].cost = px[i+1].first - px[i].first;
    }
    rep(i, n-1) {
        es[i+(n-1)].a = py[i].second;
        es[i+(n-1)].b = py[i+1].second;
        es[i+(n-1)].cost = py[i+1].first - py[i].first;
    }
    sort(all(es));  // esをcostの昇順でソート

    UnionFind Uni(n);
    Uni.init(n);

    // クラスカル法。計算量はO(E*log(E))
    ll min_cost = 0;
    rep(i, m) {
        if(!Uni.same(es[i].a, es[i].b)) {
            Uni.unite(es[i].a, es[i].b);
            min_cost += es[i].cost;
        }
    }

    out(min_cost);
    re0;
}

