struct union_find {
    ll rank[MAX_N], par[MAX_N];
    ll cnt;
    union_find(ll n) { cnt = 0;rep(i, n) rank[i] = 1, par[i] = i; }

    ll find(ll x) {
        if(x == par[x]) return x;
        else return par[x] = find(par[x]);
    }
    void unite(ll x, ll y, ll cost) {
        x = find(x); y = find(y);
        if(x == y) return;
        cnt += cost;
        if(rank[x] > rank[y]) par[y] = x;
        else {
            par[x] = y;
            if(rank[x] == rank[y]) rank[y]++;
        }
    }
    bool same(ll x, ll y) {
        x = find(x); y = find(y);
        return x == y;
    }
};


