class Prim
{
public:
	const static ll LLBIG = 987654321987654321LL;

	Prim(int v) : V(v)
	{
		cost.resize(V);
		for (int i = 0; i<SZ(cost); i++)
		{
			cost[i].resize(V);
			fill(cost[i].begin(), cost[i].end(), LLBIG);
		}

		mincost.resize(V);
		used.resize(V);
		for (int i = 0; i<V; i++)
		{
			mincost[i] = LLBIG;
			used[i] = false;
		}
	}

	void setcost(int from, int to, ll co)
	{
		assert(0 <= from && from <= V - 1);
		assert(0 <= to && to <= V - 1);
		amin(cost[from][to], co);
		amin(cost[to][from], co);
	}

	ll run()
	{
		mincost[0] = 0;
		ll res = 0;
		while (1)
		{
			int v = NG;
			for (int u = 0; u<V; u++)
			{
				if (!used[u] && (v == NG || mincost[u]<mincost[v]))
				{
					v = u;
				}
			}

			if (v == NG) break;
			used[v] = true;
			res += mincost[v];

			for (int u = 0; u<V; u++)
			{
				mincost[u] = min(mincost[u], cost[v][u]);
			}
		}
		return res;
	}

private:
	const int V;
	vector < vector <ll> > cost;
	vector <ll> mincost;
	vector <bool> used;
};


