// Union-Find
// n要素で初期化
void init(int par[], int rank[], int n){
    for(int i=0;i<n;i++){
        par[i] = i;
        rank[i] = 0;
    }
}

// 木の根を求める
int find(int par[], int x){
    if(par[x] == x){
        return x;
    }else{
        return par[x] = find(par,par[x]);
    }
}

// xとyの属する集合を併合
void unite(int par[], int rank[], int x, int y){
    x = find(par,x);
    y = find(par,y);
    if(x == y) return;

    if(rank[x] < rank[y]){
        par[x] = y;
    }else{
        par[y] = x;
        if(rank[x] == rank[y]) rank[x]++;
    }
}

// xとyが同じ集合に属するか否か
bool same(int par[], int x, int y){
    return find(par,x) == find(par,y);
}

bool comp(const edge& e1, const edge& e2){
    return e1.cost < e2.cost;
}

long long int kruscal(int V, int E, edge es[]){
    sort(es, es + E, comp); // edge.costが小さい順にソートする

    int par[V]; // 親
    int rank[V]; // 木の深さ
    init(par, rank, V); // Union-Findの初期化
    long long int res = 0;
    for(int i=0; i<E; i++){
        edge e = es[i];
        if(!same(par,e.u, e.v)){
            unite(par, rank, e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}

int cmp1(const void *a, const void *b){ // 昇順
    // qsort
    // http://www.cc.kyoto-su.ac.jp/~yamada/ap/qsort.html

    return *(int*)a - *(int*)b;
}
int cmp2(const void *a, const void *b){ // 降順
    // qsort
    // http://www.cc.kyoto-su.ac.jp/~yamada/ap/qsort.html

    return *(int*)b - *(int*)a;
}

int main() {
    // main関数で定義するもの



    int n;
