        x = root(x);
        y = root(y);
        if (x == y)return;
        if (rank[x] < rank[y]) {
            par[x] = y;
            memo[y] += memo[x];
        } else {
            par[y] = x;
            memo[x] += memo[y];
            if (rank[x] == rank[y])rank[x]++;
        }
    }

    int size(int x) {
        return memo[root(x)];
    }
}

