    sort(v.begin(), v.end(), [](auto x, auto y) {
        return x.second.first > y.second.first;
    });
    priority_queue<pair<int, P>> q;
    for (int i = 1; i < N; i++) {
        q.push(make_pair(v[i].second.first - v[i - 1].second.first, P(v[i].first, v[i - 1].first)));
    }
    sort(v.begin(), v.end(), [](auto x, auto y) {
        return x.second.second > y.second.second;
    });
    for (int i = 1; i < N; i++) {
        q.push(make_pair(v[i].second.second - v[i - 1].second.second, P(v[i].first, v[i - 1].first)));
    }
    uf::init(N);
    ll ans = 0;
    while (q.size()) {
        auto x = q.top();
        q.pop();
        if (uf::same(x.second.first, x.second.second)) {
            continue;
        }
        ans -= x.first;
        uf::unite(x.second.first, x.second.second);
        if (uf::size(x.second.first) == N) {
            break;
        }
    }
    cout << ans << endl;
}

