struct UnionFind
{
  vector<int> par;
  vector<int> sizes;

  UnionFind(int n) : par(n), sizes(n, 1) {
    rep(i,n) par[i] = i;
  }

  int find(int x) {
    if (x == par[x]) return x;
    return par[x] = find(par[x]);
  }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);

    if (x == y) return;

    if (sizes[x] < sizes[y]) swap(x, y);

    par[y] = x;
    sizes[x] += sizes[y];

  }

  bool same(int x, int y) {
    return find(x) == find(y);
  }

  int size(int x) {
    return sizes[find(x)];
  }
};

struct Edge
{
  int a, b, cost;

  bool operator<(const Edge& o) const {
    return cost < o.cost;
  }
};

struct Graph
{
  int n;
  vector<Edge> es;

  int kruskal() {
    sort(es.begin(), es.end());

    UnionFind uf(n);
    int min_cost = 0;

    rep(ei, es.size()) {
      Edge& e = es[ei];
      if (!uf.same(e.a, e.b)) {
        min_cost += e.cost;
        uf.unite(e.a, e.b);
      }
    }

    return min_cost;
  }
};

Graph input_graph() {
  Graph g;
  cin >> g.n;
  vector<long long> x(g.n), y(g.n);
  for(int i=0;i<g.n;i++){
      cin >> x[i] >> y[i];
  }
  for(int i=0;i<g.n-1;i++){
    for(int j=i+1; j<g.n;j++){
      Edge e;
      e.a = i; e.b = j;
      e.cost = min(abs(x[i] - x[j]),abs(y[i]-y[j]));
      g.es.push_back(e);
    }
  }
  return g;
}


int main()
{
  Graph g = input_graph();
  cout <<  g.kruskal() << endl;
  return 0;
}

