struct Edge {
	int to; int cost;
	Edge(int t, int c) { to = t; cost = c; }
};
using Graph = vector<vector<Edge>>;

ll prim(const Graph& graph, int start)
{
	vector<bool> seen(graph.size(), 0);
	using CostPair = pair<ll, int>;
	priority_queue<CostPair, vector<CostPair>, greater<CostPair>> pq;
	pq.push(make_pair(0, start));
	ll sumcost = 0;
	while (!pq.empty()) {
		auto top = pq.top(); pq.pop();
		ll c = top.first;
		int v = top.second;
		if (seen[v]) continue;
		seen[v] = 1;
		sumcost += c;
		for (Edge e : graph[v]) {
			if (seen[e.to]) continue;
			pq.push(make_pair(e.cost, e.to));	//keyは、辺のコスト
		}
	}
	return sumcost;
}

