  }
  bool issame(int x, int y) {
    return (root(x) == root(y));
  }
  bool merge(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return true;
  }
  int size(int x) {
    return (-data[root(x)]);
  }
};

template<typename T>
T kruskal(Edges<T> es, int n) {
  sort(es.begin(), es.end(), [](const edge<T> &a, const edge<T> &b) {
    return (a.cost < b.cost);
  });
  UnionFind tree(n);
  T ret = 0;
  for (auto e : es) {
    if (tree.merge(e.src, e.to)) ret += e.cost;
  }
  return ret;
}

