struct UnionFind
{
    vector<int> par, rank;

    UnionFind(int n){
        par.resize(n);
        rank.resize(n);
        for(int i = 0; i < n; i++){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int i){
        if(i == par[i]) return i;
        return par[i] = find(par[i]);
    }

    bool same(int i, int j){
        return find(i) == find(j);
    }

    void unite(int i, int j){
        if(same(i, j)) return;
        i = find(i), j = find(j);
        if(rank[i] < rank[j]) par[i] = j;
        else{
            par[j] = i;
            if(rank[i] == rank[j]) rank[i]++;
        }
    }
};

int main()
{
    int n;
    cin >> n;
    P px[100005], py[100005];
    for(int i = 0; i < n; i++){
        ll x, y;
        cin >> x >> y;
        px[i] = P(x, i);
        py[i] = P(y, i);
    }
    sort(px, px + n);
    sort(py, py + n);
    PP p[200005];
    for(int i = 0; i < n - 1; i++) p[i] = PP(px[i + 1].first - px[i].first, P(px[i + 1].second, px[i].second));
    for(int i = 0; i < n - 1; i++) p[i + n - 1] = PP(py[i + 1].first - py[i].first, P(py[i + 1].second, py[i].second));
    sort(p, p + n * 2 - 2);
    UnionFind uf(n);
    ll ans = 0;
    for(int i = 0; i < n * 2 - 2; i++){
        P q = p[i].second;
        if(!uf.same(q.first, q.second)){
            ans += p[i].first;
            uf.unite(q.first, q.second);
        }
    }
    cout << ans << endl;
}

