    UF uf(N);
    auto comp = [](bridge b1, bridge b2) { return b1.d > b2.d; };
    priority_queue<bridge, vc<bridge>, decltype(comp)> pq(comp);
    rep(i, N - 1) pq.emplace(X[i + 1].first - X[i].first, X[i].second, X[i + 1].second);
    rep(i, N - 1) pq.emplace(Y[i + 1].first - Y[i].first, Y[i].second, Y[i + 1].second);

    ll ans = 0;
    while(!pq.empty()){
        bridge b = pq.top();
        pq.pop();
        if (uf.issame(b.u, b.v)) continue;
