struct edge { int u, v, cost; };

edge es[100010];
int N, E;
pair<int, int>p[100010];
int par[100010];
int ran[100010];

bool comp(const edge& e1, const edge& e2) {
	return e1.cost < e2.cost;
}

void init(int n) {
	for (int i = 0; i < n; i++) {
		par[i] = i;
		ran[i] = 0;
	}
}

int find(int x) {
	if (par[x] == x)return x;
	else return par[x] = find(par[x]);
}

void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y)return;
	if (ran[x] < ran[y]) {
		par[x] = y;
	} else {
		par[y] = x;
		if (ran[x] == ran[y])ran[x]++;
	}
}

bool same(int x, int y) {
	return find(x) == find(y);
}

int kruskal() {
	sort(es, es + E, comp);
	init(N);
	int res = 0;
	for (int i = 0; i < E; i++) {
		edge e = es[i];
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}

int main() {
	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> p[i].first >> p[i].second;
	}
	for (int i = 0; i < N - 1; i++) {
		for (int j = i + 1; j < N; j++) {
			es[E].u = i;
			es[E].v = j;
			es[E].cost = min(abs(p[j].first - p[i].first), abs(p[j].second - p[i].second));
			E++;
		}
	}
	cout << kruskal() << endl;
	return 0;
}

