using namespace std;

using pii = pair<int, int>;
using ppii = pair<int, pii>;

pii x[100010], y[100010];

//頂点のキュー
vector<ppii> queue;

// 素集合データ構造
struct UnionFind
{
	// par[i]：データiが属する木の親の番号。i == par[i]のとき、データiは木の根ノードである
	vector<int> par;
	// sizes[i]：根ノードiの木に含まれるデータの数。iが根ノードでない場合は無意味な値となる
	vector<int> sizes;

	UnionFind(int n) : par(n), sizes(n, 1) {
		// 最初は全てのデータiがグループiに存在するものとして初期化
		for (int i = 0; i < n; i++) par[i] = i;
	}

	// データxが属する木の根を得る
	int find(int x) {
		if (x == par[x]) return x;
		return par[x] = find(par[x]);  // 根を張り替えながら再帰的に根ノードを探す
	}

	// 2つのデータx, yが属する木をマージする
	void unite(int x, int y) {
		// データの根ノードを得る
		x = find(x);
		y = find(y);

		// 既に同じ木に属しているならマージしない
		if (x == y) return;

		// xの木がyの木より大きくなるようにする
		if (sizes[x] < sizes[y]) swap(x, y);

		// xがyの親になるように連結する
		par[y] = x;
		sizes[x] += sizes[y];
		// sizes[y] = 0;  // sizes[y]は無意味な値となるので0を入れておいてもよい
	}

	// 2つのデータx, yが属する木が同じならtrueを返す
	bool same(int x, int y) {
		return find(x) == find(y);
	}

	// データxが含まれる木の大きさを返す
	int size(int x) {
		return sizes[find(x)];
	}
};

int main() {

	int n;
	cin >> n;

	for (int i = 0; i < n; i++) {
		cin >> x[i].first >> y[i].first;
		x[i].second = y[i].second = i;
	}

	sort(x,x+n);
	sort(y,y+n);

	for (int i = 0; i < n - 1; i++) {
		queue.push_back(ppii(abs(x[i].first - x[i+1].first),pii(x[i].second,x[i+1].second)));
	}

	for (int i = 0; i < n - 1; i++) {
		queue.push_back(ppii(abs(y[i].first - y[i + 1].first), pii(y[i].second, y[i + 1].second)));
	}

	sort(queue.begin(),queue.end());

	long long int res = 0;

	UnionFind uf(n);

	for (int i = 0; i < queue.size(); i++) {

		ppii t = queue[i];

		if (!uf.same(t.second.first,t.second.second)) {
			uf.unite(t.second.first, t.second.second);
			res += t.first;
		}

	}

	cout << res << endl;

}

