using namespace std;

vector<bool> on(100005);

class Node
{
    public:
        unsigned long long id, x, y;
};

bool xsort(Node a, Node b)
{
    return a.x < b.x ? true : false;
}
bool ysort(Node a, Node b)
{
    return a.y < b.y ? true : false;
}

void build_table(vector<Node>& nodes, vector<vector<pair<unsigned long long, unsigned long long> > >& cost)
{
    vector<Node> sorted(nodes);
    sort(sorted.begin(), sorted.end(), xsort);
    for (auto itr = sorted.begin(); itr != sorted.end(); ++itr) {
        if (itr != sorted.begin())
            cost.at(itr->id).push_back(make_pair(itr->x - (itr - 1)->x, (itr - 1)->id));
        if (itr != sorted.end())
            cost.at(itr->id).push_back(make_pair((itr + 1)->x - itr->x, (itr + 1)->id));
    }
    sort(sorted.begin(), sorted.end(), ysort);
    for (auto itr = sorted.begin(); itr != sorted.end(); ++itr) {
        if (itr != sorted.begin())
            cost.at(itr->id).push_back(make_pair(itr->y - (itr - 1)->y, (itr - 1)->id));
        if (itr != sorted.end())
            cost.at(itr->id).push_back(make_pair((itr + 1)->y - itr->y, (itr + 1)->id));
    }
}

unsigned long long prim(vector<vector<pair<unsigned long long, unsigned long long> > >& cost)
{
    unsigned long long sum = 0;
    for (unsigned long long i = 0; i < cost.size(); i++) {
        on[i] = false;
    }
    // pair<cost, node>
    priority_queue<pair<unsigned long long, unsigned long long>, vector<pair<unsigned long long, unsigned long long> >, greater<pair<unsigned long long, unsigned long long> > > PQ;
    PQ.push(make_pair(0, 0));
    while (!PQ.empty()) {
        pair<unsigned long long, unsigned long long> edge = PQ.top();
        PQ.pop();
        if (on.at(edge.second)) continue;
        on.at(edge.second) = true;
        sum += edge.first;
        for (auto itr = cost.at(edge.second).begin(); itr != cost.at(edge.second).end(); ++itr) {
            if (on.at(itr->second)) continue;
            PQ.push(*itr);
        }
    }
    return sum;
}

int main()
{
    unsigned long long n;
    cin >> n;

    vector<Node> nodes;
    // pair<cost, dst>
    vector<vector<pair<unsigned long long, unsigned long long> > > cost(n);
    Node node;
    for (unsigned long long i = 0; i < n; i++) {
        node.id = i;
        cin >> node.x >> node.y;
        nodes.push_back(node);
    }
    build_table(nodes, cost);
    cout << prim(cost) << endl;
    return 0;
}

