struct edge {
    int from;
    int to;
    ll cost;
    edge(){}
    edge(int a, int b, ll c) : from(a), to(b), cost(c){}
};

struct UnionFind {
public:
    vector <ll> par; // 
    vector <ll> siz; // 

    UnionFind(ll sz_) : par(sz_), siz(sz_, 1LL) {
        for (ll i = 0; i < sz_; ++i) par[i] = i;
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);
        for (ll i = 0; i < sz_; ++i) par[i] = i;
    }

    ll root(ll x) {
        while (par[x] != x) {
            x = par[x] = par[par[x]];
        }
        return x;
    }

    bool merge(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool issame(ll x, ll y) {
        return root(x) == root(y);
    }

    ll size(ll x) {
        return siz[root(x)];
    }
};

struct KruskalRunner {
    static bool orderByCost(const edge& e1, const edge& e2) {
        return e1.cost < e2.cost;
    }

    ll solve(int vCount, vector<edge>& edges) {
        sort(edges.begin(), edges.end(), orderByCost);
        UnionFind uf = UnionFind(vCount);
        ll sum = 0;
        for (int i = 0; i < edges.size(); ++i) {
            edge e = edges[i];
            if (!uf.issame(e.from, e.to)) {
                uf.merge(e.from, e.to);
                sum += e.cost;
            }
        }
        return sum;
    }
};

int main() {

    ll n;
    cin >> n;
    vector<P> xs(n);
    vector<P> ys(n);
    for (int i = 0; i < n; i++) {
        ll x, y;
        cin >> x >> y;
        xs[i] = { x, i };
        ys[i] = { y, i };
    }
    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());
    vector<edge> edges;
    for (int i = 0; i < n-1; i++) {
        edges.emplace_back(xs[i].second, xs[i + 1].second, xs[i + 1].first - xs[i].first);
        edges.emplace_back(ys[i].second, ys[i + 1].second, ys[i + 1].first - ys[i].first);
    }
    KruskalRunner r;
    ll sum = r.solve(n, edges);
    cout << sum << endl;
    return 0;
}

