struct UnionFind {
  vec<int> data;
  UnionFind() {}
  UnionFind(int size) : data(size, -1) {}
  bool unite(int x, int y) {
    x = root(x);
    y = root(y);

    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y];
      data[y] = x;
    }
    return x != y;
  }

  bool same(int x, int y) {
    return root(x) == root(y);
  }

  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }

  int size(int x) {
    return -data[root(x)];
  }
};

struct edge {
  int u, v, cost;
  edge(int u, int v, int cost) : u(u), v(v), cost(cost) {}
  bool operator<(const edge& rhs) const {
    return cost < rhs.cost;
  }
};

struct State {
  int x, y, num;
  State(int x, int y, int num) : x(x), y(y), num(num) {}
};

vec<edge> g;
int n;
vec<State> v;

int kruskal() {
  sort(all(g));
  UnionFind uni(g.size());
  int res = 0;
  each(e, g) {
    if (!uni.same(e.u, e.v)) {
      uni.unite(e.u, e.v);
      res += e.cost;
    }
  }

  return res;
}

