struct edge {
  int u, v, cost;
};

struct Point{
    int p, n;
    bool operator< (const Point &obj) const{
        if(this->p > obj.p) return true;
        else return false;
    }
};

int par[MAX_N];  // 親
int depth[MAX_N]; // 木の深さ

// n要素で初期化
void init(int n) {
  for (int i = 0; i < n; i++) {
    par[i] = i;
    depth[i] = 0;
  }
}

// 木の根を求める
int find(int x) {
  if (par[x] == x) {
    return x;
  } else {
    return par[x] = find(par[x]);
  }
}

// xとyの属する集合を併合
void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if (x == y)
    return;

  if (depth[x] < depth[y]) {
    par[x] = y;
  } else {
    par[y] = x;
    if (depth[x] == depth[y])
      depth[x]++;
  }
}

// xとyが同じ集合に属するか否か
bool same(int x, int y) { return find(x) == find(y); }

bool comp(const edge &e1, const edge &e2) { return e1.cost < e2.cost; }

edge es[MAX_E];
int V, E; // 頂点数と辺数

int kruskal() {
  sort(es, es + E, comp); // edge.costが小さい順にソートする
  init(V);                     // Union-Findの初期化
  int res = 0;
  for (int i = 0; i < E; i++) {
    edge e = es[i];
    if (!same(e.u, e.v)) {
      unite(e.u, e.v);
      res += e.cost;
    }
  }
  return res;
}

priority_queue<Point> x, y;

int main(){
    cin >> V;
    E = 0;
    for(int i=0;i<V;++i){
        int a, b;
        cin >> a >> b;
        x.push((Point){a,i});
        y.push((Point){b,i});
    }
    while(!x.empty()){
        Point p = x.top(); x.pop();
        es[E] = (edge){p.n, x.top().n, x.top().p - p.p};
        E++;
    }
    while(!y.empty()){
        Point p = y.top(); y.pop();
        es[E] = (edge){p.n, y.top().n, y.top().p - p.p};
        E++;
    }
    cout << kruskal() << endl;

    return 0;
}

