struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};


struct edge{
    ll v;
    ll u;
};

bool operator< (const edge &edge1, const edge &edge2){
    return edge1.v < edge2.u;
};

int main(){
    ll N; cin >> N;
    priority_queue<pair<ll, edge>, vector<pair<ll, edge>>, greater<pair<ll, edge>>> Q;
    UnionFind tree(N);
    vector<pair<ll, ll>> X(N), Y(N);

    for(int i = 0; i < N; i++){
        ll x, y; cin >> x >> y;
        X[i] = {x, i}, Y[i] = {y, i};
    }
    sort(X.begin(), X.end());
    sort(Y.begin(), Y.end());
    for(int i = 0; i < N-1; i++){
        ll d = X[i+1].first - X[i].first;
        ll v = X[i].second, u = X[i+1].second;
        edge e; e.u=u, e.v=v;
        Q.push({d, e});
    }

    for(int i = 0; i < N-1; i++){
        ll d = Y[i+1].first - Y[i].first;
        ll v = Y[i].second, u = Y[i+1].second;
        edge e; e.u=u, e.v=v;
        Q.push({d, e});
    }


    ll ans = 0;
    while(!Q.empty()){
        auto p = Q.top();
        Q.pop();
        ll d = p.first;
        ll v = p.second.v, u = p.second.u;
        if(tree.root(v) != tree.root(u)){
            ans += d;
            tree.unite(v, u);
        }
    }
    cout << ans << endl;




}

