struct UnionFind {
  vector<ll> data;
  UnionFind(ll size) : data(size, -1) { }
  bool unionSet(ll x, ll y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(ll x, ll y) {
    return root(x) == root(y);
  }
  ll root(ll x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  ll size(ll x) {
    return -data[root(x)];
  }
};

vi cum(vi V) {
  vi U(SZ(V));
  partial_sum(ALL(V), begin(U));
  return U;
}

void solve() {
  ll n;
  ll ans = 0;

  cin >> n;
  auto uf = UnionFind(n);
  vector<pair<ll, ll>> v(n), xi(n), yi(n);
  vector<tuple<ll, ll, ll>> e;
  REP(i, n) {
    ll x, y;
    cin >> x >> y;
    v[i] = mp(x, y);
    xi[i] = mp(x, i);
    yi[i] = mp(y, i);
  }
  SORT(xi);
  SORT(yi);
  REP(i, n - 1) {
    e.pb(make_tuple(xi[i + 1].first - xi[i].first, xi[i + 1].second, xi[i].second));
    e.pb(make_tuple(yi[i + 1].first - yi[i].first, yi[i + 1].second, yi[i].second));
  }
  SORT(e);
  EACH(i, e) {
    if (uf.findSet(get<1>(i), get<2>(i))) continue;
    ans += get<0>(i);
    uf.unionSet(get<1>(i), get<2>(i));
  }

  cout << ans << endl;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  cout << fixed << setprecision(15);
  solve();
}

