    //入力
    cin >> n ;
    rep(i,n){
        cin>>xy[i].first>>xy[i].second;
        a[i]=i;
        b[i]=i;
    }
    //処理
    uftree tree(n);
    priority_queue<ppint,vector<ppint>,greater<ppint>> que;
    sort(a,a+n,[](int i,int j)->bool{return xy[i].first<xy[j].first;});
    sort(b,b+n,[](int i,int j)->bool{return xy[i].second<xy[j].second;});
    rep(i,n-1){
        que.push({xy[a[i+1]].first-xy[a[i]].first,{a[i+1],a[i]}});
        que.push({xy[b[i+1]].second-xy[b[i]].second,{b[i+1],b[i]}});
    }
    int count=0;
    ll res=0;
    while(count<n-1){
        ppint now=que.top();que.pop();
        if(tree.same(now.second.first,now.second.second))continue;
        tree.merge(now.second.first,now.second.second);
        count++;
        res=res+now.first;
    }
