struct UnionFind {
    vector<int> par;

    UnionFind(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

int main(void){
    int N; cin >> N;
    vector<pair<ll, int>> xi(N);
    vector<pair<ll, int>> yi(N);
    vector<pair<ll, pair<int, int>>> edge(N*2-2);
    rep(i, N){
        cin >> xi[i].first >> yi[i].first;
        xi[i].second = i; yi[i].second = i;
    }
    sort(xi.begin(), xi.end());
    sort(yi.begin(), yi.end());
    rep(i, N-1){
        edge[i] = make_pair(xi[i+1].first - xi[i].first, make_pair(xi[i].second, xi[i+1].second));
    }
    rep(i, N-1){
        //edge[i+(N-1)]
        edge[i+(N-1)] = make_pair(yi[i+1].first - yi[i].first, make_pair(yi[i].second, yi[i+1].second));
    }
    sort(edge.begin(), edge.end());

    ll ans = 0;
    UnionFind uf(N);
    rep(i, edge.size()){
        ll c = edge[i].first;
        int from = edge[i].second.first;
        int to = edge[i].second.second;
        if(!uf.issame(from, to)){
            uf.merge(from, to);
            ans += c;
        }
    }
    cout << ans << endl;
    return 0;
}

