    for (int i = 0; i < edges.size() && uf.size(first) < N; i++) {
        int c, x, y;
        tie(c, x, y) = edges[i];
        if (uf.findSet(x, y)) continue;
        uf.unionSet(x, y);
        cost += c;
    }
    cout << cost << endl;
    return 0;
}

