int father[maxn], rank_[maxn], sz[maxn];

void init() {
    for (int i = 1; i <= n; i++) {
        father[i] = i;
        rank_[i] = 0;
        sz[i] = 0;
    }
}

int find(int x) {
    return father[x] == x ? x : father[x] = find(father[x]);
}

void merge(int a, int b) {
    a = find(a);
    b = find(b);
    if (a != b) {
        if (rank_[a] > rank_[b]) {
            father[b] = a;
            sz[a] += sz[b];
            sz[b] = 0;
        }
        else {
            father[a] = b;
            sz[b] += sz[a];
            sz[a] = 0;
            if (rank_[a] == rank_[b]) rank_[b]++;
       }
    }
}

