#include <iostream>
#include <vector>
using namespace std;

int *par, *ranks;
int N;
struct P {int n, x, y;};
struct PATH {int v1, v2, cost;};

void init()
{
  for (int i = 0; i < N; i++) {
    par[i] = i;
    ranks[i] = 0;
  }
}

int find(int x)
{
  if (par[x] == x) return x;
  return par[x] = find(par[x]);
}

void unite(int x, int y)
{
  x = find(x); y = find(y);
  if (x == y) return;

  if (ranks[x] < ranks[y]) par[x] = par[y];
  else {
    par[y] = par[x];
    if (ranks[x] == ranks[y]) ranks[x]++;
  }
}

bool same(int x, int y)
{
  return find(x) == find(y);
}

bool comp_x(P p1, P p2)
{
  return p1.x < p2.x;
}
bool comp_y(P p1, P p2)
{
  return p1.y < p2.y;
}

bool comp_cost(PATH path1, PATH path2)
{
  return path1.cost < path2.cost;
}

int main()
{
  cin >> N;
  P p[N];
  par = new int[N];
  ranks = new int[N];
  for (int i = 0; i < N; i++) {
    p[i].n = i;
    cin >> p[i].x >> p[i].y;
  }
  init();
  vector<PATH> pathes;
  sort(p, p + N, comp_x);
  for (int i = 0; i < N-1; i++) {
    PATH tmp;
    tmp.v1 = p[i].n; tmp.v2 = p[i+1].n;
    tmp.cost = p[i+1].x - p[i].x;
    pathes.push_back(tmp);
  }
  sort(p, p + N, comp_y);
  for (int i = 0; i < N-1; i++) {
    PATH tmp;
    tmp.v1 = p[i].n; tmp.v2 = p[i+1].n;
    tmp.cost = p[i+1].y - p[i].y;
    pathes.push_back(tmp);
  }

  sort(pathes.begin(), pathes.end(), comp_cost);
  int lim = pathes.size(), ans = 0;
  for (int i = 0; i < lim; i++) {
    PATH path = pathes[i];
    if (same(path.v1, path.v2)) continue;
    unite(path.v1, path.v2);
    ans += path.cost;
  }

  cout << ans << endl;
  delete [] par;
  delete [] ranks;
}

