using Weight = ll;
class Edge {
public:
	int s, d;
	Weight w;
	Edge() : s(0), d(0), w(0) {}
	Edge(int s, int d, Weight w) : s(s), d(d), w(w) {}
	bool operator < (const Edge &e) const {
		return w != e.w ? w < e.w :
			   s != e.s ? s < e.s :
			   d < e.d;
	}
};
using Graph = vector<vector<Edge>>;

// 最小全域木とそのコストを返す O(ElogE)
pair<Weight, Graph> prim(Graph& g) {
	vector<int> visited(g.size());
	Weight cost = 0;
	Graph f(g.size());
	priority_queue<Edge> que;
	que.push(Edge(-1, 0, 0));
	while (!que.empty()) {
		Edge now = que.top();
		now.w *= -1;
		que.pop();
		if (visited[now.d])
			continue;
		visited[now.d] = true;
		cost += now.w;
		if(now.s >= 0)
			f[now.s].push_back(now);
		for (auto&& e : g[now.d]) {
			if (!visited[e.d])
				que.push(Edge(e.s, e.d, -e.w));
		}
	}
	return make_pair(cost, f);
}

