    vx.PB(MP(x, i));
    vy.PB(MP(y, i));
  }
  sort(vx.begin(), vx.end());
  sort(vy.begin(), vy.end());

  vector<pair<int, pair<int, int>>> edge;
  for (int i = 0; i < N - 1; i++) {
    int v1, v2, cost;

    v1 = vx[i].SE;
    v2 = vx[i + 1].SE;
    cost = vx[i + 1].FI - vx[i].FI;
