    v1 = vy[i].SE;
    v2 = vy[i + 1].SE;
    cost = vy[i + 1].FI - vy[i].FI;
    edge.PB(MP(cost, MP(v1, v2)));

  }
  sort(edge.begin(), edge.end());

  UnionFind uf;
  uf.init(N);
  int ans = 0;
  for (auto e : edge) {
    int v1 = e.SE.FI;
    int v2 = e.SE.SE;
    int cost = e.FI;
    if (! uf.same(v1, v2)) {
