    vector<vector<P>> connect(N, vector<P>(0));
    for(ll i=0;i<N-1;i++){
        connect[xsort[i].second].emplace_back(P(xsort[i+1].first-xsort[i].first,xsort[i+1].second));
        connect[xsort[i+1].second].emplace_back(P(xsort[i+1].first-xsort[i].first,xsort[i].second));
        connect[ysort[i].second].emplace_back(P(ysort[i+1].first-ysort[i].first,ysort[i+1].second));
        connect[ysort[i+1].second].emplace_back(P(ysort[i+1].first-ysort[i].first,ysort[i].second));
    ;}
    priority_queue<P, vector<P>, greater<P>> pq;
    UnionFind tree(N);
    for(ll i=0;i<connect[0].size();i++){
