class DisjointSetUnion {
public:
    explicit DisjointSetUnion(uint32_t pointsCount);
    uint32_t find(uint32_t point);
    bool merge(uint32_t left, uint32_t right);
    uint32_t addPoint();
    uint32_t components() { return components_; }
private:
    std::vector<uint32_t> roots_;
    std::vector<uint32_t> size_;
    // use same stack for all calls of find method
    std::stack<uint32_t> nodes_;
    uint32_t components_;
};

DisjointSetUnion::DisjointSetUnion(uint32_t pointsCount) {
    roots_.resize(pointsCount);
    size_.assign(pointsCount, 1);
    components_ = pointsCount;
    for (uint32_t element = 0; element < pointsCount; ++element) {
        roots_[element] = element;
    }
}

uint32_t DisjointSetUnion::find(uint32_t point) {
    auto current = point;
    while (roots_[current] != current) {
        nodes_.push(current);
        current = roots_[current];
    }
    while (!nodes_.empty()) {
        roots_[nodes_.top()] = current;
        nodes_.pop();
    }
    return current;
}

bool DisjointSetUnion::merge(uint32_t left, uint32_t right) {
    left = find(left);
    right = find(right);
    if (left == right) {
        return false;
    }
    if (size_[left] < size_[right]) {
        std::swap(left, right);
    }
    roots_[right] = left;
    --components_;
    size_[left] += size_[right];
    return true;

}

uint32_t DisjointSetUnion::addPoint() {
    roots_.push_back(roots_.size());
    size_.push_back(1);
    ++components_;
    return roots_.size();
}

