ll prim(){
	priority_queue<T,vector<T>, greater<T> > que;
	fill(mincost,mincost+V,inf);
	mincost[0]=0;
	ll res=0;
	que.push(T(0,0));

	while(!que.empty()){
		T t = que.top();
		que.pop();
		int v=t.second;
		if(mincost[v]<t.first){ 
			continue;
		}
		for(int i=0;i<G[v].size();i++){
			edge e = G[v][i];
			if(mincost[e.to]>mincost[v]+e.cost){
				mincost[e.to]=mincost[v]+e.cost;
				res+=e.cost;
				que.push(T(mincost[e.to],e.to));
			}
		}
	}
	return res;
}


