    diff_x[i].first = x[i+1].first - x[i].first;
    diff_y[i].first = y[i+1].first - y[i].first;
    diff_x[i].second = pii(x[i].second, x[i+1].second);
    diff_y[i].second = pii(y[i].second, y[i+1].second);
