//unionFind
class unionFind {
private:
	int* p;   //親配列のポインタ
	int* rank;
	int N;   //要素数
	int* check;   //同値な要素の数
public:
	unionFind(int);   //コンストラクタ
	int parent(int);   //親要素を返す
	void unit(int, int);   //2要素をつなぐ
	int operator[](int);   //parentの省略形
	~unionFind();
	int size(int n);   //頂点nと同値な要素数を返す
};

unionFind::unionFind(int n) {
	N = n;
	p = new int[N];
	rank = new int[N];
	for (int i = 0; i < N; i++) {
		p[i] = i;
		rank[i] = 0;
	}
	check = new int[N];
	for (int n = 0; n < N; n++)check[n] = 1;
	return;
}

int unionFind::parent(int n) {
	if (n < 0 || n >= N)return -1;
	if (p[n] == n)return n;   //自分が一番上の親
	return p[n] = parent(p[n]);   //つなぎ直しと上にたどる操作
}

int unionFind::operator[](int n) {
	return parent(n);
}

void unionFind::unit(int x, int y) {
	x = parent(x), y = parent(y);
	if (x == y)return;   //根が同じだから何もせずに帰る
	int sum = check[x] + check[y];
	if (rank[x] < rank[y])p[x] = y;
	else {
		p[y] = x;
		if (rank[x] == rank[y])rank[x]++;
	}
	check[x] = sum;
	check[y] = sum;
	return;
}

unionFind::~unionFind() {
	delete(p);
	delete(rank);
	delete(check);
	return;
}

int unionFind::size(int n) {
	return check[parent(n)];
}

template<class Type>
Type MinSpanTree(WeightedGraph<Type>& G, WeightedGraph<Type>& G2) {
	int N = G.size();
	G2.resize(N);
	unionFind UF(N);
	Gedges<Type> edges;
	for (int n = 0; n < N; n++) {
		for (Gedge<Type>& e : G[n]) {
			edges.push_back(e);
		}
	}
	sort(edges.begin(), edges.end(), [](Gedge<Type>& a, Gedge<Type>& b) {
		return a.cost < b.cost;
	});
	Type ans = 0;
	for (Gedge<Type>& e : edges) {
		int from = e.src;
		int to = e.to;
		if (UF[from] == UF[to])continue;
		ans += e.cost;
		G2[from].push_back({ from,to,e.cost,e.id });
		G2[to].push_back({ to,from,e.cost,e.id });
		UF.unit(from, to);
	}
	return ans;
}

