const int INF = 1001001001;

int main(){
    int N;
    cin >> N;
    vector<P> x(N), y(N);

    for(int i = 0; i < N; ++i){
        int temp;
        cin >> temp;
        x[i] = P(temp, i);
        cin >> temp;
        y[i] = P(temp, i);
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    vector<vector<P>> graph(N);     // (cost, to)
    for(int i = 0; i < N - 1; ++i){
        P p1 = x[i];
        P p2 = x[i + 1];
        int temp = p2.first - p1.first;
        graph[p1.second].push_back(P(temp, p2.second));
        graph[p2.second].push_back(P(temp, p1.second));

        p1 = y[i];
        p2 = y[i + 1];
        temp = p2.first - p1.first;
        graph[p1.second].push_back(P(temp, p2.second));
        graph[p2.second].push_back(P(temp, p1.second));
    }

    ll res = 0;
    vector<int> mincost(N, INF);
    vector<bool> used(N, false);
    priority_queue<P, vector<P>, greater<P>> que;
    que.push(P(0, 0));          // (現在の部分最小全域木からのcost, coord)
    mincost[0] = 0;

    while(!que.empty()){
        P p = que.top();
        que.pop();

        if(used[p.second])      continue;

        used[p.second] = true;
        if(mincost[p.second] == p.first)       res += p.first;

        for(int i = 0; i < graph[p.second].size(); ++i){
            P t = graph[p.second][i];
            mincost[t.second] = min(mincost[t.second], t.first);
            que.push(P(t.first, t.second));
        }
    }

    cout << res << endl;
}

