// Union-Find木(素集合データ構造) - グループ分けを木構造で管理する。任意の２要素が同じグループに所属するか判定する
struct UnionFind
{
  // 親ノードのインデックス
  vector<int> parent;

  UnionFind(int size)
  {
    parent.resize(size);
    rep(i, size){ parent[i] = i; } // 初期状態は自ノードが親ノード(＝すべてのノードが独立)
  }

  // 木の根(root)を取得する
  int root(int x)
  {
    // 要素xが根の場合
    if(parent[x] == x)
      return x;

    // 経路圧縮
    parent[x] = root(parent[x]);

    return parent[x];
  }

  // 同じグループかどうか判定する
  bool same(int x, int y)
  {
    return root(x) == root(y);
  }

  // ２つのグループを併合する
  void unite(int x, int y)
  {
    x = root(x);
    y = root(y);
    if(x != y)
      parent[x] = y;
  }
};


