        p[0].pb({i, x});
        p[1].pb({i, y});
    }

    V<VPL> path(N);

    REP(k, 2) {
        sort(ALL(p[k]), secondSort);

        REP(i, N - 1) {
            ll x1 = p[k][i].fst;
            ll x2 = p[k][i + 1].fst;
            ll cost = p[k][i + 1].snd - p[k][i].snd;
            path[x1].pb({x2, cost});
            path[x2].pb({x1, cost});
        }
    }

    ll ans = 0;

    VB visited(N, false);
    ll v = 0;
    visited[v] = true;
    VPL edge;

    REP(i, N - 1) {
        for (auto p : path[v]) {
            if (!visited[p.fst]) {
                edge.pb(p);
            }
        }

        sort(ALL(edge), secondSort);

        while (!edge.empty()) {
            auto p = edge.front();
            edge.erase(edge.begin());

            if (!visited[p.fst]) {
                ans += p.snd;
                visited[p.fst] = true;
                v = p.fst;
                break;
            }
        }
    }

