            debugline("undigraph add");
            deb(f, t, c,  ty,id);
            ole();
        }
        if (id == -1)id = eid, eid += 2;
        g[f].emplace_back(f, t, c, ty, id);
        g[t].emplace_back(t, f, c, ty, id + 1);
        edges.emplace_back(f, t, c, ty, id);
        edges.emplace_back(t, f, c, ty, id + 1);
    }
