struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};


int main(){
  int n;
  cin >> n;
  vector<pair<int,int>> vh(n),vv(n);
  for(int i=0;i<n;i++){
    cin >> vh[i].first;
  	cin >> vv[i].first;
    vh[i].second = i;
    vv[i].second = i;
  }
  sort(vh.begin(),vh.end());
  sort(vv.begin(),vv.end());
  priority_queue<pair<int,pair<int,int>>, vector<pair<int,pair<int,int>>>, std::greater<pair<int,pair<int,int>>> > q;
  for(int i=0;i<n-1;i++){
    int costh,costv;
    costh = vh[i+1].first-vh[i].first;
    costv = vv[i+1].first-vv[i].first;
    q.push(make_pair(costh, make_pair(vh[i].second,vh[i+1].second)));
    q.push(make_pair(costv, make_pair(vv[i].second,vv[i+1].second)));
  }

  struct UnionFind uf(n);
  long long int ans = 0;
  while(uf.size(0)!=n){
  	int cost = q.top().first, r = q.top().second.first, l = q.top().second.second;
    q.pop();
    if(uf.findSet(r,l)) continue;
    else{
      ans += cost;
      uf.unionSet(r,l);
    }
  }
  cout << ans << endl;
  return 0;
}

