        point_f[i] = {{x, y}, i};
        point_s[i] = {{y, x}, i};
    }
    sort(point_f.begin(), point_f.end());
    sort(point_s.begin(), point_s.end());
    for(int i = 1; i < N; i++) {
        int a = point_f[i-1].second;
        int b = point_f[i].second;
        edge[a].push_back({point_f[i].first.first - point_f[i-1].first.first, b});
        edge[b].push_back({point_f[i].first.first - point_f[i-1].first.first, a});

        int c = point_s[i-1].second;
        int d = point_s[i].second;
        edge[c].push_back({point_s[i].first.first - point_s[i-1].first.first, d});
        edge[d].push_back({point_s[i].first.first - point_s[i-1].first.first, c});
    }

    ll ans = 0;
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> q;
    for (pair<int, int> p : edge[0]) {
