template<class E>
inline long long kruscal(edgeset<E> &graph){
	int e=graph.esize();
	E *t=new E[e];
	for(int i=0;i<e;++i) t[i]=graph[i];
	std::sort(t,t+e,[](E &x,E &y){return x.wgt<y.wgt;});
	unionfind s(graph.vsize());
	long long ret=0LL;
	for(int i=0;i<e;++i){
		if(!s.same(t[i].start,t[i].end)){
			ret+=t[i].wgt;
			s.unite(t[i].start,t[i].end);
		}
		if(s.group()==1) break;
	}
	delete[] t;
	s.close();
	return ret;
}

