inline void unionfind::close(void){
	siz=grp=0;
	delete[] par;
	par=nullptr;
}
inline void unionfind::unite(int ndx,int ndy){
	ndx=find(ndx);
	ndy=find(ndy);
	if(ndx==ndy) return;
	if(par[ndx]>par[ndy]){
		par[ndy]+=par[ndx];
		par[ndx]=ndy;
	}
	else{
		par[ndx]+=par[ndy];
		par[ndy]=ndx;
	}
	--grp;
	return;
}
inline int unionfind::same(int ndx,int ndy){
	return find(ndx)==find(ndy)?1:0;
}
inline int unionfind::size(int nd){
	return -par[find(nd)];
}
inline int unionfind::group(void){
	return grp;
}
inline int unionfind::find(int nd){
	if(par[nd]<0) return nd;
	return par[nd]=find(par[nd]);
}
