    return find(x) == find(y);
}

void unite(long long x, long long y){
    long long xx = find(x);
    long long yy = find(y);

    if(mdep[xx] < mdep[yy]){
        msk[xx] = yy;
    }
    else{
        msk[yy] = xx;
        if(mdep[xx] == mdep[yy]){
            mdep[xx]++;
        }
    }
}

