pair<graph,ll> prim(graph gg){//mstを求める. 0-indexed,連結を前提
    vector<bool> ck(gg.size(),false);
    ll lgt=0;//length
    graph mst(gg.size());//mst
    ll ct = 0;
    ck[0] = true; ct++;
    priority_queue< pair<edge,ll> , vector<pair<edge,ll>>, greater<pair<edge,ll>>> q;
    rep(i,gg[0].size()){
        q.push(mp(gg[0][i],0));
    }
    while(ct!=gg.size()){
        edge id = q.top().first;
        ll from = q.top().second;
        q.pop();
        if(ck[id.to])continue;
        ck[id.to] = true;
        mst[from].pb(id);
        lgt += id.cost;
        ct++;
        rep(i,gg[id.to].size()){
            q.push(mp(gg[id.to][i],id.to));
        }
    }
    //return lgt;//mst's length
    return mp(mst,lgt);
}

