class UnionFind
{
public:
	int p[N];
	void init(int n = N)
	{
		memset(p, -1, sizeof(int) * n);
	}
	int treesize(int x)
	{
		return -p[Find(x)];
	}
	int Find(int x)
	{
		int s = x;
		while (p[s] >= 0) s = p[s];
		while (x != s)
		{
			int t = p[x];
			p[x] = s;
			x = t;
		}
		return s;
	}
	void Union(int x, int y)
	{
		int px = Find(x);
		int py = Find(y);
		if (p[px] > p[py]) swap(px, py);
		p[px] += p[py];
		p[py] = px;
	}
} uf;
vector<tuple<int, int, int>> vt;
void solve(vector<pair<int, int>>& vp)
{
	sort(vp.begin(), vp.end());
	for (int i = 0; i + 1 < vp.size(); i++)
	{
		vt.emplace_back(vp[i + 1].first - vp[i].first, vp[i].second, vp[i + 1].second);
	}
}
