}edge[M];
void addEdge(ll u, ll v, ll w) {
    edge[cnt].u = u;
    edge[cnt].v = v;
    edge[cnt].w = w;
    cnt++;
}
bool cmp(Edge a, Edge b) {
    return a.w < b.w;
}
ll find(ll x) {
    return p[x] == x ? x : p[x] = find(p[x]);
}
ll Kruskal() {
    ll ans = 0, sum = 0, u, v, w;
    for(ll i = 0; i <= n; i++)
        p[i] = i;
    sort(edge, edge + cnt, cmp);
    for(int i = 0; i < cnt; i++) {
    	u = edge[i].u, v = edge[i].v, w = edge[i].w;
        ll fa = find(u), fb = find(v);
        if(fa != fb) {
            ans += w;
            p[fa] = fb;
            sum++;
        }
        if(sum == n-1) break;
    }
    if(sum < n-1) return -1;
    return ans;
}

