struct UnionFind {
  vi32 par;
  vi32 siz;
  UnionFind(int n) {
    par = vi32(n);
    siz = vi32(n, 1);
    iota(all(par), 0);
  }
  int root(int x) {
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }
  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;
    par[x] = y;
    siz[y] += siz[x];
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int size(int x) {
    return siz[root(x)];
  }
};

void solve() {
  int N; cin >> N;
  vi32 x(N), y(N);
  rep(i, N) cin >> x[i] >> y[i];

  pqasc<tuple<int, int, int>> pq;

  vi32 o(N);
  iota(all(o), 0);
  sort(all(o), [&](int i, int j) { return x[i] < x[j]; });
  rep(i, N - 1) {
    int c = abs(x[o[i + 1]] - x[o[i]]);
    pq.emplace(c, o[i], o[i + 1]);
  }
  sort(all(o), [&](int i, int j) { return y[i] < y[j]; });
  rep(i, N - 1) {
    int c = abs(y[o[i + 1]] - y[o[i]]);
    pq.emplace(c, o[i], o[i + 1]);
  }

  i64 ans = 0;

  auto uf = UnionFind(N);
  while (true) {
    int c, v, u;
    tie(c, v, u) = pq.top(), pq.pop();
    if (uf.same(v, u)) continue;
    uf.unite(v, u);
    ans += c;
    if (uf.size(v) == N) break;
  }

  cout << ans << '\n';
}

