        tot += dist(i,parent[i]);
    return tot;
}


void primMST(int n)
{
     int parent[n];
     int key[n];
     bool mstSet[n];

     for (int i = 0; i < n; i++)
        key[i] = INT_MAX, mstSet[i] = false;

     key[0] = 0;
     parent[0] = -1;

     for (int count = 0; count < n-1; count++)
     {
        int u = minKey(key, mstSet, n);

        mstSet[u] = true;

        for (int v = 0; v < n; v++)
          if (mstSet[v] == false && dist(u,v) <  key[v])
             parent[v]  = u, key[v] = dist(u,v);
     }
