    edge(): u(0), v(0), cost(0) {};
    edge(ll u_, ll v_): u(u_), v(v_) {
        cost = min(abs(vs[u].se.fi - vs[v].se.fi), abs(vs[u].se.se - vs[v].se.se));
        //cout << "[" << u << ", " << v << "] " << cost << endl;
    };
};
edge es[100010];
bool comp(const edge &lhs, const edge &rhs)
{
