bool xcomp(const LLP &lhs, const LLP &rhs)
{
    return lhs.se.fi < rhs.se.fi;
}

bool ycomp(const LLP &lhs, const LLP &rhs)
{
    return lhs.se.se < rhs.se.se;
}

ll kruskal()
{
    sort(es, es+E, comp);
    UnionFind uf(V);
    ll ret = 0;
    REP(i, E){
        edge e = es[i];
        //cout << "(" << e.cost << ")" << endl;
        if(!uf.isSame(e.u, e.v)){
            uf.unite(e.u, e.v);
            //cout << e.cost << endl;
            ret += e.cost;
        }
    }
    return ret;
}

