const int MAX = 100005;

struct edge { int from; int to; int cost; };

class unionfind {
private:
	int par[MAX]; int rank[MAX];
public:
	unionfind(int n) {
		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
		}
	}
	int find(int x) {
		if (par[x] == x) {
			return x;
		}
		else {
			return par[x] = find(par[x]);
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	void unite(int x, int y) {
		if (!same(x, y)) {
			x = par[x]; y = par[y];
			if (rank[x] < rank[y]) {
				par[x] = y;
			}
			else {
				par[y] = x;
				if (rank[x] == rank[y]) {
					rank[x]++;
				}
			}
		}
	}
};

bool compare(edge a, edge b) {
	return a.cost < b.cost;
}

struct city { int x; int y; int num; };

bool x_bigger(city a,city b){
	return a.x < b.x;
}
bool y_bigger(city a, city b) {
	return a.y < b.y;
}

city c[MAX];
edge g[MAX*2];
unionfind t(MAX);

int main() {
	int n;
	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> c[i].x >> c[i].y;
		c[i].num = i;
	}
