	int ans = 0;
	/* int v, e;
	cin >> v >> e;
	for (int i = 0; i < e; i++) {
		cin >> g[i].from >> g[i].to >> g[i].cost;
	}*/
	sort(c, c + n, x_bigger);
	for (int i = 0; i < n - 1; i++) {
		g[i].from = c[i].num;
		g[i].to = c[i + 1].num;
		g[i].cost = c[i + 1].x - c[i].x;
	}
	sort(c, c + n, y_bigger);
	for (int i = 0; i < n - 1; i++) {
		g[i + n - 1].from = c[i].num;
		g[i + n - 1].to = c[i + 1].num;
		g[i + n - 1].cost = c[i + 1].y - c[i].y;
	}
	int e = 2 * n - 2;
	sort(g, g + e, compare);
	for (int i = 0; i < e; i++) {
		int fr, next;
		fr = g[i].from; next = g[i].to;
		if (!t.same(fr, next)) {
