struct UnionFind {
  vector<int> data;

  // 宣言するときは UnionFind(N+1); でやってください！！！
  UnionFind(int sz) {
    data.assign(sz, -1);
  }

  bool unite(int x, int y) {
    x = find(x); y = find(y); 
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return true;
  }

  bool same(int x, int y) {
    x = find(x); y = find(y); 
    return (x == y);
  }

  int find(int k) {
    if (data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  // 要素 k が属する集合の要素の数を求める
  int size(int k) {
    return -data[find(k)];
  }
};

