const int INF = 1<<30;

ll Prim(ll V, vector<vector<int>> graph) {
  ll res = 0;
  vector<bool> used(V);
  vector<ll> mincost(V);
  rep(i, V) {
    mincost[i] = INF;
  }
  mincost[0] = 0;

  while (true) {
    ll v = -1;
    rep(u, V) {
      if (!used[u] && (v == -1 || mincost[u] < mincost[v])) v = u;
    }

    if (v == -1) break;
    used[v] = true;
    res += mincost[v];

    rep(u, V) {
      mincost[u] = min(mincost[u], (ll)graph[v][u]);
    }
  }
  return res;
}

