	incd(sz,n+1);
	for(int i=0;i<=n;i++)
	dsu[i]=i,sz[i]=1;
}

int get_par(int x)
{
	if(dsu[x]==x) return x;
	return dsu[x]=get_par(dsu[x]);
}

void unite(int x,int y)
{
	int p1=get_par(x);
	int p2=get_par(y);
	if(p1!=p2)
	{
		sz[p1]+=sz[p2];
		dsu[p2]=p1;
	}
}

int MST(vector<pair<int,pii>> edges,int n)
{
	init_dsu(n+1);
	int cost=0;
	sort(all(edges));
	for(auto i:edges)
	{
		pii p=i.se;
		int x=get_par(p.f);
		int y=get_par(p.se);
		if(x!=y)
		{
			//cout<<x<<" "<<y<<" "<<i.f<<"\n";
			unite(x,y);
			cost+=i.f;
		}
	}
	return cost;
}

