struct UnionFind {
    vector<int> par, cnt;

    UnionFind(int n): par(n, -1), cnt(n) {}
    int find(int x) {
        if (par[x]<0) return x;
        return par[x] = find(par[x]);
    }
    bool same(int i, int j) {
        // iとjが同じグループかどうかを判別する
        return find(i) == find(j);
    }
    int size(int x) {
        return -par[find(x)];
    }

    bool unite(int x, int y) {
        // iとjを併合する
        x = find(x);
        y = find(y);
        bool ok = (-par[x]>cnt[x] || -par[y]>cnt[y]);
        if (x == y) {
            cnt[x]++;
        } else if (par[x] > par[y]) {
            par[y] += par[x];
            par[x] = y;
            cnt[y] += cnt[x]+1;
        } else {
            par[x] += par[y];
            par[y] = x;
            cnt[x] += cnt[y]+1;
        }
        return ok;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n; cin >> n;
    V<int> x(n), y(n);
    for (int i = 0; i < n; i++) cin >> x[i] >> y[i];

    priority_queue< P<int, P<int, int> > > pq;
    V<int> ord(n); iota(ALL(ord), 0);
    sort(ALL(ord), [&](int i, int j) {
        return x[i] < x[j];
    });
    for (int i = 1; i < n; i++) {
        pq.push(make_pair(x[ord[i - 1]] - x[ord[i]], make_pair(ord[i], ord[i - 1])));
    }
    sort(ALL(ord), [&](int i, int j) {
        return y[i] < y[j];
    });
    for (int i = 1; i < n; i++) {
        pq.push(make_pair(y[ord[i - 1]] - y[ord[i]], make_pair(ord[i], ord[i - 1])));
    }

    UnionFind uni(n);

    ll ans = 0;
    while (!pq.empty()) {
        P<int, P<int, int> > q = pq.top(); pq.pop();
        if (!uni.same(q.second.first, q.second.second)) {
            uni.unite(q.second.first, q.second.second);
            ans -= (ll)q.first;
        }
    }
    cout << ans << '\n';
    return 0;
