class UnionFind {
public:
    vector <int> par; // 各元の親を表す配列
    vector <int> siz; // 素集合のサイズを表す配列(1 で初期化)

    // Constructor
    UnionFind(int sz_): par(sz_), siz(sz_, (int)1) {
        for (int i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }
    void init(int sz_) {
        par.resize(sz_);
        siz.assign(sz_, (int)1);
        for (int i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }

    // Member Function
    // Find
    int root(int x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }

    // Union(Unite, Merge)
    bool merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        // merge technique（データ構造をマージするテク．小を大にくっつける）
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool issame(int x, int y) { // 連結判定
        return root(x) == root(y);
    }

    int size(int x) { // 素集合のサイズ
        return siz[root(x)];
    }
};

signed main(){
	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;
	pair<P, int> p[N];
	UnionFind uf(N);
	priority_queue<pair<int, P>, vector<pair<int, P>>, greater<pair<int, P>>> que;
	rep(i,N){
		cin >> p[i].first.first >> p[i].first.second;
		p[i].second = i;
	}
	sort(p, p+N);
	rep(i,N-1){
		que.push({p[i+1].first.first-p[i].first.first, P(p[i].second, p[i+1].second)});
	}
	rep(i,N){
		swap(p[i].first.first, p[i].first.second);
	}
	sort(p, p+N);
	rep(i,N-1){
		que.push({p[i+1].first.first-p[i].first.first, P(p[i].second, p[i+1].second)});
	}
	int ans = 0;
	while(!que.empty()){
		auto e = que.top();
		que.pop();
		int v = e.first;
		int x = e.second.first;
		int y = e.second.second;
		if(uf.issame(x,y)) continue;
		uf.merge(x,y);
		ans += v;
	}
	cout << ans << endl;
}

