		costV[v[vx[i + 1].first][vx[i + 1].second]].push_back(make_pair(costX, vx[i]));

		ll costY = abs(vy[i].first - vy[i + 1].first);
		//x,yに戻す
		pair<ll, ll> vyStart = make_pair(vy[i].second, vy[i].first);
		pair<ll, ll> vyEnd = make_pair(vy[i + 1].second, vy[i + 1].first);
		costV[v[vyStart.first][vyStart.second]].push_back(make_pair(costY, vyEnd));
		costV[v[vyEnd.first][vyEnd.second]].push_back(make_pair(costY, vyStart));

	}


	vector<ll> visited = vector<ll>(n, 0);
	rep(i, 0, n) {
		if (costV[i].size() == 0)visited[i] = 1;
	}
	ll ans = 0;

	priority_queue<pair<ll, pair<ll, ll>>, vector<pair<ll, pair<ll, ll>>>, greater<>> queue =
		priority_queue<pair<ll, pair<ll, ll>>, vector<pair<ll, pair<ll, ll>>>, greater<>>();


	rep(i, 0, n) {
		if (costV[i].size() > 0) {
			for (auto& edge : costV[i]) {
				queue.push(edge);
			}
			visited[i] = 1;
		}
		break;
	}

	while (queue.size() > 0) {
		pair<ll, pair<ll, ll>> edge = queue.top();
		queue.pop();
		ll vIndex = v[edge.second.first][edge.second.second];
		if (visited[vIndex] == 1) continue;
		else {
			visited[vIndex] = 1;
			for (auto& e : costV[vIndex]) {
				queue.push(e);
			}
			ans += edge.first;
		}
	}

	cout << ans << endl;

}

