template <class NumberType>
class Kruskal{
private:
    struct UnionFindTree{
    private:
        int m;
        std::vector<int> Parent;
        std::vector<int> SetSize;
    public:
        UnionFindTree(int mm = 0){
            m = mm;
            SetSize.resize(m, 0); Parent.resize(m);
            for(int v = 0; v < m; ++v) Parent[v] = v;
        }
        void resize(int mm){
            m = mm;
            SetSize.resize(m, 0); Parent.resize(m);
            for(int v = 0; v < m; ++v) Parent[v] = v;
        }
        int rootOf(int v){
            if(Parent[v] == v) return v;
            Parent[v] = rootOf(Parent[v]);
            return Parent[v];
        }
        // 頂点 x, y を併合する
        void unite(int x, int y){
            int root_x = rootOf(x);
            int root_y = rootOf(y);
            // 異なる集合に属する場合
            if(root_x == root_y) return;
            if(SetSize[root_x] < SetSize[root_y]) std::swap(root_x, root_y);
            Parent[root_y] = root_x;
            SetSize[root_x] += SetSize[root_y];
        }
        // 頂点 x, y が 同じ集合に属しているかを判定する
        bool sameSet(int x, int y){
            return rootOf(x) == rootOf(y);
        }
        // 頂点 x の属する集合の要素数
        int sizeOf(int x){
            return SetSize[rootOf(x)];
        }
    };
    using node = std::tuple<NumberType, int, int>;
    // コスト, 頂点1 頂点2

    const int n;
    std::vector<node> Node;
    UnionFindTree UFT;
public:
    std::vector<std::vector<std::pair<int, NumberType>>> TheTree;
    long long int ans;

    Kruskal(int nn): n(nn){
        UFT.resize(n); Node.resize(0); 
        TheTree.resize(n, std::vector<std::pair<int, NumberType>>(0));
    }
    void add(int a, int b, NumberType cost){
        Node.push_back({cost, a, b});
    }
    long long int compute(){
        ans = 0;
        std::sort(Node.begin(), Node.end(), std::greater<node>());
        while(not Node.empty()){
            int a, b; NumberType cost;
            std::tie(cost, a, b) = Node.back(); Node.pop_back();

            if(UFT.sameSet(a, b)) continue;

            UFT.unite(a, b);
            ans += cost;
            TheTree[a].push_back({b, cost});
            TheTree[b].push_back({a, cost});
        }
        return ans;
    }
};



