  }

  sort(s.begin(), s.end());

  for(ll i = 0; i < N; i++){
    par[i] = i;
  }

  while(!s.empty()){
    ll des = s.front()[0], fst = s.front()[1], scd = s.front()[2]; s.pop_front();
    if(!same(fst, scd)){
      ans += des;
      unite(fst, scd);
    }
  }

  cout << ans << endl;
}

