int solve(int n)
{
    int res = 0;
    priority_queue<P, vector<P>, greater<P>> que;
    que.push(P(0, 0));
    bool used[n + 1] = {};
    while(not que.empty())
    {
        int w = que.top().first;
        int v = que.top().second;
        que.pop();
        if(used[v]) continue;
        used[v] = true;
        res += w;
        for(int u = 0; u < G[v].size(); u++)
        {
            edge e = G[v][u];
            if(not used[e.to]) que.push(P(e.cost, e.to));
        }
    }
