struct UnionFind {
    vector<int> par, rnk;
    UnionFind(int N) : par(N), rnk(N) {
        for (int i = 0; i < N; ++i)
            par[i] = i;
    }

    int root(int x) {
        return par[x] == x ? x : par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    void unite(int x, int y) {
        x = root(x), y = root(y);
        if (x == y)
            return;
        if (rnk[x] < rnk[y])
            swap(x, y);
        if (rnk[x] == rnk[y])
            rnk[x]++;
        par[y] = x;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    cin >> N;
    vector<pii> x(N), y(N);
    for (int i = 0; i < N; ++i) {
        int a, b;
        cin >> a >> b;
        x[i] = {a, i};
        y[i] = {b, i};
    }

    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    auto cmp = [&](edge a, edge b) {
        if (a.cost == b.cost)
            return a.from == b.from ? a.to < b.to : a.from < b.from;
        else
            return a.cost > b.cost;
    };
    priority_queue<edge, vector<edge>, decltype(cmp)> que(cmp);
    for (int i = 0; i < N - 1; ++i) {
        {
            int a = x[i].second, b = x[i + 1].second;
            int c = x[i + 1].first - x[i].first;
            que.push({a, b, c});
        }
        {
            int a = y[i].second, b = y[i + 1].second;
            int c = y[i + 1].first - y[i].first;
            que.push({a, b, c});
        }
    }

    ll ans = 0;
    UnionFind uf(N);
    while (!que.empty()) {
        edge e = que.top();
        que.pop();
        if (uf.issame(e.from, e.to))
            continue;
        ans += e.cost;
        uf.unite(e.from, e.to);
    }
    cout << ans << endl;

    return 0;
}

