    for (auto x : VX) fprintf(stderr, "%ld %ld %ld\n", x.first.first, x.first.second, x.second);
    */
    int c = 0;
    auto prev = VX.begin();
    for (auto x = next(prev, 1); x != VX.end(); x++) { 
        ll  cost = min(abs(get<0>(*prev) - get<0>(*x)),
                       abs(get<1>(*prev) - get<1>(*x)));
        ll  u = get<2>(*prev), v = get<2>(*x);
        E[c++] = {u, v, cost};
        prev = x;
    }

    /*
    fprintf(stderr, "-------------- VY --------------\n");
    for (auto y : VY) fprintf(stderr, "%ld %ld %ld\n", y.first.second, y.first.first, y.second);
    */
    prev = VY.begin();
    for (auto y = next(prev, 1); y != VY.end(); y++) {
        ll cost = min(abs(get<0>(*prev) - get<0>(*y)),
                      abs(get<1>(*prev) - get<1>(*y)));
        ll u = get<2>(*prev), v = get<2>(*y);
        E[c++] = {u, v, cost};
        prev = y;
    }
    /*
    fprintf(stderr, "--------------  E --------------\n");
    for (auto x : E) {
        fprintf(stderr, "%ld %ld %ld\n", x.first.first, x.first.second, x.second);
    }
    */

    // Kruskal
    sort(E, E + ((N-1)*2), comp);
    UnionFind U = UnionFind(N);
    ll res = 0;
    rep(i, (N-1) * 2) {
       Edge e = E[i];
       if (!U.issame(e.from, e.to)) {
           U.merge(e.from, e.to);
           res += e.cost;
       }
    }

    cout << res << endl;
}

