using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;

const ll mod = 1e9 + 7;

vector<vector<P>> g;

int main() {


    ll n;
    cin >> n;

    vector<pair<P, ll>> vp(n);
    vector<pair<P, ll>> vp2(n);
    for (int i = 0; i < n; ++i)
    {
        ll x, y;
        cin >> x >> y;
        vp[i] = make_pair(P(x, y), i);
        vp2[i] = make_pair(P(y, x), i);
    }

    sort(vp.begin(), vp.end());
    sort(vp2.begin(), vp2.end());

    g = vector<vector<P>>(n, vector<P>());

    for (int i = 0; i < n - 1; ++i)
    {
        ll cost1 = min(abs(vp[i].first.first - vp[i + 1].first.first), abs(vp[i].first.second - vp[i + 1].first.second));
        ll cost2 = min(abs(vp2[i].first.first - vp2[i + 1].first.first), abs(vp2[i].first.second - vp2[i + 1].first.second));
        g[vp[i].second].push_back(make_pair(vp[i + 1].second, cost1));
        g[vp[i + 1].second].push_back(make_pair(vp[i].second, cost1));
        g[vp2[i].second].push_back(make_pair(vp2[i + 1].second, cost2));
        g[vp2[i + 1].second].push_back(make_pair(vp2[i].second, cost2));
    }

    priority_queue<P, vector<P>, greater<>> q;
    q.push(P(0, 0));

    ll count = 0;
    ll ret = 0;
    vector<bool> used(n);
    while (count < n)
    {
        P cur = q.top();
        q.pop();
        if (used[cur.second])
        {
            continue;
        }
        used[cur.second] = 1;
        ret += cur.first;
        for (int i = 0; i < g[cur.second].size(); ++i)
        {
            if (!used[g[cur.second][i].first])
            {
                P next = g[cur.second][i];
                swap(next.first, next.second);
                q.push(next);
            }
        }
        count++;
    }

    cout << ret << endl;

    return 0;
}

