//        printf("add to cost[2] > %d %d\n", dwDist2, poslist[dwVectorIdx - 1].first);

        mincost.push(dist_info(dwDist1, poslist[dwVectorIdx + 1].first));
        mincost.push(dist_info(dwDist2, poslist[dwVectorIdx - 1].first));
    }
}

