    rep(i, n - 1){
        edge g;
        g.from = x[i].second;
        g.to = x[i+1].second;
        g.cost = x[i+1].first - x[i].first;
        G.push_back(g);
        g.from = y[i].second;
        g.to = y[i+1].second;
        g.cost = y[i+1].first - y[i].first;
