    // rep(i, 2 * (n - 1)) cout << G[i].cost << " ";
    // cout << endl;
    init(n);
    long int count = 0;
    long int ans = 0;
    for (int i = 0; count < n - 1; i++){
        long int e1 = G[i].from;
        long int e2 = G[i].to;
        if (same(e1, e2)){
            continue;
        }
        unite(e1, e2);
        ans += G[i].cost;
        count++;
    }
    cout << ans << endl;
}

