    vector<edge> es;

    sort(num.begin(), num.end(), [&](int i, int j) {return x[i] < x[j];});
    for (int i = 0; i < n - 1; i++) es.push_back({num[i], num[i+1], x[num[i+1]]-x[num[i]]});
    sort(num.begin(), num.end(), [&](int i, int j) {return y[i] < y[j];});
    for (int i = 0; i < n - 1; i++) es.push_back({num[i], num[i+1], y[num[i+1]]-y[num[i]]});

    sort(es.begin(), es.end());
    UnionFind uf(n);
    ll ans = 0;
    for (auto &e: es) {
        if (!uf.same(e.u, e.v)) {
            uf.unite(e.u, e.v);
            ans += e.w;
        }
    }
    cout << ans << endl;
    return 0;
}

