class UF
{
	vector<int> par;
public:
	UF(int n) {
		par.resize(n);
		for (int i = 0; i < n; ++i) par[i] = i;	//頂点iの親を格納する
	}
	int root(int x) {
		if (x == par[x]) return x;
		else return par[x] = root(par[x]);	//経路圧縮
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	bool unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		par[x] = y;
		return true;
	}
};
struct Edge {
	int from, to, cost;
	Edge(int f, int t, int c) { from = f; to = t; cost = c; }
};

ll kruskal(vector<Edge> edges, int vnum)
{
	sort(edges.begin(), edges.end(), [](Edge a, Edge b) {
		return a.cost < b.cost;
		});
	UF uf = UF(vnum);
	ll sum = 0;
	for (Edge e : edges) {
		if (uf.unite(e.from, e.to)) sum += e.cost;
	}
	return sum;
}

