class Graph {
    using ll = long long;
public:
    struct Edge {
        struct Info {
            ll   cost{1};
            bool validity{true};
            Info() = default;
            explicit Info(const ll& _cost) : cost(_cost) { }
            Info(const ll& _cost, const bool& _validity) : cost(_cost), validity(_validity) { }
            friend std::ostream& operator <<(std::ostream& os, const std::shared_ptr<Info>& i) {
                os << "cost : " << i->cost << ", " << "validity : " << i->validity;
                return os;
            }
        };

        enum class Type { Directed, Undirected };

        int src, dst;
        std::shared_ptr<Info> info;

        Edge(const int& _src, const int& _dst, const std::shared_ptr<Info>& _info) : src(_src), dst(_dst), info(_info) { }
        friend std::ostream& operator <<(std::ostream& os, const Edge& e) {
            os << "src : " << e.src << ", " << "dst : " << e.dst << ", " << "info : [" << e.info << "]";
            return os;
        }
    };

    struct Vertex {
        ll cost;
        explicit Vertex(const ll& _cost) : cost(_cost) { }
        friend std::ostream& operator <<(std::ostream& os, const Vertex& v) {
            os << "cost : " << v.cost;
            return os;
        }
    };

    const Edge::Type edge_type;

    std::vector<Vertex>            vertices;
    std::vector<std::vector<Edge>> edges;

    Graph(const int&        num_vertex,
          const Edge::Type& edge_type,
          const ll&         vertex_init_cost = (ll)1e9 + 1) :
        edge_type(edge_type),
        vertices(num_vertex, Vertex(vertex_init_cost)),
        edges(num_vertex) { }

    void setCostToAllVertex(const ll& val) {
        std::fill(vertices.begin(), vertices.end(), Vertex(val));
    };

    void addEdge(const int& src, const int& dst, const ll& cost = 1) {
        auto info = std::make_shared<Edge::Info>(cost);
        edges[src].emplace_back(src, dst, info);
        if(edge_type == Edge::Type::Undirected) edges[dst].emplace_back(dst, src, info);
    }

    void invalidateEdge(const int& src, const int& dst) {
        for(auto& edge : edges[src]) if(edge.dst == dst) { edge.info->validity = false; return; }
    }

    friend std::ostream& operator <<(std::ostream& os, const Graph& g) {
        os << std::endl
           << "--- Vertex Information ---" << std::endl;
        for(size_t i = 0; i < g.vertices.size(); i++) {  os << "[[" << i << "] " << g.vertices[i] << "]" << std::endl; }
        os << "---- Edge Information ----" << std::endl;
        for(const auto& v : g.edges) { for(const auto& e : v) { os << "[" << e << "]" << std::endl; } }
        os << "--------------------------";
        return os;
    }
};

/**
 *  最小全域木を求める(Kruskal法)
 *  NOTE: 計算量O(|E|log|V|), Dependencies: comp-Graph,
 *  @Return: 最小全域木を返す グラフが非連結の場合、連結成分ごとに最小全域木を構成する
 */
// 使用例
// auto mst = kruskal(g);
// std::cout << mst.getTotalCost() << std::endl;
Graph kruskal(const Graph& g) {
    if(g.edge_type != Graph::Edge::Type::Undirected) {
        throw std::logic_error("Graph type is invalid");
    }
    Graph mst(g.vertices.size(), Graph::Edge::Type::Undirected);
    std::vector<Graph::Edge> mst_e;
    mst_e.reserve(g.edges.size());
    for(const auto& ee : g.edges) for(const auto& e : ee) mst_e.push_back(e);
    auto sort_rule = [](const Graph::Edge& l, const Graph::Edge& r) { return l.info->cost < r.info->cost; };
    sort(mst_e.begin(), mst_e.end(), sort_rule);
    struct UF {
        struct N{ll p,r;N(const ll&_p=0,const ll&_r=0):p(_p),r(_r){}};std::vector<N>n;
        explicit UF(const ll&nn){n.reserve(nn);for(ll i=0;i<nn;i++){n.emplace_back(i);}}
        ll r(const ll&x){return(n[x].p==x)?x:n[x].p=r(n[x].p);}
        void u(const ll&x,const ll&y){ll w=r(x);ll z=r(y);
            if(w!=z){if(n[w].r<n[z].r)std::swap(w,z);n[z].p=w;if(n[w].r==n[z].r)n[w].r++;}}
        bool s(const ll&x,const ll&y){return r(x)==r(y);}
    };
    UF uf(g.vertices.size());
    for(const auto& e : mst_e) {
        if(!uf.s(e.src, e.dst)) {
            mst.addEdge(e.src, e.dst, e.info->cost);
            uf.u(e.src, e.dst);
        }
    }
    return mst;
}

void DFS(Graph&     g,
         const int& index,
         ll&       ans) {
    for(const auto& e : g.edges[index]) {
        if(g.vertices[e.dst].cost == 0) {
            g.vertices[e.dst].cost = 1;
            ans += e.info->cost;
            DFS(g, e.dst, ans);
        }
    }
}

