        road[lary].push_back(P(smay, dy));
    }
    for (ll i = 0; i < n; i++){
        used[i] = false;
    }
    que.push(P(0, 0));
    while(que.size()){
        P p = que.top(); que.pop();
        if (used[p.second]) continue;
        used[p.second] = true;
        for (ll i = 0; i < road[p.second].size(); i++){
            P q = road[p.second][i];
            if (used[q.first]) continue;
            que.push(P(q.second, q.first));
        }
        res += p.first;
    }
