    vector<pair<ll,pair<ll,ll>>> roads;//コスト-（街）
    For(i,1,n){
        roads.push_back(make_pair(x.at(i).first-x.at(i-1).first,make_pair(x.at(i).second,x.at(i-1).second)));
        roads.push_back(make_pair(y.at(i).first-y.at(i-1).first,make_pair(y.at(i).second,y.at(i-1).second)));
    }
