int main() {
    ll N;
    cin >> N;
    vector<city> cities(N);
    for (ll i = 0; i < N; i++) {
        cin >> cities[i].x;
        cin >> cities[i].y;
        cities[i].id = i;
    }
    vector<city> cities_x(N);
    vector<city> cities_y(N);
    copy(cities.begin(), cities.end(), cities_x.begin());
    copy(cities.begin(), cities.end(), cities_y.begin());

    sort(cities_x.begin(), cities_x.end(), [](city a, city b) { return a.x < b.x; });
    sort(cities_y.begin(), cities_y.end(), [](city a, city b) { return a.y < b.y; });

    iunionfind* uf = new iunionfind(N);

    map<ll, vector<city>> same_x;
    for (ll i = 0; i < N; i++) {
        if (same_x[cities[i].x].size() > 0) {
            uf->unite(cities[i].id, same_x[cities[i].x][0].id);
        }
        same_x[cities[i].x].push_back(cities[i]);
    }
    map<ll, vector<city>> same_y;
    for (ll i = 0; i < N; i++) {
        if (same_y[cities[i].y].size() > 0) {
            uf->unite(cities[i].id, same_y[cities[i].y][0].id);
        }
        same_y[cities[i].y].push_back(cities[i]);
    }

    vector<edg> dists;
    for (ll i = 1; i < N; i++) {
        city x1 = cities_x[i - 1];
        city x2 = cities_x[i];
        if (x1.x != x2.x) {
            dists.push_back({u : x1.id, v : x2.id, cost : x2.x - x1.x});
        }
    }
    for (ll i = 1; i < N; i++) {
        city y1 = cities_y[i - 1];
        city y2 = cities_y[i];
        if (y1.y != y2.y) {
            dists.push_back({u : y1.id, v : y2.id, cost : y2.y - y1.y});
        }
    }
    sort(dists.begin(), dists.end(), [](edg a, edg b) { return a.cost < b.cost; });

    ll total_cost = 0;
    for (auto edg : dists) {
        if (uf->same(edg.u, edg.v)) {
            continue;
        }
        total_cost += edg.cost;
        uf->unite(edg.u, edg.v);
    }
    cout << total_cost << endl;
}

