typedef long long ll;
typedef pair<ll,ll> V;
typedef pair<ll,int> P;
priority_queue<P,vector<P>,greater<P> > xque;
priority_queue<P,vector<P>,greater<P> > yque;


struct UFT{
	// Union-Find Tree
	int par[MAX_N];
	int depth[MAX_N];
	void init(){
		for(int i=0;i<MAX_N;i++){
			par[i]=i;
			depth[i]=0;
		}
		return;
	}
	UFT(){
		init();
	}

	int get_root(int i){
		if(par[i]==i){
			return i;
		}
		int rt = get_root(par[i]);
		par[i] = rt;
		return rt;
	}
	void merge(int i,int j){
		int x = get_root(i);
		int y = get_root(j);
		if(depth[x]>depth[y]){
			par[y] = x;
		}else{
			par[x] = y;
			if(depth[x]==depth[y]){
				depth[y]++;
			}
		}
		return;
	}
	bool same(int i,int j){
		return get_root(i) == get_root(j);
	}

};

struct EDGE{int from,to,cost;};



bool comp(EDGE a,EDGE b){
	return a.cost < b.cost;
}

int vn;
V vertex[MAX_V];
vector<EDGE> es;

ll cost(V a,V b){
	return min(abs(a.first-b.first),abs(a.second-b.second));
}



