		yque.push(P(b,i));
		vertex[i] = V(a,b);
	}
	int pxi = xque.top().second;xque.pop();
	int pyi = yque.top().second;yque.pop();	
	for(int i=0;i<vn-1;i++){
		int xi = xque.top().second;xque.pop(); 
		ll c = cost(vertex[pxi],vertex[xi]);
		es.push_back((EDGE){pxi,xi,c});
		pxi = xi;
		int yi = yque.top().second;yque.pop(); 
		c = cost(vertex[pyi],vertex[yi]);
		es.push_back((EDGE){pyi,yi,c});
		pyi = yi;
	}
	sort(es.begin(),es.end(),comp);

	for(int i=0;i<es.size();i++){
		if(!uft.same(es[i].from,es[i].to)){
