	vector<Edge> g;

	for(int i=0; i<n-1; i++){
		for(int j=i+1; j<n; j++){
			auto d = min(abs(x.at(i)-x.at(j)),abs(y.at(i)-y.at(j)));
			g.push_back({i,j,d});
			g.push_back({j,i,d});
		}
	}
	sort(g.begin(),g.end());
	int sum{};
	Unionfind uf(n);
	for(auto i:g){
		if(!uf.same(i.s,i.g)){
			uf.unite(i.s,i.g);
			sum += i.d;
		}
	}
	cout << sum << endl;
}

