    }

    // |x2 - x1| の辺と |y2 - y1| の辺を考える
    // |x3 - x1| の辺は |x3 - x2| + |x2 - x1| なので必要ない

    sort(allof(points), [](Point& lhs, Point& rhs) {
        return lhs.x < rhs.x;
        });

    rep(i, n - 1) {
        int from = points[i].index;
        int to = points[i + 1].index;
        int dist = min(abs(points[i + 1].x - points[i].x), abs(points[i + 1].y - points[i].y));
        G.emplace_back(Edge(from, to, dist));
    }

    sort(allof(points), [](Point& lhs, Point& rhs) {
        return lhs.y < rhs.y;
        });

    rep(i, n - 1) {
