  rep(i,N-1){
    stock[i] = mt(x[i+1].fi-x[i].fi, x[i+1].se, x[i].se);
    stock[i+N-1] = mt(y[i+1].fi-y[i].fi, y[i+1].se, y[i].se);
  }
  vsort(stock);
  UnionFind tree(N);

  ll ans = 0;
  rep(i,2*(N-1)){
    ll cost, p1, p2;
    tie(cost, p1, p2) = stock[i];
    if(tree.same(p1,p2)) continue;
    tree.unite(p1,p2);
    ans += cost;
  }


  cout << ans << endl;
}

















