P find(P a) {

    if (a == Parent[a]) return a;
    else {
        return Parent[a] = find(Parent[a]);
    }
}

bool isSame(P a, P b) {
    return find(a) == find(b);

}

void unite(P a, P b) {

    P x = find(a);
    P y = find(b);

    if (x == y) return;

    if (Rank[x] < Rank[y]) {
        Parent[x] = y;
    }
    else {
        Parent[y] = x;
        if (Rank[x] == Rank[y])
            Rank[x]++;
    }
}

