}

int Root( int x ) {
    if( x == root[x] ) return x;
    return root[x] = Root( root[x] );

}

bool Unite( int x, int y ) {
    int rx, ry;
    rx = Root( x );
    ry = Root( y );

    if( rx == ry ) return false;
    if( rx < ry ) {
        root[ry] = rx;

    } else {
        root[rx] = ry;

    }
    return true;

}

/*
