 */
LL Kruskal() {
    vector<pair<LL, P>> ed(int(edges.size()));
    for(int i = 0; i < edges.size(); ++i) {
        ed[i].F = edges[i].S;
        ed[i].S = edges[i].F;
    }

    sort(all(ed));

    LL res = 0;
    for(int i = 0; i < ed.size(); ++i) {
        if(Unite(ed[i].S.F, ed[i].S.S)) {
            res += ed[i].F;
        }
    }
    return res;

}



