using namespace std;

const int N = 111111;
int n;

typedef struct Point {
    int x, y, id;
} Point;

bool compx(const Point& a, const Point& b) {
    return a.x < b.x;
}

bool compy(const Point& a, const Point& b) {
    return a.y < b.y;
}

typedef struct Edge {
    int u, v, cost;
} Edge;

bool compcost(const Edge& a, const Edge& b) {
    return a.cost < b.cost;
}

typedef struct Node {
    Node *parent;
    int rank;
} Node;

Node *getParent(Node *a) {
    while(a->parent != NULL) {
        a = a->parent;
    }
    return a;
}

bool merge(Node *a, Node *b) {
    a = getParent(a);
    b = getParent(b);
    if(a == b) return false;
    if(a->rank < b->rank) {
        a->parent = b;
    } else {
        b->parent = a;
        if(a->rank == b->rank) {
            a->rank++;
        }
    }
    return true; 
}

Point pts[N];
Node ds[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n;
    for(int i = 0; i < n; i++) {
        cin >> pts[i].x >> pts[i].y;
        pts[i].id = i;
    }
    vector<Edge> edges;
    sort(pts, pts + n, compx);
    for(int i = 1; i < n; i++) {
        Edge e;
        e.u = pts[i - 1].id;
        e.v = pts[i].id;
        e.cost = min(abs(pts[i - 1].x - pts[i].x), abs(pts[i - 1].y - pts[i].y));
        edges.push_back(e);
    }
    sort(pts, pts + n, compy);
    for(int i = 1; i < n; i++) {
        Edge e;
        e.u = pts[i - 1].id;
        e.v = pts[i].id;
        e.cost = min(abs(pts[i - 1].x - pts[i].x), abs(pts[i - 1].y - pts[i].y));
        edges.push_back(e);
    }
    sort(edges.begin(), edges.end(), compcost);
    for(int i = 0; i < n; i++) {
        ds[i].parent = NULL;
        ds[i].rank = 0;
    }
    long long int ans = 0;
    for(int i = 0; i < edges.size(); i++) {
        int u = edges[i].u, v = edges[i].v;
        int cost = edges[i].cost;
        Node *a = getParent(ds + u), *b = getParent(ds + v);
        if(merge(a, b)) {
            ans += cost;
        }
    }
    cout << ans << endl;
    return 0;
}

