int Root( int x ) {
    if( x == root[x] ) {
        return x;

    }

    return root[x] = Root( root[x] );

}

bool Unite( int x, int y ) {
    int rx, ry;
    rx = Root( x );
    ry = Root( y );
    if( rx == ry ) {
        return false;

    }

    if( rx > ry ) {
        root[y] = rx;

    } else {
        root[x] = ry;

    }
    return true;

}

LL Kruskal() {
    sort( all( edge ), comp );

    LL res = 0;
    for( int i = 0; i < edge.size(); ++i ) {
        if( Unite( edge[i].u, edge[i].v ) ) {
            res += edge[i].cost;

        }
    }

    return res;
}

