    for(int i=0;i<p.size();i++)
    {
        int from=p[i].from;
        int to=p[i].to;
        int cost=p[i].cost;

        if(!uf.same(from,to))
        {
            uf.unite(from,to);
            ans+=cost;
        }
    }

    cout<<ans<<endl;
