struct UnionFind{
    vector<ll> par,siz;

    UnionFind(ll N):par(N+1),siz(N+1,1){
        rep1(i,N) par[i]=i; //親を自分自身として初期化
    }

    ll root(ll x){
        if(par[x]==x){
            return x;
        }
        else{
            return  par[x]=root(par[x]);
        }
    }
    void unite(ll x,ll y){
        x=root(x);
        y=root(y);
        if(x==y) return;

        if(siz[x]<siz[y]) swap(x,y);

		siz[x]+=siz[y];
		par[y]=x;
    }
    bool same(ll x,ll y){
        return root(x)==root(y);
    }
    ll size(ll x){
        return siz[root(x)];
    }
};

// 頂点a, bをつなぐコストcostの（無向）辺
struct edge{
    ll from,to,cost;

    // コストの大小で順序定義
    bool operator<(const edge& o) const {
        return cost<o.cost;
    }
};

// 頂点数と辺集合の組として定義したグラフ
struct graph{
    ll n;  // 頂点数
    vector<edge> es;  // 辺集合

    graph(ll N){
        n=N;
    }

    void add_edge(ll from,ll to,ll cost){
        edge e;
        e.from=from;
        e.to=to;
        e.cost=cost;
        es.pb(e);
    }

    // クラスカル法で無向最小全域木のコストの和を計算する
    // グラフが非連結のときは最小全域森のコストの和となる
    ll kruskal() {
        // コストが小さい順にソート
        sort(all(es));

        UnionFind uf(n);
        ll res=0;

        rep(i,sz(es)){
            edge& e = es[i];
            if (!uf.same(e.from,e.to)){
                // 辺を追加しても閉路ができないなら、その辺を採用する
                res+=e.cost;
                uf.unite(e.from,e.to);
            }
        }

        return res;
    }
};

int main(){
    ll N; cin>>N;
    graph g(N); // N頂点用意

    vector<P> x(N); //x,i-1
    vector<P> y(N); //y,i-1
    vector<P> p(N); //x,y
    rep(i,N){
