    rep(i,N-1){
        g.add_edge(x[i].b,x[i+1].b,min(abs(p[x[i].b].a-p[x[i+1].b].a),abs(p[x[i].b].b-p[x[i+1].b].b)));
        g.add_edge(y[i].b,y[i+1].b,min(abs(p[y[i].b].a-p[y[i+1].b].a),abs(p[y[i].b].b-p[y[i+1].b].b)));
    }

    cout<<g.kruskal();
}

