using namespace std;

#define ll long long
constexpr ll inf = 1e9+7;

template<size_t N>
class UnionFind {
    int par[N];
public:
    UnionFind() {
        for (int n = 0; n < N; n++) par[n] = n;
    }
    int root(int x) {
        if (par[x] == x) return x;
        else return par[x] = root(par[x]);
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        par[x] = y;
    }
};

int main () {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    cin>>N;
    using pos = pair<ll, ll>;
    map<ll, vector<int>> xs, ys;
    for (int n = 1; n <= N; n++) {
        int x, y;
        cin>>x>>y;
        xs[x].push_back(n);
        ys[y].push_back(n);
    }

    priority_queue<pos, vector<pos>, greater<pos>> dx;
    priority_queue<pos, vector<pos>, greater<pos>> dy;
    for (auto it = begin(xs); it != end(xs); it++) {
        if (++it == end(xs)) break;
        ll nx = it->first;
        ll px = (--it)->first;
        dx.push(make_pair(nx-px, px));
    }
    for (auto it = begin(ys); it != end(ys); it++) {
        if (++it == end(ys)) break;
        ll ny = it->first;
        ll py = (--it)->first;
        dy.push(make_pair(ny-py, py));
    }

    int cost = 0;
    UnionFind<100001> uf;
    while (1) {
        if (dx.empty() && dy.empty()) break;
        if (!dx.empty() && (dy.empty() || dx.top().first < dy.top().first)) {
            ll px = dx.top().second;
            ll nx = dx.top().first + px;
            dx.pop();
            for (ll p : xs[px]) {
                for (ll n : xs[nx]) {
                    if (uf.same(p, n)) continue;
                    uf.unite(p, n);
                    cost += nx - px;
                }
            }
        } else {
            ll py = dy.top().second;
            ll ny = dy.top().first + py;
            dy.pop();
            for (ll p : ys[py]) {
                for (ll n : ys[ny]) {
                    if (uf.same(p, n)) continue;
                    uf.unite(p, n);
                    cost += ny - py;
                }
            }
        }
    } 

    cout<<cost<<endl;

    return 0;
}

