ll prim(){
    priority_queue<ii,vector<ii>,greater<ii> > que;
    que.push(ii(0,0));
    ll res=0;
    while(!que.empty()){
        int cnt=que.top().first;
        int v=que.top().second;
        que.pop();
        if(used[v]) continue;
        used[v]=true;
        res+=cnt;
        for(auto e:G[v]){
            que.push(ii(e.cost,e.to));
        }
    }
    return res;
}

