//比較関数
bool comp(const edge& e1, const edge&e2) {
	return e1.cost < e2.cost;
}
bool compX(const vertex& v1, const vertex& v2) {
	return v1.x < v2.x;
}
bool compY(const vertex& v1, const vertex& v2) {
	return v1.y < v2.y;
}

edge es[2 * MAX];
vertex ver[MAX];
int N; int E;

int kruskal() {
	sort(es, es + E, comp);//costでソート
	init(N);
	int res = 0;
	//コストが小さい辺から順に追加する
	REP(i, E) {
		edge e = es[i];
		//もし閉路ができなければその辺を追加する
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}

