		px[i].first = x[i];
		px[i].second = i;
		py[i].first = y[i];
		py[i].second = i;
	}
	sort(all(px));
	sort(all(py));
	vector<int> from, to;
	vector<ll> cost;
	REP(i, n - 1) {
		from.push_back(px[i].second);
		to.push_back(px[i + 1].second);
		cost.push_back(abs(from.back() - to.back()));
		from.push_back(py[i].second);
		to.push_back(py[i + 1].second);
		cost.push_back(abs(from.back() - to.back()));
	}
	MinimumSpanningTree<ll> mst(from, to, cost, n);
	vector<int> edges = mst.Kruskal();
	ll res = 0;
	REP(i, edges.size()) {
		res += cost[edges[i]];
	}
	put(res);
	return 0;
}

