typedef long long ll;

#define MAX_N 100000
int x[MAX_N+1], y[MAX_N+1];

// Kruskal
struct edge {int from, to, cost;};
vector<edge> KSedges;

// Union-Find tree
int UFpar[MAX_N+1];
int UFrank[MAX_N+1];
void UFinit(int n);
int UFfind(int x);
void UFunite(int x, int y);
bool UFsame(int x, int y);


int main() {
    int N;
    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
    }
    int idxs[N];
    // argsort for x
    for (int i = 0; i < N; i++) idxs[i] = i;
    sort(idxs, idxs+N, [&](int i, int j) {return x[i] < x[j];});
    for (int i = 0; i < N-1; i++) {
        int u = idxs[i], v = idxs[i+1];
        KSedges.push_back({u, v, abs(x[u]-x[v])});
    }
    // argsort for y
    for (int i = 0; i < N; i++) idxs[i] = i;
    sort(idxs, idxs+N, [&](int i, int j) {return y[i] < y[j];});
    for (int i = 0; i < N-1; i++) {
        int u = idxs[i], v = idxs[i+1];
        KSedges.push_back({u, v, abs(y[u]-y[v])});
    }
    sort(KSedges.begin(), KSedges.end(), [](const edge& e1, const edge& e2) {return e1.cost < e2.cost;});
    UFinit(KSedges.size());
    ll res = 0;
    for (int i = 0; i < KSedges.size(); i++) {
        edge e = KSedges[i];
        if (!UFsame(e.from, e.to)) {
            UFunite(e.from, e.to);
            res += e.cost;
        }
    }
    cout << res << endl;
    return 0;
}


void UFinit(int n) {
    for (int i = 0; i < n; i++) {
        UFpar[i] = i;
        UFrank[i] = 0;
    }
}

// 木の根を求める
int UFfind(int x) {
    if (UFpar[x] == x) {
        return x;
    } else {
        return UFpar[x] = UFfind(UFpar[x]);
    }
}

// xとyの属する集合を併合
void UFunite(int x, int y) {
    x = UFfind(x);
    y = UFfind(y);
    if (x == y) return;

    if (UFrank[x] < UFrank[y]) {
        UFpar[x] = y;
    } else {
        UFpar[y] = x;
        if (UFrank[x] == UFrank[y]) UFrank[x]++;
    }
}

// xとyが同じ集合に属するか否か
bool UFsame(int x, int y) {
    return UFfind(x) == UFfind(y);
}

