#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef unsigned long long ull;
#define REP(i, n) for(int i=0; i<n; i++)

class UnionFind{
    public:
        vector<int> par;
        vector<int> rank;

        UnionFind(int n){
            for(int i = 0; i < n; i++){
                par.push_back(i);
                rank.push_back(0);
            }
        }

        int find(int x){
            if(x == par[x])
                return x;
            else
                return par[x] = find(par[x]);
        }

        void unite(int x, int y){
            x = find(x);
            y = find(y);
            if(x == y) return;

            if(rank[x] < rank[y])
                par[x] = y;
            else{
                par[y] = x;
                if(rank[x] == rank[y]) rank[x]++;
            }
        }

        bool same(int x, int y){
            return find(x) == find(y);
        }
};


struct edge { ll u, v, cost; };

bool comp(const edge &e1, const edge &e2){
    return e1.cost < e2.cost;
}

vector<edge> es;
int E;
int V;

//最小全域木  O(|E|*log|V|)
ll kruskal(){
    sort(es.begin(), es.end(), comp);
    UnionFind uf = UnionFind(V);
    ll res = 0;
    for(int i = 0; i < E; i++){
        edge e = es[i];
        if(!uf.same(e.u, e.v)){
            uf.unite(e.u, e.v);
            res += e.cost;
        }
    }   
    return res;
}

pair<ll, int> X[100100];
pair<ll, int> Y[100100];
int main(){
    cin >> V;
    REP(i,V){
        ll x, y;
        cin >> x >> y;
        x--, y--;
        X[i] = make_pair(x, i);
        Y[i] = make_pair(y, i);
    }
    sort(X, X+V);
    sort(Y, Y+V);

    for(int i = 1; i < V; i++){
        pair<ll, int> p0 = X[i-1];
        pair<ll, int> p1 = X[i];
        int idx0 = p0.second;
        int idx1 = p1.second;
        ll loc0 = p0.first;
        ll loc1 = p1.first;
        es.push_back((edge){idx0,idx1,loc1-loc0});
        E++;
    }
    for(int i = 1; i < V; i++){
        pair<ll, int> p0 = Y[i-1];
        pair<ll, int> p1 = Y[i];
        int idx0 = p0.second;
        int idx1 = p1.second;
        ll loc0 = p0.first;
        ll loc1 = p1.first;
        es.push_back((edge){idx0,idx1,loc1-loc0});
        E++;
    }

    ll ans = kruskal();

    cout << ans << endl;
    return 0;
}

