typedef long long ll;

struct Path
{
    int from,to,cost;

    bool operator<(const Path& rhs)const
    {
        return cost<rhs.cost;
    }
};

struct UF
{
    vector<int> par;

    UF(int n):par(n)
    {
        for(int i=0;i<n;i++) par[i]=i;
    }

    int root(int x)
    {
        if(par[x]==x) return x;
        else          return par[x]=root(par[x]);
    }

    void unite(int x,int y)
    {
        int rx=root(x);
        int ry=root(y);

        par[rx]=ry;
    }

    bool same(int x,int y)
    {
        int rx=root(x);
        int ry=root(y);

        return rx==ry;
    }
};

struct V
{
    int pos,index;
    bool operator<(const V& rhs)const
    {
        return pos<rhs.pos;
    }
}

int main()
{
    int n;
    cin>>n;
    vector<Path> p;
    int x[MAX],y[MAX];
    V vx[MAX],vy[MAX];
    for(int i=0;i<n;i++)
    {
        cin>>x[i]>>y[i];
        vx[i]={x[i],i};
        vy[i]={y[i],i};
    }
    sort(vx,vx+n);
    sort(vy,vy+n);
    for(int i=0;i<n-1;i++)
    {
        p.push_back({vx[i].index,vx[i+1].index,vx[i+1].pos-vx[i].pos});
        p.push_back({vy[i].index,vy[i+1].index,vy[i+1].pos-vy[i].pos});
    }
    UF uf(n);

    ll ans=0;
    for(int i=0;i<p.size();i++)
    {
        int from=p[i].from;
        int to=p[i].to;
        int cost=p[i].cost;

        if(!uf.same(from,to))
        {
            uf.unite(from,to);
            ans+=cost;
        }
    }

    cout<<ans<<endl;
    return 0;
}

