    xpr.emplace_back(x[i],i);
    ypr.emplace_back(y[i],i);
  }

  SORT(xpr);
  SORT(ypr);

  UnionFind uf(N);

  rep(i,N-1){
    ll x1=xpr[i].second; ll x2=xpr[i+1].second;
