#include <bits/stdc++.h>

class union_find {
 public:
  using tp = std::vector<size_t>::size_type;
  // 取り扱う型.

  explicit union_find(const tp n) : parent(n), rank(n, 0), cache() {
    for (tp i = 0; i < n; i++) {
      parent[i] = i;
    }
    cache.reserve(n);
  }

  tp root(tp n) {
    // 番号nの親を求める. ついでに経路圧縮を行う.

    while (parent[n] != n) {
      // 根になるまで親を探索. ついでにキャッシュ変数に追加.
      cache.push_back(n);
      n = parent[n];
    }
    for (const auto i : cache) {
      // キャッシュ変数に追加された子の親を経路圧縮.
      parent[i] = n;
    }
    cache.clear();
    return n;
  }

  bool same(tp x, tp y) {
    // xとyが同じグループに属しているか計算.
    return root(x) == root(y);
  }

  void unite(const tp x, const tp y) {
    // xとyを同じグループにする.
    const auto x_root = root(x);
    const auto y_root = root(y);

    if (x_root == y_root) {
      // 根が同じなら元から同じグループ.
      return;
    }

    if (rank[x_root] < rank[y_root]) {
      // rankの大きい方の根を統合後の根にする.
      parent[x_root] = y_root;
    } else if (rank[y_root] < rank[x_root]) {
      // rankの大きい方の根を統合後の根にする.
      parent[y_root] = x_root;
    } else {
      // rankが同じなら, どっちかを根にして根になったほうのランクを上げる.
      parent[x_root] = y_root;
      rank[x_root]++;
    }
  }

 private:
  std::vector<tp> parent;
  // 親の番号を格納. 自分が根なら parent[i] == i になる.
  std::vector<tp> rank;
  // 自分の下に何段分の子があるかを格納.
  std::vector<tp> cache;
  // root計算のときに経路圧縮を行うためのキャッシュ変数.
};

int main() {
  int64_t n;
  std::cin >> n;

  std::vector<std::pair<int64_t, int64_t>> x(n), y(n);

  for (int64_t i = 0; i < n; i++) {
    std::cin >> x[i].first >> y[i].first;
    x[i].second = i;
    y[i].second = i;
  }

  std::sort(x.begin(), x.end());
  std::sort(y.begin(), y.end());

  std::multimap<int64_t, std::pair<int64_t, int64_t>> m;

  for (int64_t i = 0; i < n - 1; i++) {
    m.emplace(x[i + 1].first - x[i].first,
      std::make_pair(x[i + 1].second, x[i].second));
    m.emplace(y[i + 1].first - y[i].first,
      std::make_pair(y[i + 1].second, y[i].second));
  }

  union_find uf(n);
  int64_t l = 0;

  for (const auto &i : m) {
    if (!uf.same(i.second.first, i.second.second)) {
      uf.unite(i.second.first, i.second.second);
      l += i.first;
    }
  }

  std::cout << l << std::endl;
  return 0;
}

