using namespace std;

typedef pair<int, int> P;

// 素集合データ構造
struct UnionFind {
  vector<int> par, sizes; // par:あるデータの親, sizes:あるデータが属する木のサイズ

  // コンストラクタ
  // データ一つ一つを木とし、親は自分自身に初期化する
  UnionFind(int n) : par(n), sizes(n, 1) {
    for (int i = 0; i < n; i++) par[i] = i;
  }

  // データxが属する木の根ノードを取得
  // 再帰的に根を調べる際に、調べた辺を根に直接繋ぎ直すことで効率化している（経路圧縮）
  int find(int x) {
    return (x == par[x] ? x : par[x] = find(par[x]));
  }

  // 2つのデータx, yが属する木をマージする
  void unite(int x, int y) {
    // それぞれのデータの根ノードを取得
    x = find(x);
    y = find(y);

    // x, yが同じ木に属するならマージしない
    if (x == y) return;

    // xの木がyの木より大きくなるようにする
    if (sizes[x] < sizes[y]) swap(x, y);

    // xがyの親になるようにマージする
    par[y] = x;
    sizes[x] += sizes[y];
  }

  // 2つのデータx, yが同じ木に属するかどうか
  bool same(int x, int y) {
    return (find(x) == find(y));
  }

  // データxの属する木のサイズを返す
  int size(int x) {
    return sizes[find(x)];
  }
};

// 頂点a, bを繋ぐコストcostの無向辺
struct Edge {
  int a, b, cost;

  // Edgeの比較はcostで行うことを定義している？
  bool operator<(const Edge &o) const {
    return cost < o.cost;
  }
};

// 頂点数と辺集合の組として定義したグラフ
struct Graph {
  int n; // 頂点数
  vector<Edge> es; // 辺集合
};

// クラスカル法で無向最小全域木を求め、コストの和を返す
int kruskal(Graph g) {
  // costの小さい辺から繫いでいくので、昇順にソートしておく
  sort(g.es.begin(), g.es.end());

  UnionFind uf(g.n);
  int min_cost = 0;
  for (int i = 0; i < g.es.size(); i++) {
    Edge e = g.es[i];
    // 辺を追加しても閉路ができないなら、辺を繋ぐ
    if (!uf.same(e.a, e.b)) {
      min_cost += e.cost;
      uf.unite(e.a, e.b);
    }
  }

  return min_cost;
}

int main() {
  int N;
  cin >> N;
  P x[N], y[N];
  for (int i = 0; i < N; i++) {
    scanf("%d %d", &x[i].first, &y[i].first);
    x[i].second = y[i].second = i;
  }

  // 最小全域木を求めるのに辺が多すぎるので、ソートして隣り合う頂点の辺のみを残す
  sort(x, x + N);
  sort(y, y + N);
  Graph g;
  g.n = N;
  Edge e;
  for (int i = 0; i < N - 1; i++) {
    e.a = x[i].second; e.b = x[i+1].second; e.cost = x[i+1].first - x[i].first;
    g.es.push_back(e);
    e.a = y[i].second; e.b = y[i+1].second; e.cost = y[i+1].first - y[i].first;
    g.es.push_back(e);
  }

  // クラスカル法
  cout << kruskal(g) << endl;
  return 0;
