void prim(int v) {
    priority_queue<P, vector<P>, greater<P> > q;
    fill(dist, dist+100100, INF);
    dist[0] = 0;
    q.push(P(0, 0));
    while (!q.empty()) {
        P p = q.top(); q.pop();
        int cost = p.first;
        int node = p.second;
        if (cost > dist[node]) continue;
        for (auto e: g[node]) {
            if (dist[e.to] > e.cost) {
                dist[e.to] = e.cost;
                q.push(P(e.cost, e.to));
            }
        }
    }
}

