struct union_find{
  vector<long long> data;//そのノードがrootであれば-（集合のサイズ）を表し、そうでなければ親ノードidを示す。
  vector<long long> diff_weight;
  union_find(long long size, long long abel_sum_unity = 0)
  :data(size,-1),diff_weight(size,abel_sum_unity){}//コンストラクタ,size個のノードを作成し、-1で初期化
  //根を探す,経路圧縮
  long long root(long long a){
    if(data[a]<0) return a;
    long long r = root(data[a]);
    diff_weight[a] += diff_weight[data[a]];
    return data[a] = r;
    // return data[a] < 0 ? a : data[a]=root(data[a]),diff_weight[a] += diff_weight[data[a]];
  }
  //a,bが同じ集合に属するか調べる
  bool same(long long a,long long b){
    return root(a) == root(b);
  }
  //小さい方の木の根に大きい方の根を上書きする
  bool unite(long long a,long long b, long long w=1){
    w += weight(a) - weight(b);
    a = root(a),b = root(b);
    if(a==b) return false;//根が同じなら終了,uniteが失敗したことを出力
    if(-data[a]<-data[b]) swap(a,b),w=-w; //-data[a]≥-data[b]となるようにswap
    //集合サイズの大きい方に小さい方をつける。
    data[a] += data[b];//集合サイズを統合
    data[b] = a;//bの親をaにする。
    diff_weight[b] = w;
    return true;//unite成功を出力
  }
  //aが属する集合のサイズを出力
  long long size(long long a){
    return -data[root(a)];
  }
  //root(a)からaまでの距離を返す。
  long long weight(long long a){
    root(a);
    return diff_weight[a];
  }
  long long diff(long long a,long long b){
    return weight(b) - weight(a);
  }
};
