#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef pair<int, int> Edge;

struct UnionFind {
  vector<int> par;
  vector<int> sizes;

  UnionFind(int n) : par(n), sizes(n, 1) {
    for (int i = 0; i < n; i++) par[i] = i;
  }

  int find(int x) {
    return x == par[x] ? x : par[x] = find(par[x]);
  }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);

    if (x == y) return;

    if (sizes[x] > sizes[y]) swap(x, y);

    par[x] = y;
  }

  bool same(int x, int y) {
    return find(x) == find(y);
  }
};

int main() {
  int n; cin >> n;
  int x[n], y[n];
  vector<int> v(n), w(n);
  for (int i = 0; i < n; i++) {
    cin >> x[i] >> y[i];
    v[i] = w[i] = i;
  }

  sort(v.begin(), v.end(), [&](int a, int b) {
    return x[a] < x[b];
  });
  sort(w.begin(), w.end(), [&](int a, int b) {
    return y[a] < y[b];
  });

  auto f = [&](Edge e) {
    int ex = abs(x[e.first] - x[e.second]);
    int ey = abs(y[e.first] - y[e.second]);
    return min(ex, ey);
  };

  int en = n * 2 - 2;
  Edge edges[en];
  int cost[en];
  vector<int> u(en);
  for (int i = 0; i < en/2; i++) {
    edges[i] = Edge(v[i], v[i+1]);
    cost[i] = f(edges[i]);
    u[i] = i;
  }
  for (int i = en/2; i < en; i++) {
    edges[i] = Edge(w[i-en/2], w[i+1-en/2]);
    cost[i] = f(edges[i]);
    u[i] = i;
  }

  sort(u.begin(), u.end(), [&](int a, int b) {
    return cost[a] < cost[b];
  });

  long long ans = 0;
  UnionFind uf(en);
  for (int i : u) {
    int p = edges[i].first;
    int q = edges[i].second;
    if (!uf.same(p, q)) {
      uf.unite(p, q);
      ans += cost[i];
    }
  }
  cout << ans << endl;
}

