bool Unite( int x, int y ) {
    int rx, ry;
    rx = Root( x );
    ry = Root( y );
    if( rx == ry ) {
        return false;

    }

    if( rx > ry ) {
        root[y] = rx;

    } else {
        root[x] = ry;

    }
    return true;

}

