  ll N;
  scanf("%lld", &N);
  vector<Node> ns(N);
  for (int i = 0; i < N; i++) {
    (&ns[i])->id = i;
    scanf("%lld", &ns[i].x);
    scanf("%lld", &ns[i].y);
  }
  solve(N, std::move(ns));
  return 0;
}

