  sort(x,x+V);
  sort(y,y+V);
  rep(i,V-1){
    es[2*i]={x[i].second,x[i+1].second,x[i+1].first-x[i].first};
    es[2*i+1]={y[i].second,y[i+1].second,y[i+1].first-y[i].first};
  }
  int ans=kruskal();
  cout << ans << endl;
return 0;}

