using namespace std;

struct point
{
	int id;
	int x;
	int y;
};

struct edge
{
	int src;
	int dst;
	int cost;

	bool operator<(const edge &other) const
	{
		return other.cost < cost;
	}
};

int main()
{
	int N;
	cin >> N;
	vector<point> p(N);

	for (int i = 0; i < N; ++i) {
		p[i].id = i;
		cin >> p[i].x >> p[i].y;
	}

	vector<vector<edge>> g(N);

	sort(p.begin(), p.end(), [](auto &a, auto &b) {return a.x < b.x; });
	for (int i = 0; i + 1 < N; ++i) {
		edge e;
		e.src = p[i].id;
		e.dst = p[i + 1].id;
		e.cost = p[i + 1].x - p[i].x;
		g[e.src].push_back(e);
		swap(e.src, e.dst);
		g[e.src].push_back(e);
	}

	sort(p.begin(), p.end(), [](auto &a, auto &b) {return a.y < b.y; });
	for (int i = 0; i + 1 < N; ++i) {
		edge e;
		e.src = p[i].id;
		e.dst = p[i + 1].id;
		e.cost = p[i + 1].y - p[i].y;
		g[e.src].push_back(e);
		swap(e.src, e.dst);
		g[e.src].push_back(e);
	}

	set<int> visited;
	priority_queue<edge> q;
	auto visit = [&](int x) -> bool {
		if (!visited.insert(x).second) {
			return false;
		}
		for (auto &e : g[x]) {
			q.push(e);
		}
		return true;
	};
	visit(0);
	int ans = 0;
	while (!q.empty()) {
		auto e = q.top();
		q.pop();
		if (visit(e.dst)) {
			ans += e.cost;
		}
	}
	cout << ans << endl;
}

