template <typename T>
class UnionFindTree
{
public:
    UnionFindTree(T size = 0)
    {
        if (size == 0)
            return;

        unitedSize.resize(size + 1, 1);
        rank.resize(size + 1, 0);
        parents.resize(size + 1);
        for (T i=0; i<size; ++i)
            parents[i] = i;
    }

    bool Union(T x, T y)
    {
        x = FindRoot(x);
        y = FindRoot(y);
        if (x == y)
            return false;

        if (rank[x] < rank[y])
        {
            parents[x] = y;
            unitedSize[y] += unitedSize[x];
            if (rank[y] == rank[x])
                rank[y]++;
        }
        else
        {
            parents[y] = x;
            unitedSize[x] += unitedSize[y];
            if (rank[x] == rank[y])
                rank[x]++;
        }

        return true;
    }

    T FindRoot(T x)
    {
        if (parents[x] == x)
            return x;

        while (parents[x] != x)
        {
            T parent = parents[x];
            parents[x] = parents[parent];
            x = parents[x];
        }

        return x;
    }

    bool IsUnited(T a, T b)
    {
        return FindRoot(a) == FindRoot(b);
    }

private:
    std::vector<T> parents;
    std::vector<T> rank;
    std::vector<T> unitedSize;
};

class Edge
{
public:
    Edge(ll from, ll to, ll weight)
    {
        From = from;
        To = to;
        Weight = weight;
    }

    ll From;
    ll To;
    ll Weight;
};

ll MSTWeight(int nodeNum, std::vector<Edge>& edgeList)
{
    UnionFindTree<int> vertexTree(nodeNum);

    std::sort(edgeList.begin(), edgeList.end(), [](Edge& lhs, Edge& rhs) {
        return lhs.Weight < rhs.Weight;
    });
    ll result = 0;
    for (auto& edge : edgeList)
    {
        if (!vertexTree.IsUnited(edge.From, edge.To) || edge.Weight < 0)
        {
            vertexTree.Union(edge.From, edge.To);
            result += edge.Weight;
        }
    }

    return result;
}

int main()
{
    ll N;
    std::cin >> N;
    std::vector<std::pair<ll, ll>> towns(N, std::pair<ll, ll>(0, 0));
    for (auto i=0; i<N; ++i)
        std::cin >> towns[i].first >> towns[i].second;

    std::vector<Edge> edges;
    for (auto i=0; i<N; ++i)
    {
        for (auto j=0; j<i; ++j)
        {
            auto vertical = std::abs(towns[i].first - towns[j].first);
            auto horizontal = std::abs(towns[i].second - towns[j].second);
            auto cost = std::min(vertical, horizontal);
            edges.emplace_back(Edge(i, j, cost));
        }
    }

    std::cout << MSTWeight(N, edges) << std::endl;
}

