ll nearest(int N, vector<int> connected, vector<ll> x, vector<ll> y){
    ll cost = 1000000001;
    int add;
    if (connected.size() == N) return 0;
    for (auto v : connected){
        for (int i=0; i<N; i++){
            if (find(connected.begin(),connected.end(),i) != connected.end()) continue;
            if(chmin(cost, abs(x[i]-x[v])) | chmin(cost, abs(y[i]-y[v]))){
                add = i;
            }
        }
    }
    connected.push_back(add);
    return cost + nearest(N, connected, x, y);
}

