template <class T>
class graph {
private:
    const size_t count_vertices;
    const bool is_directed;
public:
    using weight_type = T;
    vector<edge<T>> *edges;
    graph(size_t count_vertices, bool is_directed = true) : count_vertices(count_vertices), is_directed(is_directed) {
        edges = new vector<edge<T>>[count_vertices];
    }
    ~graph() {
        delete [] edges;
    }
    size_t size() const { return count_vertices; }
    void make_edge(size_t u, size_t v, T cost) {
        edges[u].push_back(edge<T>(v, cost));
        if (!is_directed)
            edges[v].push_back(edge<T>(u, cost));
    }
};

template <class T>
typename graph<T>::weight_type minimum_spanning_tree(const graph<T> &g) {
    using W = typename graph<T>::weight_type;
    using P = pair<W, size_t>;

    int n = g.size();
    W result = 0;
    vector<bool> used(n, false);
    priority_queue<P, vector<P>, greater<P>> q;
    q.push(P(0, 0));
    while (!q.empty()) {
        W w;
        size_t u;
        tie(w, u) = q.top();
        q.pop();
        if (used[u]) {
            continue;
        }
        used[u] = true;
        result += w;
        for (const edge<W> &e: g.edges[u]) {
            size_t v = e.to;
            if (!used[v]) {
                q.push(P(e.cost, v));
            }
        }
    }
    return result;
}

