// 最小全域木のコストを求める
int kruskal(vector<edge> &edges, const int size) {
  sort(edges.begin(), edges.end(), comp);
  UnionFind uf(size);
  int res = 0;
  for (auto e : edges) {
    if (!uf.isSame(e.u, e.v)) {
      uf.merge(e.u, e.v);
      res += e.cost;
    }
  }
  return res;
}

