#define rep(i,n) for(int i = 0; i < ((int)(n)); i++)   // 0-indexed昇順

int main() {
    ll N; cin >> N;
    map<pair<ll,ll>, ll> E;

    map<pair<ll,ll>, ll> VX;
    map<pair<ll,ll>, ll> VY;
    rep(i, N) {
        ll x, y; cin >> x >> y;
        VX[make_pair(x,y)] = i;
        VY[make_pair(y,x)] = i;
    }
    /*
    fprintf(stderr, "-------------- VX --------------\n");
    for (auto x : VX) fprintf(stderr, "%ld %ld %ld\n", x.first.first, x.first.second, x.second);
    */
    auto prev = VX.begin();
    for (auto x = next(prev, 1); x != VX.end(); x++) { 
        ll cost = min(abs(prev->first.first - x->first.first),
                      abs(prev->first.second - x->first.second)); 
        E.emplace(make_pair(prev->second, x->second), cost);
        prev = x;
    }

    /*
    fprintf(stderr, "-------------- VY --------------\n");
    for (auto y : VY) fprintf(stderr, "%ld %ld %ld\n", y.first.second, y.first.first, y.second);
    */
    prev = VY.begin();
    for (auto y = next(prev, 1); y != VY.end(); y++) {
        ll cost = min(abs(prev->first.first - y->first.first),
                      abs(prev->first.second - y->first.second));
        E.emplace(make_pair(prev->second, y->second), cost);
        prev = y;
    }
    /*
    fprintf(stderr, "--------------  E --------------\n");
    for (auto x : E) {
        fprintf(stderr, "%ld %ld %ld\n", x.first.first, x.first.second, x.second);
    }
    */

    // Prim
    vector<ll> mincost(N, INT64_MAX);
    vector<bool> used(N, false);
    mincost[0] = 0;
    ll res = 0;
    while(1) {
        int v = -1;
        for (ll u = 0; u < N; u++) {
            if (!used[u] && (v == -1 || mincost[u] < mincost[v])) v = u;
        }
        if (v == -1) break;
        used[v] = true;
        res += mincost[v];

        for (int u = 0; u < N; u++) {
            if (E.count({v,u}) > 0) {
                mincost[u] = min(mincost[u], E[{v,u}]);
            }
            if (E.count({u,v}) > 0) {
                mincost[u] = min(mincost[u], E[{u,v}]);
            }
        }
    }
    cout << res << endl;
}

