class UnionFind {
public:
    int rank;
    vector <int> par; // 各元の親を表す配列
    vector <int> siz; // 素集合のサイズを表す配列(1 で初期化)

    // Constructor
    UnionFind(int sz_): par(sz_), siz(sz_, 1) {
        rank = sz_;
        for (int i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }
    void init(int sz_) {
        rank = sz_;
        par.resize(sz_);
        siz.assign(sz_, 1);  // resize だとなぜか初期化されなかった
        for (int i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }

    // Member Function
    // Find
    int root(int x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }

    // Union(Unite, Merge)
    bool merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        // merge technique（データ構造をマージするテク．小を大にくっつける）
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        rank--;
        return true;
    }

    bool issame(int x, int y) { // 連結判定
        return root(x) == root(y);
    }

    int size(int x) { // 素集合のサイズ
        return siz[root(x)];
    }
};

struct town_cord {
    int v;
    int idx;

    bool operator<(const town_cord& other) const {
        if (v < other.v) return true;
        else return false;
    }
};

int main() {
    int N;
    cin >> N;
    vector<P> towns;
    set<town_cord> xs, xs_minus, ys, ys_minus;
    REP(i, N) {
        P town;
        cin >> town.first >> town.second;
        town_cord t1 = {town.first, i};
        town_cord t3 = {town.second, i};
        xs.insert(t1);
        town_cord t2 = {-town.first, i};
        xs_minus.insert(t2);
        ys.insert(t3);
        town_cord t4 = {-town.second, i};
        ys_minus.insert(t4);
        towns.push_back(town);
    }

    N = towns.size();
    UnionFind uf = UnionFind(N);
    vector<edge> edges;

    int town_idx = 0;
    for(P town: towns) {
        town_cord t1 = {town.first, 0};
        town_cord t2 = {-town.first, 0};
        town_cord t3 = {town.second, 0};
        town_cord t4 = {-town.second, 0};
        auto x1_itr = xs.upper_bound(t1);
        auto x2_itr = xs_minus.upper_bound(t2);
        auto y1_itr = ys.upper_bound(t3);
        auto y2_itr = ys_minus.upper_bound(t4);

        if(x1_itr != xs.end()) {
            edge e = {town_idx, x1_itr->idx, ll(abs(town.first-x1_itr->v))};
            edges.push_back(e);
        }

        if(x2_itr != xs_minus.end()) {
            edge e = {town_idx, x2_itr->idx, ll(abs(town.first+x2_itr->v))};
            edges.push_back(e);
        }

        if(y1_itr != ys.end()) {
            edge e = {town_idx, y1_itr->idx, ll(abs(town.second-y1_itr->v))};
            edges.push_back(e);
        }

        if(y2_itr != ys_minus.end()) {
            edge e = {town_idx, y2_itr->idx, ll(abs(town.second+y2_itr->v))};
            edges.push_back(e);
        }
        town_idx++;
    }

    sort(ALL(edges));
    // cerr << "edges.size = " << edges.size() << endl;
    // cerr << "n_unique_town = " << n_unique_town << endl;
    vector<edge> tree;

    for(edge e: edges) {
        // cerr << "e.from =" << e.from << " e.to = " << e.to << " e.d = " << e.d << endl;
        if(!uf.issame(e.from, e.to)) {
            uf.merge(e.from, e.to);
            tree.push_back(e);
        }
    }

    ll ans = 0;
    for(edge e: tree) {
        ans += e.d;
    }

    cout << ans << endl;

    return 0;
}

