	P roadind[2*n-2];
	P cost[2*n-2];
	for (ll i=1;i<n;i++){
		roadind[2*(i-1)] = P(x[i-1].second,x[i].second);
		cost[2*(i-1)] = P(x[i].first-x[i-1].first,2*(i-1));
		roadind[2*(i-1)+1] = P(y[i-1].second,y[i].second);
		cost[2*(i-1)+1] = P(y[i].first-y[i-1].first,2*(i-1)+1);
	}

	sort(cost,cost+2*n-2);

	init(n);
	ll ans = 0;
	for (ll i=0;i<2*n-2;i++){
