}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;

int N;
vector<P> x, y;
vector<vector<P>> graph(100001); //辺のコスト、行先の頂点
bitset<100001> bit;//各点を一度使ったかどうか

ll Prim(int start = 1){

    priority_queue<P, vector<P>, greater<P>> que;
    que.push(make_pair(0, start)); //頂点startから始める

    ll num = 0;
    while(!que.empty()){
        ll cost, next; tie(cost, next) = que.top(); que.pop();
        if(bit[next]) continue;
        bit[next] = true;
        num += cost;
        for(int i = 0; i < graph[next].size(); ++i) que.push(graph[next][i]);
    }

    return num;
}

int main(void){

	scanf("%d", &N);
	for(int i = 1; i <= N; ++i){
	    ll a, b; scanf("%lld %lld", &a, &b);
	    x.push_back(make_pair(a, i)), y.push_back(make_pair(b, i));
	}
	sort(x.begin(), x.end()), sort(y.begin(), y.end());

	for(int i = 0; i < x.size() - 1; ++i){
	    int t1 = x[i].second, t2 = x[i + 1].second;
	    ll c = abs(x[i].first - x[i + 1].first);
	    graph[t1].push_back(make_pair(c, t2));
	    graph[t2].push_back(make_pair(c, t1));
	}

	for(int i = 0; i < y.size() - 1; ++i){
	    int t1 = y[i].second, t2 = y[i + 1].second;
	    ll c = abs(y[i].first - y[i + 1].first);
	    graph[t1].push_back(make_pair(c, t2));
	    graph[t2].push_back(make_pair(c, t1));
	}

	printf("%lld\n", Prim());

    return 0;
}

