int n;


struct union_find{
    vector<int> par;
    vector<int> rank;
    union_find(int n) : par(n), rank(n){
        for(int i = 0; i < n; i++){
            par[i] = i; rank[i] = 0;
        }
    }
    int root (int x){
        if(par[x] == x) return x;
        par[x] = root(par[x]);
        return par[x];
    }
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]){
            par[rx] = ry;
        }
        else{
            par[ry] = rx;
            if (rank[rx] == rank[ry]) rank[rx]++;
        }
    }
    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

lint Kruskal(){
    sort(all(G), [](edge const& l, edge const& r)->bool{
        return l.cost < r.cost;
    });

    union_find uf(n);
    lint res = 0; int c = 0;
    for(edge& e: G){
        if(uf.same(e.to, e.from)) continue;
        uf.unite(e.to, e.from);
        res += e.cost; c++;
        if(c == n - 1) break;
    }
    return res;
}

