    });
    rep(i, n-1){
        G.push_back(edge{vp[i].num, vp[i+1].num, vp[i+1].x - vp[i].x});
        G.push_back(edge{vp[i+1].num, vp[i].num, vp[i+1].x - vp[i].x});
