    }
    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());
    vector<edge> es;
    rep(i, n) {
        if (i + 1 < n) es.push_back({xs[i].second, xs[i + 1].second, xs[i + 1].first - xs[i].first});
        if (i + 1 < n) es.push_back({ys[i].second, ys[i + 1].second, ys[i + 1].first - ys[i].first});
    }
    sort(es.begin(), es.end(), [](auto& e1, auto& e2) {
        return e1.cost < e2.cost;
    });
    ll ans = 0;
    for (int i = 0; i < es.size(); i++) {
        edge e = es[i];
        if (uf.find(e.from) != uf.find(e.to)) {
            uf.unite(e.from, e.to);
            ans += e.cost;
        }
    }
    cout << ans << endl;
}

