struct UnionFind {
  vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

  UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
    for(int i = 0; i < N; i++) par[i] = i;
  }

  int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  void unite(int x, int y) { // xとyの木を併合
    int rx = root(x); //xの根をrx
    int ry = root(y); //yの根をry
    if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
    par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
  }

  bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }
};

int main(int argc, const char * argv[]) {
  int N; cin >> N;
  vector<ll> x(N), y(N);
  for(int i=0; i<N; i++) cin >> x[i] >> y[i];

  vector<int> xi(N), yi(N);
  iota(xi.begin(), xi.end(), 0);
  iota(yi.begin(), yi.end(), 0);
  sort(xi.begin(), xi.end(), [&](int i, int j){return x[i]<x[j];});
  sort(yi.begin(), yi.end(), [&](int i, int j){return y[i]<y[j];});

  multiset<tuple<ll, int, int>> s;
  for(int i=1; i<N; i++){
    s.emplace((x[xi[i]] - x[xi[i-1]]), xi[i], xi[i-1]);
    s.emplace((y[yi[i]] - y[yi[i-1]]), yi[i], yi[i-1]);
  }

  UnionFind tree(N);
  int n, i, j;
  ll ans = 0;
  for(auto t: s){
    tie(n, i, j) = t;
    if(tree.same(i, j)) continue;
    tree.unite(i, j);
    ans += n;
  }

  cout << ans << endl;
  return 0;
}

