struct DSU {
    vector<int> par;
    int n;
    DSU (int n) : n(n) {
        par = vector<int>(n + 1, -1);
    }
    bool Find(int u, int v) {
        return root(u) == root(v);
    }
    int root(int u) {
        if(par[u] < 0)
            return u;
        return par[u] = root(par[u]);
    }
    void Union(int u, int v) {
        int i = root(u);
        int j = root(v);
        if(i == j)
            return;
        if(par[i] > par[j])
            swap(i, j);
        par[i] += par[j];
        par[j] = i;
    }
};

