    UnionFind uf(n);
    priority_queue<Edge> Q;
    rep(u, n) {
        for (auto e = g[u].begin(); e != g[u].end();e++) {
            if (u < e->dst) Q.push(*e);
        }
    }
    Weight total = 0;
    Edges F;
    while (F.size() < n - 1 && !Q.empty()) {
        Edge e = Q.top(); Q.pop();
        if (uf.unite(e.src, e.dst)) {
            F.push_back(e);
            total += e.weight;
        }
    }
    return pair<Weight, Edges>(total, F);
}
int main() {
    cin >> n; int a, b, c;
    vector<vector<Edge>> G(n + 1);
    vector<pair<int,int>> x(n), y(n);
    rep(i, n) {
        cin >> a >> b;
        x[i] = make_pair(a, i);
        y[i] = make_pair(b, i);
    }sort(ALL(x)), sort(ALL(y));
    rep(i, n - 1) {
        int t = x[i].second, u = x[i + 1].second;
        c = x[i + 1].first - x[i].first;
        Edge e = { t,u,c };
        G[t].push_back(e);
        e = { u,t,c };
        G[u].push_back(e);
    }
    rep(i, n - 1) {
        int t = y[i].second, u = y[i + 1].second;
        c = y[i + 1].first - y[i].first;
        Edge e = { t,u,c };
        G[t].push_back(e);
        e = { u,t,c };
        G[u].push_back(e);
    }
    pair<Weight, Edges> p = minimumSpanningForest(G);
    cout << p.first << endl;
}

