    vector<Edge> edges;
    for (int i = 1; i < N; i++) {
        int from, to;
        ll cost;
        from = x.at(i).second;
        to = x.at(i - 1).second;
        cost = x.at(i).first - x.at(i - 1).first;
        edges.push_back(Edge(from, to, cost));
    }
    for (int i = 1; i < N; i++) {
        ll from, to, cost;
        from = y.at(i).second;
        to = y.at(i - 1).second;
        cost = y.at(i).first - y.at(i - 1).first;
        edges.push_back(Edge(from, to, cost));
    }

