  });

  sort(pointsSortByY.begin(), pointsSortByY.end(), [](Point l, Point r) {
    return l.y < r.y;
  });

  UnionFind uf(n);
  priority_queue<QP, vector<QP>, greater<QP>> que;
  long res = 0;

  rep(i, n-1) {
    if (pointsSortByX[i].x == pointsSortByX[i+1].x) {
      uf.unite(pointsSortByX[i].id, pointsSortByX[i+1].id);
    } else {
      que.push(QP({pointsSortByX[i].id, pointsSortByX[i+1].id, pointsSortByX[i+1].x - pointsSortByX[i].x}));
