void union_find_init(int x){
    for(int i=0; i<n; i++){
        par[i] = i;
        rnk[i] = 0;
    }
}
int find(int x){
    if(par[x] == x){
        return x;
    }else{
        return par[x] = find(par[x]);
    }
}

void unite(int x, int y){
    x = find(x);
    y = find(y);
    if(x == y){
        return;
    }
    if(rnk[x] < rnk[y]){
        par[x] = y;
    }else{
        par[y] = x;
        if(rnk[x] == rnk[y]){
            rnk[x]++;
        }
    }
}
bool same(int x, int y){
    return find(x) == find(y);
}

bool comp_x(const Vertex& e1, const Vertex& e2){
    return e1.x < e2.x;
}
bool comp_y(const Vertex& e1, const Vertex& e2){
    return e1.y < e2.y;
}
bool comp_cost(const edge& e1, const edge& e2){
    return e1.cost < e2.cost;
}

