        for2(j,i+1,N) {
            dis.push_back(make_tuple(min(abs(X[i]-X[j]),abs(Y[i]-Y[j])),i,j));
        }
    }
    sort(dis.begin(),dis.end());
    ll rest = N - 1;
    UnionFind uni(N);
    ll ans = 0;
    for (auto item : dis) {
        if (rest == 0) break;
        ll d,a,b;
        tie(d,a,b) = item;
        if (uni.root(a) == uni.root(b)) continue;
        ans += d;
        uni.connect(a,b);
        --rest;
    }

    cout << ans << endl;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    solve();
}

