//find  どのグループか調べる
struct UnionFind {
    vector<LL> parent;

    UnionFind(LL n) : parent(n, -1) { }
    void init(LL n) { parent.assign(n, -1); }

    //xの属している木の根っこを返す
    LL root(LL x) {
        if (parent[x] < 0) return x;
        else return parent[x] = root(parent[x]);//経路圧縮
    }

    LL size(LL x) {return -parent[root(x)];}//xの属する木の要素数を求める
    bool is_same_tree(LL x,LL y) {return root(x)==root(y);}

    bool merge(LL x,LL y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (parent[x] > parent[y]) swap(x, y);//xの親の方がyの親より小さくなるようにする
        parent[x] += parent[y];//経路の長さを加算
        parent[y] = x;//yの親をxとする
        return true;
    }
};

LL N;
vector<tuple<LL,LL,LL>> xy;
vector<tuple<LL,LL,LL>> yx;

LL ans = 0;

void solve(){
	sort(xy.begin(),xy.end());
	sort(yx.begin(),yx.end());

	priority_queue<tuple<LL,LL,LL>,vector<tuple<LL,LL,LL>>,greater<tuple<LL,LL,LL>>> pq;
	for(int i=0;i<=N-2;i++){
		LL weight = min(abs(get<0>(xy[i]) - get<0>(xy[i+1])),
						abs(get<1>(xy[i]) - get<1>(xy[i+1])));
		LL p1 = get<2>(xy[i]);
		LL p2 = get<2>(xy[i+1]);
		pq.push(tuple<LL,LL,LL>(weight,p1,p2));
	}
	for(int i=0;i<=N-2;i++){
		LL weight = min(abs(get<0>(yx[i]) - get<0>(yx[i+1])),
						abs(get<1>(yx[i]) - get<1>(yx[i+1])));
		LL p1 = get<2>(yx[i]);
		LL p2 = get<2>(yx[i+1]);
		pq.push(tuple<LL,LL,LL>(weight,p1,p2));
	}

	UnionFind uf(N);
	while(!pq.empty()){
		LL weight = get<0>(pq.top());
		LL p1 = get<1>(pq.top());
		LL p2 = get<2>(pq.top());
		pq.pop();
		if(uf.is_same_tree(p1,p2)) continue;
		uf.merge(p1,p2);
		ans += weight;
	}
}

int main(){
    cin >> N;
    for(int i=0;i<N;i++){
    	LL x,y;cin >> x >> y;
    	xy.push_back(tuple<LL,LL,LL>(x,y,i));
    	yx.push_back(tuple<LL,LL,LL>(y,x,i));
    }

    solve();

    cout << ans << endl;
    return 0;
}

