struct UnionFind {
    vector<int> par;

    UnionFind(int n) : par(n, -1) {}
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0)
            return x;
        else
            return par[x] = root(par[x]);
    }

    bool issame(int x, int y) { return root(x) == root(y); }

    bool merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y);  // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) { return -par[root(x)]; }
};

// 通路
struct corridor {
    int a, b;  // 繋がっているcell
    ll len;    // 通路の長さ
    corridor(int a, int b, ll len) : a(a), b(b), len(len) {}

    // ソート用
    bool operator<(const corridor& rhs) const {
        if (len != rhs.len) {
            return len < rhs.len;
        }
        if (a != rhs.a) {
            return a < rhs.a;
        }
        return b < rhs.b;
    }
};

int main() {
    //三次元座標
    int N;
    cin >> N;
    vector<ll> x(N), y(N);
    for (int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
    }

    vector<P> v1, v2;
    rep(i, N) v1.push_back(make_pair(x[i], i));
    rep(i, N) v2.push_back(make_pair(y[i], i));

    sort(v1.begin(), v1.end());
    sort(v2.begin(), v2.end());

    // 全ての通路を長さでソートする
    vector<corridor> cor;
    for (int i = 0; i < N - 1; i++) {
        ll dx, dy, w;
        int s, t;

        s = v1[i].second, t = v1[i + 1].second;
        dx = abs(x[s] - x[t]);
        dy = abs(y[s] - y[t]);
        w = min(dx, dy);
        cor.push_back(corridor(s, t, w));
        cor.push_back(corridor(t, s, w));

        s = v2[i].second, t = v2[i + 1].second;
        dx = abs(x[s] - x[t]);
        dy = abs(y[s] - y[t]);
        w = min(dx, dy);
        cor.push_back(corridor(s, t, w));
        cor.push_back(corridor(t, s, w));
    }
    sort(cor.begin(), cor.end());

    UnionFind uf(N);
    ll ans = 0;     // 通路の長さの総和
    int count = 0;  // 選んだ通路の数

    for (vector<corridor>::iterator itr = cor.begin(); count < N - 1; ++itr) {
        // aとbが別々の集合に属しているならばその通路を採用する
        if (uf.merge(itr->a, itr->b)) {
            ans += itr->len;
            ++count;
        }
    }

    cout << ans << endl;
}

