struct unionfind{
    vec<int> par;int num;
    unionfind(int n):num(n),par(n,-1){}
    int find(int x){
        if(par[x]==-1)return x;
        else return par[x]=find(par[x]);
    }
    void unite(int x,int y){
        x=find(x),y=find(y);
        if(x==y)return;
        par[x]=y;
        num--;
        return;
    }
};

