using namespace std;


struct Edge {
    int from;
    int to;
    int cost;
    Edge(int from, int to, int cost): from(from), to(to), cost(cost){};
    bool operator<(const Edge& edge) const {
        return this->cost < edge.cost;
    }
    bool operator>(const Edge& edge) const {
        return this->cost > edge.cost;
    }
};

class UnionFind {
public:
    vector<int> parent;

    UnionFind(int size) {
        parent.resize(size + 1);
        iota(parent.begin(), parent.end(), 0);
    }

    // xとyが同じ集合に属するか
    bool isSameSet(int x, int y) {
        return findRoot(x) == findRoot(y);
    }

    // xとyの属する集合を併合
    void unionSet(int x, int y) {
        x = findRoot(x);
        y = findRoot(y);
        if (x == y) { return; }

        parent[x] = y;
    }

    // 集合の数を取得
    int getNumberOfSet() {
        int n = 0;
        for (int i = 0; i < parent.size(); ++i) {
            if (parent[i] == i) { n++; }
        }
        return n;
    }

private:
    // 木の根を求める
    int findRoot(int x) {
        if (parent[x] == x) {
            return x;
        }
        else {
            return parent[x] = findRoot(parent[x]);
        }
    }
};

/**
 * 最小全域木のコストを算出
 * @param V ノード数 
 * @param edges エッジ
 * @return 最小全域木のコスト
 */
int kruskal(int V, vector<Edge> edges) {
    sort(edges.begin(), edges.end());   // コストでソート

    UnionFind uf(V);
    int res = 0;
    for (Edge e : edges) {
        // 閉路にならないことをチェック
        if (!uf.isSameSet(e.from, e.to)) {
            uf.unionSet(e.from, e.to);
            res += e.cost;
        }
    }
    return res;
}


