        edges.push_back(Edge(xList[i].second, xList[i - 1].second, abs(xList[i - 1].first - xList[i].first)));
        edges.push_back(Edge(yList[i - 1].second, yList[i].second, abs(yList[i - 1].first - yList[i].first)));
        edges.push_back(Edge(yList[i].second, yList[i - 1].second, abs(yList[i - 1].first - yList[i].first)));
    }

    std::cout << kruskal(N, edges) << std::endl;
    return 0;
}

