using tp = std::tuple<int,int,int>;
class unionfind {
    std::vector<int> par, rank, size_;
public:
    unionfind(int n) :par(n), rank(n), size_(n, 1) {
        std::iota(par.begin(),par.end(), 0);
    }
    int find(int x) {
        if (par[x] == x)return x;
        return par[x] = find(par[x]);
    }
    void unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y)return;
        if (rank[x] < rank[y])std::swap(x, y);
        par[y] = x;
        size_[x] += size_[y];
        if (rank[x] == rank[y])rank[x]++;
    }
    bool same(int x, int y) {
        return find(x) == find(y);
    }
    int size(int x) {
        return size_[find(x)];
    }
};

int main(){
    int N;
    std::cin >> N;
    std::vector<tp>xst,yst;
    for(int idx = 0; idx < N; ++idx){
        int x,y; std::cin >> x >> y;
        xst.emplace_back(x,y,idx);
        yst.emplace_back(y,x,idx);
    }
    std::sort(xst.begin(), xst.end());
    std::sort(yst.begin(), yst.end());
    std::priority_queue<tp,std::vector<tp>,std::greater<>>que;
    for(int i = 0; i + 1 < xst.size(); ++i){
        int ax,ay,ai,bx,by,bi;
        std::tie(ax,ay,ai) = xst[i];
        std::tie(bx,by,bi) = xst[i + 1];
        que.emplace(std::abs(ax - bx),std::min(ai,bi),std::max(ai,bi));
    }
    for(int i = 0; i + 1 < yst.size(); ++i){
        int ax,ay,ai,bx,by,bi;
        std::tie(ay,ax,ai) = yst[i];
        std::tie(by,bx,bi) = yst[i + 1];
        que.emplace(std::abs(ay - by),std::min(ai,bi),std::max(ai,bi));
    }
    int edge = 0;
    long long sum = 0;
    auto uf = unionfind(N);
    while(edge < N - 1){
        int cost,i,j;
        std::tie(cost,i,j) = que.top();
        que.pop();
        if(not uf.same(i,j)){
            uf.unite(i, j);
            ++edge;
            sum += cost;
        }
    }
    std::cout << sum << std::endl;
}

