using namespace std;


vector<int> parent;
vector<int> tree_size;

void make_set(int i) {
	parent[i] = i;
	tree_size[i] = 1;
}

int find(int i) {
	while (parent[i] != i) {
		i = parent[i];
	}
	return i;
}

void union_tree(int i, int j) {
	i = find(i);
	j = find(j);
	if (tree_size[i] >= tree_size[j]) {
		parent[j] = i;
		tree_size[i] += tree_size[j];
	}
	else {
		parent[i] = j;
		tree_size[j] += tree_size[i];
	}
}

int main()
{
	int N;
	cin >> N;

	vector<pair<int, int>> X(N);
	vector<pair<int, int>> Y(N);
	parent = vector<int>(N);
	tree_size = vector<int>(N);


