		E.emplace_back(make_pair(value, make_pair(X[i].second, X[i + 1].second)));

		value = abs(Y[i].first - Y[i + 1].first);

		E.emplace_back(make_pair(value, make_pair(Y[i].second, Y[i + 1].second)));
	}

	sort(E.begin(), E.end());

	for (int i = 0; i < N; ++i) {
		make_set(i);
	}

	int total = 0;

	for (pair<int, pair<int, int>> e : E) {
		if (find(e.second.first) != find(e.second.second)) {
			union_tree(find(e.second.first), find(e.second.second));
			total += e.first;
		}
	}

	cout << total << endl;

	return 0;
}

