bool operator> (const edge &e1, const edge &e2) {  
  return e1.cost > e2.cost; 
}
bool operator< (const edge &e1, const edge &e2) {  
  return e1.cost < e2.cost; 
}

int N;
vector<pair<int, int>> px, py;
priority_queue<edge, vector<edge>, greater<edge>> pq;
long long ans = 0;

class UnionFind {  
public:
  vector<long long> par;
  vector<long long> rank;

  UnionFind(long long N) : par(N + 1), rank(N + 1){
    for(int i = 0; i < N; i++){  
      par[i] = i;
      rank[i] = 1;
    }
  }

  long long root(long long x){  
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  long long size(long long x){  
    return rank[root(x)]; 
  }

  void unite(long long x, long long y){  
    long long rx = root(x); 
    long long ry = root(y);
    if (rx == ry) return;

    if(rank[rx] < rank[ry]){  
      par[rx] = ry; 
    } else{  
      par[ry] = rx;
      if(rank[rx] == rank[ry]) rank[rx]++; 
    }
  }

  bool same(long long x, long long y){  
    return root(x) == root(y); 
  }
};


int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout << setprecision(20) << fixed;
  cin >> N;
  UnionFind uf(N);
  for(int i = 0; i < N; i++){  
    int x, y;
    cin >> x >> y;
    px.push_back(make_pair(x, i));
    py.push_back(make_pair(y, i));
  }
  sort(px.begin(), px.end());
  sort(py.begin(), py.end());
  for(int i = 0; i < N-1; i++){  
    edge x = {px[i+1].first - px[i].first, px[i].second, px[i+1].second};
    edge y = {py[i+1].first - py[i].first, py[i].second, py[i+1].second};
    pq.push(x);
    pq.push(y);
  }
  for(int i = 0; i < 2 * (N - 1); i++){  
    edge e = pq.top(); 
    pq.pop();
    if(!uf.same(e.to, e.from)){  
      ans += e.cost;
      uf.unite(e.to, e.from);
    }
  }
  cout << ans <<endl;
}

