	REP(i, n-1){
		edge e;
		e.u=x[i];
		e.v=x[i+1];
		e.cost=e.v.first-e.u.first;
		es[i]=e;
	}
	sort(y, y+n);
	REP(i, n-1){
		edge e;
		e.u=y[i];
		e.v=y[i+1];
		e.cost=e.v.first-e.u.first;
		es[n-1+i]=e;
	}
