bool cmpx(const posi_t& left, const posi_t& right) {
    return left.x < right.x;
}
bool cmpy(const posi_t& left, const posi_t& right) {
    return left.y < right.y;
}

priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
void prim(ll& ans, vector<bool>& visit) {
    while (!pq.empty()) {
        pair<int, int> x = pq.top();
        pq.pop();
        if (!visit[x.second])ans += (ll)x.first;
        visit[x.second] = true;

        //cout << x.second << "ans=" << ans << endl;
        for (auto ed : node[x.second].edge) {
            if (visit[ed.second]) continue;
            pq.push(ed);
        }
    }
}

