    sort(posi.begin(), posi.end(), cmpx);
    for (int i = 0; i < N - 1; i++) {
        int cost = posi[i + 1].x - posi[i].x;
        node[posi[i].id].edge.push_back(make_pair(cost, posi[i + 1].id));
