        }
    }

    // cerr << "get tree" << endl;
    sort(ALL(edges));
    vector<edge> tree;

    for(edge e: edges) {
        if(!uf.issame(e.from, e.to)) {
            uf.merge(e.from, e.to);
            tree.push_back(e);
        }
    }

    ll ans = 0;
    for(edge e: tree) {
        ans += e.d;
    }

    cout << ans << endl;

    return 0;
}

