struct UnionFind{
    vector<int32> par;
    UnionFind(int32 n){
        REP(i,n)par.pb(i);
    }
    int32 root(int32 x){
        if(par[x] == x)return x;
        return par[x] = root(par[x]);
    }
    void unite(int32 a, int32 b){
        a = root(a);
        b = root(b);
        if(a == b)return;
        par[a] = b;
    }
    bool same(int32 a, int32 b){
        return root(a) == root(b);
    }
};

