struct Sieve
{
  int n;
  vector<int> f, primes;
  Sieve(int n = 1) : n(n), f(n + 1)
  {
    f[0] = f[1] = -1;
    for (ll i = 2; i <= n; ++i)
    {
      if (f[i])
        continue;
      primes.push_back(i);
      f[i] = i;
      for (ll j = i * i; j <= n; j += i)
      {
        if (!f[j])
          f[j] = i;
      }
    }
  }
  bool isPrime(int x) { return f[x] == x; }
  vector<int> factorList(int x)
  {
    vector<int> res;
    while (x != 1)
    {
      res.push_back(f[x]);
      x /= f[x];
    }
    return res;
  }
  vector<P> factor(int x)
  {
    vector<int> fl = factorList(x);
    if (fl.size() == 0)
      return {};
    vector<P> res(1, P(fl[0], 0));
    for (int p : fl)
    {
      if (res.back().first == p)
      {
        res.back().second++;
      }
      else
      {
        res.emplace_back(p, 1);
      }
    }
    return res;
  }
};
struct UnionFind
{
  vector<int> par;
  UnionFind(int N) : par(N)
  {
    for (int i = 0; i < N; i++)
      par[i] = i;
  }
  int root(int x)
  {
    if (par[x] == x)
      return x;
    return par[x] = root(par[x]);
  }
  void unite(int x, int y)
  {
    int rx = root(x);
    int ry = root(y);
    if (rx == ry)
      return;
    par[rx] = ry;
  }
  bool same(int x, int y)
  {
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }
};
struct mint
{
  ll x; // typedef long long ll;
  mint(ll x = 0) : x((x % mod + mod) % mod) {}
  mint operator-() const { return mint(-x); }
  mint &operator+=(const mint a)
  {
    if ((x += a.x) >= mod)
      x -= mod;
    return *this;
  }
  mint &operator-=(const mint a)
  {
    if ((x += mod - a.x) >= mod)
      x -= mod;
    return *this;
  }
  mint &operator*=(const mint a)
  {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const
  {
    mint res(*this);
    return res += a;
  }
  mint operator-(const mint a) const
  {
    mint res(*this);
    return res -= a;
  }
  mint operator*(const mint a) const
  {
    mint res(*this);
    return res *= a;
  }
  mint pow(ll t) const
  {
    if (!t)
      return 1;
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1)
      a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const
  {
    return pow(mod - 2);
  }
  mint &operator/=(const mint a)
  {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const
  {
    mint res(*this);
    return res /= a;
  }
};
struct combination
{
  vector<mint> fact, ifact;
  combination(int n) : fact(n + 1), ifact(n + 1)
  {
    assert(n < mod);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
      fact[i] = fact[i - 1] * i;
    ifact[n] = fact[n].inv();
    for (int i = n; i >= 1; --i)
      ifact[i - 1] = ifact[i] * i;
  }
  mint operator()(int n, int k)
  {
    if (k < 0 || k > n)
      return 0;
    return fact[n] * ifact[k] * ifact[n - k];
  }
};

int cost(pair<int, int> a, pair<int, int> b) {
  return min(abs(a.first - b.first), abs(a.second - b.second));
}

int main()
{
  int n;
  cin >> n;
  vector<P> xe, ye;
  vector<P> node;
  //<座標、番号>
  rep(i, n) {
    int x, y;
    cin >> x >> y;
    xe.emplace_back(x, i);
    ye.emplace_back(y, i);
    node.emplace_back(x, y);
  }
  sort(ALL(xe));
  sort(ALL(ye));

  vector<priority_queue<P, vector<P>, greater<P>>> E(n);
  rep(i, n-1) {
    auto now = xe[i];
    auto next = xe[i+1];
    int start = now.second;
    int to = next.second;
    int cost = next.first - now.first;
    E[start].push(make_pair(cost, to));
    E[to].push(make_pair(cost, start));
  }
  rep(i, n-1) {
    auto now = ye[i];
    auto next = ye[i+1];
    int start = now.second;
    int to = next.second;
    int cost = next.first - now.first;
    E[start].push(make_pair(cost, to));
    E[to].push(make_pair(cost, start));
  }
  vector<int> V_new;
  vector<P> E_new;
  V_new.push_back(0);
  vector<bool> isVisit(n, false);
  isVisit[0] = true;

  while(V_new.size() != n) {

    int min_cost = INF;
    pair<int, int> min_e;
    vector<vector<P>> save(n);

    for(auto u : V_new) {
      pair<int, int> v;
      while(E[u].size()) {
        v = E[u].top(); E[u].pop();
        save[u].push_back(v);
        if(!isVisit[v.second]) break;
      }
      if(min_cost > v.first) {
        min_cost = v.first;
        min_e = make_pair(u, v.second);
      }
    }

    rep(i, n) rep(j, save[i].size()) E[i].push(save[i][j]);
    V_new.push_back(min_e.second);
    isVisit[min_e.second] = true;
    E_new.push_back(min_e);
  }
  ll ans = 0ll;
  for(auto e : E_new) {
    ans += (ll)cost(node[e.first], node[e.second]);
  }
  cout << ans << endl;
}

