typedef long long ll;
typedef pair<pair<ll, ll>, ll> P;		//from, to, cost

int main(){
	vector<P> v;
	ll n; cin >> n;
	vector< pair<ll, ll> > vx, vy;
	for(ll i = 0; i < n; ++i){
		ll x, y; cin >> x >> y; --x; --y;
		vx.push_back(pair<ll, ll>(x, i));
		vy.push_back(pair<ll, ll>(y, i));
	}
	bool used[n] = {0};
	sort(vx.begin(), vx.end());
	sort(vy.begin(), vy.end());
	for(ll i = 0; i < vx.size() - 1; ++i){
		P p;
		p.first = pair<ll, ll>(vx[i].second, vx[i + 1].second);
		p.second = vx[i + 1].first - vx[i].first;
		v.push_back(p);
		p.first = pair<ll, ll>(vy[i].second, vy[i + 1].second);
		p.second = vy[i + 1].first - vy[i].first;
		v.push_back(p);
	}
	vector< pair<ll, ll> > lis[n];
	for(int i = 0; i < v.size(); ++i){
		lis[v[i].first.first].push_back(pair<ll, ll>(v[i].second, v[i].first.second));
		lis[v[i].first.second].push_back(pair<ll, ll>(v[i].second, v[i].first.first));
	}

	ll ans = 0;
	priority_queue<pair<ll, ll> , vector< pair<ll, ll> >, greater< pair<ll, ll> > > q;
	q.push(pair<ll, ll>(0, 0));

	while(!q.empty()){
		pair<ll, ll> p = q.top(); q.pop();
		if(used[p.second]) continue;
		used[p.second] = 1;
		ans += p.first;
		for(pair<ll, ll> u : lis[p.second]){
			if(!used[u.second]) q.push(u);
		}
	}

	cout << ans << endl;
	return 0;
}

