typedef long long ll;
const ll MAX_V = 100000;
ll V,Par[MAX_V],Rank[MAX_V] = {};
void init(ll n){
  for(ll i=0;i<n;i++) Par[i] = i;
}
ll find(ll x){
  if(x == Par[x]) return x;
  else return Par[x] = find(Par[x]);
}
void unite(ll x,ll y){
  x = find(x);y = find(y);
  if(x == y) return;
  if(Rank[x] < Rank[y]) swap(x,y);
  Par[y] = x;
  if(Rank[x] == Rank[y]) Rank[x]++;
}
bool same(ll x,ll y){
  return find(x) == find(y);
}
bool priY(const pair<pair<ll,ll>,ll> &l,const pair<pair<ll,ll>,ll> &r){
  return l.first.second < r.first.second;
}
int main(){
  ll i,ans = 0;scanf("%lld",&V);
  pair<pair<ll,ll>,ll> P[V];pair<ll,pair<ll,ll>> Dis[V*2-2];
  init(V);
  for(i=0;i<V;i++){
    scanf("%lld%lld",&P[i].first.first,&P[i].first.second);
    P[i].second = i;
  }
  sort(P,P+V);
  for(i=0;i<V-1;i++){
    Dis[i].first = P[i+1].first.first-P[i].first.first;
    Dis[i].second.first = P[i].second;
    Dis[i].second.second = P[i+1].second;
  }
  sort(P,P+V,priY);
  for(i=0;i<V-1;i++){
    Dis[i+V-1].first = P[i+1].first.second-P[i].first.second;
    Dis[i+V-1].second.first = P[i].second;
    Dis[i+V-1].second.second = P[i+1].second;
  }
  sort(Dis,Dis+V*2-2);
  for(i=0;i<V*2-2;i++){
    if(!same(Dis[i].second.first,Dis[i].second.second)){
      ans += Dis[i].first;
      unite(Dis[i].second.first,Dis[i].second.second);
    }
  }
  printf("%lld\n",ans);
  return 0;
}

