    rep(i, n) {
        int x, y; cin >> x >> y;
        X.push_back(make_pair(x, i));
        Y.push_back(make_pair(y, i));
    }
    sort(X.begin(), X.end());
    sort(Y.begin(), Y.end());
    rep(i, n-1) {
        int u = X[i].second;
        int v = X[i+1].second;
        int cost = X[i+1].first - X[i].first;
        graph.push_back(edge(u, v, cost));
    }
    rep(i, n-1) {
        int u = Y[i].second;
        int v = Y[i+1].second;
        int cost = Y[i+1].first - Y[i].first;
        graph.push_back(edge(u, v, cost));
    }

    sort(graph.begin(), graph.end(), compare);

    UnionFind uf(n);
