//Initialize UFDS
int parent[100005], sz[100005];
void init(int n) {
	for (int i = 0; i <= n; i++) {
		parent[i] = i;
		sz[i] = 1;}}
int find(int x) {
	if (parent[x] == x) {
		return x;} 
  else {
		parent[x] = find(parent[x]);
		return parent[x];}}
void merge(int x, int y) {
	x = find(x);
	y = find(y);
	if (sz[x] < sz[y]) {
		parent[x] = y; sz[y] += sz[x];} 
  else {parent[y] = x; sz[x] += sz[y];
   sz[y] += sz[x];}}

//Main Program
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  deque <pair<long long, long long>> xlist, ylist;
  deque <deque<long long>> G;
  pair <long long, long long> xample, yample; set <long long> set1;
  long long N, xa, ya, cost=0, W, A, B; cin >> N;
  for (long long i=1; i<=N; i++){
    cin >> xa >> ya;
    xample = make_pair(xa,i); yample = make_pair(ya,i);
    xlist.push_back(xample); ylist.push_back(yample);}
  sort(xlist.begin(), xlist.end()); sort(ylist.begin(), ylist.end());

  //Kruskal's Algorithm
  for (long long i=0; i<N-1; i++) {
		deque<long long> x_edge;
		x_edge.push_back(xlist[i+1].first - xlist[i].first);
		x_edge.push_back(xlist[i].second);
		x_edge.push_back(xlist[i+1].second);
		G.push_back(x_edge);
		deque<long long> y_edge;
		y_edge.push_back(ylist[i+1].first - ylist[i].first);
		y_edge.push_back(ylist[i].second);
		y_edge.push_back(ylist[i+1].second);
		G.push_back(y_edge);}
  sort(G.begin(), G.end()); init(N);

  for (int i = 0; i < G.size(); i++) {
    W=G[i][0], A=G[i][1], B=G[i][2];
    if (find(A)!= find(B)){
      merge(A,B); cost+=W;}}
  cout << cost;}

