  friend bool operator<(const edge_t &lhs, const edge_t &rhs) {
    return lhs.w < rhs.w;
  }
};
int main() {
  int n;
  cin >> n;
  vector<pair<int,int>> pts(n);
  for (auto &p : pts) cin >> p.first >> p.second;
  sort(pts.begin(), pts.end());
  pts.resize(unique(pts.begin(), pts.end()) - pts.begin());
  n = pts.size();
  int64_t cost = 0;
  vector<int> p(n, -1), r(n, 1);
  function<int(int)> find = [&](int x) {
    if (p[x] == -1) return x;
    return p[x] = find(p[x]);
  };
  auto merge = [&](int x, int y) {
    int xg = find(x), yg = find(y);
    if (xg == yg) return false;
    if (r[xg] < r[yg]) {
      p[xg] = yg;
    } else if (r[xg] > r[yg]) {
      p[yg] = xg;
    } else {
      r[xg] += 1;
      p[yg] = xg;
    }
    return true;
  };
  vector<edge_t> edges;
  {
    for (int i = 1; i < n; ++i) {
      edges.emplace_back(i - 1, i, pts[i].first - pts[i - 1].first);
    }
    auto vt = pts;
    sort(vt.begin(), vt.end(), [&](pair<int, int> lhs, pair<int, int> rhs) {
      return make_pair(lhs.second, lhs.first) < make_pair(rhs.second, rhs.first);
    });
    for (int i = 1; i < n; ++i) {
      int u = lower_bound(pts.begin(), pts.end(), vt[i]) - pts.begin();
      int v = lower_bound(pts.begin(), pts.end(), vt[i - 1]) - pts.begin();
      edges.emplace_back(v, u, vt[i].second - vt[i - 1].second);
    }
  }
  sort(edges.begin(), edges.end());
  for (auto &[u, v, w] : edges) {
    if (merge(u, v)) {
      cost += w;
    }
  }
  cout << cost << '\n';
  return 0;
}

