    ll cost;
};
using Graph = vector<vector<edge>>;
// <最短距離, 頂点の番号>
using P = pair<ll, ll>;

int seen[MAX];


//対象の頂点からのびる辺を調べていって，一番小さいものを全域木に追加する．
//もう訪れていた場合は追加しない．
ll prim(const Graph &G, ll N, ll s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(seen, seen+N, 0);
    seen[s] = 0;
    que.push(P(0, s));
    ll total = 0;

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        ll v = p.second;
        if( seen[v] == 1 ) continue;
        total += p.first;
        seen[v] = 1;
        for (ll i=0; i<G[v].size(); ++i) {
            edge e = G[v][i];
            que.push(P(e.cost, e.to));
        }
    }

    return total;
}



