class Solution {
public:
    void solve(std::istream& in, std::ostream& out) {
        int n;
        in >> n;
        vt.clear();
        vt.resize(n);
        rep(i, n) {
            in >> vt[i].x >> vt[i].y;
            vt[i].idx = i;
        }

        es.clear();
        uf.init(n);
        sort(vt.begin(), vt.end(), compX);
        int c;
        edge e;
        rep(i, n - 1) {
            e.from = vt[i + 0].idx;
            e.to = vt[i + 1].idx;
            e.cost = cost(vt[i + 0], vt[i + 1]);
            es.push_back(e);
        }

        sort(vt.begin(), vt.end(), compY);
        rep(i, n - 1) {
            e.from = vt[i + 0].idx;
            e.to = vt[i + 1].idx;
            e.cost = cost(vt[i + 0], vt[i + 1]);
            es.push_back(e);
        }

        sort(es.begin(), es.end(), compCost);

        ll res = 0;
        each(it, es) {
            if (!uf.same(it->to, it->from))
            {
                uf.unite(it->to, it->from);
                res += it->cost;
            }
        }

        out << res << endl;
    }
};

