struct mint
{
  ll x; // typedef long long ll;
  mint(ll x = 0) : x((x % mod + mod) % mod) {}
  mint operator-() const { return mint(-x); }
  mint &operator+=(const mint a)
  {
    if ((x += a.x) >= mod)
      x -= mod;
    return *this;
  }
  mint &operator-=(const mint a)
  {
    if ((x += mod - a.x) >= mod)
      x -= mod;
    return *this;
  }
  mint &operator*=(const mint a)
  {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const
  {
    mint res(*this);
    return res += a;
  }
  mint operator-(const mint a) const
  {
    mint res(*this);
    return res -= a;
  }
  mint operator*(const mint a) const
  {
    mint res(*this);
    return res *= a;
  }
  mint pow(ll t) const
  {
    if (!t)
      return 1;
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1)
      a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const
  {
    return pow(mod - 2);
  }
  mint &operator/=(const mint a)
  {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const
  {
    mint res(*this);
    return res /= a;
  }
};
struct combination
{
  vector<mint> fact, ifact;
  combination(int n) : fact(n + 1), ifact(n + 1)
  {
    assert(n < mod);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
      fact[i] = fact[i - 1] * i;
    ifact[n] = fact[n].inv();
    for (int i = n; i >= 1; --i)
      ifact[i - 1] = ifact[i] * i;
  }
  mint operator()(int n, int k)
  {
    if (k < 0 || k > n)
      return 0;
    return fact[n] * ifact[k] * ifact[n - k];
  }
};

ll cost(pair<ll, ll> a, pair<ll, ll> b) {
  return min(abs(a.first - b.first), abs(a.second - b.second));
}

int main()
{
  int n;
  cin >> n;
  vector<pair<ll, ll>> xe, ye;
  vector<pair<ll, ll>> p(n);
  rep(i, n) {
    ll x, y;
    cin >> x >> y;
    xe.emplace_back(x, i);
    ye.emplace_back(y, i);
    p[i] = make_pair(x, y);
  }
  sort(ALL(xe));
  sort(ALL(ye));

  vector<vector<edge>> e(n);
  rep(i, n-1) {
    auto now = xe[i];
    auto next = xe[i+1];
    ll cost = next.first - now.first;
    e[now.second].push_back({(int)next.second, cost});
    e[next.second].push_back({(int)now.second, cost});
  }
  rep(i, n-1) {
    auto now = ye[i];
    auto next = ye[i+1];
    ll cost = next.first - now.first;
    e[now.second].push_back({(int)next.second, cost});
    e[next.second].push_back({(int)now.second, cost});
  }

  vector<int> new_v;
  vector<pair<int, int>> new_e;

  new_v.push_back(0);
  vector<bool> isVisit(n, false);
  isVisit[0] = true;

  while(new_v.size() != n) {
    ll min_cost = INF64;
    pair<int, int> min_e;

    for(auto u : new_v) {
      for(auto v : e[u]) {
        if(isVisit[v.to]) continue;
        if(min_cost > v.cost) {
          min_cost = v.cost;
          min_e = make_pair(u, v.to);
        }
      }
    }
    new_v.push_back(min_e.second);
    new_e.push_back(min_e);
    isVisit[min_e.second] = true;
  }
  ll ans = 0ll;
  for(auto x : new_e) {
    ans += cost(p[x.first], p[x.second]);
  }
  cout << ans << endl;
}

