        return cost < o.cost;//costの大小で順序を定義
    }
};

struct Graph{
    int n;
    vector<Edge> es; //辺の集合

    //クラスカル法で無向最小全域木のコストの和を計算する
    //グラフが非連結の場合最小全域森のコストの和
    int kruskal(){
        sort(es.begin(),es.end());//コストが小さい順に採用
        UnionFind uf(n);
        int min_cost = 0;
        rep(ei,es.size()){
            Edge& e = es[ei];
            if(!uf.same(e.a,e.b)){//辺を追加して閉路が出来なければ辺を採用
                min_cost += e.cost;
                uf.merge(e.a,e.b);
            }
        }
        return min_cost;
    }


};

