struct UnionFind {
  vector< int > par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2
  vector< int > siz;
  int parsize;

  UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
    for (int i = 0; i < N; i++)
      par[i] = i;
    siz.assign(N, 1);
    parsize = N;
  }

  int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
    if (x < 0 || parsize <= x)
      return -1;
    if (par[x] == x)
      return x;
    return par[x] = root(par[x]);
  }

  bool unite(int x, int y) { // xとyの木を併合
    if (x < 0 || parsize <= x || y < 0 || parsize <= y)
      return false;
    int rx = root(x); // xの根をrx
    int ry = root(y); // yの根をry
    if (rx == ry)
      return false; // xとyの根が同じ(=同じ木にある)時はそのまま
    if (siz[x] < siz[y])
      swap(x, y);
    siz[x] += siz[y];
    par[ry] =
        rx; // xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    return true;
  }

  bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
    if (x < 0 || parsize <= x || y < 0 || parsize <= y)
      return false;
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }
  int size(int x) { return (x < 0 || parsize <= x) ? -1 : siz[root(x)]; }
};
