using namespace std;

struct vertex {
    int x, y, index;
};

struct edge {
    int from, to, cost;
};

bool vcomp_x(const vertex &v1, const vertex &v2){
    return v1.x < v2.x;
}
bool vcomp_y(const vertex &v1, const vertex &v2){
    return v1.y < v2.y;
}

int main(int argc, char** argv){
    int N;
    cin >> N;
    vector<vertex> vs(N);
    vector<vector<edge>> es(N, vector<edge>());
    for (int i=0; i<N; i++){
        cin >> vs[i].x >> vs[i].y;
        vs[i].index = i;
    }

    sort(vs.begin(), vs.end(), vcomp_x);
    for (int i=1; i<N; i++){
        edge e1, e2;
        int ix1 = vs[i-1].index, ix2 = vs[i].index;
        e1.from = ix1; e1.to = ix2; e1.cost = vs[i].x - vs[i-1].x;
        e2.from = ix2; e2.to = ix1; e2.cost = vs[i].x - vs[i-1].x;
        es[ix1].push_back(e1);
        es[ix2].push_back(e2);
    }

    sort(vs.begin(), vs.end(), vcomp_y);
    for (int i=1; i<N; i++){
        edge e1, e2;
        int ix1 = vs[i-1].index, ix2 = vs[i].index;
        e1.from = ix1; e1.to = ix2; e1.cost = vs[i].y - vs[i-1].y;
        e2.from = ix2; e2.to = ix1; e2.cost = vs[i].y - vs[i-1].y;
        es[ix1].push_back(e1);
        es[ix2].push_back(e2);
    }

    auto comp_pq = [](edge &e1, edge &e2){
        return e1.cost > e2.cost;
    };
    priority_queue<edge, vector<edge>, decltype(comp_pq)> pq(comp_pq);

    int sum = 0;
    bool v_picked[N];
    for (int i=0; i<N; i++) v_picked[i] = false;
    v_picked[0] = true;
    for (auto itr = es[0].begin(); itr != es[0].end(); itr++)
        pq.push(*itr);
    for (int i=1; i<N; i++){
        edge e;
        while (1){
            e = pq.top();
            pq.pop();
            if (!v_picked[e.to]) break;
        }
        sum += e.cost;
        v_picked[e.to] = true;
        for (auto itr = es[e.to].begin(); itr != es[e.to].end(); itr++)
            pq.push(*itr);
    }

    cout << sum << "\n";

    return 0;
}

