using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;
#define NODE_MAX 100001
int par[NODE_MAX],rk[NODE_MAX];
void init(){
  for(int i=0;i<NODE_MAX;i++){
    par[i]=i;
    rk[i]=0;
  }
}
int root(int x){
  if(x==par[x]) return x;
  return par[x]=root(par[x]);
}
void unite(int x,int y){
  x = root(x);
  y = root(y);
  if(x==y) return;

  if(rk[x]<rk[y]){
    par[x] = y;
  }else{
    par[y] = x;
    if(rk[x]==rk[y]) rk[x]++;
  }
}
bool same(int x,int y){
  return root(x)==root(y);
}
int main(){
  ll n,sum=0,tmp;
  cin >> n;
  ll x[n],y[n];
  P vx[n],vy[n];
  vector<P> xy;
  init();
  priority_queue<pair<ll,P>,vector<pair<ll,P>>,greater<pair<ll,P>>> que;
  for(ll i=0;i<n;i++){
    cin >> x[i] >> y[i];
    vx[i]=P(x[i],i);
    vy[i]=P(y[i],i);
    xy.push_back(P(x[i],y[i]));
  }
  sort(vx,vx+n);
  sort(vy,vy+n);
  for(int i=1;i<n;i++){
    tmp = min(vx[i].first-vx[i-1].first,
        abs(y[vx[i].second]-y[vx[i-1].second]));
    que.push(make_pair(tmp,P(vx[i].second,vx[i-1].second)));

    tmp = min(vy[i].first-vy[i-1].first,
        abs(x[vy[i].second]-x[vy[i-1].second]));
    que.push(make_pair(tmp,P(vy[i].second,vy[i-1].second)));
  }
  while(!que.empty()){
    pair<ll,P> e = que.top(); que.pop();
    if(!same(e.second.first,e.second.second)){
      unite(e.second.first,e.second.second);
      sum+=e.first;
    }
  }
  cout <<sum<<endl;
}

