    vector<Edge> edges (2*N-2);
    vector<P> A(N);
    vector<P> B(N);
    for(int i = 0; i < N; i++) {
        A[i].first = B[i].first = i;
        cin >> A[i].second >> B[i].second;
    }


    sort(A.begin(), A.end(), pairCompare);
    sort(B.begin(), B.end(), pairCompare);
    int cnt = 0;

    for(int i = 0; i < N-1; i++){
        edges[cnt].source = A[i].first;
        edges[cnt].target = A[i+1].first;
        edges[cnt].cost = A[i+1].second - A[i].second;
        cnt++;
    }


    for(int i = 0; i < N-1; i++){
        edges[cnt].source = B[i].first;
        edges[cnt].target = B[i+1].first;
        edges[cnt].cost = B[i+1].second - B[i].second;
        cnt++;
    }


    cout << kruskal(2*N-2, edges) << endl;
}

