  for (int i = 0; i < n; ++i) {
    vx.emplace_back(x[i], i);
    vy.emplace_back(y[i], i);
  }

  sort(vx.begin(), vx.end()); sort(vy.begin(), vy.end());

  vector<bridge> v;
  UnionFind uf(n);

  for (int i = 0; i < n - 1; ++i) {
    v.push_back({vx[i + 1].first - vx[i].first, vx[i].second, vx[i + 1].second});
    v.push_back({vy[i + 1].first - vy[i].first, vy[i].second, vy[i + 1].second});    
  }

  sort(v.begin(), v.end(), [](const bridge& x, const bridge& y){return x.cost < y.cost;});

  int64 ans = 0;

  for (int i = 0; i < 2 * (n - 1); ++i) {
    if (uf.issame(v[i].from, v[i].to)) continue;
    uf.unite(v[i].from, v[i].to);
    ans += v[i].cost;
  }
  print(ans);

  return 0;
}

