#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef tuple<ll,pair<ll,ll>,pair<ll,ll>> edge;
typedef priority_queue<edge,vector<edge>,greater<edge>> min_heap;
typedef multiset<pair<ll,ll>> points;
void process(points &a, points &b, points &c, points &d, pair<ll,ll> p, min_heap &h) {
  ll x1,x2,x3,x4;
  auto p1 = a.lower_bound(p);
  if (p1 != a.end()) {
    x1 = abs(p.first-p1->first);
  } else {
    x1 = LLONG_MAX;
  }
  auto p2 = b.lower_bound({-p.first,p.second});
  if (p2 != b.end()) {
    x2 = abs(p.first+p2->first);
  } else {
    x2 = LLONG_MAX;
  }
  auto p3 = c.lower_bound({p.second,p.first});
  if (p3 != c.end()) {
    x3 = abs(p.second-p3->first);
  } else {
    x3 = LLONG_MAX;
  }
  auto p4 = d.lower_bound({-p.second,p.first});
  if (p4 != d.end()) {
    x4 = abs(p.second+p4->first);
  } else {
    x4 = LLONG_MAX;
  }
  if (min(min(x1,x2),min(x3,x4)) == x1) {
    h.push(make_tuple(x1,p,*p1));
  } else if (min(min(x1,x2),min(x3,x4)) == x2) {
    h.push(make_tuple(x2,p,make_pair(-p2->first,p2->second)));
  } else if (min(min(x1,x2),min(x3,x4)) == x3) {
    h.push(make_tuple(x3,p,make_pair(p3->second,p3->first)));
  } else {
    h.push(make_tuple(x4,p,make_pair(p4->second,-p4->first)));
  }
}
int main() {
  ll N,x,y,answer=0;
  points a,b,c,d;
  for (cin >> N; N; N--) {
    cin >> x >> y;
    a.insert({x,y});
    b.insert({-x,y});
    c.insert({y,x});
    d.insert({-y,x});
  }
  min_heap h;
  pair<ll,ll> p = *a.begin(), q;
  a.erase(a.find(p));
  b.erase(b.find({-p.first,p.second}));
  c.erase(c.find({p.second,p.first}));
  d.erase(d.find({-p.second,p.first}));
  process(a,b,c,d,p,h);
  while (!a.empty()) {
    if (a.find(get<2>(h.top())) != a.end()) {
      answer += get<0>(h.top());
      p = get<1>(h.top());
      q = get<2>(h.top());
      h.pop();
      a.erase(a.find(q));
      b.erase(b.find({-q.first,q.second}));
      c.erase(c.find({q.second,q.first}));
      d.erase(d.find({-q.second,q.first}));
      process(a,b,c,d,p,h);
      process(a,b,c,d,q,h);
    } else {
      p = get<1>(h.top());
      q = get<2>(h.top());
      h.pop();
      process(a,b,c,d,p,h);
      process(a,b,c,d,q,h);
    }
  }
  cout << answer;
}

