int par[100010];
int r[100010];

struct memo{
  int x,y,num;
};

struct route{
  int from,to,cost;
};

bool cmp_x(const memo& a, const memo& b){
  return a.x < b.x;
}

bool cmp_y(const memo& a, const memo& b){
  return a.y < b.y;
}

bool cmp(const route& a, const route& b){
  return a.cost < b.cost;
}

void init(int n){
  for(int i=0;i<n;i++){
    par[i]=i;
    r[i]=0;
  }
}

int root(int n){
  if(par[n]==n){
    return n;
  }
  return par[n]=root(par[n]);
}

void unite(int x,int y){
  int rx=root(x), ry=root(y);
  if(rx==ry) return;
  if(r[rx]<r[ry]) par[rx]=ry;
  else{
    par[ry]=rx;
    if(r[rx]==r[ry]) r[rx]++;
  }
  return;
}

bool same(int x,int y){
  return root(x)==root(y);
}

int main() {
  int n;
  cin>>n;
  memo p[n];
  for(int i=0;i<n;i++){
    memo m;
    int x,y;
    cin>>x>>y;
    m.x=x,m.y=y,m.num=i;
    p[i]=m;
  }
  route ans[2*(n-1)];
  sort(p,p+n,cmp_x);
  for(int i=0;i<n-1;i++){
    route r1;
    r1.from=p[i].num,r1.to=p[i+1].num,r1.cost=abs(p[i+1].x-p[i].x);
    ans[i]=r1;
  }
  sort(p,p+n,cmp_y);
  for(int i=0;i<n-1;i++){
    route r1;
    r1.from=p[i].num,r1.to=p[i+1].num,r1.cost=abs(p[i+1].y-p[i].y);
    ans[n-1+i]=r1;
  }
  sort(ans,ans+2*(n-1),cmp);
  ll res=0;
  init(n);
  for(int i=0;i<2*(n-1);i++){
    route e=ans[i];
    if(!same(e.from,e.to)){
      unite(e.from,e.to);
      res+=e.cost;
    }
  }
  cout<<res<<endl;
  return 0;
}

