// Kruskal algorithm: build minimum spanning tree

template <typename T>
struct Kruskal {
    struct edge {
        int from, to, used;
        T cost;
        edge(int from_, int to_, T cost_) : from(from_), to(to_), cost(cost_), used(0) {}
        bool operator<(const edge &e) const { return cost < e.cost; }
    };

    vector<int> rank, parent;
    vector<edge> es;
    Kruskal(int n) : rank(n + 1, 0), parent(n + 1) { iota(parent.begin(), parent.end(), 0); }
    // union-find methods
    int root(int x) {
        if (x != parent[x]) {
            parent[x] = root(parent[x]);
        }
        return parent[x];
    }
    bool isSame(int x, int y) { return root(x) == root(y); }
    bool unite(int x, int y) { return link(root(x), root(y)); }
    bool link(int x, int y) {
        if (x == y)
            return false;
        if (rank[x] > rank[y]) {
            parent[y] = x;
        } else {
            parent[x] = y;
            if (rank[x] == rank[y]) {
                rank[y]++;
            }
        }
        return true;
    }
    // Kruskal methods
    void addEdge(int f, int t, T c) { es.emplace_back(f, t, c); }
    T build() {
        sort(es.begin(), es.end());
        T res = 0;
        for (auto &e : es) {
            if (!isSame(e.from, e.to)) {
                res += e.cost;
                unite(e.from, e.to);
                e.used = 1;
            }
        }
        return res;
    }
};

int main() {
    int n;
    cin >> n;
    vector<ll> a(n), b(n);
    vector<pll> x(n), y(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i];
        x[i] = {a[i], i};
        y[i] = {b[i], i};
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());
    Kruskal<ll> kr(n);
    for (int i = 1; i < n; ++i) {
        int fx = x[i - 1].second;
        int tx = x[i].second;
        ll dx  = min(abs(a[fx] - a[tx]), abs(b[fx] - b[tx]));
        int fy = y[i - 1].second;
        int ty = y[i].second;
        ll dy  = min(abs(a[fy] - a[ty]), abs(b[fy] - b[ty]));
        kr.addEdge(fx, tx, dx);
        kr.addEdge(tx, fx, dx);
        kr.addEdge(fy, ty, dy);
        kr.addEdge(ty, fy, dy);
    }
    ll ret = kr.build();
    cout << ret << "\n";
    return 0;
}

