        edges.push_back(Edge(y[v]-y[u],pint(u,v)));
    }
    sort(edges.begin(),edges.end());
    UnionFind uf = UnionFind(n+1);
    ll res = 0;
    for(auto e:edges){
        int u = e.second.first,v = e.second.second;
        ll cost = e.first;
        if(uf.same(u,v))continue;
        uf.unite_node(u,v);
        res+=cost;
    }
    cout<<res<<endl;
}

