struct Path
{
    int from,to,cost;

    bool operator<(const Path& rhs)const
    {
        return cost<rhs.cost;
    }
};

struct UF
{
    vector<int> par;

    UF(int n):par(n)
    {
        for(int i=0;i<n;i++) par[i]=i;
    }

    int root(int x)
    {
        if(par[x]==x) return x;
        else          return par[x]=root(par[x]);
    }

    void unite(int x,int y)
    {
        int rx=root(x);
        int ry=root(y);

        par[rx]=ry;
    }

    bool same(int x,int y)
    {
        int rx=root(x);
        int ry=root(y);

        return rx==ry;
    }
};

int main()
{
