template <typename T>
using Graph = vector<vector<T>>;
const int MOD = 1e9 + 7;

ll prim(int s, const Graph<pii> &G) {
    int N = G.size();
    vector<bool> isused(N);
    priority_queue<pii, vector<pii>, greater<pii>> que;
    que.push({0, s});
    ll res = 0;
    while (!que.empty()) {
        int c = que.top().first;
        int v = que.top().second;
        que.pop();
        if (isused[v])
            continue;
        isused[v] = true;
        res += c;
        for (auto np : G[v]) {
            int nv = np.second;
            if (isused[nv])
                continue;
            que.push(np);
        }
    }
    return res;
}

