struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2
    vector<int> siz; 

    UnionFind(int N) : par(N),siz(N,1ll) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }
    void init(ll N) {
        par.resize(N);
        siz.assign(N, 1LL);  // resize だとなぜか初期化されなかった
        for (ll i = 0; i < N; ++i) par[i] = i; // 初期では親は自分自身
    }
    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
        if (siz[rx] < siz[ry]) swap(rx, ry);
        siz[rx] += siz[ry];
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
    int size(int x) { // 素集合のサイズ
        return siz[root(x)];
    }
};

struct edge{
    int from,to,dist;
    edge(int from,int to,int dist):
     from(from),to(to),dist(dist){}
};
struct Edge{
    int to,dist;
    Edge(int to,int dist):
     to(to),dist(dist){}
};
std::vector<vector<Edge>> ki;
std::vector<edge> g;
ll ans=0;
void Kruscal(int v,int e){
    //最小全域木 クラスカル法
    //UnionFindを忘れずにインクルードすること
    UnionFind u(v);
    ki.resize(v);
    priority_queue<P,std::vector<P>,greater<P>> q;
    rep(i,e){
        q.push(mp(g[i].dist,i));
    }
    rep(i,e){
        int p=q.top().se;
        if(!u.same(g[p].from,g[p].to)){
            u.unite(g[p].from,g[p].to);
            ki[g[p].from].pb(Edge(g[p].to,g[p].dist));
            ki[g[p].to].pb(Edge(g[p].from,g[p].dist));                                                                      
      //      ans+=g[p].dist;
        }
        q.pop();
    }
}

int main(){
