            if(j==i)continue;
            g.pb(edge(i,j,int( min(abs(x[i]-x[j]),abs(y[i]-y[j])) )));
        }
    }
    Kruscal(n,n*n-n);
    ll ans=0;
    rep(i,n){
        erep(j,ki[i]){
            if(j.to>i)ans+=j.dist;
        }
    }
