class DisjointSet {
    private:
    class Node {
        public: 
        int parent = -1;
        int rank = 0;
        int degree = 1;
    };

    Node *nodes;

    void make_set(int x) {
        ++count;
        nodes[x].parent = x;
        nodes[x].rank = 0;
        nodes[x].degree = 1;
    }

    public:
    int count = 0;

    DisjointSet(){}
    DisjointSet(int length) {
        nodes = (Node *)malloc(sizeof(Node) * length);
        for(int i = 0; i < length; ++i)
            make_set(i);
    }

    ~DisjointSet() {
        free(nodes);
    }

    int find_set(int x) {
        if(nodes[x].parent == x)
            return x;

        return nodes[x].parent = find_set(nodes[x].parent);
    }

    int get_degree(int x) {
        return nodes[find_set(x)].degree;
    }

    void unite(int x, int y) {
        int set_x = find_set(x);
        int set_y = find_set(y);
        if(set_x == set_y) return;
        --count;

        if(nodes[x].rank < nodes[y].rank) {
            nodes[set_x].parent = set_y;
            nodes[y].degree += nodes[x].degree;
        } else if(nodes[x].rank > nodes[y].rank) {
            nodes[set_y].parent = set_x;
            nodes[x].degree += nodes[y].degree;
        } else {
            nodes[set_y].parent = set_x;
            nodes[x].rank++;
            nodes[x].degree += nodes[y].degree;
        }
    }

    bool is_same(int x, int y) {
        int set_x = find_set(x);
        int set_y = find_set(y);
        return set_x == set_y;
    }
};

int kruskal() {
    llong res = 0;

    auto *dset = new DisjointSet(N);
    while(!edge_cost.empty()) {
        int cost = -get<0>(edge_cost.top());
        int st = get<1>(edge_cost.top());
        int ed = get<2>(edge_cost.top()); edge_cost.pop();

        if(!dset->is_same(st, ed)) {
            res += cost;
            dset->unite(st, ed);
        }

    }

    return res;
}

