int find(vector<int> &tab, int a){
    if(tab[a]==-1)return a;
    tab[a]=find(tab, tab[a]);
    return tab[a];
}

void merge(vector<int> &tab, int a, int b){
    auto pa=find(tab, a);
    auto pb=find(tab, b);
    if(pa!=pb)tab[pb]=pa;
}

void solve(long long N, std::vector<long long> x, std::vector<long long> y){
    vector<int> tab(N, -1);
    vector<pair<LL, LL>> arr(N);
    vector<pair<LL, pair<LL, LL>>> pairs;

    for(int i=0; i<N; i++)arr[i] = make_pair(x[i], i);
    sort(arr.begin(), arr.end());
    for(int i=1; i<N; i++)
        pairs.emplace_back(make_pair(arr[i].first-arr[i-1].first, make_pair(arr[i].second, arr[i-1].second)));

    for(int i=0; i<N; i++)arr[i] = make_pair(y[i], i);
    sort(arr.begin(), arr.end());
    for(int i=1; i<N; i++)
        pairs.emplace_back(make_pair(arr[i].first-arr[i-1].first, make_pair(arr[i].second, arr[i-1].second)));

    sort(pairs.begin(), pairs.end());
    LL ans=0;
