        cost = abs(y[i].first - y[i+1].first);
        edge y;
        y.cost = cost;
        y.next = next;
        y.now = now;
        e.push_back(y);
    }
    ll ans = 0;
    sort(ALL(e),cmp);
    for(int i=0;i<e.size();i++){
        int now = e[i].now;
        int next= e[i].next;
        ll cost = e[i].cost;
        if(uni.root(now)!=uni.root(next)){
            ans += cost;
            uni.unite(now,next);
        }
    }
    cout << ans << endl;
}

