const ll MAX = 200010;

class UnionFind
{
private:
    int par[MAX];
    int rank[MAX];
public:
    UnionFind(int N);
    int find(int x);
    void unite(int x, int y);
    bool same(int x, int y);
};

//コンストラクタ
UnionFind::UnionFind(int N)
{
    for(int i=0; i<N; i++)
    {
        par[i]=i;
        rank[i]=0;
    }
 }

//木の根を求める
int UnionFind::find(int x)
{
    if(par[x]==x)
    {
        return x;
    }
    else
    {
        return par[x]=find(par[x]);
    }
}
//位数の大きい木に統合する
void UnionFind::unite(int x, int y)
{
    x=find(x);
    y=find(y);

    if(x==y)
        return;

    if(rank[x] < rank[y])
    {
        par[x]=y;
    }
else
    {
        par[y]=x;

        if(rank[x]==rank[y])
        {
            rank[x]++;
        }
    }
}

//同じ根を持つならtrueを返す
bool UnionFind::same(int x, int y)
{
    return find(x)==find(y);
}

