    for (int j = i + 1; j < N; ++j) {
      LL d = min(
          abs(ps[i].first - ps[j].first),
          abs(ps[i].second - ps[j].second));
      es.push_back(Edge(i, j, d));
    }
  }

  cout << kruskal(N, es) << endl;
}

