struct UnionFind{
  vector<int> par;
  UnionFind(int n) : par(n, -1){}
  int root(int x){ return (par[x] < 0) ? x : par[x] = root(par[x]); }
  int size(int x){ return -par[root(x)]; }
  bool issame(int x, int y){ return root(x) == root(y); }
  void marge(int x, int y){
    x = root(x); y = root(y);
    if(x == y) return;
    if(x > y) swap(x, y);
    par[x] += par[y];
    par[y] = x;
  }
};

int main(void){
  ll n;
  cin >> n;
  map<P, ll> xmp, ymp;
  vector<P> xp(n), yp(n);
  vector<tuple<ll, ll, ll>> c;
  UnionFind uf(n);
  REP(i, n){
    ll x, y;
    cin >> x >> y;
    xp[i] = P(x, y);
    yp[i] = P(y, x);
    xmp[xp[i]] = i;
    xmp[yp[i]] = i;
  }
  sort(ALL(xp));
  sort(ALL(yp));
  auto cost = [](P a, P b){
    ll c = abs(a.first - b.first);
    ll d = abs(a.second - b.second);
    return min(c, d);
  };
  REP(i, n-1){
    ll p = xmp[xp[i]];
    ll q = xmp[xp[i+1]];
    c.emplace_back(cost(xp[i], xp[i+1]), p, q);
    p = ymp[yp[i]];
    q = ymp[yp[i+1]];
    c.emplace_back(cost(yp[i], yp[i+1]), p, q);
  }
  sort(ALL(c));
  ll ans = 0;
  ll m = c.size();
  for(ll i = 0; i < m && uf.size(0) != n; i++){
    ll d, p, q;
    tie(d, p, q) = c[i];
    if(uf.issame(p, q)) continue;
    uf.marge(p, q);
    ans += d;
  }
  cout << ans << endl;
  return 0;
}

