typedef long long ll;

const int INF = 1e9;
const ll LLINF = 1e18;
const ll MOD = (ll)1e9 + 7;

struct UF {
  vector<int> parent_, rank_;

  UF(int N) : parent_(N + 5), rank_(N + 5, 1) {
    for (int i = 0; i <= N; ++i) {
      parent_[i] = i;
    }
  }

  int find_set(int x) {
    if (x != parent_[x]) {
      parent_[x] = find_set(parent_[x]);
    }
    return parent_[x];
  }

  void unite(int x, int y) {
    int a = find_set(x), b = find_set(y);
    if (a == b) { return; }
    if (rank_[a] > rank_[b]) {
      parent_[b] = a;
    }
    else {
      parent_[a] = b;
      if (rank_[a] == rank_[b]) { ++rank_[b]; }
    }
  }

  bool is_connected(int x, int y) {
    return find_set(x) == find_set(y);
  }

};

int main()
{
  int N; scanf("%d", &N);
  vector<pair<ll, int>> X(N), Y(N);
  ll x, y;
  for (int i = 0; i < N; ++i) {
    scanf("%lld %lld", &x, &y);
    X[i] = make_pair(x, i);
    Y[i] = make_pair(y, i);
  }
  sort(X.begin(), X.end());
  sort(Y.begin(), Y.end());
  vector<pair<ll, pair<int, int>>> edges;
  for (int i = 0; i + 1 < N; ++i) {
    edges.push_back(make_pair(abs(X[i].first - X[i + 1].first),
                              make_pair(X[i].second, X[i + 1].second)));
    edges.push_back(make_pair(abs(Y[i].first - Y[i + 1].first),
                              make_pair(Y[i].second, Y[i + 1].second)));
  }

  sort(edges.begin(), edges.end());
  ll ans = 0;
  UF uf(N + 5);
  for (int i = 0; i < (int)edges.size(); ++i) {
    ll d = edges[i].first;
    int u = edges[i].second.first, v = edges[i].second.second;
    if (uf.is_connected(u, v)) { continue; }
    uf.unite(u, v);
    ans += d;
  }
  printf("%lld\n", ans);
  return 0;
}

