#define for2(i,m,n) for (ll (i)=(m);(i)<(n);(i)++)
#define for3(i,m,n,d) for (ll (i)=(m);(i)<(n);(i)+=(d))
#define INF (1LL << 60)

class UnionFind {
public:
    //親の番号を格納する。親だった場合は-(その集合のサイズ)
    vector<ll> Parent;

    //作るときはParentの値を全て-1にする
    //こうすると全てバラバラになる
    UnionFind(ll N) {
        Parent = vector<ll>(N, -1);
    }

    //Aがどのグループに属しているか調べる
    ll root(ll A) {
        if (Parent[A] < 0) return A;
        return Parent[A] = root(Parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    ll size(ll A) {
        return -Parent[root(A)];//親をとってきたいß
    }

    //AとBをくっ付ける
    bool connect(ll A, ll B) {
        //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        if (A == B) {
            //すでにくっついてるからくっ付けない
            return false;
        }

        //大きい方(A)に小さいほう(B)をくっ付けたい
        //大小が逆だったらひっくり返しちゃう。
        if (size(A) < size(B)) swap(A, B);

        //Aのサイズを更新する
        Parent[A] += Parent[B];
        //Bの親をAに変更する
        Parent[B] = A;

        return true;
    }
};

void solve()
{
    ll N;
    cin >> N;
    vector<pair<ll,ll>> sx;
    vector<pair<ll,ll>> sy;
    vector<tuple<ll,ll,ll>> dis;
    for1(i,N) {
        ll x,y;
        cin >> x >> y;
        sx.emplace_back(x,i);
        sy.emplace_back(y,i);
    }
    sort(sx.begin(),sx.end());
    sort(sy.begin(),sy.end());
    bool first = true;
    ll px = 0;
    ll py = 0;
    ll pi = 0;
    for (auto s : sx) {
        if (first) {
            first = false;
        } else {
            dis.emplace_back(s.first - px, pi, s.second);
        }
        px = s.first;
        pi = s.second;
    }
    first = true;
    for (auto s : sy) {
        if (first) {
            first = false;
        } else {
            dis.emplace_back(s.first - py, pi, s.second);
        }
        py = s.first;
        pi = s.second;
    }
    sort(dis.begin(),dis.end());

    ll rest = N - 1;
    UnionFind uni(N);
    ll ans = 0;
    for (auto item : dis) {
        if (rest == 0) break;
        ll d,a,b;
        tie(d,a,b) = item;
        if (uni.root(a) == uni.root(b)) continue;
        ans += d;
        uni.connect(a,b);
        --rest;
    }

    cout << ans << endl;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    solve();
}

