//union by size + path having
class UnionFind{
	public:
	vector<long long> par; // 各元の親を表す配列
	vector<long long> siz; // 素集合のサイズを表す配列(1 で初期化)


	// Constructor
	UnionFind(long long sz_) : par(sz_), siz(sz_,1LL){
		for (long long i = 0; i < sz_; ++i)
		par[i] = i; // 初期では親は自分自身
	}
	void init(long long sz_){
		par.resize(sz_);
		siz.assign(sz_,1LL); // resize だとなぜか初期化されなかった
		for (long long i = 0; i < sz_; ++i)
			par[i] = i; // 初期では親は自分自身
	}
	// Member Function


	// Find
	long long root(long long x){ // 根の検索
		while (par[x] != x){
			x = par[x] = par[par[x]]; // x の親の親を x の親とする
		}
		return x;
	}
	// 結合(Unite, Merge)
	bool merge(long long x, long long y){
		x = root(x);
		y = root(y);
		if (x == y){
			return false;
		}
		// merge technique（データ構造をマージするテク．小を大にくっつける）
		if (siz[x] < siz[y]){
			swap(x, y);
		}
		siz[x] += siz[y];
		par[y] = x;
		return true;
	}


	// 連結判定(つながっているときはture,つながっていなければfalse)
	bool issame(long long x, long long y){ 
		return root(x) == root(y);
	}


	// 素集合のサイズ
	long long size(long long x){ 
		return siz[root(x)];
	}
};
//クラスカル法(隣接リストから最小全域木を隣接リストで返す)
//計算量 (辺)log(頂点)
vector<vector<pair<int, long long>>>Kruskal(vector<vector<pair<int,long long>>>pathlist){
	vector<pair<long long, pair<int, int>>> paths;
	int edge=pathlist.size();
	UnionFind conect(edge);
	vector<vector<pair<int, long long>>> res(edge);
	rep(i, edge){
		for (auto itr = pathlist[i].begin(); itr != pathlist[i].end(); itr++){
			paths.emplace_back(itr->second, make_pair(i, itr->first));
		}
	}
	sort(paths.begin(),paths.end());
	for (auto at = paths.begin(); at != paths.end(); at++){
		if (conect.merge(at->second.first, at->second.second)){
			res[at->second.first].emplace_back(at->second.second, at->first);
			res[at->second.second].emplace_back(at->second.first, at->first);
			if (conect.size(0) == edge){
				break;
			}
		}
	}
	return res;
}
