//------------------------------------------------------------
struct UnionFind {
	struct Node {
		Node*	parent = nullptr;
		int		count = 1;

		Node* Root() {
			if (parent == nullptr) {
				return this;
			}
			return parent = parent->Root();
		}
	};
	vector<Node> nodes;

	UnionFind(int count) {
		nodes.resize(count);
	}

	void Join(int a, int b) {
		Node* rootA = nodes[a].Root();
		Node* rootB = nodes[b].Root();
		if (rootA == rootB) {
			return;
		}

		if (rootA->count > rootB->count) {
			swap(rootA, rootB);
		}

		rootB->count += rootA->count;
		rootA->parent = rootB;
		rootA->count = 0;
	}

	bool IsReachable(int a, int b) {
		Node* rootA = nodes[a].Root();
		Node* rootB = nodes[b].Root();
		return rootA == rootB;
	}
};

//------------------------------------------------------------
struct Kruskal {
	UnionFind uf;
	int totalCost;
	arr<dic<int, int>> G;

	Kruskal(int N, arr<pr<pint, int>> edges) : uf(N) {
		edges.sort([&](pr<pint, int> const& a, pr<pint, int> const& b) {
			return a.second < b.second;
});

		totalCost = 0;

		G.init(N);
		REP(i, edges.sz()) {
			int s = edges[i].first.x;
			int t = edges[i].first.y;
			int w = edges[i].second;

			if (uf.IsReachable(s, t)) {
				continue;
			}

			G[s][t] = w;
			G[t][s] = w;
			uf.Join(s, t);
			totalCost += w;
		}
	}
};

