			ySortedIndexs[i] = i;
		}

		auto calcCost = [&](pint a, pint b) -> int {
			return min(abs(a.x - b.x), abs(a.y - b.y));
		};

		auto predX = [&](int a, int b) {
			return C[a].x < C[b].x;
		};
		auto predY = [&](int a, int b) {
			return C[a].y < C[b].y;
		};
		xSortedIndexs.sort(predX);
		ySortedIndexs.sort(predY);

		arr<pr<pint, int>> edges;
		REP(i, N - 1) {
			{
				pr<pint, int> edge;
				edge.first.a = xSortedIndexs[i];
				edge.first.b = xSortedIndexs[i + 1];
				edge.second = calcCost(C[edge.first.a], C[edge.first.b]);
				edges.pb(edge);
				swap(edge.first.a, edge.first.b);
				//edges.pb(edge);
			}
			{
				pr<pint, int> edge;
				edge.first.a = ySortedIndexs[i];
				edge.first.b = ySortedIndexs[i + 1];
				edge.second = calcCost(C[edge.first.a], C[edge.first.b]);
				edges.pb(edge);
				swap(edge.first.a, edge.first.b);
				//edges.pb(edge);
			}
		}

		auto k = Kruskal(N, edges);

		out << k.totalCost;
	}
};

