const ll MAXN = 1e5 + 5;
const ll inf = 1e17;

vector < ll > parent(MAXN), sz(MAXN);

void make_set(int u){
  parent[u] = u;
  sz[u] = 1;
}

int find_set(int u){
  if(u == parent[u]) return u;
  return parent[u] = find_set(parent[u]);
}

void union_sets(int u , int v){
  u = find_set(u);
  v = find_set(v);
  if(u != v){
    if(sz[u] > sz[v]) swap(u, v);
    parent[u] = v;
    sz[v] += sz[u];
  }
}

