class UnionFind {
    public:
    int n;
    vector<int> par, rank;

    UnionFind(int n) {
        rep(n) {
            par.push_back(i);
            rank.push_back(0);
        }
    }

    int find(int x) {
        return ((par[x] == x) ? x : par[x] = find(par[x]));
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);

        if(x == y) return;

        if(rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if(rank[x] == rank[y]) rank[x]++;
        }
        return;
    }

    bool is_same(int x, int y) {
        return find(x) == find(y);
    }
};

struct Edge{
    int from, to; ll cost;
    Edge(int from, int to, ll cost){
        this->from = from;
        this->to = to;
        this->cost = cost;
    }
    bool operator<(const Edge &e) const{
        return cost < e.cost;
    }
};

class Graph{
    public:
    int V,E;
    vector<Edge> edges;
    Graph(int n, vector<Pll> x, vector<Pll> y){
        V = 2*n;
        E = 2*n-2;
        rep(n-1){
            edges.push_back(Edge(x[i+1].second, x[i].second, x[i+1].first - x[i].first));
            edges.push_back(Edge(y[i+1].second, y[i].second, y[i+1].first - y[i].first));
        }
    }

    ll kruskal(){
        ll ret = 0LL;
        UnionFind uf = UnionFind(V);
        sort(all(edges));
        for(Edge e: edges){
            if(!uf.is_same(e.from, e.to)){
                ret += e.cost;
                uf.unite(e.from, e.to);
            }
        }
        return ret;
    }
};

