        return par[x] = find(par[x]);
}

void unite(int x, int y) {
    x = find(x);    y = find(y);

    if (x == y)
        return ;
    else if (sz[x] < sz[y])
        par[x] = y;
    else {
        par[y] = x;
        if (sz[x] == sz[y])
            sz[x]++;
    }
}

