#include <bits/stdc++.h>
using namespace std;
#define UF_SIZE 1 // 1/0: 同値類のサイズを記録する/しない

struct UnionFind{
// 同値関係をサポートするデータ構造
// 併合,所属する同値類の代表元:O(logN), 集合の分割はNG
// 経路圧縮する場合,各クエリはO(a(n)) (a(n): アッカーマン関数A(m,n)について,f(n)=A(n,n)としたときの逆関数)
  vector<int> m_root;
#if (UF_SIZE==1)
  vector<int> m_size;
#endif

  UnionFind(int N)
  : m_root(N)
#if (UF_SIZE==1)
  , m_size(N,1)
#endif
  { iota(m_root.begin(), m_root.end(), 0); }

  int find(int a){
    if(m_root.at(a)==a){
      return a;
    }
    else{
      return m_root.at(a)= find(m_root.at(a));
    }
  }

  void unify(int a, int b){
    int r_a= find(a);
    int r_b= find(b);
#if (UF_SIZE==1)
    if(r_a != r_b){
      if(m_size.at(r_a) < m_size.at(r_b)){
        m_root.at(r_a)= r_b;
        m_size.at(r_b)+= m_size.at(r_a);
        return;
      }
      else{
        m_root.at(r_b)= r_a;
        m_size.at(r_a)+= m_size.at(r_b);
        return;
      }
    }
#else
    if(r_a != r_b){
      m_root.at(r_b)= r_a;
      return;
    }
#endif
  }

  bool are_comrade(int a, int b){
    return find(a)==find(b);
  }

#if (UF_SIZE==1)
  int get_size(int a){
    return m_size.at(find(a));
  }
#endif
};

int main(){
  using coord= pair<int, int>;
  using pii  = pair<int, int>;

  int N;
  cin >> N;

  vector<coord> data(N);
  map<coord, int> ids;
  priority_queue<pair<int, pii>, vector<pair<int, pii>>, greater<pair<int, pii>>> pq;
  UnionFind uf(N);

  coord buf;
  for(int i=0; i<N; i++){
    cin >> buf.first >> buf.second;
    data.at(i)= buf;
    if(!ids.count(buf)){
       ids[buf]= i;
    }
    else{
      uf.unify(ids.at(buf), i);
    }
  }

  auto comp1= [](coord p1, coord p2){
    bool ans= (p1.first != p2.first) ? (p1.first  < p2.first)
                                     : (p1.second < p2.second);
    return ans;
  };
  auto comp2= [](coord p1, coord p2){
    bool ans= (p1.second != p2.second) ? (p1.second < p2.second)
                                       : (p1.first  < p2.first);
    return ans;
  };
  auto dist= [](coord p1, coord p2){
    return min(abs(p1.first- p2.first), abs(p1.second- p2.second));
  };


  sort(data.begin(), data.end(), comp1);
  for(int i=1; i<N; i++){
    coord p1= data.at(i-1);
    coord p2= data.at(i);

    pq.push(make_pair(dist(p1, p2), make_pair(ids.at(p1), ids.at(p2))));
  }
  sort(data.begin(), data.end(), comp2);
  for(int i=1; i<N; i++){
    coord p1= data.at(i-1);
    coord p2= data.at(i);

    pq.push(make_pair(dist(p1, p2), make_pair(ids.at(p1), ids.at(p2))));
  }

  int ans= 0;
  while(uf.get_size(0) < N){
    auto tmp= pq.top();
    int d,id1,id2; pii ids_tmp;
    tie(d, ids_tmp)= tmp;
    tie(id1, id2)= ids_tmp;

    if(!uf.are_comrade(id1, id2)){
      uf.unify(id1, id2);
      ans+= d;
    }
    pq.pop();
  }

  cout << ans << endl;
}

