int minimum_spaning_tree()
{
	sort(all(edges));
	UnionFind uf(N);

	int ans = 0;
	for (auto edge : edges)
	{
		if (!uf.same(edge.s, edge.t))
		{
			ans += edge.cost;
			uf.unite(edge.s, edge.t);
		}
	}

	return ans;
}

