struct edge{
  int from, to, cost;
};

bool cmp(const edge &a, const edge &b){
  return a.cost < b.cost;
}

int par[200005];
int _rank[200005];
void init(int n){
  for(int i = 0; i < n; i++){
    par[i] = i;
    _rank[i] = 0;
  }
}

int find(int x){
  if(par[x] == x) return x;
  return par[x] = find(par[x]);
}

void unite(int x, int y){
  x = find(x); y = find(y);
  if(_rank[x] > _rank[y]) swap(x, y);
  par[y] = x;
  if(_rank[x] == _rank[y]) _rank[x]++;
}

bool same(int x, int y){
  return find(x) == find(y);
}

int main(){
  vector<p> px, py;
  int n, x, y;
  cin >> n;
  for(int i = 0; i < n; i++){
    cin >> x >> y;
    px.push_back(p(x, i));
    py.push_back(p(y, i));
  }
  sort(px.begin(), px.end());
  sort(py.begin(), py.end());
  vector<edge> g;
  for(int i = 1; i < px.size(); i++){
    int dist = abs(px[i].first - px[i-1].first);
    g.push_back(edge{px[i-1].second, px[i].second, dist});
  }
  for(int i = 1; i < py.size(); i++){
    int dist = abs(py[i].first - py[i-1].first);
    g.push_back(edge{py[i-1].second, py[i].second, dist});
  }
  sort(g.begin(), g.end(), cmp);
  init(2 * n);
  int sum = 0;
  for(int i = 0; i < g.size(); i++){
    edge e = g[i];
    if(!same(e.from, e.to)){
      unite(e.from, e.to);
      sum += e.cost;
    }
  }
  cout << sum << endl;
  return 0;
}

