#define REP(i, n) for (ll i=0; i<n; i++)
using namespace std;

struct UnionFind {
    vector<ll> par;

    UnionFind(ll N) : par(N) {
        REP (i, N) par[i] = i;
    }

    ll root (ll x) {
        if (par[x] == x) return x;
         return par[x] = root(par[x]);
    }

    void unite (ll x, ll y) {
         ll rx = root(x);
         ll ry = root(y);
        if (rx == ry) return;
        par[rx] = ry;
    }

    bool same (ll x, ll y) {
        ll rx = root(x);
        ll ry = root(y);
        return rx == ry;
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;
    vector<pair<ll, ll>> cox(N), coy(N);
    REP (i, N) {
        ll x, y;
        cin >> x >> y;
        cox[i] = make_pair(x, i);
        coy[i] = make_pair(y, i);
    }

    sort(cox.begin(), cox.end());
    sort(coy.begin(), coy.end());

    // Kruskal's Algorithm
    priority_queue<tuple<ll, ll, ll>> edge;
    UnionFind tree(N);
    REP (i, N-1) {
        edge.push(make_tuple(cox[i].first - cox[i+1].first,
            cox[i].second, cox[i+1].second));
        edge.push(make_tuple(coy[i].first - coy[i+1].first,
            coy[i].second, coy[i+1].second));
    }

    ll count = 0;
    ll ans = 0;
    while (count < N - 1) {
        auto e = edge.top();
        edge.pop();
        ll cost = get<0>(e) * -1;
        ll a = get<1>(e);
        ll b = get<2>(e);
        if (!tree.same(a, b)) {
            ans += cost;
            count++;
            tree.unite(a, b);
        }
    }

    cout << ans << "\n";
}

