typedef long long ll;

const int INF = 1000000000;

struct UF {

  vector<int> parent_, rank_;

  UF(int n) : parent_(n + 5), rank_(n + 5, 1) {
    for (int i = 0; i < n + 5; ++i) {
      parent_[i] = i;
    }
  }

  int find_set(int x) {
    if (x != parent_[x]) {
      parent_[x] = find_set(parent_[x]);
    }
    return parent_[x];
  }

  bool is_connected(int x, int y) {
    return find_set(x) == find_set(y);
  }

  void unite(int x, int y) {
    int s1 = find_set(x), s2 = find_set(y);
    if (s1 == s2) { return; }
    if (rank_[s1] > rank_[s2]) {
      parent_[s2] = s1;
    }
    else {
      parent_[s1] = s2;
      if (rank_[s1] == rank_[s2]) { ++rank_[s2]; }
    }
  }
};

int main()
{
  int N; scanf("%d", &N);
  vector<pair<ll, int> > X(N), Y(N);
  ll x, y;
  for (int i = 0; i < N; ++i) {
    scanf("%lld %lld", &x, &y);
    X[i] = make_pair(x, i);
