  sort(Y.begin(), Y.end());
  vector<pair<ll, pair<int, int>>> edges;
  for (int i = 1; i < N; ++i) {
    edges.push_back(make_pair(abs(X[i].first - X[i - 1].first),
                              make_pair(X[i].second, X[i - 1].second)));
    edges.push_back(make_pair(abs(Y[i].first - Y[i - 1].first),
                              make_pair(Y[i].second, Y[i - 1].second)));
  }
  sort(edges.begin(), edges.end());
  UF uf(N);
  ll ans = 0;
  for (int i = 0; i < (int)edges.size(); ++i) {
    ll w = edges[i].first;
    int u = edges[i].second.first, v = edges[i].second.second;
    if (not uf.is_connected(u, v)) {
      uf.unite(u, v);
      ans += w;
    }
  }
  printf("%lld\n", ans);
  return 0;
}

