using namespace std;

struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main()
{
  int N;scanf("%d",&N);
  vector<pair<int,int>> x,y;
  for(int X,Y,i=0;i<N;i++)
  {
    scanf("%d %d",&X,&Y);
    x.push_back(make_pair(X,i));
    y.push_back(make_pair(Y,i));
  }
  sort(x.begin(),x.end());sort(y.begin(),y.end());
  vector<tuple<int,int,int>> G;
  for(int i=1;i<N;i++)
  {
    G.push_back(make_tuple(x[i].first-x[i-1].first,x[i].second,x[i-1].second));
    G.push_back(make_tuple(y[i].first-y[i-1].first,y[i].second,y[i-1].second));
  }
  sort(G.begin(),G.end());int ans=0;
  UnionFind tree(N);
  for(int dist,a,b,i=0;i<N;i++)
  {
    dist=get<0>(G[i]);a=get<1>(G[i]);b=get<2>(G[i]);
    if(tree.same(a,b))continue;
    ans+=dist;
    tree.unite(a,b);
  }
  printf("%d",ans);
}

