struct UnionFind {
    vector<int> par;
    UnionFind(int N) : par(N) {
        rep(i, N) par[i] = -1;
    }
    int root(int x) {
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }
    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if (par[rx] > par[ry]) swap(rx, ry);
        par[rx] += par[ry];
        par[ry] = rx;
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    int size(int x) {
        return -par[root(x)];
    }
};

struct Edge {int from; int to; ll cost;};

int main() {
    int N;
    cin >> N;
    vector<tuple<ll, ll, int>> S(N);
    rep(i, N) {
        cin >> get<0>(S[i]) >> get<1>(S[i]);
        get<2>(S[i]) = i;
    }

    vector<Edge> Edges;
    sort(ALL(S));
    rep(i, N - 1) Edges.push_back(Edge{get<2>(S[i]), get<2>(S[i + 1]), min(get<0>(S[i + 1]) - get<0>(S[i]), abs(get<1>(S[i]) - get<1>(S[i + 1])))});
    rep(i, N) swap(get<0>(S[i]), get<1>(S[i]));
    sort(ALL(S));
    rep(i, N - 1) Edges.push_back(Edge{get<2>(S[i]), get<2>(S[i + 1]), min(get<0>(S[i + 1]) - get<0>(S[i]), abs(get<1>(S[i]) - get<1>(S[i + 1])))});

    sort(ALL(Edges), [](Edge a, Edge b) {
        return a.cost < b.cost;
    });
    UnionFind U(N);
    ll ans = 0;
    for (auto e : Edges) {
        if (U.same(e.from, e.to)) continue;
        U.unite(e.from, e.to);
        ans += e.cost;
    }
    cout << ans << "\n";
    return 0;
}

