typedef long long ll;

const ll MAXV = 1e5;
ll V;
// firstに頂点、secondにコストとした隣接リスト
vector<pair<ll, ll> > graph[MAXV];
ll used[MAXV]; // 頂点がTに含まれているかどうか

// 最小全域木のコストを返す
ll prim(){
  ll res = 0;
  // firstにmincost、secondにid
  priority_queue<pair<ll, ll>, vector<pair<ll, ll> >, greater<pair<ll, ll> > > PQ;
  PQ.push(make_pair(0, 0));
  while(!PQ.empty()){
    pair<ll, ll> p = PQ.top(); PQ.pop();
    ll v = p.second;
    if(used[v] == true) continue;
    used[v] = true;
    res += p.first;
    for(int i=0;i<graph[v].size();i++){
      ll to = graph[v][i].first;
      ll cost = graph[v][i].second;
      if(!used[to]) PQ.push(make_pair(cost, to));
    }
  }
  return res;
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  cin >> V;
  // X.firstはx座標, X.secondはid
  vector<pair<int, int> > X, Y;
  for(int i=0;i<V;i++){
    int tx, ty; cin >> tx >> ty;
    X.push_back(make_pair(tx, i));
    Y.push_back(make_pair(ty, i));
  }
  sort(X.begin(), X.end());
  sort(Y.begin(), Y.end());
  for(int i=0;i<V-1;i++){
    ll costX = X[i+1].first - X[i].first;
    ll costY = Y[i+1].first - Y[i].first;
    graph[X[i].second].push_back(make_pair(X[i+1].second, costX));
    graph[X[i+1].second].push_back(make_pair(X[i].second, costX));
    graph[Y[i].second].push_back(make_pair(Y[i+1].second, costY));
    graph[Y[i+1].second].push_back(make_pair(Y[i].second, costY));
  }
  cout << prim() << endl;
}

