    for (auto i = es.begin(); i != es.end(); ++i){
        edge e = *i;
    }
    init(V);

    int res = 0;
    for (auto i = es.begin(); i != es.end(); ++i){
        edge e = *i;
        if (!isSame(e.u, e.v)){
            unite(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}


