struct UnionFind {
  vector<int> par;
  vector<int> rank;
  vector<int> size;

  UnionFind(int N) : par(N), rank(N), size(N) {
    for (int i = 0; i < N; i++) {
      par[i]  = i;
      rank[i] = 0;
      size[i] = 1;
    }
  }

  int root(int x) {
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  bool unite(int x, int y) {
    int rx = root(x);
    int ry = root(y);
    if (rx == ry) return false;

    if (rank[rx] < rank[ry]) {
      par[rx] = ry;
      size[ry] = size[ry] + size[rx];
    }
    else if (rank[rx] > rank[ry]) {
      par[ry] = rx;
      size[rx] = size[rx] + size[ry];
    }
    else {
      par[ry] = rx;
      size[rx] = size[rx] + size[ry];
      rank[rx]++;
    }
    return true;
  }

  bool same(int x, int y) {
    return root(x) == root(y);
  }

  int get_size(int x) {
    int rx = root(x);
    return size[rx];
  }

};


ll kruskal() {
  sort(es, es + E, comp_edge);
  UnionFind uf = UnionFind(N);
  ll res = 0;
  for (ll i = 0; i < E; i++) {
    edge e = es[i];
    if(!uf.same(e.u, e.v)) {
      uf.unite(e.u, e.v);
      res += e.cost;
    }
  }
  return res;
}

