string alph("abcdefghijklmnopqrstuvwxyz"),s;
bool fl=true;
struct edge{ll from,to,cost;};
edge g[1000000];

//-------------------------↓↓↓↓↓↓------------------------

void init(ll nn){
        rep(i,nn){
            par[i]=i;
            ran[i]=0;
        }
}

ll root(ll xx){
    if(par[xx]==xx)return xx;
    else return par[xx]=root(par[xx]);
}

bool same(ll xx,ll yy){
    return root(xx)==root(yy);
}

void unite(ll xx,ll yy){
    xx=root(xx);
    yy=root(yy);
    if(xx==yy)return;
    if(ran[xx]<ran[yy])par[xx]=yy;
    else{
        par[yy]=xx;
        if(ran[xx]==ran[yy])ran[xx]++;
    }
}

bool comp(const edge& e1, const edge& e2){
    return e1.cost<e2.cost;
}

ll kruskal(){
    sort(g,g+2*n,comp);
    init(2*n);
    ll res=0;
    rep(i,2*n){
        edge e=g[i];
        if(!same(e.from,e.to)){
            unite(e.from,e.to);
            res+=e.cost;
        }
    }
    return res;
}

int main(void){
       cin.tie(0);
    ios::sync_with_stdio(false);

       cin >> n;
       vector<pair<ll,ll>> x;
       vector<pair<ll,ll>> y;
       rep(i,n){
           cin>>a>>b;
           x.push_back({a,i});
           y.push_back({b,i});
       }
       sort(all(x));
       sort(all(y));
       rep(i,n-1){
           g[i]={x[i].second,x[i+1].second,x[i+1].first-x[i].first};
           g[n+i]={y[i].second,y[i+1].second,y[i+1].first-y[i].first};
       }
       Cout(kruskal());
return 0;
}

