        if (n >= 100)return;        cerr << "---tree---" << endl;        rep(i, n) {            if (!(i == root || sz(g[i]) > 1))continue;            cerr << i << " -> ";            vi ts;            forg_f(gi, g[i]) {                forg_f_init(g[i]);                if (t != par_[i])ts.push_back(t);            }            rep(i, sz(ts) - 1)cerr << ts[i] << ", ";            if (sz(ts))cerr << ts.back() << endl;        }        cerr << endl;
