struct UnionFind{
  vector<int> p;
  UnionFind(int n) : p(n,-1) {}

  int root(int x){
    if(p[x] < 0) return x;
    return p[x] = root(p[x]);
  }

  bool issame(int x,int y){
    return root(x) == root(y);
  }

  bool merge(int x,int y){
    x = root(x);
    y = root(y);
    if(x == y) return false;
    if(p[x] > p[y]) swap(x,y);
    p[x] += p[y];
    p[y] = x;
    return true;
  }
};

using tup = tuple<int,int,int>;

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int N;
  cin >> N;
  vector<tup> suzu(N);
  for(int i=0; i<N; i++){
    int x,y;
    cin >> x >> y;
    suzu[i] = tup(x,y,i);
  }
  priority_queue<tup,vector<tup>,greater<tup>> que;
  sort(suzu.begin(),suzu.end());
  for(int i=1; i<N; i++){
    int x1,y1,id1;
    tie(x1,y1,id1) = suzu[i-1];
    int x2,y2,id2;
    tie(x2,y2,id2) = suzu[i];
    que.emplace(x2-x1,id1,id2);
    suzu[i-1] = tup(y1,x1,id1);
    if(i == N-1){
      suzu[i] = tup(y2,x2,id2);
    }
  }
  sort(suzu.begin(),suzu.end());
  for(int i=1; i<N; i++){
    int x1,y1,id1;
    tie(x1,y1,id1) = suzu[i-1];
    int x2,y2,id2;
    tie(x2,y2,id2) = suzu[i];
    que.emplace(x2-x1,id1,id2);
  }
  UnionFind uf(N);
  ll ans = 0;
  while(que.size()){
    int cost,a,b;
    tie(cost,a,b) = que.top();
    que.pop();
    if(uf.issame(a,b)) continue;
    ans += cost;
    uf.merge(a,b);
  }
  cout << ans << "\n";
  return 0;
}

