struct UnionFind {
  vector<lli> v;

  UnionFind(lli n = 0) : v(n) { iota(begin(v), end(v), 0); }
  lli root(lli i) { return i == v[i] ? i : v[i] = root(v[i]); }
  bool same(lli i, lli j) { return root(i) == root(j); }
  void unite(lli i, lli j) { v[root(i)] = root(j); }
};

