struct UnionFind{
    vector<int> parent;
    vector<int> rank;
    UnionFind(int n): rank(n,0), parent(n){
        rep(i,n) parent[i] = i;
    }

    int find(int x){
        if(parent[x] == x) return x;
        else return parent[x] = find(parent[x]);
    }

    void unite(int x,int y){
        x = find(x);
        y = find(y);
        if(x==y) return;
        else if(rank[x]<rank[y]) parent[x]=y;
        else{
            parent[y] = x;
            if(rank[x]==rank[y]){
                rank[x]+=1;
            }
        }
    }
};

