void Group (int u,int v)
{
    int x=Find(u);
    int y=Find(v);
    if (x==y)
        return;
    else
    {
        if (level[x]>level[y])
        {
            p[y]=x;
            return;
        }
        if (level[x]<level[y])
        {
            p[x]=y;
            return;
        }
        if (level[x]==level[y])
        {
            p[y]=x;
            level[x]++;
            return;
        }
    }
