int parent[N_MAX] = {};
vector<Point> P;
vector<Edge> edgeList;

ll findRoot(ll x){
    if(parent[x] == x){
        return x;
    }else{
        auto root = findRoot(parent[x]);
        parent[x] = root; // path compression
        return root;
    }
}

void _union(ll a, ll b){
    auto rootA = findRoot(a);
    auto rootB = findRoot(b);

    if(rootA == rootB){
        return;
    }else{
        parent[a] = b;
    }
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N;
    cin >> N;

    P.reserve(N);

    FOR(i, 0, N){
        ll x, y;
        cin >> x >> y;
        Point p = Point(x, y, i);
        P.push_back(p);
    }

    sort(ALL(P), Point::sortByX);
    FOR(i, 0, N-1){
        Edge edge;
        edge.from = P[i].id;
        edge.to = P[i+1].id;
        edge.cost = min(abs(P[i].x - P[i+1].x), abs(P[i].y - P[i+1].y));
        edgeList.push_back(edge);
    }

    sort(ALL(P), Point::sortByY);
    FOR(i, 0, N-1){
        Edge edge;
        edge.from = P[i].id;
        edge.to = P[i+1].id;
        edge.cost = min(abs(P[i].x - P[i+1].x), abs(P[i].y - P[i+1].y));
        edgeList.push_back(edge);
    }

    sort(ALL(edgeList), Edge::sortByCost);

    // make MST by kruskal
    FOR(i, 0, N_MAX){
        parent[i] = i;
    }

    ll cost_sum = 0;

    // 短いエッジから見ていって必要なら連結
    for(auto edge : edgeList){

        if(findRoot(edge.from) == findRoot(edge.to)){
            // skip
        }
        else{
            // つなぐ
            _union(findRoot(edge.from), findRoot(edge.to));
            cost_sum += edge.cost;
        }
    }

    p(cost_sum);

    return 0;
}

