void initUnionFind(int n) {
  rep(i, n) {
    Parent[i] = i;
    Node[i] = 0;
  }
}

int findParent(int i) {
  if (i == Parent[i]) return i;
  return Parent[i] = findParent(Parent[i]);
}

bool isSame(int x, int y) { return (findParent(x) == findParent(y)); }

void unite(int x, int y) {
  x = findParent(x);
  y = findParent(y);
  if (Node[x] < Node[y]) swap(x, y);
  Parent[y] = x;
  Node[x]++;
}

int main(void) {
  int N;
  cin >> N;
  vector<pair<int, int>> X(N);
  vector<pair<int, int>> Y(N);
  rep(i, N) {
    int x, y;
    cin >> x >> y;
    X[i] = {x, i};
    Y[i] = {y, i};
  }

  vector<tuple<int, int, int>> E((N - 1) * 2);
  sort(X.begin(), X.end());
  for (int i = 1; i < N; ++i) {
    int x0, x1, t0, t1;
    tie(x0, t0) = X[i - 1];
    tie(x1, t1) = X[i];
    E[i - 1] = {abs(x1 - x0), t0, t1};
  }

  sort(Y.begin(), Y.end());
  for (int i = 1; i < N; ++i) {
    int y0, y1, t0, t1;
    tie(y0, t0) = Y[i - 1];
    tie(y1, t1) = Y[i];
    E[N - 1 + i - 1] = {abs(y1 - y0), t0, t1};
  }

  initUnionFind(N);
  sort(E.begin(), E.end());
  int answer = 0;
  for (int i = 0; i < 2 * (N - 1); ++i) {
