    // cout << "t0=" << t0 << " t1=" << t1 << " : cost=" << cost << endl;
    if (!isSame(t0, t1)) {
      unite(t0, t1);
      answer += cost;
    }
  }
  cout << answer << endl;
  return 0;
}

