class Unionfind{
public:
  vector<int> par;
  vector<int> rak;

  Unionfind(int n): par(n), rak(n, 0){
    for(int i=0; i<n; ++i) par[i] = i;
  }

  int root(int x){
    return par[x] == x ? x : par[x] = root(par[x]);
  }

  bool same(int x, int y){
    return root(x) == root(y);
  }

  void unite(int x, int y){
    x = root(x);
    y = root(y);
    if(rak[x] < rak[y]) par[x] = y;
    else{
      par[y] = x;
      if(rak[x] == rak[y]) rak[x]++;
    }
  }
};

