ll E = 0; // 辺数
ll kruskal(ll V) {
	sort(es, es + E, comp); // edge.costが小さい順にソートする 
	UnionFind uf(V); // Union-Findの初期化
	ll res = 0;
	for (ll i = 0; i < E; i++) {
		edge e = es[i];
		if (!uf.issame(e.u, e.v)) {
			uf.merge(e.u, e.v);
			res += e.cost; 
		}
	}
	return res; 
}




