    xp[i] = {x, i};
    yp[i] = {y, i};
  }
  Sort(xp), Sort(yp);

  priority_queue<T, vT, greater<T>> to;
  rep(i, n-1){
    ll u = xp[i].second;
    ll v = xp[i+1].second;
    to.emplace(abs(xp[i].first - xp[i+1].first), u, v);
    u = yp[i].second;
    v = yp[i+1].second;
    to.emplace(abs(yp[i].first - yp[i+1].first), u, v);
  }

  ll ans = 0;
  UnionFind uf(n);
  while(uf.count() > 1){
    ll c, u, v;
    tie(c, u, v) = to.top();
    to.pop();
    if(!uf.same(u,v)){
      uf.unite(u,v);
      ans += c;
    }
  }

  cout << ans << endl;

  return 0;
}

