class UnionFind {
  std::vector<int> parent_;

  public:
  UnionFind(int size_num) : parent_(size_num, -1) {}
  int find(int x) {
    if (parent_[x] < 0) return x;
    return parent_[x] = find(parent_[x]);
  }
  bool unite(int x, int y) {
    x = find(x);
