    if(x == y) return;
    if(ufrank[x] < ufrank[y]){
        par[x] = y;
    int sx = ufsize[x], sy = ufsize[y];
    ufsize[x] = ufsize[y] = sx + sy;
    }else{
        par[y] = x;
        if(ufrank[x] == ufrank[y]) ufrank[x]++;
        int sx = ufsize[x], sy = ufsize[y];
        ufsize[x] = ufsize[y] = sx + sy;
