using namespace std;
using ppi = pair<pair<int, int>, int>;
struct UnionFind
{
  //自身が親であれば、その集合に属する頂点数に-1を掛けたもの
  //そうでなければ親のid
  vector<int> r;

  UnionFind(int N)
  {
    r = vector<int>(N, -1);
  }

  int root(int x)
  {
    if (r[x] < 0)
      return x;
    return r[x] = root(r[x]);
  }

  bool unite(int x, int y)
  {
    x = root(x);
    y = root(y);
    if (x == y)
      return false;
    if (r[x] > r[y])
      swap(x, y);
    r[x] += r[y];
    r[y] = x;
    return true;
  }

  int size(int x)
  {
    return -r[root(x)];
  }
};
int main()
{
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  cin >> n;
  vector<ppi> town(n);
  rep(i, n)
  {
    int a, b;
    cin >> a >> b;
    town[i] = make_pair(make_pair(a, b), i);
  }
  UnionFind closed(n);
  priority_queue<pair<int, pair<int, int>>> road;
  sort(ALL(town), [](const ppi &a, const ppi &b) { return a.first.first < b.first.first; });
  rep(i, n - 1)
  {
    road.push(make_pair(-min(abs(town[i].first.first - town[i + 1].first.first), abs(town[i].first.second - town[i + 1].first.second)), make_pair(town[i].second, town[i + 1].second)));
  }
  sort(ALL(town), [](const ppi &a, const ppi &b) { return a.first.second < b.first.second; });
  rep(i, n - 1)
  {
    road.push(make_pair(-min(abs(town[i].first.first - town[i + 1].first.first), abs(town[i].first.second - town[i + 1].first.second)), make_pair(town[i].second, town[i + 1].second)));
  }
  int ans = 0;
  while (!road.empty())
  {
    auto top = road.top();
    road.pop();
    int cost = -top.first;
    int i = top.second.first;
    int j = top.second.second;
    if (closed.root(i) == closed.root(j))
      continue;
    closed.unite(i, j);
    ans += cost;
  }
  cout << ans << endl;

  return 0;
}

