class union_find {
  private:
    vector<int> par, rank;
  public:
    explicit union_find(int n) : par(n), rank(n) {
      for (int i = 0; i < n; i++)
        par[i] = i;
    }
    int root_of(int x) {
      auto& p = par[x];
      if (p == x) return x;
      return p = root_of(p);
    }
    void unite(int x, int y) {
      x = root_of(x);
      y = root_of(y);
      if (x == y) return;
      if (rank[x] < rank[y])
        par[x] = y;
      else {
        par[y] = x;
        if (rank[x] == rank[y]) rank[x]++;
      }
    }
    bool connected(int x, int y) {
      return root_of(x) == root_of(y);
    }
};

int main() {
