// use in Kruskal
class DisjointSet {
	public:
	vector<int> rank;
	vector<int> parent;

	DisjointSet() {}

	// 0, 1, ... size-1 をそれぞれ唯一の要素とする
	// size個の互いに素な集合を作成
	DisjointSet(int size) {
		rank.resize(size, 0);
		parent.resize(size, 0);
		for (int i=0; i<size; i++) {
			makeSet(i);
		}
	}

	// 要素がXただ一つである新しい集合を作る
	void makeSet(int x) {
		parent[x] = x;
		rank[x] = 0;
	}

	// xとyが同じ集合に属しているかを判定する
	bool same(int x, int y) {
		return findSet(x) == findSet(y);
	}

	// 指定された2つの要素x, yを合併する
	void unite(int x, int y) {
		link(findSet(x), findSet(y));
	}

	// 低い方の木を高い方の木に合併
	void link(int x, int y) {
		if (rank[x] > rank[y]) {
			parent[y] = x;
		} else {
			parent[x] = y;
			if (rank[x] == rank[y]) {
				rank[y]++;
			}
		}
	}

	// 要素xが属する集合の代表の要素を求める
	int findSet(int x) {
		if (x != parent[x]) {
			parent[x] = findSet(parent[x]);
		}
		return parent[x];
	}
};

class Edge {
	public:
	int node1, node2;
	ll cost;

	Edge(int node1 = 0, int node2 = 0, ll cost = 0):
		node1(node1), node2(node2), cost(cost) {}

	bool operator < (const Edge &e) const {
		return cost < e.cost;
	}
};

ll Kruskal(int N, vector<Edge> edges) {
	ll totalCost = 0;
	sort(edges.begin(), edges.end());

	DisjointSet dset = DisjointSet(N);

	int node1, node2;
	for (int i=0; i< edges.size(); i++) {
		Edge e = edges[i];
		if (!dset.same(e.node1, e.node2)) {
			//MST.push_back(e);
			totalCost += e.cost;
			dset.unite(e.node1, e.node2);
		}
	}

	return totalCost;
}

