    rep(i, n) { index_array[i] = i; }

    vector<edge> es;

    sort(v.begin(), v.end());
    sort(index_array, index_array + n, [&](ll const &a, ll const &b) {
        if (v[a].first != v[b].first) {
            return v[a].first < v[b].first;
        } else {
            return v[a].second < v[b].second;
        }
    });
    repd(i, 1, n) {
        int cost =
            min(abs(v[index_array[i]].first - v[index_array[i - 1]].first),
                abs(v[index_array[i]].second - v[index_array[i - 1]].second));
        es.push_back(edge(index_array[i], index_array[i - 1], cost));
    }

    sort(index_array, index_array + n, [&](ll const &a, ll const &b) {
        if (v[a].second != v[b].second) {
            return v[a].second < v[b].second;
        } else {
            return v[a].first < v[b].first;
        }
    });
    repd(i, 1, n) {
        int cost =
            min(abs(v[index_array[i]].first - v[index_array[i - 1]].first),
                abs(v[index_array[i]].second - v[index_array[i - 1]].second));
        es.push_back(edge(index_array[i], index_array[i - 1], cost));
    }

    sort(es.begin(), es.end(), comp);

    ll result = 0;
    UnionFind u(n);
    for (auto e : es) {
        if (!u.same(e.u, e.v)) {
            u.unite(e.u, e.v);
            result += e.cost;
        }
    }

    cout << result << endl;
    return 0;
}

