class UnionFind {

public:
    // コンストラクタ
    UnionFind(int N) {
        this->N = N;
        REP(i, N) {
            // 初期化: par[i] = i, rank[i] = 0
            par.pb(i);
            rank.pb(0);
        }
    }

    // xの親を返す+更新
    int find(int x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    // xとyを含むグループを統合する
    void unite(int x, int y) {
        x = find(x);
        y = find(y);

        if (x == y) return;

        // rankの小さい方にくっつける
        if (rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (rank[x] == rank[y]) rank[x]++;
        }
    }

    // xとyが同じグループに属するか判定
    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int N;
    VI par, rank;
};

