//◆--↓--最小全域木(Kruskal) : O(E * logV)--↓--
struct UnionFind {
	vector<ll> data;

	UnionFind(ll sz) {
		data.assign(sz, -1);
	}

	bool unite(ll x, ll y) {
		x = find(x), y = find(y);
		if (x == y) return (false);
		if (data[x] > data[y]) swap(x, y);
		data[x] += data[y];
		data[y] = x;
		return (true);
	}

	ll find(ll k) {
		if (data[k] < 0) return (k);
		return (data[k] = find(data[k]));
	}

	ll size(ll k) {
		return (-data[find(k)]);
	}
};

template<typename T>
T kruskal(Edges<T> &edges, ll V) {
	sort(begin(edges), end(edges), [](const edge<T> &a, const edge<T> &b) {
		return (a.cost < b.cost);
	});
	UnionFind tree(V);
	T ret = 0;
	for (auto &e : edges) {
		if (tree.unite(e.src, e.to)) ret += e.cost;
	}
	return (ret);
}
