template <class T> class UnionFind {
  private:
    struct subset  { 
      int parent; 
      int rank;
      T diff_weight;
      int sizes;
    }; 
    std::vector<subset> subsets;

  public:
    UnionFind (int N) {
      subsets.resize(N);
      for(int i=0; i<N; i++) subsets[i] = subset( { i, 0, T(0), 1 } );
    }

    int Find (int x) { 
      if (subsets[x].parent == x) return x;
      int r = Find(subsets[x].parent); 
      subsets[x].diff_weight += subsets[subsets[x].parent].diff_weight;
      return subsets[x].parent = r; 
    } 

    T weight(int x) {
      Find(x);
      return subsets[x].diff_weight;
    }

    bool Same (int x, int y) {
        return Find(x) == Find(y);
    }

    bool Union (int x, int y, T w) {
      w += weight(x); w -= weight(y);
      x = Find(x);  y = Find(y); 
      if ( x == y ) return false;

      if (subsets[x].rank < subsets[y].rank) {
        std::swap(x, y);
        w = -w;
      }
      if (subsets[x].rank == subsets[y].rank) {
        subsets[x].rank++; 
        subsets[x].sizes += subsets[y].sizes;
      }
      subsets[y].parent = x;
      subsets[y].diff_weight = w;
      return true;
    }

    T diff(int x, int y) {
      assert( Same(x,y) );
      return weight(y) - weight(x);
    }

    int size (int x) {
      return subsets[Find(x)].sizes;
    }
};


int main (void) {
  std::cin.tie(0);  std::ios::sync_with_stdio(false);
  int N; std::cin >> N;
  std::vector<int> x(N), y(N);
  rep(i,N) std::cin >> x[i] >> y[i];

  struct Edge{
    ll cost;
    int a;
    int b;
  };
  std::vector<Edge> edges;

  std::vector<int> ids(N); rep(i,N) ids[i] = i;

  // x
  std::sort( all(ids), [&](int i, int j) { return x[i] < x[j]; } );
  for(int i=0; i<N-1; i++) {
    auto u = ids[i];
    auto v = ids[i+1];
    edges.push_back( Edge( { std::abs(x[u]-x[v]), u, v } ) );
  }

  // y
  rep(i,N) ids[i] = i;
  std::sort( all(ids), [&](int i, int j) { return y[i] < y[j]; } );
  for(int i=0; i<N-1; i++) {
    auto u = ids[i];
    auto v = ids[i+1];
    edges.push_back( Edge( { std::abs(y[u]-y[v]), u, v } ) );
  }

  // Kruskal
  std::sort( all(edges), [](Edge &x, Edge &y) { return x.cost < y.cost; } );
  UnionFind<int> uf(N);
  ll ans = 0;
  for(auto&& e : edges) {
    if ( uf.Same(e.a,e.b) ) continue;
    uf.Union(e.a,e.b,0);
    ans += e.cost;
  }
  std::cout << ans << std::endl;

  return 0;
}

