template<typename T>
T prim(vector<vector<pair<ll, T>>> &g){
    ll n = (ll)g.size();
    T ret = 0;
    vector<bool> used(n, false);
    using P = pair<T, ll>;
    priority_queue<P, vector<P>, greater<P>> que;
    que.emplace(0,0);
    while(!que.empty()){
        auto p = que.top();
        que.pop();
        if(used[p.second]) continue;
        used[p.second] = true;
        ret += p.first;
        for(auto &e : g[p.second]){
          que.emplace(e.second,e.first);
        }
    }
    return ret;
}

