#define in(v) cin>>v;
#define out(v) cout<<v<<"\n"

const int MAX_N = 1e5+1;

int parent[MAX_N];
int root(int x) {
  if (parent[x] == x)
    return x;
  return parent[x] = root(parent[x]);
}
void unite(int x, int y) {
  if (root(x) == root(y))
    return;
  x = root(x);
  y = root(y);
  parent[x] = y;
  return;
}
bool same(int x, int y) {
  return root(x) == root(y);
}
int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  int N; in(N);

  int x[N], y[N];
  rep(i, N) {
    in(x[i]); in(y[i]);
    parent[i] = i;
  }
  priority_queue<pair<int, pii>, vector<pair<int, pii>>, greater<pair<int, pii>>> E;
  rep(i, N) {
    loop(j, i+1, N) {
      int cost = min(abs(x[i] - x[j]), abs(y[i] - y[j]));
      E.push(make_pair(cost, make_pair(i, j)));
    }
  }
  int ans = 0;
  while (!E.empty()) {
    int cost = E.top().first;
    int i = E.top().second.first,
        j = E.top().second.second;
    E.pop();

    if (same(i, j))
      continue;
    unite(i, j);
    ans += cost;
  }
  out(ans);

  return 0;
}

