struct Node {
  int id;
  int x;
  int y;
};

struct Edge {
  int from;
  int to;
  int distance;

  bool operator<(const Edge &e) const { return distance < e.distance; }
};

int cmpx(Node a, Node b) { return a.x < b.x; }
int cmpy(Node a, Node b) { return a.y < b.y; }

struct UnionFind {
  vector<int> par;
  vector<ll> sizes;

  UnionFind(int N) : par(N), sizes(N, 1) { rep(i, N) par[i] = i; }

  // find root parent
  int find(int x) {
    if (x == par.at(x)) {
      return x;
    } else {
      // update x's parent
      return par.at(x) = find(par.at(x));
    }
  }

  // merge x's and y's trees
  void unite(int x, int y) {
    x = find(x);
    y = find(y);

    if (x == y)
      return;

    if (sizes.at(x) < sizes.at(y))
      swap(x, y);

    // merge x as y's parent
    par.at(y) = x;
    sizes.at(x) += sizes.at(y);
  }

  // is same parents
  bool same(int x, int y) { return find(x) == find(y); }
};

void solve(ll N, vector<Node> ns) {
  ll cost = 0;
  vector<Edge> es;

  sort(ns.begin(), ns.end(), cmpx);
  rep(i, N - 1) {
    es.push_back((Edge){
      from : ns.at(i).id,
      to : ns.at(i + 1).id,
      distance : ns.at(i + 1).x - ns.at(i).x
    });
  }

  sort(ns.begin(), ns.end(), cmpy);
  rep(j, N - 1) {
    es.push_back((Edge){
      from : ns.at(j).id,
      to : ns.at(j + 1).id,
      distance : ns.at(j + 1).y - ns.at(j).y
    });
  }

  sort(all(es)); // sort by distance

  UnionFind uf(N);
  for (Edge e : es) {
    if (!uf.same(e.from, e.to)) {
      cost += e.distance;
      uf.unite(e.from, e.to);
    }
  }

  cout << cost << endl;
}

int main() {
  ll N;
  scanf("%lld", &N);
  vector<Node> ns(N);
  for (int i = 0; i < N; i++) {
    (&ns[i])->id = i;
    scanf("%lld", &ns[i].x);
    scanf("%lld", &ns[i].y);
  }
  solve(N, std::move(ns));
  return 0;
}

