        connect[ysort[i+1].second].emplace_back(P(ysort[i+1].first-ysort[i].first,ysort[i].second));
    ;}
    priority_queue<P, vector<P>, greater<P>> pq;
    UnionFind tree(N);
    for(ll i=0;i<connect[0].size();i++){
        pq.push(connect[0][i]);
    ;}
    ll ans=0;
    while(pq.size()){
        P X=pq.top();
        pq.pop();
        if(X.first==0){
            tree.unite(X.second,0);
            for(ll i=0;i<connect[X.second].size();i++){
                if(!tree.same(X.second,connect[X.second][i].second))pq.push(connect[X.second][i]);
            ;}
        }
        else if(!tree.same(X.second,0)){
            ans+=X.first;
            tree.unite(X.second,0);
            for(ll i=0;i<connect[X.second].size();i++){
                pq.push(connect[X.second][i]);
            ;}
        }
    }
    cout<<ans<<endl;



return 0;
