ll prim(vector<vector<Edge>> &g, ll n){
    ll res = 0;
    vector<int> used(n, 0);
    priority_queue<pair<ll,ll>, vector<pair<ll,ll>>, greater<pair<ll,ll>>> q;
    q.push(make_pair(0, 0));
    while(!q.empty()){
        pair<ll,ll> now = q.top();
        q.pop();
        if(used[now.second]) continue;
        used[now.second] = 1;
        res += now.first;
        for(int i = 0; i < g[now.second].size(); i++){
            Edge next = g[now.second][i];
            if(!used[next.to]){
                q.push(make_pair(next.cost, next.to));
            }
        }
    }
    return res;
}

