/*使い方
UnionFind a(N);//初期化、N個の頂点を考える

Int b = a.root(x);//頂点xの親が返る
bool c = a.same(x,y);//xとyが同じ集合→trueが返る
Int d = a.size(x);//頂点xの属する集合の要素数が返る

a.unite(x,y);//頂点xとyを連結する
（xとyが元々同じ集合に属している場合falseが、元々異なる集合に属している場合trueが返るようになっている）

*/

class UnionFind {
private:
	vector<Int> data;//data[i]:頂点iの親（頂点番号）

public:
	UnionFind(Int size) : data(size, -1) { }//全ての頂点の親を-1で初期化
	Int root(Int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }//data[i]が負なら頂点i自身が親であり、その時さらに-data[i]は集合の要素数を表す
	bool same(Int x, Int y) { return root(x) == root(y); }//頂点xとyが同じ集合に属するかどうか
	Int size(Int x) { return -data[root(x)]; }//頂点xの含まれる集合の要素数

	bool unite(Int x, Int y) {//頂点xとyを同じ集合に連結する
		x = root(x); y = root(y);
		if (x != y) {//頂点xとyが元々違う集合に属していた場合
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
			return true;//連結したという意味でtrueが返る
		}
		else {//頂点xとyが元々同じ集合に属していた場合
			return false;//連結を行わなかったという意味でfalseが返る
		}
	}
};

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	Int N;
	cin >> N;

	vector<vector<Int>> xy(N, vector<Int>(3));//（x座標、y座標、頂点番号）
	for (Int i = 0; i < N; i++) {
		cin >> xy[i][0] >> xy[i][1];
		xy[i][2] = i;
	}

	priority_queue<edge, vector<edge>, decltype(&cmpq)> pq(&cmpq);

	//x座標でソート
	sort(xy.begin(), xy.end(), cmpx);
	DMP(xy);

	//x座標の距離
	edge temp;//（from、to、距離）
	for (Int i = 0; i < N - 1; i++) {
		temp.from = xy[i][2];//from
		temp.to = xy[i + 1][2];//to
		temp.dis = abs(xy[i][0] - xy[i + 1][0]);
		pq.push(temp);
	}

	//y座標でソート
	sort(xy.begin(), xy.end(), cmpy);
	DMP(xy);


	for (Int i = 0; i < N - 1; i++) {
		temp.from = xy[i][2];//from
		temp.to = xy[i + 1][2];//to
		temp.dis = abs(xy[i][1] - xy[i + 1][1]);
		pq.push(temp);
	}

	UnionFind a(N);
	Int ans = 0;
	while (!pq.empty()) {

		temp = pq.top();
		if (a.same(temp.from,temp.to)) {//fromとtoが既につながれている場合スルー
			pq.pop();
			continue;
		}
		else {
			ans += temp.dis;//ansに距離を足す
			a.unite(temp.from, temp.to);//fromとtoをつなげる
			pq.pop();
		}
	}

	cout << ans << "\n";

}

