/*
引数
　g:探索するグラフ
戻り値
　return:最小全域木を構成する辺のコストの総和
　ming:最小全域木のグラフ
*/
ll kruskal(const vector<vector<Edge>> &g, vector<vector<Edge>> &ming) {
	ll n = g.size();
	ming.assign(n, vector<Edge>());
 	UnionFind uf(n);
	priority_queue<Edge, vector<Edge>, function<bool(Edge,Edge)>> que(
		[](const Edge &x, const Edge &y){
			return x.cost != y.cost ? (x.cost > y.cost) : 
				(x.from != y.from ? x.from < y.from : x.to < y.to);
		}
	);
	for(ll u=0;u<n;u++){
		for(Edge e:g[u]){
			if (u < e.to) que.push(e);
		}
	}

	ll edgecount = 0;
	ll mincost = 0;
	while (edgecount < n-1 && !que.empty()) {
		Edge e = que.top();
		que.pop();
		if (uf.unite(e.from, e.to)) {
			edgecount++;
			ming[e.from].push_back(e);
			mincost += e.cost;
		}
	}
	return mincost;
}


