vector <P> p;

struct UnionFind {
    //number of parents(par[i] = i => root)
    vector <int> par;
    //rank of tree
    vector <int> rank;

    UnionFind(int n) : par(n), rank(n, 1) {
        //initialize
        rep(n, i) par[i] = i;
    }

    //find root (keiroasshuku at the same time)
    int root(int x){
        if (par[x] == x) return x;
        else return par[x] = root(par[x]);
    }

    //unite
    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (rank[x] > rank[y]) swap(x, y);
        par[x] = y;
        if (rank[x] == rank[y]) rank[y]++;
    }

    //same tree?
    bool same(int x, int y){
        return root(x) == root(y);
    }
};

struct Edge
{
  int from, to; ll cost;

  // コストの大小で順序定義
  bool operator<(const Edge& o) const {
    return cost < o.cost;
  }
};

struct Kruskal
{
    int V;  // number of nodes
    vector<Edge> edges;

    void input(){
        cin >> V;
        rep(V, i) {
            ll x, y;
            scanf("%lld %lld\n", &x, &y);
            p.pb(P(llP(x, y), i));
        }
        sort(all(p));
        rep(V-1, i) {
            Edge e = {p[i].second, p[i+1].second, min(abs(p[i].first.first-p[i+1].first.first), abs(p[i].first.second-p[i+1].first.second))};
            edges.pb(e);
        }
        rep(V, i) swap(p[i].first.first, p[i].first.second);
        sort(all(p));
        rep(V-1, i) {
            Edge e = {p[i].second, p[i+1].second, min(abs(p[i].first.first-p[i+1].first.first), abs(p[i].first.second-p[i+1].first.second))};
            edges.pb(e);
        }
    }

    // グラフが非連結のときは最小全域森のコストの和となる
    ll kruskal() {
        //init
        UnionFind uf(V);
        sort(all(edges));
        ll min_cost = 0LL;

        for (Edge e : edges) {
            if (!uf.same(e.from, e.to)) {
                min_cost += e.cost;
                uf.unite(e.from, e.to);
            }
        }
        return min_cost;
    }
};


