using namespace std;

struct union_find {
    vector<int> par, sz;

    union_find(int n) {
        par.resize(n);
        sz.resize(n);
        for (int i =0; i < n; i++)
            par[i] = i, sz[i] = 0;
    }

    int find(int x) {
        if (par[x] == x)
            return x;
        else 
            return par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x = find(x), y = find(y);

        if (x == y) return ;

        else if (sz[x] < sz[y])
            par[x] = y;
        else {
            par[y] = x;
            if (sz[x] == sz[y])
                sz[x]++;
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

typedef long long ll;
typedef pair<int, int> P;
typedef pair<ll, P> PP;

ll minimum_spanning_tree(int n, vector<PP> &G) {
    ll ans = 0;
    union_find uf(n);
    sort(G.begin(), G.end());

    for (int i = 0; i < G.size(); i++) {
        int u = G[i].second.first;
        int v = G[i].second.second;
        ll cost = G[i].first;

        if (uf.same(u, v))
            continue;

        else  {
            uf.unite(u, v);
            ans += cost;
        }
    }

    return ans;
}

int main() {
    int n;  cin >> n;
    vector<pair<pair<ll, ll>, int > > x, y;
    for (int i = 0; i < n; i++) {
        int a, b;   cin >> a >> b;
        x.push_back(pair<pair<ll, ll>, int> (pair<ll, ll>(a, b), i));
        y.push_back(pair<pair<ll, ll>, int> (pair<ll, ll>(b, a), i));
    }

    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    vector<PP> G;
    for (int i = 0; i < n-1; i++) {
        pair<pair<ll, ll>, int> p, q, r, s;
        p = x[i], q = x[i+1], r = y[i], s = y[i+1];

        G.push_back(PP(q.first.first - p.first.first, P(p.second, q.second)));
        G.push_back(PP(s.first.first - r.first.first, P(r.second, s.second)));
    }

    cout << minimum_spanning_tree(n, G) << endl;
    return 0;
}

