int Par[1000000];//親
int Rank[1000000];//深さ
int sum[1000000];//要素数

			  //n要素で初期化
void init(int n) {
	for (int i = 0; i < n; i++) {
		Par[i] = i;
		Rank[i] = 0;
		sum[i] = 1;
	}
}
//xの木の根を求める
int find(int x) {
	if (Par[x] == x) {
		return x;
	}
	else {
		return Par[x] = find(Par[x]);
	}
}
//xとyの属性を併合
void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y) return;

	if (Rank[x] < Rank[y]) {
		Par[x] = y;
		sum[y] += sum[x];
	}
	else {
		Par[y] = x;
		sum[x] += sum[y];
		if (Rank[x] == Rank[y])Rank[x]++;
	}
}
//xとyが同じ集合かどうか
bool same(int x, int y) {
	return find(x) == find(y);
}

struct edge { ll u, v, cost; };

bool comp(const edge& e1, const edge& e2) {
	return e1.cost < e2.cost;
}


edge es[1000000];//max辺数
ll V, E;//頂点数、辺数


ll kruskal() {
	sort(es, es + E, comp);
	init(V);
	int res = 0;

	for (int i = 0; i < E; i++) {
		edge e = es[i];
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}

