        int u, sx, sy, v, tx, ty;
        tie(sx, sy, u) = p[i];
        tie(tx, ty, v) = p[i + 1];
        int dist = min(abs(sx - tx), abs(sy - ty));
        edges.push_back(make_tuple(dist, p[i], p[i + 1]));
    }
    sort(p.begin(), p.end(), [](const Point &l, const Point &r) {
        int u, sx, sy, v, tx, ty;
        tie(sx, sy, u) = l;
        tie(tx, ty, v) = r;
        return sy <= ty || sx <= tx;
    });
    for (int i = 0; i < n - 1; ++i) {
        int u, sx, sy, v, tx, ty;
        tie(sx, sy, u) = p[i];
        tie(tx, ty, v) = p[i + 1];
        int dist = min(abs(sx - tx), abs(sy - ty));
        edges.push_back(make_tuple(dist, p[i], p[i + 1]));
    }

