        return this->cost > edge.cost;
    }
};

/*
最小全域木(プリム)
連結前提．無向グラフならedgesはfrom->toとto->from両方いれないとだめ
ただし，出力は片方だけ
O(|E| log |E|)
*/
vector<Edge> prim(set<int> nodes, vector<Edge> edges) {

    priority_queue<Edge, vector<Edge>, greater<Edge>> q;
    q.push({ -1, 0, 0 });
    set<int> visited_node;
    vector<Edge> result;

    while (!q.empty() && result.size() < nodes.size()) {
        Edge edge = q.top(); q.pop();
        int cost = edge.cost, from = edge.from, to = edge.to;
        if (find(visited_node.begin(), visited_node.end(), to) != visited_node.end()) {
            continue;
        }
        visited_node.insert(to);
        result.push_back(edge);

        for (Edge e : edges) {
            if (e.from == to) {
                if (find(visited_node.begin(), visited_node.end(), e.to) != visited_node.end()) {
                    continue;
                }
                q.push(e);
            }
        }
    }
    // ダミーのエッジを削除
    result.erase(result.begin());
    return result;
}

