struct UnionFind {
    vector<int> par; // 親の番号
    UnionFind(int size) : par(size, -1) {}
    // xとyの木を併合
    bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if (par[y] < par[x])
                swap(x, y);
            par[x] += par[y];
            par[y] = x;
            return true;
        } else {
            return false;
        }
    }
    // 2つのデータx, yが属する木が同じならtrueを返す
    bool same(int x, int y) { return root(x) == root(y); }
    // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
    int root(int x) { return par[x] < 0 ? x : par[x] = root(par[x]); }
    // 頂点 v が属するグループと同じグループに属する頂点数を得る
    int size(int x) { return -par[root(x)]; }
};

struct edge {
    int from, to, cost;
    bool operator<(const edge &t) const { return cost < t.cost; };
};

int kruskal(int v, vector<edge> es) {
    sort(ALL(es));

    UnionFind uf(v);

    int res = 0;
    for (auto &e : es) {
        if (uf.unite(e.from, e.to)) {
            res += e.cost;
        }
    }

    return res;
}
