using namespace std;

typedef long long ll;
typedef unsigned long long ull;
#define REP(i, n) for(int i=0; i<n; i++)
const int MAXN = 100100;

class UnionFind{
    public:
        vector<int> par;
        vector<int> rank;

        UnionFind(int n){
            for(int i = 0; i < n; i++){
                par.push_back(i);
                rank.push_back(0);
            }
        }

        int find(int x){
            if(x == par[x])
                return x;
            else
                return par[x] = find(par[x]);
        }

        void unite(int x, int y){
            x = find(x);
            y = find(y);
            if(x == y) return;

            if(rank[x] < rank[y])
                par[x] = y;
            else{
                par[y] = x;
                if(rank[x] == rank[y]) rank[x]++;
            }
        }

        bool same(int x, int y){
            return find(x) == find(y);
        }
};

pair<ll, int> X[MAXN], Y[MAXN];

struct edge { ll u, v, cost; };
bool comp(const edge &e1, const edge &e2){
    return e1.cost < e2.cost;
}
edge es[2*MAXN];
int E;
int V;

ll kruskal(){
    sort(es, es+E, comp);
    UnionFind uf = UnionFind(V);
    ll res = 0;
    for(int i = 0; i < E; i++){
        edge e = es[i];
        if(!uf.same(e.u, e.v)){
            uf.unite(e.u, e.v);
            res += e.cost;
        }
    }   
    return res;
}

int main(){
    int N;
    cin >> N;
    REP(i,N){
        ll x,y;
        cin >> x >> y;
        X[i] = make_pair(x,i);
        Y[i] = make_pair(y,i);
    }

    sort(X, X+N);
    sort(Y, Y+N);

    REP(i,N-1){
        es[i].u = X[i].second;
        es[i].v = X[i+1].second;
        es[i].cost = X[i+1].first - X[i].first;
    }
    REP(i,N-1){
        es[N-1+i].u = Y[i].second;
        es[N-1+i].v = Y[i+1].second;
        es[N-1+i].cost = Y[i+1].first - Y[i].first;
    }

    V = N;
    E = 2*(N-1);
    ll ans = kruskal();
    cout << ans << endl;
    return 0;
}

