template <typename T>
struct Kruskal
{

    struct edge
    {
        int from, to, used;
        T cost;

        edge(int x, int y, T z) : from(x), to(y), cost(z){}
        //初期化

        bool operator<(const edge &e) const
        {
            return cost < e.cost;
        }
        //sort用
    };

    int V;
    vector<int> Parent;
    vector<edge> es;

    Kruskal(){}
    Kruskal(int V_):V(V_), Parent(V_) {
        for(auto &i:Parent){
            i=-1;
        }
    }
    //1.宣言する

    void add_edge(T u, T v, T c)
    {
        es.emplace_back(u, v, c);
    }
    //2.辺を入れる

    int root(int A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = root(Parent[A]);
    }

    int size(int A)
    {
        return -Parent[root(A)];
    }

    bool connect(int A, int B)
    {
        //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        if (A == B)
        {
            //すでにくっついてるからくっ付けない
            return false;
        }

        //大きい方(A)に小さいほう(B)をくっ付けたい
        //大小が逆だったらひっくり返しちゃう。
        if (size(A) < size(B))
            swap(A, B);

        //Aのサイズを更新する
        Parent[A] += Parent[B];
        //Bの親をAに変更する
        Parent[B] = A;

        return true;
    }

    bool same(int A, int B)
    {
        return root(A) == root(B);
    }

    //3.回す
    T build()
    {
        sort(es.begin(), es.end());

        T res = 0;

        for (int i = 0; i < (ll)es.size(); i++)
        {
            edge e = es[i];
            if (!same(e.from, e.to))
            {
                connect(e.from, e.to);
                res += e.cost;
            }
        }

        return res;
    }
};

