// Union Find用
class DisjointSet
{
  private:
    vector<int> p;

  public:
    DisjointSet(int size) : p(size, -1) {}

    bool unite_set(int x, int y)
    {
	x = root(x);
	y = root(y);

	if (x != y)
	{
	    if (x > y)
	    {
		swap(x, y);
	    }
	    p[x] += p[y];
	    p[y] = x;
	}

	return x != y;
    }

  private:
    int root(int x)
    {
	return p[x] < 0 ? x : p[x] = root(p[x]);
    }
};

// 通路
struct corridor
{
    int a, b; // 繋がっているcell
    int len;  // 通路の長さ
    corridor(int a, int b, int len) : a(a), b(b), len(len) {}

    // ソート用
    bool operator<(const corridor &rhs) const
    {
	if (len != rhs.len)
	{
	    return len < rhs.len;
	}
	if (a != rhs.a)
	{
	    return a < rhs.a;
	}
	return b < rhs.b;
    }
};

int dist(int a, int b, int c, int d)
{
    return min(abs(a - c), abs(b - d));
}

int main(int argc, char const *argv[])
{
    int n;
	cin >> n;
    int x[100010], y[100010];
    for (int i = 1; i <= n; i++)
    {
		cin >> x[i] >> y[i];
    }

    // 全ての通路を長さでソートする
    vector<corridor> cor;
    for (int i = 1; i <= n; i++)
    {
		for (int j = 1; j < i; j++)
		{
			cor.push_back(corridor(i, j, max(0, dist(x[i],y[i],x[j],y[j]))));
		}
    }
    sort(cor.begin(), cor.end());

    DisjointSet ds(n+1);
    int ans = 0;   // 通路の長さの総和
    int count = 0; // 選んだ通路の数

    for (vector<corridor>::iterator itr = cor.begin(); count < n - 1; itr++)
    {
		// aとbが別々の集合に属しているならばその通路を採用する
		if (ds.unite_set(itr->a, itr->b))
		{
			ans += itr->len;
			count++;
		}
    }
    printf("%d\n", ans);
    return 0;
}

