    return cost > e.cost;
  }
};
int main() {
  int n;
  cin>>n;
  set<pair<int, int> > s;
  for (int i=0; i<n; i++) {
    int x, y;
    cin>>x>>y;
    s.emplace(x, y);
  }
  vector<pair<int, int> > points(s.begin(), s.end());
  priority_queue<edge, vector<edge>, greater<edge> > que;
  int  size = points.size();
  long long cost = 0;
  set<int> v;
  set<int> orig;
  v.insert(0);
  for (int i=1; i<size; i++) {
    auto p0 = points[0];
    auto pi = points[i];
    que.push({0, i, min(abs(p0.first-pi.first), abs(p0.second-pi.second))});
  }
  for (int i=1; i<size; i++) {
    orig.insert(i);
  }
  while (v.size() != size) {
    auto e = que.top();
    que.pop();
    int n1 = e.n1;
    int n2 = e.n2;
    if (v.find(n1) != v.end() && v.find(n2) != v.end()) {
      continue;
    }
    int from;
    if (v.find(n1) == v.end()) {
      from = n1;
    } else {
      from = n2;
    }
    v.insert(from);
    orig.erase(from);
    for (auto i: orig) {
      auto p = points[from];
      auto pi = points[i];
      que.push({from, i, min(abs(p.first-pi.first), abs(p.second-pi.second))});
    }
    cost += e.cost;
  }
  cout<<cost<<endl;
}

