        int x, y; cin >> x >> y;
        xs[i] = make_tuple(x, y, i);
        ys[i] = make_tuple(y, x, i);
    }
    sort(all(xs));
    sort(all(ys));
    UndirectedGraph g(n + 1);
    rep(i, n - 1) {
        int a, b, from, to;
        tie(a, ignore, from) = xs[i];
        tie(b, ignore, to) = xs[i + 1];
        g.connect(from, to, abs(b - a));
        tie(a, ignore, from) = ys[i];
        tie(b, ignore, to) = ys[i + 1];
        g.connect(from, to, abs(b - a));
    }
    cout << g.kluskal() << "\n";
}

