bool compare_by_x(tuple<ll, ll, ll> a, tuple<ll, ll, ll> b)
{
    if (get<1>(a) != get<1>(b))
    {
        return get<1>(a) < get<1>(b);
    }
    else
    {
        return get<2>(a) < get<2>(b);
    }
}

bool compare_by_y(tuple<ll, ll, ll> a, tuple<ll, ll, ll> b)
{
    if (get<2>(a) != get<2>(b))
    {
        return get<2>(a) < get<2>(b);
    }
    else
    {
        return get<1>(a) < get<1>(b);
    }
}

