#define for2(i,m,n) for (ll (i)=(m);(i)<(n);(i)++)
#define for3(i,m,n,d) for (ll (i)=(m);(i)<(n);(i)+=(d))
#define INF (1LL << 60)

ll X[100005];
ll Y[100005];

class UnionFind {
public:
    //親の番号を格納する。親だった場合は-(その集合のサイズ)
    vector<ll> Parent;

    //作るときはParentの値を全て-1にする
    //こうすると全てバラバラになる
    UnionFind(ll N) {
        Parent = vector<ll>(N, -1);
    }

    //Aがどのグループに属しているか調べる
    ll root(ll A) {
        if (Parent[A] < 0) return A;
        return Parent[A] = root(Parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    ll size(ll A) {
        return -Parent[root(A)];//親をとってきたいß
    }

    //AとBをくっ付ける
    bool connect(ll A, ll B) {
        //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        if (A == B) {
            //すでにくっついてるからくっ付けない
            return false;
        }

        //大きい方(A)に小さいほう(B)をくっ付けたい
        //大小が逆だったらひっくり返しちゃう。
        if (size(A) < size(B)) swap(A, B);

        //Aのサイズを更新する
        Parent[A] += Parent[B];
        //Bの親をAに変更する
        Parent[B] = A;

        return true;
    }
};

void solve()
{
    ll N;
    cin >> N;
    for1(i,N) {
        cin >> X[i] >> Y[i];
    }
    vector<tuple<ll,ll,ll>> dis;
    for1(i,N) {
        for2(j,i+1,N) {
            dis.emplace_back(min(abs(X[i]-X[j]),abs(Y[i]-Y[j])),i,j);
        }
    }
    sort(dis.begin(),dis.end());
    ll rest = N - 1;
    UnionFind uni(N);
    ll ans = 0;
    for (auto item : dis) {
        if (rest == 0) break;
        ll d,a,b;
        tie(d,a,b) = item;
        if (uni.root(a) == uni.root(b)) continue;
        ans += d;
        uni.connect(a,b);
        --rest;
    }

    cout << ans << endl;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    solve();
}

