//連結成分の判定のために用意
struct UnionFind {
    //自身が親であれば，その集合に属する頂点数に-1を掛けたもの
    //そうでなければ親のid
    vector<int> r;

    UnionFind(int n) {
        r = vector<int>(n, -1);
    }

    int root(int x) { //木の根を調べる（どのグループに属しているか）
        if (r[x] < 0) return x;
        return r[x] = root(r[x]);
    }

    bool unite(int x, int y) { //xとyの属する集合を併合
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (r[x] > r[y]) swap(x, y);
        r[x] += r[y];
        r[y] = x;
        return true;
    }

    int size(int x) { //xが属する集合の頂点数を調べる
        return -r[root(x)];
    }

    bool same(int x, int y) { //xとyが同じ集合に属するか否か
        return root(x) == root(y);
    }
};

struct edge { int u, v, cost; }; //点uとvを結ぶ重みcostの辺

bool comp(const edge& e1, const edge& e2) {
    return e1.cost < e2.cost;
}

vector<edge> es;
int n, m; //頂点数と辺数

ll kruskal() {
    sort(all(es), comp); //edge.costが小さい順にソート
    UnionFind UF(n); //連結成分の判定用
    ll res = 0;
    rep(i,2*(n-1)) {
        edge e = es[i];
        if (!UF.same(e.u, e.v)) { //同じ連結成分に属していなければ閉路できないためOK
            UF.unite(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}

int main() {
    cin >> n;
    vector<P> x(n), y(n);
    rep(i,n) {
        cin >> x[i].first >> y[i].first;
        x[i].second = i; y[i].second = i;
    }
    sort(all(x)); sort(all(y));

    //考えるグラフの辺集合を構築
    rep(i,n-1) {
        edge e;
        e.u = x[i].second; e.v = x[i+1].second;
        e.cost = x[i+1].first - x[i].first;
        es.pb(e);
        e.u = y[i].second; e.v = y[i+1].second;
        e.cost = y[i+1].first - y[i].first;
        es.pb(e);
    }

    ll ans = kruskal();
    cout << ans << endl;
}

