struct UFT {
	vector< int > par;
	int getpar(int i) {
		if (par[i] == i)
			return i;
		return par[i] = getpar(par[i]);
	}
	void unite(int i, int j) {
		int t = getpar(i);
		par[t] = getpar(j);
	}
	bool uf(int i, int j) {
		return getpar(i) == getpar(j);
	}
	UFT(int n) {
		par = vector< int >(n);
		for (int i = 0; i < n; i++)
			par[i] = i;
	}
};
int minT(edges &es, int n) {
	sort(es.begin(), es.end());
	int ret = 0;
	UFT *u = new UFT(n);
	for (int i = 0; i < es.size(); i++) {
		edge e = es[i];
		if (u->uf(e.from, e.to))
			continue;
		ret += e.d;
		u->unite(e.from, e.to);
	}
	for (int i = 1; i < n; i++)
		if (!u->uf(0, i))
			return -1;
	return ret;
}
