class UnionFind {

public:
    // コンストラクタ
    UnionFind(int N) {
        this->N = N;
        REP(i, N) {
            // 初期化: par[i] = i, rank[i] = 0
            par.pb(i);
            rank.pb(0);
        }
    }

    // xの親を返す+更新
    int find(int x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    // xとyを含むグループを統合する
    void unite(int x, int y) {
        x = find(x);
        y = find(y);

        if (x == y) return;

        // rankの小さい方にくっつける
        if (rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (rank[x] == rank[y]) rank[x]++;
        }
    }

    // xとyが同じグループに属するか判定
    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int N;
    VI par, rank;
};

/* ----------- Main Function ------------ */

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;

    V<VPL> data(2);
    // data[0]がx,data[1]がyのデータ

    REP(i, N) {
        ll x, y;
        cin >> x >> y;
        data[0].pb({x, i});
        data[1].pb({y, i});
        // idは0-indexedなのに注意
    }

    V<tuple<ll, ll, ll>> edge;
    REP(k, 2) {
        SORT(data[k]);

        REP(i, N - 1) {
            ll v1 = data[k][i].snd;
            ll v2 = data[k][i + 1].snd;
            ll cost = data[k][i + 1].fst - data[k][i].fst;
            edge.push_back(make_tuple(cost, v1, v2));
        }
    }

    SORT(edge);
    ll ans = 0;
    UnionFind uf(N);

    for (auto e : edge) {
        ll w, va, vb;
        tie(w, va, vb) = e;
        if (uf.find(va) != uf.find(vb)) {
            uf.unite(va, vb);
            ans += w;
        }
    }

    cout << ans << endl;
    return 0;
}

