struct City {
    int id, x, y;
};
inline int built(City lhs, City rhs) {
    return min(abs(lhs.x - rhs.x), abs(lhs.y - rhs.y));
}
struct Edge {
    int from, to, cost;
    Edge(){}
    Edge(int f, int t, int c): from(f), to(t), cost(c) {};
    bool operator < (const Edge& e) const noexcept {
        return this->cost < e.cost;
    }
    bool operator <= (const Edge& e) const noexcept {
        return this->cost <= e.cost;
    }
    bool operator > (const Edge& e) const noexcept {
        return this->cost > e.cost;
    }
    bool operator >= (const Edge& e) const noexcept {
        return this->cost >= e.cost;
    }
};
signed main() {
