        int x, y; cin >> x >> y;
        cities[i].id = i; cities[i].x = x; cities[i].y = y;
    }

    heapq<Edge> que;
    vector<City> cityX(cities);
    sort(ALL(cityX), [](auto const& lhs, auto const& rhs) {
            return lhs.x < rhs.x;
            });
    repx(i, 1, N, 1) {
        int cost = built(cityX[i], cityX[i - 1]);
        que.push(Edge(cityX[i].id, cityX[i - 1].id, cost));
