struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2
    vector<int> size;
    UnionFind(int N): par(N),size(N) {

         //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++){
            par[i] = i;
            size[i] = -1;
        }

    }
    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
        size[ry] += size[rx];
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
    int getsize(int x){
        return -size[root(x)];
    }
    int getNunion(){//これちょっと遅い sameと組み合わせて順次数えていけば早くなりそう。
        map<int,int> m;
        rep(i,par.size()){
            m[this->root(i)]++;
        }
        return int(m.size());
    }
};

int main(){
    ll N;
    cin >> N;
    vector<Pll> x(N), y(N);
    rep(i,N){
        cin >> x[i].fi >> y[i].fi;
        x[i].se = i;
        y[i].se = i;
    }
    sort(x.begin(),x.end());
    sort(y.begin(),y.end());
    UnionFind tr(N);
    vector<PlP> edge;
    rep(i,N-1){
        edge.push_back({{x[i+1].fi - x[i].fi},{x[i+1].se, x[i].se}});
        edge.push_back({{y[i+1].fi - y[i].fi},{y[i+1].se, y[i].se}});
    }
    sort(edge.begin(), edge.end());
    ll M = edge.size();
    ll ans = 0;
    rep(i,M){
        ll c = edge[i].fi;
        ll v = edge[i].se.fi;
        ll u = edge[i].se.se;
        if(tr.same(v,u)){
            continue;
        }else{
            tr.unite(v,u);
            ans += c;
        }
    }
    cout << ans << endl;
}

#include<bits/stdc++.h>
typedef long long int ll;
