using namespace std;


#define SIZE 100005


struct Node{
	bool operator<(const struct Node &arg) const{
		return weight < arg.weight;
	};
	int from,to,weight;
};

struct Info{
	Info(int arg_node,int arg_value){
		node = arg_node;
		value = arg_value;
	}
	bool operator<(const struct Info &arg) const{

		return value < arg.value;
	}
	int node,value;
};

int parent[SIZE],height[SIZE];

int getParent(int id){
	if(parent[id] == id)return id;
	else{
		return parent[id] = getParent(parent[id]);
	}
}

bool isSame(int a, int b){
	return getParent(a) == getParent(b);
}

void unite(int a,int b){
	int a_parent = getParent(a);
	int b_parent = getParent(b);

	if(a_parent == b_parent)return;	//元々同じグループ

	if(height[a_parent] > height[b_parent]){ //高い方に吸収する
		parent[b_parent] = a_parent;
	}else{
		if(height[a_parent] == height[b_parent])height[b_parent]++;
		parent[a_parent] = b_parent;
	}
}


int main(){

	int V,E;

	scanf("%d",&V);
	E = 2*(V-1);

	vector<Info> X,Y;
	for(int i = 0; i < V; i++){

		int x,y;
		scanf("%d %d",&x,&y);
		X.push_back(Info(i,x));
		Y.push_back(Info(i,y));
	}

	sort(X.begin(),X.end());
	sort(Y.begin(),Y.end());

	Node nodes[E];

	int index = 0;

	for(int i = 1; i < V; i++){

		nodes[index].from = X[i-1].node;
		nodes[index].to = X[i].node;
		nodes[index].weight = abs(X[i-1].value-X[i].value);
		index++;
	}

	for(int i = 1; i < V; i++){

		nodes[index].from = Y[i-1].node;
		nodes[index].to = Y[i].node;
		nodes[index].weight = abs(Y[i-1].value-Y[i].value);
		index++;
	}

	sort(nodes,nodes+E);

	//統合するのは頂点
	for(int i = 0; i < V; i++){
		parent[i] = i;
		height[i] = 0;
	}

	ll sum = 0;

	for(int i = 0; i < E; i++){
		if(!isSame(nodes[i].from,nodes[i].to)){ //同じグループでなければくっつけて、そのコストを足す
			sum += nodes[i].weight;
			unite(nodes[i].from,nodes[i].to);
		}
	}

	printf("%lld\n",sum);

	return 0;
}

