using namespace std;
typedef long long ll;
const ll MOD = (ll)1e9 + 7;
const ll INF = (ll)1e17;
const ll MAX = 1e5+1;

vector<ll> par, sz;

ll root(ll x){
  if(par[x] == x) return x;
  return root(par[x]);
}

void unite(ll x, ll y){
  ll rx = root(x);
  ll ry = root(y);
  if(rx == ry) return;
  if(sz[rx] < sz[ry]){
    par[rx] = ry;
    sz[ry] += sz[rx];
  }else{
    par[ry] = rx;
    sz[rx] += sz[ry];
  }
}

bool same(ll x, ll y){
  return root(x) == root(y);
}


int main(){
  ll N; cin >> N;
  vector<pair<ll, ll> > x(N), y(N);
  vector<vector<ll> > g(N, vector<ll>(N, INF));
  deque<vector<ll> > s;
  ll ans = 0;


  for(ll i = 0; i < N; i++){
    ll xx, yy; cin >> xx >> yy;
    x[i] = make_pair(xx, i);
    y[i] = make_pair(yy, i);
    g[i][i] = 0;
  }

  sort(x.begin(), x.end());
  sort(y.begin(), y.end());
  for(ll i = 1; i < N; i++){
    ll dx = x[i].first - x[i-1].first;
    ll fx = x[i].second, sx = x[i-1].second;
    g[fx][sx] = dx, g[sx][fx] = dx;

    ll dy = y[i].first - y[i-1].first;
    ll fy = y[i].second, sy = y[i-1].second;
    g[fy][sy] = min(g[fy][sy], dy), g[sy][fy] = min(g[sy][fy], dy);
  }

  for(ll i = 0; i < N-1; i++){
    for(ll j = i+1; j < N; j++){
      if(g[i][j] < INF)
        s.emplace_back(vector<ll>{g[i][j], i, j});
    }
  }

  sort(s.begin(), s.end());

  for(ll i = 0; i < N; i++){
    par.emplace_back(i);
    sz.emplace_back(1);
  }

  while(!s.empty()){
    ll des = s[0][0], fst = s[0][1], scd = s[0][2]; s.pop_front();
    if(!same(fst, scd)){
      ans += des;
      unite(fst, scd);
    }
  }

  cout << ans << endl;
}

