private:
  T n;
  vector<T> parent;

public:
  Union_Find(T v){
    n=v;
    parent.resize(n,-1);
  }

  T root(T v){
    if(parent[v]<0)return v;
    return parent[v]=root(parent[v]);
  }
  T size(T v){
    return -parent[root(v)];
  }
  bool connect(T a,T b){
    a=root(a);
    b=root(b);
    if(a==b)return false;
    if(size(a)<size(b)) swap(a,b);
    parent[a]+=parent[b];
    parent[b]=a;
    return true;
  }
  bool same(T a,T b){
    return root(a)==root(b);
  }

};
main(){
  cin.tie(0);
  ios::sync_with_stdio(0);
  cout<<fixed<<setprecision(10);

  ll n;
  cin>>n;
  vector<tuple<ll,ll,ll>> a,x,y;
  rep(i,n){
    ll f,t;
    cin>>f>>t;
    a.emplace_back(f,t,i);
  }
  x=a;
  y=a;
  auto cmp=[](auto x,auto y){
    return get<1>(x) < get<1>(y);
  };
  sort(x.begin(),x.end());
  sort(y.begin(),y.end(),cmp);

  vector<tuple<ll,ll,ll>> edges;
  auto dist = [&](auto x,auto y)->ll{
    ll a,b,c,d,u,v;
    tie(a,b,u)=x;
    tie(c,d,v)=y;
    return min(abs(a-c),abs(b-d));
  };
  rep(i,n-1){
    ll tmp1=dist(x[i],x[i+1]);
    ll tmp2=dist(y[i],y[i+1]);
    edges.emplace_back(tmp1,get<2>(x[i]),get<2>(x[i+1]));
    edges.emplace_back(tmp2,get<2>(y[i]),get<2>(y[i+1]));
  }
  sort(edges.begin(),edges.end());

  Union_Find<ll> uni(n);
  ll ans=0;
  for(auto& e:edges){
    ll c,u,v;
    tie(c,u,v)=e;
    if(uni.same(u,v))continue;
    ans+=c;
    uni.connect(u,v);
  }
  assert(ans!=3);
  cout<<ans<<endl;

}

