typedef long long int ll;

struct union_find{
	int n;
	vector<int> par,rnk;
	union_find(int _n){
		n = _n;
		for(int i=0;i<n;i++) par.push_back(i);
		for(int i=0;i<n;i++) rnk.push_back(0);
	}
	int find(int x){
		if(par[x]==x) return x;
		else return par[x] = find(par[x]);
	}
	bool same(int x,int y){
		return find(x) == find(y);
	}
	void unite(int x,int y){
		x = find(x);
		y = find(y);
		if(rnk[x]<rnk[y]){
			par[x] = y;
		}else{
			par[y] = x;
			if(rnk[x]==rnk[y]) rnk[x]++;
		}
	}
};
typedef pair<ll,pair<int,int> > edge;

int main(){
	int n;
	pair<ll,int> x[100000];
	pair<ll,int> y[100000];
	scanf("%d",&n);
	for(int i=0;i<n;i++){
		scanf("%lld%lld",&x[i].first,&y[i].first);
		x[i].second = y[i].second = i;
	}
	sort(x,x+n);
	sort(y,y+n);
	vector<edge> E;
	for(int i=0;i<n-1;i++){
		edge e;
		e.second.first = x[i].second;
		e.second.second = x[i+1].second;
		e.first = x[i+1].first - x[i].first;
		E.push_back(e);
	}
	for(int i=0;i<n-1;i++){
		edge e;
		e.second.first = y[i].second;
		e.second.second = y[i+1].second;
		e.first = y[i+1].first - y[i].first;
		E.push_back(e);
	}
	sort(E.begin(),E.end());
	ll ans = 0;
	union_find uf(n);
	for(int i=0;i<E.size();i++){
		if(!uf.same(E[i].second.first,E[i].second.second)){
			ans += E[i].first;
			uf.unite(E[i].second.first,E[i].second.second);
		}
	}
	printf("%lld\n",ans);
}

