//Union-Find tree
struct UnionFind{
    vector<int> par; // par[i]:iの親の番号 (例) par[3] = 2 : 3の親が2
    vector<int> tree_size;  // treeの大きさ

    UnionFind(int N) : par(N),tree_size(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N;  i++) par[i] = i;
        for(int i = 0; i < N;  i++) tree_size[i] = 1;
    }  

    int root(int x) { // データxが属する木の根を再帰で得る : root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { //xとyの木を併合
        int rx = root(x); //xの木の根をrx
        int ry = root(y); //yの木の根をyx
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)ときはそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時 : xの根rxをyの根ryにつける
        tree_size[ry] += 1; //根をつけた場合はtree sizeを1上げる
        tree_size[rx] = -1; // 同じ木になったため、xの根は-1
        //tree_size[x] = -1;  //子になった木はtree_sizeを持たない
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    int size(int x){ // データxが属する木のサイズを返す
        int rx = root(x); //xの木の根をrx
        return tree_size[rx];
    }
};

#define F first;
#define S second;

int main(){
    int n;
    cin >> n;
    vector<pair<pair<ll,ll>,int>> x;
    vector<pair<pair<ll,ll>,int>> y;
    rep(i,n){
        ll a,b;
        cin >> a >> b;
        x.push_back({{a,b},i});
        y.push_back({{b,a},i});
    }
    sort(x.begin(),x.end());
    sort(y.begin(),y.end());
    priority_queue<pair<ll,pair<int,int>>> q;
    rep(i,n-1){
        q.push({-MIN(abs(x[i].first.first - x[i+1].first.first),
        abs(x[i].first.second - x[i+1].first.second)),{x[i].second,x[i+1].second}});
        q.push({-MIN(abs(y[i].first.first - y[i+1].first.first),
        abs(y[i].first.second - y[i+1].first.second)),{y[i].second,y[i+1].second}});
    }
    ll ans = 0;
    UnionFind UF(n);
    while(!q.empty()){
        pair<ll,pair<int,int>> nq;
        nq = q.top();
        q.pop();
        ll cost = -nq.first;
        int i = nq.second.first, j = nq.second.second;
        if(UF.same(i,j)) continue;
        ans += cost;
        UF.unite(i,j);
    }
