using namespace std;
#define ll long long

#define MAX_N 1000000

int par[MAX_N]; // 親の番号
int node_rank[MAX_N];

// n要素で初期化
void init(int n){
  for(int i=0; i<n; i++){
    par[i] = i;
    node_rank[i] = 0;
  }
}
// 木の根を求める
int root(int x){
  if(par[x] == x){ // 根
    return x;
  } else {
    return par[x] = root(par[x]); // 経路圧縮
  }
}

// xとyが同じ集合に属するか否か
bool same(int x, int y){
  return root(x) == root(y);
}

// xとyの属する集合を併合
void unite(int x, int y){
  x = root(x);
  y = root(y);
  if(x == y) return;

  if(node_rank[x] < node_rank[y]){
    par[x] = y;
  } else {
    par[y] = x;
    if(node_rank[x] == node_rank[y])
      node_rank[x]++;
  }
}

