const int MAX_N = 1e5+1;

int parent[MAX_N];
int root(int x) {
  if (parent[x] == x)
    return x;
  return parent[x] = root(parent[x]);
}
void unite(int x, int y) {
  if (root(x) == root(y))
    return;
  x = root(x);
  y = root(y);
  parent[x] = y;
  return;
}
bool same(int x, int y) {
  return root(x) == root(y);
}
// end

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  int N; in(N);

  pii x[N], y[N];
  rep(i, N) {
    in(x[i].first); in(y[i].first);
    x[i].second = y[i].second = i;
    parent[i] = i;
  }
  sort(x, x+N); sort(y, y+N);
  priority_queue<pair<int, pii>, vector<pair<int, pii>>, greater<pair<int, pii>>> diff_x, diff_y;

  rep(i, N-1) {
    diff_x.push(make_pair(x[i+1].first - x[i].first, pii(x[i].second, x[i+1].second)));
    diff_y.push(make_pair(y[i+1].first - y[i].first, pii(y[i].second, y[i+1].second)));
  }
  ll ans = 0;
  while (!diff_x.empty() || !diff_y.empty()) {
    int cost1 = diff_x.top().first;
    int cost2 = diff_y.top().first;
    if (diff_y.empty() || !diff_x.empty() && cost1 < cost2) {
      int x1 = diff_x.top().second.first,
          x2 = diff_x.top().second.second;
      diff_x.pop();
      if (!same(x1, x2)) {
        unite(x1, x2);
        ans += cost1;
      }
    } else {
      int y1 = diff_y.top().second.first,
          y2 = diff_y.top().second.second;
      diff_y.pop();
      if (!same(y1, y2)) {
        unite(y1, y2);
        ans += cost2;
      }
    }
  }
  out(ans);
  return 0;
}

