struct UnionFind{
	vector<int> par;
	vector<int> rank;

	UnionFind(int n=1){
		init(n);
	}

	// n要素で初期化
	void init(int n=1){
		par.resize(n);
		rank.resize(n);
		REP(i, n){
			par[i]=i;
			rank[i]=0;
		}
	}

	// xの根を求める
	int find(int x){
		if(par[x]==x){
			return x;
		}
		else{
			return par[x]=find(par[x]);
		}
	}

	// xとyが属する集合を併合
	bool unite(int x, int y){
		x=find(x);
		y=find(y);
		if(x==y){
			return false;
		}
		if(rank[x]<rank[y]){
			par[x]=y;
		}
		else{
			par[y]=x;
			if(rank[x]==rank[y]){
				++rank[x];
			}
		}
		return true;
	}

	// xとyが同じ集合に属するか判定
	bool is_same(int x, int y){
		return find(x)==find(y);
	}
};

struct edge{
	int u;
	int v;
	int cost;
};

int root[MAX_N], depth[MAX_N];

edge es[MAX_E];
int V, E;

void add_edge(int u, int v, int cost){
	edge e;
	e.u=u;
	e.v=v;
	e.cost=cost;
	es[E++]=e;
	return;
}

bool comp(const edge& e1, const edge& e2){
	return e1.cost<e2.cost;
}

ll kruskal(){
	sort(es, es+E, comp);
	UnionFind uf(V);
	ll res=0;
	REP(i, E){
		edge e=es[i];
		if(!uf.is_same(e.u, e.v)){
			uf.unite(e.u, e.v);
			res+=e.cost;
		}
	}
	return res;
}

