struct Edge { ll from_x, from_y, to_x, to_y, cost; };
using P_Graph = map<P, vector<Edge>>;

int n;
vector<P> xy,yx;
P_Graph g;

template<typename T = ll>
T prim(P_Graph &g) {
    using TP = pair<T, P>;

    T res = 0;
    map<P, bool> used;
    priority_queue<TP, vector<TP>, greater<TP>> pq;
    pq.push(TP(0, P(xy[0].first, xy[0].second)));
    while(!pq.empty()) {
        auto t = pq.top(); pq.pop();
        auto cost = t.first, v = t.second;
        if(used[v]) continue;
        used[v] = true;
        res += cost;
        for(auto e : g[v]){
            pq.push(TP(e.cost, P(e.to_x, e.to_y)));
        }
    }
    return res;
}

