{
    Node *xsorted = new Node[n];
    Node *ysorted = new Node[n];
    memcpy(xsorted, nodes, sizeof(Node) * n);
    memcpy(ysorted, nodes, sizeof(Node) * n);
    sort(xsorted, xsorted + n, xsort);
    sort(ysorted, ysorted + n, ysort);
