using namespace std;

struct point {
    int x;
    int y;
    int id;
};

struct edge {
    int node;
    int cost;
    bool operator<(const edge& r) const {
        return cost > r.cost;
    }
};

bool cmpx(const point& l, const point& r) {
    return l.x < r.x;
}
bool cmpy(const point& l, const point& r) {
    return l.y < r.y;
}

vector<edge> edges[100010];
bool visited[100010];

int main() {
    int N;
    cin >> N;

    vector<point> v;
    for (int i=0; i<N; i++) {
        int x,y;
        cin >> x >> y;
        v.push_back( point{x,y,i} );
    }

    // x軸で移動するとき
    sort(v.begin(), v.end(), cmpx);
    for (int i=1; i<v.size(); i++) {
        int c = abs(v[i].x - v[i-1].x);
        edges[v[i].id].push_back( edge{v[i-1].id, c} );
        edges[v[i-1].id].push_back( edge{v[i].id, c} );
    }

    // y軸で移動するとき
    sort(v.begin(), v.end(), cmpy);
    for (int i=1; i<v.size(); i++) {
        int c = abs(v[i].y - v[i-1].y);
        edges[v[i].id].push_back( edge{v[i-1].id, c });
        edges[v[i-1].id].push_back( edge{v[i].id, c} );
    }

    int ans = 0;
    priority_queue<edge> q;
    q.push( edge{0, 0} ); // 初期ノード
    while (!q.empty()) {
        edge curr = q.top();
        q.pop();
        if (visited[curr.node]) continue;
        visited[curr.node] = true;
        ans += curr.cost;

        for (int i=0; i<edges[curr.node].size(); i++) {
            edge e = edges[curr.node][i];
            if (visited[e.node]) continue;
            q.push( e );
        }
    }

    cout << ans << endl;

    return 0;
}

