typedef pair<int, int> P;
const int MAX_N = 100010;
long long int n;
int par[MAX_N];    //親
int deapth[MAX_N]; //木の深さ
long long int cnt[MAX_N];
long long int num;

struct edge
{
    int from;
    int to;
    int cost;
    bool operator<(const edge &another) const
    {
        return cost < another.cost;
    }
    bool operator>(const edge &another) const
    {
        return cost > another.cost;
    }
};

//n要素で初期化
void init(int n)
{
    for (int i = 0; i < n; i++)
    {
        par[i] = i;
        deapth[i] = 0;
        cnt[i] = 1;
    }
}
//木の根を求める
int find(int x)
{
    if (par[x] == x)
    {
        return x;
    }
    else
    {
        return par[x] = find(par[x]);
    }
}

//xとyの属する集合を併合
void unite(int x, int y)
{
    x = find(x);
    y = find(y);
    if (x == y)
        return;
    if (deapth[x] < deapth[y])
    {
        par[x] = y;
        cnt[y] += cnt[x];
    }
    else
    {
        par[y] = x;
        cnt[x] += cnt[y];
        if (deapth[x] == deapth[y])
            deapth[x]++;
    }
}

bool same(int x, int y)
{
    return find(x) == find(y);
}

int main()
{
    cin >> n;
    vector<P> x(n);
    vector<P> y(n);
    for (int i = 0; i < n; i++)
    {
        int a, b;
        cin >> a >> b;
        x[i] = P(a, i + 1);
        y[i] = P(b, i + 1);
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());
    vector<edge> v;
    for (int i = 0; i < n - 1; i++)
    {
        /* code */
        edge e;
        e.from = x[i].second;
        e.to = x[i + 1].second;
        e.cost = x[i + 1].first - x[i].first;
        v.push_back(e);
        e.from = y[i].second;
        e.to = y[i + 1].second;
        e.cost = y[i + 1].first - y[i].first;
        v.push_back(e);
    }
    sort(v.begin(), v.end());
    init(n);
    long long int ans = 0;
    for (int i = 0; i < v.size(); i++)
    {
        edge e = v[i];
        if (same(e.from, e.to))
        {
            continue;
        }
        else
        {
            unite(e.from, e.to);
            ans += e.cost;
        }
    }
    cout << ans << endl;
}

