using namespace std;

int prim(int V, vector<vector<int>> cost) {
    vector<int> mincost(V, INF);
    vector<int> used(V, false);
    mincost[0] = 0;

    int res = 0;
    while (true) {
        int v = -1;
        // Xに属さない頂点のうちXからの辺のコストが最小になる頂点を探す
        for (int u = 0; u < V; ++u) {
            if (!used[u] && (v == -1 || mincost[u] < mincost[v])) {
                v = u;
            }
        }

        if (v == -1) {
            break;
        }
        used[v] = true;
        res += mincost[v];
        for (int u = 0 ; u < V; ++u) {
            mincost[u] = min(mincost[u], cost[v][u]);
        }
    }
    return res;
}

