class UnionFind
{
public:
    UnionFind(int n)
        : m_n(n), m_rank(m_n, 0)
    {
        m_par.resize(m_n);
        rep(i, m_n)
        {
            m_par[i] = i;
        }
    }

    int find(int x)
    {
        if (m_par[x] == x)
        {
            return x;
        }
        else
        {
            return m_par[x] = find(m_par[x]);
        }
    }

    void unite(int x, int y)
    {
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (m_rank[x] < m_rank[y])
        {
            m_par[x] = y;
        }
        else
        {
            m_par[y] = x;
            if (m_rank[x] == m_rank[y])
                ++m_rank[x];
        }
    }

    bool same(int x, int y)
    {
        return find(x) == find(y);
    }

private:
    int m_n;
    vint m_par;
    vint m_rank;
};

