class UnionFind {
public:
    vector<ll> par; // 親
    vector<ll> rank; // 木の深さ

    explicit UnionFind(unsigned int n) {
        par.resize(n);
        rank.resize(n);
        rep(i, n) {
            par[i] = i;
            rank[i] = 0;
        }
    }

    // 木の根を求める
    ll find(ll x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    // xとyの属する集合を併合
    void unite(ll x, ll y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (rank[x] == rank[y]) rank[x]++;
        }
    }

    // xとyが同じ集合に属するか否か
    bool is_same(ll x, ll y) {
        return find(x) == find(y);
    }
};

bool comp(const edge &e1, const edge &e2) {
    return e1.cost < e2.cost;
}

// 頂点数V, 辺の数E
vector<edge> es;
ll n;

// 最小全域木のコストの和を返す．
ll kruskal() {
    sort(es.begin(), es.end(), comp);
    UnionFind u = UnionFind(n);
    ll res = 0;
    each(e, es) {
        if (!u.is_same(e.u, e.v)) {
            u.unite(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}

