#include <bits/stdc++.h>
using namespace std;

struct UnionFind{
    vector<int> par;
    vector<int> dep;

    UnionFind(int siz){
        par.assign(siz, 0);
        dep.assign(siz, 0);
        for(int i = 0; i < siz; i++){
            par[i] = i;
        }
    };

    int find(int x){
        if(par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return;
        if(dep[x] < dep[y]) par[x] = y;
        else{
            par[y] = x;
            if(dep[x] == dep[y]) dep[x]++;
        }
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }
};

struct edge{int from, to, cost;};

bool comp(const edge& e1, const edge& e2){
    return e1.cost < e2.cost;
}

int main(){
    int n; cin >> n;
    vector<long long> x(n), y(n);
    for(int i = 0; i < n ; i++) cin >> x[i] >> y[i];

    vector<edge> e;

    vector<int> ids(n);
    iota(ids.begin(), ids.end(), 0);
    sort(ids.begin(), ids.end(), [&](int i, int j) { return x[i] < x[j]; });

    for(int i = 0; i < ids.size()-1; i++){
        int u = ids[i], v = ids[i+1];
        e.push_back({u, v, x[v] - x[u]});
    }

    sort(ids.begin(), ids.end(), [&](int i, int j) { return y[i] < y[j]; });
    for(int i = 0; i < ids.size()-1; i++){
        int u = ids[i], v = ids[i+1];
        e.push_back({u, v, y[v] - y[u]});
    }

    sort(e.begin(), e.end(), comp);
    UnionFind uf(n);
    long long res = 0;
    for(auto E: e){
        int u = E.from, v = E.to;
        long long cost = E.cost;
        if(uf.same(u, v)) continue;
        uf.unite(u, v);
        res += cost;
    }
    cout << res << endl;
}

