struct Nyaa
{
	ll town;
	ll x;
	ll y;
};

auto NyaaSortX = [](const Nyaa& l, const Nyaa& r)
{	// 降順は演算子>, 昇順は演算子<, if順の優先でソートされる
	if (l.x != r.x) return l.x < r.x;
	return l.y < r.y;
};

auto NyaaSortY = [](const Nyaa& l, const Nyaa& r)
{	// 降順は演算子>, 昇順は演算子<, if順の優先でソートされる
	if (l.y != r.y) return l.y < r.y;
	return l.x < r.x;
};

int main(void)
{
	ll N; cin >> N;
	vt<Nyaa> nyaa(N); each(i, e, nyaa) e.town = i, cin >> e.x >> e.y;
	each(i, e, nyaa) --e.x, --e.y;

	vector<vector<pair<long long, long long>>> lg(N);
	sort(all(nyaa), NyaaSortX);
	rep(i, 1, N)
	{
		lg[nyaa[i].town].push_back({ nyaa[i - 1].town, abs(nyaa[i].x - nyaa[i - 1].x) });
		lg[nyaa[i - 1].town].push_back({ nyaa[i].town, abs(nyaa[i - 1].x - nyaa[i].x) });
	}
	sort(all(nyaa), NyaaSortY);
	rep(i, 1, N)
	{
		lg[nyaa[i].town].push_back({ nyaa[i - 1].town, abs(nyaa[i].y - nyaa[i - 1].y) });
