template <typename T>
class UnionFindTree
{
public:
    UnionFindTree(T size = 0)
    {
        if (size == 0)
            return;

        unitedSize.resize(size + 1, 1);
        rank.resize(size + 1, 0);
        parents.resize(size + 1);
        for (T i=0; i<size; ++i)
            parents[i] = i;
    }

    bool Union(T x, T y)
    {
        x = FindRoot(x);
        y = FindRoot(y);
        if (x == y)
            return false;

        if (rank[x] < rank[y])
        {
            parents[x] = y;
            unitedSize[y] += unitedSize[x];
            if (rank[y] == rank[x])
                rank[y]++;
        }
        else
        {
            parents[y] = x;
            unitedSize[x] += unitedSize[y];
            if (rank[x] == rank[y])
                rank[x]++;
        }

        return true;
    }

    T FindRoot(T x)
    {
        if (parents[x] == x)
            return x;

        while (parents[x] != x)
        {
            T parent = parents[x];
            parents[x] = parents[parent];
            x = parents[x];
        }

        return x;
    }

    bool IsUnited(T a, T b)
    {
        return FindRoot(a) == FindRoot(b);
    }

private:
    std::vector<T> parents;
    std::vector<T> rank;
    std::vector<T> unitedSize;
};

class Edge
{
public:
    Edge(ll from, ll to, long double weight)
    {
        From = from;
        To = to;
        Weight = weight;
    }

    ll From;
    ll To;
    long double Weight;
};

long double MSTWeight(int nodeNum, const std::vector<Edge>& edgeList)
{
    UnionFindTree<int> vertexTree(nodeNum);

    // weight の昇順
    auto comp = ([](const Edge& lhs, const Edge& rhs) {
        return rhs.Weight < lhs.Weight;
    });

    std::priority_queue<Edge, std::vector<Edge>, decltype(comp)> edges {comp};
    for (auto& e : edgeList)
        edges.push(e);

    long double result = 0;
    while (!edges.empty())
    {
        auto minEdge = edges.top();
        edges.pop();
        if (!vertexTree.IsUnited(minEdge.From, minEdge.To) || minEdge.Weight < 0)
        {
            vertexTree.Union(minEdge.From, minEdge.To);
            result += minEdge.Weight;
        }
    }

    return result;
}

int main()
{
    ll N;
    std::cin >> N;
    std::vector<std::pair<ll, ll>> towns(N, std::pair<ll, ll>(0, 0));
    for (auto i=0; i<N; ++i)
        std::cin >> towns[i].first >> towns[i].second;

    std::vector<Edge> edges;
    for (auto i=0; i<N; ++i)
    {
        for (auto j=0; j<i; ++j)
        {
            auto vertical = std::abs(towns[i].first - towns[j].first);
            auto horizontal = std::abs(towns[i].second - towns[j].second);
            auto cost = std::min(vertical, horizontal);
            edges.emplace_back(Edge(i, j, cost));
        }
    }

    std::cout << MSTWeight(N, edges) << std::endl;
}

