class unionfind {
public:
	int N;
	vector<int> par;
	vector<int> buf;
	unionfind(int n) :N(n) {
		par.resize(N);
		buf.reserve(N);
		for (int i = 0; i < n; ++i)par[i] = i;
	}

	int getpar(int ind) {
		buf.clear();
		while (par[ind] != ind) {
			buf.push_back(ind);
			ind = par[ind];
		}
		for (int i = 1; i < buf.size(); ++i) par[buf[i]] = ind;
		return ind;
	}

	void merge(int ind1, int ind2) {
		int par1 = getpar(ind1);
		int par2 = getpar(ind2);
		par[par1] = par[par2];
	}

	bool same(int ind1, int ind2) { return getpar(ind1) == getpar(ind2); }
};

