	auto cmpedge = [](edge a, edge b) {return a.cost > b.cost; };
	auto dist = [](pair<ll, ll> a, pair<ll, ll> b) {return min(abs(a.first - b.first), abs(a.second - b.second)); };
	vector<int> ix(N), iy(N);
	REP(i, 0, N) ix[i] = i;
