	priority_queue<edge, vector<edge>, decltype(cmpedge)> q(cmpedge);
	REP(i, 0, N - 1) q.push(edge{ ix[i],ix[i + 1],dist(p[ix[i]],p[ix[i + 1]]) });
	REP(i, 0, N - 1) q.push(edge{ iy[i],iy[i + 1],dist(p[iy[i]],p[iy[i + 1]]) });
	unionfind u{ (int)N };
	ll ans = 0;
