const int MAX_V = 200005;
const int MAX_E = 200005;
int V; // 頂点数
int E; // 辺の本数

struct edge{ int u, v, cost;};
edge es[MAX_E];

struct UnionFind {
  vector<int> d;
  UnionFind(int n): d(n,-1) {}
  int find(int x) {
    if (d[x] < 0) return x;
    return d[x] = find(d[x]);
  }
  bool unite(int x, int y) {
    x = find(x); y = find(y);
    if (x == y) return false;
    if (d[x] > d[y]) swap(x,y); // -d[x] < -d[y]
    d[x] += d[y];
    d[y] = x;
    return true;
  }
  bool same(int x, int y) { return find(x) == find(y);}
  int size(int x) { return -d[find(x)];}
};

// クラスカル法: 最小全域木のコストの合計値を返す O(|E|log|V|)
int kruskal() {
  auto comp = [](const edge& e1, const edge& e2) {
    return e1.cost < e2.cost;
  };
  sort(es, es + E, comp);
  UnionFind uf(MAX_V);
  int res = 0;
  for (int i = 0; i < E; ++i) {
    edge e = es[i];
    if (!uf.same(e.u, e.v)) {
      uf.unite(e.u, e.v);
      res += e.cost;
    }
  }
  return res;
}

