struct UnionFind {
  vector<int> parent, size;
  UnionFind(int n) : parent(n), size(n, 1) {
    rep(i,n) parent[i] = i;
  }
  int root(int v) {
    while(parent[v] != v) {
      parent[v] = parent[parent[v]];
      v = parent[v];
    }
    return v;
  }
  void unite(int v, int u) {
    v=root(v), u=root(u);
    if(size[u] < size[v]) swap(u,v);
    parent[v] = u;
    size[u] += size[v];
  }
  int find(int v, int u) {
    return root(v) == root(u);
  }
};

