    edge[v[i].se].push_back(make_pair(now, v[i - 1].se));
    edge[v[i - 1].se].push_back(make_pair(now, v[i].se));
  }
  for(int i = 0; i < n; ++i) swap(v[i].fi.fi, v[i].fi.se);
  sort(v.begin(), v.end());
