long long solve() {
  long long ans = 0;
  for(int i = 1; i < n; ++i) dis[i].fi = inf;
  pq.push(make_pair(0, 0));
  while(pq.size() > 0) {
    p now = pq.top();
    pq.pop();
    for(int i = 0; i < edge[now.se].size(); ++i) {
      p nextp = now;
      nextp.se = edge[now.se][i].se;
      nextp.fi += edge[now.se][i].fi;
      if(dis[nextp.se].fi >= nextp.fi) {
        if(dis[nextp.se].fi > nextp.fi) pq.push(nextp);
        dis[nextp.se].fi = nextp.fi;
        dis[nextp.se].se = now.se;
        mp[make_pair(nextp.se, now.se)] =
            edge[now.se][i].fi;
      }
    }
  }
  for(int i = 1; i < n; ++i)
    if(!ch[make_pair(i, dis[i].se)]) {
      ans += mp[make_pair(i, dis[i].se)];
      ch[make_pair(i, dis[i].se)] = 1;
    }
  return ans;
}

