class UnionFind {
public:
    vector<int> par;
    vector<int> rnk;
    vector<ll> siz;
    UnionFind(int N):par(N),rnk(N),siz(N){
        for(int i=0;i<N;i++){
            par[i]=i,rnk[i]=0,siz[i]=1;
        }
    }
    //根
    int find(int x){
        if(par[x]==x)return x;
        return par[x]=find(par[x]);
    }
    void unite(int x,int y){
        int rx=find(x);
        int ry=find(y);
        if (rx==ry) return;
        if(rnk[rx]<rnk[ry]){
            par[rx]=ry;
            siz[ry]+=siz[rx];
            siz[rx]=0;
        }
        else{
            par[ry]=rx;
            siz[rx]+=siz[ry];
            siz[ry]=0;
            if(rnk[rx]==rnk[ry]){
                rnk[rx]++;
            }
        }
    }
    //集合が同じか
    bool same(int x, int y){
        return find(x)==find(y);
    }
    //集合の大きさ
    int size(int x){
        return siz[find(x)];
    }
};

int N;

priority_queue<pair<ll,P>,vector<pair<ll,P>>,greater<pair<ll,P>>> que;

ll kruskal() {
    UnionFind uf(N);
    ll cost=0;
    while(que.size()){
        pair<ll,P> x=que.top();
        que.pop();
        if(uf.same(x.second.first,x.second.second))continue;
        else{
            uf.unite(x.second.first,x.second.second);
            cost+=x.first;
        }
    }
    return cost;
}

