using namespace std;

typedef pair<int,int> pii;

struct edge{int u, v; llong cost;};

void init(int par[], int V){
  for(int i = 0; i < V; ++i)
    par[i] = i;
}

int find(int x, int par[]){
  if(par[x] == x){
    return x;
  }else{
    return par[x] = find(par[x], par);
  }
}

void unite(int x, int y, int par[], int rank[]){
  x = find(x, par);
  y = find(y, par);

  if(x == y)
    return;

  if(rank[x] > rank[y]){
    par[y] = x;
  }else{
    par[x] = y;
    if(rank[x] == rank[y])
      rank[y]++;
  }
}

int same(int x, int y, int par[]){
  return find(x, par) == find(y, par);
}

bool comp(const edge& e1, const edge& e2){
  return e1.cost < e2.cost;
}

llong kruskal(int V, int E, vector<edge> es){
  sort(ALL(es), comp);
  int *par, *rank;

  par = new int[V];
  rank = new int[V];

  init(par, V);
  REP(i,V){
    rank[i] = 0;
  }

  llong res = 0;
  REP(i,E){
    edge e = es[i];
    if(!same(e.u, e.v, par)){
      unite(e.u, e.v, par, rank);
      res += e.cost;
    }
  }

  delete[] par;
  delete[] rank;

  return res;
}

int main(){

  int n;
  scanf("%d", &n);

  vector<pii> x, y;
  REP(i,n){
    int tx, ty;
    scanf("%d %d", &tx, &ty);
    x.push_back({tx, i});
    y.push_back({ty, i});
  }

  SORTV(x); SORTV(y);

  vector<edge> v;
  REP(i,n - 1){
    v.push_back({x[i].second, x[i + 1].second, x[i + 1].first - x[i].first});
    v.push_back({y[i].second, y[i + 1].second, y[i + 1].first - y[i].first});
  }

  printf("%lld\n", kruskal(n, (int)v.size(), v));

  return 0;
}

