struct UnionFind
{
    int i;
    vector<int> par;
    vector<int> size;
    UnionFind(int n): par(n),size(n,1){
        for(i = 0;i < n;++i){
            par.at(i) = i;
        }
    }

    int root(int x){
        if(par.at(x) == x){
            return x;
        }else{
            return par.at(x) = root(par.at(x));
        }
    }

    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if(rx == ry){
            return;
        }else{
            if(size.at(rx) < size.at(ry)){
                swap(rx,ry);
            }
            par.at(ry) = rx;
            size.at(rx) += size.at(ry);
            return;
        }
    }

    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    int get_size(int x){
        return size.at(root(x));
    }
};

int main()
{
    ll i,j;
    ll n;
    cin >> n;
    vector<ll> x(n);
    vector<ll> y(n);
    for(i = 0;i < n;++i){
        cin >> x.at(i) >> y.at(i);
    }

    priority_queue<pair<ll,pair<ll,ll>>> pq; //優先度付きキュー

    vector<ll> ids(n);
    iota(all(ids), 0);
    sort(all(ids), [&](ll i, ll j){ return x.at(i) < x.at(j);});
    for(i = 0;i + 1 < ids.size();++i){
        ll u = ids.at(i);
        ll v = ids.at(i+1);
        pq.emplace(x.at(u) - x.at(v),make_pair(u,v));
    }
    sort(all(ids), [&](ll i, ll j){ return y.at(i) < y.at(j);});
    for(i = 0;i + 1 < ids.size();++i){
        ll u = ids.at(i);
        ll v = ids.at(i+1);
        pq.emplace(y.at(u) - y.at(v),make_pair(u,v));
    }

    ll ans = 0; //最小全域木の重み

    UnionFind uf(n); //連結管理(UnionFind)
    while(!pq.empty()){
        auto x = pq.top();
        pq.pop();
        ll w = -x.first;
        ll s = x.second.first;
        ll t = x.second.second;
        if(uf.same(s,t)) continue; //連結は排除
        ans += w;
        uf.unite(s,t);
    }

    cout << ans << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

