void solve()
{
    ll n;
    cin >> n;
    Kruskal<ll> K(n+1);
    vector<PL> x, y;
    for(int i=0; i < n; i++){
        ll a, b;
        cin >> a >> b;
        x.push_back({a,i});
        y.push_back({b,i});
    }
    sort(ALL(x));
    sort(ALL(y));
    for(int i=0; i < n - 1; i++){
        K.add_edge(x[i].second, x[i + 1].second, abs(x[i].first - x[i + 1].first));
        K.add_edge(y[i].second, y[i + 1].second, abs(y[i].first - y[i + 1].first));
    }
    ll ans = K.build();
    cout << ans << endl;
}

