        x[i] = make_pair(a, i);
        y[i] = make_pair(b, i);
    }

    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    vector<p> n(2 * N - 2);

    for(int i = 0; i < N - 1; i++) {
        n[i] = make_pair(x[i + 1].first - x[i].first, make_pair(x[i + 1].second, x[i].second));
        n[i + N - 1] = make_pair(y[i + 1].first - y[i].first, make_pair(y[i + 1].second, y[i].second));
    }

    sort(n.begin(), n.end());

    UnionFind uf(N);

    ll ans = 0;

    for(int i = 0; i < 2 * N - 2; i++) {
        p q = n[i];
        ll l = q.first;
        int p1 = q.second.first;
        int p2 = q.second.second;
        if(uf.same(p1, p2)) continue;
        ans += l;
        uf.unite(p1, p2);
    }

    cout << ans << endl;
}

