const int N = 2E5 + 10;

int n, Root[N], Ranked[N], type = 1;
ii a[N], x[N], y[N];

void Input()
{
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i].X >> a[i].Y;
}

int Find_Root(int u)
{
    if (u == Root[u]) return u;
    return Root[u] = Find_Root(Root[u]);
}

bool Union(int u, int v)
{
    u = Find_Root(u);
    v = Find_Root(v);
    if (u == v) return false;

    if (Ranked[u] > Ranked[v]) swap(u, v);
    Root[u] = v;
    Ranked[v] += Ranked[u];

    return true;
}

ll Modify(int u, int v, int type)
{
    ll x = abs(a[u].X - a[v].X);
    ll y = abs(a[u].Y - a[v].Y);
    if (type == 1) return min(x, y);
    else return max(x, y);
}

void Solve(int type)
{
    ll res = 0;
    priority_queue <iii, vector <iii>, greater <iii> > PQ;
    for (int i = 1; i < n; i++)
    for (int j = i + 1; j <= n; j++) {
        ll Dist = Modify(i, j, type);
        PQ.push({Dist, {i, j}});
    }
    for (int i = 1; i <= n; i++) Root[i] = i, Ranked[i] = 1;

    int k = n - 1;
    while (k && PQ.size()) {
        ll Distance = PQ.top().X;
        int u = PQ.top().Y.X;
        int v = PQ.top().Y.Y;
        PQ.pop();
        if (Union(u, v)) {
            k--;
            res += Distance;
        }
    }

    cout << res;
}

