using namespace std;

struct UnionFind {
	vector<int> par;

	UnionFind(int n) : par(n, -1) { }
	void init(int n) { par.assign(n, -1); }

	int root(int x) {
		if (par[x] < 0) return x;
		else return par[x] = root(par[x]);
	}

	bool issame(int x, int y) {
		return root(x) == root(y);
	}

	bool merge(int x, int y) {
		x = root(x); y = root(y);
		if (x == y) return false;
		if (par[x] > par[y]) swap(x, y); // merge technique
		par[x] += par[y];
		par[y] = x;
		return true;
	}

	int size(int x) {
		return -par[root(x)];
	}
};

int main() {
	int N;
	cin >> N;
	vector<int>x(N);
	vector<int>y(N);
	for (int n = 0; n < N; ++n) {
		cin >> x[n] >> y[n];
	}

	// Kruskal 法で使用する枝
	using pint = pair<int, int>;
	using Edge = pair<long long, pint>;
	vector<Edge> edges;

	// x 軸方向にソートして隣接している部分のみ
	vector<int> ids(N);
	iota(ids.begin(), ids.end(), 0);
	sort(ids.begin(), ids.end(), [&](int i, int j) { return x[i] < x[j]; });
	for (int i = 0; i + 1 < ids.size(); ++i) {
		int u = ids[i], v = ids[i + 1];
		edges.push_back(Edge(x[v] - x[u], pint(u, v)));
	}

	// y 軸方向にソートして隣接している部分のみ
	sort(ids.begin(), ids.end(), [&](int i, int j) { return y[i] < y[j]; });
	for (int i = 0; i + 1 < ids.size(); ++i) {
		int u = ids[i], v = ids[i + 1];
		edges.push_back(Edge(y[v] - y[u], pint(u, v)));
	}

	// Kruskal 法
	sort(edges.begin(), edges.end());
	UnionFind uf(N);
	long long res = 0;
	for (auto e : edges) {
		int u = e.second.first, v = e.second.second;
		long long cost = e.first;
		if (uf.issame(u, v)) continue;
		uf.merge(u, v);
		res += cost;
	}
	cout << res << endl;
}

