struct UnionFind {
  vector<int> par;

  UnionFind(int n) : par(n, -1) {
  }

  int root(int x) {
    if (par[x] < 0)
      return x;
    else
      return par[x] = root(par[x]);
  }

  bool issame(int x, int y) {
    return root(x) == root(y);
  }

  void merge(int x, int y) {
    int rx = root(x), ry = root(y);
    if (rx == ry) return;
    if (-par[rx] < -par[ry]) swap(rx, ry);
    par[rx] += par[ry];
    par[ry] = rx;
  }
};

int main() {
  ios::sync_with_stdio(false);
