int main() {
    ll N;
    cin >> N;
    vector<city> cities(N);
    for (ll i = 0; i < N; i++) {
        cin >> cities[i].x;
        cin >> cities[i].y;
        cities[i].id = i;
    }
    vector<city> cities_x(N);
    vector<city> cities_y(N);
    copy(cities.begin(), cities.end(), cities_x.begin());
    copy(cities.begin(), cities.end(), cities_y.begin());

    sort(cities_x.begin(), cities_x.end(), [](city a, city b) { return a.x < b.x; });
    sort(cities_y.begin(), cities_y.end(), [](city a, city b) { return a.y < b.y; });

    vector<edg> dists;
    map<ll, vector<city>> same;
    for (ll i = 0; i < N; i++) {
        same[cities[i].x].push_back(cities[i]);
    }
    for (auto iter = same.begin(); iter != same.end(); iter++) {
        for (auto c1 : iter->second) {
            for (auto c2 : iter->second) {
                if (c1.id < c2.id) {
                    dists.push_back({u : c1.id, v : c2.id, cost : 0});
                }
            }
        }
    }
    for (ll i = 1; i < N; i++) {
        city x1 = cities_x[i - 1];
        city x2 = cities_x[i];
        if (x1.x != x2.x) {
            for (auto x1s : same[x1.x]) {
                for (auto x2s : same[x2.x]) {
                    dists.push_back({u : x1s.id, v : x2s.id, cost : x2s.x - x1s.x});
                }
            }
        }
    }
    same.clear();
    for (ll i = 0; i < N; i++) {
        same[cities[i].y].push_back(cities[i]);
    }
    for (auto iter = same.begin(); iter != same.end(); iter++) {
        for (auto c1 : iter->second) {
            for (auto c2 : iter->second) {
                if (c1.id < c2.id) {
                    dists.push_back({u : c1.id, v : c2.id, cost : 0});
                }
            }
        }
    }
    for (ll i = 1; i < N; i++) {
        city y1 = cities_y[i - 1];
        city y2 = cities_y[i];
        if (y1.y != y2.y) {
            for (auto y1s : same[y1.y]) {
                for (auto y2s : same[y2.y]) {
                    dists.push_back({u : y1s.id, v : y2s.id, cost : y2s.y - y1s.y});
                }
            }
        }
    }
    sort(dists.begin(), dists.end(), [](edg a, edg b) { return a.cost < b.cost; });

    iunionfind* uf = new iunionfind(N);
    ll total_cost = 0;
    for (auto edg : dists) {
        if (uf->same(edg.u, edg.v)) {
            continue;
        }
        total_cost += edg.cost;
        uf->unite(edg.u, edg.v);
    }
    cout << total_cost << endl;
}

