int main()
{
	int n;
	cin >> n;
	vector<pair<long long int, long long int>> points(n);
	vector<int> xpoints(n);
	vector<int> ypoints(n);
	vector<bool> flag(n, false);
	for (int i = 0; i < n; i++)
	{
		long long int x, y;
		cin >> x >> y;
		points[i] = make_pair(x, y);
		xpoints[i] = i;
		ypoints[i] = i;
	}
	auto comparex = [&points](int a, int b) -> bool
	{
		return points[a].first < points[b].first;
	};
	auto comparey = [&points](int a, int b) -> bool
	{
		return points[a].second < points[b].second;
	};
	sort(xpoints.begin(), xpoints.end(), comparex);
	sort(ypoints.begin(), ypoints.end(), comparey);

	//プリム法の実装
	struct node
	{
		int index;
		pair<long long int, long long int> dist;
		node* next;
		node(int index, pair<long long int, long long int> dist, node* next)
		{
			this->index = index;
			this->dist = dist;
			this->next = next;
		}
	};
	vector<node*> graph(n);
	for (int i = 0; i < n; i++)
	{
		node* head = new node(i, points[i], nullptr);
		graph[i] = head;
	}
	for (int i = 0; i < n; i++)
	{
		if (i == 0)
		{
			node* newnode = new node(xpoints[i + 1], points[xpoints[i + 1]], nullptr);
			node* head = graph[xpoints[i]];
			while (head->next != nullptr)
			{
				head = head->next;
			}
			head->next = newnode;
		}
		else if(i == n - 1){
			node* newnode = new node(xpoints[i - 1], points[xpoints[i - 1]], nullptr);
			node* head = graph[xpoints[i]];
			while (head->next != nullptr)
			{
				head = head->next;
			}
			head->next = newnode;
		}
		else {
			node* newnode1 = new node(xpoints[i - 1], points[xpoints[i - 1]], nullptr);
			node* newnode2 = new node(xpoints[i + 1], points[xpoints[i + 1]], nullptr);
			newnode1->next = newnode2;
			node* head = graph[xpoints[i]];
			while (head->next != nullptr) head = head->next;
			head->next = newnode1;
		}
	}
	for (int i = 0; i < n; i++)
	{
		if (i == 0)
		{
			node* newnode= new node(ypoints[i + 1], points[ypoints[i + 1]], nullptr);
			node* head = graph[ypoints[i]];
			while (head->next != nullptr)
			{
				head = head->next;
			}
			head->next = newnode;
		}
		else if(i == n - 1){
			node* newnode= new node(ypoints[i - 1], points[ypoints[i - 1]], nullptr);
			node* head = graph[ypoints[i]];
			while (head->next != nullptr)
			{
				head = head->next;
			}
			head->next = newnode;
		}
		else {
			node* newnode1 = new node(ypoints[i - 1], points[ypoints[i - 1]], nullptr);
			node* newnode2 = new node(ypoints[i + 1], points[ypoints[i + 1]], nullptr);
			newnode1->next = newnode2;
			node* head = graph[ypoints[i]];
			while (head->next != nullptr) head = head->next;
			head->next = newnode1;
		}
	}
	int cost = 0;
	flag[0] = true;
	vector<int> visited;
	visited.push_back(0);
	while (visited.size() != n)
	{
		int index;
		int temp = 1000000000;
		for (auto i : visited)
		{
			node* head = graph[i]->next;
			while (head->next != nullptr)
			{
				int xdist = abs(graph[i]->dist.first - head->dist.first);
				int ydist = abs(graph[i]->dist.second - head->dist.second);
				int mindist = xdist <= ydist ? xdist : ydist;
				if (mindist < temp && flag[head->index] == false)
				{
					index = head->index;
					temp = mindist;
				}
				head = head->next;
			}
		}
		flag[index] = true;
		cost += temp;
		visited.push_back(index);
	}
	cout << cost << endl;
}

