void init (int n) {
	par.resize(n);
	r.resize(n);
	for (int i = 0; i < n; i++) {
		par[i] = i;
		r[i] = 0;
	}
}

int find(int x) {
    if (par[x] == x) {
		return x;
    } else {
		return par[x] = find(par[x]);
    }
}

void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;

    if (r[x] < r[y]) {
		par[x] = y;
    } else {
		par[y] = x;
		if (r[x] == r[y]) r[x]++;
    }
}

bool same(int x, int y) {
    return find(x) == find(y);
}

struct edge {int u, v; ll cost;};
bool comp(const edge&  e1, const edge& e2) {
	return e1.cost < e2.cost;
}

edge es[SIZE];
int V, E;
ll kruscal() {
	sort(es, es + E, comp);
	init(V);
	ll res = 0;
	for (int i = 0; i < E; i++) {
		edge e = es[i];
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}


