class DisjointSet{
    public:
        vector<int> rank,p;

        DisjointSet(){}

        //初期化
        DisjointSet(int size){
            rank.resize(size,0);
            p.resize(size,0);
            rep(i,size){
                makeSet(i);
            }
        }        
        void makeSet(int x){
            p[x]=x;
            rank[x]=0;
        }

        bool same(int x,int y){
            return findSet(x)==findSet(y);
        }

        void unite(int x,int y){
            link(findSet(x),findSet(y));
        }

        void link(int x,int y){
            if(rank[x]>rank[y]){
                p[y]=x;
            }
            else{
                p[x]=y;
                if(rank[x]==rank[y]){
                    rank[y]++;
                }
            }
        }

        int findSet(int x){
            if(x!=p[x]){
                p[x]=findSet(p[x]);
            }
            return  p[x];
        }
};

class Edge{
    public:
    ll  source,target,cost;
    Edge(ll source=0,ll  target=0,ll cost=0):
    source(source),target(target),cost(cost){}
    bool operator < (const Edge &e) const{
        return cost < e.cost;
    }
};

ll kruskal(ll N,vector<Edge> edges){
    ll totalCost = 0;
    sort(edges.begin(),edges.end());
    DisjointSet dset = DisjointSet(N+1);
    rep(i,N){
        dset.makeSet(i);
    }
    ll source,target;
    rep(i,edges.size()){
        Edge e = edges[i];
        if(!dset.same(e.source,e.target)){
            //MST.push_back(e);
            totalCost += e.cost;
            dset.unite(e.source,e.target);
        }
    }
    return totalCost;
}

