ll root(ll x){
  if(par[x] == x) return x;
  return root(par[x]);
}

void unite(ll x, ll y){
  ll rx = root(x);
  ll ry = root(y);
  if(rx == ry) return;
  par[rx] = ry;
}

bool same(ll x, ll y){
  ll rx = root(x), ry = root(y);
  return rx == ry;
}


