    }

    sort(pa_x.begin(),pa_x.end());
    sort(pa_y.begin(),pa_y.end());

    vector<edge> e;
    for(int i=0;i<n-1;i++){
        edge tmp={pa_x[i].second.second,pa_x[i+1].second.second,pa_x[i+1].first-pa_x[i].first};
        e.push_back(tmp);
        tmp={pa_x[i+1].second.second,pa_x[i].second.second,pa_x[i+1].first-pa_x[i].first};
