class UnionFindTree
{
public:

	UnionFindTree(size_t n)
		: m_parent(n)
		, m_rank(n, 0)
	{
		for (size_t i = 0; i < n; i++) {
			m_parent[i] = static_cast<i32>(i);
		}
	}

	void Unite(i32 x, i32 y)
	{
		x = findParent(x);
		y = findParent(y);
		if (x == y) return;
		if (m_rank[x] < m_rank[y]) {
			m_parent[x] = y;
		} else {
			m_parent[y] = x;
			if (m_rank[x] = m_rank[y]) m_rank[x]++;
		}
	}

	bool InSameGroup(i32 x, i32 y)
	{
		return findParent(x) == findParent(y);
	}

private:

	i32 findParent(i32 x)
	{
		if (m_parent[x] == x) {
			return x;
		} else {
			return m_parent[x] = findParent(m_parent[x]);
		}
	}

	vector<i32> m_parent;
	vector<i32> m_rank;
};

struct edge {
	i32 u;
	i32 v;
	i32 cost;

	edge(i32 u_, i32 v_, i32 cost_): u(u_), v(v_), cost(cost_)
	{}
};

i32 Kruskal(vector<edge> &edges, size_t num_vertices)
{
	sort(edges.begin(), edges.end(), [](const edge& e1, const edge& e2) {
		return e1.cost < e2.cost;
	});
	UnionFindTree t(num_vertices);
	i32 sumCost = 0;
	for (const auto& e : edges) {
		if (!t.InSameGroup(e.u, e.v)) {
			t.Unite(e.u, e.v);
			sumCost += e.cost;
		}
	}
	return sumCost;
}

int main()
{
	i32 N;
	cin >> N;
	vector<pii> xsorted;
	vector<pii> ysorted;
	REP(i, N) {
		i32 x, y;
		cin >> x >> y;
		xsorted.emplace_back(mp(x, i));
		ysorted.emplace_back(mp(y, i));
	}

	sort(xsorted.begin(), xsorted.end());
	sort(ysorted.begin(), ysorted.end());

	vector<edge> edges;

	REP(i, N - 1) {
		edges.emplace_back(
			xsorted[i].second,	// u
			xsorted[i + 1].second, // v
			xsorted[i + 1].first - xsorted[i].first // cost
		);
		edges.emplace_back(
			ysorted[i].second,	// u
			ysorted[i + 1].second, // v
			ysorted[i + 1].first - ysorted[i].first // cost
		);
	}

	printf("%d\n", Kruskal(edges, N));

	return 0;
}

