int main() {
    u32 N;
    IN(N);
    REP(i, N) {
        cin >> x[i] >> y[i];
    }
    auto q = priority_queue<pair<u32, u32>, vector<pair<u32, u32>>,
         greater<pair<u32, u32>>>();
    used[0] = true;
    REP(i, N) {
        u32 cost = calc(x[0], y[0], x[i], y[i]);
        q.push(MP(cost, i));
    }
    u32 ans = 0;
    u32 remain = N-1;
    while(!q.empty()) {
        auto vi = q.top();
        q.pop();
        auto v = vi.first;
        auto index = vi.second;
        if(used[index]) {
            continue;
        }
        ans += v;
        if(!--remain) {
            break;
        }
        used[index] = true;
        REP(i, N) {
            if(used[i]) {
                continue;
            }
            u32 cost = calc(x[index], y[index], x[i], y[i]);
            q.push(MP(cost, i));
        }
    }
    cout << ans << endl;
    return 0;
}

