void init(int n) {
    rep(i, n) par[i] = i;
}

int root(int x) {
    if (par[x] == x) {
        return x;
    } else {
        par[x] = root(par[x]);
        return par[x];
    }
}

bool same(int x, int y) {
    return root(x) == root(y);
}

void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;
    par[x] = y;
}

ll kruskal(int n) {
