/*使い方
UnionFind a(N);//初期化、N個の頂点を考える

Int b = a.root(x);//頂点xの親が返る
bool c = a.same(x,y);//xとyが同じ集合→trueが返る
Int d = a.size(x);//頂点xの属する集合の要素数が返る

a.unite(x,y);//頂点xとyを連結する
（xとyが元々同じ集合に属している場合falseが、元々異なる集合に属している場合trueが返るようになっている）

*/

class UnionFind {
private:
	vector<Int> data;//data[i]:頂点iの親（頂点番号）

public:
	UnionFind(Int size) : data(size, -1) { }//全ての頂点の親を-1で初期化
	Int root(Int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }//data[i]が負なら頂点i自身が親であり、その時さらに-data[i]は集合の要素数を表す
	bool same(Int x, Int y) { return root(x) == root(y); }//頂点xとyが同じ集合に属するかどうか
	Int size(Int x) { return -data[root(x)]; }//頂点xの含まれる集合の要素数

	bool unite(Int x, Int y) {//頂点xとyを同じ集合に連結する
		x = root(x); y = root(y);
		if (x != y) {//頂点xとyが元々違う集合に属していた場合
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
			return true;//連結したという意味でtrueが返る
		}
		else {//頂点xとyが元々同じ集合に属していた場合
			return false;//連結を行わなかったという意味でfalseが返る
		}
	}
};

template<class T = Int>
struct Edge {
	Int to;
	T cost;
	Edge() {}
	Edge(Int to, T cost) : to(to), cost(cost) {}
	bool operator>(const Edge& r) const { return this->cost > r.cost; }
};

template<class T>
vector<T> Dijkstra(vector<vector<Edge<T>>>& edges, Int st) {

	Int V = (Int)edges.size();
	const T inf = numeric_limits<T>::max() / 2;
	vector<T> cost(V, inf);
	cost[st] = 0;

	priority_queue<Edge<T>, vector<Edge<T>>, greater<Edge<T>>> p_que;//要素の型はEdge<T>、内部コンテナはvector<Edge>>、昇順
	p_que.emplace(st, cost[st]);

	while (!p_que.empty()) {

		Edge<T> now(p_que.top().to, p_que.top().cost);//now.to: 配る側になった頂点 now.cost: その頂点の最小コスト
		p_que.pop();

		//↓この一行、有向グラフ（行きと帰りで辺の重みが違う場合）で威力を発揮、オーダーレベルで計算量が異なることも
		//後からキューに入れたものが追い越した場合、追い越されたものはオワコンになる
		if (cost[now.to] < now.cost) continue;


		for (const Edge<T>& e : edges[now.to]) {
			T tmp_cost = now.cost + e.cost;
			if (cost[e.to] > tmp_cost) {
				cost[e.to] = tmp_cost;
				p_que.emplace(e.to, cost[e.to]);
			}
		}
	}

	return cost; // min cost to vertex idx from st
}

