    int to, from, cost;
};
static vector<edge> E;
int V;
P x[MAXV], y[MAXV];

static int ran[MAXV];
static int parent[MAXV];

void init_union_find(int n){
    for(int i = 0;i < n;i++){
        ran[i] = 0;
        parent[i] = i;
    }
    return;
}

int find(int c){
    if(parent[c] == c) return c;
    return parent[c] = find(parent[c]);
}

bool same(int l, int r){
    return find(l) == find(r);
}

void link(int l, int r){
    l = find(l);
    r = find(r);
    if(l == r) return;

    if(ran[l] < ran[r]){
        parent[l] = r; 
    }else {
        parent[r] = l;
        if(ran[l] == ran[r]){
            ran[l]++;
        }
    }

    return;
}

bool comp(const edge &e1, const edge &e2){
    return e1.cost < e2.cost;
}

int kruskal(){
    int sum = 0;
    init_union_find(V);
    sort(E.begin(), E.end(), comp);
    for(int i = 0;i < E.size();i++){
        const edge &e = E[i];
        if(!same(e.from, e.to)){
            link(e.from, e.to);
            sum += e.cost;
        }
    }

    return sum;
}

