	if(x1.x == x2.x)
		return x1.y < x2.y; 
	return x1.x < x2.x;
}
bool comy(point y1, point y2) {
	if(y1.y == y2.y)
		return y1.x < y2.x;
	return y1.y < y2.y;
}
