    return p[x] == x ? x : p[x] = find(p[x]);
}
ll Kruskal() {
    ll ans = 0, sum = 0, u, v, w;
    for(ll i = 0; i <= n; i++)
        p[i] = i;
    sort(edge, edge + cnt, cmp);
    for(int i = 0; i < cnt; i++) {
