struct UnionFind{
    vector<int> data;

    UnionFind(int sz) {
    data.assign(sz, -1);
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);//親は負でサイズを保存
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  bool same(int x, int y){
      return find(x) == find(y);
  }

  int size(int k) {
    return (-data[find(k)]);
  }
};

struct Edge{long long u,v,cost;};
using Edges = vector<Edge>;

bool comp(const Edge &a, const Edge &b){
    return a.cost < b.cost;
}


int kruskal(Edges &es,int V){
    sort(es.begin(),es.end(),comp);
    UnionFind uf(V);
    int res = 0;
    for(auto e : es){
        long long cost = e.cost;
        int u = e.u,v = e.v;
        if(!uf.same(u,v)){
            uf.unite(u,v);
            res += cost;
        }
    }
    return res;
}

