struct UnionFind
{
    // data 中の負数の要素が根となる
    // 根は集合のデータ数を負数でもつ
    vector<int> data;
    UnionFind(int size) : data(size, -1) {}

    // マージする. すでに同じ集合なら false を返す
    bool merge(int x, int y)
    {
        x = root(x);
        y = root(y);
        if (x == y)
            return false;
        if (data[y] < data[x])
            swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }

    int root(int x)
    {
        return data[x] < 0 ? x : (data[x] = root(data[x]));
    }

    int size(int x)
    {
        return -data[root(x)];
    }
    bool issame(int x, int y)
    {
        return root(x) == root(y);
    }
};

