			}
			for (int j = 0; j < connected.size(); j++) {
				int temp = min(abs(xs[i] - xs[connected[j]]), abs(ys[i] - ys[connected[j]]));
				if (temp < min_cost) {
					min_index = i;
					min_cost = temp;
				}
			}
		}
		connected.push_back(min_index);
		cost += min_cost;
		visited[min_index] = 1;
	}
	cout << cost << endl;
}

