using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;
static const ll INF=1e18;
static const ll MAX=101010;
static const ll MOD=1e9+7;
static const ll LOGN=55;


class Edge {
public:
  ll t, w;
  Edge(ll t, ll w): t(t), w(w){}
};

vector<Edge> g[MAX*2];
ll N;
P x[MAX], y[MAX];

ll solve() {
  ll clr[MAX]={};
  ll d[MAX];
  ll i;
  priority_queue<P> q;
  q.push({0, 0});

  for(i=0; i<N; i++) d[i]=INF;
  d[0]=0;

  while(q.size()) {
    P f=q.top(); q.pop();
    ll u=f.second;

    if(d[u]<-f.first) continue;
    clr[u]=1;

    for(i=0; i<g[u].size(); i++) {
      Edge e=g[u][i];

      if(clr[e.t]) continue;
      if(d[e.t]<=e.w) continue;

      d[e.t]=e.w;
      q.push({-d[e.t], e.t});

    }

  }

  ll res=0;
  for(i=0; i<N; i++) res+=d[i];

  return res;
}

