class unionfind {
    vector<int64> _size;
    vector<int64> _root;
public:
    unionfind(int n) {
        _size = vector<int64> (n+1, 1);
        _root = vector<int64> (n+1);
        iota(_root.begin(), _root.end(), 0);
    }
    int64 root(int x) {
        while(x != _root[x]) x = _root[x];
        return x;
    }
    bool merge(int x, int y) {
        if (is_same(x,y)) return false;
        x = root(x); y = root(y);
        if (_size[x] > _size[y]) swap(x,y);
        _size[y] += _size[x];
        _root[x] = y;
        return true;
    }
    int64 is_same(int x, int y) {
        return root(x) == root(y);
    }
    int64 size(int x) {
        return _size[root(x)];
    }
};

int64 kruskal(const int& n,vector<edge>& edges) {

    auto cmp = [](edge x, edge y) {return x.cost < y.cost;};
    sort(edges.begin(), edges.end(), cmp);
    unionfind uni(n);
    int res = 0;
    for (auto e : edges) {
        if (uni.is_same(e.u , e.v)) continue;
        uni.merge(e.u, e.v);
        res += e.cost;
    }

    return res;
}

