        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};
template<typename T>
T kruskal(vector<edge<T>> &edges, int V) {
    sort(edges.begin(), edges.end(), [](const edge<T> &a, const edge<T> &b) {
        return a.cost < b.cost;
    });
    UnionFind unionFind(V);
    T res = 0;
    for (edge<T> &e: edges) {
        if (unionFind.merge(e.to, e.from)) {
            res += e.cost;
        }
    }
    return res;
}

int main() {
  int N; cin >> N;
  vector<pair<int, pair<ll, ll>>> p(N);
  REP(i, N) {
    ll a, b; cin >> a >> b;
    auto tmp = make_pair(i, make_pair(a, b));
    p[i] = tmp;
  }
  vector<edge<ll>> tree;
  sort(all(p), compare_by_a);
  for(int i = 0; i < N - 1; ++i) {
    ll tmp = abs(p[i].second.first - p[i + 1].second.first);
    edge<ll> res;
    res.from = p[i].first;
    res.to = p[i + 1].first;
    res.cost = tmp;
    tree.push_back(res);
  }
  sort(all(p), compare_by_b);
  for(int i = 0; i < N - 1; ++i) {
    ll tmp = abs(p[i].second.second - p[i + 1].second.second);
    edge<ll> res;
    res.from = p[i].first;
    res.to = p[i + 1].first;
    res.cost = tmp;
    tree.push_back(res);
  }
  cout << kruskal(tree, N) << endl;
}

