struct UnionFind
{
  // par[i]：データiが属する木の親の番号。i == par[i]のとき、データiは木の根ノードである
  vector<int> par;
  // sizes[i]：根ノードiの木に含まれるデータの数。iが根ノードでない場合は無意味な値となる
  vector<int> sizes;

  UnionFind(int n) : par(n), sizes(n, 1) {
    // 最初は全てのデータiがグループiに存在するものとして初期化
    REP(i,n) par[i] = i;
  }

  // データxが属する木の根を得る
  int find(int x) {
    if (x == par[x]) return x;
    return par[x] = find(par[x]);  // 根を張り替えながら再帰的に根ノードを探す
  }

  // 2つのデータx, yが属する木をマージする
  void unite(int x, int y) {
    // データの根ノードを得る
    x = find(x);
    y = find(y);

    // 既に同じ木に属しているならマージしない
    if (x == y) return;

    // xの木がyの木より大きくなるようにする
    if (sizes[x] < sizes[y]) swap(x, y);

    // xがyの親になるように連結する
    par[y] = x;
    sizes[x] += sizes[y];
    // sizes[y] = 0;  // sizes[y]は無意味な値となるので0を入れておいてもよい
  }

  // 2つのデータx, yが属する木が同じならtrueを返す
  bool same(int x, int y) {
    return find(x) == find(y);
  }

  // データxが含まれる木の大きさを返す
  int size(int x) {
    return sizes[find(x)];
  }
};

struct Edge{
  int a, b, cost;
  Edge(int a=0, int b=0, int cost=0){
    this->a = a;
    this->b = b;
    this->cost = cost;
  }
  bool operator< (const Edge &o) const {
    return cost < o.cost;
  }
};

struct Pos{
  int x, y, idx;
  Pos(int idx=0, int x=0, int y=0){
    this->idx = idx;
    this->x = x;
    this->y = y;
  }
};

bool cmp1(Pos l, Pos r){
  return l.x < r.x;
}
bool cmp2(Pos l, Pos r){
  return l.y < r.y;
}

ll kruskal(vector<Edge>& edges, int N){
  sort(edges.begin(), edges.end());
  UnionFind uf(N);
  ll cost = 0;
  for(auto e : edges){
    if(!uf.same(e.a, e.b)){
      cost += e.cost;
      uf.unite(e.a, e.b);
    }
  }
  return cost;
}
