class UnionFind {
    vector<int> parent;
    vector<int> rank;

public:
    int root(int x) {
        return parent[x] >= 0 ? parent[x] = root(parent[x]) : x;
    }

    void unite(int x, int y) {
        int rootX = root(x);
        int rootY = root(y);
        if (rootX == rootY)
            return;

        if (rank[rootX] > rank[rootY]) {
            parent[rootX] += parent[rootY];
            parent[rootY] = rootX;
        } else {
            if (rank[rootX] == rank[rootY])
                ++rank[rootY];

            parent[rootY] += parent[rootX];
            parent[rootX] = rootY;
        }
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int groupSize(int x) {
        return -parent[root(x)];
    }

    int numGroup() {
        int num = 0;
        for (int k : parent) {
            num += k < 0;
        }
        return num;
    }

    UnionFind(int size) : parent(size + 1, -1), rank(size + 1, 1) {
        parent[0] = rank[0] = 0;
    }
};

bool point_comp(const Point &l, const Point &r) {
    int u, sx, sy, v, tx, ty;
    tie(sx, sy, u) = l;
    tie(tx, ty, v) = r;
    return sy <= ty || sx <= tx;
}

