        int u, sx, sy, v, tx, ty;
        tie(sx, sy, u) = p[i];
        tie(tx, ty, v) = p[i + 1];
        int dist = min(abs(sx - tx), abs(sy - ty));
        edges.push_back(make_tuple(dist, p[i], p[i + 1]));
    }

    sort(p.begin(), p.end(), point_comp);

    for (int i = 0; i < n - 1; ++i) {
        int u, sx, sy, v, tx, ty;
        tie(sx, sy, u) = p[i];
        tie(tx, ty, v) = p[i + 1];
