ll kruskal() {
    sort(es, es+2*E, comp);
    init(V);
    ll res = 0;
    rep(i,2*E) {
        edge e = es[i];
        if(!same(e.u, e.v)) {
            unite(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}


