int pre[MAXN];

void init(int n){
	for(int i=1;i<=n;i++){
		pre[i]=i;
	}
}

bool cmpv(V a,V b){
	return a.x<b.x;
}
bool cmpe(Edge a,Edge b){
	return a.w<b.w;
}

int find(int v){
	if(pre[v]==v){
		return v;
	}
	else {
		pre[v]=find(pre[v]);
		return pre[v];
	}
}

ll Kruskal(int ver,int edges){
	ll tot=0,ale=0;//权重和已加入的顶点数 
	init(ver);
	for(int i=1;i<=edges&&ale<ver-1;i++){
		 int h=find(e[i].va);
		 int k=find(e[i].vb);
		 if(h!=k){
		 	tot+=e[i].w;//增加权重 
		 	ale++;//增加边 
		 	pre[h]=k;//加入集合 
		 } 
	}
	return tot; 

}

