struct Edge {int to, cost;};

int main() {
    int N; cin >> N;
    using P = pair<int, int>;
    vector<P> X(N), Y(N);
    rep(i, 0, N) {
        int x, y;
        cin >> x >> y;
        x--, y--;
        X[i] = {x, i};
        Y[i] = {y, i};
    }
    sort(X.begin(), X.end());
    sort(Y.begin(), Y.end());
    vector<vector<Edge>> G(N);
    auto input = [&](vector<P> &V) {
        rep(i, 0, N - 1) {
            int f = V[i].second;
            int t = V[i + 1].second;
            int d = V[i + 1].first - V[i].first;
            G[f].push_back({t, d});
            G[t].push_back({f, d});
        }
    };
    input(X);
    input(Y);
    priority_queue<P, vector<P>, greater<P>> pq;
    vector<int> visited(N);
    pq.push({0, 0});
    int ans = 0;
    while(!pq.empty()) {
        P t = pq.top(); pq.pop();
        int cur = t.second;
        int cost = t.first;
        if(visited[cur]) continue;
        visited[cur] = 1;
        ans += cost;
        for(auto &e : G[cur]) {
            if(visited[e.to]) continue;
            pq.push({e.cost, e.to});
        }
    }
    cout << ans << endl;
    return 0;
}

