using namespace std;

class UnionFindTree {
private:
    vector<int> parent;
    vector<int> count;
public:
    UnionFindTree(int n) : parent(n), count(n, 1) {
        // 最初は全てを根として初期化
        for(int i = 0; i < n; i++) parent[i] = i;
    }

    int get_root(const int x) {
        // データxが属する木の根を取得する
        if (parent[x] == x) return x;
        // 取得したものは直接木の根をつなぐ(経路圧縮)
        return parent[x] = get_root(parent[x]);
    }

    void unite(const int x, const int y) {
        // xとyの木を併合する
        int rx = get_root(x);
        int ry = get_root(y);
        // 元から同じ木に属している場合は何もしない
        if (rx == ry) return;
        // xの属する木をyの属する木につける
        parent[rx] = ry;
        count[ry] += count[rx];
        count[rx] = 0;
    }

    bool is_same_root(const int x, const int y) {
        return get_root(x) == get_root(y);
    }

    int get_size(const int x) {
        return count[get_root(x)];
    }

    void print() {
        for(auto elm : parent) cout << elm << " ";
        cout << endl;
        for(auto elm : count) cout << elm << " ";
        cout << endl;
    }
};

int main(){
    int n; cin >> n;
    vector<pair<int, int>> x(n), y(n);
    map<int, vector<pair<int, int>>> g;
    UnionFindTree tree(n); int64_t ans = 0;
    for (auto i = 0; i < n; i++) {
        cin >> x[i].first >> y[i].first;
        x[i].second = i; y[i].second = i;
    }
    sort(x.begin(), x.end()); sort(y.begin(), y.end());
    for (auto i = 0; i < n - 1; i++) {
        g[abs(x[i].first - x[i + 1].first)].emplace_back(x[i].second, x[i + 1].second);
        g[abs(y[i].first - y[i + 1].first)].emplace_back(y[i].second, y[i + 1].second);
    }
    for (auto & vec : g) {
        for (auto & elm : vec.second) {
            if (not tree.is_same_root(elm.first, elm.second)) {
                tree.unite(elm.first, elm.second);
                ans += vec.first;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

