using namespace std;

struct UnionFind {
    vector<int> par;
    UnionFind(int n) : par(n, -1) {}
    int root(int x) {
        if(par[x] < 0)
            return 0;
        else
            return par[x] = root(par[x]);
    }
    int issame(int x, int y) { return root(x) == root(y); }
    void merge(int x, int y) {
        x = root(x);
        y = root(y);
        if(x == y)
            return;
        if(-par[x] < -par[y])
            swap(x, y);
        par[x] += par[y];
        par[y] = x;
    }
};
// http://drken1215.hatenablog.com/entry/2019/02/14/124300
int main() {
    int N;
    cin >> N;
    vector<long long> x(N), y(N);
    for(int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
    }
    using pint = pair<int, int>;
    using Edge = pair<long long, pint>;
    vector<Edge> edges;
    // x軸にソートして隣接している部分のみ
    vector<int> ids(N);
    iota(ids.begin(), ids.end(), 0);
    sort(ids.begin(), ids.end(), [&](int i, int j) { return x[i] < x[j]; });
    for(int i = 0; i < ids.size() - 1; i++) {
        int u = ids[i];
        int v = ids[i + 1];
        edges.push_back(Edge(x[v] - x[u], pint(u, v)));
    }
    sort(ids.begin(), ids.end(), [&](int i, int j) { return y[i] < y[j]; });
    for(int i = 0; i + 1 < ids.size(); ++i) {
        int u = ids[i], v = ids[i + 1];
        edges.push_back(Edge(y[v] - y[u], pint(u, v)));
    }
    //ここまでで辺を作る
    sort(edges.begin(), edges.end());
    UnionFind uf(N);
    long long res = 0;
    for(auto e : edges) {
        int u = e.second.first;
        int v = e.second.second;
        long long cost = e.first;
        if(uf.issame(u, v))
            continue;
        uf.merge(u, v);
        res += cost;
    }
    cout << res << endl;
}

