typedef long long ll;
using namespace std;

struct UnionFind {
    vector<int> parent;
    UnionFind(int n) : parent(n) {
        for (int i = 0; i < n; i++) parent[i] = i;
    }

    int root(int n) {
        if (parent[n] == n) return n;
        return parent[n] = root(parent[n]);
    }

    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        parent[rx] = ry;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n; cin >> n;
    vector<pair<int, int>> xBased(n), yBased(n);
    for (int i = 0; i < n; i++) {
        int x, y; cin >> x >> y;
        xBased[i] = { x, i };
        yBased[i] = { y, i };
    }
    sort(xBased.begin(), xBased.end());
    sort(yBased.begin(), yBased.end());
    vector<tuple<int, int, int>> costs;
    for (int i = 1; i < n; i++) {
        int xdiff = xBased[i].first - xBased[i-1].first;
        int ydiff = yBased[i].first - yBased[i-1].first;
        costs.push_back(make_tuple(xdiff, xBased[i].second, xBased[i-1].second));
        costs.push_back(make_tuple(ydiff, yBased[i].second, yBased[i-1].second));
    }
    sort(costs.begin(), costs.end());
    UnionFind tree(n);
    ll ans = 0;
    for (auto& cost : costs) {
        int c = get<0>(cost);
        int f = get<1>(cost);
        int s = get<2>(cost);
        if (tree.root(f) != tree.root(s)) {
            tree.unite(f, s);
            ans += c;
        }
    }
    cout << ans << endl;
    return 0;
}

