			g.pb(edge(i,j,jarak));	
			k++;
		}
	}
	sort(g.begin(),g.end(),cmpfunc);
	ll ans=0,cc=0;
	for(ll i=0;i<k && cc<n-1; i++){
		ll p = findParent(g[i].from);
		ll q= findParent(g[i].to);
		if (p!=q){
			parent[p] = q;
			ans+=g[i].cost;
			cc++;
		}

	}
	cout<<ans<<endl;

	return 0;
}

