class UnionFind
{
public:
	UnionFind(int sz) : size(sz), table(size, 0)
	{
		for(int i=0; i<size; i++)
			table[i] = i;
	};

	int find(int id)
	{
		if(id == table[id])
			return id;
		return table[id] = find(table[id]);
	};
	bool same(int id1, int id2)
	{
		return find(id1) == find(id2);
	};
	void unite(int id1, int id2)
	{
		id1 = find(id1);
		id2 = find(id2);
		table[max(id1, id2)] = table[min(id1, id2)];
	};

private:
	const int size;
	vector<int> table;
};

int main(void)
{
	int N;
	cin >> N;

	vector<long long> x(N), y(N);
	for(int i=0; i<N; i++)
		cin >> x[i] >> y[i];

	vector<pair<long long, int>> xx(N), yy(N);
	for(int i=0; i<N; i++)
	{
		xx[i] = make_pair(x[i], i);
		yy[i] = make_pair(y[i], i);
	}

	sort(xx.begin(), xx.end());
	sort(yy.begin(), yy.end());

	priority_queue<tuple<long long, int, int>> edge;
	for(int i=0; i<N-1; i++)
	{
		int from = i;
		int to = i + 1;

		edge.push(make_tuple(-abs(xx[to].first-xx[from].first), xx[from].second, xx[to].second));
		edge.push(make_tuple(-abs(yy[to].first-yy[from].first), yy[from].second, yy[to].second));
	}

	long long ret = 0;
	UnionFind uf(N);
	while(edge.empty() != true)
	{
		auto e = edge.top();
		edge.pop();

		int cost = -get<0>(e);
		int from = get<1>(e);
		int to = get<2>(e);

		if(uf.same(from, to) == true)
			continue;

		uf.unite(from, to);
		ret += cost;
	}

	cout << ret << endl;

	return 0;
}

