struct Union_Find{
    vector<int> par, depth;
    Union_Find(int n){init(n);}
    void init(int n){
        par.resize(n); depth.resize(n);
        for(int i=0; i<n; i++){
            par[i]=i;
            depth[i]=0;
        }
    }

    int find(int x){
        if(par[x] == x) return x;
        return par[x]=find(par[x]);
    }

    void unite(int x, int y){
        x=find(x), y=find(y);
        if(x == y) return;

        if(depth[x] < depth[y]) par[x]=y;
        else{
            par[y]=x;
            if(depth[x] == depth[y]) depth[x]++;
        }
    }

    bool same(int x, int y){
        return find(x) == find(y); 
    }
};

struct edge{int u, v, cost;};

struct Kruskal{
    ll sum=0;
    int V, E;
    vector<edge> es;
    Kruskal(const vector<edge> &es_, int V_) : es(es_), V(V_) {init();}
    void init(){
        E=(int)es.size();
        sort(all(es), [](const edge &e1, const edge &e2)
        {return e1.cost < e2.cost;});
        Union_Find uf(V);
        for(int i=0; i<E; i++){
            edge e=es[i];
            if(uf.same(e.u, e.v)) continue;
            uf.unite(e.u, e.v);
            sum+=e.cost;
        }
    }
};

