// 素集合データ構造というデータ構造ですj
struct UnionFind {
  std::vector<int> parent; // あるデータの親
  std::vector<int> sizes;  // あるデータが属する木のサイズ

  // コンストラクタ
  // データ一つ一つを木とし、親は自分自身に初期化する
  UnionFind(int n)
    : parent(n)
    , sizes(n, 1)
  {
    for (int i = 0; i < n; ++i) {
      parent[i] = i;
    }
  }

  // データxが属する木の根ノードを取得
  // findだがunion-find木の仕組み的に内部で破壊的更新を伴う
  int find(int x) {
    // 親と自分が同じであることが
    // 自分がルートノードであるということ
    if( x == parent[x] ) {
      return x;
    }

    // 経路を圧縮するため調べた辺を根に直接繋ぎ直す
    parent[x] = find(parent[x]);
    return parent[x];
  }

  // 2つのデータx, yが属する木をマージする
  void unite(int x, int y) {
    // それぞれのデータの根ノードを取得
    int root_x = find(x);
    int root_y = find(y);

    // x, yが同じ木に属するならマージしない
    if (root_x == root_y) return;

    // xの木がyの木より大きくなるようにする
    if (sizes[root_x] < sizes[root_y]) {
      std::swap(root_x, root_y);
    }

    // xがyの親になるようにマージする
    parent[root_y] = root_x;
    sizes[root_x] += sizes[root_y];
  }

  // 2つのデータx, yが同じ木に属するかどうか
  bool same(int x, int y) {
    return (find(x) == find(y));
  }

  // データxの属する木のサイズを返す
  int size(int x) {
    return sizes[find(x)];
  }
};

// 頂点a, bを繋ぐコストcostの無向辺
struct Edge {
  int a, b, cost;

  // コストで順序を決める(ソートのときに使われる)
  bool operator<(const Edge &o) const {
    return cost < o.cost;
  }
};

// 頂点数と辺集合の組として定義したグラフ
struct Graph {
  int n;           // 頂点数
  std::vector<Edge> edges; // 辺集合

  // クラスカル法で無向最小全域木を求め、コストの和を返す
  int kruskal() {
    // costの小さい辺から繫いでいくので、昇順にソートしておく
    sort(edges.begin(), edges.end());

    // UnionFindで同じ集合にいることを確認できます
    // これを使って「繋がってるノード」をすべて1つの集合にいることにします
    // 最初の状態では「どれも繋がっていません」が
    // エッジで繋いだ2つのノードは、同じ集合にいることにしてしまいます
    // 辺を追加するときに、すでにつながっているノード同士を繋ぐということが閉路ができる条件なので
    // 閉路を作らないようにつながっていないノードを繋ぐということを繰り返す
    UnionFind uf(n);
    int min_cost = 0;
    for (size_t i = 0; i < edges.size(); ++i) {
      Edge e = edges[i];
      if (!uf.same(e.a, e.b)) {
        min_cost += e.cost;
        uf.unite(e.a, e.b);
      }
    }

    return min_cost;
  }
};

int main() {
  int N;
  std::cin >> N;
  std::pair<int, int> x[N], y[N];
  for (size_t i = 0; i < N; ++i) {
    std::cin >> x[i].first >> y[i].first;
    x[i].second = y[i].second = i;
  }

  // 式 min( |a-c|, |b-d| ) を検討してみると
  // - "x軸側で一番近い"街
  // - "y軸側で一番近い"街
  // の2つだけがそれぞれの街に存在することがわかります。
  //
  // ということは言い換えると
  // - x軸側について街を並べた並び
  // - y軸側について街を並べた並び
  // の2つだけを検討したら十分なことがわかります
  sort(x, x + N);
  sort(y, y + N);

  // グラフ構造を引っ張る
  Graph g;
  g.n = N;  // Nノードあります

  // 辺を作っていく
  for (size_t i = 0; i < N - 1; ++i) {
    Edge e;
    e.a = x[i].second;
    e.b = x[i+1].second;
    e.cost = x[i+1].first - x[i].first;
    g.edges.push_back(e);

    e.a = y[i].second;
    e.b = y[i+1].second;
    e.cost = y[i+1].first - y[i].first;
    g.edges.push_back(e);
  }

  std::cout << g.kruskal() << std::endl;
  return 0;
}

