typedef long long LL;

struct Edge {
  int u, v;
  LL cost;
  Edge(int a, int b, LL c) : u(a), v(b), cost(c) {}
  bool operator<(const Edge& e) { return cost < e.cost; }
};

struct UnionFindTree {
  std::vector<int> data;

  UnionFindTree(int size) : data(size, -1) { }
  bool Unite(int x, int y) {
    x = Root(x); y = Root(y);
    if (x != y) {
      if (data[y] < data[x]) std::swap(x, y);
      data[x] += data[y];
      data[y] = x;
    }
    return x != y;
  }
  bool IsSameRoot(int x, int y) {
    return Root(x) == Root(y);
  }
  int Root(int x) {
    return data[x] < 0 ? x : data[x] = Root(data[x]);
  }
  int Size(int x) { return -data[Root(x)]; }
};

LL kruskal(int V, vector<Edge>& es) {
  UnionFindTree tree(V);
  LL total_dist = 0LL;

  sort(es.begin(), es.end());  // if you need max cost, use sort(es.rbegin(), es.rend()).
  for (const Edge& e : es) {
    if (!tree.IsSameRoot(e.u, e.v)) {
      tree.Unite(e.u, e.v);
      total_dist += e.cost;
    }
  }
  return total_dist;
}

