typedef tuple <int, int, int> piii;

int uf[100000];
int root(int i) { return (uf[i] < 0 ? i : uf[i] = root(uf[i])); }
void merge(int i, int j) {
    if((i = root(i)) == (j = root(j))) return ;
    if(uf[i] < uf[j]) swap(i, j);
    uf[j] += uf[i];
    uf[i] = j;
    return ;
}

