struct UnionFind {
  vector<int> par_;
  vector<int> rank_;

  void init(int size) {
    par_.resize(size, 0);
    rank_.resize(size, 0);
    for (int i = 0; i < size; i++) {
      par_[i] = i;
      rank_[i] = 0;
    }
  }
  int root(int x) { return par_[x] == x ? x : par_[x] = root(par_[x]); }

  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return true;

    if (rank_[x] < rank_[y]) {
      par_[x] = y;
    } else {
      par_[y] = x;
      if (rank_[x] == rank_[y]) rank_[x]++;
    }
    return false;
  }
  bool same(int x, int y) { return root(x) == root(y); }
};

struct edge{
    int to;
    i64 cost;
};

i64 Kruskal(const vector<vector<edge>>& G){
    using P = pair<i64,pair<int,int>>;
    vector<P> edges;
    for(int i = 0;i < G.size();i++){
        for(auto & e : G[i]){
            edges.push_back({e.cost,{i,e.to}});
        }
    }

    sort(edges.begin(),edges.end());

    UnionFind uf;
    uf.init(G.size());

    i64 res = 0;
    for(auto& p : edges){
        if(!uf.unite(p.second.first,p.second.second)){
          res += p.first;
        }
    }
    return res;
}

