class union_find{
private:
    vector<ll>par,sz,rank;
    ll cnt;
public:
    union_find  (ll n):par(n),sz(n,1),rank(n,0),cnt(n){iota(ALL(par),0);}
    ll   count  ()          {return cnt;}
    ll   find   (ll n)      {return par[n]==n?n:par[n]=find(par[n]);}
    ll   size   (ll n)      {return sz[find(n)];}
    bool is_same(ll x, ll y){return find(x)==find(y);}
    void unite  (ll x, ll y)
    {
        x=find(x);y=find(y);
        if (x!=y) {
            if (rank[x]<rank[y]){
                par[x]=y;
                sz[y]+=sz[x];
            }else{
                par[y]=x;
                sz[x]+=sz[y];
                if(rank[x]==rank[y])++rank[x];
            }
            --cnt;
        }
    }
};
