typedef pair<int, int> P;
const int MAX_V = 200001;
vector<vector<P>> G(MAX_V);

int prim() {
    vector<int> used(MAX_V, false);
    priority_queue<P, vector<P>, greater<P>> que;
    int ret = 0;
    que.push(P(0, 0));
    while (!que.empty()) {
        P p = que.top(); que.pop();
        if (used[p.second]) continue;
        used[p.second] = true;
        ret += p.first;
        rep(i, G[p.second].size()) {
            que.push(P(G[p.second][i]));
        }
    }
    return ret;
}

