	for (int i = 0; i < N; i++) {
		cin >> x[i] >> y[i];
	}

	auto c = [](auto &lhs, auto &rhs) {
		return get<2>(lhs) > get<2>(rhs);
	};

	priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, decltype(c)> q(c);
	for (int i = 0; i < N; i++) {
		for (int j = i + 1; j < N; j++) {
			q.push(make_tuple(i, j, min(abs(x[i] - x[j]), abs(y[i] - y[j]))));
		}
	}

	UnionFind uf(N);
	ll ans = 0;
	while (uf.size(0) < N) {
		auto e = q.top();
		q.pop();

		if (!uf.findSet(get<0>(e), get<1>(e))) {
			uf.unionSet(get<0>(e), get<1>(e));
			ans += get<2>(e);
		}
	}

	cout << ans << endl;
	return 0;
}

