int find(int x)
{
    int t,r=x;
    while(x!=pre[x])
    {
        x=pre[x];
    }
    while(r!=x)
    {
        t=pre[r];
        pre[r]=x;
        r=t;
    }
    return x;
}

void join(int a,int b)
{
    int A=find(a);
    int B=find(b);
    if(A==B) return ;
    if(Rank[A]<Rank[B])
    {
        pre[A]=B;
    }
    else
    {
        pre[B]=A;
        if(Rank[A]==Rank[B])
            Rank[A]++;
    }
}

