      min_x[x[i].second] = P(x[i].first - x[i-1].first, x[i-1].second);
    } else {
      min_x[x[i].second] = P(x[i+1].first - x[i].first, x[i+1].second);
    }
    if (y[i].first - y[i-1].first < y[i+1].first - y[i].first) {
      min_y[y[i].second] = P(y[i].first - y[i-1].first, y[i-1].second);
    } else {
      min_y[y[i].second] = P(y[i+1].first - y[i].first, y[i+1].second);
    }
  }
  min_x[x[N-1].second] = P(x[N-1].first - x[N-2].first, x[N-2].second);
  min_y[y[N-1].second] = P(y[N-1].first - y[N-2].first, y[N-2].second);

  ll ans = 0;
  ll tmp = 0;
  map<ll, ll> mp;
  ll prev;
  for (ll i = 0; i < N; i++) {
    if (min_x[i].first < min_y[i].first) {
      ans += min_x[i].first;
      prev = mp.size();
      mp.insert(P(min(min_x[i].first, i), max(min_x[i].first, i)));
      if (prev == mp.size()) tmp = max(tmp, min_x[i].first);
    } else {
      ans += min_y[i].first;
      prev = mp.size();
      mp.insert(P(min(min_y[i].first, i), max(min_y[i].first, i)));
      if (prev == mp.size()) tmp = max(tmp, min_y[i].first);
    }
  }

  // 解答
  cout << ans - tmp << endl;
  return 0;
}

