	vector<Edge> es;  // 辺集合

										// クラスカル法で無向最小全域木のコストの和を計算する
										// グラフが非連結のときは最小全域森のコストの和となる
	int kruskal()
	{
		// コストが小さい順にソート
		sort(es.begin(), es.end());

		UnionFind uf(n);
		int min_cost = 0;

		rep(ei, es.size())
		{
			Edge& e = es[ei];
			if (!uf.same(e.a, e.b)) {
				// 辺を追加しても閉路ができないなら、その辺を採用する
				min_cost += e.cost;
				uf.unite(e.a, e.b);
			}
		}

		return min_cost;
	}
};



