using namespace std;
typedef long long ll;

struct UnionFind
{
    vector<int> par;  // 親ノード
    vector<int> rank; // ランク

    UnionFind(int n = 1)
    {
        init(n);
    }

    void init(int n = 1)
    {
        par.resize(n);
        rank.resize(n);
        for (int i = 0; i < n; ++i)
            par[i] = i, rank[i] = 0;
    }

    int root(int x)
    {
        if (par[x] == x)
        {
            return x;
        }
        else
        {
            int r = root(par[x]);
            return par[x] = r;
        }
    }

    bool issame(int x, int y)
    {
        return root(x) == root(y);
    }

    bool merge(int x, int y)
    {
        x = root(x);
        y = root(y);
        if (x == y)
            return false;
        if (rank[x] < rank[y])
            swap(x, y);
        if (rank[x] == rank[y])
            ++rank[x];
        par[y] = x;
        return true;
    }
};

int main()
{
    int n;
    cin >> n;
    vector<pair<int, int> > xlist(n), ylist(n);
    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        xlist[i] = make_pair(a, i);
        ylist[i] = make_pair(b, i);
    }
    sort(xlist.begin(), xlist.end());
    sort(ylist.begin(), ylist.end());

    vector<pair<ll, pair<int, int> > > difflist;
    for (int i = 0; i < n - 1; i++) {
        int xdiff = xlist[i + 1].first - xlist[i].first;
        int ydiff = ylist[i + 1].first - ylist[i].first;
        difflist.push_back(make_pair(xdiff, make_pair(xlist[i + 1].second, xlist[i].second)));
        difflist.push_back(make_pair(ydiff, make_pair(ylist[i + 1].second, ylist[i].second)));
    }
    sort(difflist.begin(), difflist.end());

    ll ans = 0;
    UnionFind uf(n);
    for (pair<int, pair<int, int> > p : difflist) {
        if (!uf.issame(p.second.first, p.second.second)) {
            uf.merge(p.second.first, p.second.second);
            ans += p.first;
        }
    }
    cout << ans << endl;
    return 0;
}

