using namespace std;
using ll = long long;

typedef struct UnionFind
{
    vector<int> par;
    vector<int> rank;

    UnionFind(int n) : par(n), rank(n, 0) 
    {
        for (int i = 0; i < n;i++)
        {
            par[i] = i;
        }
    }

    int find(int x)
    {
        if(x == par[x])
        {
            return x;
        }
        return par[x] = find(par[x]);
    }

    void unite(int x, int y)
    {
        x = find(x);
        y = find(y);
        if(x == y)
        {
            return;
        }

        if(rank[x] < rank[y])
        {
            par[x] = y;
        }
        else
        {
            par[y] = x;
            if(rank[x] == rank[y])
            {
                rank[x]++;
            }
        }
    }

    bool same(int x, int y)
    {
        return find(x) == find(y);
    }
}UnionFind;

typedef struct Edge
{
    int u, v, cost;
}Edge;

bool comp(const Edge& e1, const Edge& e2)
{
    return e1.cost < e2.cost;
}

vector<Edge> es;

int V, E;

ll kruscul()
{
    sort(es.begin(), es.end(), comp);
    UnionFind ui(V);
    ll res = 0;
    for (int i = 0; i < E;i++)
    {
        Edge e = es[i];
        if(!ui.same(e.u, e.v))
        {
            ui.unite(e.u, e.v);
            res += e.cost;
        }
    }

    return res;
}

int main()
{
    cin >> V;

    vector<pair<ll, ll> > xs(V);
    vector<pair<ll, ll> > ys(V);

