class UnionFind {
  public:
    vector <int> par;
    vector <int> siz;

    UnionFind(int sz_): par(sz_), siz(sz_, 1LL) {
      for (int i = 0; i < sz_; ++i) par[i] = i;
    }
    void init(int sz_) {
      par.resize(sz_);
      siz.assign(sz_, 1LL);
      for (int i = 0; i < sz_; ++i) par[i] = i;
    }
    int root(int x) {
      while (par[x] != x) {
        x = par[x] = par[par[x]];
      }
      return x;
    }
    bool unite(int x, int y) {
      x = root(x);
      y = root(y);
      if (x == y) return false;
      if (siz[x] < siz[y]) swap(x, y);
      siz[x] += siz[y];
      par[y] = x;
      return true;
    }
    bool same(int x, int y) {
      return root(x) == root(y);
    }
    int size(int x) {
      return siz[root(x)];
    }
};


template<typename T>
T kruskal(vector<vector<pair<int, int>>> &graph, int N){
  priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>, greater<pair<int, pair<int, int>>>> q;
  // to from cost
  REP(i, N) REP(j, graph[i].size()){
    q.push(make_pair(graph[i][j].second, make_pair(i, graph[i][j].first)));
  }
  UnionFind uf(N);
  T res = 0;
  while(!q.empty()){
    auto p = q.top(); q.pop();
    if(uf.unite(p.second.first, p.second.second)){
      res += p.first;
    }
  }
  return res;
}

