priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
bool isConnected[100000];

long long calc(int now){
    if(now == n) return 0;
    if(now == 0){
        isConnected[0] = true;
        for(int i = 1; i < n; i++){
            pq.push(make_pair(min(abs(p[0].first - p[i].first), abs(p[0].second - p[i].second)), i));
        }
        return calc(1);
    }
    while(isConnected[pq.top().second]){
        pq.pop();
    }
    auto status = pq.top();
    pq.pop();
    isConnected[status.second] = true;
    long long res = status.first;
    for(int i = 1; i < n; i++){
        if(isConnected[i]){
            continue;
        }
        pq.push(make_pair(min(abs(p[status.second].first - p[i].first), abs(p[status.second].second - p[i].second)), i));
    }
    return res + calc(now + 1);
}

