signed main() {
    cin >> N;
    REP(i, N) cin >> x[i] >> y[i];

    REP(i, N) sx[i] = x[i], sy[i] = y[i];
    sort(sx, sx + N);
    sort(sy, sy + N);

    DUMP(N)

    int ans = 0;
    int mans = INF;
    REP(i, N) {
        int tx = x[i];
        int ty = y[i];

        int tans = INF;

        auto poslx = lower_bound(sx, sx + N, tx);
        if (poslx > sx) {
            tans = min(tans, tx - sx[poslx - 1 - sx]);
        }
        auto posux = upper_bound(sx, sx + N, tx);
        if (sx[posux - sx] > tx) tans = min(tans, sx[posux - sx] - tx);
        if (posux - poslx > 1) tans = 1;

        auto posly = lower_bound(sy, sy + N, ty);
        if (posly > sy) {
            tans = min(tans, ty - sy[posly - 1 - sy]);
        }
        auto posuy = upper_bound(sy, sy + N, ty);
        if (sy[posuy - sy] > ty) tans = min(tans, sy[posuy - sy] - ty);

        if (posuy - posly > 1) tans = 1;

        ans += tans;
        mans = min(mans, tans);
    }
