struct UnionFind
{
	vector<int> par;
	vector<int> height;

	UnionFind(int n)
	{
		for (int i = 0; i < n; i++)
		{
			par.push_back(i);
			height.push_back(0);
		}
	}

	int find(int x)
	{
		if (par[x] == x)
			return x;
		else
			return par[x] = find(par[x]);
	}

	void unite(int x, int y)
	{
		x = find(x);
		y = find(y);
		if (x == y)
			return;

		if (height[x] < height[y])
			par[x] = y;
		else
		{
			par[y] = x;
			if (height[x] == height[y])
				height[x]++;
		}
	}

	bool same(int x, int y)
	{
		return find(x) == find(y);
	}
};

struct edge
{
	int u;
	int v;
	int cost;
};

bool comp(const edge& e1, const edge& e2)
{
	return e1.cost < e2.cost;
}


int kruskal(int V, int E, edge* es)
{
	sort(es, es + E, comp);
	UnionFind uf(V);

	int res = 0;
	for (int i = 0; i < E; i++)
	{
		edge e = es[i];
		if (!uf.same(e.u, e.v))
		{
			uf.unite(e.u, e.v);
			res += e.cost;
		}
	}

	return res;
}

