using namespace std;

int N;

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	// Read in graph
	cin >> N;
	vector<pair<int, int>> verts(N);
	for (int i = 0; i < N; i++) {
		int X, Y;
		cin >> X >> Y;
		verts[i] = make_pair(X, Y);
	}

	// Create edges
	vector<vector<pair<int, int>>> G(N);
	for (int i = 0; i < N - 1; i++) {
		for (int j = i + 1; j < N; j++) {
			int x1 = verts[i].first;
			int y1 = verts[i].second;
			int x2 = verts[j].first;
			int y2 = verts[j].second;
			int w = min(abs(x1 - x2), abs(y1 - y2));
			G[i].push_back(make_pair(j, w));
			G[j].push_back(make_pair(i, w));
		}
	}

	// Prim's Algorithm
	int cost = 0;
	// Priority queue, storing (weight, node)
	priority_queue<pair<int, int>, vector<pair<int, int> >, greater<pair<int, int> > > pq;
	// Tracks whether a node is already in the MST
	vector<bool> in_mst(N);
	for (int i = 0; i < N; i++) {
		in_mst[i] = false;
	}

	// SOURCE is the initial node in the MST
	int SOURCE = 1;
	pq.push(make_pair(0, SOURCE));

	while (!pq.empty()) {
		// As long as priority queue is not empty (there are more edges to inspect)

		// Take out the next node from the pq
		int weight = pq.top().first;
		int node = pq.top().second;
		pq.pop();
		if (in_mst[node]) {
			continue;
		}
		in_mst[node] = true;
		cost += weight;
		for (int i = 0; i < G[node].size(); i++) {
			int neighbour_node = G[node][i].first;
			int neighbour_weight = G[node][i].second;
			if (!in_mst[neighbour_node]) {
				pq.push(make_pair(neighbour_weight, neighbour_node));
			}
		}
	}

	cout << cost << "\n";

}

