using ll = long long;
using namespace std;

// elt.at(x) x の親 (Elternteil)
vector<int> elt;
// 木の深さ
vector<int> tiefe;

// ツリーの初期化
void init( int n ){
	elt.clear();
	tiefe.clear();
	for( int i = 0; i < n; ++i ){
		elt.push_back(i);
		tiefe.push_back(0);
	}
}

// wurz(x) x の根 (Wurzel)
int wurz( int x ){
	if( elt.at(x) == x ){
		return x;
	} else {
		// wurz(elt.at(x)) で親の根を順番に再帰的にたどっていく
		// return wurz(elt.at(x)) でも動作はするが，高速化のために経路の圧縮を行う
		// 再帰的にたどって一番上の根にたどり着いたら，elt.at(x) に根を代入することでノードをその根に付け替える
		// こうすることによって深さが 1 になり，木が大きくなることを防ぐことができる
		return elt.at(x) = wurz(elt.at(x));
	}
}

// kopp(x, y) x と y の木をつなげる (koppeln)
void kopp( int x, int y ){
	// 根に根をつなげるので，まず根を探しに行く
	x = wurz(x);
	y = wurz(y);
	if( x == y ) return;
	// 深さの小さい木に深さの大きい木をくっつければ，深さが大きくなる
	// 深さの大きい木に深さの小さい木をくっつければ，深さが変わらない　←このほうが有利
	if( tiefe.at(x) < tiefe.at(y) ){
		elt.at(x) = y;
	} else {
		elt.at(y) = x;
		// 深さ N と 深さ N ならくっつけてできる木の深さは N+1 になる
		// 深さ 0 と 0 のときは 1 になる
		if( tiefe.at(x) == tiefe.at(y) ){
			++tiefe.at(x);
		}
	}
}

// x と y が同じ木に属しているか
bool gleich( int x, int y ){
	return wurz(x) == wurz(y);
}

