int prim(){
    priority_queue<P, vector<P>, greater<P> > que;
    fill(mincost, mincost + v, inf);
    long long res = 0;
    mincost[0] = 0;
    que.push(P(0, 0));
    while (!que.empty()) {
        P p = que.top(); que.pop();
        int w = p.second;
        if (mincost[w] < p.first) continue;
        mincost[w] = 0;
        res += p.first;
        for (int ii = 0; ii < g[w].size(); ii++) {
            edge e=g[w][ii];
            if (mincost[e.to] > e.cost) {
                mincost[e.to] = e.cost;
                que.push(P(mincost[e.to], e.to));
            }
        }
    }
    return res;
}

