struct UnionFind{
  vector<int> par;

  UnionFind(int N) : par(N){ //作成
    for(int i = 0; i< N; i++){
      par[i] = i;
    }
  }

  int root(int x){
    if(par[x] == x){
      return x;
    }
    return par[x] = root(par[x]);
  }

  void unite(int x, int  y){ //結合
    int rx  = root(x);
    int ry = root(y);
    if(rx == ry) return;
    par[rx]  = ry;
  }

  bool same(int  x, int y){ //確認
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }

};

