struct Edge { int to, cost; };

void input(int N, vector<vector<Edge>> &G, vector<PI> &A) {
    sort(A.begin(), A.end());
    rep(i, 1, N) {
        int cost = A[i].first.first - A[i-1].first.first;
        G[A[i].second].push_back({A[i-1].second, cost});
        G[A[i-1].second].push_back({A[i].second, cost});
    }
}

int main() {
    int N;
    cin >> N;
    vector<PI> A(N), B(N);
    rep(i, 0, N) {
        int a, b; cin >> a >> b;
        A[i] = {P(a, b), i};
        B[i] = {P(b, a), i};
    }
    vector<vector<Edge>> G(N);
    input(N, G, A);
    input(N, G, B);
    priority_queue<P, vector<P>, greater<P>> Q;
    vector<int> visited(N);
    Q.push(P(0, 0));
    int ans = 0;
    while(!Q.empty()) {
        P p = Q.top(); Q.pop();
        int cur = p.second;
        int cost = p.first;
        if(visited[cur]) continue;
        visited[cur] = 1;
        ans += cost;
        for(auto &e : G[cur]) {
            if(visited[e.to]) continue;
            Q.push(P(e.cost, e.to));
        }
    }
    cout << ans << endl;
    return 0;
}

