//union find
struct UnionFind {
    vector<ll> parent;
    vector<ll> usize;

    UnionFind(int n) : parent(n), usize(n, 1LL){
        rep(i, n)parent[i]=i;
    }

    int root(int x){
        if(parent[x] == x) return x;
        else return parent[x] = root(parent[x]);
    }

    bool issame(int x, int y){
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x);
        y = root(y);

        if(x == y)return false;

        if(parent[x] > parent[y]) swap(x, y);

        usize[x] += usize[y];
        parent[y] = x;

        return true;
    }

    int size(int x) {
        return usize[root(x)];
    }
};

