class UnionFind {
public:
    UnionFind(int n) : parent_(n), rank_(n) {
        for (int i = 0; i < n; ++i) {
            parent_[i] = i;
            rank_[i] = 0;
        }
    }

    int find(int x) {
        if (parent_[x] == x)
            return x;
        else
            return parent_[x] = find(parent_[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);

        if (x == y) return;

        if (rank_[x] < rank_[y]) {
            parent_[x] = y;
        } else {
            parent_[y] = x;
            if (rank_[x] == rank_[y]) rank_[x]++;
        }
    }

    bool same(int x, int y) { return find(x) == find(y); }

    vector<int> parent_, rank_;
};

class Kruskal {
public:
    struct edge {
        int u, v, cost;
    };

    vector<edge> edges_;
    int v_;

    Kruskal(int v) : v_(v) {}

    void add_edge(int u, int v, int cost) { edges_.push_back((edge){u, v, cost}); }

    int kruskal() {
        sort(edges_.begin(), edges_.end(), comp);

        UnionFind uf(v_);

        int res = 0;

        for (const edge& e : edges_) {
            if (!uf.same(e.u, e.v)) {
                uf.unite(e.u, e.v);
                res += e.cost;
            }
        }

        return res;
    }

    static bool comp(const edge& e1, const edge& e2) { return e1.cost < e2.cost; }
};

