struct dsu {
    vector<int> p;
    dsu(int n) {
        p.resize(n);
        iota(begin(p), end(p), 0);
    }
    int get(int v) {
        return p[v] == v ? v : p[v] = get(p[v]);
    }
    int unite(int u, int v) {
        u = get(u), v = get(v);
        if(u == v)
            return 0;
        p[u] = v;
        return 1;
    }
