      miny_i = yin[i]+1;
    }else if(yin[i] == N-1){
      miny = abs(Y[yin[i]].first - Y[yin[i]-1].first);
      miny_i = yin[i]-1;
    }else{
      if(abs(Y[yin[i]].first - Y[yin[i]-1].first) < abs(Y[yin[i]].first - Y[yin[i]+1].first)){
	miny = abs(Y[yin[i]].first - Y[yin[i]-1].first);
	miny_i = yin[i]-1;
      }else{
	miny = abs(Y[yin[i]].first - Y[yin[i]+1].first);
	miny_i = yin[i]+1;
      }
    }
    if(pre_miny < miny){
      miny = pre_miny;
      miny_i = pre_miny_i;
    }
    if(minx < miny){
      cost += minx;
      i = minx_i;
      pre_miny = miny;
      pre_miny_i = miny_i;
    }else{
      cost += miny;
      i = miny_i;
      pre_minx = minx;
      pre_minx_i = minx_i;
    }
  }

  cout << cost << endl;
  return 0;
}

