using namespace std;
struct UnionFind {
  vector<int> par;
  vector<int> rank;
  vector<int> num;

  UnionFind(int N) : par(N),rank(N),num(N) {
        for(int i = 0; i < N; i++){ 
          par[i] = i;
          rank[i] = 0;
          num[i] = 1;
        }
   }

  int root(int x) {
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  int ranker(int x){
    x = root(x);
    return rank[x];
  }

  int number(int x){
    x = root(x);
    return num[x];
   }

  void unite(int x, int y){
    int rx = root(x);
    int ry = root(y);
    if ( rx == ry ) return;
    if ( rank[rx] < rank[ry] ){
      par[rx] = ry;
      num[ry] += num[rx];
      num[rx] = 0;
    } else {
      par[ry] = rx;
      num[rx] += num[ry];
      num[ry] = 0;
      if ( rank[rx] == rank[ry] ) rank[rx]++;
    }
   }

  bool same(int x, int y){
    return root(x) == root(y);
  }
};

struct edge{ int u, v; long cost; };

bool comp(const edge &e1, const edge &e2){
    return e1.cost < e2.cost;
}

int main(){
