    P px,py;
    long tx,ty;
    vector<P> x,y;
    cin >> N;
    for(int i = 1; i <= N; ++i){
        cin >> tx >> ty;
        px = make_pair(tx,i);
        py = make_pair(ty,i);
        x.push_back(px);
        y.push_back(py);
    }



    sort(x.begin(),x.end());
    sort(y.begin(),y.end());

    vector<edge> edges;

    for(int i = 0; i < N - 1; ++i){
        edges.push_back({x[i].second , x[i+1].second, x[i+1].first -  x[i].first});
        edges.push_back({y[i].second , y[i+1].second, y[i+1].first -  y[i].first});
    }

    sort(edges.begin(),edges.end(),comp);

    UnionFind city(N);
    long ans = 0;
    for(int i = 0; i < edges.size(); i++){
        int c1 = edges[i].u;
        int c2 = edges[i].v;
        long ct = edges[i].cost;
        if(!city.same(c1,c2)){
            city.unite(c1,c2);
            ans += ct;
        }
    }

    cout << ans << endl;
}

