  sort (ylist.begin(), ylist.end());

  vector<pair<int, pair<int, int> > > order;
  for (int i = 0; i < N - 1; i++) {
    ll xdiff = xlist[i + 1].first - xlist[i].first;
    order.push_back(make_pair(xdiff, make_pair(xlist[i].second, xlist[i + 1].second)));

    ll ydiff = ylist[i + 1].first - ylist[i].first;
    order.push_back(make_pair(ydiff, make_pair(ylist[i].second, ylist[i + 1].second)));    
  }

  sort(order.begin(), order.end());

  ll ans = 0;
  UnionFind uf(N);

  for (auto o : order) {
    ll s = o.second.first;
    ll e = o.second.second;

    if (!uf.issame(s, e)) {
      uf.merge(s, e);
      ans += o.first;
    }
  }
  cout << ans << endl;
  return 0;
}

