class UnionFind {
	public:
		vector<int> par, rank;

		void init(int n) {
			par = vector<int>(n + 1);
			rank = vector<int>(n + 1);
			for (int i = 0; i < n; i++) par[i] = i, rank[i] = 0;
		}
		// 木の根を求める
		int root(int x) {
			return (par[x] == x) ? x : par[x] = root(par[x]);
		}
		// xとyの属する集合を併合
		void unite(int x, int y) {
			x = root(x), y = root(y);
			if (x == y)return;

			if (rank[x] < rank[y]) par[x] = y;
			else {
				par[y] = x;
				if (rank[x] == rank[y]) rank[x]++;
			}
		}
		// xとyが同じ集合に属するか否か
		bool same(int x, int y) {
			return root(x) == root(y);
		}
};

ll Kruscal(){

    UnionFind uf;
    uf.init(N);

    ll ans = 0;
    for(auto g : graph){
        ll x, y, c; tie(c, x, y) = g;

        if(uf.root(x) != uf.root(y)){
            uf.unite(x, y);
            ans += c;
        }

    }

    return ans;
}

