using namespace std;
typedef pair<long long, long long> p;

struct Unionfind {
  // tree number
  vector<int> par;
  // tree rank
  vector<int> treerank;
  // constructor
  Unionfind(int n = 1) { stree(n + 1); }
  // make and initialization
  void stree(int n = 1) {
    par.resize(n);
    treerank.resize(n);
    for(int i = 0; i < n; ++i) {
      par[i] = i;
      treerank[i] = 0;
    }
  }
  // search root
  int root(int x) {
    if(par[x] == x) return x;
    return par[x] = root(par[x]);
  }
  // is same?
  bool issame(int x, int y) { return root(x) == root(y); }

  // add
  // already added, return 0
  bool uni(int x, int y) {
    x = root(x);
    y = root(y);
    if(x == y) return 0;
    if(treerank[x] < treerank[y])
      par[x] = y;
    else if(treerank[y] < treerank[x])
      par[y] = x;
    else {
      par[y] = x;
      ++treerank[x];
    }
    return 1;
  }
};

long long n;
// x,y, point num
vector<pair<p, int>> v;
// cost, from, to
priority_queue<pair<long long, p>,
               vector<pair<long long, p>>,
               greater<pair<long long, p>>>
    pq;
Unionfind uf;

long long calccost(int x, int y) {
  return min(
      max(v[x].fi.fi - v[y].fi.fi, v[y].fi.fi - v[x].fi.fi),
      max(v[x].fi.se - v[y].fi.se,
          v[y].fi.se - v[x].fi.se));
}

void setedge();
long long solve();

int main() {
  cin >> n;
  uf = Unionfind(n + 1);
  for(int i = 0; i < n; ++i) {
    long long x, y;
    cin >> x >> y;
    v.push_back(make_pair(make_pair(x, y), i));
  }
  setedge();
  cout << solve() << endl;
  return 0;
}

void setedge() {
  sort(v.begin(), v.end());
  for(int i = 1; i < n; ++i) {
    long long now = calccost(i - 1, i);
    pq.push(
        make_pair(now, make_pair(v[i - 1].se, v[i].se)));
  }
  for(int i = 0; i < n; ++i) swap(v[i].fi.fi, v[i].fi.se);
  sort(v.begin(), v.end());
  for(int i = 1; i < n; ++i) {
    long long now = calccost(i - 1, i);
    pq.push(
        make_pair(now, make_pair(v[i - 1].se, v[i].se)));
  }
}

long long solve() {
  long long ans = 0;
  while(pq.size() > 0) {
    pair<long long, p> now = pq.top();
    pq.pop();
    if(!uf.issame(now.se.fi, now.se.se)) {
      ans += now.fi;
      uf.uni(now.se.fi, now.se.se);
    }
  }
  return ans;
}

