// UnionFind
struct UnionFind {
    vector<int> par;
    vector<int> siz;

    UnionFind(int N) : par(N), siz(N, 1LL) {
        for(int i = 0; i < N; i++)
            par[i] = i;
    }
    int root(int x) {
        if(par[x] == x)
            return x;
        return par[x] = root(par[x]);
    }
    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if(rx == ry)
            return;
        if(siz[rx] < siz[ry])
            swap(rx, ry);
        siz[rx] += siz[ry];
        par[ry] = rx;
    }
    bool same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
    ll size(ll x) { return siz[root(x)]; }
};

// Edge
template <typename T> struct Edge {
    int from, to;
    T cost;
    Edge(int f, int t, T c) : from(f), to(t), cost(c) {}
};

// Kruskal Method
// @param edges := set of Edge
//        V := the number of vertice
template <typename T> T kruskal(vector<Edge<T>> &edges, int V) {
    sort(begin(edges), end(edges),
         [](const Edge<T> &a, const Edge<T> &b) { return (a.cost < b.cost); });
    UnionFind tree(V);
    T res = 0;
    for(auto &e : edges) {
        if(!tree.same(e.from, e.to)) {
            tree.unite(e.from, e.to);
            res += e.cost;
        }
    }
    return res;
}

