struct UnionFind {
    vector<int> par;
    UnionFind(int n) : par(n, -1) { }
    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }
    bool issame(int x, int y) {
        return root(x) == root(y);
    }
    void merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return;
        if (-par[x] < -par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
    }
};

void solve() {
    int N; cin >> N;
    vector<long long>x(N), y(N);
    using pint = pair<int, int>;
    using Edge = pair<long long, pint>;
    vector<Edge> edges(N);
    for (int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
    }
    vector<int> ids(N);
    //x軸方向でソートして隣接している部分のみ
    iota(ids.begin(), ids.end(), 0);
    sort(ids.begin(), ids.end(), [&](int i, int j){
        return x[i] < x[j];
    });
    for (int i = 0; i + 1 < ids.size(); i++) {
        long long u = ids[i];
        long long v = ids[i + 1];
        edges.push_back(Edge(x[v] - x[u], pint(u, v)));
    }
    //y軸方向でソートして隣接している部分のみ
    sort(ids.begin(), ids.end(), [&](int i, int j){
        return y[i] < y[j];
    });
    for (int i = 0; i + 1 < ids.size(); i++) {
        long long u = ids[i];
        long long v = ids[i + 1];
        edges.push_back(Edge(y[v] - y[u], pint(u, v)));
    } 
    sort(edges.begin(), edges.end());
    UnionFind uf(N);
    int res = 0;
    for (auto e : edges) {
        long long u = e.second.first;
        long long v = e.second.second;
        long long cost = e.first;
        if (uf.issame(u, v)) {
            continue;
        }
        uf.merge(u, v);
        res += cost; 
    }
    cout << res << endl;
    return;
}
//逆元を求める関数
long long fac[MAX], finv[MAX], inv[MAX];
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++) {
      fac[i] = fac[i-1] * i % MOD;
      inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
      finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
//組み合わせ
long long COM (int n, int k) {
    if(n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n-k] % MOD) % MOD;
}
int main(int args, char* argv[]) {
    solve();
}

