template<size_t N>
class UnionFind {
    int par[N];
public:
    UnionFind() {
        for (int n = 0; n < N; n++) par[n] = n;
    }
    int root(int x) {
        if (par[x] == x) return x;
        else return par[x] = root(par[x]);
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        par[x] = y;
    }
};

int main () {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    cin>>N;
    using pos = pair<ll, ll>;
    vector<pos> po(N+1);
    map<ll, vector<int>> xs, ys;
    for (int n = 1; n <= N; n++) {
        int x, y;
        cin>>x>>y;
        po[n] = make_pair(x, y);
        xs[x].push_back(n);
        ys[y].push_back(n);
    }

    UnionFind<100001> uf;
    map<ll, pos> dst;
    for (auto it = begin(xs); it != end(xs); it++) {
        if (++it == end(xs)) break;
        ll nx = it->first;
        auto& ns = it->second;
        ll px = (--it)->first;
        auto& ps = it->second;
        for (int n : ns)
            for (int p : ps) {
                if (nx == px || po[n].second == po[n].second) uf.unite(n, p);
                else dst[min(nx-px, abs(po[n].second-po[p].second))] = make_pair(n, p);
            }
    }
    for (auto it = begin(ys); it != end(ys); it++) {
        if (++it == end(ys)) break;
        ll ny = it->first;
        auto& ns = it->second;
        ll py = (--it)->first;
        auto& ps = it->second;
        for (int n : ns)
            for (int p : ps) {
                if (ny == py || po[n].first == po[p].first) uf.unite(n, p);
                else dst[min(ny-py, abs(po[n].first-po[p].first))] = make_pair(n, p);
            }
    }

    int cost = 0;
    for (auto&& [k,v] : dst) {
        if (uf.same(v.first, v.second)) continue;
        else {
            cost += k;
            uf.unite(v.first, v.second);
        }
    }

    cout<<cost<<endl;

    return 0;
}

