#define MAX_N 100000

class Node
{
    public:
        int x, y, index, cost = INT_MAX;;
        bool used = false;
};

int n;
int A[MAX_N][MAX_N] = {};
Node *nodes = new Node[MAX_N];

int prim()
{
    int i, u, v, minv, sum = 0;
    nodes[0].cost = 0;
    while (true) {
        u = -1; minv = INT_MAX;
        for (i = 0; i < n; i++) {
            if (nodes[i].cost < minv && !nodes[i].used) {
                u    = i;
                minv = nodes[i].cost;
            }
        }
        if (-1 == u) break;
        nodes[u].used = true;
        sum += nodes[u].cost;
        for (v = 0; v < n; v++) {
            if (!nodes[v].used && A[u][v] != 0) {
                nodes[v].cost = A[u][v] < nodes[v].cost ? A[u][v] : nodes[v].cost;
            }
        }
    }
    return sum;
}

bool xsort(Node a, Node b)
{
    if (a.x < b.x) return true;
    else return false;
}

bool ysort(Node a, Node b)
{
    if (a.y < b.y) return true;
    else return false;
}
