struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

struct Point {
  Point(int _index, int _x,int _y){
    index = _index;
    x = _x;
    y = _y;
  }
  int index;
  int x;
  int y;
};

bool xcmp(const Point &a, const Point &b)
{
    return a.x < b.x;
}

bool ycmp(const Point &a, const Point &b)
{
    return a.y < b.y;
}

struct Edge{
  Edge(int _a, int _b, int _cost){
    a = _a;
    b = _b;
    cost = _cost;
  }

  int a;
  int b;
  int cost;
};

bool costcmp(const Edge &a, const Edge &b)
{
    return a.cost < b.cost;
}

int kruskal(vector<Edge>& edges, int n){
  UnionFind uf(n);
  int cost =0;
  int rest = n;
  for(auto it: edges){
    if(uf.findSet(it.a,it.b)){continue;}
    cost += it.cost;
    uf.unionSet(it.a,it.b);
    rest--;

    //cout << "a:" << it.a << ",b:" << it.b << ",cost:" << it.cost << endl;

    if(rest-1==0){break;}
  }
  return cost;
}

