struct UnionFind {
  vector<int> d;
  UnionFind(int n=0): d(n, -1) {}

  //functions
  int find(int x) {
    if (d[x] < 0) return x;
    return d[x] = find(d[x]);
  }

  bool unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return false;
    if (d[x] > d[y]) swap(x, y);
    d[x] += d[y];
    d[y] = x;
    return true;
  }

  bool same(int x, int y) {
    return find(x) == find(y);
  }

  int size(int x) {
    return -d[find(x)];
  }
};

ll kruskal(vector<edge>&edges, UnionFind &uf) {
  sort(edges.begin(), edges.end());

  ll ans = 0;
  for (edge e: edges) {
    if (!uf.same(e.from, e.to)) {
      uf.unite(e.from, e.to);
      ans += e.cost;
    }
  }
  return ans;
}

