class UnionFind {
  public:
    vi Parent;
    UnionFind(int N) {
      Parent = vi(N,-1);
    }

    int root(int A) {
      if(Parent[A] < 0) return A;
      return Parent[A] = root(Parent[A]);
    }

    int size(int A) {
      return -Parent[root(A)];
    }

    bool connect(int A,int B) {
      A = root(A);
      B = root(B);
      if(A == B) return false;
      if(size(A) < size(B)) swap(A,B);
      Parent[A] += Parent[B];
      Parent[B] = A;
      return true;
    }
};

ll kruskal(vector<pair<ll,P>> &ES,int V) {
  // ES[i] = P(c,P(f,t)) means that from `f` to `t` 's cost is `c`
  sort(rng(ES));
  UnionFind tree = UnionFind(V);
  ll res = 0;
  rep(i,sz(ES)) {
    ll c = ES[i].first;
    int f = ES[i].second.first;
    int t = ES[i].second.second;
    if(tree.root(f) != tree.root(t)) {
      res += c;
      tree.connect(f,t);
    }
  }
  return res;
}

