#include <bits/stdc++.h>
using namespace std;

#define f first
#define s second

vector<int> link, len;

int find(int node) {
    if (node == link[node]) {
        return node;
    }
    link[node] = find(link[node]);
	return link[node];
}

bool same(int node1, int node2) {
    return find(node1) == find(node2);
}

void unite(int node1, int node2) {
    node1 = find(node1);
    node2 = find(node2);
    if (len[node1] < len[node2]) {
        swap(node1, node2);
    }
    len[node1] += len[node2];
    link[node2] = node1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    vector<pair<int,int>> x(n), y(n);
    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        x[i] = {a, i};
        y[i] = {b, i};
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    vector<pair<int, pair<int,int>>> edges(2 * (n - 1));
    for (int i = 0; i < n - 1; i++) {
        edges[i] = {x[i+1].f - x[i].f, {x[i].s, x[i+1].s}};
    }
    for (int i = 0; i < n - 1; i++) {
        edges[i + n - 1] = {y[i+1].f - y[i].f, {y[i].s, y[i+1].s}};
    }
    sort(edges.begin(), edges.end());

    long long ans = 0, cnt = 0;
    link.resize(n);
    len.resize(n);
    for (int i = 0; i < n; i++) {
        link[i] = i;
    }
    for (int i = 0; i < edges.size(); i++) {
        if (cnt >= n - 1) break;
        if (!same(edges[i].s.f, edges[i].s.s)) {
            unite(edges[i].s.f, edges[i].s.s);
            ans += edges[i].f;
            cnt++;
        }
    }

    cout << ans << '\n';

    return 0;
}

