    for (int i = 0; i < N - 1; i++) {
        edges.push_back({get<2>(px[i]), get<2>(px[i + 1]), get<0>(px[i + 1]) - get<0>(px[i])});
    }
    sort(ALL(py));
    for (int i = 0; i < N - 1; i++) {
        edges.push_back({get<2>(py[i]), get<2>(py[i + 1]), get<0>(py[i + 1]) - get<0>(py[i])});
    }
    Kruskal krs(edges, N);
    cout << krs.sum << endl;
    return 0;
}

