struct UnionFind{
    vector<long long> parents;
    vector<long long> ranks;

    UnionFind(long long n) : parents(n), ranks(n){
        for (int i=0;i<n;i++){
            parents[i] = i;
            ranks[i] = 1;
        }
    }

    long long find(long long x){
        if (parents[x] == x){
            return x;
        } else {
            return parents[x] = find(parents[x]);
        }
    }

    bool same(long long x, long long y){
        return find(x) == find(y);
    }

    void unite(long long x, long long y){
        auto root_x = find(x);
        auto root_y = find(y);
        if (root_x == root_y){
            return;
        }
        if (ranks[root_x] < ranks[root_y]){
            parents[root_x] = root_y;
            ranks[root_y]++;
        } else {
            parents[root_y] = root_x;
            ranks[root_x]++;
        }
    }
};

struct Edge{
    long long l, r, cost;

    bool operator<(const Edge& o) const {
        return cost < o.cost;
    }
};

int main(){
    int n;cin>>n;
    vector<pair<long long, long long>> cities(n);
    long long x, y;
    for(int i=0;i<n;i++){
        cin >> x >> y;
        cities[i] = make_pair(x, y);
    }
    vector<Edge> roads;
    for (int i=0;i<n-1;i++){
        for (int j=i+1;j<n;j++){

            long long cost = min(abs(cities[i].first - cities[j].first), abs(cities[i].second - cities[j].second));
            auto edge = Edge();
            edge.l = i;
            edge.r = j;
            edge.cost = cost;
            roads.push_back(edge);
        }
    }
    sort(roads.begin(), roads.end());

    auto uf = UnionFind(n+1);
    long long acc = 0;
    for (auto road : roads){
        if (!uf.same(road.l, road.r)){
            acc += road.cost;
            uf.unite(road.l, road.r);
        }
    }
    cout << acc << endl;
    return 0;
}

