struct UnionFind{
    vector<int> par,siz;
    UnionFind(int n){
        par.resize(n);
        siz.resize(n,1);
        for(int i=0;i<n;i++)par[i]=i;
    }
    int root(int a){
        if(par[a]==a)return a;
        else return par[a]=root(par[a]);
    }
    bool issame(int a,int b){
        return par[a]==par[b];
    }
    int size(int a){
        return siz[root(a)];
    }
    void marge(int a,int b){
        if(siz[root(a)]>siz[root(b)])swap(a,b);
        par[root(a)]=root(b);
        siz[root(b)]+=siz[root(a)];
    }
};
int main(){
    int n;
    cin>>n;
    using P=pair<int,int>;
    vector<P> x(n),y(n);
    for(int i=0;i<n;i++){
        cin>>x[i].first>>y[i].first;
        x[i].second=i;
        y[i].second=i;
    }
    sort(x.begin(),x.end());
    sort(y.begin(),y.end());
    using PP=pair<int,P>;
    priority_queue<PP,vector<PP>,greater<>> pq;
    for(int i=0;i<n-1;i++){
        pq.push(PP(x[i+1].first-x[i].first,P(x[i].second,x[i+1].second)));
        pq.push(PP(y[i+1].first-y[i].first,P(y[i].second,y[i+1].second)));
    }
    UnionFind uf(n);
    int ret=0;
    for(int i=0;i<(n-1)*2;i++){
        PP pp=pq.top();
        pq.pop();
        if(uf.issame(pp.second.first,pp.second.second))continue;
        else {
            ret+=pp.first;
            uf.marge(pp.second.first,pp.second.second);
        }
    }
    cout<<ret<<endl;
}

