    e[p[i+1].id].push_back(edge(p[i+1].id, p[i].id, p[i+1].yc-p[i].yc));
  }
  vector<bool> used(n, false);
  long ans = 0;
  auto c = [](const edge &a, const edge &b){return a.cost > b.cost;};
  priority_queue<edge, vector<edge>, decltype(c)> que(c);
