struct UnionFind {
    vector<int> par;
    vector<int> sizes;
    vector<int> maxs;
    vector<int> mins;

    UnionFind(int n) :
            par(n), sizes(n, 1), maxs(n), mins(n) {
        rep(i, n) par[i] = i;
        rep(i, n) maxs[i] = i;
        rep(i, n) mins[i] = i;
    }

    int root(int x) {
        if (x == par[x]) return x;
        else return par[x] = root(par[x]);
    }

    bool merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (sizes[x] < sizes[y]) swap(x, y);
        par[y] = x;
        maxs[x] = max(maxs[y], maxs[x]);
        mins[x] = min(mins[y], mins[x]);
        sizes[x] += sizes[y];
        return true;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int size(int x) {
        return sizes[root(x)];
    }

    int getMax(int x) {
        return maxs[root(x)];
    }

    int getMin(int x) {
        return mins[root(x)];
    }

};


