//構造体
//Union-Find木
struct UnionFind{
  //メンバ変数 
  vector<long long>par; //par[i]:=頂点iの親

  //コンストラクタ
  UnionFind(long long N):par(N){
    for(long long i=0;i<N;i++) par[i]=i; //最初はすべてが根として初期化
  }

  //メンバ関数
  //root(i):=頂点iの根
  long long root(long long i){
    if(par[i]==i) return i;

    par[i]=root(par[i]); //経路圧縮
    return root(par[i]); //再帰
  }
  //unite(x,y) xの根をyの根を繋げる(集合を合併)
  void unite(long long x, long long y){
    long long rx=root(x);
    long long ry=root(y);
    par[rx]=par[ry];
  }
  //same(x,y) xとyが同じ根を持つか(同じ集合に含まれるか)
  bool same(long long x, long long y){
    return root(x)==root(y);
  }
};

