typedef pair<int,int> P;
const int inf=1000000007;
const int MOD=1000000007;
class Grid{
    public:
    map<P,int> H;
    map<P,int> V;
    Grid(vector<P> const& input){
        int n=input.size();
        rep(i,n){
            H[input[i]]+=1;
            V[{input[i].second,input[i].first}]+=1;
        }
        H[{inf,inf}]+=1;
        H[{-inf,-inf}]+=1;
        V[{inf,inf}]+=1;
        V[{-inf,-inf}]+=1;
    }
    P get_r(int x){
        auto it=H.lower_bound({x,0});
        return it->first;
    }
    P get_l(int x){
        auto it=H.lower_bound({x,0});
        --it;
        return it->first;
    }
    P get_u(int y){
        auto it=V.lower_bound({y,0});
        return it->first;
    }
    P get_d(int y){
        auto it=V.lower_bound({y,0});
        --it;
        return it->first;
    }
    int solve(P v){
        //一番小さい要素の大きさを取得
        int res=inf;
        P r=get_r(v.first);
        res=min(res,abs(r.first-v.first));
        P l=get_l(v.first);
        res=min(res,abs(l.first-v.first));
        P u=get_u(v.first);
        res=min(res,abs(u.first-v.second));
        P d=get_d(v.first);
        res=min(res,abs(d.first-v.second));
        return res;     
    }
    void del(int x,int y){
        H.erase({x,y});
        V.erase({y,x});
    }
    P er(P v){
        //vから最も近い点を削除してその点を返す
        int mn=solve(v);
        int res=inf;
        P r=get_r(v.first);
        res=min(res,abs(r.first-v.first));
        if(res==mn){
            del(r.first,r.second);
            return r;
        }
        P l=get_l(v.first);
        res=min(res,abs(l.first-v.first));
        if(res==mn){
            del(l.first,l.second);
            return l;
        }
        P u=get_u(v.first);
        res=min(res,abs(u.first-v.second));
        if(res==mn){
            del(u.second,u.first);
            swap(u.first,u.second);
            return u;
        }
        P d=get_d(v.first);
        res=min(res,abs(d.first-v.second));
        if(res==mn){
            del(d.second,d.first);
            swap(d.first,d.second);
            return d;
        }
        return {inf,inf};
    }
};
