	for (int i = 0; i < n; i++)
	{
		cin >> vec[i].x >> vec[i].y;
	}

	vector<set<int>> vec2(n);
	for (int i = 0; i < n; i++)
	{
		vec2[i].insert(i);
	}

	const auto func = [&](const set<int>& vec1, const set<int>& vec2) {
		int r = INT32_MAX;
		for (const auto& v1 : vec1)
		{
			for (const auto& v2 : vec2)
			{
				r = min(r, min(abs(vec[v1].x - vec[v2].x), abs(vec[v1].y - vec[v2].y)));
			}
		}
		return r;
	};

	int cost = 0;
	int add = 0;
	while (add < n - 1)
	{
		for (int i = 0; i < vec2.size(); i++)
		{
			int min = i;
			int r = INT32_MAX;
			if (!vec2[i].empty())
			{
				for (int j = 0; j < vec2.size(); j++)
				{
					if (i != j && !vec2[j].empty())
					{
						const int range = func(vec2[i], vec2[j]);
						if (r > range)
						{
							r = range;
							min = j;
						}
					}
				}
				for (const auto& v : vec2[min])
				{
					vec2[i].insert(v);
				}
				vec2[min].clear();
				cost += r;
				add++;
			}

		}
	}

	cout << cost << endl;

	return 0;
}

