        bool operator<( const  edge& right) const {
            return w < right.w;
        }
};

struct p {
    int v;
    int z;

    bool operator<( const p& right ) const {
        return z < right.z;
    }
};


int find(int x, vector<int>& par) {
    while (par[x] != x) {
        x = par[x];
    }

    return x;
}

void unite(int x, int y, vector<int>& rank, vector<int>& par) {
    x = find(x, par);
    y = find(y, par);
    if (x == y) {return;}

    if (rank[x] < rank[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (rank[x] == rank[y]) {rank[x]++;}
    }
}

bool same(int x, int y, vector<int>& par) {
    return find(x, par) == find(y, par);
}

int main(void){
    int n;
    scanf("%d", &n);

    vector< vector <int> > edges(n, vector<int>(n));
    vector<p> p_x(n);
    vector<p> p_y(n);

    for (int i = 0; i < n; i++) {
        p_x[i].v = i;
        p_y[i].v = i;
        scanf("%d %d", &p_x[i].z, &p_y[i].z);;
    } 

    sort(p_x.begin(), p_x.end());
    sort(p_y.begin(), p_y.end());

    vector<edge> e(2 * (n-1));

    for (int i = 0; i< (n-1);i++) {
        e[i].v_a = p_x[i].v;
        e[i].v_b = p_x[i+1].v;
        e[i].w = abs(p_x[i].z - p_x[i+1].z);
    }

    for (int i = 0; i < (n-1); i++) {
        e[i + (n-1)].v_a = p_y[i].v;
        e[i + (n-1)].v_b = p_y[i+1].v;
        e[i + (n-1)].w = abs(p_y[i].z - p_y[i+1].z);
    }

    sort(e.begin(), e.end());

    vector<int> par(n);
    vector<int> rank(n);

    for (int i = 0; i < n; i++) {
        par[i] = i;
        rank[i] = 0;
    } 

    int cost = 0;

    for (int i = 0; i < 2*(n-1); i++) {
        if (!same(e[i].v_a, e[i].v_b, par)) {
            cost += e[i].w;
            unite(e[i].v_a, e[i].v_b, rank, par);
        }
    }

    printf("%d \n", cost);

    return 0;
}

