/* template */

struct UnionFind{
private:
    std::vector<int> par;

    int find(int x){
        if(par[x]<0) return x;
        else return par[x] = find(par[x]);
    }

public:
    UnionFind(int n=0): par(n,-1){ }

    bool same(int x,int y){
        return find(x)==find(y);
    }

    bool unite(int x, int y){
        x = find(x); y = find(y);
        if(x==y) return false;
        if(par[x]>par[y]) std::swap(x,y);
        par[x]+=par[y];
        par[y] = x;
        return true;
    }

    int size(int x){
        return -par[find(x)];
    }

    int count_group(){
        int c = 0;
        for(int i = 0; i<par.size(); i++){
            if(par[i]<0) c++; 
        }
        return c;
    }
};

