// one-based numbering
struct union_find {
    vector<int> rank, par;
    union_find(int n) {
      rank.resize(n+1);
      par.resize(n+1);
      for(int i = 1; i <= n; i++) rank[i] = 1, par[i] = i;
    }
    int find(int x) {
        if(x == par[x]) return x;
        else return par[x] = find(par[x]);
    }
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return;
        if(rank[x] > rank[y]) par[y] = x;
        else{
            par[x] = y;
            if(rank[x] == rank[y]) rank[y]++;
        }
    }
    bool same(int x, int y) {
        x = find(x); y = find(y);
        return x == y;
    }
};

struct edge {
  int a, b; long long cost;
  bool operator< (struct edge &e) {
    return cost < e.cost;
  }
};

long long kruskal(int n, vector<edge> &v) {
  sort(v.begin(), v.end());
  union_find u = union_find(n);
  long long mincost = 0;
  for (int i = 0; i < v.size(); i++) {
    if (!u.same(v[i].a, v[i].b)){
      mincost += v[i].cost;
      u.unite(v[i].a, v[i].b);
    }
  }
  return mincost;
}


