bool is_prime(ll n){
  ll i = 2;
  if(n==1)return false;
  if(n==2)return true;
  bool res = true;
  while(i*i <n){
    if(n%i==0){
      res = false;
    }
    i = i+1;
  }

  //if(i==1)res = false;
  if(n%i==0)res=false;
  return res;
}

struct city{
  ll x, y, id;
};
struct edge{
  ll u, v, c;
};
llvec p;
vector<edge> e;

ll total;


P root(ll a){
  ll atmp=a;
  ll cnt=0;
  while(atmp!=p[atmp]){
    atmp=p[atmp];
    cnt++;
  }
  p[a]=atmp;
  return {cnt, atmp};
}

bool con(ll u, ll v){
  P ur=root(u);
  P vr=root(v);
  if(ur.second==vr.second){
    return false;
  }else{
    if(ur.first>vr.first)swap(ur, vr);
    p[ur.second]=vr.second;
    return true;
  }
}

