class UnionFind {
  vector<ll> par, rank; // par > 0: number, par < 0: -par
public:
  void init(ll n) {
    par.resize(n, 1); rank.resize(n, 0);
  }
  ll getSize(ll x) {
    return par[find(x)];
  }
  ll find(ll x) {
    if (par[x] > 0) return x;
    return -(par[x] = -find(-par[x]));
  }
  void merge(ll x, ll y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rank[x] < rank[y]) {
      par[y] += par[x];
      par[x] = -y;
    } else {
      par[x] += par[y];
      par[y] = -x;
      if (rank[x] == rank[y]) rank[x]++;
    }
  }
  bool isSame(ll x, ll y) {
    return find(x) == find(y);
  }
};
int main(){
    cin>>N;
    for(ll i=0;i<N;i++){
        x[i].second=i;
        y[i].second=i;
        cin>>x[i].first>>y[i].first;
    }
    sort(x,x+N);
    sort(y,y+N);
    for(ll i=0;i<N-1;i++){
        ll u=x[i].second,v=x[i+1].second;
        edges.push_back(make_pair(x[i+1].first-x[i].first,P(u,v)));
        u=y[i].second,v=y[i+1].second;
        edges.push_back(make_pair(y[i+1].first-y[i].first,P(u,v)));
    }
    sort(edges.begin(),edges.end());
    UnionFind UF;
    UF.init(N);
    ll ans=0;

    for(auto e:edges){
        ll u=e.second.first,
           v=e.second.second;
        if(UF.isSame(u,v))continue;
        ans+=e.first;
        UF.merge(u,v);
    }
    cout<<ans<<endl;
    return 0;
}

