using namespace std;

class UnionFindTree {
  private:
    vector<long long int> par;   // 親
    vector<long long int> depth; // 木の深さ

  public:
    // n要素で初期化
    UnionFindTree(long long int n) {
        for (long long int i = 0; i < n; i++) {
            par.push_back(i);
            depth.push_back(0);
        }
    }

    // 木の根を求める
    long long int find(long long int x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    // xとyの属する集合を併合
    void unite(long long int x, long long int y) {
        x = find(x);
        y = find(y);
        if (x == y)
            return;

        if (depth[x] < depth[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (depth[x] == depth[y])
                depth[x]++;
        }
    }

    // xとyが同じ集合に属するか否か
    bool same(long long int x, long long y) { return find(x) == find(y); }
};

