long long int kruskal() {
    sort(es.begin(), es.end(), comp); // edge.costが小さい順にソートする
    UnionFindTree uft = UnionFindTree(V);
    long long int res = 0;
    for (long long int i = 0; i < es.size(); i++) {
        edge e = es[i];
        if (!uft.same(e.u, e.v)) {
            uft.unite(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}

