const int mxN = 1e5;
vt<ar<int, 3>> E;
int link[mxN], size[mxN];

int find(int x) {
    if (link[x] == x) {
        return x;
    }
    return find(link[x]);
}

bool same(int a, int b) {
    return find(a) == find(b);
}

void unite(int a, int b) {
    a = find(a);
    b = find(b);

    if (size[a] < size[b]) swap(a, b);

    size[a] += size[b];
    link[b] = a;
}

void solve() {
    int n;
    read(n);

    vt<ar<int, 2>> xv, yv;

    map<ar<int, 2>, int> mp;
    FOR(n) {
        int x, y;
        read(x, y);
        mp[{x, y}] = i;
        xv.pb({x, y});
        yv.pb({y, x});
    }

    sort(all(xv));
    sort(all(yv));

    FOR(i, 1, n) {
        int x = abs(xv[i][0] - xv[i - 1][0]);
        int y = mp[{xv[i - 1][0], xv[i - 1][1]}];
        int z = mp[{xv[i][0], xv[i][1]}];
        E.pb({x, y, z});
        x = abs(yv[i][0] - yv[i - 1][0]);
        y = mp[{yv[i - 1][1], yv[i - 1][0]}];
        z = mp[{yv[i][1], yv[i][0]}];
        E.pb({x, y, z});
    }

    sort(all(E));
    FOR(n) {
        link[i] = i;
        size[i] = 1;
    }

    int ans = 0;
    EACH(x, E) {
        if (!same(x[1], x[2])) {
            ans += x[0];
            unite(x[1], x[2]);
        }
    }

    print(ans);

}

