struct UnionFind {
  UnionFind(int sz) : data(sz, -1) {}

  int root(int ver) { return data[ver] < 0 ? ver : data[ver] = root(data[ver]); }

  void unite(int ver1, int ver2) {
    ver1 = root(ver1);
    ver2 = root(ver2);
    if (ver1 != ver2) {
      if (data[ver1] > data[ver2]) swap(ver1, ver2);
      data[ver1] += data[ver2];
      data[ver2] = ver1;
    }
  }

  bool same(int ver1, int ver2) { return root(ver1) == root(ver2); }

  int size(int ver) { return -data[root(ver)]; }

private:
  vector<int> data;
};

using CostType = long long;
struct Edge {
  int src, dst;
  CostType cost;
  Edge(int dst_, CostType cost_ = 0) : src(-1), dst(dst_), cost(cost_) {}
  Edge(int src_, int dst_, CostType cost_) : src(src_), dst(dst_), cost(cost_) {}
};
inline bool operator < (const Edge &lhs, const Edge &rhs) { return lhs.cost < rhs.cost; }
inline bool operator <= (const Edge &lhs, const Edge &rhs) { return lhs.cost <= rhs.cost; }
inline bool operator > (const Edge &lhs, const Edge &rhs) { return lhs.cost > rhs.cost; }
inline bool operator >= (const Edge &lhs, const Edge &rhs) { return lhs.cost >= rhs.cost; }

CostType kruskal(const vector<vector<Edge> > &graph) {
  int sz = graph.size();
  priority_queue<Edge, vector<Edge>, greater<Edge> > que;
  REP(i, sz) for (Edge e : graph[i]) que.emplace(e);
  vector<vector<Edge> > res(sz);
  CostType total = 0;
  UnionFind uf(sz);
  while (!que.empty()) {
    Edge e = que.top(); que.pop();
    if (!uf.same(e.src, e.dst)) {
      res[e.src].emplace_back(e);
      res[e.dst].emplace_back(Edge(e.dst, e.src, e.cost));
      total += e.cost;
      uf.unite(e.src, e.dst);
    }
  }
  // return res;
  return total;
}

