using namespace std;
using ll = long long int;
using P = pair<ll, ll>; // cost, node
using T = tuple<ll, ll, ll>; // x, y, node
const int N = 1e5+9;

struct graph {
    bool used = false;
    vector<P> next;
};

int n;
T xp[N];
T yp[N];
graph g[N];

int main() {
    cin >> n;
    for(int i = 1; i <= n; i++) {
        ll x, y;
        cin >> x >> y;
        xp[i] = T(x, y, i);
        yp[i] = T(y, x, i);
    }
    sort(&xp[1], &xp[n+1]);
    sort(&yp[1], &yp[n+1]);

    for(int i = 1; i <= n-1; i++) {
        ll x1, y1, n1;
        ll x2, y2, n2;
        tie(x1, y1, n1) = xp[i];
        tie(x2, y2, n2) = xp[i+1];
        g[n1].next.push_back(P(abs(x1 - x2), n2));
        g[n2].next.push_back(P(abs(x1 - x2), n1));
    }

    for(int i = 1; i <= n-1; i++) {
        ll y1, x1, n1;
        ll y2, x2, n2;
        tie(y1, x1, n1) = yp[i];
        tie(y2, x2, n2) = yp[i+1];
        g[n1].next.push_back(P(abs(y1 - y2), n2));
        g[n2].next.push_back(P(abs(y1 - y2), n1));
    }

    priority_queue<P, vector<P>, greater<P>> que;
    g[1].used = true;
    for(auto x : g[1].next)  que.push(x);
    ll ans = 0;
    while(!que.empty()) {
        ll cost, node;
        tie(cost, node) = que.top(); que.pop();
        if(g[node].used)  continue;
        g[node].used = true; ans += cost;
        for(auto x : g[node].next)  que.push(x);
    }
    cout << ans << endl;
}

