bool cmp1(const Node &a, const Node &b) {
	return a.x < b.x;
}
bool cmp2(const Node &a, const Node &b) {
	return a.y < b.y;
}
struct Edge{
	int u, v, dis;
	bool operator < (const Edge &e) const {
		return dis < e.dis;
	}
}G[2*N];

int f[N];
int find(int u) {
	return u == f[u] ? u : f[u] = find(f[u]);
}
void merge(int u, int v) {
	u = find(u);
	v = find(v);
	f[u] = v;
}
int main(){
