		int dis = abs(node[i].x - node[i-1].x);
		G[cnt++] = Edge{node[i].id, node[i-1].id, dis};
	}
	sort(node, node+n, cmp2);
	rep(i,1,n) {
		int dis = abs(node[i].y - node[i-1].y);
		G[cnt++] = Edge{node[i].id, node[i-1].id, dis};
