using namespace std;

class unionfind {
  vector<int> par;

public:
  void init(int n) {
    for (int i = 0; i < n; i++) par.push_back(i);
  }

  int find(int i) {
    if (par.at(i) == i) return i;
    return par.at(i) = find(par.at(i));
  }

  void merge(int i, int j) {
    par.at(find(i)) = find(j);
  }
};

int main() {
  int n;
  cin >> n;
  vector<pair<int, int>> x, y;
  vector<tuple<int, int, int>> p;
  for (int i = 0; i < n; i++) {
    int a, b;
    cin >> a >> b;
    x.emplace_back(a, i);
    y.emplace_back(b, i);
  }
  sort(x.begin(), x.end());
  sort(y.begin(), y.end());
  for (int i = 0; i < n - 1; i++) {
    p.emplace_back(x.at(i + 1).first - x.at(i).first, x.at(i).second, x.at(i + 1).second);
    p.emplace_back(y.at(i + 1).first - y.at(i).first, y.at(i).second, y.at(i + 1).second);
  }
  sort(p.begin(), p.end());
  long ans = 0;
  unionfind network;
  network.init(n);
  for (auto r : p) {
    int d = get<0>(r), x1 = get<1>(r), x2 = get<2>(r);
    if (network.find(x1) != network.find(x2)) {
      ans += d;
    }
    network.merge(x1, x2);
  }
  cout << ans << endl;
}

