template <class T>
struct UnionFind
{
	vector<T> data;
	UnionFind(T size) : data(size, -1) {}
	bool unionSet(T x, T y)
	{
		x = root(x); y = root(y);
		if (x != y)
		{
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(T x, T y)
	{
		return root(x) == root(y);
	}
	T root(T x)
	{
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	T size(T x)
	{
		return -data[root(x)];
	}
};

