		Q.push(tie(dist, it->second, next(it)->second));
	}
	ll NoRemainClass = N - 1; // これがゼロになるまで。
	ll ans = 0;
	while (NoRemainClass != 0) {		
		ll dist, cls1, cls2;
		tie(dist, cls1, cls2) = Q.top(); Q.pop();
		if (!UF.unionSet(cls1, cls2)) {
			NoRemainClass -= 1;
			ans += dist;
		}
	}

	cout << ans << endl;

	return 0;
}

