using namespace std;

struct UnionFind {
    vector<int> par;
    vector<int> rank;
    vector<int> num;
    UnionFind(int N) : par(N), rank(N), num(N) {
        for(int i = 0; i < N; i++) {
            par[i] = i;
            rank[i] = 0;
            num[i] = 1;
        }
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) rank[x]++;
        par[y] = x;
        num[x] += num[y];
        num[y] = 0;
        return true;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }
};

struct edge {
    int from, to, weight;
};

bool comp_edge(edge &a, edge &b) {
    return a.weight < b.weight;
}

int main(int argc, const char * argv[]) {

    ios::sync_with_stdio(false);
    cin.tie(0);

    int n; cin >> n;
    vector<pair<int, int>> xs(n), ys(n);
    for (int i = 0; i < n; i++) {
        int x, y; cin >> x >> y;
        xs[i] = make_pair(x, i);
        ys[i] = make_pair(y, i);
    }
    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());

    vector<edge> G;
    for (int i = 0; i < n - 1; i++) {
        G.push_back({xs[i].second, xs[i + 1].second, xs[i + 1].first - xs[i].first});
        G.push_back({ys[i].second, ys[i + 1].second, ys[i + 1].first - ys[i].first});
    }

    sort(G.begin(), G.end(), comp_edge);

    UnionFind tree(n);
    int64_t ans = 0;

    for (int i = 0; i < G.size(); i++) {
        int s = G[i].from, t = G[i].to;
        if (!tree.same(s, t)) {
            ans += G[i].weight;
            tree.unite(s, t);
        }
    }

    cout << ans << endl;

    return 0;
}

