struct Vertex
{
    int id;
    int x;
    int y;
    int parent;
    int root(vector<Vertex>& vs)
    {
        if(parent == -1)
        {
            return id;
        }
        auto r = vs[parent].root(vs);
        parent = r;
        return r;
    }
};

struct Edge
{
    int s;
    int t;
    int d;
};

int main(int, const char**)
{
    int n;
    cin >> n;
    vector<Vertex> vs(n);
    vector<int> xs(n), ys(n);
    rep(i, n)
    {
        int x, y;
        cin >> x >> y;
        vs[i] = {i, x, y, -1};
        xs[i] = i;
        ys[i] = i;
    }

    sort(xs.begin(), xs.end(), [&vs](const auto& a, const auto& b){
        return vs[a].x < vs[b].x;
    });
    sort(ys.begin(), ys.end(), [&vs](const auto& a, const auto& b){
        return vs[a].y < vs[b].y;
    });
    vector<Edge> es(n * 2);
    es.resize(0);
    rep(i, n - 1)
    {
        es.push_back({xs[i], xs[i + 1], abs(vs[xs[i]].x - vs[xs[i + 1]].x)});
        es.push_back({ys[i], ys[i + 1], abs(vs[ys[i]].y - vs[ys[i + 1]].y)});
    }

    sort(es.begin(), es.end(), [](const auto& a, const auto& b){
        return a.d < b.d;
    });

    int64_t cost = 0;
    for(auto& e : es)
    {
        auto& s = vs[e.s];
        auto& t = vs[e.t];
        auto d = e.d;
        if(s.root(vs) == t.root(vs))
        {
            continue;
        }
        cost += d;
        vs[t.root(vs)].parent = e.s;
    }

    cout << cost << endl;
    return 0;
}

