using namespace std;
using namespace __gnu_pbds;

#define fi first
#define se second
#define mp make_pair
#define pb push_back
#define fbo find_by_order
#define ook order_of_key
#define mt make_tuple

typedef long long ll;
typedef pair<ll,ll> ii;
typedef vector<int> vi;
typedef long double ld;
typedef tree<int, null_type, less<int>, rb_tree_tag, tree_order_statistics_node_update> pbds;

const long long mod = 1000000007;
const long long inf = 1e18;

int par[100001];
int ran[100001];

int findset(int i){
    if(par[i]==i)
        return i;
    else
        return par[i]=findset(par[i]);
}

void merge(int i,int j){
    int b=findset(i);
    int s=findset(j);
    if(ran[b]<ran[s])swap(b,s);
    else ran[b]++;
    par[s]=b;
}

int main() {
    std::ios::sync_with_stdio(false);
    int n;
    cin>>n;
    for(int i=0;i<n;i++){
        par[i]=i;
        ran[i]=1;
    }
    vector<tuple<int,int,int>> kruskal;
    vector<pair<int,int> > x;
    vector<pair<int,int> > y;
    for(int i=0;i<n;i++){
        int a,b;
        cin>>a>>b;
        x.pb({a,i});
        y.pb({b,i});
    }
    sort(x.begin(),x.end());
    sort(y.begin(),y.end());
    for(int i=0;i<n-1;i++){
        int p=x[i].fi,q=x[i].se;
        int r=x[i+1].fi,s=x[i+1].se;
        kruskal.push_back(mt(r-p,q,s));
        p=y[i].fi,q=y[i].se;
        r=y[i+1].fi,s=y[i+1].se;
        kruskal.push_back(mt(r-p,q,s));
    }
    sort(kruskal.begin(),kruskal.end());

    long long ans=0;
    for(long i=0;i<kruskal.size();i++){
        int u,v,c;
        c=get<0>(kruskal[i]);
        u=get<1>(kruskal[i]);
        v=get<2>(kruskal[i]);
        if(findset(u)!=findset(v)){
            merge(u,v);
            ans+=c;
        }
    }
    cout<<ans<<endl;
    return 0;
}

