        v[i].second = i;
    }
    sort(v.begin(), v.end());
    for(i = 1; i < n;i++){
        pq.push({v[i].first.first - v[i - 1].first.first, {v[i].second, v[i-1].second}});
    }
    sort(v.begin(), v.end(), [](const auto &a, const auto &b) {
        return a.first.second < b.first.second;
    });
    for(i = 1; i < n; i++) {
        pq.push({v[i].first.second - v[i - 1].first.second, {v[i].second, v[i-1].second}});
    }

    UnionFind uf;
    ll ret = 0;
    while(!pq.empty()) {
        auto x = pq.top();
        pq.pop();
        if(!uf.same(x.second.first,x.second.second)){
            uf.unite(x.second.first, x.second.second);
            ret += x.first;
        }
    }
    cout << ret << endl;
    return 0;
}

