typedef std::pair<ll, ll> P;

ll INF = 9223372036854775806;

ll prim(vector<bool> &visit, vector<vector<P>> E)
{
    ll total_cost = 0;

    priority_queue<P, vector<P>, greater<P>> S;
    visit[0] = 1;
    for (P u_pair : E[0])
    {

        S.push(u_pair);
    }

    while (!S.empty())
    {

        ll cost = S.top().first;
        ll u = S.top().second;
        S.pop();

        if (visit[u] == 0)
        {
             //cout << cost <<endl;
            visit[u] = 1;
            total_cost += cost;

            for (P v_pair : E[u])
            {
                if (visit[v_pair.second] == 0)
                {
                    S.push(v_pair);
                }
            }
        }
    }

    return total_cost;
}

