    ll _x, _y;
    cin >> _x >> _y;
    x[i] = make_pair(_x, i);
    y[i] = make_pair(_y, i);
  }

  vector<vector<ll>> g(N, vector<ll>(0));
  map<P, ll> m;
  sort(x.begin(), x.end());
  sort(y.begin(), y.end());

  make_graph(x, g, m);
  make_graph(y, g, m);

  ll cnt = solve_prim(g, m);
  cout << cnt << endl;
}

