    v.push_back({y[i+1].F-y[i].F, {y[i].S, y[i+1].S}});
  }
  sort(v.begin(),v.end());
  UnionFind uf(n);
  ll ans = 0;
  for(auto it:v){
    if(!uf.check(it.S.F,it.S.S)){
      uf.unite(it.S.F,it.S.S);
      ans += it.F;
    }
  }
  cout << ans << endl;
  return 0;
}

