  ll res=0;
  sort(e,e+E,comp);//コストの小さい順にソート
  uft u(V);//頂点数VでUnionFind木を作成
  FOR(i,0,E){
    int f=e[i].from,t=e[i].to,c=e[i].cost;
    if(!u.same(f,t)){
      res+=c;
      u.unite(f,t);
    }
  }
  return res;
}
