                dst.insert(make_pair(min(ny-py, abs(po[n].first-po[p].first)), make_pair(n, p)));
                break;
            }
            break;
        }
    }

    int cost = 0;
    for (auto&& d : dst) {
        if (uf.same(d.second.first, d.second.second)) continue;
        else {
            cost += d.first;
            uf.unite(d.second.first, d.second.second);
        }
    }

    cout<<cost<<endl;

    return 0;
}

