const int N = 2E5 + 10;

int n, Root[N], Ranked[N];
ii a[N], x[N], y[N];

void Input()
{
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i].X >> a[i].Y;
}

int Find_Root(int u)
{
    if (u == Root[u]) return u;
    return Root[u] = Find_Root(Root[u]);
}

bool Union(int u, int v)
{
    u = Find_Root(u);
    v = Find_Root(v);
    if (u == v) return false;

    if (Ranked[u] > Ranked[v]) swap(u, v);
    Root[u] = v;
    Ranked[v] += Ranked[u];

    return true;
}

ll Modify(int u, int v)
{
    ll x = abs(a[u].X - a[v].X);
    ll y = abs(a[u].Y - a[v].Y);
    return min(x, y);
}

void Solve()
{
    ll res = 0;
    priority_queue <iii, vector <iii>, greater <iii> > PQ;
    for (int i = 1; i <= n; i++) x[i] = {a[i].X, i};
    for (int i = 1; i <= n; i++) y[i] = {a[i].Y, i};
    sort(x + 1, x + 1 + n);
    sort(y + 1, y + 1 + n);

    for (int i = 1; i < n; i++) {
        int u = x[i].Y;
        int v = x[i + 1].Y;
        ll Dist = Modify(u, v);
        PQ.push({Dist, {u, v}});

        u = y[i].Y;
        v = y[i + 1].Y;
        Dist = Modify(u, v);
        PQ.push({Dist, {u, v}});

    }
    for (int i = 1; i <= n; i++) Root[i] = i, Ranked[i] = 1;

    int k = n - 1;
    while (k && PQ.size()) {
        ll Distance = PQ.top().X;
        int u = PQ.top().Y.X;
        int v = PQ.top().Y.Y;
        PQ.pop();
        if (Union(u, v)) {
            k--;
            res += Distance;
        }
    }

    cout << res;
}

