struct UnionFind{
    int data[n_max];
    UnionFind(int n){
        REP(i,n) data[i]=i;
    }

    int root(int x){
        int tmp;
        if(data[x]==x) return x;
        else{
            tmp=root(data[x]);
            data[x]=tmp;
            return tmp;
        }
    }

    bool is_same(int x,int y){
        return root(x) == root(y);
    }

    void merge(int x,int y){
        data[root(x)] = root(y);
    }
};


