class UnionFindTree{
private:
  std::vector<int> parent;

public:
  UnionFindTree(int n) : parent(n){
    for(int i = 0; i < n; i++) parent[i] = i;
  }

  int find(int x){
    if(parent[x] == x) return x;
    else return parent[x] = find(parent[x]);
  }

  void unite(int x, int y){
    parent[find(x)] = find(y);
  }

  bool same(int x, int y){
    return find(x) == find(y);
  }
};

struct Road{
  int t1;
  int t2;
  int cost;

  bool operator>(const Road& r) const{
    return cost > r.cost;
  }
};

struct Town{
  int x;
  int y;
  int name;
};

int cost_of_road(Town t1, Town t2){
  return std::min(std::abs(t1.x - t2.x), std::abs(t1.y - t2.y));
}

int main(){
  int N;
  std::cin >> N;

  std::vector<Town> towns(N);
  std::priority_queue<Road, std::vector<Road>, std::greater<Road>> pq;
  for(int i = 0; i < N; i++){
    int x, y;
    std::cin >> x >> y;
    towns[i] = {x, y, i};
  }

  std::sort(towns.begin(), towns.end(), [](const Town& t1, const Town& t2){
    return t1.x < t2.x;
  });
  for(int i = 1; i < N; i++){
    pq.push({towns[i - 1].name, towns[i].name, cost_of_road(towns[i - 1], towns[i])});
  }

  std::sort(towns.begin(), towns.end(), [](const Town& t1, const Town& t2){
    return t1.y < t2.y;
  });
  for(int i = 1; i < N; i++){
    pq.push({towns[i - 1].name, towns[i].name, cost_of_road(towns[i - 1], towns[i])});
  }

  UnionFindTree tree(N);
  long long sum_cost = 0;

  while(!pq.empty()){
    Road r = pq.top();
    pq.pop();

    if(!tree.same(r.t1, r.t2)){
      tree.unite(r.t1, r.t2);
      sum_cost += r.cost;
    }
  }

  std::cout << sum_cost << std::endl;

  return 0;
}

