struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) {}

	// union
	bool unionSet(int x, int y) {
		x = root(x);
		y = root(y);
		if (x != y) {
			if (data[y] < data[x]) {
				swap(x, y);
			}
			data[x] += data[y];
			data[y] = x;
		}
		return x != y;
	}

	// find
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}

	// root
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}

	// size
	int size(int x) {
		return -data[root(x)];
	}
};

