/*
 * Union Find Tree
 */
ll par[100002]; // 親
ll rnk[100002]; // 木の深さ

void init(ll n) {
    rep(i, n+1) par[i] = i, rnk[i] = 0;
}

ll find(ll x) {
    if (par[x] == x) return x;
    else return par[x] = find(par[x]);
}

void unite(ll x, ll y) {
    x = find(x);
    y = find(y);
    if (x == y) return;

    if (rnk[x] < rnk[y]) par[x] = y;
    else {
        par[y] = x;
        if (rnk[x] == rnk[y]) rnk[x]++;
    }
}

bool same(ll x, ll y) {
    return find(x) == find(y);
}

/*
 * kruskal
 */
struct edge {
    ll u, v, cost; 
    edge(ll a, ll b, ll c): u(a), v(b), cost(c) {}
};

bool comp(const edge& e1, const edge& e2) {
    return e1.cost < e2.cost;
}

vector<edge> es;
ll V;

ll kruskal() {
    sort(es.begin(), es.end(), comp);
    init(V);
    ll res = 0;
    rep(i, es.size()) {
        edge e = es[i];
        if (!same(e.u, e.v)) {
            unite(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}

