using ll = long long;

template <typename T>
vector<size_t> argsort(const vector<T> &target) {
    vector<size_t> idx(target.size());
    iota(idx.begin(), idx.end(), 0);
    sort(idx.begin(), idx.end(), [&target](size_t i1, size_t i2) {return target[i1] < target[i2];});
    return idx;
}

struct Edge{
    ll from, to, cost;
    bool operator > (const Edge & e){
        return cost > e.cost;
    }
};

struct UnionFind {
    vector<ll> data;

    UnionFind(int size) : data(size, -1) {}

    bool unionSet(int x, int y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if (data.at(y) < data.at(x)) swap(x, y);
            data.at(x) += data.at(y);
            data.at(y) = x;
        }
        return x != y;
    }

    bool findSet(int x, int y) {
        return root(x) == root(y);
    }

    int root(int x) {
        return data.at(x) < 0 ? x : data.at(x) = root(data.at(x));
    }

    int size(int x) {
        return -data.at(root(x));
    }
};


int main() {
    ll N;
    cin >> N;
    vector<ll> xs(N);
    vector<ll> ys(N);
    for (auto && i: irange(0LL, N)){
        cin >> xs.at(i) >> ys.at(i);
    }
    vector<size_t> x_sort_idx = argsort(xs);
    vector<size_t> y_sort_idx = argsort(ys);


    // あとは普通にクラスカル法を適用するだけ
    vector<Edge> edges{};
    for (auto && i: irange(0LL, N-1)){
        size_t x1{x_sort_idx.at(i)}, x2{x_sort_idx.at(i+1)};
        size_t y1{y_sort_idx.at(i)}, y2{y_sort_idx.at(i+1)};
        edges.emplace_back(Edge{x1, x2, xs.at(x2)-xs.at(x1)});
        edges.emplace_back(Edge{y1, y2, ys.at(y2)-ys.at(y1)});
    }
    sort(edges.begin(), edges.end(), greater<>());
    UnionFind u(N);
    ll cost{0};
    while(!edges.empty()){
        Edge e = edges.back();
        edges.pop_back();
        if (!u.findSet(e.from, e.to)){
            cost += e.cost;
            u.unionSet(e.from, e.to);
        }
    }
    cout << cost;




    return 0;
}

