using namespace std;

typedef long long ll;
typedef pair<int, int> P;

const int INF = 1001001001;

int used[100010];

int main(){
    int N;
    cin >> N;
    vector<P> x(N), y(N);

    for(int i = 0; i < N; ++i){
        int temp;
        cin >> temp;
        x[i] = P(temp, i);
        cin >> temp;
        y[i] = P(temp, i);
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());

    vector<vector<P>> graph(N);     // (cost, to)
    for(int i = 0; i < N - 1; ++i){
        P p1 = x[i];
        P p2 = x[i + 1];
        int temp = p2.first - p1.first;
        graph[p1.second].push_back(P(temp, p2.second));
        graph[p2.second].push_back(P(temp, p1.second));

        p1 = y[i];
        p2 = y[i + 1];
        temp = p2.first - p1.first;
        graph[p1.second].push_back(P(temp, p2.second));
        graph[p2.second].push_back(P(temp, p1.second));
    }

    ll res = 0;
    priority_queue<P, vector<P>, greater<P>> que;
    que.push(P(0, 0));          // (現在の部分最小全域木からのcost, coord)

    while(!que.empty()){
        P p = que.top();
        que.pop();

        // 部分最小全域木に含まれていれば何もしない
        if(used[p.second])      continue;

        // 部分最小全域木に入れる(usedのフラグを立てる)
        // priority_queueから部分木からの最小コストは取り出せている
        used[p.second] = true;
        res += p.first;

        for(int i = 0; i < graph[p.second].size(); ++i){
            P t = graph[p.second][i];
            // 部分最小全域木からの最小コスト候補をどんどん入れていく
            // 最小全域木に含まれなければcontinueで操作が飛ばされる
            que.push(P(t.first, t.second));
        }
    }

    cout << res << endl;
}

