typedef long long ll;

struct UnionFind {
    vector<int> par;
    vector<int> rank;

    UnionFind(int N) : par(N), rank(N) {
        for (int i = 0; i < N; i++) {
            par[i] = i;
            rank[i] = 0;
        }
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]) swap(rx, ry);
        par[ry] = rx;
        if (rank[rx] == rank[ry]) rank[rx]++;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }
};

//Kruskalを適応したいが辺の数が多すぎるので減らす。
//x軸方向にソートして隣接している部分のみエッジを入れる
//y軸方向にソートして隣接つしている部分のみエッジを入れる
//こうすると，不必要なエッジを省ける。計算量はO(N)。

int main() {
    int N; cin >> N;
    using P = pair<int, int>;
    using Edge = pair<int, P>;
    vector<Edge> edges;
    vector<P> grids;
    for (int i = 0; i < N; i++) {
        int x, y; cin >> x >> y;
        grids.push_back(P(x, y));
    }
    grids.erase(unique(grids.begin(), grids.end()), grids.end()); //重複ノードは消す

    //x軸方向にソートして隣接してるもののみエッジに組み込む
    sort(grids.begin(), grids.end());
    for (int i = 0; i < grids.size()-1; i++) {
        int a = grids[i].first, b = grids[i].second;
        int c = grids[i+1].first, d = grids[i+1].second;
        int cost = min(abs(a-c), abs(b-d));
        edges.push_back(Edge(cost, P(i, i+1)));
        edges.push_back(Edge(cost, P(i+1, i)));
    }
    //y軸方向も同様
    sort(grids.begin(), grids.end(), [](P a, P b) {
        return a.second < b.second;
    });
    for (int i = 0; i < grids.size()-1; i++) {
        int a = grids[i].first, b = grids[i].second;
        int c = grids[i+1].first, d = grids[i+1].second;
        int cost = min(abs(a-c), abs(b-d));
        edges.push_back(Edge(cost, P(i, i+1)));
        edges.push_back(Edge(cost, P(i+1, i)));
    }

    //Kruskal
    sort(edges.begin(), edges.end());
    UnionFind uf(grids.size());
    ll res = 0;
    for (auto e : edges) {
        int u = e.second.first, v = e.second.second;
        if (uf.same(u, v)) continue;
        uf.unite(u, v);
        res += e.first;
    }
    cout << res << endl;
}

