		unionfind uf(N);

		sort(e.begin(), e.end(), [](edge x, edge y) {return x.d < y.d; });

		dis = 0;

		rep(i,e.size()){
			ll a = e[i].fr;
			ll b = e[i].to;
			if (uf.same(a, b)) { continue; }
			g[a].push_back({ e[i].ind,a,b,e[i].d });
			g[b].push_back({ e[i].ind,b,a,e[i].d });
			dis += e[i].d;
			uf.unite(a, b);
		}

	}


};



