// union find
class UnionFind {
private:
  vector<LL> p;

public:
  UnionFind(LL size) : p(size, -1) {}

  bool unionSet(LL x, LL y) {
    x = root(x);
    y = root(y);

    if (x != y) {
      if (x > y) { swap(x, y); }
      p[x] += p[y];
      p[y] = x;
    }   

    return x != y;
  }

private:
  LL root(LL x) {
    return p[x] < 0 ? x : p[x] = root(p[x]);
  }
};


