        return n1.first > n2.first;
    }
};

priority_queue<pair<int64_t, int>, vector<pair<int64_t, int> >, compq> q; 

int getMSTWeight(int startNode) {
	for (int i = 0; i < g[startNode].size(); i++) {
		q.push(g[startNode][i]);
	}
	vis[startNode] = true;

	int64_t totalWeight = 0;

	while (!q.empty()) {
		while (vis[q.top().second] && !q.empty()) { 
			q.pop();
		}

		if (q.empty()) break;

		auto top = q.top();
		q.pop();
		totalWeight += top.first;
		vis[top.second] = true;
		//cout << "selected " << top.second + 1 << "; val: " << top.first << endl;

		for (int i = 0; i < g[top.second].size(); i++) {
			if (!vis[g[top.second][i].second]) {
				q.push(g[top.second][i]);
			}
		}
	}

	return totalWeight;
}

