      merge(ed.ND.ST,ed.ND.ND);
      cost+=ed.ST;
			//cout<<"merge... cost:"<<ed.ST<<" /"<<ed.ND.ST<<"&"<<ed.ND.ND<<endl;
    }
}
  return cost;
}


