struct UnionFind {
    typedef vector<int> vi;
    int n;
    vi par, rank, cnt;

    UnionFind(int n)
        : n(n), par(n), rank(n, 0), cnt(n, 1) {
        for (int i = 0; i < n; i++) par[i] = i;
    }

    int find(int a) {
        if (par[a] == a) return a;
        return par[a] = find(par[a]);
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);

        if (a == b) return;
        if (rank[a] < rank[b]) {
            par[a] = b;
            cnt[b] += cnt[a];
        } else {
            par[b] = a;
            cnt[a] += cnt[b];
            if (rank[a] == rank[b]) rank[a]++;
        }
    }

    int count(int a) { return cnt[find(a)]; }

    bool same(int a, int b) { return find(a) == find(b); }
};

