class union_find{
    public:
    vector<int> parent;
    vector<int> sz;
    //初期化
    union_find(int n): parent(n), sz(n){
        for(int i=0;i<n;++i){
            parent[i] = i;
            sz[i] = 1;
        }
    }
    //親を探す
    int root(int i){
        //return parent[i]==i ? i:parent[i]=root(parent[i]);
        if(parent[i]==i) return i;
        else return parent[i]=root(parent[i]);
    }
    //i, jを結合
    void unite(int i, int j){
        i = root(i);
        j = root(j);
        if(i==j) return;
        if(sz[i] > sz[j]){
            parent[j] = i;
        }
        else{
            parent[i] = j;
            if(sz[i]==sz[j]){
                sz[j]++;
            }
        }
    }
    //iとjの親が同じか確認
    bool same(int i, int j){
        return root(i)==root(j);
    }
    //iのサイズを確認
    int size(int i){
        return sz[root(i)];
    }
};

