        cost[i] = min(abs(p[status.second].first - p[i].first), abs(p[status.second].second - p[i].second));
        pq.push(make_pair(min(abs(p[status.second].first - p[i].first), abs(p[status.second].second - p[i].second)), i));
    }
    return res + calc(now + 1);
}

