		p = pq.top();
		pq.pop();
		if (find(p.first.id) != f || find(p.second.id) != f) {
			un(p.first.id, f);
			un(p.second.id, f);
			ans += min(abs(p.first.x - p.second.x), abs(p.first.y - p.second.y));
		} else {
			i--;
			continue;
		}
	}

	cout << ans << endl;
}

