using namespace std;
typedef unsigned long long ull;
typedef long long ll;

struct EdgeM
{
	int to;
	ll cost;
};


ll calcMinSpanningTree(vector<vector<EdgeM>>& G)
{
	auto V = (int)G.size();
	vector<ll> cost(V, LLONG_MAX);
	vector<bool> used(V);
	cost[0] = 0;
	auto res = 0ll;

	priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> q;
	q.push({ 0, 0 });
	while (!q.empty())
	{
		auto p = q.top();
		q.pop();

		auto u = p.second;
		if (used[u])
		{
			continue;
		}
		used[u] = true;
		res += p.first;

		for (auto& e : G[u])
		{
			if (cost[e.to] > e.cost && !used[e.to])
			{
				cost[e.to] = e.cost;
				q.push({ e.cost, e.to });
			}
		}
	}

	return res;
}


