    cin >> x >> y;
    X[i] = {x, i};
    Y[i] = {y, i};
  }

  vector<tuple<int, int, int>> E((N - 1) * 2);
  sort(X.begin(), X.end());
  for (int i = 1; i < N; ++i) {
    int x0, x1, t0, t1;
    tie(x0, t0) = X[i - 1];
    tie(x1, t1) = X[i];
    E[i - 1] = make_tuple(abs(x1 - x0), t0, t1);
  }

  sort(Y.begin(), Y.end());
