// UFDS for checking if two nodes are connected
class UFDS {

public:
	// this function initializes the UFDS
	UFDS(ll n) {
		par.resize(n);
		sz.resize(n);
		for (ll i = 0; i < n; i++) {
			par[i] = i;
			sz[i] = 1;
		}
	}

	//  this function returns the representative of the group that item x is in
	ll find(ll x) {
		if (par[x] == x) {
			return x;
		}
		else {
			// path compression: link x -> representative of the group directly
			// recursively follow the arrows up to the representative
			par[x] = find(par[x]);
			return par[x];
		}
	}

	// this function combines the groups items x and y are in
	void merge(ll x, ll y) {
		// find the representatives of the two groups
		x = find(x);
		y = find(y);
		if (x == y) {
			return;
		}
		par[x] = y; // x -> y
		sz[y] += sz[x]; // number of items in group y has increased by the number of items in group x
		return;
	}

	// this function returns the size of the group item x is in
	ll get_size(ll x) {
		return sz[find(x)];
	}

	// this function returns true if items x and y are in the same set
	bool same_set(ll x, ll y) {
		return find(x) == find(y);
	}

private:
	vector<ll> par;
	// par[i] is the 'parent' of item i
	// i -> par[i]
	vector<ll> sz;
	// sz[i] stores the number of items in group i
};


// weight, endpoints of the edge
int N;

bool comp(vector<int> a, vector<int> b) {
	return a[1] < b[1];
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	// Read in graph
	cin >> N;
	vector<vector<int>> verts(N);
	for (int i = 0; i < N; i++) {
		int X, Y;
		cin >> X >> Y;
		verts[i] = { X, Y, i };
	}

	vector<vector<int>> G;
	// sort by x
	sort(verts.begin(), verts.end());

	// Add to edges
	for (int i = 0; i < N - 1; i++) {
		G.push_back({ verts[i + 1][0] - verts[i][0], verts[i][2], verts[i + 1][2] });
	}

	// sort by y
	sort(verts.begin(), verts.end(), comp);

	// Add to edges
	for (int i = 0; i < N - 1; i++) {
		G.push_back({ verts[i + 1][1] - verts[i][1], verts[i][2], verts[i + 1][2] });
	}

	// Kruskal's Algorithm
	// First sort the edges by weight in ascending order
	sort(G.begin(), G.end());

	// Initialize UFDS
	UFDS data(N);

	// To track the cost of the MST
	int cost = 0;
	// Go through edges one by one, add them into the MST as long as a cycle is not formed
	int verts_in_graph = 0;
	for (int i = 0; i < G.size(); i++) {
		int W = G[i][0], A = G[i][1], B = G[i][2];
		// Note: adding an edge A - B only forms a cycle if A and B are already connected via some other path
		// Two nodes are already connected, if they are in the same set
		if (data.find(A) != data.find(B)) {
			data.merge(A, B);
			verts_in_graph++;
			cost += W;
		}
		if (verts_in_graph == N - 1) {
			break;
		}
	}

	cout << cost << "\n";

}

