using namespace std;

int main() {
  int N;
  cin >> N;
  vector<pair<int, int>> X, Y;
  for (int i = 0; i < N; i++) {
    int x, y;
    cin >> x >> y;
    X.push_back(make_pair(x, i));
    Y.push_back(make_pair(y, i));
  }
  auto compare = [](const pair<int, int> &a, const pair<int, int> &b) {
                   if (a.first < b.first) {
                     return 1;
                   }else {
                     return 0;
                   }
                 };
  sort(X.begin(), X.end(), compare);
  sort(Y.begin(), Y.end(), compare);
  map<int, vector<pair<int, int>>> edges; // key: fr, value: (to, dist)                                                                                                                                                                                                                       
  for (int i = 0; i < N-1; i++) {
    edges[X[i].second].push_back(make_pair(abs(X[i].first-X[i+1].first), X[i+1].second));
    edges[Y[i].second].push_back(make_pair(abs(Y[i].first-Y[i+1].first), Y[i+1].second));
  }
  for (int i = 1; i < N; i++) {
    edges[X[i].second].push_back(make_pair(abs(X[i].first-X[i-1].first), X[i-1].second));
    edges[Y[i].second].push_back(make_pair(abs(Y[i].first-Y[i-1].first), Y[i-1].second));
  }
  // mst                                                                                                                                                                                                                                                                                      
  auto compare2 = [](const pair<int, int> &a, const pair<int, int> &b) {
                   if (a.first > b.first) {
                     return 1;
                   }else {
                     return 0;
                   }
                 };
  priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(compare2)> q(compare2);
  int start = 0;
  for (pair<int, int> e : edges[start]) {
    q.push(e);
  }
  long ans = 0;
  int cnt = 0;
  vector<bool> in_tree(N, false);
  in_tree[start]=true;
  while (!q.empty() && cnt < N-1) {
    pair<int, int> e = q.top();
    q.pop();
    if (in_tree[e.second]) {
      continue;
    }
    ans += e.first;
    in_tree[e.second] = true;
    cnt++;
    for (pair<int, int> ee : edges[e.second]) {
      if (!in_tree[ee.second]) {
        q.push(ee);
      }
    }
  }
  cout << ans << endl;
}

