}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using P = pair<ll,ll>;
#define rep(i, n) for(int i = 0; i < (int)(n); i++)

int main(){
    ll N; cin>>N;

    vector<P> x_pos;
    vector<P> y_pos;

    vector<ll> x_map(N,0);
    vector<ll> y_map(N,0);

    rep(i,N){
        ll x,y;cin>>x>>y;
        x_pos.push_back(make_pair(x,i));
        y_pos.push_back(make_pair(y,i));
        x_map[i] = x;
        y_map[i] = y;
    }

    sort(x_pos.begin(),x_pos.end());
    sort(y_pos.begin(),y_pos.end());

    // x_sorted_pos[i]: i番目の都市のx位置のソートした際の順番
    vector<ll> x_sorted_pos(N,0);
    vector<ll> y_sorted_pos(N,0);
    rep(i,N){
        P temp_x = x_pos.at(i);
        x_sorted_pos.at(temp_x.second) =i;

        P temp_y = y_pos.at(i);
        y_sorted_pos.at(temp_y.second) =i;
    }


    //最小連結木を作る方針でやろう。
    //小さい部分グラフから初めて、最も近いノードの点を加えていく
    //この際に、追加するべき候補としてはx,yのそれぞれ両方向あることに注意しよう
    //そのノードが追加済ならばスキップする
    //一番目の町から探索を始めよう。

    priority_queue<P, vector<P>, greater<P>> pq;
    pq.push(make_pair(0, 0));//

    vector<ll> cost_list(N,-1);

    while(!pq.empty()){
        P next_pos = pq.top(); pq.pop();
        if(cost_list.at(next_pos.second)!=-1){
            continue;
        }
        cost_list.at(next_pos.second) =  next_pos.first;

        ll x_position = x_map.at(next_pos.second);
        ll y_position = y_map.at(next_pos.second);

        ll x_index = x_sorted_pos.at(next_pos.second);
        ll y_index = y_sorted_pos.at(next_pos.second);
        for(int i=-1;i<2;i++){
            if(i==0)continue;
            if(x_index+i<0 || x_index+i>=N)continue;
            P next_candidate = x_pos.at(x_index+i);
            if(cost_list.at(next_candidate.second)!=-1){
                continue;
            }
            pq.push(make_pair(abs(x_position-next_candidate.first), next_candidate.second));
        }
        for(int i=-1;i<2;i++){
            if(i==0)continue;
            if(y_index+i<0 || y_index+i>=N)continue;
            P next_candidate = y_pos.at(y_index+i);
            if(cost_list.at(next_candidate.second)!=-1){
                continue;
            }
            pq.push(make_pair(abs(y_position-next_candidate.first), next_candidate.second));
        }
    }

    ll total = 0;
    for(int i=0;i<N;i++){
        total+=cost_list.at(i);
    }
    cout<<total<<endl;

    return 0;



}

