static const LL INFTY = (1<<21);

LL M[MAX_NUM][MAX_NUM];

LL prim(LL n){
	int u, minv;
	int d[MAX_NUM], p[MAX_NUM], color[MAX_NUM];

	REP(i, n){
		d[i] = INFTY;
		p[i] = -1;
		color[i] = 0;
	}

	d[0] = 0;

	while(1){
		minv = INFTY;
		u = -1;
		REP(i, n){
			if(minv > d[i] && color[i] != 2){
				u = i;
				minv = d[i];
			}
		}
		if(u == -1) break;
		color[u] = 2;
		REP(v, n){
			if(color[v] != 2 && M[u][v] != INFTY){
				if(d[v] > M[u][v]){
					d[v] = M[u][v];
					p[v] = u;
					color[v] = 1;
				}
			}
		}
	}
	LL sum = 0;
	REP(i, n){
		if(p[i] != -1) sum += M[i][p[i]];
	}

	return sum;
}

