struct Kruskal
{
	int V, E;
	vector<Edge> edges;
	vector<Edge> min_span_tree;
	long long min_span_cost;

	Kruskal(int V, const vector<Edge> &edges) : V(V), E(edges.size()), edges(edges) {}

	void calc() {
		auto edge_comp = [&](Edge e1, Edge e2) -> bool {
			return e1.cost < e2.cost;
		};
		sort(edges.begin(), edges.end(), edge_comp);
		UnionFind uf(V);
		min_span_cost = 0;
		for (Edge e : edges) {
			if (uf.same(e.a, e.b)) continue;
			min_span_tree.push_back(e);
			uf.merge(e.a, e.b);
			min_span_cost += e.cost;
		}
	}
};

