      return ct < o.ct;
    }
};

bool cpX(T3 a,T3 b) {
  return get<0>(a) < get<0>(b);
}

bool cpY(T3 a, T3 b) {
  return get<1>(a) < get<1>(b);
}

struct Graph {
  int N;
  vector<Edge> Es;

  int kruskal() {
    UnionFind uf(N);
    sort(Es.begin(), Es.end());
    int m=0,i;

    for(i=0; i<Es.size(); i++) {
      Edge& e = Es.at(i);
      if(!uf.issame(e.a, e.b)) {
        m += e.ct;
        uf.merge(e.a, e.b);
      }
    }

    return m;
  }
};

