    return a.cost < b.cost;
}

bool comp1(const pair<int, pair<int, int>> a, const pair<int, pair<int, int>> b)
{
    return a.second.first < b.second.first;
}

bool comp2(const pair<int, pair<int, int>> a, const pair<int, pair<int, int>> b)
{
    return a.second.second < b.second.second;
}

int V, E;

ll kruskal()
{
    sort(edges.begin(), edges.end(), comp);

    UnionFind Unitree(V);

    ll res = 0;
    for (auto edge : edges)
    {
        if (!Unitree.same(edge.from, edge.to))
        {
            Unitree.unite(edge.from, edge.to);
            res += edge.cost;
        }
    }
    return res;
}

