    {
        cin >> x[i] >> y[i];
    }
    vector<int> ids(n);
    iota(ALL(ids), 0);
    sort(ALL(ids), [&](int i, int j) {
        return x[i] < x[j];
    });
    for (int i = 0; i < n-1; i++)
    {
        int u = ids[i], v = ids[i + 1];
        edges.push_back((Edge(x[v] - x[u], {u, v})));
    }

    sort(ALL(ids), [&](int i, int j) {
        return y[i] < y[j];
    });
    for (int i = 0; i < n - 1; i++)
    {
        int u = ids[i], v = ids[i + 1];
        edges.push_back((Edge(y[v] - y[u], {u, v})));
    }
    //kruskal法
    sort(ALL(edges));
    UnionFind uni(n);
    int ans = 0;
    for(auto e :edges){
        int u = e.second.first;
        int v = e.second.second;
        int cnt = e.first;
        if(uni.issame(u,v)){
            continue;
        }
        uni.merge(u, v);
        ans += cnt;
    }
    cout << ans << endl;

    return 0;
}

