ll prim(void) {
	mincost[0] = 0LL;
	ll res = 0LL;

	while (true) {
		int v = -1;
		for (int u = 0; u < N; ++u) {
			if (!used[u] && (v == -1 || mincost[u] < mincost[v]))
				v = u;
		}
		if (v == -1)
			break;
		used[v] = true;
		res += mincost[v];
		for (int u = 0; u < N; ++u) {
			mincost[u] = min(mincost[u], (ll)cost[v][u]);
		}
	}
	return res;
}

int main(void) {
