	cost.resize(N, v);
	sort(X.begin(), X.end());
	sort(Y.begin(), Y.end());
	cost[X[0].second][X[1].second] = X[1].first - X[0].first;
	cost[Y[0].second][Y[1].second] = min(cost[Y[0].second][Y[1].second], Y[1].first - Y[0].first);
	for (int i = 1; i < N - 1; ++i) {
		cost[X[i].second][X[i - 1].second] = min(cost[X[i].second][X[i - 1].second], X[i].first - X[i - 1].first);
