		cost[Y[i].second][Y[i + 1].second] = min(cost[Y[i].second][Y[i + 1].second], Y[i + 1].first - Y[i].first);
	}
	cost[X[N - 1].second][X[N - 2].second] = min(cost[X[N - 1].second][X[N - 2].second], X[N - 1].first - X[N - 2].first);
	cost[Y[N - 1].second][Y[N - 2].second] = min(cost[Y[N - 1].second][Y[N - 2].second], Y[N - 1].first - Y[N - 2].first);

	mincost.resize(N, INF);
	used.resize(N, false);

	ll ans = prim();
	cout << ans << '\n';
	return 0;
}

