int main(){
    int n;
    cin>>n;
    //(x,y)
    vector< node > city(n);
    for(int i=0;i<n;i++){
        cin>>city[i].x>>city[i].y;
        city[i].name = i;
    }
    //各ノードから出る辺を考える
    vector< vector<edge> > G(n); 
    //xでそーと
    sort(city.begin(),city.end(),compx);
    for(int i=0;i<n-1;i++){
        int dis = city[i+1].x-city[i].x;
        edge edge1,edge2;
        edge1.to = city[i+1].name;
        edge1.cost = dis;
        G[city[i].name].push_back(edge1);
        edge2.to = city[i].name;
        edge2.cost = dis;
        G[city[i+1].name].push_back(edge2);
    }
    //yでソート
    sort(city.begin(),city.end(),compy);
    for(int i=0;i<n-1;i++){
        int dis = city[i+1].y-city[i].y;
        edge edge1,edge2;
        edge1.to = city[i+1].name;
        edge1.cost = dis;
        G[city[i].name].push_back(edge1);
        edge2.to = city[i].name;
        edge2.cost = dis;
        G[city[i+1].name].push_back(edge2);
    }

    priority_queue<edge, vector<edge>, greater<edge> > pq; 
    vector<bool> used(n,false);
    used[0]=true;
    for(int i=0;i<G[0].size();i++){
        pq.push(G[0][i]);
    }
    int ans = 0;
    while(!pq.empty()){
        //一番最小の辺
        edge tmp = pq.top();
        pq.pop();
        int to = tmp.to;
        int cost = tmp.cost;
        if(used[to]) continue;
        used[to] = true;
        ans += cost;
        for(int i=0;i<G[to].size();i++){
            pq.push(G[to][i]);
        }
    }
    cout<<ans<<endl;
    return 0;

}

