    int n, m;
    read(n, m);

    fact[0] = 1;
    fact[1] = 1;

    FOR(i, 2, max(n, m) + 1) {
        fact[i] = (fact[i - 1] * i) % M;
    }


    if (abs(n - m) > 1) {
        print(0);
    }
    else if (abs(n - m) == 1) {
        print((fact[m] * fact[n]) % M);
    }
    else{
        print((fact[m] * fact[n] * 2) % M);
    }
}

