#define MAX_N 100010
struct UnionFind {
    int par[MAX_N]; // 親
    int rank[MAX_N]; // 木の深さ

    UnionFind() {
    }

    // n要素で初期化
    void init(int n) {
        for (int i = 0; i < n; i++) {
            par[i] = i;
            rank[i] = 0;
        }
    }

    // 木の根を求める
    int find(int x) {
        if (par[x] == x) {
            return x;
        }
        else {
            return par[x] = find(par[x]);
        }
    }

    // xとyの属する集合を併合
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) {
            return;
        }

        if (rank[x] < rank[y]) {
            par[x] = y;
        }
        else {
            par[y] = x;
            if (rank[x] == rank[y]) {
                rank[x]++;
            }
        }
    }

    // xとyが同じ集合に属するか否か
    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

int cost(const edge& e1, const edge& e2) {
    return min(abs(e1.x - e2.x), abs(e1.y - e2.y));
}

bool compX(const edge& e1, const edge& e2) {
    return e1.x < e2.x;
}

bool compY(const edge& e1, const edge& e2) {
    return e1.y < e2.y;
}

bool compCost(const edge& e1, const edge& e2) {
    return e1.cost < e2.cost;
}

edge es[MAX_N];
UnionFind uf;

class Solution {
public:
    void solve(std::istream& in, std::ostream& out) {
        int n;
        in >> n;
        rep(i, n) {
            in >> es[i].x >> es[i].y;
            es[i].cost = INF;
            es[i].from = i;
        }

        uf.init(MAX_N);
        sort(es, es + n, compX);
        int c;
        rep(i, n) {
            if (i == n - 1) {
                c = cost(es[i], es[i - 1]);
                if (es[i].cost > c) {
                    es[i].cost = c;
                    es[i].to = es[i - 1].from;
                }
            }
            else {
                c = cost(es[i], es[i + 1]);
                if (es[i].cost > c) {
                    es[i].cost = c;
                    es[i].to = es[i + 1].from;
                }
            }
        }

        sort(es, es + n, compY);
        rep(i, n - 1) {
            if (i == n - 1) {
                c = cost(es[i], es[i - 1]);
                if (es[i].cost > c) {
                    es[i].cost = c;
                    es[i].to = es[i - 1].from;
                }
            }
            else {
                c = cost(es[i], es[i + 1]);
                if (es[i].cost > c) {
                    es[i].cost = c;
                    es[i].to = es[i + 1].from;
                }
            }
        }

        sort(es, es + n, compCost);

        int res = 0;
        rep(i, n) {;
            if (!uf.same(es[i].to, es[i].from))
            {
                uf.unite(es[i].to, es[i].from);
                res += es[i].cost;
            }
        }

        out << res << endl;
    }
};

void solve(std::istream& in, std::ostream& out)
{
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}

