struct UnionFind{
    vector<int> par;
    vector<int> rank;
    vector<ll> connection;

    UnionFind(int N):par(N),rank(N),connection(N){
        rep(i,N){
          par[i] = i;
          rank[i] = 0;
          connection[i] = 1;
        }
    }

    int root(int x){
       while(x != par[x]){
        x =  par[x] = par[par[x]];
       }
       return x;
    }

    bool same(int x,int y){
      return root(x) == root(y);
    }

    void unite(int x,int y){
        int rx = root(x);
        int ry = root(y);
        if(!same(x,y)){
            connection[root(x)] += connection[root(y)];
            connection[root(y)] = connection[root(x)];
        }
        if(rx == ry)return;
        if(rank[x] > rank[y]){
          par[y] = rx;
        }
        if(rank[x] < rank[y]){
          par[rx] = ry;
        }else{
          par[ry] = rx;
          if(rank[x] == rank[y]){
            rank[rx]++;
          }
        }
    }

    ll SIZE(int x){
        return connection[root(x)];
    }
};


