// UFDS for checking if two nodes are connected
int parent[1000], sz[1000];

void init(int n) {
	for (int i = 0; i <= n; i++) {
		parent[i] = i;
		sz[i] = 1;
	}
}

int find(int x) {
	if (parent[x] == x) {
		return x;
	}
	else {
		parent[x] = find(parent[x]);
		return parent[x];
	}
}

void merge(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y) {
		return;
	}
	parent[y] = x;
	sz[x] += sz[y];
}


// weight, endpoints of the edge
int N;

bool comp(vector<int> a, vector<int> b) {
	return a[1] < b[1];
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	// Read in graph
	cin >> N;
	vector<vector<int>> verts(N);
	for (int i = 0; i < N; i++) {
		int X, Y;
		cin >> X >> Y;
		verts[i] = { X, Y, i };
	}

	vector<vector<int>> G;
	// sort by x
	sort(verts.begin(), verts.end());

	// Add to edges
	for (int i = 0; i < N - 1; i++) {
		G.push_back({ verts[i + 1][0] - verts[i][0], verts[i][2], verts[i + 1][2] });
	}

	// sort by y
	sort(verts.begin(), verts.end(), comp);

	// Add to edges
	for (int i = 0; i < N - 1; i++) {
		G.push_back({ verts[i + 1][1] - verts[i][1], verts[i][2], verts[i + 1][2] });
	}

	// Kruskal's Algorithm
	// First sort the edges by weight in ascending order
	sort(G.begin(), G.end());

	// Initialize UFDS
	init(N);

	// To track the cost of the MST
	int cost = 0;
	// Go through edges one by one, add them into the MST as long as a cycle is not formed
	for (int i = 0; i < G.size(); i++) {
		int W = G[i][0], A = G[i][1], B = G[i][2];
		// Note: adding an edge A - B only forms a cycle if A and B are already connected via some other path
		// Two nodes are already connected, if they are in the same set
		if (find(A) != find(B)) {
			merge(A, B);
			cost += W;
		}
	}

	cout << cost << "\n";

}

