// Minimum Spanning Tree Kruskal O(E log V)
// 1. init E, V
// 2. kruskal() returns the sum of costs

const int MAX_E = 200000;
const int MAX_V = 100000;

struct edge { ll u, v, cost; };
bool comp(const edge& e1, const edge& e2) {
  return e1.cost < e2.cost; 
}

int par[MAX_V];
int rk[MAX_V];

void init(int n){
  REP(i,n){
    par[i] = i;
    rk[i] = 0;
  }
}

int find(int x){
  if(par[x] == x){
    return x;
  }else{
    return par[x] = find(par[x]);
  }
}

void unite(int x, int y){
  x = find(x);
  y = find(y);
  if(x==y) return;
  if(rk[x] < rk[y]){
    par[x] = y;
  }else{
    par[y] = x;
    if(rk[x] == rk[y]) rk[x]++;
  }
}

bool same(int x, int y){
  return find(x) == find(y);
}

edge es[MAX_E];
int V, E;

ll kruskal() {
  sort(es, es + E, comp);
  init(V);
  ll res = 0;
  for(int i = 0; i < E; i++) {
    edge e = es[i];
    if (!same(e.u, e.v)) {
      unite(e.u, e.v);
      res += e.cost;
    }
  }
  return res;
}


