struct UnionFind
{
    vector<int> rank, parents;
    UnionFind() {}
    UnionFind(int n)
    {
        rank.resize(n, 0);
        parents.resize(n, 0);
        for (int i = 0; i < n; i++)
        {
            makeTree(i);
        }
    }
    void makeTree(int x)
    {
        parents[x] = x;
        rank[x] = 0;
    }
    bool isSame(int x, int y) { return findRoot(x) == findRoot(y); }
    void unite(int x, int y)
    {
        x = findRoot(x);
        y = findRoot(y);
        if (rank[x] > rank[y])
        {
            parents[y] = x;
        }
        else
        {
            parents[x] = y;
            if (rank[x] == rank[y])
            {
                rank[y]++;
            }
        }
    }
    int findRoot(int x)
    {
        if (x != parents[x])
            parents[x] = findRoot(parents[x]);
        return parents[x];
    }
};

struct Edge
{
    long long u;
    long long v;
    long long cost;
};

bool comp_e(const Edge &e1, const Edge &e2)
{
    return e1.cost < e2.cost;
}

bool comp_e_greater(const Edge &e1, const Edge &e2)
{
    return e1.cost > e2.cost;
}

struct Kruskal
{
    UnionFind uft;
    long long sum;
    vector<Edge> edges;
    vector<Edge> resEdges;
    int V;
    Kruskal(const vector<Edge> &edges_, int V_) : edges(edges_), V(V_) { init(); }
    void init()
    {
        sort(edges.begin(), edges.end(), comp_e);
        uft = UnionFind(V);
        sum = 0;
        for (auto e : edges)
        {
            if (!uft.isSame(e.u, e.v))
            {
                uft.unite(e.u, e.v);
                sum += e.cost;
                resEdges.push_back(e);
            }
        }
    }
};

