        for(int i=0;i<n;i++){
            par.emplace_back(i);
            rankTree.emplace_back(i);
        }       
    }

    int find(int x){
        if(par[x] == x){
            return x;
        }
        return find(par[x]);
    }

    bool same(int x,int y){
        return find(x) == find(y);
    }

    void unite(int x, int y){
        if(same(x,y)){
            return;
        }

        int rootx = find(x);
        int rooty = find(y);

        if(rankTree[rootx] < rankTree[rooty]){
            par[rootx] = rooty;
            return;
        }
        par[rooty] = rootx;
        if(rankTree[rootx] == rankTree[rooty]){
            rankTree[rootx] ++;
        }
    }
};


