    Edge(int t, ll w) : to(t), weight(w) { }
};

int main()
{
    int N;
    cin >> N;

    vector<vector<Edge>> G(N);
    // 座標、街の番号の順でpairをつくる
    vector<pair<ll, int>> pairsX(N);
    vector<pair<ll, int>> pairsY(N);

    REP(i, N)
    {
        ll x, y;
        cin >> x >> y;
        pairsX[i] = make_pair(x, i);
        pairsY[i] = make_pair(y, i);
    }

    // 街のX, Y座標をそれぞれ昇順にソート
    sort(pairsX.begin(), pairsX.end());
    sort(pairsY.begin(), pairsY.end());

    // グラフに辺を貼る
    // 考える辺はソートしたX, Y 座標のなかで隣り合うものだけでよい
    // 二重辺になったとしても、あとのアルゴリズムで問題ない

    // X座標について
    REP(i, N - 1)
    {
        int from, to;
        ll weight;
        from = pairsX[i].second;
        to = pairsX[i + 1].second;
        weight = pairsX[i + 1].first - pairsX[i].first;
        // 無向グラフを考える
        G[from].push_back(Edge(to, weight));
        G[to].push_back(Edge(from, weight));
    }
    // Y座標について
    REP(i, N - 1)
    {
        int from, to;
        ll weight;
        from = pairsY[i].second;;
        to = pairsY[i + 1].second;
        weight = pairsY[i + 1].first - pairsY[i].first;
        // 無向グラフを考える
        G[from].push_back(Edge(to, weight));
        G[to].push_back(Edge(from, weight));
    }

    // 最小全域木をつくる
    bool visited[N] = {false};
    vector<int> visitedV;
    priority_queue<P, vector<P>, greater<P> > edgeQ;
    ll ans = 0;

    int v = 0;
    visitedV.push_back(v);
    visited[v] = true;
    while(visitedV.size() != N)
    {
        for(int i = 0; i != G[v].size(); ++i)
        {
            edgeQ.push(P(G[v][i].weight, G[v][i].to));
        }
        while(true)
        {
            P p = edgeQ.top();
            int vTo = p.second;
            ll weight = p.first;
            if (!visited[vTo])
            {
                visitedV.push_back(vTo);
                visited[vTo] = true;
                v = vTo;
                ans += weight;
                break;
            }
            edgeQ.pop();
        }
    }

    cout << ans << endl;
}

