struct MinimumSpanningTree {
    vector<vector<int>> cost;
    vector<int> min_cost;
    vector<bool> used;
    int inf;

    MinimumSpanningTree() {}
    MinimumSpanningTree(int n) {
        resize(n);
    }

    void resize(int n) {
        inf = numeric_limits<int>::max();
        cost.resize(n, vector<int>(n, inf));
        min_cost.resize(n);
        used.resize(n);
    }

    void add_edge(int a, int b, int c) {
        cost[a][b] = c;
        cost[b][a] = c;
    }

    int get_total_cost() {
        int n = (int)used.size();
        for (int i = 0; i < n; i++) {
            min_cost[i] = inf;
            used[i] = false;
        }
        min_cost[0] = 0;
        int res = 0;
        while(true) {
            int v = -1;
            for (int i = 0; i < n; i++) {
                if ((!used[i]) && ((v == -1) || (min_cost[i] < min_cost[v]))) v = i;
            }
            if (v == -1) break;
            used[v] = true;
            res += min_cost[v];
            for (int i = 0; i < n; i++) {
                min_cost[i] = min(min_cost[i], cost[v][i]);
            }
        }
        return res;
    }
};

