template<typename T>
class UnionFindTree{
	private:
		int N;
		vector<int> parent, rank, size;
		vector<T> diff_weight;

		int find(int x){
			if(parent[x] == x){
				return x;
			}else{
				int r = find(parent[x]);
				diff_weight[x] += diff_weight[parent[x]];
				return parent[x] = r;
			}
		}

		T weight(int x){
			find(x);
			return diff_weight[x];
		}

	public:
		void init(int N = -1){
			if(N > this -> N){
				this -> N = N;
				parent.resize(N); rank.resize(N); size.resize(N); diff_weight.resize(N);
			}

			for(int i = 0; i < this -> N; i++){
				parent[i] = i; rank[i] = 0; size[i] = 1; diff_weight[i] = 0;
			}
		}

		UnionFindTree(int N = 0): N(N), parent(N), rank(N), size(N), diff_weight(N){
			init();
		}

		T diff(int x, int y){
			return weight(y) - weight(x);
		}

		// weight(y) = weight(x) + w となるようにmergeする
		bool unite(int x, int y, T w = 0){
			w += weight(x); w -= weight(y);
			x = find(x); y = find(y);
			if(x == y) return weight(y) - weight(x) == w;

			if(rank[x] < rank[y]){
				swap(x, y);
				w = -w;
			}

			parent[y] = x;
			size[x] += size[y];
			if(rank[x] == rank[y]) rank[x]++;
			diff_weight[y] = w;
			return true;
		}

		bool isSame(int x, int y){
			return find(x) == find(y);
		}

		int count(int x){
			return size[find(x)];
		}
};
