}a[nmax];
struct ha
{
    int u,v,w;
}d[nmax];
bool cmp1(hd a, hd b)
{
    if(a.x == b.x)
        return a.y < b.y;
    return a.x < b.x;
}
bool cmp2(hd a, hd b)
{
    if(a.y==b.y)
        return a.x < b.x;
    return a.y < b.y;
}
int get_root(int u){
    return root[u] ? (root[u] = get_root(root[u])) : u ;
}
void READ()
{
    ios_base::sync_with_stdio(0);
