    cin >> n;
    forinc(i,1,n)
    {
        a[i].id = i;
        cin >> a[i].x >> a[i].y;
    }
    sort(a + 1, a + 1 + n, cmp1);
    forinc(i,1,n - 1)
    {
        d[i].u = a[i].id;
        d[i].v = a[i + 1].id;
        int t =min(abs(a[i + 1].x - a[i].x),abs(a[i + 1].y - a[i].y));
        d[i].w = t;
    }
    sort(a + 1, a + 1 + n, cmp2);
    forinc(i,1,n - 1)
    {
        d[i + n - 1].u = a[i].id;
        d[i + n - 1].v = a[i + 1].id;
        d[i + n - 1].w = min(abs(a[i + 1].x - a[i].x),abs(a[i + 1].y - a[i].y));
    }
}
bool cmp3(ha a,ha b)
{
    return a.w < b.w;
}
void SOLVE()
{
