		x[i] = p[i].fi.fi;
		y[i] = p[i].fi.se;
	}
	sort(all(p), cmp);
	vector<pi> edges;
	repn(i, 1, n) edges.pb(mp(p[i].se, p[i - 1].se));
	sort(all(p), cmp1);
	repn(i, 1, n) edges.pb(mp(p[i].se, p[i - 1].se));
	sort(all(edges), cmp2);
	DSU dsu(n);
