class UnionFindTree {
public:
  int n;
  vector<int> par;
  vector<int> rnk;

  void init(int _n) {
    n = _n;
    par.resize(n);
    rnk.resize(n, 0);
    REP(i, n) par[i] = i;
  }

  int find(int x) {
    if (par[x] == x) {
      return x;
    } else {
      return par[x] = find(par[x]);
    }
  }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;

    if (rnk[x] < rnk[y]) {
      par[x] = y;
    } else {
      par[y] = x;
      if (rnk[x] == rnk[y]) rnk[x]++;
    }
  }

  bool same(int x, int y) {
    return find(x) == find(y);
  }
};

