const int N_MAX = 1e5;
const int X_I_MAX = 1e9;
const int Y_I_MAX = 1e9;

struct city { int id, x, y; };
struct dist { int i, j, d; };

int N;
// int x[N_MAX];
// int y[N_MAX];

city cs[N_MAX];
dist ds[N_MAX * 2];

UnionFindTree uf;

bool compare_x_asc(const city& c1, const city& c2) {
  return c1.x < c2.x;
}

bool compare_y_asc(const city& c1, const city& c2) {
  return c1.y < c2.y;
}

bool compare_d_asc(const dist& d1, const dist& d2) {
  return d1.d < d2.d;
}

void solve() {
  uf.init(N);
  sort(cs, cs + N, compare_x_asc);
  REP(i, N - 1) ds[i] = { cs[i].id, cs[i + 1].id, cs[i + 1].x - cs[i].x };
  sort(cs, cs + N, compare_y_asc);
  REP(i, N - 1) ds[N - 1 + i] = { cs[i].id, cs[i + 1].id, cs[i + 1].y - cs[i].y };
  int M = (N - 1) * 2;
  sort(ds, ds + M, compare_d_asc);

  int ans = 0;
  REP(k, M) {
    dist d = ds[k];
    if (uf.same(d.i, d.j)) continue;
    uf.unite(d.i, d.j);
    ans += d.d;
  }
  printf("%d\n", ans);
}

void input() {
  scanf("%d", &N);
  REP(i, N) {
    int x, y;
    scanf("%d%d", &x, &y);
    cs[i] = {i, x, y};
  }
}

int main() {
  input();
  solve();
  return 0;
}

