struct Edge {
    int src, dst, cost;
    Edge(int s, int d, int c = 1) : src(s), dst(d), cost(c) {}
    bool operator<(const Edge &e) const { return cost < e.cost;}
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;

struct UnionFind {
    vector<int> par, rnk, weight;
    UnionFind(int n) :par(n), rnk(n), weight(n) { for(int i=0; i < n; ++i) par[i] = i; }
    void unite(int x, int y, int w = 0) {
        x = root(x); y = root(y);
        if (x == y) return;
        if (rnk[x] < rnk[y]) swap(x, y), w = -w;
        par[y] = x;
        if(rnk[x] == rnk[y]) ++rnk[x];
        return;
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int root(int x) {
        if(par[x]==x) return x;
        return root(par[x]);
    }
    int sizeOf(int x) { return rnk[root(x)]; }
};

// O(|E|log|E|)
int kruskal(Edges &es, int n) {
    UnionFind uf(n);
    sort(es.begin(), es.end());
    int min_cost = 0;

    for (Edge e : es){
        if (!uf.same(e.src, e.dst)) {
            uf.unite(e.src, e.dst);
            min_cost += e.cost;
        }
    }
    return min_cost;
}

