typedef pair<long long, long long> P;

int main(){
    int n;
    cin >> n;

    //xとyそれぞれについてsort
    vector<P> x_node(n);
    vector<P> y_node(n);
    long long x, y;
    for (int i = 0; i < n; i++){
        cin >> x >> y;
        x_node[i] = {x, i};
        y_node[i] = {y, i};
    }
    sort(x_node.begin(), x_node.end());
    sort(y_node.begin(), y_node.end());

    //辺を貼る
    vector<vector<P>> node(n);
    for (int i = 1; i < n; i++){
        node[x_node[i - 1].second].push_back({abs(x_node[i - 1].first - x_node[i].first), x_node[i].second});
        node[x_node[i].second].push_back({abs(x_node[i - 1].first - x_node[i].first), x_node[i - 1].second});
        node[y_node[i - 1].second].push_back({abs(y_node[i - 1].first - y_node[i].first), y_node[i].second});
        node[y_node[i].second].push_back({abs(y_node[i - 1].first - y_node[i].first), y_node[i - 1].second});
    }

    //プリム法
    vector<bool> used(n, false);
    long long res = 0;

    priority_queue<P, vector<P>, greater<P>> pq;
    pq.push({0, 0});

    while(pq.size() > 0){
        x = pq.top().first; y = pq.top().second; pq.pop();
        if (used[y]) continue;

        used[y] = true;
        res += x;

        int k = (int)node[y].size();
        for (int i = 0; i < k; i++){
            if (used[node[y][i].second] == false){
                pq.push({node[y][i].first, node[y][i].second});
            }
        }
    }
    cout << res << endl;
}

