//Union-Find Tree
class UnionFind{
public:
    int N;              //頂点数
    vector<int> par;    //par[i]:iの親の番号
    vector<int> size;   //size[i]:iが属するグループと同じグループに属する頂点数

    UnionFind(int n) : N(n), par(n), size(n, 1){  //初期化時はすべて根とする
        for(int i=0; i<n; i++){
            par.at(i) = i;
        }
    }

    int root(int x){    //データxが属する木の根を再帰で得る
        if(par.at(x) == x){
            return x;
        }else{
            return par.at(x) = root(par.at(x)); //経路圧縮を同時に実行
        }
    }

    void unite(int x, int y){   //xの属する木とyの属する木を併合
        int rx = root(x), ry = root(y);
        if(rx != ry){   //xとyの属する木が異なるとき
            par.at(rx) = ry;    //xの木の根をyの根につける
            size.at(ry) += size.at(rx);   //sizeを更新
        }
    }

    int getSize(int x){         //xの属する木のサイズを返す
        return size.at(x) = size.at(root(x));
    }

    bool same(int x, int y){    //x,yが同じ木に属するときtrue, そうでなければfalse
        return root(x) == root(y);
    }
};

signed main(){
    int n;
    cin >> n;
    vector<vector<int>> v(n, vector<int>(3));
    REP(i, n){
        v[i][0] = i;
        cin >> v[i][1] >> v[i][2];
    }

    typedef tuple<int,int,int> TP;
    auto c = [](TP a, TP b){return get<2>(a) > get<2>(b);};
    priority_queue<TP, vector<TP>, decltype(c)> p(c), q(c);
    sort(all(v), [](auto a, auto b){return a[1] < b[1];});
    REP(i, n-1){
        p.push(make_tuple(v[i][0], v[i+1][0], v[i+1][1] - v[i][1]));
    }
    sort(all(v), [](auto a, auto b){return a[2] < b[2];});
    REP(i, n-1){
        q.push(make_tuple(v[i][0], v[i+1][0], v[i+1][2] - v[i][2]));
    }

    ll ans = 0;
    UnionFind UF(n);
    while(UF.getSize(0) < n){
        TP t1 = p.top(), t2 = q.top();
        if(get<2>(t1) < get<2>(t2)){
            p.pop();
            if(!UF.same(get<0>(t1), get<1>(t1))){
                UF.unite(get<0>(t1), get<1>(t1));
                ans += get<2>(t1);
            }
        }else{
            q.pop();
            if(!UF.same(get<0>(t2), get<1>(t2))){
                UF.unite(get<0>(t2), get<1>(t2));
                ans += get<2>(t2);
            }
        }
    }

    cout << ans << endl;

    return 0;
}

