class UnionFind
{
    struct UFNode
    {
        int par;
        int rank;
    };
    vector<UFNode> nodes;

public:
    UnionFind(int n) : nodes(n)
    {
        for (int i = 0; i < n; i++)
        {
            nodes[i].par = i;
            nodes[i].rank = 0;
        }
    };
    int root(int x)
    {
        return nodes[x].par == x ? x : root(nodes[x].par);
    }
    bool same(int x, int y)
    {
        return root(x) == root(y);
    }
    void unite(int x, int y)
    {
        x = root(x);
        y = root(y);
        if (x == y)
            return;
        if (nodes[x].rank < nodes[y].rank)
        {
            nodes[x].par = y;
        }
        else
        {
            nodes[y].par = x;
            if (nodes[x].rank == nodes[y].rank)
                nodes[x].rank++;
        }
    }
    //~UnionFind() {cout << nodes.size() << endl;}
};

struct S
{
    int x, y, i;
};

void solve()
{
    int n;
    cin >> n;
    vector<S> p(n);
    REP(i, 0, n)
    {
        cin >> p[i].x >> p[i].y;
        p[i].i = i;
    }

    UnionFind uf(n);
    vector<edge> es;

    sort(all(p), [](auto &l, auto &r) { return l.x < r.x; });
    REP(i, 0, n - 1)
    {
        int d = min(abs(p[i].x - p[i + 1].x), abs(p[i].y - p[i + 1].y));
        es.pb(p[i].i, p[i + 1].i, d);
    }
    sort(all(p), [](auto &l, auto &r) { return l.y < r.y; });
    REP(i, 0, n - 1)
    {
        int d = min(abs(p[i].x - p[i + 1].x), abs(p[i].y - p[i + 1].y));
        es.pb(p[i].i, p[i + 1].i, d);
    }

    sort(all(es), [](auto &l, auto &r) { return l.cost < r.cost; });

    LL ans = 0;
    for (auto &e : es)
    {
        int l = e.from, r = e.to, d = e.cost;
        if (uf.same(l, r))
            continue;
        uf.unite(l, r);
        ans += d;
    }
    cout << ans << endl;
}

