	vector<ll> x(n), y(n);
	vector<P> px(n), py(n);
	REP(i, n) {
		cin >> x[i] >> y[i];
		px[i].first = x[i];
		px[i].second = i;
		py[i].first = y[i];
		py[i].second = i;
	}
	sort(all(px));
	sort(all(py));
	using el = edge<ll>;
	vector<vector<el>> path(n);
	REP(i, n - 1) {
		int from1 = px[i].second;
		int to1 = px[i + 1].second;
		ll cost1 = min<ll>(abs(x[from1] - x[to1]), abs(y[from1] - y[to1]));
		el e1(from1, to1, cost1);
		int from2 = px[i + 1].second;
		int to2 = px[i].second;
		ll cost2 = min<ll>(abs(x[from2] - x[to2]), abs(y[from2] - y[to2]));
		el e2(from2, to2, cost2);
		path[from1].push_back(e1);
		path[from2].push_back(e2);
	}
	REP(i, n - 1) {
		int from1 = py[i].second;
		int to1 = py[i + 1].second;
		ll cost1 = min<ll>(abs(x[from1] - x[to1]), abs(y[from1] - y[to1]));
		el e1(from1, to1, cost1);
		int from2 = py[i + 1].second;
		int to2 = py[i].second;
		ll cost2 = min<ll>(abs(x[from2] - x[to2]), abs(y[from2] - y[to2]));
		el e2(from2, to2, cost2);
		path[from1].push_back(e1);
		path[from2].push_back(e2);
	}
	auto comp = [](el r, el l) {
		return r.cost > l.cost;
	};
	priority_queue<edge<ll>, vector<el>, decltype(comp)> pq{ comp };
	int source = 0;
	REP(i, path[source].size()) {
		pq.push(path[source][i]);
	}
	vector<el> mst;
	vector<bool> visited(n, false);
	visited[0] = true;

	ll res = 0;
	REP(i, n - 1) {
		bool flag = true;
		while (flag) {
			auto p = pq.top();
			pq.pop();
			if (!visited[p.to]) {
				REP(j, path[p.to].size()) {
					pq.push(path[p.to][j]);
				}
				visited[p.to] = true;
				flag = false;
				res += p.cost;
			}
		}
	}
	put(res);
	return 0;
}

