struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main() {
  cin >> N;
  rep(i, N) {
    long long a, b;
    cin >> a >> b;
    x[i] = make_pair(a, i);
    y[i] = make_pair(b, i);
  }
  sort(x, x+N);
  sort(y, y+N);

  priority_queue<P, vector<P>, greater<P>> quex;
  for(long long i = 0; i < N - 1; i++) {
    long long dist = x[i+1].first - x[i].first;
    quex.push(make_pair(dist, make_pair(x[i].second, x[i+1].second)));
  }
  priority_queue<P, vector<P>, greater<P>> quey;
  for(long long i = 0; i < N - 1; i++) {
    long long dist = y[i+1].first - y[i].first;
    quey.push(make_pair(dist, make_pair(y[i].second, y[i+1].second)));
  }

  priority_queue<P, vector<P>, greater<P>> que;
  for(long long i = 0; i < N - 1; i++) {
    P nx = quex.top();
    quex.pop();
    que.push(nx);
    P ny = quey.top();
    quey.pop();
    que.push(ny);
  }

  UnionFind tree(N);
  long long ans = 0;

  while(que.size()) {
    P p = que.top();
    que.pop();
    long long cost = p.first;
    long long s = p.second.first;
    long long t = p.second.second;
    if(tree.same(s, t)) {
      continue;
    } else {
      tree.unite(s, t);
      ans += cost;
      // cout << cost << " " << s << " " << t << endl;
    }
  }

  cout << ans << endl;

  return 0;
}

