struct UnionFind {
    vector<int> par;
    UnionFind(int n) : par(n, -1) { }
    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }
    bool issame(int x, int y) {
        return root(x) == root(y);
    }
    void merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return;
        if (-par[x] < -par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
    }
};

int main(){
    int n;
    cin >> n;
    vec<P<int, int>> xy;
    rep(i, n) {
        int x, y; cin >> x >> y;
        xy.emplace_back(x, y);
    }
    vec<P<int, int>> px(n), py(n);
    rep(i, n) {
        px[i] = P<int, int>(xy[i].first, i);
        py[i] = P<int, int>(xy[i].second, i);
    }
    sort(px.begin(), px.end());
    sort(py.begin(), py.end());
    vec<P<ll, P<int, int>>> edges;
    int idx_prev = px[0].second;
    int idy_prev = py[0].second;
    rep(i, n-1) {
        int idx = px[i+1].second;
        int idy = py[i+1].second;
        ll costx = abs(xy[idx].first - xy[idx_prev].first);
        ll costy = abs(xy[idy].second - xy[idy_prev].second);
        edges.emplace_back(costx, P<int, int>(idx_prev, idx));
        edges.emplace_back(costy, P<int, int>(idy_prev, idy));
        idx_prev = idx, idy_prev = idy;
    }

    sort(edges.begin(), edges.end());
    UnionFind uf(n);
    long long res = 0;
    for (auto e : edges) {
        int u = e.second.first, v = e.second.second;
        long long cost = e.first;
        if (uf.issame(u, v)) continue;
        uf.merge(u, v);
        res += cost;
    }
    cout << res << endl;
}

