const ll MAX = 100010;

class UnionFind
{
private:
    int par[MAX];
    int rank[MAX];
public:
    UnionFind(int N);
    int find(int x);
    void unite(int x, int y);
    bool same(int x, int y);
};

//コンストラクタ
UnionFind::UnionFind(int N)
{
    for(int i=0; i<N; i++)
    {
        par[i]=i;
        rank[i]=0;
    }
 }

//木の根を求める
int UnionFind::find(int x)
{
    if(par[x]==x)
    {
        return x;
    }
    else
    {
        return par[x]=find(par[x]);
    }
}
//位数の大きい木に統合する
void UnionFind::unite(int x, int y)
{
    x=find(x);
    y=find(y);

    if(x==y)
        return;

    if(rank[x] < rank[y])
    {
        par[x]=y;
    }
else
    {
        par[y]=x;

        if(rank[x]==rank[y])
        {
            rank[x]++;
        }
    }
}

//同じ根を持つならtrueを返す
bool UnionFind::same(int x, int y)
{
    return find(x)==find(y);
}

struct edge { int from, to, cost; };

struct point { int x, y, no; };


bool comp(const edge& e1, const edge& e2)
{
    return e1.cost < e2.cost;
}


bool pcomp1(const point& p1, const point& p2)
{
    return p1.x < p2.x;
}

bool pcomp2(const point& p1, const point& p2)
{
    return p1.y < p2.y;
}

edge es[MAX];
point p[MAX];

int V, E;

int kruskal()
{
    sort(es, es+E, comp);
    UnionFind *tree = new UnionFind(V);
    int res = 0;
    for(int i=0; i<E; i++)
    {
        edge e = es[i];
        if(!tree->same(e.from, e.to))
        {
            tree->unite(e.from, e.to);
            res+=e.cost;
        }
    }
    return res;
}


