struct SUS {
	vector<int> up;

	SUS(int n) {
		up.resize(n);
		for (int i = 0; i < n; i++) {
			up[i] = i;
		}
	}

	int get_root(int v) {
		if (up[v] == v) return v;
		return up[v] = get_root(up[v]);
	}

	void merge(int a, int b) {
		a = get_root(a);
		b = get_root(b);
		up[a] = b;
	}

	bool one_comp(int a, int b) {
		return get_root(a) == get_root(b);
	}
};

