using namespace std;
#define MAX_N (int)1e6

typedef long long ll;
const ll INF = 1LL << 60;
typedef pair<ll, ll> P;

int N, E;
vector<ll> x, y;

struct edge { ll u, v, cost; };
bool comp(const edge& e1, const edge& e2) {
    return e1.cost < e2.cost;
}
// edge es[(int)1e6];
vector<edge> es;

class UnionFind {
    int par[MAX_N];  // 親
    int my_rank[MAX_N]; // 木の深さ

public:
    void init(int n) {
        for (int i = 0; i < n; i++) {
            par[i] = i;
            my_rank[i] = 0;
        }
    }

    int find(int x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        } } 
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) {
            return;
        }
        if (my_rank[x] < my_rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (my_rank[x] == my_rank[y]) my_rank[x]++;
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

ll kruskal() {
    // N 個
    UnionFind uf;
    uf.init(N);
    // sort(es, es + E, comp);
    sort(es.begin(), es.end(), comp);
    ll res = 0;
    for (ll i = 0; i < E; i++) {
        edge e = es[i];
        if (!uf.same(e.u, e.v)) {
            uf.unite(e.u, e.v);
            res += e.cost;
        }
    }

    return res;
}

