        P py(y[i], i);
        y2.push_back(py);
    }
    sort(x2.begin(), x2.end());
    sort(y2.begin(), y2.end());

    // x の辺
    rep(i, N) {
        if (i - 1 >= 0) {
            edge ex = {x2[i].second, x2[i - 1].second, abs(x2[i].first - x2[i - 1].first)};
