ll kruskal() {
	sort(es, es + E, comp);//costでソート
	init(N);
	ll res = 0;
	//コストが小さい辺から順に追加する
	REP(i, E) {
		edge e = es[i];
		//もし閉路ができなければその辺を追加する
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}

