    sort(p.begin(),p.end(),[&xy](int a,int b){return xy[a].first < xy[b].first;});
    for(int i=0;i<N-1;i++){
        edge e={p[i],p[i+1],std::abs(xy[p[i]].first - xy[p[i+1]].first)};
        E.push_back(e);
    }

    sort(p.begin(),p.end(),[&xy](int a,int b){return xy[a].second < xy[b].second;});
    for(int i=0;i<N-1;i++){
        edge e={p[i],p[i+1],std::abs(xy[p[i]].second - xy[p[i+1]].second)};
        E.push_back(e);
    }

    sort(E.begin(),E.end(),[](edge e1,edge e2){return e1.dist > e2.dist;});

    for(int i=0;i<N;i++){
        p[i]=i;
    }

    long ans=0;

    while(!E.empty()){
        edge e=E.back();
        E.pop_back();
        if(p[e.p1] != p[e.p2]){
            int _p=p[e.p1];
            for(int i=0;i<N;i++){
                if(p[i]==_p){
                    p[i]=p[e.p2];
                }
            }
            ans+=e.dist;
        }
    }

    cout << ans << endl;

    return 0;
}

