#include <bits/stdc++.h>
using namespace std;

class UnionFind
{
private:
    vector<int> parents;

public:
    UnionFind(int n) : parents(n)
    {
        for (int i = 0; i < n; i++)
        {
            parents.at(i) = -1;
        }
    }

    bool is_root(int x)
    {
        return parents.at(x) < 0;
    }

    int size(int x)
    {
        return -parents.at(find(x));
    }

    int find(int x)
    {
        if (is_root(x))
            return x;
        parents.at(x) = find(parents.at(x));
        return parents.at(x);
    }

    void unite(int x, int y)
    {
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (size(x) < size(y))
            swap(x, y);
        parents.at(x) -= size(y);
        parents.at(y) = x;
    }

    bool same(int x, int y)
    {
        return find(x) == find(y);
    }
};

class Edge
{
public:
    int u, v, cost;
    Edge(int u, int v, int cost) : u(u), v(v), cost(cost) {}
    bool operator<(const Edge &other) const
    {
        return cost > other.cost;
    }
};

int main()
{
    int N;
    cin >> N;
    vector<int> x(N), y(N);
    for (int i = 0; i < N; i++)
    {
        cin >> x.at(i) >> y.at(i);
    }

    vector<pair<int, int>> points(N);
    vector<pair<int, int>> points_by_x(N);
    vector<pair<int, int>> points_by_y(N);
    for (int i = 0; i < N; i++)
    {
        points.at(i) = make_pair(x.at(i), y.at(i));
        points_by_x.at(i) = make_pair(x.at(i), i);
        points_by_y.at(i) = make_pair(y.at(i), i);
    }
    sort(points_by_x.begin(), points_by_x.end());
    sort(points_by_y.begin(), points_by_y.end());

    priority_queue<Edge> q;
    int id_prev = points_by_x.at(0).second;
    pair<int, int> p_prev = points.at(id_prev);
    for (int i = 1; i < N; i++)
    {
        int id = points_by_x.at(i).second;
        pair<int, int> p = points.at(id);
        Edge e = Edge(id_prev, id, min(abs(p.first - p_prev.first), abs(p.second - p_prev.second)));
        q.push(e);
        id_prev = id;
        p_prev = p;
    }
    id_prev = points_by_y.at(0).second;
    p_prev = points.at(id_prev);
    for (int i = 1; i < N; i++)
    {
        int id = points_by_y.at(i).second;
        pair<int, int> p = points.at(id);
        Edge e = Edge(id_prev, id, min(abs(p.first - p_prev.first), abs(p.second - p_prev.second)));
        q.push(e);
        id_prev = id;
        p_prev = p;
    }

    int res = 0;
    UnionFind tree = UnionFind(N);
    while (!q.empty())
    {
        Edge e = q.top();
        q.pop();
        if (!tree.same(e.u, e.v))
        {
            res += e.cost;
            tree.unite(e.u, e.v);
        }
    }
    cout << res << endl;
    return 0;
}

