// db

// [D] Union-Find木（素集合データ構造）
vi par; // par[i]: 要素iの親
vi dep; // dep[i]: 要素iが根であるときは，iを含む木の最も深い要素の(根を0とした)深さ(rank)。iが根であるといえなければ dep[root(i)] とする。
vi siz; // siz[i]: 要素iが根であるときは，iを含む木の大きさ(要素数，size)。iが根であるといえなければ siz[root(i)] とする。

int root(int x) {
	if (par[x] == x) return x;
	else return par[x] = root(par[x]); // 縮約
}

void unite(int x, int y) {
	x = root(x); y = root(y);
	if (x == y) return;
	if (dep[x] > dep[y]) { // xを根とする木の方が深い場合
		par[y] = x; // xが根となる
		siz[x] += siz[y];
	} else if (dep[x] < dep[y]) {
		par[x] = y;
		siz[y] += siz[x];
	} else { // 深さが等しい場合，xを根とすることとする
		par[y] = x;
		dep[x] ++;
		siz[x] += siz[y];
	}
}

bool same(int x, int y) {
	return root(x) == root(y);
}

void UF(int N) { // 0-ind，要素数Nでの初期化に使用する
	par.assign(N, -1); dep.assign(N, 0); siz.assign(N, 1);
	rep(i, N) par[i] = i; // 全ての要素につき自身が根であるとして初期化
}


// [E] クラスカル(Kruskal)法　※最小全域木。Union-Find木と合わせて用いる
int main() {
	int N; cin >> N;
	vector<ti3> V(N);
	rep(i, N) {
		int x, y; cin >> x >> y;
		V[i] = ti3(i, x, y);
	}
	priority_queue<ti3, vector<ti3>, greater<ti3>> q; // ti3の第1要素の降順
	sort(ALL(V), [](ti3 t1, ti3 t2) { return get<1>(t1) < get<1>(t2); }); // Vをx座標でソート
	rep(i, N - 1) {
		int u, ux, v, vx;	tie(u, ux, ignore) = V[i]; tie(v, vx, ignore) = V[i + 1];
		q.push(ti3(vx - ux, u, v));
	}	
	sort(ALL(V), [](ti3 t1, ti3 t2) { return get<2>(t1) < get<2>(t2); }); // Vをy座標でソート
	rep(i, N - 1) {
		int u, uy, v, vy;	tie(u, ignore, uy) = V[i]; tie(v, ignore, vy) = V[i + 1];
		q.push(ti3(vy - uy, u, v));
	}
	UF(N);
	int cnt = 0; // cnt: uniteの回数。V-1回行うと森が木になる
	int ans = 0;
	while (cnt < N - 1) {
		int d, i, j; tie(d, i, j) = q.top(); q.pop();
		if (!same(i, j)) {
			// 併合時の処理
			ans += d;
			unite(i, j);			
			cnt++;
		}
	}
	output(ans);
}

