const int mn = 100010;
vector<P> x, y;

#define N 100010

bool comp(const edge& e1, const edge& e2) {
	return e1.cost < e2.cost;
}

int par[N];
int urank[N];

void init(int n) {
	REP(i, n) {
		par[i] = i;
		urank[i] = 0;
	}
}

int find(int x) {
	if (par[x] == x) {
		return x;
	}
	else {
		return par[x] = find(par[x]);
	}
}

void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y) return;

	if (urank[x] < urank[y]) {
		par[x] = y;
	}
	else {
		par[y] = x;
		if (urank[x] == urank[y]) urank[x]++;
	}
}

bool same(int x, int y) {
	return find(x) == find(y);
}

edge es[N * 2];

ll kruskal(int E) {
	sort(es, es + E, comp);
	ll res = 0;
	REP(i, E) {
		edge e = es[i];
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}


int main() {
	int n;
	cin >> n;
	int E = 0;
	REP(i, n) {
      	P a, b;
		cin >> a.first >> b.first;
		a.second = b.second = i;
      	x.pb(a); y.pb(b);
	}

	init(n);
	sort(x.begin(), x.end());
	sort(y.begin(), y.end());
	REP(i, n - 1) {
		edge e;
		e.u = x[i].second; e.v = x[i + 1].second; e.cost = x[i + 1].first - x[i].first; es[i] = e; E++;
		e.u = y[i].second; e.v = y[i + 1].second; e.cost = y[i + 1].first - y[i].first; es[i + n - 1] = e; E++;
	}
	cout << kruskal(E) << endl;
}

