long long naive()
{
    long long cost_total = 0;
    unordered_set<int> mst;

    mst.insert(0);
    while(mst.size() < N) {
        long long cost_min = numeric_limits<long long>::max();
        pair<int, int> argmin;

        for(int src : mst) {
            for(int dst = 0; dst < N; ++dst) {
                if(mst.find(dst) != mst.end()) continue;
                int c = cost(points[src], points[dst]);
                if(c < cost_min) {
                    cost_min = c;
                    argmin = make_pair(src, dst);
                }
            }
        }

        cost_total += cost_min;
        mst.insert(argmin.second); }
    return cost_total;
}

