int root(int i){
  if(i == tree[i]){
    for(int j = 0; j < child.size(); j++)
      tree[child[j]] = i;
    child.clear(); 
    return i;                   
  }
  else{
    child.push_back(i);
    return i = root(tree[i]);
  }
}

int unit(int x,int y){
  x = root(x);
  y = root(y);
  tree[max(x,y)] = min(x,y);     
}

