void makemkj(rs g[],mkj x[],long long n){
    long long i,ms=0,nst=g[0].st;
    for(i=1;i<n;i++){
        if(g[i].st!=g[i-1].st){
            x[nst].kz=i-ms;
            x[nst].st=ms;
            nst=g[i].st;ms=i;
        }
    }
    x[nst].kz=n-ms;
    x[nst].st=ms;
}

//Heap and Priority_queue

typedef struct{
long long node;
long long cost;
}data;

data heap[1048576];
long long hsize=0;

void resheap(){
    long long i;
    heap[0].node=-1;
    heap[0].cost=-llinf;
    for(i=1;i<1048576;i++){
        heap[i].node=-1;
        heap[i].cost=llinf;
    }
}

int swjud(data high,data low){
    if(high.cost > low.cost){return 1;}
    return -1;
}

void pqpush(data x){
    long long a,b;
    data m;
    hsize++;
    heap[hsize]=x;
    a=hsize;
    while(1){
        b=a/2;
        if(swjud(heap[b],heap[a]) == 1){
            m=heap[a];heap[a]=heap[b];heap[b]=m;
        }
        else{break;}
        a=b;
    }
}

data pqpop(){
    long long a,b,c;
    data m,sw;
    m=heap[1];
    heap[1]=heap[hsize];
    heap[hsize].node=-1;
    heap[hsize].cost=llinf;
    hsize--;
    a=1;
    while(1){
        b=a*2;c=a*2+1;
        if(swjud(heap[a],heap[b])==-1 && swjud(heap[a],heap[c])==-1){break;}
        if(swjud(heap[b],heap[c])==-1){
            sw=heap[a];heap[a]=heap[b];heap[b]=sw;
            a=b;
        }
        else{
            sw=heap[a];heap[a]=heap[c];heap[c]=sw;
            a=c;
        }
    }
    return m;
}

long long prim(long long vc,long long ec,rs g[],mkj x[]){
  resheap();
  data pd,od;
  long long cnt=0,i,r=0,nv;
  bool fl[1048576]={0};
  pd.node=1;
  pd.cost=0;
  pqpush(pd);
  while(hsize>0){
    od=pqpop();
    if(fl[od.node]==1){continue;}
    nv=od.node;
    fl[nv]=1;
    cnt++;
    r+=od.cost;
    if(cnt==vc){return r;}
    for(i=x[nv].st;i<x[nv].st+x[nv].kz;i++){
      if(fl[g[i].fi]==1){continue;}
      pd.node=g[i].fi;
      pd.cost=g[i].kr;
      pqpush(pd);
    }
  }
  return -1;
}

