int PAR[SIZE],RANK[SIZE];
void init_uf(int n){for(int i=0;i<n;i++){PAR[i]=i;RANK[i]=0;}}//initialize
int root(int i){return PAR[i]==i?i:(PAR[i]=root(PAR[i]));}//search group
int same(int x,int y){return root(x)==root(y);}//judge same group
void unite(int x,int y){//add edge
  x=root(x);y=root(y);
  if(x==y)return;
  if(RANK[x]<RANK[y])PAR[x]=y;
  else{PAR[y]=x;if(RANK[x]==RANK[y])RANK[x]++;}
}
void quicksort(long int a[],long int v[],int s,int t){
  if(s<t){
    int i=s,j=t,p=v[a[s]];
    while(1){
      while(v[a[i]]<p)i++;
      while(p<v[a[j]])j--;
      if(i>=j)break;
      a[i]^=a[j]^=a[i]^=a[j];
      i++;j--;
    }
    quicksort(a,v,s,i-1);quicksort(a,v,j+1,t);
  }
}
