/*
  アルゴリズム概要
  最初、頂点１つからなる「木」からスタート
  最小全域木においては、辺の数 = 頂点の数 - 1 となることは自明（辺と頂点はセット）
  各時点における「木」から出ている辺のうち、最小コストのものを考えると、
  その辺は最小全域木の部分グラフになる。（ノート参照）
  （辺のコストを、頂点のコストと読み替えない方が良い）
*/
int prim(int N, int **cost){
  //「木」と直接（辺１本だけを介して）繋がっている頂点のコストを記録。
  //一見、辺のコストを頂点のコストと読み替えてしまっているが、これはコスト最小の辺を選ぶためだけに使われているのでok
  //まあ、辺のコストを頂点のコストとして管理するのは面白い。
  int *mincost=(int *)malloc(sizeof(int)*N);
  bool *used=(bool *)malloc(sizeof(bool)*N);
  rep(i,N){
    mincost[i]=INF;
    used[i]=false;
  }
  mincost[0]=0;
  int ans=0;

  while(true){
    int next=-1;
    rep(i,N){
      if(used[i]==false && (next==-1 || mincost[next]>mincost[i])){
        //mincost[i]は木と直接繋がっていない頂点においても定義されているが、
        //最小になる頂点は必ず木と繋がっていることを利用している。
        next=i;
      }
    }

    if(next==-1){
      break;
    }

    used[next]=true;
    ans=ans+mincost[next];

    rep(i,N){
      //ここがダイクストラと違うところ。積み重ねではない。
      mincost[i]=min(mincost[i], cost[next][i]);
    }
  }

  return ans;
}


