    for(i=0;i<n;i++){
        par[i]=i;
        rank[i]=0;
    }
}
int root(int x){
    if(par[x]==x) return x;
    par[x]=root(par[x]);
    return par[x];
}
void combsort(int a[],int b[],int c[],int n){
    int i,h=n/1.3,swaped,tmp;
    if(h==0) h=1;
    while(h!=0||swaped!=0){
        swaped=0;
        if(h==0) h=1;
        if(h==10||h==9) h=11;
        for(i=0;i<n-h;i++){
            if(a[i]>a[i+h]){
                tmp=a[i];
                a[i]=a[i+h];
                a[i+h]=tmp;
                if(b!=NULL){
                    tmp=b[i];
                    b[i]=b[i+h];
                    b[i+h]=tmp;
                }
                if(c!=NULL){
                    tmp=c[i];
                    c[i]=c[i+h];
                    c[i+h]=c[i];
                }
                swaped=1;
            }
        }
        h=h/1.3;
    }
}
void unite(int x,int y){
    x=root(x);
    y=root(y);
    if(x!=y){
        int rx=rank[x],ry=rank[y];
        if(rx<ry){
            par[x]=y;
        }else{
            par[y]=x;
        }
        if(rx==ry) rank[x]++;
    }
}
int same(int x,int y){
    if(root(x)==root(y)) return 1;
    return 0;
}
