		candidates[i + (N - 1)].n1 = xy[i].idx;
		candidates[i + (N - 1)].n2 = xy[i + 1].idx;
		candidates[i + (N - 1)].cost = xy[i + 1].y - xy[i].y;
	}
	qsort(candidates, (N - 1) * 2, sizeof(*candidates),cmp_cost);
	uf_init();
	for (i = 0; i < (N - 1) * 2; i++) {
		if (!uf_issame(candidates[i].n1, candidates[i].n2)) {
			uf_merge(candidates[i].n1, candidates[i].n2);
			answer += candidates[i].cost;
		}
	}
	printf("%" PRId64 "\n", answer);
	return 0;
}

