#define NMAX 100000
struct node {
  int id;
  int weight;
  struct node *next;
};
struct point {
  int id;
  int x;
  int y;
};
struct node *list[NMAX];
struct point pos[NMAX];
int key[NMAX], visit[NMAX], heap[NMAX], heap_index[NMAX], heapsize; 

int comparex(const void *a, const void *b);
int comparey(const void *a, const void *b);
void Insert(int, int, int);
void downheap(int);
void upheap(int);
void PQ_init(int);
void PrimPQ(int, int);
int main(void)
{
  int i, j, n, x, y;
  long long int cost = 0;
  scanf("%d", &n);
  for (i = 0; i < n; i++) list[i] = NULL;
  for (i = 0; i < n; i++) {
    scanf("%d %d", &x, &y);
    pos[i].id = i;
    pos[i].x = x;
    pos[i].y = y;
  }
  qsort(pos, n, sizeof(struct point), comparex);
  for (i = 0; i < n - 1; i++) Insert(pos[i].id, pos[i+1].id, abs(pos[i].x - pos[i+1].x));
  qsort(pos, n, sizeof(struct point), comparey);
  for (i = 0; i < n - 1; i++) Insert(pos[i].id, pos[i+1].id, abs(pos[i].y - pos[i+1].y));
  PrimPQ(0, n);
  for (i = 0; i < n; i++) {
    cost += key[i];
    free(list[i]);
  }
