}
int comparex(const void *a, const void *b)
{
  int ax = ((struct point*)a)->x, bx = ((struct point*)b)->x;
  return ax - bx;
}
int comparey(const void *a, const void *b)
{
  int ay = ((struct point*)a)->y, by = ((struct point*)b)->y;
  return ay - by;
}
void Insert(int a, int b, int weight)
{
  struct node *p = (struct node*)malloc(sizeof(struct node));
  p->weight = weight;
  p->id = b;
  p->next = list[a];
  list[a] = p;
  p = (struct node*)malloc(sizeof(struct node));
  p->weight = weight;
  p->id = a;
  p->next = list[b];
  list[b] = p; 
}
void downheap(int k)
{
  int j, v = heap[k];
  while (k < heapsize / 2) {
    j = 2 * k + 1;
    if (j < heapsize - 1 && key[heap[j]] > key[heap[j+1]]) j++;
    if (key[v] <= key[heap[j]]) break;
    heap[k] = heap[j];
    heap_index[heap[j]] = k;
    k = j;
  }
  heap[k] = v;
  heap_index[v] = k;
}
void upheap(int j)
{
  int k, v = heap[j];
  while (j > 0) {
    k = (j + 1) / 2 - 1;
    if (key[v] >= key[heap[k]]) break;
    heap[j] = heap[k];
    heap_index[heap[k]] = j;
    j = k;
  }
  heap[j] = v;
  heap_index[v] = j;
}
void PQ_init(int size)
{
  int i;
  heapsize = size;
  for (i = 0; i < size; i++) {
    heap[i] = heap_index[i] = i;
  }
  for (i = size / 2 - 1; i >= 0; i--) {
    downheap(i);
  }
}
void PrimPQ(int p, int size)
{
  int i;
  for (i = 0; i < size; i++) {
    key[i] = INT_MAX;
    visit[i] = 0;
  }
  key[p] = 0;
  PQ_init(size);
  while (heapsize > 0) {
    struct node *n;
    int u = heap[0];
    visit[u] = 1;
    heap[0] = heap[heapsize - 1];
    heap_index[heap[heapsize - 1]] = 0;
    heapsize--;
    downheap(0);
    for (n = list[u]; n != NULL; n = n->next) {
      int v = n->id, w = n->weight;
      if (visit[v] == 0 && w < key[v]) {
	key[v] = w;
	upheap(heap_index[v]);
      }
    }
  }
}

#include<stdio.h>
#define SIZE 200000

int PAR[SIZE],RANK[SIZE];
void init_uf(int n){for(int i=0;i<n;i++){PAR[i]=i;RANK[i]=0;}}//initialize
int root(int i){return PAR[i]==i?i:(PAR[i]=root(PAR[i]));}//search group
int same(int x,int y){return root(x)==root(y);}//judge same group
void unite(int x,int y){//add edge
  x=root(x);y=root(y);
  if(x==y)return;
  if(RANK[x]<RANK[y])PAR[x]=y;
  else{PAR[y]=x;if(RANK[x]==RANK[y])RANK[x]++;}
}
void quicksort(long int a[],long int v[],int s,int t){
  if(s<t){
    int i=s,j=t,p=v[a[s]];
    while(1){
      while(v[a[i]]<p)i++;
      while(p<v[a[j]])j--;
      if(i>=j)break;
      a[i]^=a[j]^=a[i]^=a[j];
      i++;j--;
    }
    quicksort(a,v,s,i-1);quicksort(a,v,j+1,t);
  }
}
int main(){
