  for(i=0;i<n-1;i++){c[i]=x[a[i+1]]-x[a[i]];l[i][0]=a[i];l[i][1]=a[i+1];}
  quicksort(a,y,0,n-1);
  for(i=0;i<n-1;i++){c[n+i-1]=y[a[i+1]]-y[a[i]];l[n+i-1][0]=a[i];l[n+i-1][1]=a[i+1];}
  for(i=0;i<n*2-2;i++)a[i]=i;
  quicksort(a,c,0,n*2-3);
  init_uf(n*2);
  for(i=0;i<n*2-2;i++)if(!same(l[a[i]][0],l[a[i]][1])){t+=c[a[i]];unite(l[a[i]][0],l[a[i]][1]);}
  printf("%ld",t);
}

