import java.util.*
import kotlin.comparisons.compareBy

fun main(args: Array<String>) {
    val n = readLine()!!.toInt()
    val nodes: Array<Node> = Array(n) { i ->
        readLine()!!.split(" ").map { s -> s.toInt() }.let { Node(i, it[0], it[1]) }
    }
    nodes.sortBy { it.x }
    for (i in 0 until n - 1) {
        val a = nodes[i]
        val b = nodes[i + 1]
        val d = b.x - a.x
        a.edges.add(Edge(a, b, d))
        b.edges.add(Edge(b, a, d))
    }
    nodes.sortBy { it.y }
    for (i in 0 until n - 1) {
        val a = nodes[i]
        val b = nodes[i + 1]
        val d = b.y - a.y
        a.edges.add(Edge(a, b, d))
        b.edges.add(Edge(b, a, d))
    }
    val queue = PriorityQueue<Edge>(Math.sqrt(n.toDouble()).toInt(), compareBy { it.dist })

    val a = nodes[0]
    queue.addAll(a.edges)
    a.isVisited = true
    var d = 0L
    while (!queue.isEmpty()) {
        val e = queue.poll()
        if (!e.to.isVisited) {
            d += e.dist
            e.to.isVisited = true
            queue.addAll(e.to.edges)
        }
    }
    println(d)
}

class Node(val id: Int, val x: Int, val y: Int) {
    val edges: ArrayList<Edge> = ArrayList()
    var isVisited: Boolean = false
}

class Edge(val from: Node, val to: Node, val dist: Int)

fun main(arg: Array<String>) {

    val n = readLine()!!.toInt()

    val p = Array(n) { i ->
        readLine()!!.split(" ").map { it.toInt() }.let { intArrayOf(i, it[0], it[1]) }
    }

    val edge = ArrayList<IntArray>()

    p.sortBy { it[1] }
    for (i in 0..n - 2) {
        val d = Math.abs(p[i][1] - p[i + 1][1])
        edge.add(intArrayOf(p[i][0], p[i + 1][0], d))
    }

    p.sortBy { it[2] }
    for (i in 0..n - 2) {
        val d = Math.abs(p[i][2] - p[i + 1][2])
        edge.add(intArrayOf(p[i][0], p[i + 1][0], d))
    }

    edge.sortBy { it[2] }

    val uf = UnionFind(n)
    var ret = 0L

    edge.forEach {
        if (!uf.hasSameRoot(it[0], it[1])) {
            uf.unite(it[0], it[1])
            ret += it[2]
        }
    }
    println(ret)
}

class UnionFind(size: Int) {
    private val data: Array<Int> = Array(size) { -1 }

    fun unite(x: Int, y: Int) {
        val x = find(x)
        val y = find(y)
        if (data[x] > data[y]) {
            val temp = data[x]
            data[x] = data[y]
            data[y] = temp
        }
        data[x] += data[y]
        data[y] = x
    }

    fun find(k: Int): Int {
        if (this.data[k] < 0) return k
        data[k] = find(data[k])
        return data[k]
    }

    fun hasSameRoot(x: Int, y: Int) = find(x) == find(y)

    fun size(k: Int) = -data[find(k)]
}

import java.util.*

open class MainKt {
    companion object Static {
        @JvmStatic
        fun main(args: Array<String> = arrayOf()) {
            MainKt().solve()
        }
    }

    val scanner = Scanner(System.`in`)

    fun printf(pattern: String, vararg args: Any): Unit {
        println(String.format(pattern, *args))
    }

    open fun println(line: String) {
        kotlin.io.println(line)
    }

    fun println(line: Int) {
        println(line.toString())
    }

    fun println(line: Long) {
        println(line.toString())
    }

    open fun readLine(): String {
        return scanner.nextLine()
    }

    fun readArg(): String {
        return readLine()
    }

    fun readInt(): Int {
        return readArg().toInt()
    }

    fun readLong(): Long {
        return readArg().toLong()
    }

    fun readIntList(): List<Int> {
        return readArgList().map { it.toInt() }
    }

    fun readLongList(): List<Long> {
        return readArgList().map { it.toLong() }
    }

    fun readArgList(): List<String> {
        return readLine().split(" ")
    }

    data class Edge(val pointA: Point, val pointB: Point, val length: Int) {
        fun equals(other: Edge): Boolean {
            return pointA == other.pointA && pointB == other.pointB ||
                    pointA == other.pointB && pointB == other.pointA
        }
    }

    fun solve(): Unit {
        val n = readInt()
        var pointArray = Array<Point>(n, { Point(readIntList(), Tag(it)) })

        var edgeArray = arrayOfNulls<Edge>(2 * (n - 1))

        pointArray.sortBy { it!!.x }

        for (i in 0..(n-2)) {
            edgeArray[i] = Edge(
                    pointArray[i], pointArray[i + 1],
                    pointArray[i+1]!!.x - pointArray[i]!!.x)
        }

        pointArray.sortBy { it!!.y }

        for (i in 0..(n-2)) {
            edgeArray[n - 1 + i] = Edge(
                    pointArray[i], pointArray[i + 1],
                    pointArray[i+1]!!.y - pointArray[i]!!.y)
        }

        edgeArray.sortBy { it!!.length }

        var totalCost = 0

        edgeArray.forEach {
            if (it!!.pointA.tag != it.pointB.tag) {
                val tag: Tag
                val replacedTag: Tag
                if (it.pointA.tag.number < it.pointB.tag.number) {
                    tag = it.pointA.tag
                    replacedTag = it.pointB.tag
                } else {
                    tag = it.pointB.tag
                    replacedTag = it.pointA.tag
                }
                pointArray.forEach { sub ->
                    if (sub!!.tag == replacedTag)
                        sub.tag = tag
                }
                totalCost += it.length
            }
        }

        println(totalCost)
    }

