class Program {
    fun solve() {
        val sc = FastScanner()
        val n = sc.nextInt()
        val xy = Array(n) { sc.nextLong() - 1 to sc.nextLong() - 1 }

        val sortedByX = (0 until n).sortedBy { xy[it].first }
        val sortedByY = (0 until n).sortedBy { xy[it].second }

        val edges = mutableListOf<Triple<Int, Int, Long>>()
        for (i in 1 until n) {
