            edges.add(Triple(fx, tx, dx))

            val fy = sortedByY[i]
            val ty = sortedByY[i - 1]
            val dy = xy[fy].second - xy[ty].second
            edges.add(Triple(fy, ty, dy))
        }
        edges.sortBy { it.third }

        val uf = UnionFind(n)
        var ans = 0L
        for (i in edges.indices) {
