open class MainKt {
    companion object Static {
        @JvmStatic
        fun main(args: Array<String> = arrayOf()) {
            MainKt().solve()
        }
    }

    val scanner = Scanner(System.`in`)

    fun printf(pattern: String, vararg args: Any): Unit {
        println(String.format(pattern, *args))
    }

    open fun println(line: String) {
        kotlin.io.println(line)
    }

    fun println(line: Int) {
        println(line.toString())
    }

    fun println(line: Long) {
        println(line.toString())
    }

    open fun readLine(): String {
        return scanner.nextLine()
    }

    fun readArg(): String {
        return readLine()
    }

    fun readInt(): Int {
        return readArg().toInt()
    }

    fun readLong(): Long {
        return readArg().toLong()
    }

    fun readIntList(): List<Int> {
        return readArgList().map { it.toInt() }
    }

    fun readLongList(): List<Long> {
        return readArgList().map { it.toLong() }
    }

    fun readArgList(): List<String> {
        return readLine().split(" ")
    }

    data class Edge(val pointA: Point, val pointB: Point, val length: Int) {
        fun equals(other: Edge): Boolean {
            return pointA == other.pointA && pointB == other.pointB ||
                    pointA == other.pointB && pointB == other.pointA
        }
    }

    fun solve(): Unit {
        val n = readInt()
        var pointArray = Array<Point>(n, { Point(readIntList(), it) })

        var edgeArray = arrayOfNulls<Edge>(2 * (n - 1))

        pointArray.sortBy { it!!.x }

        for (i in 0..(n-2)) {
            edgeArray[i] = Edge(
                    pointArray[i], pointArray[i + 1],
                    pointArray[i+1]!!.x - pointArray[i]!!.x)
        }

        pointArray.sortBy { it!!.y }

        for (i in 0..(n-2)) {
            edgeArray[n - 1 + i] = Edge(
                    pointArray[i], pointArray[i + 1],
                    pointArray[i+1]!!.y - pointArray[i]!!.y)
        }

        edgeArray.sortBy { it!!.length }

        var totalCost = 0

        edgeArray.forEach {
            if (it!!.pointA.tag != it.pointB.tag) {
                val tag: Int
                val replacedTag: Int
                if (it.pointA.tag < it.pointB.tag) {
                    tag = it.pointA.tag
                    replacedTag = it.pointB.tag
                } else {
                    tag = it.pointB.tag
                    replacedTag = it.pointA.tag
                }
                pointArray.forEach { sub ->
                    if (sub!!.tag == replacedTag)
                        sub.tag = tag
                }
                totalCost += it.length
            }
        }

        println(totalCost)
    }

    data class Point(val x: Int, val y: Int, var tag: Int) {
        constructor(list: List<Int>, tag: Int): this(list[0], list[1], tag)
    }
}

