        return readLine().split(" ")
    }

    fun solve(): Unit {
        val n = readInt()
        val pointGroupList = mutableListOf<List<Point>>()
        val groupList = mutableListOf<Group>()
        for (i in 1..n) {
            val (x, y) = readIntList()
            groupList.add(Group(mutableListOf(x), mutableListOf(y)))
//            val p = Point(readIntList())
//            pointGroupList.add(listOf(p))
        }

        var totalCost: Int = 0
        while (groupList.count() > 1) {
            for (i in 0..(groupList.count() / 2 - 1)) {
                var cost = -1
                var minIndex = -1
                for (j in 0..(groupList.count() - 1)) {
                    if (i == j) continue
                    val c = d(groupList[i], groupList[j])
                    if (cost == -1) {
                        cost = c
                        minIndex = j
                    } else {
                        if (cost > c) {
                            minIndex = j
                            cost = c
                        }
                    }
                }
                totalCost += cost
                if (minIndex < i) {
                    groupList[minIndex] = Group(
                            groupList[minIndex].xList.union(groupList[i].xList).sorted() as MutableList<Int>,
                            groupList[minIndex].yList.union(groupList[i].yList).sorted() as MutableList<Int>
                    )
                    groupList.removeAt(i)
                } else {
                    groupList[i] = Group(
                            groupList[minIndex].xList.union(groupList[i].xList).sorted() as MutableList<Int>,
                            groupList[minIndex].yList.union(groupList[i].yList).sorted() as MutableList<Int>
                    )
                    groupList.removeAt(minIndex)
                }
            }
        }

        println(totalCost)
    }

    data class Group(
            val xList: MutableList<Int>,
            val yList: MutableList<Int>) {
    }

    data class Point(val x: Int, val y: Int) {
        constructor(list: List<Int>): this(list[0], list[1])
    }

    val pointList = mutableListOf<Point>()

    fun d(a: Point, b: Point): Int {
        return Math.min(Math.abs(a.x - b.x), Math.abs(a.y - b.y))
    }

    fun d(listA: List<Point>, listB: List<Point>): Int {
        var cost: Int = -1
        listA.forEach { a ->
            listB.forEach { b ->
                if (cost == -1) cost = d(a, b)
                else cost = Math.min(cost, d(a, b))
                if (cost == 0) return 0
            }
        }
        return cost
    }

    fun d(groupA: Group, groupB: Group): Int {
        var isFirst = true
        var cost: Int = -1
        groupA.xList.forEach { a ->
            groupB.xList.forEach { b ->
                val c = Math.abs(a - b)
                if (c == 0) return 0
                if (isFirst) {
                    cost = c
                    isFirst = false
                } else cost = Math.min(c, cost)
            }
        }
        groupA.yList.forEach { a ->
            groupB.yList.forEach { b ->
                val c = Math.abs(a - b)
                if (c == 0) return 0
                cost = Math.min(c, cost)
            }
        }
        return cost
    }
}

