fun kruskal(from: IntArray, to: IntArray, w: IntArray): Long {
    val n = from.size
    val uf = UnionFind(n)
    var ret = 0L
    for (i in 0..n - 1) {
        if (!uf.same(from[i], to[i])) {
            uf.union(from[i], to[i])
            ret += w[i]
        }
    }
    return ret
}

class UnionFind(size: Int) {
    val par = IntArray(size) { -1 }

    fun same(x: Int, y: Int) = root(x) == root(y)

    fun union(x: Int, y: Int) {
        val rx = root(x)
        val ry = root(y)
        if (rx == ry) return
        par[rx] += par[ry]
        par[ry] = x
    }

    fun root(x: Int): Int {
        if (par[x] < 0) return x
        par[x] = root(par[x])
        return par[x]
    }
}

