    for(i in 0 until n-1) {
        val a = nodes[i]
        val b = nodes[i + 1]
        val d = b.x - a.x
        a.edges.add(Edge(a, b, d))
        b.edges.add(Edge(b, a, d))
    }
    nodes.sortBy { it.y }
    for(i in 0 until n-1) {
        val a = nodes[i]
        val b = nodes[i + 1]
        val d = b.y - a.y
        a.edges.add(Edge(a, b, d))
        b.edges.add(Edge(b, a, d))
    }
    val queue = PriorityQueue<Edge>(compareBy { it.dist })

    val a = nodes[0]
    queue.addAll(a.edges)
    a.isVisited = true
    var d = 0L
    while (!queue.isEmpty()) {
        val e = queue.poll()
        if(!e.to.isVisited) {
            d += e.dist
            e.to.isVisited = true
            queue.addAll(e.to.edges)
        }
    }
    println(d)
}

