    fun solve(): Unit {
        val n = readInt()
        val pointGroupList = mutableListOf<List<Point>>()
        for (i in 1..n) {
            val p = Point(readIntList())
            pointGroupList.add(listOf(p))
        }

        var totalCost: Int = 0
        while (pointGroupList.count() > 1) {
            for (i in 0..(pointGroupList.count() / 2 - 1)) {
                var cost = -1
                var minIndex = -1
                for (j in 0..(pointGroupList.count() - 1)) {
                    if (i == j) continue
                    val tCost = d(pointGroupList[i], pointGroupList[j])
                    if (cost == -1) {
                        cost = tCost
                        minIndex = j
                    } else {
                        if (cost > tCost) {
                            cost = tCost
                            minIndex = j
                        }
                    }
                }
                pointGroupList[i] = pointGroupList[i] + pointGroupList[minIndex]
                pointGroupList.removeAt(minIndex)
                totalCost += cost
            }
        }

        println(totalCost.toInt())
    }

    data class Point(val x: Int, val y: Int) {
        constructor(list: List<Int>): this(list[0], list[1])
    }

    val pointList = mutableListOf<Point>()

    fun d(a: Point, b: Point): Int {
        return Math.min(Math.abs(a.x - b.x), Math.abs(a.y - b.y))
    }

    fun d(listA: List<Point>, listB: List<Point>): Int {
        var cost: Int = -1
        listA.forEach { a ->
            listB.forEach { b ->
                if (cost == -1) cost = d(a, b)
                else cost = Math.min(cost, d(a, b))
                if (cost == 0) return 0
            }
        }
        return cost
    }
}

