			int t[] = town[i], nt[] = town[i+1];
			q.add(new Edge(t[0], nt[0], nt[1] - t[1]));
		}
		Arrays.sort(town, (t1,t2)->t1[2]-t2[2]);
		for(int i=0;i<n-1;i++) {
			int t[] = town[i], nt[] = town[i+1];
			q.add(new Edge(t[0], nt[0], nt[2] - t[2]));
		}

		long ans = 0;
		UnionFind uf = new UnionFind(n);
		while(!q.isEmpty()) {
			Edge e = q.poll();
			if(uf.same(e.from, e.to))continue;
			ans += e.cost;
			uf.unite(e.from, e.to);
		}
		out.println(ans);
	}

