            addEdge(p, xa, i);
            addEdge(p, ya, i);
        }

        System.out.println(p.prim());
    }

    public static void addEdge(Prim p, int[][] za, int i){
        int from = za[i][1];
        int to = za[i+1][1];
        int cost = za[i+1][0] - za[i][0];
        p.addEdge(from, to, cost);
    }

