import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class Main {

	public static void main(String args[]) {
		FastScanner cin = new FastScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	private static void solve(FastScanner cin, PrintWriter cout) {
		int n = cin.nextInt();
		int[][] xs = new int[n][];
		int[][] ys = new int[n][];
		for (int i = 0; i < n; i++) {
			xs[i] = new int[] { cin.nextInt(), i };
			ys[i] = new int[] { cin.nextInt(), i };
		}

		PriorityQueue<int[]> edges = new PriorityQueue<>(Comparator.comparingInt((edge) -> edge[0]));

		Arrays.sort(xs, Comparator.comparingInt((vi) -> vi[0]));
		for (int i = 1; i < n; i++)
			edges.add(new int[] { Math.abs(xs[i - 1][0] - xs[i][0]), xs[i - 1][1], xs[i][1] });
		xs = null;

		Arrays.sort(ys, Comparator.comparingInt((vi) -> vi[0]));
		for (int i = 1; i < n; i++)
			edges.add(new int[] { Math.abs(ys[i - 1][0] - ys[i][0]), ys[i - 1][1], ys[i][1] });
		ys = null;

		long ans = 0;

		rt = new int[n];
		Arrays.fill(rt, -1);

		while (!edges.isEmpty()) {
			int[] edge = edges.remove();
			if (!unite(edge[1], edge[2]))
				continue;
			ans += edge[0];
		}

		cout.println(ans);
	};

	private static int[] rt;

	private static int root(int operand) {
		if (rt[operand] < 0)
			return operand;
		return rt[operand] = root(rt[operand]);
	}

	private static boolean unite(int fr, int to) {
		int a = root(fr);
		int b = root(to);
		if (a == b)
			return false;
		if (rt[a] > rt[b]) {
			int tmp = a;
			a = b;
			b = tmp;
		}
		rt[a] += rt[b];
		rt[b] = a;
		return true;
	}

	/**
	 * How to read input in Java — tutorial <br />
	 * By Flatfoot<br />
	 * http://codeforces.com/blog/entry/7018
	 */
	static class FastScanner {
		private BufferedReader br;
		private StringTokenizer st;

		FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements())
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new IllegalStateException(e);
				}
			return st.nextToken();
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				throw new IllegalStateException(e);
			}
			return str;
		}

		long nextLong() {
			return Long.parseLong(next());
		}
	}

}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Node ns[] = new Node[n];
        for (int i = 0; i < n; i++) {
            ns[i] = new Node(i, sc.nextLong(), sc.nextLong());
        }

        ArrayList<Edge> es[] = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            es[i] = new ArrayList<>();
        }
        Arrays.sort(ns, (n1, n2) -> Long.compare(n1.x, n2.x));
        createEdge(es, ns, n);
        Arrays.sort(ns, (n1, n2) -> Long.compare(n1.y, n2.y));
        createEdge(es, ns, n);

        boolean used[] = new boolean[n];
        long res = 0;
        PriorityQueue<Edge> queue = new PriorityQueue<>((e1, e2) ->
                Long.compare(e1.cost, e2.cost));
        used[0] = true;
        queue.addAll(es[0]);

        while (!queue.isEmpty()) {
            Edge e = queue.poll();
            if (used[e.to]) continue;
            used[e.to] = true;
            res += e.cost;

            queue.addAll(es[e.to]);
        }
        System.out.println(res);
    }

    static long dist(int i, int j, Node[] ns) {
        return Math.min(Math.abs(ns[i].x - ns[j].x), Math.abs(ns[i].y - ns[j].y));
    }

    static void createEdge(ArrayList<Edge> es[], Node[] ns, int n) {
        for (int i = 1; i < n; i++) {
            long dist1 = dist(i, i-1, ns);
            int prevID = ns[i-1].id;
            int ID = ns[i].id;
            Edge e1 = new Edge(prevID, ID, dist1);
            Edge e2 = new Edge(ID, prevID, dist1);
            es[prevID].add(e1);
            es[ID].add(e2);
        }

    }

    static class Node {
        int id;
        long x, y;
        Node(int id, long x, long y) {
            this.id = id;
            this.x = x;
            this.y = y;
        }

    }

    static class Edge {
        int from, to;
        long cost;
        Edge(int f, int t, long c) {
            from = f;
            to = t;
            cost = c;
        }

    }


}

