		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);

    	int vn=sc.nexI();

    	long[] xs = new long[vn];
    	long[] ys = new long[vn];

	   	for(int i=0; i<vn; i++){
	   	    xs[i] = sc.nexL();
	   	    ys[i] = sc.nexL();
	   	}

		int[] parent = new int[vn];
	   	for(int i=0; i<vn; i++){
	   	    parent[i]=i;
	   	}

	   	Edge[] xln = new Edge[vn];
	   	Edge[] yln = new Edge[vn];

	   	for(int i=0; i<vn; i++){
	   	    xln[i] = new Edge(i, xs[i]);
	   	    yln[i] = new Edge(i, ys[i]);
	   	}
	   	Arrays.sort(xln, new Comparator_Edge());
	   	Arrays.sort(yln, new Comparator_Edge());

	    Queue<Edge> edges = new PriorityQueue<>(new Comparator_Edge());

	    for(int i=1; i<vn; i++){
	        edges.add(new Edge(xln[i-1].v2, xln[i].v2, xln[i].weight-xln[i-1].weight));
	        edges.add(new Edge(yln[i-1].v2, yln[i].v2, yln[i].weight-yln[i-1].weight));
	    }

	    long ans=0;
	    while(edges.size()>0){
	        Edge e = edges.poll();
	        if(!is_same_uf(parent,e.from, e.v2)){
	            ans += e.weight;
	            unite_uf(parent,e.from, e.v2);
	        }
	    }
		out.println(ans);
