import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

/**
 * Created by dizzyvn on 6/24/17.
 */
public class Main {

    public static void main(String[] args) {

        class ArrayIndexComparator implements Comparator<Integer> {

            private final int[] array;


            public ArrayIndexComparator(int[] array) {
                this.array = array;
            }


            public Integer[] createIndexArray() {
                Integer[] indexes = new Integer[array.length];
                for (int i = 0; i < array.length; i++) {
                    indexes[i] = i; // Autoboxing
                }
                return indexes;
            }


            @Override
            public int compare(Integer idx1, Integer idx2) {
                // Autounbox from Integer to int to use as array indexes
                if (array[idx1] < array[idx2]) return -1;
                if (array[idx1] > array[idx2]) return 1;
                return 0;
            }
        }

        //input
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] X = new int[n];
        int[] Y = new int[n];
        int[] x_cost = new int[n-1];
        int[] y_cost = new int[n-1];

        for (int i = 0; i < n; i++) {
            X[i] = sc.nextInt();
            Y[i] = sc.nextInt();
        }

        //sort
        ArrayIndexComparator xComparator = new ArrayIndexComparator(X);
        ArrayIndexComparator yComparator = new ArrayIndexComparator(Y);
        Integer[] x_index = xComparator.createIndexArray();
        Integer[] y_index = yComparator.createIndexArray();
        Arrays.sort(x_index, xComparator);
        Arrays.sort(y_index, yComparator);


        for (int i = 0; i < n-1; i++) {
            x_cost[i] = X[x_index[i + 1]] - X[x_index[i]];
            y_cost[i] = Y[y_index[i + 1]] - Y[y_index[i]];
        }

        ArrayIndexComparator xCostComparator = new ArrayIndexComparator(x_cost);
        ArrayIndexComparator yCostComparator = new ArrayIndexComparator(y_cost);
        Integer[] xCost_index = xCostComparator.createIndexArray();
        Integer[] yCost_index = yCostComparator.createIndexArray();
        Arrays.sort(xCost_index, xCostComparator);
        Arrays.sort(yCost_index, yCostComparator);

        //process
        int cost = 0;
        boolean[] flag = new boolean[n];
        int x_pos = 0;
        int y_pos = 0;
        while (x_pos < n-1 && y_pos < n-1) {
            int costX = x_cost[xCost_index[x_pos]];
            int costY = y_cost[yCost_index[y_pos]];

            // try to use x
            if (costX < costY) {
                int idx1 = x_index[xCost_index[x_pos]];
                int idx2 = x_index[xCost_index[x_pos]+1];

                if (!flag[idx1] || !flag[idx2]) {
                    cost += costX;
                    flag[idx1] = true;
                    flag[idx2] = true;
                }
                x_pos++;
            }
            // try to use y
            else {
                int idx1 = y_index[yCost_index[y_pos]];
                int idx2 = y_index[yCost_index[y_pos]+1];

                if (!flag[idx1] || !flag[idx2]) {
                    cost += costY;
                    flag[idx1] = true;
                    flag[idx2] = true;
                }
                y_pos++;
            }
        }

        //output
        System.out.println(cost);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.StringTokenizer;

public class Main {

	public static void main(String args[]) {
		FastScanner cin = new FastScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	private static void solve(FastScanner cin, PrintWriter cout) {
		int n = cin.nextInt();
		int[][] xs = new int[n][];
		int[][] ys = new int[n][];
		for (int i = 0; i < n; i++) {
			xs[i] = new int[] { cin.nextInt(), i };
			ys[i] = new int[] { cin.nextInt(), i };
		}

		long ans = solve(n, xs, ys);
		cout.println(ans);
	}

	private static long solve(int n, int[][] xs, int[][] ys) {
		// editorialと他人の解答を参考
		// 速度・メモリを調整中

		ArrayList<int[]> edges = new ArrayList<>();

		Arrays.sort(xs, Comparator.comparingInt((vi) -> vi[0]));
		Arrays.sort(ys, Comparator.comparingInt((vi) -> vi[0]));
		for (int[][] vis : new int[][][] { xs, ys })
			for (int i = 1; i < n; i++)
				edges.add(new int[] { Math.abs(vis[i - 1][0] - vis[i][0]), vis[i - 1][1], vis[i][1] });

		// 最小全域木
		// https://ja.wikipedia.org/wiki/%E5%85%A8%E5%9F%9F%E6%9C%A8
		// https://en.wikipedia.org/wiki/Kruskal%27s_algorithm
		long ans = 0;
		Collections.sort(edges, Comparator.comparingInt((edge) -> edge[0]));

		rt = new int[n];
		Arrays.fill(rt, -1);

		for (int[] edge : edges) {
			int w = edge[0];
			int fr = edge[1];
			int to = edge[2];
			if (!unite(fr, to))
				continue;
			ans += w;
		}
		return ans;
	};

	private static int[] rt;

	private static int root(int operand) {
		if (rt[operand] < 0)
			return operand;
		return rt[operand] = root(rt[operand]);
	}

	private static boolean unite(int fr, int to) {
		int a = root(fr);
		int b = root(to);
		if (a == b)
			return false;
		if (rt[a] > rt[b]) {
			int tmp = a;
			a = b;
			b = tmp;
		}
		rt[a] += rt[b];
		rt[b] = a;
		return true;
	}

	/**
	 * How to read input in Java — tutorial <br />
	 * By Flatfoot<br />
	 * http://codeforces.com/blog/entry/7018
	 */
	static class FastScanner {
		private BufferedReader br;
		private StringTokenizer st;

		FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements())
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new IllegalStateException(e);
				}
			return st.nextToken();
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				throw new IllegalStateException(e);
			}
			return str;
		}

		long nextLong() {
			return Long.parseLong(next());
		}
	}

}

