class UnionFindTree
{
    int[] par;
    int[] rank;
    int[] sizes;

    UnionFindTree(int n)
    {
        par = new int[n];
        rank = new int[n];
        sizes = new int[n];
        for (int i = 0; i < n; i++)
        {
            par[i] = i;
            sizes[i] = 1;
        }
    }

    int root(int x)
    {
        if (par[x] == x) return x;
        else return par[x] = root(par[x]);
    }

    void unite(int x, int y)
    {
        int rx = root(x);
        int ry = root(y);

        if (rx == ry) return;
        if (rank[rx] < rank[ry])
        {
            par[rx] = ry;
            sizes[ry] += sizes[rx];
        }
        else
        {
            par[ry] = rx;
            sizes[rx] += sizes[ry];
            if (rank[rx] == rank[ry]) rank[rx]++;
        }
    }

    boolean isSame(int x, int y)
    {
        return root(x) == root(y);
    }

    int size(int x)
    {
        return sizes[root(x)];
    }
}

class P implements Comparable<P>
{
    int v, id;

    P(int a, int b)
    {
        v = a;
        id = b;
    }

    @Override
    public boolean equals(Object o)
    {
        if (this == o) return true;
        if (!(o instanceof P)) return false;
        P p = (P) o;
        return v == p.v && id == p.id;
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(v, id);
    }

    @Override
    public int compareTo(P p)
    {
        return v > p.v ? 1 : -1; //xで昇順にソート
