import java.util.ArrayList;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		new Main().solve();
	}

	int N;
	int[]x;
	int[]y;
	int INF=Integer.MAX_VALUE/2;

	void solve(){
		Scanner sc=new Scanner(System.in);
		N=sc.nextInt();
		x=new int[N];
		y=new int[N];
		ArrayList<Edge>[] list=new ArrayList[N];
		for(int i=0;i<N;i++){
			x[i]=sc.nextInt();
			y[i]=sc.nextInt();
			list[i]=new ArrayList<Edge>();
		}
		for(int i=0;i<N;i++){
			for(int j=i+1;j<N;j++){
				list[i].add(new Edge(j,Math.min(
						Math.abs(x[i]-x[j]),Math.abs(y[i]-y[j]))));

				list[j].add(new Edge(i,Math.min(
						Math.abs(x[i]-x[j]),Math.abs(y[i]-y[j]))));
			}
		}

		boolean[] used=new boolean[N];
		Queue<Edge> pq=new PriorityQueue<Edge>();
		pq.add(new Edge(0,0));
		int total=0;

		while(!pq.isEmpty()){
			Edge e=pq.poll();
			if(used[e.to]){
				continue;
			}
			used[e.to]=true;
			total+=e.cost;

			for(Edge e2: list[e.to]){
				pq.add(e2);
			}
		}
		System.out.println(total);

	}

	class Edge implements Comparable<Edge>{
		int to;
		int cost;

		Edge(int to, int cost){
			this.to=to;
			this.cost=cost;
		}
		@Override
		public int compareTo(Edge e){
			return this.cost-e.cost;
		}
	}
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    static Scanner in = new Scanner(System.in);

    public static void main(String[] args) {
        int N = in.nextInt();
        int[] x = new int[N], y = new int[N];
        for(int i =0; i < N; i++){
            x[i] = in.nextInt();
            y[i] = in.nextInt();

        }
        int[][] cost = new int[N][N];
        for(int i = 0; i < N; i++){
            for(int j = 0; j < N; j++){
                cost[i][j] = Math.min(Math.abs(x[i] - x[j]), Math.abs(y[i] - y[j]));
            }
        }
        int[] minicost = new int[N];
        boolean[] used = new boolean[N];
        Arrays.fill(minicost, Integer.MAX_VALUE);
        minicost[0] = 0;
        long ans = 0;

        while(true){
            int v = -1;
            for(int i = 0; i < N; i++){
                if(!used[i] && (v == -1 || minicost[i] < minicost[v])){
                    v = i;
                }
            }
            if(v == -1){
                break;
            }
            used[v] = true;
            ans += minicost[v];

            for(int i = 0; i < N; i++){
                minicost[i] = Math.min(minicost[i], cost[v][i]);
            }
        }
        System.out.println(ans);
    }
}

import java.util.*;

public class Main {
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		City[] cities = new City[n];
		for (int i = 0; i < n; i++) {
		    cities[i] = new City(i, sc.nextInt(), sc.nextInt());
		}
		Arrays.sort(cities, new Comparator<City>() {
		    public int compare(City c1, City c2) {
		        return c1.x - c2.x;
		    }
		});
		PriorityQueue<Road> queue = new PriorityQueue<>();
		for (int i = 1; i < n; i++) {
		    queue.add(new Road(cities[i].x - cities[i - 1].x, cities[i], cities[i - 1]));
		}
		Arrays.sort(cities, new Comparator<City>() {
		    public int compare(City c1, City c2) {
		        return c1.y - c2.y;
		    }
		});
		for (int i = 1; i < n; i++) {
		    queue.add(new Road(cities[i].y - cities[i - 1].y, cities[i], cities[i - 1]));
		}
		UnionFindTree uft = new UnionFindTree(n);
		long total = 0;
		while (queue.size() > 0) {
		    Road r = queue.poll();
		    if (!uft.same(r.from.id, r.to.id)) {
		        uft.unite(r.from.id, r.to.id);
		        total += r.cost;
		    }
		}
	    System.out.println(total);
   }

   static class UnionFindTree {
       int[] parents;

       public UnionFindTree(int size) {
           parents = new int[size];
           for (int i = 0; i < size; i++) {
               parents[i] = i;
           }
       }

       public int find(int x) {
           if (parents[x] == x) {
               return x;
           } else {
               return parents[x] = find(parents[x]);
           }
       }

       public boolean same(int x, int y) {
           return find(x) == find(y);
       }

       public void unite(int x, int y) {
           int xx = find(x);
           int yy = find(y);
           if (xx == yy) {
               return;
           }
           parents[xx] = yy;
       }
   }

   static class Road implements Comparable<Road> {
       int cost;
       City from;
       City to;

       public Road (int cost, City from, City to) {
           this.cost = cost;
           this.from = from;
           this.to = to;
       }

       public int compareTo(Road another) {
           return cost - another.cost;
       }
   }

   static class City {
       int id;
       int x;
       int y;

       public City(int id, int x, int y) {
           this.id = id;
           this.x = x;
           this.y = y;
       }
   }
}

import java.io.OutputStream;
