        // -----------------------------------------
        // ABC-065 D Built ?
        //
        // 工事中
        //
        final int INF = 1000000010;
        final int WHITE = 0, GRAY = 1, BLACK = 2;

        GraphWith G = new GraphWith();					// グラフの隣接リスト(頂点と辺の長さ）
														// 辺の長さの短い順で並ぶ、優先度付きキュー
        PriorityQueue<PP> PQ = new PriorityQueue<>(comparing(PP::getKey));

        int N;											// 頂点の数
    	int[] d;										// d[3] なら 頂点３ までの最短コストを記録する
    	int[] p;										// p[3] なら 頂点３ の親の頂点を保存する（つながっていなければ -1 ）
    	int[] color;									// 白：未処理　黒：処理済み　グレー：
        // プリムのアルゴリズム
        int prim() {
        	for(int i=0; i < N; i++) {					// 変数の初期化
        		d[i] = INF;
        		p[i] = -1;
        		color[i] = WHITE;
        	}
        	d[0] = 0;									// 先頭は　０
        	PQ.add(new PP(0,0));						// 優先度付きキューにいれるのは　辺の長さと頂点のペア（並びに注意）
        	int u, v;
        	PP pp;
        	while(!PQ.isEmpty()) {
        		pp = PQ.poll();							// 始点に一番近い頂点を取り出して、消す
//        		prn("頂点　：　" + pp.getVal() + "  距離　: " + pp.getKey());
        		u = pp.getVal();						// 頂点の番号
        		color[u] = BLACK;
        		if(G.contains(u)) {
	        		for(PP wk : G.get(u)) {
	        			v = wk.getKey();					// u につながる頂点
	        			if(color[v] == BLACK)	continue;	// 処理済みなら　次へ
	        			if(d[v] > wk.getVal()) {			// wk.getVal() が辺の長さ
	        				d[v] = wk.getVal();
        					p[v] = u;
	        				PQ.add(new PP(d[v], v));	// 辺の長さと頂点のペア（並びに注意）
	        			}
	        		}
        		}
        	}
        	int sum = 0;
        	for(int i=0; i < N; i++) {
        		// つながっている頂点の辺を集計する
        		if(p[i] != -1) {
        			for(PP wk : G.get(i)) {
        				if(wk.getKey() == p[i]) {
        					sum += wk.getVal();
//        					prn("i = " + i + "  [" + wk.getKey() + "][" + p[i] + "] = " + wk.getVal() + " --> " + sum);
        					break;
        				}
        			}
        		}
        	}
        	return sum;
        }
        public void solve() {
        	N = ni();
        	d = new int[N];
        	p = new int[N];
        	color = new int[N];

        	List<PP> listX = new ArrayList<>();
        	List<PP> listY = new ArrayList<>();
        	int x, y;
        	for (int i = 0; i < N; i++) {
				x = ni();
				y = ni();
				listX.add(new PP(x, i));
				listY.add(new PP(y, i));
			}
        	listX.sort(comparing(PP::getKey));
        	listY.sort(comparing(PP::getKey));
        	Map<PPKEY, Integer> map = new HashMap<PPKEY, Integer>();
        	PP pre = null;
        	PPKEY pkey = null;
        	for(PP pp : listX) {
        		if(pre != null) {
//        			prn(" X  [" + pre.val + "] <--> [" + pp.val + "]  = " + (pp.key - pre.key));
        			map.put(new PPKEY(pre.val, pp.val), pp.key - pre.key);
        			map.put(new PPKEY(pp.val, pre.val), pp.key - pre.key);
        		}
        		pre = pp;
        	}
        	pre = null;
        	Integer val;
        	for(PP pp : listY) {
        		if(pre != null) {
//        			prn(" Y  [" + pre.val + "] <--> [" + pp.val + "]  = " + (pp.key - pre.key));
        			pkey = new PPKEY(pre.val, pp.val);
        			val = map.get(pkey);
        			map.put(pkey, Math.min((val == null ? 1000100100 : val), pp.key - pre.key));
        			pkey = new PPKEY(pp.val, pre.val);
        			val = map.get(pkey);
        			map.put(pkey, Math.min((val == null ? 1000100100 : val), pp.key - pre.key));
        		}
        		pre = pp;
        	}
        	for(PPKEY ppkey : map.keySet()) {
        		val = map.get(ppkey);
//    			prn("[" + ppkey.key + "] <--> [" + ppkey.val + "]  = " + val);
        		G.add(ppkey.key, new PP(ppkey.val, val));
//        		G.add(ppkey.val, new PP(ppkey.key, val));
        	}
        	prn(prim());
        }

