      graph[i+n-1] = new Edge(p[i].id,p[i+1].id,(long)(p[i+1].y-p[i].y));
    }
    Arrays.sort(graph,Comparator.comparingLong(e -> e.cost));
    UnionFind uf = new UnionFind(n);
