      this.x = x;
      this.y = y;
      this.id = id;
    }
  }
  private class Edge {
    private int from;
    private int to;
    private long cost;
    Edge(int from,int to,long cost) {
      this.from = from;
      this.to = to;
      this.cost = cost;
    }
  }
  private class UnionFind {
    int n;
    int[] par;
    int[] rank;
    int[] size;
    UnionFind(int n) {
      this.n = n;
      par = new int[n];
      rank = new int[n];
      size = new int[n];
      for (int i=0;i<n;i++) {
        par[i] = i;
        size[i] = 1;
      }
    }
    private int find(int i) {
      if (par[i] == i) return i;
      return par[i] = find(par[i]);
    }
    private boolean same(int i,int j) {
      return find(i) == find(j);
    }
    private int size(int i) {
      return size[find(i)];
    }
    private void unite(int i,int j) {
      i = find(i);
      j = find(j);
      if (i == j) return;
      if (rank[i] < rank[j]) {
        par[i] = j;
        size[j] += size[i];
      } else {
        par[j] = i;
        size[i] += size[j];
        if (rank[i] == rank[j]) rank[i]++;
      }
    }
  }
}

