		}
		list.sort(comparing(PPP::getVal2));
		from = null;
		for (PPP to : list) {
			if(from == null)	from = to;
			else {
				len1 = Math.abs(to.val - from.val);
				len2 = Math.abs(to.val2 - from.val2);
				if(len2 < len1) {
					G.add(from.key, new PP(to.key, len2));
					G.add(to.key, new PP(from.key, len2));
				}
