			i = ii[h - 1];
			j = ii[h];
			w = xx[j] - xx[i];
			ee[m++] = new E(i, j, w);
			i = jj[h - 1];
			j = jj[h];
			w = yy[j] - yy[i];
			ee[m++] = new E(i, j, w);
		}
		Arrays.sort(ee, (e, f) -> e.w - f.w);
		ds = new int[n]; Arrays.fill(ds, -1);
		long ans = 0;
		for (int h = 0; h < m; h++) {
			E e = ee[h];
			if (join(e.i, e.j))
				ans += e.w;
		}
		println(ans);
	}
}

