class DisjointSet {
	int[] p;
	public DisjointSet(int n) {
		p = new int[n];
		for (int i = 0; i < n; ++i)
			p[i] = -1;
	}
	public int getRoot(int u) {
		if (p[u] == -1) return u;
		return p[u] = getRoot(p[u]);
	}
	public boolean isConnected(int u, int v) {
		u = getRoot(u); 
		v = getRoot(v);
		if (u == v) return true;
		p[u] = v;
		return false;
	}
}

