		E = new Edge[2*N-2];
		int m = 0;
		for (int i = 1; i < N; ++i) {
			E[m++] = new Edge(X_id[i], X_id[i-1], X_Coor[X_id[i]]-X_Coor[X_id[i-1]]);
			E[m++] = new Edge(Y_id[i], Y_id[i-1], Y_Coor[Y_id[i]]-Y_Coor[Y_id[i-1]]);
		}
		Arrays.sort(E, new CompKey_e());
		d = new DisjointSet(N);
		long res = 0;
		for (int i = 0; i < m; ++i) 
			if (!d.isConnected(E[i].u, E[i].v)) 
				res += E[i].w;
		jvout.println(res);
		jvout.flush();
	}
}

