class City {
    int p;
    long x, y;

    public City(int a, long b, long c) {
        p = a;
        x = b;
        y = c;
    }
}

class Road{
    int from, to;
    long cost;
    public Road(int f, int t, long c){
        from = f;
        to= t;
        cost = c;
    }
}

class UnionFind {
    int[] par;
    int[] rank;

    public UnionFind(int n) {
        par = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            par[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int i) {
        if (par[i] == i) {
            return i;
        }
        return par[i] = find(par[i]);
    }

    public void union(int x, int y) {
        x = find(x);
        y = find(y);

        if (rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (rank[x] == rank[y]) {
                rank[x]++;
            }
        }
    }

    public boolean same(int x, int y) {
        return find(par[x]) == find(par[y]);
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    static Scanner in = new Scanner(System.in);

    public static void main(String[] args) {
        int N = in.nextInt();
        long[] x = new long[N], y = new long[N];
        for(int i =0; i < N; i++){
            x[i] = in.nextLong();
            y[i] = in.nextLong();

        }
        long[][] cost = new long[N][N];
        for(int i = 0; i < N; i++){
            for(int j = 0; j < N; j++){
                cost[i][j] = Math.min(Math.abs(x[i] - x[j]), Math.abs(y[i] - y[j]));
            }
        }
        long[] minicost = new long[N];
        boolean[] used = new boolean[N];
        Arrays.fill(minicost, Integer.MAX_VALUE);
        minicost[0] = 0;
        long ans = 0;

        while(true){
            int v = -1;
            for(int i = 0; i < N; i++){
                if(!used[i] && (v == -1 || minicost[i] < minicost[v])){
                    v = i;
                }
            }
            if(v == -1){
                break;
            }
            used[v] = true;
            ans += minicost[v];

            for(int i = 0; i < N; i++){
                minicost[i] = Math.min(minicost[i], cost[v][i]);
            }
        }
        System.out.println(ans);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.Scanner;

public class Main {

    private static Scanner scan = new Scanner(System.in);

    public static void main(String[] args) {
	int N = Integer.parseInt(scan.next());
	List<X> xList = new ArrayList<X>(N);
	List<X> yList = new ArrayList<X>(N);
	int[] belong = new int[N];

	for (int i = 0; i < N; i++) {
	    belong[i] = i;
	    xList.add(new X(Integer.parseInt(scan.next()), i));
	    yList.add(new X(Integer.parseInt(scan.next()), i));
	}
	Collections.sort(xList);
	Collections.sort(yList);

	List<Edge> list = new ArrayList<Edge>();
	for (int i = 0; i < N-1; i++) {
	    list.add(new Edge(xList.get(i).index, xList.get(i+1).index, Math.abs(xList.get(i).x - xList.get(i+1).x)));
	    list.add(new Edge(yList.get(i).index, yList.get(i+1).index, Math.abs(yList.get(i).x - yList.get(i+1).x)));
	}
	Collections.sort(list);

	int total = 0;
	for(Iterator<Edge> itr = list.iterator(); itr.hasNext();) {
	    Edge e = itr.next();
	    int idx1 = e.from;
	    int idx2 = e.to;

	    if(belong[idx1] != belong[idx2]) {
		total += e.cost;
		belong[idx1] = belong[idx2];
	    }
	}

	System.out.println(total);
	scan.close();
    }
}

class X implements Comparable<X> {
    int x;
    int index;

    X(int x, int index) {
	this.x = x;
	this.index = index;
	}

    @Override
    public int compareTo(X o) {
	return x - o.x;
    }
}

class Edge implements Comparable<Edge>{
    int from;
    int to;
    int cost;

    Edge(int from, int to, int cost) {
	this.from = from;
	this.to = to;
	this.cost = cost;
	}

    @Override
    public int compareTo(Edge o) {
	return cost - o.cost;
    }

}

