    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class IntVPair<V> implements Comparable<IntVPair<V>> {
        public final int first;
        public final V second;

        public static <V> IntVPair<V> makePair(int first, V second) {
            return new IntVPair<V>(first, second);
        }

        private IntVPair(int first, V second) {
            this.first = first;
            this.second = second;
        }

        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || getClass() != o.getClass()) {
                return false;
            }

            IntCharPair pair = (IntCharPair) o;

            return first == pair.first && second.equals(pair.second);
        }

        public int hashCode() {
            int result = Integer.hashCode(first);
            result = 31 * result + second.hashCode();
            return result;
        }

        public String toString() {
            return "(" + first + "," + second + ")";
        }

        public int compareTo(IntVPair<V> o) {
            int value = Integer.compare(first, o.first);
            if (value != 0) {
                return value;
            }
            return ((Comparable<V>) second).compareTo(o.second);
        }

    }

    static class IntIntPair implements Comparable<IntIntPair> {
        public final int first;
        public final int second;

        public IntIntPair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || getClass() != o.getClass()) {
                return false;
            }

            IntIntPair pair = (IntIntPair) o;

            return first == pair.first && second == pair.second;
        }

        public int hashCode() {
            int result = first;
            result = 31 * result + second;
            return result;
        }

        public String toString() {
            return "(" + first + "," + second + ")";
        }

        public int compareTo(IntIntPair o) {
            int value = Integer.compare(first, o.first);
            if (value != 0) {
                return value;
            }
            return Integer.compare(second, o.second);
        }

    }

    static class UnionFind {
        int[] parent;

        public UnionFind(int size) {
            parent = new int[size];
            Arrays.fill(parent, -1);
        }

        public boolean union(int x, int y) {
            x = root(x);
            y = root(y);
            if (x != y) {
                if (parent[y] < parent[x]) {
                    int tmp = y;
                    y = x;
                    x = tmp;
                }
                parent[x] += parent[y];
                parent[y] = x;
                return true;
            }
            return false;
        }

        public boolean isConnected(int x, int y) {
            return root(x) == root(y);
        }

        public int root(int x) {
            return parent[x] < 0 ? x : (parent[x] = root(parent[x]));
        }

        public ArrayList<ArrayList<Integer>> getGroups() {
            int n = parent.length;
            ArrayList<ArrayList<Integer>> groups = new ArrayList<>();
            HashMap<Integer, Integer> map = new HashMap<>();
            for (int i = 0; i < n; i++) {
                int r = root(i);
                if (!map.containsKey(r)) {
                    map.put(r, groups.size());
                    groups.add(new ArrayList<>());
                }
                groups.get(map.get(r)).add(i);
            }
            return groups;
        }

        public String toString() {
            return getGroups().toString();
        }

    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.BitSet;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * https://atcoder.jp/contests/abc065/submissions/3882674 を参考に作成
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			Node[] nodes = new Node[n];
			IntStream.range(0, n).forEach(i -> nodes[i] = new Node(i, scanner.nextInt(), scanner.nextInt()));
			// X座標でソート
			Arrays.sort(nodes, (n1, n2) -> n1.x - n2.x);
			IntStream.range(0, n - 1).forEach(i -> {
				nodes[i].edges.add(new Edge(nodes[i], nodes[i + 1], nodes[i + 1].x - nodes[i].x));
				nodes[i + 1].edges.add(new Edge(nodes[i + 1], nodes[i], nodes[i + 1].x - nodes[i].x));
			});
			// Y座標でソート
			Arrays.sort(nodes, (n1, n2) -> n1.y - n2.y);
			IntStream.range(0, n - 1).forEach(i -> {
				nodes[i].edges.add(new Edge(nodes[i], nodes[i + 1], nodes[i + 1].y - nodes[i].y));
				nodes[i + 1].edges.add(new Edge(nodes[i + 1], nodes[i], nodes[i + 1].y - nodes[i].y));
			});
			System.out.println(getResult(nodes[0], n));
		}
	}

	/**
	 * @param src 開始ノード
	 * @param n   町の数
	 * @return srcの町からすべての町への道路の最小コスト
	 */
	private static long getResult(Node src, int n) {
		BitSet visited = new BitSet(n);
		Queue<Edge> queue = new PriorityQueue<>((e1, e2) -> e1.cost - e2.cost);
		queue.addAll(src.edges);
		visited.set(src.id, true);
		long result = 0L;
		while (!queue.isEmpty()) {
			Edge edge = queue.poll();
			if (!visited.get(edge.to.id)) {
				result += edge.cost;
				visited.set(edge.to.id, true);
				queue.addAll(edge.to.edges);
			}
		}
		return result;
	}

	/**
	 * ノードを格納するクラス
	 */
	private static final class Node {
		final int id;
		final int x;
		final int y;
		List<Edge> edges = new ArrayList<>();

		Node(int id, int x, int y) {
			super();
			this.id = id;
			this.x = x;
			this.y = y;
		}
	}

	/**
	 * 辺を表すクラス
	 */
	private static final class Edge {
		/** 始点 */
		@SuppressWarnings("unused")
		final Node from;
		/** 終点 */
		final Node to;
		/** コスト */
		final int cost;

		Edge(Node from, Node to, int cost) {
			super();
			this.from = from;
			this.to = to;
			this.cost = cost;
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.StringTokenizer;

public class Main {

	public static void main(String args[]) {
		FastScanner cin = new FastScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	private static void solve(FastScanner cin, PrintWriter cout) {
		int n = cin.nextInt();
		int[][] xys = new int[n][];
		for (int i = 0; i < n; i++)
			xys[i] = new int[] { cin.nextInt(), cin.nextInt(), i };

		long ans = solve(n, xys);
		cout.println(ans);
	}

	private static long solve(int n, int[][] xys) {
		// editorial後

		ArrayList<int[]> ordered = new ArrayList<>();
		for (int[] xy : xys)
			ordered.add(xy);
		ArrayList<int[]> edges = new ArrayList<>();
		for (int j = 0; j < 2; j++) {
			int tmp = j;
			Collections.sort(ordered, (xy1, xy2) -> Integer.compare(xy1[tmp], xy2[tmp]));
			for (int i = 1; i < n; i++) {
				int fr = ordered.get(i - 1)[2];
				int to = ordered.get(i)[2];
				int[] frxy = xys[fr];
				int[] toxy = xys[to];
				int w = Math.abs(frxy[tmp] - toxy[tmp]);
				edges.add(new int[] { w, fr, to });
			}
		}

		// 最小全域木
		// https://ja.wikipedia.org/wiki/%E5%85%A8%E5%9F%9F%E6%9C%A8
		// クラスカル法
		// https://en.wikipedia.org/wiki/Kruskal%27s_algorithm
		long ans = 0;

		class Group {
			int no;

			public Group(int no) {
				super();
				this.no = no;
			}

			@Override
			public String toString() {
				return Integer.toString(no);
			}
		}
		Group[] vis = new Group[n];
		int group = 0;
		Collections.sort(edges, (e1, e2) -> Integer.compare(e1[0], e2[0]));
		for (int[] e : edges) {
			int w = e[0];
			int fr = e[1];
			int to = e[2];
			// unite
			Group g;
			if (vis[fr] == null && vis[to] == null) {
				group += 1;
				g = new Group(group);
			} else if (vis[fr] == null ^ vis[to] == null) {
				g = vis[to];
				if (g == null)
					g = vis[fr];
			} else if (vis[fr].no != vis[to].no) {
				// マージ
				g = vis[to];
				g.no = vis[fr].no;
			} else {
				// if same
				continue;
			}
			vis[fr] = g;
			vis[to] = g;
			ans += w;
			// System.out.println(fr + " " + to);
			// System.out.println(Arrays.toString(vis));
		}
		return ans;
	};

	/**
	 * How to read input in Java — tutorial <br />
	 * By Flatfoot<br />
	 * http://codeforces.com/blog/entry/7018
	 */
	static class FastScanner {
		private BufferedReader br;
		private StringTokenizer st;

		FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements())
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new IllegalStateException(e);
				}
			return st.nextToken();
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				throw new IllegalStateException(e);
			}
			return str;
		}

		long nextLong() {
			return Long.parseLong(next());
		}
	}

}

