      Arrays.sort(ty, (o1, o2) -> Compare.L(o1.y, o2.y));

      Graph g = new Graph();
      g.init(N);

      for (int i=0; i<N-1; i++) {
        g.addEdge(tx[i].id, tx[i+1].id, tx[i+1].x-tx[i].x, false);
