				m =a[i];
				mindex = i;
			}
		}
		return m;
	}
	long sum(long[] a){
		long s = 0;
		for(int i=0;i<a.length;i++)s += a[i];
		return s;
	}
	long sum(int[] a){
		long s = 0;
		for(int i=0;i<a.length;i++)s += a[i];
		return s;
	}
	long gcd(long a, long b){
		a = Math.abs(a);
		b = Math.abs(b);
		if(a==0)return b;
		if(b==0)return a;
		if(a%b==0) return b;
		else return gcd(b,a%b);
	}
	int igcd(int a, int b) {
		if(a%b==0) return b;
		else return igcd(b,a%b);
	}
	long lcm(long a, long b) {return a / gcd(a,b) * b;}
	public long perm(int a,int num) {
		if(!isBuild)buildFac();
		return fac[a]*(rev(fac[a-num]))%mod;
	}
	void buildComb(int N) {
		comb = new long[N+1][N+1];
		comb[0][0] = 1;
		for(int i=1;i<=N;i++) {
			comb[i][0] = 1;
			for(int j=1;j<N;j++) {
				comb[i][j] = comb[i-1][j-1]+comb[i-1][j];
				if(comb[i][j]>mod)comb[i][j]-=mod;
			}
			comb[i][i] = 1;
		}
	}
	public long comb(int a,int num){
		if(a-num<0)return 0;
		if(num<0)return 0;
		if(!isBuild)buildFac();
		return fac[a] * ((revfac[num]*revfac[a-num])%mod)%mod;
	}
	long mulchoose(int n,int k) {
		if(k==0) return 1;
		return comb(n+k-1,k);
	}
	long rev(long l) {return pow(l,mod-2);}

	void buildpow(int l,int i) {
		pow = new long[i+1];
		pow[0] = 1;
		for(int j=1;j<=i;j++) {
			pow[j] = pow[j-1]*l;
			if(pow[j]>mod)pow[j] %= mod;
		}
	}
	void buildrevpow(int l,int i) {
		revpow = new long[i+1];
		revpow[0] = 1;
		for(int j=1;j<=i;j++) {
			revpow[j] = revpow[j-1]*l;
			if(revpow[j]>mod) revpow[j] %= mod;
		}
	}
	long pow(long l, long i) {
		if(i==0)return 1;
		else{
			if(i%2==0){
				long val = pow(l,i/2);
				return val * val % mod;
			}
			else return pow(l,i-1) * l % mod;
		}
	}
	long mon(int i) {
		long ans = 0;
		for(int k=2;k<=i;k++) {
			ans += (k%2==0?1:-1) * revfac[k];
			ans += mod;
		}
		ans %= mod;
		ans *= fac[i];
		return ans%mod;
	}


	long dictnum(int[] A) {
		int N = A.length;
		long ans = 0;
		BinaryIndexedTree bit = new BinaryIndexedTree(N+1);
		buildFacn(N);
		for(int i=1;i<=N;i++) {
			bit.add(i,1);
		}
		for(int i=1;i<=N;i++) {
			int a = A[i-1];
			ans += bit.sum(a-1) * fac[N-i] % mod;
			bit.add(a,-1);
		}
		return (ans+1)%mod;
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.StringTokenizer;
import java.util.function.IntUnaryOperator;
import java.util.function.Predicate;

public class Main {

	public static void main(String args[]) {
		FastScanner cin = new FastScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	private static void solve(FastScanner cin, PrintWriter cout) {
		int n = cin.nextInt();
		int[][] xys = new int[n][];
		for (int i = 0; i < n; i++)
			xys[i] = new int[] { cin.nextInt(), cin.nextInt(), i };

		long ans = solve(n, xys);
		cout.println(ans);
	}

	private static long solve(int n, int[][] xys) {
		// editorialと他人の解答を参考

		ArrayList<int[]> edges = new ArrayList<>();

		ArrayList<int[]> ordered = new ArrayList<>();
		ordered.addAll(Arrays.asList(xys));
		for (int j = 0; j < 2; j++) {
			int tmp = j;
			Collections.sort(ordered, Comparator.comparingInt((xy) -> xy[tmp]));
			for (int i = 1; i < n; i++) {
				int fr = ordered.get(i - 1)[2];
				int to = ordered.get(i)[2];
				int[] frxy = xys[fr];
				int[] toxy = xys[to];
				int w = Math.abs(frxy[tmp] - toxy[tmp]);
				// int w = Math.min(Math.abs(frxy[0] - toxy[0]),
				// Math.abs(frxy[1] - toxy[1]));
				edges.add(new int[] { w, fr, to });
			}
		}

		// 最小全域木
		// https://ja.wikipedia.org/wiki/%E5%85%A8%E5%9F%9F%E6%9C%A8
		// クラスカル法
		// https://en.wikipedia.org/wiki/Kruskal%27s_algorithm
		long ans = 0;
		Collections.sort(edges, Comparator.comparingInt((e) -> e[0]));

		int[] rt = new int[n];
		Arrays.fill(rt, -1);
		IntUnaryOperator root = new IntUnaryOperator() {
			@Override
			public int applyAsInt(int operand) {
				if (rt[operand] < 0)
					return operand;
				return rt[operand] = this.applyAsInt(rt[operand]);
			}
		};
		Predicate<int[]> unite = new Predicate<int[]>() {
			@Override
			public boolean test(int[] t) {
				int a = root.applyAsInt(t[0]);
				int b = root.applyAsInt(t[1]);
				if (a == b)
					return false;
				if (rt[a] > rt[b]) {
					int tmp = a;
					a = b;
					b = tmp;
				}
				rt[a] += rt[b];
				rt[b] = a;
				return true;
			}
		};
		for (int[] e : edges) {
			int w = e[0];
			int fr = e[1];
			int to = e[2];
			if (!unite.test(new int[] { fr, to }))
				continue;
			ans += w;
			System.out.println(fr + " " + to);
			System.out.println(Arrays.toString(rt));
		}
		return ans;
	};

	/**
	 * How to read input in Java — tutorial <br />
	 * By Flatfoot<br />
	 * http://codeforces.com/blog/entry/7018
	 */
	static class FastScanner {
		private BufferedReader br;
		private StringTokenizer st;

		FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements())
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new IllegalStateException(e);
				}
			return st.nextToken();
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				throw new IllegalStateException(e);
			}
			return str;
		}

		long nextLong() {
			return Long.parseLong(next());
		}
	}

}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private void solve(Scanner sc) {
        int N = sc.nextInt();
        NavigableSet<Point> set1 = new TreeSet<>(new Comparator<Point>() { public int compare(Point p1, Point p2) { return (p1.x > p2.x ? 1 : (p1.x < p2.x ? -1 : 0)); } });
        NavigableSet<Point> set2 = new TreeSet<>(new Comparator<Point>() { public int compare(Point p1, Point p2) { return (p1.y > p2.y ? 1 : (p1.y < p2.y ? -1 : 0)); } });
        long cost = 0;
        Point[] points = new Point[N];
        for (int i = 0; i < N; ++i) {
            long x = sc.nextInt();
            long y = sc.nextInt();
            Point p = new Point(i, x, y);
            points[i] = p;
            set1.add(p);
            set2.add(p);
        }
        for (int i = 0; i < N; ++i) {
            Point p = points[i];
            Point p11 = set1.lower(p);
            Point p12 = set1.higher(p);
            Point p21 = set2.lower(p);
            Point p22 = set2.higher(p);
            long cost1 = 0;
            if (p11 == null && p12 == null) {
            } else if (p11 == null && p12 != null) {
                cost1 = Math.abs(p.x - p12.x);
            } else if (p11 != null && p12 == null) {
                cost1 = Math.abs(p.x - p11.x);
            } else {
                cost1 = Math.min(Math.abs(p.x - p11.x), Math.abs(p.x - p12.x));
            }
            long cost2 = 0;
            if (p21 == null && p22 == null) {
            } else if (p21 == null && p22 != null) {
                cost2 = Math.abs(p.y - p22.y);
            } else if (p21 != null && p22 == null) {
                cost2 = Math.abs(p.y - p21.y);
            } else {
                cost2 = Math.min(Math.abs(p.y - p21.y), Math.abs(p.y - p22.y));
            }
            cost += Math.min(cost1, cost2);
        }
        _out.println(cost - 1);
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    private static class Point implements Comparable<Point> {
        int n;
        long x;
        long y;
        public Point(int n, long x, long y) {
            this.n = n;
            this.x = x;
            this.y = y;
        }
        public boolean equals(Object o) {
            if (o instanceof Point) {
                Point that = (Point)o;
                return this.n == that.n && this.x == that.x && this.y == that.y;
            }
            return false;
        }
        public int hashCode() {
            int hashCode = 17;
            hashCode = hashCode * 31 + n;
            hashCode = hashCode * 31 + (int)(x ^ (x >>> 32));
            hashCode = hashCode * 31 + (int)(y ^ (y >>> 32));
            return hashCode;
        }
        public int compareTo(Point that) {
            if (this.n != that.n) {
                return this.n > that.n ? 1 : -1;
            }
            if (this.x != that.x) {
                return this.x > that.x ? 1 : -1;
            }
            if (this.y != that.y) {
                return this.y > that.y ? 1 : -1;
            }
            return 0;
        }
        public String toString() {
            return n + ":(" + x + ", " + y + ")";
        }
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main{

	public static void main(String[] args){
		new Main().solve();
	}

	int N;
	int []x;
	int []y;

	void solve(){
		Scanner sc=new Scanner(System.in);
		N=sc.nextInt();
		x=new int[N];
		y=new int[N];
		ArrayList<Edge> list=new ArrayList<>();
		int max_weight=0;
		int max=0;

		for(int i=0;i<N;i++){
			x[i]=sc.nextInt();
			y[i]=sc.nextInt();
		}

		for(int i=0;i<N;i++){
			for(int j=i;j<N;j++){
				if(i!=j){
					int w=Math.min(Math.abs(x[i]-x[j]),Math.abs(y[i]-y[j]));
					list.add(new Edge(w,i,j));
					max_weight+=w;
					max+=w;
				}
			}
		}

		Collections.sort(list);
		Collections.reverse(list);

		int ans=Integer.MAX_VALUE;


		for (int i = 0; i < list.size(); i++) {
			// 道iのコストより大きい物だけを使って最小全域木を作ってみる

			if (i > 0 && list.get(i).weight == list.get(i - 1).weight) {
				// もう調べたコストならスルー
				continue;
			}

			PriorityQueue<Edge> priorityQueue = new PriorityQueue<Edge>();
			for (int j = i; j < list.size(); j++) {
				priorityQueue.add(new Edge(list.get(j).weight, list.get(j).from, list.get(j).to));
			}

			UnionFind uf = new UnionFind(N);
			while (!priorityQueue.isEmpty()) {
				Edge e = priorityQueue.poll();
				if (!uf.isSame(e.from, e.to)) {
					max = Math.max(max, e.weight);
					uf.unite(e.from, e.to);
				}
			}

			// 全域木になっているかチェック
			boolean allSame = true;
			for (int j = 1; j < N; j++) {
				if (!uf.isSame(0, j)) {
					allSame = false;
					break;
				}
			}

			// 全域木なら解答を更新
			if (allSame) {
				ans = Math.min(ans, max - list.get(i).weight);
			} else {
				break;
			}
		}

		if (ans == Integer.MAX_VALUE) {
			System.out.println(-1);
		} else {
			System.out.println(max_weight-ans);
		}

	}

	class UnionFind {
		int[] parts;

		UnionFind(int n) {
			parts = new int[n];
			for (int i = 0; i < n; i++)
				parts[i] = i;
		}

		public int find(int x) {
			if (parts[x] == x)
				return x;
			return parts[x] = find(parts[x]);
		}

		public Boolean isSame(int x, int y) {
			return find(x) == find(y);
		}

		public void unite(int x, int y) {
			if (find(x) == find(y))
				return;
			parts[find(x)] = find(y);
		}
	}

	class Edge implements Comparable<Edge> {
		int weight;
		int from, to;

		Edge(int w, int f, int t) {
			this.weight = w;
			this.from = f;
			this.to = t;
		}

		@Override
		public int compareTo(Edge edge) {
			// 昇順
			return this.weight - edge.weight;
		}
	}

}

import java.util.Scanner;
import java.util.Arrays;
import java.util.ArrayList;
import java.util.List;
import java.util.Comparator;
import java.util.PriorityQueue;
public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		Node[] nodes=new Node[n];
		for(int i = 0; i<n; i++){
			nodes[i]=new Node(i,sc.nextInt(),sc.nextInt());
		}
		Arrays.sort(nodes,Comparator.comparingInt(o -> o.x));
		for(int i = 0; i<n-1; i++){
			Node a=nodes[i];
			Node b = nodes[i+1];
			int d=b.x-a.x;
			a.edges.add(new Edge(a,b,d));
			b.edges.add(new Edge(b,a,d));
		}
		Arrays.sort(nodes,Comparator.comparingInt(o -> o.y));
		for(int i = 0; i<n-1; i++){
			Node a = nodes[i];
			Node b = nodes[i+1];
			int d=b.y-a.y;
			a.edges.add(new Edge(a,b,d));
			b.edges.add(new Edge(b,a,d));
		}
		PriorityQueue<Edge> queue=new PriorityQueue<>(Comparator.comparingInt(o ->o.dist));
		Node a=nodes[0];
		queue.addAll(a.edges);
		a.visited=true;
		long d = 0;
		while(!queue.isEmpty()){
			Edge e = queue.poll();
			if(!e.to.visited){
				d+=e.dist;
				e.to.visited=true;
				queue.addAll(e.to.edges);
			}
		}
		System.out.println(d);
	}
	private static class Node{
		final int id;
		final int x;
		final int y;
		final List<Edge> edges=new ArrayList<>();
		boolean visited;
		private Node(int id, int x,int y){
			this.id=id;
			this.x=x;
			this.y=y;
		}
	}

	private static class Edge{
		final Node from;
		final Node to;
		final int dist;

		private Edge(Node from, Node to,int dist){
			this.from=from;
			this.to=to;
			this.dist=dist;
		}
	}
}

