class Kraskal {
	int vnum;
	ArrayList<WEdge2> elist;

	public Kraskal(int vnum){
		this.vnum = vnum;
		elist = new ArrayList<>();
	}

	void addEdge(int u, int v, int w){
		elist.add(new WEdge2(u,v,w));
	}

	//クラスカル法で最小全域木を求める
	ArrayList<WEdge2> KraskalTree(){		
		//UFT
		class UFT{
			int[] par;
			int[] rank;

			public UFT(int n){
				par = new int[n];
				rank = new int[n];

				for(int i=0;i<n;i++){
					par[i] = i;
				}
			}

			//木の根を求める
			public int find(int x){
				if(par[x] == x){
					return x;
				}
				else{
					return par[x] = find(par[x]);
				}
			}

			//xとyの属する集合を併合
			void unite(int x, int y){
				int px = find(x);
				int py = find(y);

				if(px == py){
					return;
				}
				else if(rank[px] < rank[py]){
					par[px] = py;

				}
				else{
					par[py] = px;
					if(rank[px]==rank[py]){
						rank[px]++;
					}
				}

			}

			//xとyが同じ集合に属するか
			boolean isEquivalent(int x, int y){
				return find(x) == find(y);
			}
		}

		ArrayList<WEdge2> s = elist;
		ArrayList<WEdge2> forest = new ArrayList<>();
		Collections.sort(s);
		UFT uft = new UFT(vnum);

		while(!s.isEmpty()){
			WEdge2 now = s.remove(0);

			if(!uft.isEquivalent(now.u,now.v)){
				forest.add(now);
				uft.unite(now.u, now.v);
			}
		}

		return forest;
	}

	//クラスカル法で最小全域木の重みの和を求める
	long KraskalWeight(){		
		//UFT
		class UFT{
			int[] par;
			int[] rank;

			public UFT(int n){
				par = new int[n];
				rank = new int[n];

				for(int i=0;i<n;i++){
					par[i] = i;
				}
			}

			//木の根を求める
			public int find(int x){
				if(par[x] == x){
					return x;
				}
				else{
					return par[x] = find(par[x]);
				}
			}

			//xとyの属する集合を併合
			void unite(int x, int y){
				int px = find(x);
				int py = find(y);

				if(px == py){
					return;
				}
				else if(rank[px] < rank[py]){
					par[px] = py;

				}
				else{
					par[py] = px;
					if(rank[px]==rank[py]){
						rank[px]++;
					}
				}

			}

			//xとyが同じ集合に属するか
			boolean isEquivalent(int x, int y){
				return find(x) == find(y);
			}
		}

		ArrayList<WEdge2> s = elist;
		Collections.sort(s);
		UFT uft = new UFT(vnum);
		long sum = 0;

		while(!s.isEmpty()){
			WEdge2 now = s.remove(0);

			if(!uft.isEquivalent(now.u,now.v)){
				sum += now.w;
				uft.unite(now.u, now.v);
			}
		}

		return sum;
	}

}

