class UnionFind {
    int[] uni;

    UnionFind(int N) {
	uni = new int[N];
	for (int i = 0; i < N; i++) {
	    uni[i] = -1;
	}
    }

    int root(int a) {
	if(uni[a] < 0) return a;
	else return uni[a] = root(uni[a]);
    }

    boolean connect(int a, int b) {
	a = root(a);
	b = root(b);

	if(a == b) return false;
	if(uni[a] > uni[b]) {
	    int tmp = a;
	    a = b;
	    b = tmp;
	}
	uni[a] += uni[b];
	uni[b] = a;
	return true;
    }

}

