public class Main {

    static int N;
    static Cord[] C;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        C = new Cord[N];
        for (int i = 0; i < N; i++) {
            C[i] = new Cord(i, sc.nextInt(), sc.nextInt());
        }
        System.out.println( solve() );
    }

    static class Cord {
        int n;
        int x;
        int y;

        public Cord(int n, int x, int y) {
            this.n = n;
            this.x = x;
            this.y = y;
        }
    }

    private static long solve() {
        UnionFind uf = new UnionFind(N);

        Dist[] D = new Dist[2*(N-1)];
        Arrays.sort(C, Comparator.comparingInt(c -> c.x));
        for (int i = 0; i < N - 1; i++) {
            int j = i+1;
            D[i] = new Dist(C[i], C[j], (C[j].x - C[i].x) );
        }
        Arrays.sort(C, Comparator.comparingInt(c -> c.y));
        for (int i = 0; i < N - 1; i++) {
            int j = i+1;
            D[N+i-1] = new Dist(C[i], C[j], (C[j].y - C[i].y) );
        }
        Arrays.sort(D, Comparator.comparingInt(d -> d.d));

        long total = 0;
        int di = 0;
        f: for (int i = 0; i < N-1; i++) {
            w: while(true) {
                Dist d = D[di];
                boolean u = uf.unite(d.from.n, d.to.n);
                if( u ) {
                    total += d.d;
                    continue f;
                } else {
                    di++;
                    continue w;
                }
            }
        }
        return total;
    }

    static class Dist {
        private Cord from;
        private Cord to;
        private int d;

        public Dist(Cord from, Cord to, int d) {
            this.from = from;
            this.to = to;
            this.d = d;
        }
    }

    static class UnionFind {

        private final int[] parent;
        private final int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public boolean isAllUnite() {
            int root = root(0);
            for (int i = 1; i < N; i++) {
                if( root != root(i) ) return false;
            }
            return true;
        }

        public int root(int i) {
            if( parent[i] == i ) {
                return i;
            } else {
                return parent[i] = root(parent[i]);
            }
        }

        public boolean unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if( ri == rj ) return false;

            if( rank[ri] < rank[rj] ) {
                parent[ri] = rj;

            } else {
                parent[rj] = ri;
                if( rank[ri] == rank[rj] ) {
                    rank[ri]++;
                }
            }
            return true;
        }

        public boolean isSame(int a, int b) {
            return root(a) == root(b);
        }
    }

