public class Main {
  private static long solve(int n, int[] xs, int[] ys) {
    Town[] xTowns = new Town[n];
    Town[] yTowns = new Town[n];
    for (int i = 0; i < n; i++) {
      xTowns[i] = new Town(xs[i], i);
      yTowns[i] = new Town(ys[i], i);
    }
    Arrays.sort(xTowns);
    Arrays.sort(yTowns);

    PriorityQueue<Edge> queue = new PriorityQueue<>();
    for (int i = 1; i < n; i++) {
      queue.add(new Edge(xTowns[i - 1].i, xTowns[i].i, xTowns[i].v - xTowns[i - 1].v));
      queue.add(new Edge(yTowns[i - 1].i, yTowns[i].i, yTowns[i].v - yTowns[i - 1].v));
    }

    long cost = 0;
    UnionFind unionFind = new UnionFind(n);
    while (!queue.isEmpty()) {
      Edge edge = queue.poll();
      if (unionFind.sameGroup(edge.src, edge.dst)) {
        continue;
      }
      cost += edge.cost;
      unionFind.merge(edge.src, edge.dst);
    }
    return cost;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[] xs = new int[n];
    int[] ys = new int[n];
    for (int i = 0; i < n; i++) {
      xs[i] = reader.nextInt();
      ys[i] = reader.nextInt();
    }
    out.println(solve(n, xs, ys));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

