	private void solveD() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		Town[] x = new Town[N];
		Town[] y = new Town[N];
		for (int i = 0; i < N; i++) {
			x[i] = new Town();
			x[i].id = i;
			x[i].val = sc.nextInt() - 1;
			y[i] = new Town();
			y[i].id = i;
			y[i].val = sc.nextInt() - 1;
		}
		Arrays.sort(x, ((o1, o2) -> o1.val - o2.val));
		Arrays.sort(y, ((o1, o2) -> o1.val - o2.val));
		Edge[] edges = new Edge[2 * N - 2];
		for (int i = 1; i < N; i++) {
			int current_id = i - 1;
			edges[current_id * 2] = new Edge();
			edges[current_id * 2 + 1] = new Edge();
			edges[current_id * 2].id1 = x[i - 1].id;
			edges[current_id * 2].id2 = x[i].id;
			edges[current_id * 2].val = x[i].val - x[i - 1].val;
			edges[current_id * 2 + 1].id1 = y[i - 1].id;
			edges[current_id * 2 + 1].id2 = y[i].id;
			edges[current_id * 2 + 1].val = y[i].val - y[i - 1].val;
		}

		Arrays.sort(edges, (o1, o2) -> o1.val - o2.val);
		UnionFind uf = new ArrayUnionFind(N + 1);
		int ans = 0;
		for (Edge e : edges) {
			if (!uf.judge(e.id1, e.id2)) {
				uf.union(e.id1, e.id2);
				ans += e.val;
			}
		}
