//        for (int i = 2; i <= n; i++)
//        {
//            Fa[i] = (Fa[i - 1] * i) % MOD;
//        }
        //
        for (int i = 2; i <= 100000; i++)
        {
            Fa[i] = (Fa[i - 1] * i) % MOD;
        }
        for (int i = 100001; i <= n; i++)
        {
            Fa[i] = (Fa[i - 1] * i) % MOD;
        }
    }

    static long modPow(long x, long n)
    {
        long res = 1L;
        while (n > 0)
        {
            if ((n & 1) == 1)
            {
                res = res * x % MOD;
            }
            x = x * x % MOD;
            n >>= 1;
        }
        return res;
    }

