import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class Main {

	public static void main(String args[]) {
		FastScanner cin = new FastScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	private static void solve(FastScanner cin, PrintWriter cout) {
		int n = cin.nextInt();
		int[][] xys = new int[n][];
		for (int i = 0; i < n; i++)
			xys[i] = new int[] { cin.nextInt(), cin.nextInt() };

		long ans = solve(n, xys);
		cout.println(ans);
	}

	private static long solve(int n, int[][] xys) {
		long ans = 0;
		// ダイクストラ法
		int[] vis = new int[n];
		PriorityQueue<long[]> ctfs = new PriorityQueue<>((cxy1, cxy2) -> {
			int cmp = Long.compare(cxy1[0], cxy2[0]);
			// TODO 途中経路で同一コストの時に何を優先するか？仮に通過ノード数にしているが、妥当か不明
			if (cmp == 0)
				cmp = Long.compare(cxy2[3], cxy1[3]);
			return cmp;
		});

		ctfs.add(new long[] { 0, 0, 0, 1 });
		while (!ctfs.isEmpty()) {
			long[] ctf = ctfs.remove();
			long c = ctf[0];
			int to = (int) ctf[1];
			int fr = (int) ctf[2];
			int passed = (int) ctf[3];
			// popした時点で、そのノードに到達する最短コストは確定
			if (vis[to] == 1)
				continue;
			vis[to] = 1;
			ans += dist(xys[to][0], xys[to][1], xys[fr][0], xys[fr][1]);

			for (int i = 0; i < n; i++) {
				if (vis[i] == 1)
					continue;
				long nc = c + dist(xys[to][0], xys[to][1], xys[i][0], xys[i][1]);
				ctfs.add(new long[] { nc, i, to, passed + 1 });
			}
		}
		return ans;
	}

	private static long dist(long frx, long fry, long tox, long toy) {
		return Math.min(Math.abs(tox - frx), Math.abs(toy - fry));
	};

	/**
	 * How to read input in Java — tutorial <br />
	 * By Flatfoot<br />
	 * http://codeforces.com/blog/entry/7018
	 */
	static class FastScanner {
		private BufferedReader br;
		private StringTokenizer st;

		FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements())
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new IllegalStateException(e);
				}
			return st.nextToken();
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				throw new IllegalStateException(e);
			}
			return str;
		}

		long nextLong() {
			return Long.parseLong(next());
		}
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Objects;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

class Main{
	public static void main(String[] args) {
		SC sc=new SC(System.in);
		int N=sc.nextInt();
		long[][] xs=new long[N][2];
		long[][] ys=new long[N][2];
		Vertex[] graph=new Vertex[N];
		for(int i=0; i<N; i++) {
			graph[i]=new Vertex();
		}
		for(int i=0; i<N; i++) {
			long x=sc.nextInt();
			long y=sc.nextInt();
			xs[i][0]=x;
			xs[i][1]=i;
			ys[i][0]=y;
			ys[i][1]=i;
		}
		quick_sort(xs,0,N-1);
		quick_sort(ys,0,N-1);
		for(int i=1; i<N; i++) {
			graph[(int) xs[i-1][1]].add((int)xs[i][1],xs[i][0]-xs[i-1][0]);
			graph[(int) xs[i][1]].add((int)xs[i-1][1],xs[i][0]-xs[i-1][0]);
			graph[(int) ys[i-1][1]].add((int)ys[i][1],ys[i][0]-ys[i-1][0]);
			graph[(int) ys[i][1]].add((int)ys[i-1][1],ys[i][0]-ys[i-1][0]);
		}
		long total=0;
		PriorityQueue<Pair<Integer,Long>> Q=new PriorityQueue<Pair<Integer,Long>>(Comparator.comparing(v -> v.value));
		Q.add(new Pair<Integer,Long>(0,0L));
		boolean[] use=new boolean[N];
		while(!Q.isEmpty()) {
			Pair<Integer,Long> tmp=Q.poll();
			if(use[tmp.key]) {
				continue;
			}
			else {
				use[tmp.key]=true;
				total+=tmp.value;
				for(int i=0; i<graph[tmp.key].size(); i++) {
					Q.add(graph[tmp.key].get(i));
				}
			}
		}
		pl(total);
	}
	static class SC {
