    void solve() {
        List<List<Pair>> mst = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            mst.add(new LinkedList<>());
        }
        boolean[] visited = new boolean[n];
        PriorityQueue<Edge> pQueue = new PriorityQueue<>();
        for (int i = 1; i < n; i++) {
            pQueue.offer(new Edge(0, i, Math.min(Math.abs(xs[0] - xs[i]),
                    Math.abs(ys[0] - ys[i]))));
        }
        visited[0] = true;
        int cost = 0;
        while (!pQueue.isEmpty()) {
            Edge e = pQueue.poll();
            if (visited[e.to]) {
                continue;
            }
            visited[e.to] = true;
            //mst.get(e.from).add(new Pair(e.to, e.cost));
            cost += e.cost;
            for (int i = 0; i < n; i++) {
                if (i == e.to) {
                    continue;
                }
                pQueue.offer(new Edge(e.to, i, Math.min(Math.abs(xs[e.to] - xs[i]),
                        Math.abs(ys[e.to] - ys[i]))));
            }
        }
        System.out.println(cost);
    }

    class Prim {
        List<List<Pair>> graph;
        List<List<Pair>> mst;
        long mstCost;
        boolean[] visited;

        Prim(int[] froms, int[] tos, long[] costs, int numVertex) {
            graph = new ArrayList<>();
            for (int i = 0; i < numVertex; i++) {
                graph.add(new LinkedList<>());
            }
            for (int i = 0; i < froms.length; i++) {
                graph.get(froms[i]).add(new Pair(tos[i], costs[i]));
                graph.get(tos[i]).add(new Pair(froms[i], costs[i]));
            }
            visited = new boolean[numVertex];
        }

        long minimumSpanningTree(int start) {
            long cost = 0;
            mst = new ArrayList<>();
            for (int i = 0; i < graph.size(); i++) {
                mst.add(new LinkedList<>());
            }
            visited[start] = true;
            PriorityQueue<Edge> pQueue = new PriorityQueue<>();
            for (Pair e : graph.get(start)) {
                pQueue.offer(new Edge(start, e.vertex, e.cost));
            }
            while (true) {
                if (pQueue.isEmpty()) {
                    break;
                }
                Edge e = pQueue.poll();
                if (visited[e.to]) {
                    continue;
                }
                visited[e.to] = true;
                mst.get(e.from).add(new Pair(e.to, e.cost));
                cost += e.cost;
            }
            mstCost = cost;
            return cost;
        }
    }

    class Pair implements Comparable<Pair>{
        int vertex;
        long cost;

        Pair(int vertex, long cost) {
            this.vertex = vertex;
            this.cost = cost;
        }

        public int compareTo(Pair p) {
            if (cost == p.cost) {
                return 0;
            } else {
                return cost < p.cost ? -1 : 1;
            }
        }
    }

    class Edge implements Comparable<Edge>{
        int from;
        int to;
        long cost;

        Edge(int from, int to, long cost) {
            this.from = from;
            this.to = to;
            this.cost = cost;
        }

        public int compareTo(Edge p) {
            if (cost == p.cost) {
                return 0;
            } else {
                return cost < p.cost ? -1 : 1;
            }
        }
    }

