	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int n = in.nextInt();
			P[] p = new P[n];
			for (int i = 0; i < n; i++) {
				int x = in.nextInt(), y = in.nextInt();
				p[i] = new P(i, x, y);
			}

			List<T> list = new ArrayList<>();

			Arrays.sort(p, (p1, p2) -> p1.x - p2.x);
			for (int i = 0; i < n-1; i++) {
				list.add(new T(p[i+1].idx, p[i].idx, p[i+1].x - p[i].x));
			}

			Arrays.sort(p, (p1, p2) -> p1.y - p2.y);
			for (int i = 0; i < n-1; i++) {
				list.add(new T(p[i+1].idx, p[i].idx, p[i+1].y - p[i].y));
			}

			Collections.sort(list);

			long ans = 0;
			UnionFind uf = new UnionFind(2 * n);
			for (int i = 0; i < list.size(); i++) {
				if (uf.same(list.get(i).s, list.get(i).t)) continue;
				uf.union(list.get(i).s, list.get(i).t);
				ans += list.get(i).w;
			}

			out.println(ans);
		}

		class P {
			int idx, x, y;

			public P(int idx, int x, int y) {
				super();
				this.idx = idx;
				this.x = x;
				this.y = y;
			}


			@Override
			public String toString() {
				return "P [x=" + x + ", y=" + y + "]";
			}
		}

		class T implements Comparable<T> {
			int s, t;
			long w;
			public T(int s, int t, long w) {
				super();
				this.s = s;
				this.t = t;
				this.w = w;
			}
			@Override
			public String toString() {
				return "Edge [s=" + s + ", t=" + t + ", w=" + w + "]";
			}

			@Override
			public int compareTo(T o) {
				return Long.compare(this.w, o.w);
			}
		}
	}

	static class UnionFind {
		int[] data;

		public UnionFind(int size) {
			data = new int[size];
			clear();
		}

		public void clear() {
			Arrays.fill(data, -1);
		}

		public int root(int x) {
			return data[x] < 0 ? x : (data[x] = root(data[x]));
		}

		public void union(int x, int y) {
			x = root(x);
			y = root(y);

			if (x != y) {
				if (data[y] > data[x]) {
					final int t = x;
					x = y;
					y = t;
				}

				data[x] += data[y];
				data[y] = x;
			}
		}

		boolean same(int x, int y) {
			return root(x) == root(y);
		}

		public int size(int x) {
			return -data[root(x)];
		}
	}

