public void solve() {
	int num = ni();
	long p[][] = new long[num][3];
	for(int i = 0; i < num; i ++) {
		p[i][0] = nl() - 1;
		p[i][1] = nl() - 1;
		p[i][2] = i;
	}
	List<Edge> edgesList = new ArrayList<>();
	Arrays.sort(p, (sort1, sort2) -> Long.compare(sort1[0], sort2[0]));
	for(int i = 0; i < num - 1; i ++) {
		edgesList.add(new Edge((int)p[i][2], (int)p[i + 1][2], min(abs(p[i][0] - p[i + 1][0]), abs(p[i][1] - p[i + 1][1]))));
	}
	Arrays.sort(p, (sort1, sort2) -> Long.compare(sort1[1], sort2[1]));
	for(int i = 0; i < num - 1; i ++) {
		edgesList.add(new Edge((int)p[i][2], (int)p[i + 1][2], min(abs(p[i][0] - p[i + 1][0]), abs(p[i][1] - p[i + 1][1]))));
	}
	Arrays.sort(p, (sort1, sort2) -> Long.compare(sort1[2], sort2[2]));
	int numEdge = edgesList.size();
	Edge edges[] = new Edge[numEdge];
	for(int i = 0; i < numEdge; i ++) {
		edges[i] = edgesList.get(i);
	}
	prtln(kruskal(num, edges));
}

long kruskal(int numNode, Edge[] edges) { // O(ElogE)=O(ElogV)
	UnionFind uf = new UnionFind(numNode);
	Queue<Edge> pq = new PriorityQueue<Edge>();
	for(Edge e : edges) {
		if(!isINF((long)e.cost)) { pq.add(e); }
	}

	long cost = 0;
	while (!pq.isEmpty()) {
		Edge e = pq.poll();
		if (!uf.same(e.source, e.target)) {
			cost += e.cost;
			uf.unite(e.source, e.target);
		}
	}

	return cost;
}

class UnionFind {
	int parent[];
	int size[];

	public UnionFind(int num) {
		parent = new int[num];
		size = new int[num];
		for(int i = 0; i < num; i ++) {
			initNode(i);
		}
	}

	public void initNode(int i) {
		parent[i] = i;
		size[i] = 1;
	}

	public void unite(int x, int y) {
		int xRoot = root(x);
		int yRoot = root(y);
		if(xRoot == yRoot) { return; }
		if(size[yRoot] > size[xRoot]) {
			parent[xRoot] = yRoot;
			size[yRoot] += size[xRoot];
		}else {
			parent[yRoot] = xRoot;
			size[xRoot] += size[yRoot];
		}
	}

	public int size(int i) {
		return size[root(i)];
	}

	public int root(int i) {
		if(i != parent[i]) {
			parent[i] = root(parent[i]);
		}
		return parent[i];
	}

	public boolean same(int x, int y) {
		return root(x) == root(y);
	}
}

	}
}

