namespace AtCoder.Beginner065
{
    public class ABC065D_Built
    {
        public static void Main(string[] args)
        {
            // 街の数の入力
            int n = int.Parse(Console.ReadLine());

            // 街の座標の入力
            int[][] cityPos = new int[n+1][];
            for(int i = 1; i <= n; i++)
            {
                cityPos[i] = new int[2];
                cityPos[i] = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            }


            // 街番号－街番号の道路コスト
            int[][] roadCost = new int[n + 1][];
            for(int i = 1; i <= n; i++)
            {
                roadCost[i] = new int[n + 1];
                for(int j = 1; j <= n; j++)
                {
                    int xDif = Math.Abs(cityPos[i][0] - cityPos[j][0]);
                    int yDif = Math.Abs(cityPos[i][1] - cityPos[j][1]);
                    roadCost[i][j] = Math.Min(xDif, yDif);
                }
            }


            int[] totalRoadCost = new int[n + 1];
            for(int i = 1; i <= n; i++)
            {
                totalRoadCost[i] = int.MaxValue;
            }
            totalRoadCost[1] = 0;

            int[] calcRoadCost = new int[n + 1];
            for(int cnt=1; cnt < n; cnt++)
            {
                int minCityA = 0;
                int minCityB = 0;
                int minRoadCost = int.MaxValue;

                for(int i=1; i <= n; i++)
                {
                    for(int j = 1; j <= n; j++)
                    {
                        if( i != j )
                        {
                            if(totalRoadCost[i] != int.MaxValue &&
                               totalRoadCost[j] == int.MaxValue &&
                               roadCost[i][j] < minRoadCost )
                            {
                                minCityA = i;
                                minCityB = j;
                                minRoadCost = roadCost[i][j];
                            }
                        }
                    }
                }
                totalRoadCost[minCityB] = totalRoadCost[minCityA] + roadCost[minCityA][minCityB];
                calcRoadCost[minCityB] = roadCost[minCityA][minCityB];
            }


            // 結果出力
            Console.WriteLine(calcRoadCost.Sum());


        }

    }
}

