    private object Calc()
    {
        var N = cr.Int;
        var gb = new WGraphBuilder(N, false);
        int ii = 0;
        var points = cr.Repeat(N).Select(cr => new Point { index = ii++, x = cr.Int, y = cr.Int }).Sort(p => p.x);
        for (int i = 1; i < points.Length; i++)
            gb.Add(points[i].index, points[i - 1].index, points[i].x - points[i - 1].x);
        points.Sort(p => p.y);
        for (int i = 1; i < points.Length; i++)
            gb.Add(points[i].index, points[i - 1].index, points[i].y - points[i - 1].y);
        return gb.ToArray().Prim().SelectMany(node => node.children).Sum(nx => (long)nx.value) / 2;
