namespace AtCoder.ABC065
{
    class Program
    {
        static int[] parent;
        static void Main()
        {
            int n = int.Parse(Console.ReadLine());
            int[] x = new int[n];
            int[] y = new int[n];
            for (int i = 0; i < n; i++)
            {
                string[] inputs = Console.ReadLine().Split(' ');
                x[i] = int.Parse(inputs[0]);
                y[i] = int.Parse(inputs[1]);
            }
            var sortedX = x.Select((elem, idx) => new { Value = elem, Index = idx })
                            .OrderBy(elem => elem.Value)
                            .ToArray();
            var sortedY = y.Select((elem, idx) => new { Value = elem, Index = idx })
                            .OrderBy(elem => elem.Value)
                            .ToArray();
            Edge[] edges = new Edge[2 * (n - 1)];
            int k = 0;
            for (int i = 1; i < n; i++)
            {
                edges[k++] = new Edge(sortedX[i - 1].Index, sortedX[i].Index, sortedX[i].Value - sortedX[i - 1].Value);
                edges[k++] = new Edge(sortedY[i - 1].Index, sortedY[i].Index, sortedY[i].Value - sortedY[i - 1].Value);
            }
            // Console.Error.WriteLine(edges.Length);
            // foreach (Edge elem in edges) Console.Error.WriteLine(elem.Cost);
            Array.Sort(edges);
            parent = Enumerable.Range(0, n).ToArray();
            int totalCost = 0;
            for (int i = 0; i < k; i++)
            {
                if (Root(edges[i].NodeId1) != Root(edges[i].NodeId2))
                {
                    totalCost += edges[i].Cost;
                    Console.Error.WriteLine("{0}:{1} - {2}:{3}", parent[edges[i].NodeId1], edges[i].NodeId1, parent[edges[i].NodeId2], edges[i].NodeId2);
                    int theirRoot = Math.Min(Root(edges[i].NodeId1), Root(edges[i].NodeId2));
                    parent[edges[i].NodeId1] = theirRoot;
                    parent[edges[i].NodeId2] = theirRoot;
                    Console.Error.WriteLine("total cost = {0} <- {1}", totalCost, edges[i].Cost);
                }
            }
            Console.WriteLine(totalCost);
        }

        static int Root(int id)
        {
            return parent[id] == id ? id : parent[id] = Root(parent[id]);
        }
    }

    class Edge : IComparable
    {
        public int NodeId1 { get; }
        public int NodeId2 { get; }
        public int Cost { get; }
        public Edge(int id1, int id2, int cost)
        {
            NodeId1 = id1;
            NodeId2 = id2;
            Cost = cost;
        }
        public int CompareTo(Object obj)
        {
            return this.Cost.CompareTo(((Edge)obj).Cost);
        }
    }
}

