class UnionFind
{
    int[] data;
    public UnionFind(int size)
    {
        this.data = NewArray(size, -1);
    }

    public int Root(int x)
    {
        if (data[x] < 0) return x;
        return data[x] = Root(data[x]);
    }
    public int Count(int x) => -data[Root(x)];
    public void UnionSet(int x, int y) => TryUnionSet(x, y);
    public bool TryUnionSet(int x, int y)
    {
        var xRoot = Root(x);
        var yRoot = Root(y);
        if (xRoot == yRoot) return false;
        else if (data[yRoot] < data[xRoot])//y側の方が多い場合は逆にする
        {
            var tmp = yRoot;
            yRoot = xRoot;
            xRoot = tmp;
        }
        data[xRoot] += data[yRoot];
        data[yRoot] = xRoot;
        return true;
    }
    public bool IsSameSet(int x, int y) => Root(x) == Root(y);
}

using System;
class Program
{
static int n = int.Parse(Console.ReadLine());//int.Parseは文字列を整数に変換。
static int[] parents = new int[n];//親

	static void Main()
	{
  long answer = 0;
  int[][] costs = new int[2*(n-1)];//２頂点と距離
  int[][] vertexes = new int[n][];//ここに受け取る
    for(int i = 0; i < n; i++)
    {
    int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);//１行ごとに受け取る
    vertexes[i] = new int[]{i,nums[0],nums[1]};//頂点の座標をジャグ配列へ
    }
    Array.Sort(vertexes, (a, b) => a[1] - b[1]);//x座標の昇順に並べる
    for(int i = 0; i < n-1; i++)
    {
    costs[i] = new int{vertexes[i][0],vertexes[i+1][0],
      vertexes[i+1][1] - vertexes[i][1]};
    }

    Array.Sort(vertexes, (a, b) => a[2] - b[2]);//y座標の昇順に並べる
    for(int i = n; i < 2*(n-1); i++)
    {
    costs[i] = new int{vertexes[i][0],vertexes[i+1][0],
      vertexes[i+1][2] - vertexes[i][2]};
    }

    Array.Sort(costs, (a, b) => a[2] - b[2]);//コストの昇順に並べる

    for(int i = 1; i < n; i++)//個体の結合
    {
    parents[i] = i;
    }

    for(int i = 0; i < costs.Length; i++)
    {
      int check = n-1;//頂点数だけ確認
        if(whatParent(costs[i][0]) != whatParent(costs[i][1]))
        {
          parents[costs[i][0]] = whatParent(costs[i][1]);//親の統一
          answer += costs[i][2];
          check--;
          if(check == 0) break;
        }

    }

	Console.WriteLine(answer);//WriteLineをWriteとすると、改行なしで出力。
	}

  static int whatParent(int child)
  {
    if(parents[child] == child) return child;
    else return parents[child] = whatParent(parents[child]);
  }

}

