class Program
{
    class P:IComparable<P>
    {
        public int index;
        public long Weight;
        public List<int> adj;
        public Dictionary<int, long> weights;
        public P(int index)
        {
            this.index = index;
            adj = new List<int>();
            weights = new Dictionary<int,long>();
            Weight = long.MaxValue;
        }
        public int CompareTo(P p)
            => Weight.CompareTo(p.Weight);
    }
    static void Main(string[] args)
    {
        var num = Input.num;
        var xy = Enumerable.Range(0, num).Select(v => new KeyValuePair<int,int[]>(v,Input.ar)).ToArray(); 
        var ps = Enumerable.Range(0, num).Select(v => new P(v)).ToArray();
        for (var k = 0; k < 2; k++)
        {
            xy = xy.OrderBy(pair => pair.Value[k]).ToArray();
            for (var i = 1; i < num; i++)
                for (var j = 0; j < 2; j++)
                {
                    ps[xy[i - j].Key].adj.Add(xy[i + j - 1].Key);
                    ps[xy[i - j].Key].weights[xy[i + j - 1].Key] = Min(ps[xy[i - j].Key].weights.ContainsKey(xy[i + j - 1].Key) ? ps[xy[i - j].Key].weights[xy[i + j - 1].Key] : long.MaxValue, xy[i].Value[k] - xy[i - 1].Value[k]);
                }
        }
        var pQue = new PriorityQueue<P>(false, new P(-1));
        ps[0].Weight = 0;
        pQue.Enqueue(ps[0]);
        var bo = new bool[num];
        while (!pQue.isEmpty)
        {
            var u = pQue.Dequeue();
            bo[u.index] = true;
            foreach (var ad in u.adj)
                if (!bo[ad] && ps[ad].Weight > u.weights[ad])
                {
                    ps[ad].Weight = u.weights[ad];
                    pQue.Enqueue(ps[ad]);
                }
        }
        WriteLine(ps.Sum(p => p.Weight));
    }
}

