        List<int[]> citys = new List<int[]>();
        for (int i = 0; i < N; i++)
        {
            int xi = NextInt();
            int yi = NextInt();
            citys.Add(new int[3] { i, xi, yi });
        }
        var x_city = citys.OrderBy(v => v[1]).ToList();
        var y_city = citys.OrderBy(v => v[2]).ToList();
        PriorityQueue<int, int[]> e = new PriorityQueue<int, int[]>();
        //座標でソート、近い場所以外の道を建設するのはあうと
        //PQ(長さ,(都市A,都市B))
        for (int i = 1; i < N; i++)
        {
