            int[] listY = new int[num];
            bool[] flag = new bool[num];

            int[] cacheCost = new int[num];
            int[] cacheTarget = new int[num];
            List<int> already = new List<int>();
            for (int i = 0; i < num; ++i)
            {
                string[] input = Console.ReadLine().Split(' ');
                listX[i] = int.Parse(input[0]);
                listY[i] = int.Parse(input[1]);
                flag[i] = false;
                cacheCost[i] = -1;
            }
            int costs = 0;

            already.Add(0);
            flag[0] = true;
            for (int l = 0; l < num - 1; l++)
            {
                int mincost = 1000000001;
                int mintarget = 0;
                for (int i = 0; i < already.Count; ++i)
                {
                    if( cacheCost[already[i]] != -1 && !flag[cacheTarget[already[i]]])
                    {
                        if (mincost > cacheCost[already[i]])
                        {
                            mincost = cacheCost[already[i]];
                            mintarget = cacheTarget[already[i]];                            
                        }
                        continue;
                    }
                    int thismincost = 1000000001;
                    int thismintarget = 0;
                    if (mincost == 0)
                    {
                        break;
                    }
                    for (int target = 0; target < num; ++target)
                    {
                        if (flag[target])
                        {
                            continue;
                        }
                        int temp = System.Math.Min(Math.Abs(listX[already[i]] - listX[target]), Math.Abs(listY[already[i]] - listY[target]));
                        if (mincost > temp)
                        {
                            mincost = temp;
                            mintarget = target;
                        }
                        if(thismincost > temp)
                        {
                            thismincost = temp;
                            thismintarget = target;
                        }
                    }
                    cacheCost[already[i]] = thismincost;
                    cacheTarget[already[i]] = thismintarget;
                }
                costs += mincost;
                already.Add(mintarget);
                flag[mintarget] = true;
            }
            Console.WriteLine(costs);
        }
    }
}

