            for (int i = 0; i < n; i++)
            {
                int[] x = Console.ReadLine().Split().Select(int.Parse).ToArray();
                city[i, 0] = x[0]; city[i, 1] = x[1];
            }
            long ret = 0;
            bool[] visit = new bool[n];
