        {
            int[] IdxToGroup = new int[NodesNum];
            List<int>[] GroupToIdx = new List<int>[NodesNum];
            for (int i = 0; i < NodesNum; ++i)
            {
                IdxToGroup[i] = i;
                GroupToIdx[i] = new List<int>();
