			g.Add(new VT<int, int, int>(k,l,s.Value));
		}

		VT<int,int,int>[] o;
		long r = Kruskal(g.ToArray(), n, out o);

		MyIO.WriteMulti(r);

	}




	public static long Kruskal(VT<int,int,int>[] inEdges, int V, out VT<int,int,int>[] outEdges) {
		Array.Sort(inEdges, (x,y)=>(x.Item3.CompareTo(y.Item3)));
		UnionFind tree = new UnionFind(V);
		long ret = 0;
		List<VT<int,int,int>> oedge = new List<VT<int, int, int>>();
		foreach(var e in inEdges) {
			if(tree.Unite(e.Item1, e.Item2)) {
				ret += e.Item3;
				oedge.Add(e);
			}
		}
		outEdges = oedge.ToArray();
