            flag[0] = true;
            for (int l = 0; l < num - 1; l++)
            {
                int mincost = 1000000001;
                int mintarget = 0;
                for (int i = 0; i < already.Count; ++i)
                {
                    if( cacheCost[already[i]] != -1 && !flag[cacheTarget[already[i]]])
                    {
                        if (mincost > cacheCost[already[i]])
                        {
                            mincost = cacheCost[already[i]];
                            mintarget = cacheTarget[already[i]];                            
                        }
                        continue;
                    }
                    if (cacheSecondBestCost[already[i]] != -1 && !flag[cacheSecondBestTarget[already[i]]])
                    {
                        if (mincost > cacheSecondBestCost[already[i]])
                        {
                            mincost = cacheSecondBestCost[already[i]];
                            mintarget = cacheSecondBestTarget[already[i]];
                        }
                        continue;
                    }
                    int thismincost = 1000000001;
                    int thismintarget = 0;
                    int thismincost2 = 1000000001;
                    int thismintarget2 = -1;
                    if (mincost == 0)
                    {
                        break;
                    }
                    for (int target = 0; target < num; ++target)
                    {
                        if (flag[target])
                        {
                            continue;
                        }
                        int temp = System.Math.Min(Math.Abs(listX[already[i]] - listX[target]), Math.Abs(listY[already[i]] - listY[target]));
                        if (mincost > temp)
                        {
                            mincost = temp;
                            mintarget = target;
                        }
                        if(thismincost > temp)
                        {
                            thismincost2 = thismincost;
                            thismintarget2 = thismintarget;
                            thismincost = temp;
                            thismintarget = target;                            
                        }
