namespace ConsoleApp15
{
    class Class174
    {
        struct edge { public long to, cost; }
        static void Main()
        {
            int N = int.Parse(Console.ReadLine());
            List<Tuple<int, long>> x = new List<Tuple<int, long>>(N);
            List<Tuple<int, long>> y = new List<Tuple<int, long>>(N);
            for(int i = 0; i < N; i++)
            {
                var r = Console.ReadLine().Split().Select(long.Parse).ToArray();
                x.Add(Tuple.Create(i, r[0]));
                y.Add(Tuple.Create(i, r[1]));
            }
            x = x.OrderBy(a => a.Item2).ToList();
            y = y.OrderBy(a => a.Item2).ToList();

            var G = new List<edge>[N];
            for (int i = 0; i < N; i++) G[i] = new List<edge>();
            for(int i = 0; i < N-1; i++)
            {
                G[x[i].Item1].Add(new edge { to = x[i + 1].Item1, cost = Math.Abs(x[i].Item2 - x[i + 1].Item2) });
                G[x[i + 1].Item1].Add(new edge { to = x[i].Item1, cost = Math.Abs(x[i].Item2 - x[i + 1].Item2) });

                G[y[i].Item1].Add(new edge { to = y[i + 1].Item1, cost = Math.Abs(y[i].Item2 - y[i + 1].Item2) });
                G[y[i + 1].Item1].Add(new edge { to = y[i].Item1, cost = Math.Abs(y[i].Item2 - y[i + 1].Item2) });
            }
            long[] d = Enumerable.Repeat(100000000000, N).ToArray();
            d[0] = 0;
            bool[] used = new bool[N];
            used[0] = true;
            var que = new PriorityQueue<Tuple<long, long>>(3 * N, (a,b)=>a.Item1.CompareTo(b.Item1 ));
            que.Push(Tuple.Create(0L, 0L));

            while (que.Size > 0)
            {
                var p = que.Pop();
                var v = p.Item2;
                if (d[v] < p.Item1) continue;

                used[v] = true;
                for(int i = 0; i < G[v].Count; i++)
                {
                    var e = G[v][i];
                    if(d[e.to]>e.cost&&!used[e.to])
                    {
                        d[e.to] = e.cost;
                        que.Push(Tuple.Create(d[e.to], e.to));
                    }
                }
            }

            Console.WriteLine(d.Sum());
        }
    }
    public class PriorityQueue<T>
    {
        public long Size { get; private set; } = 0;
        public long MaxSize { get; private set; } = 0;
        private T[] m_heap;
        private Comparison<T> Comp = null;

        public PriorityQueue(long maxSize, Comparison<T> comp)
        {
            if (maxSize <= 0)
                throw new Exception();
            MaxSize = maxSize;
            m_heap = new T[maxSize];

            Comp = comp;
        }

        public void Push(T x)
        {
            if (Size == MaxSize)
            {
                T[] new_heap = new T[MaxSize << 1];
                Array.Copy(m_heap, new_heap, MaxSize);
                m_heap = new_heap;
                MaxSize <<= 1;
            }

            long i = Size++;
            while (i > 0)
            {
                long p = (i - 1) / 2;
                if (Comp(m_heap[p], x) <= 0)
                    break;
                m_heap[i] = m_heap[p];
                i = p;
            }
            m_heap[i] = x;
        }

        public T Pop()
        {
            if (Size == 0)
                throw new Exception("Queue is empty.");

            T result = m_heap[0];
            T x = m_heap[--Size];
            long i = 0;
            while (i * 2 + 1 < Size)
            {
                long c1 = i * 2 + 1, c2 = i * 2 + 2;
                if (c2 < Size && Comp(m_heap[c2], m_heap[c1]) < 0)
                    c1 = c2;
                if (Comp(m_heap[c1], x) >= 0)
                    break;
                m_heap[i] = m_heap[c1];
                i = c1;
            }
            m_heap[i] = x;

            return result;
        }
    }
}

using System;
using System.Collections;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Threading.Tasks;

class Program
{
	static int N;
	static long[][] coord;
	static long[][] xDist;
	static long[][] yDist;
	static long[][] distArr;
	static int[] unionFind;

	//camparer1
	static int CompareX(long[] a, long[] b)
  {
    long xa = a[0];
		long xb = b[0];

    if (xa > xb){
			return 1;
		}
    else if(xa < xb){
      return -1;
		}
    else{
			return 0;
		}
  }

	//camparer2
	static int CompareY(long[] a, long[] b)
	{
		long ya = a[1];
		long yb = b[1];

		if (ya > yb){
			return 1;
		}
		else if(ya < yb){
			return -1;
		}
		else{
			return 0;
		}
	}

	//unionFindへの追加
	//ここでは、a<bで渡されることを前提とする
	static void MergeUF(int a, int b){
		//根を決定
		int rootA = FindRoot(a);
		int rootB = FindRoot(b);
		int newRoot = Math.Min(rootA, rootB);

		//根を変化させる
		unionFind[rootA] = newRoot;
		unionFind[rootB] = newRoot;
	}

	static int FindRoot(int ind){
		int root = 0;

		if(unionFind[ind] == ind){
				root = ind;
		}else{
				root = FindRoot(unionFind[ind]);
		}

		return unionFind[ind] = root;
	}

	//Main
	static void Main(string[] args)
	{
		//読み込む
		N = int.Parse(Console.ReadLine());
		coord = new long[N][];

		for(long i=0; i<N; i++){
				string[] line = Console.ReadLine().Split(' ');
				//それぞれ、x座標、y座標、町の番号（インデックス）、を格納
				coord[i] = new long[3];
				coord[i][0] = long.Parse(line[0]);
				coord[i][1] = long.Parse(line[1]);
				coord[i][2] = (long)i;
		}

		//1. x座標の最小距離を格納した配列
		//まず、x座標でソート
		Array.Sort(coord, CompareX);

		//x座標の距離を取得し、配列に格納していく
		xDist = new long[N-1][];
		for(int i=0; i<N-1; i++){
				//距離
				long dist = coord[i+1][0] - coord[i][0];

				//町番号（小さい順）
				long minC = Math.Min(coord[i][2], coord[i+1][2]);
				long maxC = Math.Max(coord[i][2], coord[i+1][2]);

				//距離、町番号1、町番号2の順に格納
				xDist[i] = new long[3];
				xDist[i][0] = dist;
				xDist[i][1] = minC;
				xDist[i][2] = maxC;
		}

		//2. y座標の最小距離を格納した配列
		//まず、y座標でソート
		Array.Sort(coord, CompareY);

		//y座標の距離を取得し、配列に格納していく
		yDist = new long[N-1][];
		for(int i=0; i<N-1; i++){
				//距離
				long dist = coord[i+1][1] - coord[i][1];

				//町番号（小さい順）
				long minC = Math.Min(coord[i][2], coord[i+1][2]);
				long maxC = Math.Max(coord[i][2], coord[i+1][2]);

				//距離、町番号1、町番号2の順に格納
				yDist[i] = new long[3];
				yDist[i][0] = dist;
				yDist[i][1] = minC;
				yDist[i][2] = maxC;
		}

		//両者を結合
		distArr = new long[2*N-2][];
		for(int i=0; i<N-1; i++){
				distArr[i] = xDist[i];
		}
		for(int i=0; i<N-1; i++){
				distArr[i+N-1] = yDist[i];
		}

		//距離でソート
		Array.Sort(distArr, CompareX);

		/*
		ここまでで、重みの低い順に枝（頂点の組み合わせ）を並べ替えることは完了。
		後は、閉区間を弾ければ終了。
		（基本的に小さい順に重みを足していくが、
		同じ頂点同士を結んでいたり、或いは閉区間の場合には、スキップする必要）
		*/

		//unionFindの初期化
		unionFind = new int[N];
		for(int i=0; i<N; i++){
			unionFind[i] = i;
		}

		/*
		To do!!!
		UnionFindを理解し直し、新たな辺を付け加える際の根の更新関数を完成させよう！！
		（MergeUF関数）
		それができれば、後はwhileのループ処理内部を完成させるだけ。
		*/

		//最小全域木を結ぶ辺の数はN-1本である。
		long cnt = 0;
		long min = 0;
		int j = 0;

		while(cnt < N-1){
			//閉区間やダブリ（既に結ばれた辺）の場合（Union Find木で判定）
			//pa,pbはそれぞれ辺を結ぶ候補となっている2地点（pa < pb）
			int pa = (int)distArr[j][1];
			int pb = (int)distArr[j][2];
			unionFind[pa] = FindRoot(pa);
			unionFind[pb] = FindRoot(pb);

			/*デバッグ
			Console.Write(j + "| ");
			Console.Write(pa + ":" + unionFind[pa] + ",");
			Console.Write(pb + ":" + unionFind[pb] + " / ");
			*/

			//同じ根を持つ場合、飛ばして次へ
			if(unionFind[pa] == unionFind[pb]){
				j++;
				continue;
			}

			//その他の場合
			else{
				//最小値等の更新

				//Console.WriteLine(distArr[j][0]);

				min += distArr[j][0];
				cnt++;
				j++;

				//今回結ばれた辺を記憶（Union Find木を使う）
				MergeUF(pa, pb);
			}

		}

		/*デバッグ
		foreach(long[] co in coord){
				Console.WriteLine(co[0] + "," + co[1] + "," + co[2]);
		}
		foreach(long[] co in xDist){
				Console.WriteLine(co[0] + "," + co[1] + "," + co[2]);
		}
		foreach(long[] co in yDist){
				Console.WriteLine(co[0] + "," + co[1] + "," + co[2]);
		}
		*/

		/*デバッグ
		foreach(long[] co in distArr){
				Console.WriteLine(co[0] + "," + co[1] + "," + co[2]);
		}
		*/

		//出力
		Console.WriteLine(min);
	}
}

