using System.Linq;

namespace UnionFind
{

    public class Sample
    {
        public class UnionFind{
            List<int> par;
            List<int> sizes;

            public UnionFind(int n){
                par = new List<int>();
                sizes = new List<int>();
                for(int i = 0; i < n; i++){
                    par.Add(i);
                    sizes.Add(1);
                }
            }

            public int Find(int x){
                if(x == par[x]) return x;
                return par[x] = Find(par[x]);
            }

            public void Unite(int x, int y){
                x = Find(x);
                y = Find(y);
                if(x == y) return;
                if(sizes[x] < sizes[y]){
                    int tmp = x;
                    x = y;
                    y = tmp;
                }
                par[y] = x;
                sizes[x] += sizes[y];
            }

            public bool Same(int x, int y){
                return Find(x) == Find(y);
            }

            public int size(int x){
                return sizes[Find(x)];
            }
        }

        public struct Edge
        {
            public int a, b, cost;
            public Edge(int a, int b, int cost){
                this.a = a;
                this.b = b;
                this.cost = cost;
            }
        }

        public class Graph
        {
            public Graph(){
                es = new List<Edge>();
            }

            public int n;
            public List<Edge> es;

            public int Kruskal()
            {
                es.Sort((a, b) => a.cost - b.cost);

                UnionFind uf = new UnionFind(n);
                int min_cost = 0;
                foreach(var e in es){
                    if(!uf.Same(e.a,e.b)){
                        min_cost += e.cost;
                        uf.Unite(e.a,e.b);
                    }
                }

                return min_cost;
            }
        }

