class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var XY = new Tuple<long, long, int>[N];
        for (int i = 0; i < N; i++)
        {
            var x = sc.ReadLong();
            var y = sc.ReadLong();
            XY[i] = Tuple.Create(x, y, i);
        }
        var edges = new List<Tuple<int, int, long>>();
        Array.Sort(XY);
        for (int i = 0; i < N - 1; i++)
        {
            var s = XY[i].Item3;
            var sx = XY[i].Item1;
            var t = XY[i + 1].Item3;
            var tx = XY[i + 1].Item1;
            edges.Add(Tuple.Create(s, t, Math.Abs(sx - tx)));
            edges.Add(Tuple.Create(t, s, Math.Abs(sx - tx)));
        }
        Array.Sort(XY, (t1, t2) => -t1.Item2.CompareTo(t2.Item2));
        for (int i = 0; i < N - 1; i++)
        {
            var s = XY[i].Item3;
            var sy = XY[i].Item2;
            var t = XY[i + 1].Item3;
            var ty = XY[i + 1].Item2;
            edges.Add(Tuple.Create(s, t, Math.Abs(sy - ty)));
            edges.Add(Tuple.Create(t, s, Math.Abs(sy - ty)));
        }
        edges.Sort((e1, e2) => e1.Item3.CompareTo(e2.Item3));
        var uf = new UnionFind(N);
        var ans = 0L;
        foreach (var e in edges)
        {
            var s = e.Item1;
            var t = e.Item2;
            var cost = e.Item3;
            if (!uf.Same(s, t))
            {
                ans += cost;
                uf.Union(s, t);
            }
        }
        Console.WriteLine(ans);
    }

    class UnionFind
    {
        public int[] Parents;
        public int[] Rank;
        public UnionFind(int n)
        {
            this.Parents = Enumerable.Repeat(-1, n).ToArray();
            this.Rank = new int[n];
        }
        public int Find(int x)
        {
            if (this.Parents[x] < 0) return x;
            this.Parents[x] = Find(this.Parents[x]);
            return this.Parents[x];
        }
        public int Size(int x)
        {
            return -this.Parents[this.Find(x)];
        }
        public bool Same(int x, int y)
        {
            return this.Find(x) == this.Find(y);
        }
        public bool Union(int x, int y)
        {
            x = this.Find(x);
            y = this.Find(y);
            if (x == y) return false;

            if (this.Rank[x] < this.Rank[y])
            {
                var tmp = x;
                x = y;
                y = tmp;
            }
            if (this.Rank[x] == this.Rank[y]) this.Rank[x]++;
            this.Parents[x] += this.Parents[y];
            this.Parents[y] = x;
            return true;
        }
        public int GetGroupCount()
        {
            return this.Parents.Count(p => p < 0);
        }
    }
