		MyIO.ReadLines(n, out xyl);

		VT<int,int,int>[] xsl = new VT<int, int, int>[n];
		VT<int,int,int>[] ysl = new VT<int, int, int>[n];
		for(int i=0;i<n;i++) {
			xsl[i] = new VT<int, int, int>(xyl[i].Item1,xyl[i].Item2,i);
			ysl[i] = new VT<int, int, int>(xyl[i].Item1,xyl[i].Item2,i);
		}
		Array.Sort(xsl, (x,y)=>x.Item1-y.Item1);
		Array.Sort(ysl, (x,y)=>x.Item2-y.Item2);

		SortedList<long,int> sl = new SortedList<long, int>(); 

		List<VT<int,int,int>> g = new List<VT<int, int, int>>();
		for(int i=0;i<n-1;i++){
			long i1 = (long)Math.Min(xsl[i].Item3,xsl[i+1].Item3) * (long)n + (long)Math.Max(xsl[i].Item3,xsl[i+1].Item3) ;
			int c1 = Math.Min( Math.Abs(xsl[i].Item1-xsl[i+1].Item1), Math.Abs(xsl[i].Item2-xsl[i+1].Item2) );
			if(sl.ContainsKey(i1)){
				if(c1<sl[i1]) sl[i1] = c1;
			}else{
				sl[i1] = c1;
			}
			long i2 = (long)Math.Min(ysl[i].Item3,ysl[i+1].Item3) * (long)n + (long)Math.Max(ysl[i].Item3,ysl[i+1].Item3) ;
			int c2 = Math.Min( Math.Abs(ysl[i].Item1-ysl[i+1].Item1), Math.Abs(ysl[i].Item2-ysl[i+1].Item2) );
			if(sl.ContainsKey(i2)){
				if(c2<sl[i2]) sl[i2] = c2;
			}else{
				sl[i2] = c2;
			}
		}
		foreach(var s in sl){
			int k = (int)s.Key / n;
			int l = (int)s.Key % n;
			g.Add(new VT<int, int, int>(k,l,s.Value));
		}

		VT<int,int,int>[] o;
		long r = Kruskal(g.ToArray(), n, out o);

		MyIO.WriteMulti(r);

	}




	public static long Kruskal(VT<int,int,int>[] inEdges, int V, out VT<int,int,int>[] outEdges) {
		Array.Sort(inEdges, (x,y)=>(x.Item3.CompareTo(y.Item3)));
		UnionFind tree = new UnionFind(V);
		long ret = 0;
		List<VT<int,int,int>> oedge = new List<VT<int, int, int>>();
		foreach(var e in inEdges) {
			if(tree.Unite(e.Item1, e.Item2)) {
				ret += e.Item3;
				oedge.Add(e);
			}
		}
		outEdges = oedge.ToArray();
		return ret;
	}

}


public class UnionFind {
    private int[] data;

    public UnionFind(int size) {
        data = new int[size];
        for (int i = 0; i < size; i++) data[i] = -1;
    }

    public bool Unite(int x, int y) {
        x = Find(x);
        y = Find(y);

        if (x != y) {
            if (data[y] < data[x]) {
                var tmp = y;
                y = x;
                x = tmp;
            }
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }

    public bool IsSameGroup(int x, int y) { return Find(x) == Find(y); }

    public int Find(int x) { return data[x] < 0 ? x : data[x] = Find(data[x]); }

    public int Size(int x) { return -data[Find(x)]; }

}



