namespace ABC065D
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());

            memo[] x = new memo[N];
            memo[] y = new memo[N];
            for (int i = 0; i < N; i++)
            {
                var input = ReadLong();
                x[i] = new memo() { town = i, point = input[0] };
                y[i] = new memo() { town = i, point = input[1] };
            }

            //ソート
            x = x.OrderBy(x => x.point).ToArray();
            y = y.OrderBy(x => x.point).ToArray();

            Edge[] edgesx = new Edge[N - 1];
            Edge[] edgesy = new Edge[N - 1];
            for (int i = 0; i < N - 1; i++)
            {
                edgesx[i] = new Edge() { s = x[i].town, t = x[i + 1].town, cost = x[i + 1].point - x[i].point };
                edgesy[i] = new Edge() { s = y[i].town, t = y[i + 1].town, cost = y[i + 1].point - y[i].point };
            }

            Edge[] edges = edgesx.Concat(edgesy).ToArray();
            edges = edges.OrderBy(x => x.cost).ToArray();

            UnionFind unionFind = new UnionFind(N);

            long ans = 0;   //最小コスト
            foreach (var e in edges)
            {
                //結合済みでないなら追加
                if (!unionFind.Same(e.s, e.t))
                {
                    unionFind.Unite(e.s, e.t);
                    ans += e.cost;
                }
            }

            Console.WriteLine(ans);
            Console.ReadKey();
        }


        struct Edge
        {
            public int s;
            public int t;
            public long cost;
        }

        struct memo
        {
            public int town;
            public long point;
        }

