public class D
{
	public static void Main()
	{
		int N = GetInt();
		var cities = new List<Tuple<int, int, int>>(N);
		for(int i = 0; i < N; i++)
			cities.Add(Tuple.Create(GetInt(), GetInt(), i));

		var edges = new List<Edge>(2 * N);

		cities.Sort((p, q) => p.Item1 - q.Item1);
		for(int i = 0; i < N - 1; i++)
		{
			int a = cities[i].Item3;
			int c = cities[i+1].Item3;
			edges.Add(new Edge(a, c, cities[i+1].Item1 - cities[i].Item1));
		}

		cities.Sort((p, q) => p.Item2 - q.Item2);
		for(int i = 0; i < N - 1; i++)
		{
			int b = cities[i].Item3;
			int d = cities[i+1].Item3;
			edges.Add(new Edge(b, d, cities[i+1].Item2 - cities[i].Item2));
		}

		Console.WriteLine(Kruskal(N, edges));
	}

	public static int Kruskal(int N, List<Edge> edges)
	{
		edges.Sort((x, y) => x.Cost - y.Cost);
		var uf = new UnionFind(N);
		int res = 0;
		for(int i = 0; i < edges.Count; i++)
		{
			Edge edge = edges[i];
			if(!uf.IsSame(edge.S, edge.T))
			{
				uf.Merge(edge.S, edge.T);
				res += edge.Cost;
			}
		}
		return res;
	} 
}


