class Program
{
    static void Main(string[] args)
    {
        checked
        {
            var N = sc.ReadInt();
            var XY1 = new Tuple<int, int, int>[N];
            for (int i = 0; i < N; i++)
            {
                var x = sc.ReadInt();
                var y = sc.ReadInt();
                XY1[i] = Tuple.Create(x, y, i);
            }
            XY1 = XY1.OrderBy(t => t.Item1).ToArray();
            var XY2 = XY1.OrderBy(t => t.Item2).ToArray();
            var edges = new List<Tuple<int, int, int>>();
            for (int i = 0; i < N; i++)
            {
                var x = XY1[i].Item1;
                var y = XY1[i].Item2;
                var no = XY1[i].Item3;
                if (i > 0)
                {
                    edges.Add(Tuple.Create(no, XY1[i - 1].Item3, Math.Abs(x - XY1[i - 1].Item1)));
                }
                if (i < N - 1)
                {
                    edges.Add(Tuple.Create(no, XY1[i + 1].Item3, Math.Abs(x - XY1[i + 1].Item1)));
                }

                Comparison<Tuple<int, int, int>> fy = (a, b) => a.Item2.CompareTo(b.Item2);
                var idy = Array.BinarySearch(XY2, Tuple.Create(0, y, 0), Comparer<Tuple<int, int, int>>.Create(fy));
                if (idy > 0)
                {
                    edges.Add(Tuple.Create(no, XY2[idy - 1].Item3, Math.Abs(y - XY2[idy - 1].Item2)));
                }
                if (idy < N - 1)
                {
                    edges.Add(Tuple.Create(no, XY2[idy + 1].Item3, Math.Abs(y - XY2[idy + 1].Item2)));
                }
            }

            var uf = new UnionFind(N);
            var ans = 0L;
            edges = edges.OrderBy(e => e.Item3).ToList();
            foreach (var e in edges)
            {
                var a = e.Item1;
                var b = e.Item2;
                var c = e.Item3;
                if (!uf.Same(a, b))
                {
                    uf.Union(a, b);
                    ans += c;
                }
            }
            Console.WriteLine(ans);
        }
    }

    class UnionFind
    {
        public int[] Parents { get; set; }
        public UnionFind(int n)
        {
            this.Parents = new int[n];
            for (int i = 0; i < n; i++)
            {
                this.Parents[i] = -1;
            }
        }
        public int Find(int x)
        {
            if (this.Parents[x] < 0) return x;
            this.Parents[x] = Find(this.Parents[x]);
            return this.Parents[x];
        }
        public int Size(int x)
        {
            return -this.Parents[this.Find(x)];
        }
        public bool Same(int x, int y)
        {
            return this.Find(x) == this.Find(y);
        }
        public bool Union(int x, int y)
        {
            x = this.Find(x);
            y = this.Find(y);
            if (x == y) return false;

            if (this.Size(x) < this.Size(y))
            {
                var tmp = x;
                x = y;
                y = tmp;
            }
            this.Parents[x] += this.Parents[y];
            this.Parents[y] = x;
            return true;
        }
        public int GetGroupCount()
        {
            return this.Parents.Count(p => p < 0);
        }
    }
