using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder.Beginner065
{
    public class ABC065D_Built
    {
        class City
        {
            public int no;
            public int x;
            public int y;
            public List<City> adjacentCity = new List<City>();
        }

        public static void Main(string[] args)
        {
            // 街の数の入力
            int n = int.Parse(Console.ReadLine());

            // 街の座標の入力
            List<City> CityList = new List<City>();
            for(int i = 1; i <= n; i++)
            {
                int[] pos = new int[2];
                pos = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

                City newCity = new City()
                {
                    no = i,
                    x = pos[0],
                    y = pos[1],
                };
                CityList.Add(newCity);
            }


            // X隣接都市の設定

            CityList.Sort((a, b) => a.x - b.x);

            for(int i = 0; i < CityList.Count; i++)
            {
                if(i > 0)
                {
                    CityList[i].adjacentCity.Add(CityList[i - 1]);
                }
                if(i < CityList.Count - 1)
                {
                    CityList[i].adjacentCity.Add(CityList[i + 1]);
                }
            }

            // Y隣接都市の設定

            CityList.Sort((a, b) => a.y - b.y);

            for(int i = 0; i < CityList.Count; i++)
            {
                if(i > 0)
                {
                    CityList[i].adjacentCity.Add(CityList[i - 1]);
                }
                if(i < CityList.Count - 1)
                {
                    CityList[i].adjacentCity.Add(CityList[i + 1]);
                }
            }


            int[] calcRoadCost = new int[n + 1];
            for(int i = 1; i <= n; i++)
            {
                calcRoadCost[i] = int.MaxValue;
            }
            calcRoadCost[CityList[0].no] = 0;

            for(int cnt = 1; cnt < n; cnt++)
            {
                int goalCity = 0;
                int minRoadCost = int.MaxValue;

                foreach(City currentCity in CityList)
                {
                    if(calcRoadCost[currentCity.no] == int.MaxValue) { continue; }

                    foreach(City adjacentCity in currentCity.adjacentCity)
                    {
                        int cost = GetDiff(currentCity, adjacentCity);

                        if(calcRoadCost[adjacentCity.no] == int.MaxValue &&
                           cost < minRoadCost)
                        {
                            goalCity = adjacentCity.no;
                            minRoadCost = cost;
                        }
                    }
                }
                calcRoadCost[goalCity] = minRoadCost;
            }

            // 結果出力
            Console.WriteLine(calcRoadCost.Sum());

        }

        private static int GetDiff(City a, City b)
        {
            int xDif = Math.Abs(a.x - b.x);
            int yDif = Math.Abs(a.y - b.y);
            return Math.Min(xDif, yDif);
        }

    }
}

using System;
class Program
{
static int n = int.Parse(Console.ReadLine());//int.Parseは文字列を整数に変換。
static int[] parents = new int[n];//親

	static void Main()
	{
  long answer = 0;
  int[][] costs = new int[2*(n-1)][];//２頂点と距離
  int[][] vertexes = new int[n][];//ここに受け取る
    for(int i = 0; i < n; i++)
    {
    int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);//１行ごとに受け取る
    vertexes[i] = new int[]{i,nums[0],nums[1]};//頂点の座標をジャグ配列へ
    }
    Array.Sort(vertexes, (a, b) => a[1] - b[1]);//x座標の昇順に並べる
    for(int i = 0; i < n-1; i++)
    {
    costs[i] = new int[]{vertexes[i][0],vertexes[i+1][0],
      vertexes[i+1][1] - vertexes[i][1]};
    }

    Array.Sort(vertexes, (a, b) => a[2] - b[2]);//y座標の昇順に並べる
    for(int i = 0; i < n-1; i++)
    {
    costs[(n-1)+i] = new int[]{vertexes[i][0],vertexes[i+1][0],
      vertexes[i+1][2] - vertexes[i][2]};
    }

    Array.Sort(costs, (a, b) => a[2] - b[2]);//コストの昇順に並べる

    for(int i = 1; i < n; i++)//個体の結合
    {
    parents[i] = i;
    }

    for(int i = 0; i < costs.Length; i++)
    {
      int check = n-1;//頂点数だけ確認
        if(whatParent(costs[i][0]) != whatParent(costs[i][1]))
        {
          parents[costs[i][0]] = whatParent(costs[i][1]);//親の統一
          answer += costs[i][2];
          check--;
          if(check == 0) break;
        }

    }

	Console.WriteLine(answer);//WriteLineをWriteとすると、改行なしで出力。
	}

  static int whatParent(int child)
  {
    if(parents[child] == child) return child;
    else return parents[child] = whatParent(parents[child]);
  }

}

