        public class UnionFind
        {
            public int[] parent;
            public int[] rank;
            public int[] size;
            public UnionFind(int n)
            {
                parent = new int[n];
                rank = new int[n];
                size = new int[n];
                for (var i = 0; i < n; i++)
                {
                    parent[i] = i;
                    rank[i] = 0;
                    size[i] = 1;
                }
            }

            private int Root(int x)
            {
                return parent[x] == x ? x : parent[x] = Root(parent[x]);
            }

            public bool SameRoot(int x, int y)
            {
                return Root(x) == Root(y);
            }

            public void Unite(int x, int y)
            {
                x = Root(x);
                y = Root(y);
                if (x == y) { return; }

                if (rank[x] < rank[y])
                {
                    parent[x] = y;
                    size[y] += size[x];
                    size[x] = 0;
                }
                else
                {
                    parent[y] = x;
                    if (rank[x] == rank[y]) { rank[x]++; }
                    size[x] += size[y];
                    size[y] = 0;
                }
            }

            public int GetSize(int x)
            {
                return size[Root(x)];
            }

        }
