                if (a.Y > b.Y) return 1;

                return a.Id - b.Id;
            });

            List<Edge>[] edges = new List<Edge>[N];

            for (int i = 0; i < N; i++)
            {
                edges[i] = new List<Edge>();
            }

            for (int i = 0; i < N - 1; i++)
            {
                Point px1 = xSorted[i];
                Point px2 = xSorted[i + 1];
                Point py1 = ySorted[i];
                Point py2 = ySorted[i + 1];

                edges[px1.Id].Add(new Edge(Math.Abs(px1.X - px2.X), px1.Id, px2.Id));
                edges[px2.Id].Add(new Edge(Math.Abs(px1.X - px2.X), px2.Id, px1.Id));
                edges[py1.Id].Add(new Edge(Math.Abs(py1.Y - py2.Y), py1.Id, py2.Id));
                edges[py2.Id].Add(new Edge(Math.Abs(py1.Y - py2.Y), py2.Id, py1.Id));
            }
            long ans = new Prim().CalcTotalCost(edges, 0);

            cou.WriteLine(ans);
        }
    }

    public class Prim
    {
        public long CalcTotalCost(List<Edge>[] edges, int initialIndex)
        {
            int n = edges.Length;

            var pq = new PriorityQueue<Edge>();

            // はじめはinitialIndexからinitialIndexまで、コスト0のedgeを入れておく
            pq.Enqueue(new Edge(0, initialIndex, initialIndex));

            long totalCost = 0;

            bool[] used = new bool[n];

            while (pq.Count > 0)
            {
                var edge = pq.Dequeue();

                if (used[edge.T]) continue;

                used[edge.T] = true;

                totalCost += edge.Cost;

                foreach (Edge e in edges[edge.T])
                {
                    pq.Enqueue(e);
                }
            }

            return totalCost;
        }
    }

    public class PriorityQueue<T> where T : IComparable<T>
    {
        private List<T> data;

        public PriorityQueue()
        {
            this.data = new List<T>();
        }

        public void Enqueue(T item)
        {
            data.Add(item);
            int ci = data.Count - 1; // child index; start at end
            while (ci > 0)
            {
                int pi = (ci - 1) / 2; // parent index
                if (data[ci].CompareTo(data[pi]) >= 0)
                    break; // child item is larger than (or equal) parent so we're done
                T tmp = data[ci];
                data[ci] = data[pi];
                data[pi] = tmp;
                ci       = pi;
            }
        }

        public T Dequeue()
        {
            // assumes pq is not empty; up to calling code
            int li        = data.Count - 1; // last index (before removal)
            T   frontItem = data[0];        // fetch the front
            data[0] = data[li];
            data.RemoveAt(li);

            --li;       // last index (after removal)
            int pi = 0; // parent index. start at front of pq
            while (true)
            {
                int ci = pi * 2 + 1; // left child index of parent
                if (ci > li)
                    break;       // no children so done
                int rc = ci + 1; // right child
                if (rc <= li && data[rc].CompareTo(data[ci]) < 0
                ) // if there is a rc (ci + 1), and it is smaller than left child, use the rc instead
                    ci = rc;
                if (data[pi].CompareTo(data[ci]) <= 0)
                    break; // parent is smaller than (or equal to) smallest child so done
                T tmp = data[pi];
                data[pi] = data[ci];
                data[ci] = tmp; // swap parent and child
                pi       = ci;
            }

            return frontItem;
        }

        public T Peek()
        {
            T frontItem = data[0];
            return frontItem;
        }

        public int Count => data.Count;

        public override string ToString()
        {
            string s = "";
            for (int i = 0; i < data.Count; ++i)
                s += data[i].ToString() + " ";
            s += "count = " + data.Count;
            return s;
        }
    }


    public struct Edge : IComparable<Edge>, IEquatable<Edge>
    {
        public long Cost;
        public int  F;
        public int  T;

        public Edge(long cost, int f, int t)
        {
            Cost = cost;
            F    = f;
            T    = t;
        }

        public int CompareTo(Edge other)
        {
            if (Cost < other.Cost) return -1;
            if (Cost > other.Cost) return 1;

            int secondComparison = F - other.F;
            if (secondComparison != 0)
            {
                return secondComparison;
            }

            int thirdComparison = T - other.T;
            return thirdComparison;
        }

        public bool Equals(Edge other)
        {
            return Cost == other.Cost && F == other.F && T == other.T;
        }

        public override bool Equals(object obj)
        {
            if (ReferenceEquals(null, obj))
            {
                return false;
            }

            return obj is Edge && Equals((Edge)obj);
        }

        public override int GetHashCode()
        {
            unchecked
            {
                var hashCode = Cost.GetHashCode();
                hashCode = (hashCode * 397) ^ F;
                hashCode = (hashCode * 397) ^ T;
                return hashCode;
            }
        }

        public override string ToString()
        {
            return $"{nameof(Cost)}: {Cost}, {nameof(F)}: {F}, {nameof(T)}: {T}";
        }
    }


