public class Hello
{
    public const int INF = 999999999;
    public static void Main()
    {
        var nodes = new List<Node>();
        var n = int.Parse(Console.ReadLine().Trim());
        for (int i = 0; i < n; i++)
        {
            string[] line = Console.ReadLine().Trim().Split(' ');
            var x = int.Parse(line[0]);
            var y = int.Parse(line[1]);
            nodes.Add(new Node { x = x, y = y, id = i });
        }
        var minc = new int[n];
        var r = new List<Edge>[n];
        for (int i = 0; i < n; i++)
        {
            r[i] = new List<Edge>();
            minc[i] = INF;
        }
        var xs = nodes.OrderBy(x => x.x).ToArray();
        var n1 = xs[0];
        for (int i = 1; i < xs.Length; i++)
        {
            var n2 = xs[i];
            addEdge(r, n1, n2);
            n1 = n2;
        }
        var ys = nodes.OrderBy(x => x.y).ToArray();
        var n3 = ys[0];
        for (int i = 1; i < ys.Length; i++)
        {
            var n4 = ys[i];
            addEdge(r, n3, n4);
            n3 = n4;
        }
        var m = 2 * n;
        goPrim(r, minc, 0, m);
        Console.WriteLine(minc.Sum());
    }
    public static void addEdge (List<Edge>[] r , Node n1 , Node n2)
    {
        var a = Math.Abs(n1.x - n2.x);
        var b = Math.Abs(n1.y - n2.y);
        var c = Math.Min(a, b);
        r[n1.id].Add(new Edge { to = n2.id, d = c });
        r[n2.id].Add(new Edge { to = n1.id, d = c });
    }
    public static void goPrim(List<Edge>[] r, int[] minc, int targ, int m)
    {
        var pq = new PriorityQueue<Edge>(m * 2 + 1000);
        var n = minc.Length;
        var xL = new List<int>();
        xL.Add(targ); minc[targ] = 0;
        foreach (var x in r[targ]) pq.Push(x);
        while (xL.Count() < n)
        {
            var e = pq.Pop();
            if (!xL.Contains(e.to))
            {
                xL.Add(e.to);
                minc[e.to] = e.d;
                foreach (var x in r[e.to])
                    if (!xL.Contains(x.to)) pq.Push(x);
            }
        }
    }
}

