public class Program
{
    private int N;
    private int[] X, Y;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        X = new int[N];
        Y = new int[N];
        for (int i = 0; i < N; i++)
        {
            X[i] = sc.NextInt();
            Y[i] = sc.NextInt();
        }

        var xIndex = new int[N];
        var yIndex = new int[N];
        for (int i = 0; i < N; i++)
        {
            xIndex[i] = i;
            yIndex[i] = i;
        }

        Array.Sort(xIndex, (a, b) => X[a].CompareTo(X[b]));
        Array.Sort(yIndex, (a, b) => Y[a].CompareTo(Y[b]));

        var uf = new UnionFind(N);

        var edges = new List<Edge>();
        for (int i = 0; i < N - 1; i++)
        {
            edges.Add(new Edge(xIndex[i], xIndex[i + 1], X[xIndex[i+1]] - X[xIndex[i ]]));
            edges.Add(new Edge(yIndex[i], yIndex[i + 1], Y[yIndex[i+1]] - Y[yIndex[i ]]));
        }

        edges.Sort((a,b) => a.Dist.CompareTo(b.Dist));

        long ans = 0;

        foreach (Edge edge in edges)
        {
            if (!uf.Same(edge.X, edge.Y))
            {
                ans += edge.Dist;
                uf.Union(edge.X,edge.Y);
            }
        }
        Console.WriteLine(ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

