        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static void Solve()
        {
            var N = Sarray()[0];
            var points = new List<(int i, int x, int y)>();
            for (var i = 0; i < N; ++i)
            {
                var xy = Sarray();
                points.Add((i, (int)xy[0], (int)xy[1]));
            }
            points.Sort((l, r) => l.x - r.x);
            var dft = new (int dst, int f, int t)[2 * (N - 1)];
            for (var i = 0; i < N - 1; ++i)
                dft[i] = (points[i + 1].x - points[i].x, points[i].i, points[i + 1].i);
            points.Sort((l, r) => l.y - r.y);
            for (var i = 0; i < N - 1; ++i)
                dft[N - 1 + i] = (points[i + 1].y - points[i].y, points[i].i, points[i + 1].i);
            var cst = 0L;
            var uf = new UnionFind((int)N);
            Array.Sort(dft);
            foreach (var d in dft)
            {
                if (uf.issame(d.f, d.t)) continue;
                uf.merge(d.f, d.t);
                cst += d.dst;
            }
            WriteLine(cst);
        }

        class UnionFind
        {
            int[] par;
            public UnionFind(int n)
            {
                init(n);
            }
            public void init(int n)
            {
                par = new int[n];
                for (var i = 0; i < n; ++i) { par[i] = -1; }
            }
            public int root(int x)
            {
                if (par[x] < 0) return x;
                else return par[x] = root(par[x]);
            }
            public bool issame(int x, int y)
            {
                return root(x) == root(y);
            }
            public bool merge(int x, int y)
            {
                x = root(x);
                y = root(y);
                if (x == y) return false;
                if (par[x] > par[y])
                {
                    var tmp = y;
                    y = x;
                    x = tmp;
                }
                par[x] += par[y];
                par[y] = x;
                return true;
            }
            public int size(int x)
            {
                return -par[root(x)];
            }
        }
    }
}

