    public partial class AtCoder
    {
        public void Solve()
        {
            int N = GetInt();
            var pos = GetIntJaggedArray(N).Select((s, id) => new { id, x = s[0], y = s[1] }).ToArray();
            var G = new Dictionary<int, List<Edge>>();
            for (int i = 0; i < N; i++)
            {
                G.Add(i, new List<Edge>());
            }
            pos = pos.OrderBy(o => o.x).ToArray();
            for (int i = 0; i < N - 1; i++)
            {
                var dif = pos[i + 1].x - pos[i].x;
                G[pos[i].id].Add(new Edge(pos[i + 1].id, dif));
                G[pos[i + 1].id].Add(new Edge(pos[i].id, dif));
            }
            pos = pos.OrderBy(o => o.y).ToArray();
            for (int i = 0; i < N - 1; i++)
            {
                var dif = pos[i + 1].y - pos[i].y;
                G[pos[i].id].Add(new Edge(pos[i + 1].id, dif));
                G[pos[i + 1].id].Add(new Edge(pos[i].id, dif));
            }

            long sum = 0;
            var visited = Enumerable.Repeat(false, N).ToArray();
            var pq = new PriorityQueue<Pair>();
            pq.Enqueue(new Pair(0, 0));
            while (pq.Count() > 0)
            {
                var now = pq.Dequeue();
                if (visited[now.Node]) continue;
                sum += now.Cost;
                foreach (var next in G[now.Node])
                {
                    if (visited[next.To]) continue;
                    pq.Enqueue(new Pair(next.To, next.Length));
                }
                visited[now.Node] = true;
            }

            Console.WriteLine(sum);
        }

        class PriorityQueue<T> where T : IComparable<T>
        {
            public PriorityQueue()
            {
                buffer = new List<T>();
            }

            List<T> buffer;
            public void Enqueue(T elem)
            {
                int n = buffer.Count;
                buffer.Add(elem);
                while (n != 0)
                {
                    int i = (n - 1) / 2;
                    if (buffer[n].CompareTo(buffer[i]) > 0)
                    {
                        T temp = buffer[n];
                        buffer[n] = buffer[i];
                        buffer[i] = temp;
                    }
                    n = i;
                }
            }

            public T Dequeue()
            {
                var t = Peek();
                Pop();
                return t;
            }

            void Pop()
            {
                int n = buffer.Count - 1;
                buffer[0] = buffer[n];
                buffer.RemoveAt(n);
                for (int i = 0, j; (j = 2 * i + 1) < n;)
                {
                    if ((j != n - 1) && (buffer[j].CompareTo(buffer[j + 1]) < 0)) { j++; }
                    if (buffer[i].CompareTo(buffer[j]) < 0)
                    {
                        T temp = buffer[j];
                        buffer[j] = buffer[i];
                        buffer[i] = temp;
                    }
                    i = j;
                }
            }

            public T Peek()
            {
                return buffer[0];
            }

            public int Count()
            {
                return buffer.Count;
            }
        }

        class Pair : IComparable<Pair>
        {
            public Pair(int node, long cost)
            {
                Node = node; Cost = cost;
            }
            public int Node { get; set; }
            public long Cost { get; set; }
            public int CompareTo(Pair p)
            {
                return p.Cost > Cost ? 1 : -1;
            }
        }
    }
