namespace ProCon
{
    class Program
    {

        static void Main(string[] args)
        {
            int num = int.Parse(Console.ReadLine());

            List<int> listX = new List<int>();
            List<int> listY = new List<int>();
            List<int> already = new List<int>();
            for (int i = 0; i < num; ++i)
            {
                string[] input = Console.ReadLine().Split(' ');
                listX.Add(int.Parse(input[0]));
                listY.Add(int.Parse(input[1]));
            }
            int costs = 0;

            already.Add(0);
            for(int l = 0; l < num - 1; l++)
            {
                int mincost = 1000000001;
                int mintarget = 0;
                for (int i = 0; i < already.Count; ++i)
                {
                    for (int target = 0; target < num; ++target)
                    {
                        if (already.Contains(target))
                        {
                            continue;
                        }
                        int temp = System.Math.Min(Math.Abs(listX[already[i]] - listX[target]), Math.Abs(listY[already[i]] - listY[target]));
                        if (mincost > temp)
                        {
                            mincost = temp;
                            mintarget = target;
                        }
                    }
                }
                costs += mincost;
                already.Add(mintarget);
            }
            Console.WriteLine(costs);
        }
    }
