            for(int i = 0;i<N-1;i++)
            {
                G.Add(Tuple.Create(XY[i].Item3, XY[i + 1].Item3, Math.Abs(XY[i].Item1 - XY[i + 1].Item1)));
            }
            Array.Sort(XY, (a, b) => a.Item2.CompareTo(b.Item2));
            for(int i = 0; i < N - 1; i++)
            {
                G.Add(Tuple.Create(XY[i].Item3, XY[i + 1].Item3, Math.Abs(XY[i].Item2 - XY[i + 1].Item2)));
            }
            Kruskal kruskal = new Kruskal(N, G.Count, G.ToArray());
            Console.WriteLine(kruskal.sum());
        }
    }
    public class Kruskal
    {
        struct edge { public int u, v, cost; }
        private int V;
        private int E;
        private edge[] es;
        public Kruskal(int vv, int ee, Tuple<int, int, int>[] edge)
        {
            V = vv;
            E = ee;
            es = new edge[E];
            for (int i = 0; i < E; i++)
            {
                es[i] = new edge { u = edge[i].Item1, v = edge[i].Item2, cost = edge[i].Item3 };
            }
        }
        public int sum()
        {
            Union_Find union = new Union_Find(V);
            Array.Sort(es, (x, y) => x.cost.CompareTo(y.cost));

            int res = 0;
            for (int i = 0; i < E; i++)
            {
                edge e = es[i];
                if (!union.IsSameGroup(e.u, e.v))
                {
                    union.Unite(e.u, e.v);
                    res += e.cost;
                }
            }
            return res;
        }
    }
    public class Union_Find
    {
        private int[] data;
        public Union_Find(int size)
        {
            data = new int[size];
            for (int i = 0; i < size; i++) data[i] = -1;
        }
        public bool Unite(int x, int y)
        {
            x = Root(x);
            y = Root(y);
            if (x != y)
            {
                if (data[y] < data[x])
                {
                    var tmp = y;
                    y = x;
                    x = tmp;
                }
                data[x] += data[y];
                data[y] = x;
            }
            return x != y;
        }
        public bool IsSameGroup(int x, int y) => Root(x) == Root(y);
        public int Root(int x) => data[x] < 0 ? x : data[x] = Root(data[x]);
        public int getMem(int x) => -data[Root(x)];
    }
}

