    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var towns = consoleReader.Repeat(N).Select(cr => new Point(cr.Split.Int)).ToArray();
            var townX = towns.Select((p, i) => Tuple.Create(p, i)).OrderBy(t => t.Item1.x).Select(t => t.Item2).ToArray();
            var townY = towns.Select((p, i) => Tuple.Create(p, i)).OrderBy(t => t.Item1.y).Select(t => t.Item2).ToArray();
            var roads = new List<Road>(2 * N);
            long cost = 0;
            for (int i = 1; i < N; i++)
            {
                roads.Add(new Road { a = townX[i - 1], b = townX[i], cost = towns[townX[i]].x - towns[townX[i - 1]].x });
                roads.Add(new Road { a = townY[i - 1], b = townY[i], cost = towns[townY[i]].y - towns[townY[i - 1]].y });
            }
            roads.Sort();

            var uf = new UnionFind(N);
            foreach (var r in roads)
            {
                if (uf.IsSameSet(r.a, r.b)) continue;
                uf.UnionSet(r.a, r.b);
                cost += r.cost;
            }

            return cost;
        }
        struct Road : IComparable<Road>
        {
            public int cost;
            public int a;
            public int b;

            public int CompareTo(Road other) => this.cost.CompareTo(other.cost);
        }
        struct Point : IEquatable<Point>
        {
            public int x;
            public int y;
            public Point(int[] arr) : this(arr[0], arr[1]) { }
            public Point(int x, int y)
            {
                this.x = x;
                this.y = y;
            }
            public bool Equals(Point other) => this.x == other.x && this.y == other.y;
            public override bool Equals(object obj)
            {
                if (obj is Point) return Equals((Point)obj);
                return false;
            }
            public override int GetHashCode() => x ^ y;
            public override string ToString() => $"({x}, {y})";
        }

        class UnionFind
        {
            int[] data;
            public UnionFind(int size)
            {
                this.data = Enumerable.Repeat(-1, size).ToArray();
            }

            public int Root(int x)
            {
                if (data[x] < 0) return x;
                return data[x] = Root(data[x]);
            }
            public int Count(int x) => -data[Root(x)];
            public void UnionSet(int x, int y)
            {
                var xRoot = Root(x);
                var yRoot = Root(y);
                if (xRoot == yRoot) return;
                else if (data[yRoot] < data[xRoot])//y側の方が多い場合は逆にする
                {
                    var tmp = yRoot;
                    yRoot = xRoot;
                    xRoot = tmp;
                }
                data[xRoot] += data[yRoot];
                data[yRoot] = xRoot;
            }
            public bool IsSameSet(int x, int y) => Root(x) == Root(y);
        }


