using System;
class Program
{
static int n = int.Parse(Console.ReadLine());//int.Parseは文字列を整数に変換。
static int[] parents = new int[n];//親

	static void Main()
	{
  long answer = 0;
  int[][] costs = new int[2*(n-1)][];//２頂点と距離
  int[][] vertexes = new int[n][];//ここに受け取る
    for(int i = 0; i < n; i++)
    {
    int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);//１行ごとに受け取る
    vertexes[i] = new int[]{i,nums[0],nums[1]};//頂点の座標をジャグ配列へ
    }
    Array.Sort(vertexes, (a, b) => a[1] - b[1]);//x座標の昇順に並べる
    for(int i = 0; i < n-1; i++)
    {
    costs[i] = new int[]{vertexes[i][0],vertexes[i+1][0],
      vertexes[i+1][1] - vertexes[i][1]};
    }

    Array.Sort(vertexes, (a, b) => a[2] - b[2]);//y座標の昇順に並べる
    for(int i = 0; i < n-1; i++)
    {
    costs[(n-1)+i] = new int[]{vertexes[i][0],vertexes[i+1][0],
      vertexes[i+1][2] - vertexes[i][2]};
    }

    Array.Sort(costs, (a, b) => a[2] - b[2]);//コストの昇順に並べる

    for(int i = 0; i < n; i++)//個体の結合
    {
    parents[i] = i;
    }

    for(int i = 0; i < costs.Length; i++)
    {

        if(whatParent(costs[i][0]) != whatParent(costs[i][1]))
        { 

          parents[whatParent(costs[i][0])] = whatParent(costs[i][1]);//親の統一
          answer += costs[i][2];
        }

    }

	Console.WriteLine(answer);//WriteLineをWriteとすると、改行なしで出力。
	}

  static int whatParent(int child)
  {
    if(parents[child] == child) return child;
    else return parents[child] = whatParent(parents[child]);
  }

}

using System;
using System.Collections.Generic;

public class PriorityQueue<T> where T:IComparable<T>
{
	IComparer<T> comparer;
	T[] heap;
	int heapSize;

	public PriorityQueue(int maxSize, IComparer<T> comparer=null)
	{
		heap = new T[maxSize+1];
		heapSize = 0;
		this.comparer = comparer;
	}

	int compare(T x, T y)
	{
		if(comparer == null)
		{
			return x.CompareTo(y);
		}
		else
		{
			return comparer.Compare(x, y);
		}
	}

	public void Push(T x)
	{
		heapSize++;
		int i = heapSize;
		heap[i] = x;
		while(i > 1 && compare(heap[i/2], heap[i]) < 0)
		{
			T t = heap[i/2];
			heap[i/2] = heap[i];
			heap[i] = t;
			i = i / 2;
		}

	}

	void maxHeapify(int i)
	{
		int l, r, largest;
		l = i * 2;
		r = i * 2 + 1;
		largest = i;
		if(l <= heapSize && compare(heap[l], heap[i]) > 0)
				largest = l;
		if(r <= heapSize && compare(heap[r], heap[largest]) > 0)
				largest = r;

		if(largest != i)
		{
			T t = heap[i];
			heap[i] = heap[largest];
			heap[largest] = t;
			maxHeapify(largest);
		}
	}

	public T Pop()
	{
		if(heapSize == 0)
			return default(T);
		T max = heap[1];
		heap[1] = heap[heapSize];
		heapSize--;
		maxHeapify(1);
		return max;
	}

}

