		}

		nodes.Sort((a,b) => (a.Y - b.Y));
		for(int i=0; i<nodes.Count-1; i++)
		{
			nodes[i].Edges.Add(new Edge(nodes[i+1], nodes[i+1].Y - nodes[i].Y));
			//Console.WriteLine("{0} to {1} weight = {2}", i, i+1, nodes[i+1].Y-nodes[i].Y);
			nodes[i+1].Edges.Add(new Edge(nodes[i], nodes[i+1].Y - nodes[i].Y));
