            for (int i = 0; i < n - 1; i++)
            {
                var cost = Math.Min(Math.Abs(node[i].Item2 - node[i + 1].Item2)
                    , Math.Abs(node[i].Item3 - node[i + 1].Item3));

                k.AddPath(node[i].Item1, node[i + 1].Item1, cost);
            }

            Array.Sort(node, (x, y) => x.Item3.CompareTo(y.Item3));
            for (int i = 0; i < n - 1; i++)
            {
