        /// <summary>
        /// 最小全域木(Minimum Spanning Tree)を求める
        /// 無向グラフのみ
        /// 有向グラフは「Chu-Liu/Edmondsのアルゴリズム」とからしい
        /// </summary>
        class Kruskal
        {
            /// <summary>
            /// アイテムを含まないUF木
            /// </summary>
            class UnionFind
            {
                List<int> rank { get; set; }
                List<int> size { get; set; }
                List<int> parentId { get; set; }

                public UnionFind(int size)
                {
                    this.rank = Enumerable.Repeat(0, size).ToList();
                    this.size = Enumerable.Repeat(1, size).ToList();
                    this.parentId = Enumerable.Range(0, size).ToList();
                }

                /// <summary>
                /// 同一の親を持つか
                /// </summary>
                /// <param name="x"></param>
                /// <param name="y"></param>
                /// <returns></returns>
                public bool Same(int x, int y)
                {
                    return FindRoot(x) == FindRoot(y);
                }

                /// <summary>
                /// 指定ノードのrootを返す
                /// </summary>
                /// <param name="x"></param>
                /// <returns></returns>
                public int FindRoot(int x)
                {
                    if (x != this.parentId[x])
                    {
                        // 経路中のノードのparentを更新しておく
                        this.parentId[x] = FindRoot(this.parentId[x]);
                    }

                    return this.parentId[x];
                }

                /// <summary>
                /// 重みをつけて合体する
                /// </summary>
                /// <param name="x"></param>
                /// <param name="y"></param>
                /// <param name="w"></param>
                public void Merge(int x, int y)
                {
                    x = FindRoot(x);
                    y = FindRoot(y);

                    if (x == y) return;

                    if (this.rank[y] < this.rank[x])
                    {
                        this.parentId[y] = x;
                        this.size[x] += this.size[y];
                    }
                    else
                    {
                        this.parentId[x] = y;
                        this.size[y] += this.size[x];

                        if (this.rank[x] == this.rank[y])
                        {
                            this.rank[y]++;
                        }
                    }
                }

                /// <summary>
                /// xと同じ親を持つノードの数
                /// </summary>
                /// <param name="x"></param>
                /// <returns></returns>
                public int Size(int x)
                {
                    x = FindRoot(x);

                    return this.size[x];
                }
            }

            public struct Edge : IComparable<Edge>
            {
                public int v1;
                public int v2;
                public int Cost;

                public Edge(int v1, int v2, int cost)
                {
                    this.v1 = v1;
                    this.v2 = v2;
                    this.Cost = cost;
                }

                public int CompareTo(Edge other)
                {
                    return this.Cost - other.Cost;
                }
            }

            static readonly int INF = int.MaxValue / 5;

            // 接続情報
            List<Edge> es;
            // ノード数
            int V;

            /// <summary>
            /// 
            /// </summary>
            /// <param name="v">ノード数</param>
            public Kruskal(int v)
            {
                es = new List<Edge>();
                V = v;
            }

            /// <summary>
            /// 経路追加
            /// </summary>
            /// <param name="v1"></param>
            /// <param name="v2"></param>
            /// <param name="cost"></param>
            public void AddPath(int v1, int v2, int cost)
                => es.Add(new Edge(v1, v2, cost));

            /// <summary>
            /// 最小全域木
            /// </summary>
            /// <returns></returns>
            public List<Edge> MinimumSpanningTree()
            {
                this.es.Sort();

                var uf = new UnionFind(V);
                var tree = new List<Edge>();
                foreach (var edge in this.es)
                {
                    if (!uf.Same(edge.v1, edge.v2))
                    {
                        uf.Merge(edge.v1, edge.v2);
                        tree.Add(edge);
                    }
                }

                return tree;
            }
        }

