    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            int[,] city = new int[n, 2];
            int[,] road = new int[n, n];
            for (int i = 0; i < n; i++)
            {
                int[] x = Console.ReadLine().Split().Select(int.Parse).ToArray();
                city[i, 0] = x[0]; city[i, 1] = x[1];
            }
            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++)
                {
                    if (i == j) continue;
                    road[i, j] = Math.Min(Math.Abs(city[i, 0] - city[j, 0]), Math.Abs(city[i, 1] - city[j, 1]));
                }
            }
            long ret = 0;
            bool[] visit = new bool[n];
            visit[0] = true;
            bool end = false;
            while (!end)
            {
                int minmater = int.MaxValue;
                int min = 0;
                for (int i = 0; i < n; i++)
                {
                    if (!visit[i]) continue;
                    for (int j = 0; j < n; j++)
                    {
                        if (i == j || visit[j]) continue;
                        if (minmater > road[i, j])
                        {
                            minmater = road[i, j];
                            min = j;
                        }
                    }
                }
                ret += minmater;
                visit[min] = true;
                end = true;
                for (int i = 0; i < n && end; i++)
                {
                    if (!visit[i]) end = false;
                }
            }
