public class UnionFind {
    private int[] data;

    public UnionFind(int size) {
        data = new int[size];
        for (int i = 0; i < size; i++) data[i] = -1;
    }

    public bool Unite(int x, int y) {
        x = Find(x);
        y = Find(y);

        if (x != y) {
            if (data[y] < data[x]) {
                var tmp = y;
                y = x;
                x = tmp;
            }
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }

    public bool IsSameGroup(int x, int y) { return Find(x) == Find(y); }

    public int Find(int x) { return data[x] < 0 ? x : data[x] = Find(data[x]); }

    public int Size(int x) { return -data[Find(x)]; }

}



