int Find(int x)
{
    return f[x]==x?f[x]:f[x]=Find(f[x]);
}

int main()
{
    int n; cin>>n;
    int cnt=0;
    for(int i=1;i<=n;++i){
         scanf("%d%d",&p[i].x,&p[i].y);
         p[i].id=i;
