    sort(p+1,p+n+1,[](P a,P b){return a.x<b.x;});
    for(int i=1;i<n;++i){
        e[++cnt].u=p[i].id; e[cnt].v=p[i+1].id; e[cnt].w=p[i+1].x-p[i].x;
    }
    sort(p+1,p+n+1,[](P a,P b){return a.y<b.y;});
    for(int i=1;i<n;++i){
        e[++cnt].u=p[i].id; e[cnt].v=p[i+1].id; e[cnt].w=p[i+1].y-p[i].y;
    }
