class UnionFind3
  def initialize(size)
    @table = [-1]*size
  end

  def find(x)
    if @table[x] < 0
      return x
    else
      return @table[x] = find(@table[x])
    end
  end

  def union(x, y)
    s1 = find(x)
    s2 = find(y)
    if s1 != s2
      if @table[s1] <= @table[s2]
        @table[s1] += @table[s2]
        @table[s2] = s1
      else
        @table[s2] += @table[s1]
        @table[s1] = s2
      end
      return true
    end
    return false
  end
end

