def kruskal(n, edges)
  edges.sort_by! { |_, _, c| c }
  uf = UnionFind.new(n)
  ret = 0
  edges.size.times do |i|
    u, v, c = edges[i]
    if !uf.same?(u, v)
      uf.unite(u, v)
      ret += c
    end
  end
  ret
end

