    @rank = Hash.new { |hash, key| hash[key] = 0 }
  end

  def root(x)
    @parent[x] == x ? x : @parent[x] = root(@parent[x])
  end

  def same?(x, y)
    root(x) == root(y)
  end

  def unite(x, y)
    x, y = root(x), root(y)
