	"sort"
)

type City struct {
	id, x, y int
}

type Edge struct {
	u, v, cost int
}

func main() {
	N := ReadInt()
	cities := make([]*City, N)
	for i := 0; i < N; i++ {
		cities[i] = &City{
			id: i,
			x:  ReadInt(),
			y:  ReadInt(),
		}
	}
	edges := make([]*Edge, 0)
	sort.Slice(cities, func(i, j int) bool {
		return cities[i].x < cities[j].x
	})
	for i := 0; i < N-1; i++ {
		edges = append(edges, &Edge{
			u:    cities[i].id,
			v:    cities[i+1].id,
			cost: Dist(cities[i], cities[i+1]),
		})
	}
	sort.Slice(cities, func(i, j int) bool {
		return cities[i].y < cities[j].y
	})
	for i := 0; i < N-1; i++ {
		edges = append(edges, &Edge{
			u:    cities[i].id,
			v:    cities[i+1].id,
			cost: Dist(cities[i], cities[i+1]),
		})
	}
	sort.Slice(edges, func(i, j int) bool {
		return edges[i].cost < edges[j].cost
	})
	sum := 0
	uf := MakeUnionFind(N)
	for _, edge := range edges {
		if uf.Connected(edge.u, edge.v) {
			continue
		}
		uf.Unite(edge.u, edge.v)
		sum += edge.cost
	}
	fmt.Println(sum)
}

type UnionFind []int

func MakeUnionFind(size int) UnionFind {
	parent := make([]int, size)
	for i := 0; i < size; i++ {
		parent[i] = i
	}
	return parent
}
func (uf UnionFind) Unite(x, y int) {
	if x, y = uf.Root(x), uf.Root(y); x != y {
		uf[x] = y
	}
}
func (uf UnionFind) Connected(x, y int) bool { return uf.Root(x) == uf.Root(y) }
func (uf UnionFind) Root(x int) int {
	if uf[x] == x {
		return x
	}
	uf[x] = uf.Root(uf[x])
	return uf[x]
}

func Dist(a, b *City) int {
	return Min(
		Abs(a.x-b.x),
		Abs(a.y-b.y),
	)
}

func Min(xs ...int) int {
	min := xs[0]
	for _, x := range xs[1:] {
		if min > x {
			min = x
		}
	}
	return min
}

func Abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

var reader = bufio.NewReader(os.Stdin)

func Scan(a ...interface{}) {
	if _, err := fmt.Fscan(reader, a...); err != nil {
		panic(err)
	}
}
func ReadInt() (i int)       { Scan(&i); return }
func ReadString() (s string) { Scan(&s); return }
func ReadInts(n int) []int {
	v := make([]int, n)
	for i := 0; i < n; i++ {
		Scan(&v[i])
	}
	return v
}

