        }
        e := make([][]Edge, N, N)
        for i := 0; i < N; i++ {
                e[i] = make([]Edge, 0, N)
        }
        sort.Sort(byX(V))
        for i := 1; i < N; i++ {
                e[V[i-1].I] = append(e[V[i-1].I], Edge{V[i-1].I, V[i].I, abs(V[i-1].X - V[i].X)})
                e[V[i].I] = append(e[V[i].I], Edge{V[i].I, V[i-1].I, abs(V[i-1].X - V[i].X)})
        }
        sort.Sort(byY(V))
        for i := 1; i < N; i++ {
                e[V[i-1].I] = append(e[V[i-1].I], Edge{V[i-1].I, V[i].I, abs(V[i-1].Y - V[i].Y)})
                e[V[i].I] = append(e[V[i].I], Edge{V[i].I, V[i-1].I, abs(V[i-1].Y - V[i].Y)})
        }
        ret := 0
        Vn := [10000]bool{0: true}
        q := make(PriorityQueue, len(e[0]))
        for i := range e[0] {
                q[i] = &Item{e[0][i].B, e[0][i].P, i}
        }
        heap.Init(&q)
        for len(q) > 0 {
                i := heap.Pop(&q).(*Item)
                if Vn[i.Value] {
                        continue
                }
                ret += i.Priority
                Vn[i.Value] = true
                for _, j := range e[i.Value] {
                        if !Vn[j.B] {
                                heap.Push(&q, &Item{j.B, j.P, 0})
                        }
                }
        }
        fmt.Println(ret)

}

