func getScanner(fp *os.File) *bufio.Scanner {
	scanner := bufio.NewScanner(fp)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 500001), 500000)
	return scanner
}

func getNextString(scanner *bufio.Scanner) string {
	scanner.Scan()
	return scanner.Text()
}

func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}

func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	points := make(Points, n)
	edges := make([][]Edge, n)
	for i := 0; i < n; i++ {
		points[i].x = getNextInt64(scanner)
		points[i].y = getNextInt64(scanner)
		points[i].s = points[i].x
		points[i].i = i
	}

	sort.Sort(points)

	for i := 0; i < n-1; i++ {
		cost := points[i+1].x - points[i].x
		edges[points[i].i] = append(edges[points[i].i], Edge{
			i:    points[i+1].i,
			cost: cost,
		})
		edges[points[i+1].i] = append(edges[points[i+1].i], Edge{
			i:    points[i].i,
			cost: cost,
		})
		points[i].s = points[i].y
		points[i+1].s = points[i+1].y
	}
	sort.Sort(points)

	for i := 0; i < n-1; i++ {
		cost := points[i+1].y - points[i].y
		edges[points[i].i] = append(edges[points[i].i], Edge{
			i:    points[i+1].i,
			cost: cost,
		})
		edges[points[i+1].i] = append(edges[points[i+1].i], Edge{
			i:    points[i].i,
			cost: cost,
		})
	}

	var ans int64
	color := make([]int, n)
	var h EdgeHeap
	heap.Init(&h)
	heap.Push(&h, Edge{
		i:    0,
		cost: 0,
	})

	for h.Len() > 0 {
		p := heap.Pop(&h).(Edge)
		if color[p.i] == 2 {
			continue
		}
		color[p.i] = 2
		if p.i != 0 {
			ans += p.cost
		}
		for i := 0; i < len(edges[p.i]); i++ {
			if color[edges[p.i][i].i] == 2 {
				continue
			}
			heap.Push(&h, Edge{
				i:    edges[p.i][i].i,
				cost: edges[p.i][i].cost,
			})
		}
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

// Point ...
type Point struct {
