type cost struct {
	val      int
	from, to int
}

type costSlice []cost

func (cs *costSlice) Len() int {
	return len(*cs)
}
func (cs *costSlice) Less(i, j int) bool {
	c := *cs
	return c[i].val < c[j].val
}
func (cs *costSlice) Swap(i, j int) {
	c := *cs
	c[i], c[j] = c[j], c[i]
}
func (cs *costSlice) Push(x interface{}) {
	item := x.(cost)
	*cs = append(*cs, item)
}
func (cs *costSlice) Pop() interface{} {
	c := *cs
	n := len(c) - 1
	if n == -1 {
		return nil
	}
	x := c[n]
	*cs = c[:n]
	return x
}

func main() {
	defer stdout.Flush()

	n := readInt()
	ts := make([]town, n)
	for i := 0; i < n; i++ {
		ts[i].id = i
		ts[i].x = readInt()
		ts[i].y = readInt()
	}

	E := make([][]cost, n)

	sort.Sort(townSliceX(ts))
	for i := 0; i+1 < n; i++ {
		a := ts[i].id
		b := ts[i+1].id
		c := absInt(ts[i].x - ts[i+1].x)
		E[a] = append(E[a], cost{c, a, b})
		E[b] = append(E[b], cost{c, b, a})
	}

	sort.Sort(townSliceY(ts))
	for i := 0; i+1 < n; i++ {
		a := ts[i].id
		b := ts[i+1].id
		c := absInt(ts[i].y - ts[i+1].y)
		E[a] = append(E[a], cost{c, a, b})
		E[b] = append(E[b], cost{c, b, a})
	}

	v := make(map[int]bool)

	h := new(costSlice)
	heap.Init(h)
	pop := func() (cost, bool) {
		x := heap.Pop(h)
		if x == nil {
			return cost{}, false
		}
		return x.(cost), true
	}

	push := func(c cost) {
		heap.Push(h, c)
	}

	v[0] = true
	for _, c := range E[0] {
		push(c)
	}

	var ans int64
	for len(v) != n {
		e, ok := pop()
		if !ok {
			panic("no edges found")
		}
		if v[e.to] {
			continue
		}
		ans += int64(e.val)
		v[e.to] = true
		for _, c := range E[e.to] {
			push(c)
		}
	}
	println(ans)
}

