var V, E int

func solve() {
	var N int
	fmt.Scan(&N)
	city := make([]point, N)
	for i := 0; i < N; i++ {
		fmt.Scan(&city[i].x, &city[i].y)
	}
	for i := 0; i < N; i++ {
		for j := 0; j < N; j++ {

			cost := min(abs(city[i].x-city[j].x), abs(city[i].y-city[j].y))
			if i == j {
				continue
			}
			// log.Println(i, j, cost)
			edges = append(edges, edge{u: i, v: j, cost: cost})
			E++
		}
	}
	V = N
	// log.Println(edges)
	fmt.Println(kruskal())
}

type edge struct {
	u, v, cost int
}

var edges []edge

type ByCost []edge

func (a ByCost) Len() int           { return len(a) }
func (a ByCost) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a ByCost) Less(i, j int) bool { return a[i].cost < a[j].cost }

func kruskal() int {
	sort.Sort(ByCost(edges))
	uf := makeUnionFind(V)
	res := 0
	for i := 0; i < E; i++ {
		e := edges[i]
		if !uf.Same(e.u, e.v) {
			uf.Unit(e.u, e.v)
			res += e.cost
		}
	}
	return res
}

type unionFind struct {
	par  []int
	size []int
	link [][]int
}

func makeUnionFind(count int) *unionFind {
	par := make([]int, count)
	size := make([]int, count)
	link := make([][]int, count)
	for i := range link {
		link[i] = make([]int, 1)
	}
	for i := 0; i < count; i++ {
		par[i] = i
		size[i] = 1
		link[i][0] = i
	}
	return &unionFind{par: par, size: size, link: link}
}

func (uf *unionFind) Find(a int) int {
	for uf.par[a] != a {
		uf.par[a] = uf.par[uf.par[a]]
		a = uf.par[a]
	}
	return a
}

func (uf *unionFind) Unit(a, b int) {
	a = uf.Find(a)
	b = uf.Find(b)
	if a != b {
		if uf.size[a] > uf.size[b] {
			a, b = b, a
		}
		uf.par[a] = b
		uf.size[b] += uf.size[a]
		uf.link[b] = append(uf.link[b], uf.link[a]...)
	}
}

func (uf *unionFind) Same(a, b int) bool {
	return uf.Find(a) == uf.Find(b)
}

