func main() {
    var pointSorter Sortable
    var edgeSorter Sortable
    var parent []int
    sc.Split(bufio.ScanWords)
    n := readInt()
    for i := 0; i < n; i++ {
        pointSorter.arr = append(pointSorter.arr, &Point{x:readInt(), y:readInt(), id:i})
    }
    compX := func(p, q interface{}) bool {
        return p.(*Point).x < q.(*Point).x
    }
    compY := func(p, q interface{}) bool {
        return p.(*Point).y < q.(*Point).y
    }
    compE := func(p, q interface{}) bool {
        return p.(*Edge).cost < q.(*Edge).cost
    }
    pointSorter.comp = compX
    sort.Sort(pointSorter)
    for i := 0; i < n - 1; i++ {
        p1 := pointSorter.arr[i].(*Point)
        p2 := pointSorter.arr[i + 1].(*Point)
        edgeSorter.arr = append(edgeSorter.arr, &Edge{p2.x - p1.x, p1.id, p2.id})
    }
    pointSorter.comp = compY
    sort.Sort(pointSorter)
    for i := 0; i < n - 1; i++ {
        p1 := pointSorter.arr[i].(*Point)
        p2 := pointSorter.arr[i + 1].(*Point)
        edgeSorter.arr = append(edgeSorter.arr, &Edge{p2.y - p1.y, p1.id, p2.id})
    }

    edgeSorter.comp = compE
    sort.Sort(edgeSorter)
    for i := 0; i < n; i++ {
        parent = append(parent, i)
    }

    ans := 0
    for _, edge := range edgeSorter.arr {
        p1, p2 := find(edge.(*Edge).id1, parent), find(edge.(*Edge).id2, parent)
        if p1 != p2 {
            parent[p1] = p2
            ans += edge.(*Edge).cost
        }
    }
    fmt.Println(ans)
}

