		a, b := getInt(), getInt()
		x[i] = Data{a, i}
		y[i] = Data{b, i}
		n[i] = node{a, b}
	}
	sort.Sort(x)
	sort.Sort(y)
	out(N)
	out("x=", x)
	out("y=", y)
	out(n)
	// diff
	d := make(Datas2, (N-1)*2)
	for i := 1; i < N; i++ {
		d[(i-1)*2] = Data2{x[i].k - x[i-1].k, x[i].v, x[i-1].v, 0}
		d[(i-1)*2+1] = Data2{y[i].k - y[i-1].k, y[i].v, y[i-1].v, 1}
	}
	sort.Sort(d)
	out(d)

	cnt := 0
	ans := 0
	u := newUnionFind(N)
	for _, v := range d {
		if u.same(v.i, v.j) == false {
			ans += v.k
			u.unite(v.i, v.j)
			cnt++
		}
		if cnt == N-1 {
			break
		}
	}
	fmt.Println(ans)
}

