type ufTree struct {
	parent, rank, size []int
}

func (uf *ufTree) init(n int) {
	uf.parent = make([]int, n)
	uf.rank = make([]int, n)
	uf.size = make([]int, n)
	for i, _ := range uf.parent {
		uf.parent[i] = i
	}
	for i, _ := range uf.rank {
		uf.rank[i] = 0
	}
	for i, _ := range uf.size {
		uf.size[i] = 1
	}
}

func (uf *ufTree) find(x int) int {
	if uf.parent[x] == x {
		return x
	}
	uf.parent[x] = uf.find(uf.parent[x])
	return uf.parent[x]
}

func (uf *ufTree) unite(x, y int) {
	px, py := uf.find(x), uf.find(y)

	if px == py {
		return
	}

	s := uf.size[px] + uf.size[py]

	if uf.rank[px] < uf.rank[py] {
		uf.parent[px] = py
		uf.size[py] = s
		return
	}
	uf.parent[py] = px
	if uf.rank[px] == uf.rank[py] {
		uf.rank[px]++
	}
	uf.size[px] = s
}

func (uf *ufTree) same(x, y int) bool {
	if uf.find(x) == uf.find(y) {
		return true
	}
	return false
}

func (uf *ufTree) getSize(x int) int {
	px := uf.find(x)
	return uf.size[px]
}

