        Vn := [10000]bool{0: true}
        q := make(PriorityQueue, len(e[0]))
        for i := range e[0] {
                q[i] = Item{e[0][i].B, e[0][i].P, i}
        }
        heap.Init(&q)
        fmt.Println("start calc", time.Now().Sub(start))
        for len(q) > 0 {
                i := heap.Pop(&q).(Item)
                if Vn[i.Value] {
                        continue
                }
                ret += i.Priority
                Vn[i.Value] = true
                for _, j := range e[i.Value] {
                        if !Vn[j.B] {
                                heap.Push(&q, Item{j.B, j.P, 0})
                        }
                }
        }
        fmt.Println("end calc", time.Now().Sub(start))
        fmt.Println(ret)

}

