type city struct{ x, y int }

var cities []city

func cost(s, t city) int {
	costX := abs(s.x - t.x)
	costY := abs(s.y - t.y)
	if costX < costY {
		return costX
	}
	return costY
}

func abs(v int) int {
	if v < 0 {
		return -v
	}
	return v
}

type cityList struct {
	list []int
	comp func(id int) int
}

func (cl cityList) edges() (edges []edge) {
	sort.Sort(cl)
	for i := 0; i < len(cl.list)-1; i++ {
		x, y := cl.list[i], cl.list[i+1]
		edges = append(edges, edge{x, y, cost(cities[x], cities[y])})
	}
	return
}

func (c cityList) Len() int {
	return len(c.list)
}

func (c cityList) Less(i, j int) bool {
	return c.comp(c.list[i]) < c.comp(c.list[j])
}

func (c cityList) Swap(i, j int) {
	c.list[i], c.list[j] = c.list[j], c.list[i]
}

func findMSTWithKruskal(card int, edges edgeList) (mst edgeList, cost int, err error) {
	sort.Sort(edges)
	l := len(edges)
	uf := newUnifonFind(card)
	for i := 0; !uf.connected && i < l; i++ {
		e := edges[i]
		if uf.same(e.x, e.y) {
			continue
		}
		uf.union(edges[i].x, edges[i].y)
		cost += e.cost
		mst = append(mst, e)
	}
	if !uf.connected {
		return mst, cost, errors.New("can't construct MST")
	}
	return mst, cost, nil
}

