type UnionFindTree struct {
	parent	map[int]int
	size	map[int]int
	rank	map[int]int
}

func NewUnionFindTree() *UnionFindTree {
	u := new(UnionFindTree)
	u.parent = make(map[int]int)
	u.size = make(map[int]int)
	u.rank = make(map[int]int)
	return u
}

func (u UnionFindTree) Add(a int) {
	u.parent[a] = -1
	u.size[a] = 1
	u.rank[a] = 0
}

func (u UnionFindTree) Root(a int) int {
	if u.parent[a] == -1 {
		return a
	} else {

		u.parent[a] = u.Root(u.parent[a])
		return u.parent[a]
	}
}

func (u UnionFindTree) Unite(a, b int) {
	a, b = u.Root(a), u.Root(b)
	if a == b {
		return
	}
	if u.rank[a] == u.rank[b] {
		u.rank[a] += 1
	} else if u.rank[a] < u.rank[b] {
		a, b = b, a
	}
	u.parent[b] = a
	u.size[a] += u.size[b]
}

func (u UnionFindTree) IsSame(a, b int) bool {
	return u.Root(a) == u.Root(b)
}

func (u UnionFindTree) Size(a int) int {
	return u.size[u.Root(a)]
}

func (u UnionFindTree) Groups() map[int][]int {
	ret := make(map[int][]int)
	for k := range u.parent {
		r := u.Root(k)
		if len(ret[r]) == 0 {
			ret[r] = []int{}
		}
		ret[r] = append(ret[r], k)
	}
	return ret
}

type Point struct {
	pos int
	idx int
}

type Adjacent struct {
	distance int
	a int
	b int
}

func main() {
	var N int
	fmt.Scan(&N)
	uft := NewUnionFindTree()
	xPoint := make([]Point, N)
	yPoint := make([]Point, N)
	for i := 0; i < N; i++ {
		uft.Add(i)
		var x, y int
		fmt.Scan(&x, &y)
		xPoint[i] = Point{pos: x, idx: i}
		yPoint[i] = Point{pos: y, idx: i}
	}
	sort.Slice(xPoint, func(i, j int) bool { return xPoint[i].pos < xPoint[j].pos })
	sort.Slice(yPoint, func(i, j int) bool { return yPoint[i].pos < yPoint[j].pos })
	adj := make([]Adjacent, (N-1)*2)
	for i := 0; i < N-1; i++ {
		adj[2*i] = Adjacent{
			distance: xPoint[i+1].pos - xPoint[i].pos, 
			a: xPoint[i].idx, 
			b: xPoint[i+1].idx,
		}
		adj[2*i+1] = Adjacent{
			distance: yPoint[i+1].pos - yPoint[i].pos, 
			a: yPoint[i].idx, 
			b: yPoint[i+1].idx,
		}
	}
	sort.Slice(adj, func(i, j int) bool { return adj[i].distance < adj[j].distance })
	ans := 0
	for i := 0; i < (N-1)*2; i++ {
		if !uft.IsSame(adj[i].a, adj[i].b) {
			ans += adj[i].distance
			uft.Unite(adj[i].a, adj[i].b)
		}
	}
	fmt.Println(ans)
}

