func (con *contest) main() error {
	var n int
	con.Scan(&n)
	x := make([]int, n)
	y := make([]int, n)
	for i := 0; i < n; i++ {
		con.Scan(&x[i], &y[i])
	}
	minCost := make([]int, n)
	used := make([]bool, n)
	res := 0
	for i := 1; i < n; i++ {
		minCost[i] = 1e18
	}
	for {
		v := -1
		for u := 0; u < n; u++ {
			if used[u] {
				continue
			}
			if v == -1 || minCost[u] < minCost[v] {
				v = u
			}
		}
		if v == -1 {
			break
		}
		used[v] = true
		res += minCost[v]
		for u := 0; u < n; u++ {
			cx := x[u] - x[v]
			if cx < 0 {
				cx = -cx
			}
			cy := y[u] - y[v]
			if cy < 0 {
				cy = -cy
			}
			if cx > cy {
				cx = cy
			}
			if cx < minCost[u] {
				minCost[u] = cx
			}
		}
	}
	con.Println(res)
	return nil
}

