type UnionFind struct {
	parent []int
	rank   []int
}

func NewUnionFind(n int) *UnionFind {
	u := &UnionFind{
		parent: make([]int, n),
		rank:   make([]int, n),
	}

	for i := range u.parent {
		u.parent[i] = i
		u.rank[i] = 0
	}

	return u
}

func (u *UnionFind) Find(i int) int {
	if u.parent[i] == i {
		return i
	}
	p := u.Find(u.parent[i])
	u.parent[i] = p
	return p
}

func (u *UnionFind) Union(i, j int) {
	pi := u.Find(i)
	pj := u.Find(j)

	if pi == pj {
		return
	}

	if u.rank[pi] > u.rank[pj] {
		u.parent[pj] = pi
	} else {
		u.parent[pi] = pj
		if u.rank[pi] == u.rank[pj] {
			u.rank[pj]++
		}
	}
}

