var par []int

func main() {
	var n int
	fmt.Scan(&n)
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	ps := make([][]int, n)
	for i := range ps {
		sc.Scan()
		x, _ := strconv.Atoi(sc.Text())
		sc.Scan()
		y, _ := strconv.Atoi(sc.Text())
		ps[i] = []int{x, y, i}
	}
	rs := make([][]int, 0)

	sort.Slice(ps, func(i, j int) bool { return ps[i][0] < ps[j][0] })
	for i := 0; i < n-1; i++ {
		cost := ps[i+1][0] - ps[i][0]
		rs = append(rs, []int{ps[i][2], ps[i+1][2], cost})
	}

	sort.Slice(ps, func(i, j int) bool { return ps[i][1] < ps[j][1] })
	for i := 0; i < n-1; i++ {
		cost := ps[i+1][1] - ps[i][1]
		rs = append(rs, []int{ps[i][2], ps[i+1][2], cost})
	}

	sort.Slice(rs, func(i, j int) bool { return rs[i][2] < rs[j][2] })
	par = make([]int, n)
	for i := range par {
		par[i] = i
	}
	var ans int
	for i := range rs {
		a, b := rs[i][0], rs[i][1]
		if same(a, b) {
			continue
		}
		ans += rs[i][2]
		unite(a, b)
	}
	fmt.Println(ans)
}

func root(x int) int {
	if par[x] == x {
		return x
	}
	par[x] = root(par[x])
	return par[x]
}

func unite(x, y int) {
	rx := root(x)
	ry := root(y)
	if rx == ry {
		return
	}
	par[rx] = ry
}

func same(x, y int) bool {
	return root(x) == root(y)
}

