type UnionFindTree struct {
	parent	map[int]int
	size	map[int]int
	rank	map[int]int
}

func NewUnionFindTree() *UnionFindTree {
	u := new(UnionFindTree)
	u.parent = make(map[int]int)
	u.size = make(map[int]int)
	u.rank = make(map[int]int)
	return u
}

func (u UnionFindTree) Add(a int) {
	u.parent[a] = -1
	u.size[a] = 1
	u.rank[a] = 0
}

func (u UnionFindTree) Root(a int) int {
	if u.parent[a] == -1 {
		return a
	} else {

		u.parent[a] = u.Root(u.parent[a])
		return u.parent[a]
	}
}

func (u UnionFindTree) Unite(a, b int) {
	a, b = u.Root(a), u.Root(b)
	if a == b {
		return
	}
	if u.rank[a] == u.rank[b] {
		u.rank[a] += 1
	} else if u.rank[a] < u.rank[b] {
		a, b = b, a
	}
	u.parent[b] = a
	u.size[a] += u.size[b]
}

func (u UnionFindTree) IsSame(a, b int) bool {
	return u.Root(a) == u.Root(b)
}

func (u UnionFindTree) Size(a int) int {
	return u.size[u.Root(a)]
}

func (u UnionFindTree) Groups() map[int][]int {
	ret := make(map[int][]int)
	for k := range u.parent {
		r := u.Root(k)
		if len(ret[r]) == 0 {
			ret[r] = []int{}
		}
		ret[r] = append(ret[r], k)
	}
	return ret
}

