alias Edge = Tuple!(int, "s", int, "t", int, "cost");

long kruskal(int N, Edge[] es) {
    long res = 0;
    es.sort!"a.cost < b.cost"();
    auto uf = UnionFind(N);
    while (uf.cc > 1) {
        auto e = es.front; es.popFront();
        auto u = e.s, v = e.t, c = e.cost;
        if (!uf.same(u, v)) {
            uf.merge(u, v);
            res += c;
        }
    }
    return res;
}

