    foreach (i; 0..N) {
        auto xy = readln.split.to!(int[]);
        xs ~= T(i, xy[0]);
        ys ~= T(i, xy[1]);
    }
    sort!"a.p < b.p"(xs);
    sort!"a.p < b.p"(ys);

    auto pq = priority_queue!("a.c < b.c", Path)();
    foreach (i; 0..N-1) {
        auto x1 = xs[i];
        auto x2 = xs[i+1];
        pq.enqueue(Path(x1.i, x2.i, abs(x1.p - x2.p)));
        auto y1 = ys[i];
        auto y2 = ys[i+1];
        pq.enqueue(Path(y1.i, y2.i, abs(y1.p - y2.p)));
    }

    auto uft = uftree!long(N);
    long cs;
    while (!pq.empty) {
        auto h = pq.dequeue();
        if (uft.is_same(h.a, h.b)) continue;
        uft.unite(h.a, h.b);
        cs += h.c;
    }
    writeln(cs);
}

