class UnionFind{
  int[] par;
  this(int n){
    par.length=n;
    foreach(i; 0..n) par[i]=i;
  }
  int find(int i){
    return par[i]=(i==par[i] ? par[i] : find(par[i]));
  }
  void unite(int i, int j){
    par[find(i)]=find(j);
  }
  bool same(int i, int j){
    return find(i)==find(j);
  }
}

