def compute_mst_kruskal(max_v, edges):
    edges.sort(key=lambda edge: edge.weight)
    uf = UnionFind(max_v)
    weight = 0

    for edge in edges:
        if not uf.same(edge.start, edge.end):
            uf.unite(edge.start, edge.end)
            weight+=edge.weight
    return weight

