def minimum(C, visited):
    min_index = -1
    min_cost = 10**9
    for v in visited:
        for i in xrange(0, len(C)):
            if i not in visited:
                cost = min(abs(C[i][0] - C[v][0]), abs(C[i][1] - C[v][1]))
                if cost < min_cost:
                    min_index = i
                    min_cost = cost
    return min_index, min_cost

