def main():
    n = int(sys.stdin.readline().strip())
    xy = []
    for _ in range(n):
        xy.append(map(int, sys.stdin.readline().strip().split(" ")))

    table = [-1 for _ in xrange(n)]

    def find(x):
        if table[x] < 0:
            return x
        else:
            table[x] = find(table[x])
            return table[x]

    def union(x, y):
        s1 = find(x)
        s2 = find(y)
        if s1 != s2:
            if table[s1] <= table[s2]:
                table[s1] += table[s2]
                table[s2] = s1
            else:
                table[s2] += table[s1]
                table[s1] = s2
            return True
        return False

    costs = []
    for i in range(n):
        for j in range(i + 1, n):
            ax, ay = xy[i]
            bx, by = xy[j]
            costs.append((i, j, min(abs(ax - bx), abs(ay - by))))
    costs.sort(key=lambda (x, y, c): c)

    visited = set()
    result = 0
    while len(costs) > 0:
        x, y, c = costs.pop(0)
        if x in visited and y in visited:
            pass
        if union(x, y):
            visited.add(x)
            visited.add(y)
            result += c
        # print(x, y, c)
    print(result)


