import sys
import heapq

def solve(N: int, x: "List[int]", y: "List[int]"):
    ## プリム法
    ## 0~N-1の町がある

    isUsed = [False]*N
    isUsed[0]=True
    priority_queue = [] # (cost,node)
    for i in range(1,N):
        heapq.heappush(priority_queue,(min(abs(x[0]-x[i]),abs(y[0]-y[i])),i))

    answer = 0
    while priority_queue:
        cost,node = heapq.heappop(priority_queue)

        if isUsed[node]:
            continue
        else:
            isUsed[node] = True

        answer += cost
        for i in range(N):
            if isUsed[i]:
                continue
            heapq.heappush(priority_queue,(min(abs(x[node]-x[i]),abs(y[node]-y[i])),i))
    print(answer)
    return


