        if table[x] < 0:
            return x
        else:
            # 経路の圧縮
            table[x] = find(table[x])
            return table[x]

    def union(x, y):
        s1 = find(x)
        s2 = find(y)
        if s1 != s2:
            if table[s1] <= table[s2]:
                # 小さいほうが個数が多い
                table[s1] += table[s2]
                table[s2] = s1
            else:
                table[s2] += table[s1]
                table[s1] = s2
