class PriorityQueue:
    def __init__(self):
        self.__heap = []
        self.__count = 0

    def empty(self) -> bool:
        return self.__count == 0

    def dequeue(self):
        if self.empty():
            raise Exception('empty')
        self.__count -= 1
        return heapq.heappop(self.__heap)

    def enqueue(self, v):
        self.__count += 1
        heapq.heappush(self.__heap, v)

    def __len__(self):
        return self.__count


def kruskal(edges: list, size: int)->list:
    q = PriorityQueue()
    for c, u, v in edges:
        q.enqueue((c, u, v))
    uf = UnionFind(size)

    min_tree = []
    while not q.empty():
        c, u, v = q.dequeue()

        if not uf.same(u, v):
            uf.union(u, v)
            min_tree.append((c, u, v))

    return min_tree


