import heapq
INF = float("inf")


class Graph(object):

    def __init__(self, N):
        self.N = N
        self.V = list(range(N))
        self.E = []

    def add_edge(self, edge):
        """
        args:
          edge : (from_, to_, weight)
        """
        if len(edge) == 2:
            edge.append(1)
        elif len(edge) != 3:
            print("error in add_edge")
            pass
        s, t, w = edge
        if s > t:
            s, t = t, s
        self.E.append([s, t, w])


class UnionFind(object):
    """UnionFind木
    """

    def __init__(self, N):
        self.tree = list(range(N))

    def root(self, i):
        if self.tree[i] == i:
            return i
        else:
            self.tree[i] = self.root(self.tree[i])
            return self.tree[i]

    def same(self, x, y):
        return self.root(x) == self.root(y)

    def unite(self, x, y):
        x = self.root(x)
        y = self.root(y)
        if x != y:
            self.tree[x] = y


def Kruskal(g):
    edges = []
    for from_, to_, weight in g.E[from_]:
        heapq.heappush(edges, [weight, from_, to_])

    tree = Graph(g.N)
    group = UnionFind(g.N)
    while len(edges) > 0:
        w_, f_, t_ = heapq.heappop(edges)
        if not group.same(f_, t_):
            tree.add_edge([f_, t_, w_])
            group.unite(f_, t_)
    return tree


def solve(N: int, x: "List[int]", y: "List[int]"):

    XYN = sorted(zip(x, y, range(N)))
    YXN = sorted(zip(y, x, range(N)))
    g = Graph(N)
    for i in range(N-1):
        (x1, y1, n1), (x2, y2, n2) = XYN[i:i+2]
        g.add_edge([n1, n2, min(abs(x1-x2), abs(y1-y2))])
        (x1, y1, n1), (x2, y2, n2) = YXN[i:i+2]
        g.add_edge([n1, n2, min(abs(y1-y2), abs(x1-x2))])

    edges = []
    for from_, to_, weight in g.E:
        heapq.heappush(edges, [weight, from_, to_])

    tot = 0
    group = UnionFind(g.N)
    while len(edges) > 0:
        w_, f_, t_ = heapq.heappop(edges)
        if not group.same(f_, t_):
            tot += w_
            group.unite(f_, t_)

    print(tot)
    return


