def Prim(g):
    V = list(g.keys())
    for v in g.values():
        V.extend(list(v.keys()))
    V = list(set(V))

    key = {}
    pred = {}
    in_q = set(V)
    for v in V:
        key[v] = sys.maxsize
        pred[v] = -1

    key[V[0]] = 0
    q = []
    for v in V:
        heapq.heappush(q, (key[v], v))

    while q:
        _, u = heapq.heappop(q)
        for v in g[u].keys():
            w = g[u][v]
            if w < key[v]:
                pred[v] = u
                key[v] = w
                heapq.heappush(q, (key[v], v))
    return pred


