fn main() {
    input! {
        n: usize,
        cs: [(usize, usize); n],
    }

    let mut ans = 0;
    let mut xs = std::collections::BTreeSet::new();
    let mut ys = std::collections::BTreeSet::new();

    for (idx, c) in cs.iter().enumerate() {
        xs.insert((c.0, idx));
        ys.insert((c.1, idx));
    }

    let mut dp = vec![std::collections::BTreeSet::new(); n];
    let mut gone = vec![false; n];

    let mut min = (std::usize::MAX, (0, 0));

    let mut last = (0, 0);
    for e in xs {
        if e.1 == 0 {
            last = e;
            continue;
        }

        let diff = std::cmp::max(e.0, last.0) - std::cmp::min(e.0, last.0);
        if min.0 > diff {
            min = (diff, (last.1, e.1));
        }
        dp[last.1].insert((diff, e.1));
        dp[e.1].insert((diff, last.1));

        last = e;
    }

    let mut last = (0, 0);
    for e in ys {
        if e.1 == 0 {
            last = e;
            continue;
        }

        let diff = std::cmp::max(e.0, last.0) - std::cmp::min(e.0, last.0);
        if min.0 > diff {
            min = (diff, (last.1, e.1));
        }
        dp[last.1].insert((diff, e.1));
        dp[e.1].insert((diff, last.1));

        last = e;
    }

    let mut q = std::collections::BinaryHeap::new();
    q.push(std::cmp::Reverse((min.0, (min.1).0)));
    q.push(std::cmp::Reverse((min.0, (min.1).1)));
    gone[(min.1).0] = true;
    gone[(min.1).1] = true;
    ans += min.0;

    while let Some(std::cmp::Reverse((diff, next))) = q.pop() {
        if !gone[next] {
            ans += diff;
            gone[next] = true;
        }

        for e in dp[next].iter() {
            if gone[e.1] {
                continue;
            }

            q.push(std::cmp::Reverse((e.0, e.1)));
        }
    }

    echo!(ans);
}

