fn solve() {
    let n = get!(usize);
    let xy = get!(isize, isize;n);

    let mut xyx = xy.into_iter().enumerate().map(|(i, (x,y))| (x,y,i)).collect::<Vec<_>>();
    let mut xyy = xyx.clone();

    xyx.sort_by_key(|e| e.0);
    xyy.sort_by_key(|e| e.1);

    let xyx = xyx.iter().zip(xyx.iter().skip(1)).map(|(&e1, &e2)| ((e1.0-e2.0).abs(), e1.2, e2.2)).collect::<Vec<_>>();
    let xyy = xyy.iter().zip(xyy.iter().skip(1)).map(|(&e1, &e2)| ((e1.1-e2.1).abs(), e1.2, e2.2)).collect::<Vec<_>>();

    let mut vij = xyx.into_iter().chain(xyy.into_iter()).collect::<Vec<_>>();
    vij.sort_by_key(|e| e.0);

    let mut uftree = UnionFindRank::new(n+1);

    let mut sum = 0;
    for (v,i,j) in vij {
        if uftree.is_same(i,j) {
            continue;
        }
        uftree.unite(i,j);
        sum += v;
    }
    println!("{}", sum);
}

