struct HeapElement {
    from: usize,
    into: usize,
    val: usize,
}

struct Kruskal<'a> {
    heap: &'a mut Vec<HeapElement>,
    uf: Uf,
}

impl<'a> Kruskal<'a> {

    fn new(h: &'a mut Vec<HeapElement>) -> Self {
        Kruskal {
            heap: h,
            uf: Uf::new(100010),
        }
    }

    fn sort(&mut self) {
        self.heap.sort_by_key(|h| h.val);
    }

// heapはsortされていることを仮定
    fn kruskal(&mut self) -> usize {
        let mut count = 0;
        for h in self.heap.iter() {
            if !self.uf.same(h.from, h.into) {
                count = count + h.val;
                self.uf.unite(h.from, h.into);
            }
        }
        count
    }
}

struct Uf {
    par: Vec<usize>,
    rank: Vec<usize>,
}

impl Uf {
    fn new(n: usize) -> Uf {
        Uf {
            par: (0..n).collect(),
            rank: vec![0; n],
        }
    }

    fn root(&mut self, x: usize) -> usize {
        if self.par[x] == x { 
            return x; 
        } else { 
            let tmp = self.par[x];
            self.par[x] = self.root(tmp);
            return self.par[x];
        };
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }

    fn unite(&mut self, x: usize, y: usize) {
        let a = self.root(x);
        let b= self.root(y);

        if a == b {
            return;
        }

        if self.rank[a] < self.rank[b] {
            self.par[a] = b;
        } else {
            self.par[b] = a;
            if self.rank[a] == self.rank[b] {
                self.rank[x] = self.rank[x] + 1;
            }
        }
    }

}

