pub mod mst {
	use super::*;

	impl<T> Graph<T>
	where
		T: Clone + Ord + num::Zero,
	{
		pub fn prim(&self) -> T {
			let mut r = T::zero();
			let mut used = vec![false; self.size()];
			let mut q = std::collections::BinaryHeap::new();
			use std::cmp::Reverse;
			q.push((Reverse(T::zero()), 0));
			while let Some((Reverse(cost), v)) = q.pop() {
				let v = v as usize;
				if used[v] {
					continue;
				}
				used[v] = true;
				r = r + cost;
				for Edge { dst, cost, .. } in self.edges[v].iter() {
					q.push((Reverse(cost.clone()), *dst));
				}
			}
			r
		}
	}
}

