#[derive(Debug, PartialEq, Clone)]
struct Node {
    parent: Option<usize>, 
    size: usize,
}

#[derive(Debug, PartialEq)]
pub struct UnionFind {
    tree: Vec<Node>,
}

impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        UnionFind {tree: vec![Node {parent: None, size: 1}; n]}
    }

    pub fn unite(&mut self, i: usize, j: usize) {
        let root_i = self.find(i);
        let root_j = self.find(j);
        if root_i == root_j {
            return
        }

        if self.tree[root_i].size < self.tree[root_j].size {
            self.tree[root_i].size += self.tree[root_j].size;
            self.tree[root_j].parent = Some(root_i);
        } else {
            self.tree[root_j].size += self.tree[root_i].size;
            self.tree[root_i].parent = Some(root_j);
        }

    }

    pub fn find(&mut self, i: usize) -> usize {
        match self.tree[i].parent {
            Some(p) => {
                let root = self.find(p);
                self.tree[i].parent = Some(root);
                root
            },
            None => i
        }
    }

    pub fn equiv(&mut self, i: usize, j: usize) -> bool {
        self.find(i) == self.find(j)
    }

    pub fn size(&mut self, i: usize) -> usize {
        let root = self.find(i);
        self.tree[root].size
    }
}

fn kruskal(n: usize, x_dist: &mut BinaryHeap<Edge>, y_dist: &mut BinaryHeap<Edge>) -> i64 {
    let mut union_find = UnionFind::new(n);
    let mut cost = 0;
    while x_dist.len() > 0 || y_dist.len() > 0 {
        let edge: Edge;
        if x_dist.is_empty() {
            edge = y_dist.pop().unwrap();
        } else if y_dist.is_empty() {
            edge = x_dist.pop().unwrap();
        } else {
            if x_dist.peek().unwrap().cost < y_dist.peek().unwrap().cost {
                edge = y_dist.pop().unwrap()
            } else {
                edge = x_dist.pop().unwrap();
            }
        }
        // println!("{:?}", edge);

        if !union_find.equiv(edge.from, edge.to) {
            cost += edge.cost;
            union_find.unite(edge.from, edge.to);
        }
    }
    cost
}

