pub mod mst {
	use super::*;

	impl<T> Graph<T>
	where
		T: Clone + Ord + num::Zero,
	{
		pub fn kruskal(&self) -> T {
			let mut r = T::zero();
			let mut edges = vec![];
			for i in 0..self.size() {
				for e in self.edges[i].iter() {
					edges.push((e.cost.clone(), i as u32, e.dst));
				}
			}
			edges.sort_by_key(|a| a.0.clone());
			let mut uf = super::UnionFind::new(self.size());
			for (cost, src, dst) in edges {
				if uf.unite(src as usize, dst as usize) {
					r = r + cost;
				}
			}
			r
		}
	}
}

