use std::collections::BinaryHeap;

fn main() {
    input!(n: usize, xy: [(i64, i64); n]);
    let mut xy = xy
        .iter()
        .enumerate()
        .map(|(i, &(x, y))| (i, x, y))
        .collect::<Vec<_>>();
    let mut heap = BinaryHeap::new();

    xy.sort_by_key(|&(_, x, _)| x);
    for i in 1..n {
        let (p, px, _) = xy[i - 1];
        let (n, nx, _) = xy[i];
        heap.push(Edge {
            from: p,
            to: n,
            cost: nx - px,
        });
    }
    xy.sort_by_key(|&(_, _, y)| y);
    for i in 1..n {
        let (p, _, py) = xy[i - 1];
        let (n, _, ny) = xy[i];
        heap.push(Edge {
            from: p,
            to: n,
            cost: ny - py,
        });
    }

    let mut uf = UnionFind::new(n);
    let mut ans = 0;
    while let Some(Edge { from, to, cost }) = heap.pop() {
        if uf.find(to) == uf.find(from) {
            continue;
        }
        uf.unite(from, to);
        ans += cost;
    }
    println!("{}", ans);
}

#[derive(Copy, Clone, Eq, PartialEq, Debug)]
struct Edge {
    from: usize,
    to: usize,
    cost: i64,
}

impl Ord for Edge {
    fn cmp(&self, other: &Edge) -> std::cmp::Ordering {
        other.cost.cmp(&self.cost)
    }
}

impl PartialOrd for Edge {
    fn partial_cmp(&self, other: &Edge) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

pub struct UnionFind {
    parent: Vec<usize>,
    sizes: Vec<usize>,
    size: usize,
}

impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        UnionFind {
            parent: (0..n).map(|i| i).collect::<Vec<usize>>(),
            sizes: vec![1; n],
            size: n,
        }
    }

    pub fn find(&mut self, x: usize) -> usize {
        if x == self.parent[x] {
            x
        } else {
            let px = self.parent[x];
            self.parent[x] = self.find(px);
            self.parent[x]
        }
    }

    pub fn unite(&mut self, x: usize, y: usize) -> bool {
        let parent_x = self.find(x);
        let parent_y = self.find(y);
        if parent_x == parent_y {
            return false;
        }

        let (large, small) = if self.sizes[parent_x] < self.sizes[parent_y] {
            (parent_y, parent_x)
        } else {
            (parent_x, parent_y)
        };

        self.parent[small] = large;
        self.sizes[large] += self.sizes[small];
        self.sizes[small] = 0;
        self.size -= 1;
        return true;
    }
}

