struct DisjointSet {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl DisjointSet {
    fn new(n: usize) -> DisjointSet {
        DisjointSet {
            parent: (0..n).collect(),
            size: vec![1; n],
        }
    }
    fn root(&mut self, x: usize) -> usize {
        if x == self.parent[x] {
            x
        } else {
            // 根に直接繋ぐ
            self.parent[x] = self.root(self.parent[x]);
            self.parent[x]
        }
    }
    fn merge(&mut self, x: usize, y: usize) {
        let x = self.root(x);
        let y = self.root(y);
        if x == y {
            return;
        }
        if self.size[x] > self.size[y] {
            self.size[x] += self.size[y];
            self.parent[y] = x;
        } else {
            self.size[y] += self.size[x];
            self.parent[x] = y;
        }
    }
    fn same(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }

    // fn sizeof(&mut self, x: usize) -> usize {
    //     let x = self.root(x);
    //     self.sizeof[x]
    // }
}

fn kruskal(edges: &mut Vec<Edge>) -> i64 {
    let n: usize = edges.len();

    edges.sort();

    let mut ds = DisjointSet::new(n);
    let mut res: i64 = 0;
    for e in edges.iter() {
        if ds.same(e.from, e.to) {
            continue;
        }
        ds.merge(e.from, e.to);
        res += e.cost;
    }
    res
}

