use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        ps: [(i64,i64); n],
    }
    let mut heap = BinaryHeap::new();
    // x
    let mut ps2: Vec<(i64, i64, usize)> = ps
        .iter()
        .enumerate()
        .map(|(i, &(x, y))| (x, y, i))
        .collect();
    ps2.sort();
    for k in 1..n {
        let (x1, y1, i1) = ps2[k - 1];
        let (x2, y2, i2) = ps2[k];
        let d = min((x1 - x2).abs(), (y1 - y2).abs());
        heap.push((-d, i1, i2));
    }
    // y
    let mut ps2: Vec<(i64, i64, usize)> = ps
        .iter()
        .enumerate()
        .map(|(i, &(x, y))| (y, x, i))
        .collect();
    ps2.sort();
    for k in 1..n {
        let (y1, x1, i1) = ps2[k - 1];
        let (y2, x2, i2) = ps2[k];
        let d = min((x1 - x2).abs(), (y1 - y2).abs());
        heap.push((-d, i1, i2));
    }
    let mut uf = UnionFind::new(n);
    let mut res = 0;
    while uf.num(0) != n {
        let (d, i1, i2) = heap.pop().unwrap();
        let d = -d;
        if !uf.is_same_set(i1, i2) {
            res += d;
            uf.unite(i1, i2);
        }
    }
    writeln!(buf, "{}", res);
    buf
}

