fn prim(graph: &[Vec<(usize, i64)>]) -> i64 {
    let mut visited = vec![false; graph.len()];
    let mut ret = 0;
    let mut heap = BinaryHeap::new();

    heap.push((0, 0));
    while let Some((d, v)) = heap.pop() {
        if visited[v] {
            continue;
        }
        ret += -d;
        visited[v] = true;
        for &(i, dist) in graph[v].iter() {
            if !visited[i] {
                heap.push((-dist, i))
            }
        }
    }
    ret
}
