    for i in 0..n {
        points[i].0 = read::<i64>();
        points[i].1 = read::<i64>();
        points[i].2 = i;
    }
    let mut edges = vec![];
    for _ in 0..2 {
        points.sort();
        for i in 0..n - 1 {
            let d = (points[i + 1].0 - points[i].0).abs();
            let from = points[i].2;
            let to = points[i + 1].2;
            edges.push((d, from, to));
        }
        for i in 0..n {
            let t = points[i].0;
            points[i].0 = points[i].1;
            points[i].1 = t;
        }
    }
    edges.sort();
    let mut ans = 0;
    let mut ufind = UnionFind::new(n);
    for &(cost, from, to) in edges.iter() {
        if ufind.union_set(from, to) {
            ans += cost;
        }
    }
