struct UnionFind {
    parents: Vec<isize>,
}
impl UnionFind {
    fn new(n: usize) -> UnionFind {
        let parents = vec![-1; n];
        UnionFind { parents: parents }
    }
    fn find(&mut self, x: usize) -> usize {
        if self.parents[x] < 0 {
            x
        } else {
            let xx = self.parents[x] as usize;
            let y = self.find(xx);
            self.parents[x] = y as isize;
            y
        }
    }
    fn union(&mut self, x: usize, y: usize) {
        let mut x = self.find(x);
        let mut y = self.find(y);
        if x == y {
            return;
        }
        if self.parents[x] > self.parents[y] {
            std::mem::swap(&mut x, &mut y);
        }
        self.parents[x] += self.parents[y];
        self.parents[y] = x as isize;
    }
    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }
}
fn dist(x: usize, y: usize) -> isize {
    (x as isize - y as isize).abs()
}
use std::collections::BinaryHeap;
fn main() {
    input! { n, xy: [(usize, usize); n] };
    let mut xi = (0..n).into_iter().collect::<Vec<_>>();
    xi.sort_by_key(|&i| xy[i].0);
    let mut yi = (0..n).into_iter().collect::<Vec<_>>();
    yi.sort_by_key(|&i| xy[i].1);
    let mut heap = BinaryHeap::new();
    for i in 0..(n - 1) {
        let x1 = xi[i];
        let x2 = xi[i + 1];
        heap.push((-dist(xy[x1].0, xy[x2].0), x1, x2));
        let y1 = yi[i];
        let y2 = yi[i + 1];
        heap.push((-dist(xy[y1].1, xy[y2].1), y1, y2));
    }
    let mut ans = 0;
    let mut uf = UnionFind::new(n);
    while let Some((c, i, j)) = heap.pop() {
        if !uf.same(i, j) {
            ans -= c;
            uf.union(i, j);
        }
    }
    println!("{}", ans);
}

fn main() {
    use std::io::Read;
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let n: usize = iter.next().unwrap().parse::<usize>().unwrap();
    let mut cities = vec![];
    for i in 0..n {
        let x: u64 = iter.next().unwrap().parse::<u64>().unwrap();
        let y: u64 = iter.next().unwrap().parse::<u64>().unwrap();
        cities.push((y,x,i));
    }

    let mut edges = vec![];
    // sort by y
    cities.sort_by_key(|c| c.0);
    for i in 0..n-1 {
        let cur = cities[i];
        let next = cities[i+1];
        edges.push((next.0 - cur.0, cur.2, next.2));
    }
    cities.sort_by_key(|c| c.1);
    for i in 0..n-1 {
        let cur = cities[i];
        let next = cities[i+1];
        edges.push((next.1 - cur.1, cur.2, next.2));
    }

    println!("{}", kruskal(&mut edges, n));
}

pub fn kruskal(edges: &mut [(u64, usize, usize)], n: usize) -> u64 {
    edges.sort();
    let mut utree = Utree::new(n);
    let mut ret = 0u64;
    for &(c, p, q) in &*edges {
        if !utree.is_same(p, q) {
            utree.unite(p, q);
            ret += c;
        }
    }
    ret
}

#[allow(dead_code)]
pub struct Utree {
    n: usize,
    par: Vec<usize>,
    rank: Vec<usize>,
    size: Vec<usize>,
}
#[allow(dead_code)]
impl Utree {
    pub fn new(n: usize) -> Utree {
        let par: Vec<usize> = (0..n).collect();
        let rank: Vec<usize> = vec![0; n];
        let size: Vec<usize> = vec![1; n];
        Utree {
            n: n,
            par: par,
            rank: rank,
            size: size,
        }
    }
    pub fn find(&mut self, x: usize) -> usize {
        if self.par[x] == x {
            x
        } else {
            let parent = { self.par[x] };
            let ret = self.find(parent);
            self.par[x] = ret;
            ret
        }
    }
    pub fn unite(&mut self, x: usize, y: usize) {
        let x_root = self.find(x);
        let y_root = self.find(y);
        if x_root == y_root {
            return;
        };
        if self.rank[x_root] < self.rank[y_root] {
            self.par[x_root] = y_root;
            self.size[y_root] += self.size[x_root];
        } else {
            self.par[y_root] = x_root;
            self.size[x_root] += self.size[y_root];
            if self.rank[x_root] == self.rank[y_root] {
                self.rank[x_root] += 1;
            }
        }
    }
    pub fn is_same(&mut self, x: usize, y: usize) -> bool {
        let x_root = self.find(x);
        let y_root = self.find(y);
        x_root == y_root
    }
    pub fn get_size(&mut self, x: usize) -> usize {
        let x_root = self.find(x);
        self.size[x_root]
    }
}

