        .collect::<HashSet<_>>()
        .iter()
        .cloned()
        .collect();

    let xs: Vec<_> = {
        let mut t: Vec<_> = towns.iter().map(|&(x, _)| x).zip(0..).collect();
        t.sort();
        t
    };
    let ys: Vec<_> = {
        let mut t: Vec<_> = towns.iter().map(|&(_, y)| y).zip(0..).collect();
        t.sort();
        t
    };

    let mut costs: Vec<_> = xs.windows(2)
        .chain(ys.windows(2))
        .map(|w| (w[1].0 - w[0].0, w[0].1, w[1].1))
        .collect();
    costs.sort();

    let mut uft = UFT::new(towns.len());
    let mut a = 0;
    let mut e = 0;

    for &(c, from, to) in costs.iter() {
        if !uft.same(from, to) {
            uft.unite(from, to);
            a += c;
            e += 1;
        }

        if e >= towns.len() - 1 {
            break;
        }
    }

    println!("{}", a);
}

struct UFT {
    parents: Vec<usize>,
    rank: Vec<usize>,
}

impl UFT {
    fn new(n: usize) -> UFT {
        UFT {
            parents: (0..n + 1).collect(),
            rank: vec!(0; n),
        }
    }

    fn find(&mut self, i: usize) -> usize {
        if self.parents[i] == i {
            i
        } else {
            let p1 = self.parents[i];
            let p = self.find(p1);
            self.parents[i] = p;
            p
        }
    }

    fn unite(&mut self, x: usize, y: usize) {
        let xp = self.find(x);
        let yp = self.find(y);

        if xp != yp {
            if self.rank[xp] < self.rank[yp] {
                self.parents[xp] = yp;
            } else {
                self.parents[yp] = xp;
                if self.rank[xp] == self.rank[yp] {
                    self.rank[xp] += 1;
                }
            }
        }
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }
}

