fn main() {
    let mut scanner = Scanner::new(stdin());
    let n = scanner.read::<usize>().unwrap();
    let mut points = vec![];
    let mut horizontal = vec![];
    let mut vertical = vec![];
    for i in 0..n {
        let line = scanner.read_vector::<i64>().unwrap();
        points.push((line[0], line[1]));
        horizontal.push((line[0], line[1], i));
        vertical.push((line[1], line[0], i));
    }
    horizontal.sort();
    vertical.sort();

    let mut sum = 0;
    let mut used = vec![false; n];
    let mut heap = BinaryHeap::new();
    heap.push(encode(0, 0));
    while heap.len() > 0 {
        let (crt, cost) = decode(heap.pop().unwrap());
        if used[crt] {
            continue;
        }
        sum += cost;
        used[crt] = true;
        let (x, y) = points[crt];
        let index_1 = horizontal.binary_search(&(x, y, crt)).unwrap();
        update(index_1, &horizontal, x, &mut heap);
        let index_2 = vertical.binary_search(&(y, x, crt)).unwrap();
        update(index_2, &vertical, y, &mut heap);
    }
    println!("{}", sum);
}

fn encode(p: usize, c: i64) -> (i64, usize) {
    (-c, p)
}

fn decode(item: (i64, usize)) -> (usize, i64) {
    (item.1, -item.0)
}

fn update(i: usize, arr: &[(i64, i64, usize)], val: i64, heap: &mut BinaryHeap<(i64, usize)>) {
    if i > 0 {
        let p = arr[i - 1];
        heap.push(encode(p.2, (p.0 - val).abs()));
    }
    if i < arr.len() - 1 {
        let p = arr[i + 1];
        heap.push(encode(p.2, (p.0 - val).abs()));
    }
}

