/// Union Find Tree
pub struct UFT {
    pub par: Vec<usize>,
    pub rank: Vec<usize>,
}
impl UFT {
    #[allow(dead_code)]
    pub fn new(n: usize) -> Self {
        UFT {
            par: (0..n).collect(),
            rank: vec![0; n],
        }
    }
    #[allow(dead_code)]
    pub fn root(&mut self, x: usize) -> usize {
        if self.par[x] == x {
            x
        } else {
            let p = self.par[x];
            let pp = self.root(p);
            self.par[x] = pp;
            pp
        }
    }
    #[allow(dead_code)]
    pub fn merge(&mut self, x: usize, y: usize) {
        let x = self.root(x);
        let y = self.root(y);
        if x == y {
            return;
        }
        if self.rank[x] < self.rank[y] {
            self.par[x] = y;
        } else {
            self.par[y] = x;
            if self.rank[x] == self.rank[y] {
                self.rank[x] += 1;
            }
        }
    }
}

fn solve() {
    let n = get!(usize);
    let xy = get!(u64, u64;n);

    let mut xx: Vec<(usize, u64)> = xy.iter().enumerate().map(|(i, &(x, _))| (i, x)).collect();
    let mut yy: Vec<(usize, u64)> = xy.iter().enumerate().map(|(i, &(_, y))| (i, y)).collect();

    xx.sort_by_key(|t| t.1);
    yy.sort_by_key(|t| t.1);

    let mut edges: Vec<((usize, usize), u64)> = xx.windows(2)
        .map(|v| ((v[0].0, v[1].0), v[1].1 - v[0].1))
        .chain(yy.windows(2).map(|v| ((v[0].0, v[1].0), v[1].1 - v[0].1)))
        .collect();

    edges.sort_by_key(|t| t.1);

    let mut uft = UFT::new(n);
    let mut ans = 0;

    for ((f, t), d) in edges {
        if uft.root(f) != uft.root(t) {
            uft.merge(f, t);
            ans += d;
        }
    }

    println!("{}", ans);
}

