mod union_find {

///素集合データ構造
pub struct UnionFind {
    v: Vec<usize>,
}

impl UnionFind {
    ///要素数nの素集合データ構造を構築する。
    pub fn new(n: usize) -> UnionFind {
        let mut v = Vec::new();
        for i in 0..n {
            v.push(i);
        }
        UnionFind { v: v }
    }

    ///親を探索する。
    pub fn find(&mut self, a: usize) -> usize {
        if a == self.v[a] {
            return a;
        }

        let buf = self.v[a];
        let parent = self.find(buf);
        self.v[a] = parent;
        parent
    }

    ///親が同じか判定する。
    pub fn same(&mut self, a: usize, b: usize) -> bool {
        self.find(a) == self.find(b)
    }

    ///結合する。
    pub fn union(&mut self, a: usize, b: usize) {
        let parent_a = self.find(a);
        let parent_b = self.find(b);
        self.v[parent_a] = parent_b;
    }
}
}

use input::*;
use union_find::*;

fn kruskal(e: &Vec<(usize, usize, usize)>, n: usize) -> usize {
    let mut uf = UnionFind::new(n);
    let mut res = 0;
    for i in e {
        let &(cost, from, to) = i;
        if uf.same(from, to) {
            continue;
        }

        res += cost;
        uf.union(from, to);
    }

    res
}
fn main() {
    let n: usize;
    input!(n);

    let mut v = vec![];
    let mut ex = vec![];

    for i in 0..n {
        let (a, b): (usize, usize);
        input!(a, b);
        v.push((a, b, i));
    }

    v.sort_by(|q, w| q.0.cmp(&w.0));

    for i in 1..n {
        ex.push((v[i].0 - v[i - 1].0, v[i].2, v[i - 1].2));
    }

    v.sort_by(|q, w| q.1.cmp(&w.1));
    for i in 1..n {
        ex.push((v[i].1 - v[i - 1].1, v[i].2, v[i - 1].2));
    }

    ex.sort();

    p(kruskal(&ex, n));
}

