use std::io::Read;
use std::cmp::max;
use std::cmp::min;
use std::str::FromStr;
use std::collections::HashMap;
use std::collections::HashSet;
use std::collections::BinaryHeap;

struct UnionFind{
    P: Vec<usize>,
}

impl UnionFind {
    fn new(n:usize) -> UnionFind{
        UnionFind {P:(0..n).collect()}
    }
    fn get_parent(&mut self,n:usize) -> usize{
        if self.P[n] == n{ return n;}
        let p = self.P[n];
        self.P[n] = self.get_parent(p);
        self.P[n]
    }
    fn is_unite(&mut self,x:usize,y:usize) -> bool{
        self.get_parent(x)==self.get_parent(y)
    }
    fn merge(&mut self,x:usize,y:usize){
        if self.is_unite(x,y) {return;}
        let i = self.get_parent(x);
        let j = self.get_parent(y);
        self.P[j] = i;
    }
}

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();
    let N = iter.next().unwrap().parse::<usize>().unwrap();
    let mut XY = (0..N).map(|i| (
            i,
            iter.next().unwrap().parse::<isize>().unwrap(),
            iter.next().unwrap().parse::<isize>().unwrap()
        )).collect::<Vec<_>>();

    XY.sort_by_key(|x| x.1);
    let mut dX = BinaryHeap::new();
    for i in 0..N-1{
        dX.push((XY[i].1-XY[i+1].1,XY[i].0,XY[i+1].0));
    }
    dX.push((-1e10 as isize,0,0));

    XY.sort_by_key(|x| x.2);
    let mut dY = BinaryHeap::new();
    for i in 0..N-1{
        dY.push((XY[i].2-XY[i+1].2,XY[i].0,XY[i+1].0));
    }
    dY.push((-1e10 as isize,0,0));

    let mut T = UnionFind::new(N);
    let mut ans = 0;

    for _ in 0..2*(N-1){
        let dx = dX.pop().unwrap();
        let dy = dY.pop().unwrap();
        let mut d = 0;
        let mut i = 0;
        let mut j = 0;
        if dx.0 > dy.0{
            dY.push(dy);
            d = -dx.0;
            i = dx.1;
            j = dx.2;
        } else {
            dX.push(dx);
            d = -dy.0;
            i = dy.1;
            j = dy.2;
        }
        if T.is_unite(i, j){continue;}
        ans += d;
        T.merge(i, j);
    }
    println!("{}",ans);


}

