use std::cmp::Reverse;

#[allow(dead_code)]
/// Prim's algorithm, O(E + V log V)
fn minimum_spanning_tree(g: &Graph, root: usize) -> (i32, Vec<Edge>) {
    let n = g.order();
    let mut total = 0;

    let mut visited = vec![false; n];
    let mut mst = vec![];
    let mut que = std::collections::BinaryHeap::new();  // max-heap
    que.push(Reverse(Edge{ src: root, dst: root, weight: 0 }));
    while let Some(Reverse(e)) = que.pop() {
        if visited[e.dst] {
            continue;
        }
        mst.push(e);
        total += e.weight;
        visited[e.dst] = true;
        for f in g[e.dst].iter() {
            if !visited[f.dst] {
                que.push(Reverse(*f));
            }
        }
    }
    (total, mst)
}

fn main() {
    input! {
        n: usize,
        xy: [(i32, i32); n],
    }

    let mut xpath = xy.iter().enumerate().map(|(i, &(x, _))| (x, i)).collect::<Vec<_>>();
    let mut ypath = xy.iter().enumerate().map(|(i, &(_, y))| (y, i)).collect::<Vec<_>>();
    xpath.sort();
    ypath.sort();

    let mut g = Graph::new(n);
    for i in 1..n {
        g.add_edge(xpath[i - 1].1, xpath[i].1, xpath[i].0 - xpath[i - 1].0);
        g.add_edge(ypath[i - 1].1, ypath[i].1, ypath[i].0 - ypath[i - 1].0);
    }
    let (ret, _) = minimum_spanning_tree(&g, 0);

    println!("{}", ret);
}

