use std::mem::swap;

struct UnionFind {
    parents: Vec<i64>,
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        UnionFind { parents: vec![-1; n] }
    }

    fn unite(&mut self, x: usize, y: usize) {
        let mut px = self.root(x);
        let mut py = self.root(y);
        if px == py {
            return;
        }
        if self.parents[x] < self.parents[y] {
            swap(&mut px, &mut py);
        }
        self.parents[px] += self.parents[py];
        self.parents[py] = px as i64;
    }

    fn root(&mut self, x: usize) -> usize {
        let px = self.parents[x];
        if px < 0 {
            return x;
        }
        self.parents[x] = self.root(px as usize) as i64;
        self.parents[x] as usize
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }

    fn size(&mut self, x: usize) -> usize {
        let px = self.root(x);
        -self.parents[px as usize] as usize
    }
}


fn main() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin.bytes().map(|c| c.unwrap() as char));
    let N: usize = sc.get();
    let mut x = vec![(0, 0); N];
    let mut y = vec![(0, 0); N];
    for i in 0..N {
        x[i] = (sc.get(), i);
        y[i] = (sc.get(), i);
    }
    x.sort();
    y.sort();
    let mut bh = BinaryHeap::new();
    for i in 0..N-1 {
        bh.push((Rev(x[i+1].0 - x[i].0), x[i].1, x[i+1].1));
        bh.push((Rev(y[i+1].0 - y[i].0), y[i].1, y[i+1].1));
    }
    let mut uf = UnionFind::new(N);
    let mut ans = 0usize;
    while let Some((Rev(d), i, j)) = bh.pop() {
        if !uf.same(i, j) {
            uf.unite(i, j);
            ans += d;
        }
    }
    println!("{}", ans);
}

