fn kruskal<T: Ord+Copy> (list: &Vec<(T,T,usize)>) -> usize {
    let mut edges: Vec<Edge<T>> = {
        let mut edges = Vec::new();
        for &(u,v,w) in list.iter() {
            edges.push(Edge::new((u,v),w));
        }
        edges.sort_by(|a,b| b.cmp(a));
        edges
    };
    let mut set = BTreeSet::new();

    let mut ans = 0;
    while let Some(edge) = edges.pop() {
        let (u,v) = edge.label;
        if !set.contains(&u) || !set.contains(&v) {
            ans += edge.value;
            set.insert(u);
            set.insert(v);
        }
    }
    ans
}

