	for i in 0..n - 1 {
		let (ax, _, ai) = a[i];
		let (bx, _, bi) = a[i + 1];
		let d = bx - ax;
		edges[ai].push((bi, d));
		edges[bi].push((ai, d));
	}
	a.sort_by_key(|a| a.1);
	for i in 0..n - 1 {
		let (_, ay, ai) = a[i];
		let (_, by, bi) = a[i + 1];
		let d = by - ay;
		edges[ai].push((bi, d));
		edges[bi].push((ai, d));
	}

	let mut ans = 0;
	let mut used = vec![false; edges.len()];
	let mut q = std::collections::BinaryHeap::new();
	q.push((0, 0));
	while let Some((cost, to)) = q.pop() {
		let cost = -cost;
		if used[to] {
			continue;
		}
		used[to] = true;
		ans += cost as i64;
		for &(to, cost) in edges[to].iter() {
			q.push((-cost, to));
		}
	}
	println!("{}", ans);
}

