fn _main() {
    let mut reader = reader::Reader::new();

    let n : usize = reader.next();
    type Index = usize;
    let mut vertex : Vec<(i32, i32, Index)> = Vec::with_capacity(n);
    for i in 0..n {
        let x : i32 = reader.next();
        let y : i32 = reader.next();
        vertex.push((x, y, i));
    }

    type Cost = i32;
    let mut edge : Vec<(Index, Index, Cost)> = Vec::with_capacity(n * 2);
    vertex.sort_by(|a, b| a.0.cmp(&b.0));
    for i in 0..n - 1 {
        edge.push((vertex[i].2, vertex[i + 1].2, vertex[i + 1].0 - vertex[i].0));
    }
    vertex.sort_by(|a, b| a.1.cmp(&b.1));
    for i in 0..n - 1 {
        edge.push((vertex[i].2, vertex[i + 1].2, vertex[i + 1].1 - vertex[i].1));
    }

    edge.sort_by(|a, b| a.2.cmp(&b.2));
    let mut uf = data::UnionFind::new(n);
    let mut cost = 0;
