fn kruskal(e: &Vec<(usize, usize, usize)>, n: usize) -> usize {
    let mut uf = UnionFind::new(n);
    let mut res = 0;
    for i in e {
        let (cost, from, to) = i;
        if uf.same(*from, *to) {
            continue;
        }

        res += *cost;
        uf.union(*from, *to);
    }

    res
}

