struct Edge {
    from: usize,
    to: usize,
    cost: i64,
}
impl Ord for Edge {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.cost.cmp(&other.cost)
    }
}
impl PartialOrd for Edge {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cost.cmp(&other.cost))
    }
}
impl Eq for Edge {}
impl PartialEq for Edge {
    fn eq(&self, other: &Self) -> bool {
        self.cost == other.cost
    }
}

struct DisjointSet {
    parent: Vec<usize>,
    sizeof: Vec<usize>,
}

impl DisjointSet {
    fn new(size: usize) -> DisjointSet {
        DisjointSet {
            parent: (0..size).collect(),
            sizeof: vec![1; size],
        }
    }
    fn root(&mut self, x: usize) -> usize {
        if x == self.parent[x] {
            x
        } else {
            self.parent[x] = self.root(self.parent[x]);
            self.parent[x]
        }
    }
    fn merge(&mut self, x: usize, y: usize) {
        let x = self.root(x);
        let y = self.root(y);
        if x == y {
            return;
        }
        if self.sizeof[x] > self.sizeof[y] {
            self.sizeof[x] += self.sizeof[y];
            self.parent[y] = x;
        } else {
            self.sizeof[y] += self.sizeof[x];
            self.parent[x] = y;
        }
    }
    fn same(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }
}

fn kruskal(edges: &mut Vec<Edge>) -> i64 {
    let n: usize = edges.len();

    // edgesをコストでソート
    edges.sort();

    let mut ds = DisjointSet::new(n);
    let mut res: i64 = 0;
    for e in edges.iter() {
        if ds.same(e.from, e.to) {
            continue;
        }
        ds.merge(e.from, e.to);
        res += e.cost;
    }
    res
}

