fn solve() {
    input!{
        N:usize,
        P:[(u64,u64);N],
    }
    let mut es = vec![];

    let mut ps = vec![];
    for i in 0..N {
        let p=P[i];
        ps.push((i,p.0,p.1));
    }
    // xでソート
    ps.sort_by_key(|&p| p.1);
    for i in 0..N-1 {
        let p0 = ps[i];
        let p1 = ps[i+1];
        let dist=p1.1-p0.1;
        es.push(Edge {u:p0.0, v:p1.0, cost:dist});
    }

    // yでソート
    ps.sort_by_key(|&p| p.2);
    for i in 0..N-1 {
        let p0 = ps[i];
        let p1 = ps[i+1];
        let dist=p1.2-p0.2;
        es.push(Edge {u:p0.0, v:p1.0, cost:dist});
    }

