struct UnionFindTree<T: Ord + Copy> {
    parents: Vec<T>,
}

impl<T: Ord + Copy + From<usize> + Into<usize> + Eq> UnionFindTree<T> {
    fn new(n: usize) -> UnionFindTree<T> {
        UnionFindTree {
            parents: (0..n).map(|i| i.into()).collect(),
        }
    }

    fn root(self: &mut Self, x: T) -> T {
        if self.parents[x.into()] == x {
            x
        } else {
            let r = self.root(self.parents[x.into()]);
            self.parents[x.into()] = r;
            r
        }
    }

    fn same(self: &mut Self, x: T, y: T) -> bool {
        self.root(x) == self.root(y)
    }

    fn unite(self: &mut Self, x: T, y: T) {
        let x = self.root(x);
        let y = self.root(y);
        if x != y {
            self.parents[x.into()] = y;
        }
    }
}

fn solve(n: usize, xy: &[(i32, i32)]) -> i32 {
    let mut xs = xy
        .iter()
        .enumerate()
        .map(|(i, &(x, _))| (x, i))
        .collect::<Vec<_>>();
    let mut ys = xy
        .iter()
        .enumerate()
        .map(|(i, &(_, y))| (y, i))
        .collect::<Vec<_>>();
    xs.sort();
    ys.sort();
    let mut e = xs
        .iter()
        .zip(xs.iter().skip(1))
        .map(|(&(x1, i), &(x2, j))| (x2 - x1, i, j))
        .chain(
            ys.iter()
                .zip(ys.iter().skip(1))
                .map(|(&(y1, i), &(y2, j))| (y2 - y1, i, j)),
        )
        .collect::<Vec<_>>();
    e.sort();
    let mut u = UnionFindTree::<usize>::new(n);
    let mut r = Vec::new();
    for &(d, i, j) in e.iter() {
        if !u.same(i, j) {
            r.push((d, i, j));
            u.unite(i, j);
        }
    }
    r.iter().map(|&(d, _, _)| d).sum()
}

fn main() {
    input! {
        n: usize,
        xy: [(i32, i32); n],
    }
    let r = solve(n, &xy);
    println!("{}", r);
}

