#[derive(Debug)]
pub struct UnionFind {
    par: Vec<usize>,
}
impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        let mut vec = vec![0; n];
        for i in 0..n {
            vec[i] = i;
        }
        UnionFind { par: vec }
    }
    pub fn find(&mut self, x: usize) -> usize {
        if x == self.par[x] {
            x
        } else {
            let par = self.par[x];
            let res = self.find(par);
            self.par[x] = res;
            res
        }
    }
    pub fn same(&mut self, a: usize, b: usize) -> bool {
        self.find(a) == self.find(b)
    }
    pub fn unite(&mut self, a: usize, b: usize) {
        let apar = self.find(a);
        let bpar = self.find(b);
        self.par[apar] = bpar;
    }
}

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      xys: [(usize,usize); n],
    }

    let mut xs: Vec<_> = xys.iter().cloned().enumerate().collect();
    xs.sort_by_key(|v| (v.1).0);
    let mut ys: Vec<_> = xys.iter().cloned().enumerate().collect();
    ys.sort_by_key(|v| (v.1).1);

    // クラシカル法
    let mut edges = vec![];
    for i in 0..n-1 {
        let (i1, (x1, _)) = xs[i];
        let (i2, (x2, _)) = xs[i+1];
        edges.push((i1, i2, x2-x1));
        let (i1, (_, y1)) = ys[i];
        let (i2, (_, y2)) = ys[i+1];
        edges.push((i1, i2, y2-y1));
    }
    edges.sort_by_key(|v| v.2);

    let mut uf = UnionFind::new(n);
    let mut ans = 0;
    for (u, v, c) in edges {
        if !uf.same(u, v) {
            uf.unite(u, v);
            ans += c;
        }
    }
    puts!("{}\n", ans);
}

