fn kruskal<T: Ord+Copy> (list: &Vec<(T,T,usize)>) -> usize {
    let mut edges: Vec<Edge<T>> = {
        let mut edges = Vec::new();
        for &(u,v,w) in list.iter() {
            edges.push(Edge::new((u,v),w));
        }
        edges.sort_by(|a,b| b.cmp(a));
        edges
    };
    let mut set = BTreeSet::new();

    let mut ans = 0;
    while let Some(edge) = edges.pop() {
        let (u,v) = edge.label;
        if !set.contains(&u) || !set.contains(&v) {
            ans += edge.value;
            set.insert(u);
            set.insert(v);
        }
    }
    ans
}

#[derive(Clone,Copy)]
struct Edge<T> {
    label: (T,T),
    value: usize,
}

impl<T> Edge<T> {
    fn new((u,v): (T,T), w: usize) -> Self {
        Edge { label: (u,v), value: w }
    } 
}

impl<T: Eq + Copy> Ord for Edge<T> {
    fn cmp(&self, other: &Self) -> Ordering {
        self.value.cmp(&other.value)
    }
}

impl<T: Eq + Copy> PartialOrd for Edge<T> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl<T: Eq + Copy> PartialEq for Edge<T> {
    fn eq(&self, other: &Self) -> bool {
        (self.label,self.value) == (other.label,other.value)
    }
}

impl<T: Eq + Copy> Eq for Edge<T> { }

