#[allow(dead_code)]
type Graph = Vec<Vec<usize>>;

struct UnionFind {
    parent: Vec<usize>,
    size: Vec<usize>,
    rank: Vec<usize>,
}

impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        let mut parent = vec![];
        for i in 0..n {
            parent.push(i);
        }
        UnionFind {
            parent: parent,
            size: vec![1; n],
            rank: vec![0; n],
        }
    }

    pub fn root(&mut self, x: usize) -> usize {
        if self.parent[x] == x {
            x
        } else {
            let parent = self.parent[x];
            self.parent[x] = self.root(parent);
            self.parent[x]
        }
    }

    pub fn unite(&mut self, x: usize, y: usize) {
        let x_root = self.root(x);
        let y_root = self.root(y);

        if x_root == y_root {
            return;
        }

        let sum = self.size[x_root] + self.size[y_root];
        self.size[x_root] = sum;
        self.size[y_root] = sum;

        if self.rank[x_root] < self.rank[y_root] {
            self.parent[x_root] = y_root;
        } else {
            self.parent[y_root] = x_root;
            if self.rank[x_root] == self.rank[y_root] {
                self.rank[x_root] += 1;
            }
        }
    }

    pub fn same(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }

    pub fn size(&mut self, x: usize) -> usize {
        let root = self.root(x);
        self.size[root]
    }
}

fn main() {
    input! {
        n: usize,
        p: [(usize, usize); n],
    }

    let mut p = p
        .iter()
        .enumerate()
        .map(|(i, &v)| (v.0, v.1, i))
        .collect::<Vec<_>>();
    let mut edges = vec![];
    p.sort_by_key(|v| v.0);
    for i in 0..p.len() - 1 {
        edges.push(((p[i + 1].0 - p[i].0), p[i].2, p[i + 1].2));
    }

    p.sort_by_key(|v| v.1);
    for i in 0..p.len() - 1 {
        edges.push(((p[i + 1].1 - p[i].1), p[i].2, p[i + 1].2));
    }

    edges.sort();

    let mut uf = UnionFind::new(n);

    let mut ans = 0;

    for &(c, a, b) in &edges {
        if !uf.same(a, b) {
            ans += c;
            uf.unite(a, b);
        }
    }

    println!("{}", ans);
}

macro_rules! get {
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
            get!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
            get!($($t),*)
        ).collect::<Vec<_>>()
    };
}

struct UnionFind {
    tree: Vec<usize>,
    rank: Vec<usize>,
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        UnionFind {
            tree : (0..n).collect::<Vec<_>>(),
            rank : vec![0;n],
        }
    }

    fn parent(&mut self, x: usize) -> usize {
        if x == self.tree[x] {
            x
        } else {
            let p = self.tree[x];
            let q = self.parent(p);
            self.tree[x] = q;
            q
        }
    }

    fn is_same(&mut self, a: usize, b: usize) -> bool {
        self.parent(a) == self.parent(b)
    }

    fn unite(&mut self, a: usize, b: usize) -> bool {
        let a = self.parent(a);
        let b = self.parent(b);
        if a == b {
            return false;
        }

        if self.rank[a] > self.rank[b] {
            self.tree[b] = a;
        } else {
            self.tree[a] = b;
            if self.rank[a] == self.rank[b] {
                self.rank[b] += 1;
            }
        }
        true
    }
}

use std::cmp::Ordering;
use std::collections::BinaryHeap;

#[derive(Copy, Clone, Eq, PartialEq)]
struct Road {
    a: usize,
    b: usize,
    c: i64
}

impl Ord for Road {
    fn cmp(&self, other: &Road) -> Ordering {
        other.c.cmp(&self.c)
    }
}

impl PartialOrd for Road {
    fn partial_cmp(&self, other: &Road) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn main() {
    let n = get!(usize);
    let mut xx = Vec::new();
    let mut yy = Vec::new();
    for i in 0..n {
        let (x, y) = get!(usize, usize);
        xx.push((i, x));
        yy.push((i, y));
    }
    xx.sort_by(|&(_, a), &(_, b)| a.cmp(&b));
    yy.sort_by(|&(_, a), &(_, b)| a.cmp(&b));

    let mut pq = BinaryHeap::new();

    for i in 1..n {
        let (x1, j) = xx[i-1];
        let (x2, k) = xx[i];
        pq.push(Road { a: x1, b: x2, c: (k-j) as i64 });
        let (y1, j) = yy[i-1];
        let (y2, k) = yy[i];
        pq.push(Road { a: y1, b: y2, c: (k-j) as i64 });
    }

    let mut uft = UnionFind::new(n);
    let mut cost = 0;
    while let Some(Road { a, b, c }) = pq.pop() {
        if !uft.is_same(a, b) {
            cost += c;
            uft.unite(a, b);
        }
    }
    println!("{}", cost);
}

use std::io::*;
