fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

struct UnionFind {
    par: Vec<usize>,
    rank: Vec<usize>,  
    size: Vec<usize>
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        let mut vec = vec![0; n];
        for i in 0..n {
            vec[i] = i;
        }
        UnionFind {
            par: vec, 
            rank: vec![0; n], 
            size: vec![1; n]
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if self.par[x] == x {
            x
        } else {
            let p = self.par[x];
            let pp = self.find(p);
            self.size[x] = self.size[pp];
            self.par[x] = pp;
            pp
        }
    }

    fn unite(&mut self, x: usize, y: usize) {
        let p_x = self.find(x);
        let p_y = self.find(y);
        if p_x != p_y {
            self.size[p_x] += self.size[p_y];
            self.size[p_y] = self.size[p_x];
            if self.rank[p_x] < self.rank[p_y] {
                self.par[p_x] = p_y;
            } else {
                self.par[p_y] = p_x;
                if self.rank[p_x] == self.rank[p_y] {
                    self.rank[p_x] += 1;
                }
            }
        }
    }

    fn are_same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }
}

#[derive(Clone)]
struct Edge {
    from: usize, 
    to: usize, 
    cost: u64
}

#[derive(Clone)]
struct Node {
    pos: u64, 
    idx: usize
}

fn main() {
    let N: usize = read();
    let mut edges: Vec<Edge> = vec![
        Edge{ from: 0, to: 0, cost: 0 }; N*2
    ];
    let mut x: Vec<Node> = vec![Node{ pos: 0, idx: 0}; N];
    let mut y: Vec<Node> = vec![Node{ pos: 0, idx: 0 }; N];

    for i in 0..N {
        x[i].pos = read();
        x[i].idx = i;
        y[i].pos = read();
        y[i].idx = i;
    }

    x.sort_by(
        |x1, x2| { x1.pos.cmp(&x2.pos) }
    );
    y.sort_by(
        |y1, y2| { y1.pos.cmp(&y2.pos) }
    );


    for i in 0..N-1 {
        edges[2*i].from = x[i].idx;
        edges[2*i].to = x[i+1].idx;
        edges[2*i].cost = x[i+1].pos - x[i].pos;
        edges[2*i+1].from = y[i].idx;
        edges[2*i+1].to = y[i+1].idx;
        edges[2*i+1].cost = y[i+1].pos - y[i].pos;
    }

    edges.sort_by(
        |e1, e2| { e1.cost.cmp(&e2.cost) }
    );

    let mut uf = UnionFind::new(N);
    let mut ans = 0;
    for edge in &edges {
        if !uf.are_same(edge.from, edge.to) {
            uf.unite(edge.from, edge.to);
            ans += edge.cost;
        }
    }

    println!("{}", ans);
}

#[allow(unused_imports)]
use itertools::Itertools;
#[allow(unused_imports)]
use itertools_num::ItertoolsNum;
#[allow(unused_imports)]
use std::cmp;
#[allow(unused_imports)]
use std::iter;
#[allow(unused_imports)]
use superslice::*;

fn run() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut xyi = sc
        .read_pairs::<i64>(n)
        .into_iter()
        .enumerate()
        .map(|(i, (x, y))| (x, y, i))
        .collect_vec();

    let mut edges = vec![];
    xyi.sort();
    for i in 0..(n - 1) {
        let dist = cmp::min(
            (xyi[i].0 - xyi[i + 1].0).abs(),
            (xyi[i].1 - xyi[i + 1].1).abs(),
        );
        edges.push((dist, xyi[i].2, xyi[i + 1].2));
    }
    xyi.sort_by_cached_key(|&(x, y, i)| y);
    for i in 0..(n - 1) {
        let dist = cmp::min(
            (xyi[i].0 - xyi[i + 1].0).abs(),
            (xyi[i].1 - xyi[i + 1].1).abs(),
        );
        edges.push((dist, xyi[i].2, xyi[i + 1].2));
    }

    edges.sort();
    let mut uf = UnionFind::new(n);
    let mut ans = 0;
    for (dist, i, j) in edges.into_iter() {
        if uf.find(i) != uf.find(j) {
            uf.unite(i, j);
            ans += dist;
        }
    }
    println!("{}", ans);
}

fn main() {
    std::thread::Builder::new()
        .name("run".into())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap();
}

pub struct UnionFind {
    parent: Vec<usize>,
    sizes: Vec<usize>,
    size: usize,
}

impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        UnionFind {
            parent: (0..n).map(|i| i).collect::<Vec<usize>>(),
            sizes: vec![1; n],
            size: n,
        }
    }

    pub fn find(&mut self, x: usize) -> usize {
        if x == self.parent[x] {
            x
        } else {
            let px = self.parent[x];
            self.parent[x] = self.find(px);
            self.parent[x]
        }
    }

    pub fn unite(&mut self, x: usize, y: usize) -> bool {
        let parent_x = self.find(x);
        let parent_y = self.find(y);
        if parent_x == parent_y {
            return false;
        }

        let (large, small) = if self.sizes[parent_x] < self.sizes[parent_y] {
            (parent_y, parent_x)
        } else {
            (parent_x, parent_y)
        };

        self.parent[small] = large;
        self.sizes[large] += self.sizes[small];
        self.sizes[small] = 0;
        self.size -= 1;
        true
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn read_vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn read_pairs<T: std::str::FromStr>(&mut self, n: usize) -> Vec<(T, T)> {
        (0..n).map(|_| (self.read(), self.read())).collect()
    }
    pub fn read_pairs_1_indexed(&mut self, n: usize) -> Vec<(usize, usize)> {
        (0..n)
            .map(|_| (self.read::<usize>() - 1, self.read::<usize>() - 1))
            .collect()
    }
    pub fn read_chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
    pub fn read_char_grid(&mut self, n: usize) -> Vec<Vec<char>> {
        (0..n).map(|_| self.read_chars()).collect()
    }
    pub fn read_matrix<T: std::str::FromStr>(&mut self, n: usize, m: usize) -> Vec<Vec<T>> {
        (0..n)
            .map(|_| (0..m).map(|_| self.read()).collect())
            .collect()
    }
}
